INSERT INTO `full_text` VALUES (442,'Delivery Tool Delivery Tool contains delivery builders.'),(485,'Order Tool Order Tool contains order builders.'),(914,'Obsoleted by Default Field Library for Dialogs'),(917,'Deprecated (Use Default Field Library instead)'),(920,'erp5_core_proxy_field_legacy This bt must be dropped as soon as cleanup is finished.\n\nThis bt contains for compatibility reasons all old not well named proxy field and proxy field libraries that were in erp5_core before. Like this we can do cleanup of erp5_core but we still give more time to people still using old fields to do the cleanup.'),(1419,'erp5_full_text_mroonga_catalog This business template contains SQL methods etc. to use a mroonga table as a fulltext storage.'),(1435,'Field Library for Categories'),(1442,'Obsoleted by Default Field Library for Reports'),(1499,'Default Field Library'),(1501,'document.erp5.OrderMovementGroup OrderMovementGroup ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\n\nclass OrderMovementGroup(MovementGroup):\n  \"\"\"\n  The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.\n\n  This movement group is used to group movements that come from the same\n  Order.\n  \"\"\"\n  meta_type = \'ERP5 Order Movement Group\'\n  portal_type = \'Order Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    return {\'causality_list\': [self._getOrderRelativeUrl(movement)]}\n\n  def test(self, movement, property_dict, **kw):\n    return set(property_dict[\'causality_list\']\n               ).issubset(movement.getCausalityList()), {}\n\n  def _getOrderRelativeUrl(self, movement):\n    try:\n      getRootAppliedRule = movement.getRootAppliedRule\n    except AttributeError:\n      return # This is a temp movement\n    # This is a simulation movement\n    getCausality = getRootAppliedRule().getCausality\n    return getCausality()'),(1502,'document.erp5.OrderBuilder OrderBuilder ##############################################################################\n# Copyright (c) 2010 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly advised to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\n# BACK: Temporary document so that legacy code can have its own set of classes\n#       for builders, and still distinguish order builders from others\n#       Once legacy simulation is dropped, \"Order Builder\" portal type should\n#       should be changed to use SimulatedDeliveryBuilder class.\nfrom erp5.component.document.GeneratedDeliveryBuilder import GeneratedDeliveryBuilder\n\nclass OrderBuilder(GeneratedDeliveryBuilder):\n  pass'),(1503,'document.erp5.OOoDocument OOoDocument # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2002-2006 Nexedi SARL and Contributors. All Rights Reserved.\n# Copyright (c) 2006-2007 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport contextlib\nimport re, zipfile\nfrom io import BytesIO\nimport six\nfrom warnings import warn\nfrom AccessControl import ClassSecurityInfo\nfrom OFS.Image import Pdata\nfrom zope.contenttype import guess_content_type\nfrom Products.CMFCore.utils import getToolByName\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Cache import CachingMethod\nfrom erp5.component.document.File import File\nfrom erp5.component.document.Document import Document, \\\n       VALID_IMAGE_FORMAT_LIST, VALID_TEXT_FORMAT_LIST, ConversionError, NotConvertedError\nfrom Products.ERP5Type.Utils import (guessEncodingFromText,\n                                     bytes2str,\n                                     fill_args_from_request,\n                                     str2bytes,\n                                     unicode2str)\n\n# Mixin Import\nfrom erp5.component.mixin.BaseConvertableFileMixin import BaseConvertableFileMixin\nfrom erp5.component.mixin.TextConvertableMixin import TextConvertableMixin\nfrom erp5.component.mixin.OOoDocumentExtensibleTraversableMixin import OOoDocumentExtensibleTraversableMixin\n\nEMBEDDED_FORMAT = \'_embedded\'\n\nfrom erp5.component.document.Document import DocumentConversionServerProxy\n# Backward compatibility only\nfrom erp5.component.document.Document import DOCUMENT_CONVERSION_SERVER_PROXY_TIMEOUT as OOO_SERVER_PROXY_TIMEOUT # pylint: disable=unused-import\nfrom erp5.component.document.Document import DOCUMENT_CONVERSION_SERVER_RETRY as OOO_SERVER_RETRY # pylint: disable=unused-import\nfrom erp5.component.document.Document import global_server_proxy_uri_failure_time # pylint: disable=unused-import\nfrom erp5.component.document.Document import enc, dec\nOOoServerProxy = DocumentConversionServerProxy\n\nclass OOoDocument(OOoDocumentExtensibleTraversableMixin, BaseConvertableFileMixin, File,\n                  TextConvertableMixin, Document):\n  \"\"\"\n    A file document able to convert OOo compatible files to\n    any OOo supported format, to capture metadata and to\n    update metadata in OOo documents.\n\n    This class can be used:\n\n    - to create an OOo document database with powerful indexing (r/o)\n      and metadata handling (r/w) features (ex. change title in ERP5 ->\n      title is changed in OOo document)\n\n    - to massively convert MS Office documents to OOo format\n\n    - to easily keep snapshots (in PDF and/or OOo format) of OOo documents\n      generated from OOo templates\n\n    This class may be used in the future:\n\n    - to create editable OOo templates (ex. by adding tags in WYSIWYG mode\n      and using tags to make document dynamic - ask kevin for more info)\n\n    - to automatically sign / encrypt OOo documents based on user\n\n    - to automatically sign / encrypt PDF generated from OOo documents based on user\n\n    This class should not be used:\n\n    - to store files in formats not supported by OOo\n\n    - to stored pure images (use Image for that)\n\n    - as a general file conversion system (use portal_transforms for that)\n\n    TODO:\n    - better permissions\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 OOo Document\'\n  portal_type = \'OOo Document\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.Reference\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Version\n                    , PropertySheet.Document\n                    , PropertySheet.Data\n                    , PropertySheet.ExternalDocument\n                    , PropertySheet.Url\n                    , PropertySheet.Periodicity\n                    , PropertySheet.SortIndex\n                    )\n\n  # regular expressions for stripping xml from ODF documents\n  rx_strip = re.compile(r\'<[^>]*?>\', re.DOTALL|re.MULTILINE)\n  rx_compr = re.compile(r\'\\s+\')\n\n  security.declareProtected(Permissions.View, \'index_html\')\n  @fill_args_from_request(\'display\', \'quality\', \'resolution\')\n  def index_html(self, REQUEST, *args, **kw):\n    \"\"\"Return the document data.\"\"\"\n    return Document.index_html(self, REQUEST, *args, **kw)\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'isSupportBaseDataConversion\')\n  def isSupportBaseDataConversion(self):\n    \"\"\"\n    OOoDocument is needed to conversion to base format.\n    \"\"\"\n    return True\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getTargetFormatItemList\')\n  def getTargetFormatItemList(self):\n    \"\"\"\n      Returns a list of acceptable formats for conversion\n      in the form of tuples (for listfield in ERP5Form)\n\n      NOTE: it is the responsability of the conversion server\n      to provide an extensive list of conversion formats.\n    \"\"\"\n    if not self.hasBaseData():\n      # if we have no date we can not format it\n      return []\n\n    def cached_getTargetFormatItemList(content_type):\n      from six.moves.xmlrpc_client import Fault\n      server_proxy = DocumentConversionServerProxy(self)\n      try:\n        allowed_target_item_list = server_proxy.getAllowedTargetItemList(\n                                                      content_type)\n        try:\n          response_code, response_dict, response_message = \\\n                                             allowed_target_item_list\n        except ValueError:\n          # Compatibility with older oood where getAllowedTargetItemList only\n          # returned response_dict\n          response_code, response_dict, response_message = \\\n                         200, dict(response_data=allowed_target_item_list), \'\'\n\n        if response_code == 200:\n          allowed = response_dict[\'response_data\']\n        else:\n          # This is very temporary code - XXX needs to be changed\n          # so that the system can retry\n          raise ConversionError(\"OOoDocument: can not get list of allowed acceptable\"\n                                \" formats for conversion (Code %s: %s)\" % (\n                                      response_code, response_message))\n\n      except Fault:\n        allowed = server_proxy.getAllowedTargets(content_type)\n        warn(\'Your oood version is too old, using old method \'\n            \'getAllowedTargets instead of getAllowedTargetList\',\n             DeprecationWarning)\n      finally:\n        server_proxy.close()\n      # tuple order is reversed to be compatible with ERP5 Form\n      return [(y, x) for x, y in allowed]\n\n    # Cache valid format list\n    cached_getTargetFormatItemList = CachingMethod(\n                                cached_getTargetFormatItemList,\n                                id=\"OOoDocument_getTargetFormatItemList\",\n                                cache_factory=\'erp5_ui_medium\')\n\n    return cached_getTargetFormatItemList(self.getBaseContentType())\n\n  def _getConversionFromProxyServer(self, format): #  pylint: disable=redefined-builtin\n    \"\"\"\n      Communicates with server to convert a file\n    \"\"\"\n    if not self.hasBaseData():\n      # XXX please pass a meaningful description of error as argument\n      raise NotConvertedError()\n    if format == \'text-content\':\n      # Extract text from the ODF file\n      cs = BytesIO()\n      cs.write(self.getBaseData())\n      z = zipfile.ZipFile(cs)\n      s = bytes2str(z.read(\'content.xml\'))\n      s = self.rx_strip.sub(\" \", s) # strip xml\n      s = self.rx_compr.sub(\" \", s) # compress multiple spaces\n      cs.close()\n      z.close()\n      return \'text/plain\', s\n    orig_format = self.getBaseContentType()\n    with contextlib.closing(DocumentConversionServerProxy(self)) as server_proxy:\n      generate_result = server_proxy.run_generate(self.getId(),\n                                       bytes2str(enc(bytes(self.getBaseData()))),\n                                       None,\n                                       format,\n                                       orig_format)\n    try:\n      _, response_dict, _ = generate_result\n    except ValueError:\n      # This is for backward compatibility with older oood version returning\n      # only response_dict\n      response_dict = generate_result\n\n    # XXX: handle possible OOOd server failure\n    return response_dict[\'mime\'], Pdata(dec(str2bytes(response_dict[\'data\'])))\n\n  # Conversion API\n  def _convert(self, format, frame=0, **kw): #  pylint: disable=redefined-builtin\n    \"\"\"Convert the document to the given format.\n\n    If a conversion is already stored for this format, it is returned\n    directly, otherwise the conversion is stored for the next time.\n\n    frame: Only used for image conversion\n\n    XXX Cascading conversions must be delegated to conversion server,\n    not by OOoDocument._convert (ie: convert to pdf, then convert to image, then resize)\n    *OR* as an optimisation we can read cached intermediate conversions\n    instead of compute them each times.\n      1- odt->pdf->png\n      2- odt->cached(pdf)->jpg\n    \"\"\"\n    #XXX if document is empty, stop to try to convert.\n    #XXX but I don\'t know what is a appropriate mime-type.(Yusei)\n    if not self.hasData():\n      return \'text/plain\', \'\'\n    # if no conversion asked (format empty)\n    # return raw data\n    if not format:\n      return self.getContentType(), self.getData()\n    # Check if we have already a base conversion\n    if not self.hasBaseData():\n      # XXX please pass a meaningful description of error as argument\n      raise NotConvertedError()\n    # Make sure we can support html and pdf by default\n    is_html = 0\n    requires_pdf_first = 0\n    original_format = format\n    allowed_format_list = self.getTargetFormatList()\n    if format == \'base-data\':\n      return self.getBaseContentType(), self.getBaseData()\n    if format == \'pdf\':\n      format_list = [x for x in allowed_format_list\n                                          if x.endswith(\'pdf\')]\n      format = format_list[0]\n    elif format in VALID_IMAGE_FORMAT_LIST:\n      format_list = [x for x in allowed_format_list\n                                          if x.endswith(format)]\n      if len(format_list):\n        format = format_list[0]\n      else:\n        # We must fist make a PDF which will be used to produce an image out of it\n        requires_pdf_first = 1\n        format_list = [x for x in allowed_format_list\n                                          if x.endswith(\'pdf\')]\n        format = format_list[0]\n    elif format == \'html\':\n      format_list = [x for x in allowed_format_list\n                              if x.startswith(\'html\') or x.endswith(\'html\')]\n      format = format_list[0]\n      is_html = 1\n    elif format in (\'txt\', \'text\', \'text-content\'):\n      # if possible, we try to get utf8 text. (\'enc.txt\' will encode to utf8)\n      if \'enc.txt\' in allowed_format_list:\n        format = \'enc.txt\'\n      elif format not in allowed_format_list:\n        #Text conversion is not supported by oood, do it in other way\n        if not self.hasConversion(format=original_format):\n          #Do real conversion for text\n          mime, data = self._getConversionFromProxyServer(format=\'text-content\')\n          self.setConversion(data, mime, format=original_format)\n          return mime, data\n        return self.getConversion(format=original_format)\n    # Raise an error if the format is not supported\n    if not self.isTargetFormatAllowed(format):\n      raise ConversionError(\"OOoDocument: target format %s is not supported\" % format)\n    has_format = self.hasConversion(format=original_format, **kw)\n    if not has_format:\n      # Do real conversion\n      mime, data = self._getConversionFromProxyServer(format)\n      if is_html:\n        # Extra processing required since\n        # we receive a zip file\n        cs = BytesIO()\n        cs.write(bytes(data)) # Cast explicitly to bytes for possible Pdata\n        z = zipfile.ZipFile(cs) # A disk file would be more RAM efficient\n        for f in z.infolist():\n          fn = f.filename\n          if fn.endswith(\'html\'):\n            if self.getPortalType() == \'Presentation\'\\\n                  and not (fn.find(\'impr\') >= 0):\n              continue\n            data = z.read(fn)\n            break\n        mime = \'text/html\'\n        self._populateConversionCacheWithHTML(zip_file=z) # Maybe some parts should be asynchronous for\n                                         # better usability\n        z.close()\n        cs.close()\n      if original_format not in VALID_IMAGE_FORMAT_LIST \\\n        and not requires_pdf_first:\n        self.setConversion(data, mime, format=original_format, **kw)\n      else:\n        # create temporary image and use it to resize accordingly\n        temp_image = self.portal_contributions.newContent(\n                                       portal_type=\'Image\',\n                                       file=BytesIO(),\n                                       filename=self.getId(),\n                                       temp_object=1)\n        temp_image._setData(data)\n        # we care for first page only but as well for image quality\n        mime, data = temp_image.convert(original_format, frame=frame, **kw)\n        # store conversion\n        self.setConversion(data, mime, format=original_format, **kw)\n\n    mime, data = self.getConversion(format=original_format, **kw)\n    if format in VALID_TEXT_FORMAT_LIST:\n      # Libreoffice conversions on cloudooo usually have a BOM, we are using guessEncodingFromText\n      # here mostly as a convenient way to decode with the encoding from BOM\n      data = data.decode(guessEncodingFromText(data) or \'ascii\')\n      if six.PY2:\n        data = unicode2str(data)\n    return mime, data\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'_populateConversionCacheWithHTML\')\n  def _populateConversionCacheWithHTML(self, zip_file=None):\n    \"\"\"\n    Extract content from the ODF zip file and populate the document.\n    Optional parameter zip_file prevents from converting content twice.\n    \"\"\"\n    if zip_file is None:\n      format_list = [x for x in self.getTargetFormatList()\n                                if x.startswith(\'html\') or x.endswith(\'html\')]\n      mime, data = self._getConversionFromProxyServer(format_list[0])\n      archive_file = BytesIO()\n      archive_file.write(data)\n      zip_file = zipfile.ZipFile(archive_file)\n      must_close = 1\n    else:\n      must_close = 0\n    for f in zip_file.infolist():\n      filename = f.filename\n      document = self.get(filename, None)\n      if document is not None:\n        self.manage_delObjects([filename]) # For compatibility with old implementation\n      if filename.endswith(\'html\'):\n        mime = \'text/html\'\n        # call portal_transforms to strip HTML in safe mode\n        portal = self.getPortalObject()\n        transform_tool = getToolByName(portal, \'portal_transforms\')\n        data = transform_tool.convertToData(\'text/x-html-safe\',\n                                            zip_file.read(filename),\n                                            object=self, context=self,\n                                            mimetype=mime)\n      else:\n        mime = guess_content_type(filename)[0]\n        data = Pdata(zip_file.read(filename))\n      self.setConversion(data, mime=mime, format=EMBEDDED_FORMAT, filename=filename)\n    if must_close:\n      zip_file.close()\n      archive_file.close()\n\n  security.declarePrivate(\'_convertToBaseFormat\')\n  def _convertToBaseFormat(self):\n    \"\"\"\n      Converts the original document into ODF\n      by invoking the conversion server. Store the result\n      on the object. Update metadata information.\n    \"\"\"\n    with contextlib.closing(DocumentConversionServerProxy(self)) as server_proxy:\n      response_code, response_dict, response_message = server_proxy.run_convert(\n                                      self.getFilename() or self.getId(),\n                                      bytes2str(enc(bytes(self.getData()))),\n                                      None,\n                                      None,\n                                      self.getContentType())\n    if response_code == 200:\n      # sucessfully converted document\n      self._setBaseData(dec(str2bytes(response_dict[\'data\'])))\n      metadata = response_dict[\'meta\']\n      self._base_metadata = metadata\n      if metadata.get(\'MIMEType\', None) is not None:\n        self._setBaseContentType(metadata[\'MIMEType\'])\n    else:\n      # Explicitly raise the exception!\n      raise ConversionError(\n                \"OOoDocument: Error converting document to base format. (Code %s: %s)\"\n                                       % (response_code, response_message))\n\n  def _getContentInformation(self):\n    \"\"\"\n      Returns the metadata extracted by the conversion\n      server.\n    \"\"\"\n    return getattr(self, \'_base_metadata\', {})\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'updateBaseMetadata\')\n  def updateBaseMetadata(self, **kw):\n    \"\"\"\n      Updates metadata information in the converted OOo document\n      based on the values provided by the user. This is implemented\n      through the invocation of the conversion server.\n    \"\"\"\n    if not self.hasBaseData():\n      # XXX please pass a meaningful description of error as argument\n      raise NotConvertedError()\n\n    with contextlib.closing(DocumentConversionServerProxy(self)) as server_proxy:\n      response_code, response_dict, response_message = \\\n          server_proxy.run_setmetadata(self.getId(),\n                                       bytes2str(enc(bytes(self.getBaseData()))),\n                                       kw)\n    if response_code == 200:\n      # successful meta data extraction\n      self._setBaseData(dec(str2bytes(response_dict[\'data\'])))\n      self.updateFileMetadata() # record in workflow history # XXX must put appropriate comments.\n    else:\n      # Explicitly raise the exception!\n      raise ConversionError(\"OOoDocument: error getting document metadata (Code %s: %s)\"\n                        % (response_code, response_message))'),(1504,'document.erp5.NestedLineMovementGroup NestedLineMovementGroup ##############################################################################\n#\n# Copyright (c) 2009 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\n\nclass NestedLineMovementGroup(MovementGroup):\n  \"\"\"\n  This MovementGroup is only used to multiple lines control.\n  No more effect.\n  \"\"\"\n\n  meta_type = \'ERP5 Nested Line Movement Group\'\n  portal_type = \'Nested Line Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    return {}\n\n  def test(self, document, property_dict, property_list=None, **kw):\n    if property_list not in (None, []):\n      target_property_list = [x for x in self.getTestedPropertyList() \\\n                              if x in property_list]\n    else:\n      target_property_list = self.getTestedPropertyList()\n    for prop in target_property_list:\n      if property_dict[prop] != document.getProperty(prop, None):\n        return False, property_dict\n    return True, property_dict\n\n  def isBranch(self):\n    return True'),(1505,'document.erp5.MovementGroup MovementGroup # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Utils import ensure_list\nfrom erp5.component.interface.IMovementGroup import IMovementGroup\nimport zope.interface\n\n@zope.interface.implementer( IMovementGroup,)\nclass MovementGroup(XMLObject):\n  \"\"\"\n  The purpose of MovementGroup is to define how movements\n  are grouped.\n\n  REACTORING NEEDED: XXX-JPS\n  - the initial docstring was stating that MovementGroup is\n    used to know how values are updated from simulation movements\n    (to delivery lines). This was wrong because one delivery line\n    can be built out of multiple simulation movements through\n    differen builders using different movement groups\n\n  - moreover, we need to have something to represent at which\n    level movement properties should be stored (ex. in Task\n    Report). PropertyGroup could be the name.\n\n  - it is true that during divergence resolution, it will be useful\n    to check on PropertyGroup at which level a property can be\n    set (ex. cell, line, group of lines, delivery) in order to\n    show the appropriate user interface choice to the users.\n    This will be achieved by making a union of all PropertyGroup\n    of all business path of all simulation movements involved\n    in delivery movements to resolve\n  \"\"\"\n  meta_type = \'ERP5 Movement Group\'\n  portal_type = \'Movement Group\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = (\n    PropertySheet.Base,\n    PropertySheet.SimpleItem,\n    PropertySheet.CategoryCore,\n    PropertySheet.MovementGroup,\n    PropertySheet.SortIndex,\n    )\n\n  def _getPropertyDict(self, movement, **kw):\n    # This method should be defined in sub classes.\n    raise NotImplementedError\n\n  def test(self, document, property_dict, **kw):\n    # This method should be defined in sub classes.\n    raise NotImplementedError\n\n  def _separate(self, movement_list, merge_delivery=False, **kw):\n    # By default, we separate movements by _getPropertyDict() values.\n    # You can override this method in each MovementGroup class.\n    tmp_dict = {}\n    collect_order_group_id = self.getCollectOrderGroupId()\n    for movement in movement_list:\n      # We are in the case of merging of deliveries, thus if the movement\n      # is configured to not split, just take properties of the first movement\n      if merge_delivery and collect_order_group_id == \"delivery\":\n        property_dict = {}\n      else:\n        property_dict = self._getPropertyDict(movement, **kw)\n      # XXX it can be wrong. we need a good way to get hash value, or\n      # we should compare for all pairs.\n      key = repr(property_dict)\n      if key in tmp_dict:\n        tmp_dict[key][0].append(movement)\n      else:\n        tmp_dict[key] = [[movement], property_dict]\n    return ensure_list(tmp_dict.values())\n\n  def separate(self, movement_list, **kw):\n    # We sort group of simulation movements by their IDs.\n    # DO NOT OVERRIDE THIS METHOD. Override _separate() instead.\n    return sorted([[sorted(x[0], key=lambda x: x.getId()), x[1]] \\\n                   for x in self._separate(movement_list, **kw)],\n                  key=lambda x: x[0][0].getId())\n\n  def isBranch(self):\n    # self is taken as branch point by the builder if returned value is True.\n    return False'),(1506,'document.erp5.MonthlyRangeMovementGroup MonthlyRangeMovementGroup ##############################################################################\n#\n# Copyright (c) 2009 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA\n# 02110-1301, USA.\n#\n##############################################################################\n\nfrom collections import OrderedDict\nfrom erp5.component.document.MovementGroup import MovementGroup\nfrom DateTime import DateTime\nfrom erp5.component.module.DateUtils import atTheEndOfPeriod\n\n\nclass MonthlyRangeMovementGroup(MovementGroup):\n  \"\"\"\n  The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.\n\n  This movement group is used to collect movements that have datetime\n  which is in the same month.\n  \"\"\"\n  meta_type = \'ERP5 Monthly Range Movement Group\'\n  portal_type = \'Monthly Range Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    \"\"\"Gather start_date and stop_date, converge them to the end of month.\n    \"\"\"\n    property_dict = OrderedDict()\n    for property_name in self.getTestedPropertyList() or (\'start_date\', \'stop_date\'):\n      date = movement.getProperty(property_name, None)\n      if date is not None:\n        # wrap atTheEndOfPeriod value with DateTime(value..strftime(\'%Y/%m/%d\')) so that\n        # it returns a value with an appropriate time offset at that date.\n        end_of_month = DateTime((atTheEndOfPeriod(date, \'month\')-0.5).strftime(\'%Y/%m/%d\'))\n        property_dict[property_name] = end_of_month\n    return property_dict\n\n  def test(self, document, property_dict, property_list=None, **kw):\n    for property_name in self.getTestedPropertyList() or (\'start_date\', \'stop_date\'):\n      date = property_dict.get(property_name, None)\n      if date is None:\n        return False, property_dict\n      target_date = document.getProperty(property_name, None)\n      if target_date is None:\n        return False, property_dict\n      if date.year() != target_date.year() or \\\n        date.month() != target_date.month():\n        return False, property_dict\n    return True, property_dict'),(1507,'document.erp5.MappedProperty MappedProperty ##############################################################################\n#\n# Copyright (c) 2010 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\n\nclass MappedProperty(XMLObject):\n  \"\"\"\n  Mapped Property object describes how properties or categories are\n  mapped, eg. use source as destination, use destination as source, use\n  quantity as -quantity, etc.\n  \"\"\"\n  meta_type = \'ERP5 Mapped Property\'\n  portal_type = \'Mapped Property\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = (PropertySheet.Base,\n                     PropertySheet.SimpleItem,\n                     PropertySheet.CategoryCore,\n                     PropertySheet.MappedProperty)\n\n  # XXX do we need to protect this method?\n  def getMappingDict(self, reverse=False):\n    # Use volatile attributes for caching.\n    try:\n      if reverse:\n        return self._v_reverse_mapping_dict\n      else:\n        return self._v_mapping_dict\n    except AttributeError:\n      mapping_dict = {}\n      for line in self.getMappingPropertyList():\n        f, t = [x.strip() for x in line.split(\'|\', 1)]\n        if reverse:\n          if t[:1] == \'-\':\n            f, t = t[1:], \'-\' + f\n          else:\n            f, t = t, f\n          mapping_dict[f] = t\n        else:\n          mapping_dict[f] = t\n      if reverse:\n        self._v_reverse_mapping_dict = mapping_dict\n      else:\n        self._v_mapping_dict = mapping_dict\n      return mapping_dict\n\n  # XXX do we need to protect this method?\n  def getMappedPropertyId(self, property, reverse=False): #  pylint: disable=redefined-builtin\n    return self.getMappingDict(reverse=reverse).get(property, property)\n\n  # Security should be handled by the target document not by the mapped\n  # property document.\n  security.declarePublic(\'getMappedProperty\')\n  def getMappedProperty(self, document, property): #  pylint: disable=redefined-builtin\n    if property.endswith(\'_list\'):\n      property = property[:-5]\n      getProperty = document.getPropertyList\n    else:\n      getProperty = document.getProperty\n    mapping_dict = self.getMappingDict()\n    mapped_property = mapping_dict.get(property, property)\n    if mapped_property.startswith(\'-\'):\n      return -1 * getProperty(mapped_property[1:])\n    else:\n      return getProperty(mapped_property)\n\n  # Security should be handled by the target document not by the mapped\n  # property document.\n  security.declarePublic(\'setMappedProperty\')\n  def setMappedProperty(self, document, property, value): #  pylint: disable=redefined-builtin\n    if property.endswith(\'_list\'):\n      property = property[:-5]\n      setProperty = document.setPropertyList\n    else:\n      setProperty = document.setProperty\n    mapping_dict = self.getMappingDict(reverse=True)\n    mapped_property = mapping_dict.get(property, property)\n    if mapped_property.startswith(\'-\'):\n      return setProperty(mapped_property[1:], -1 * value)\n    else:\n      return setProperty(mapped_property, value)'),(1508,'document.erp5.Login Login ##############################################################################\n#\n# Copyright (c) 2015 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom erp5.component.mixin.EncryptedPasswordMixin import EncryptedPasswordMixin\nfrom erp5.component.mixin.LoginAccountProviderMixin import LoginAccountProviderMixin\nfrom Products.ERP5Type import Permissions, PropertySheet, interfaces\nfrom Products.ERP5Type.XMLObject import XMLObject\n\n\n@zope.interface.implementer(interfaces.INode)\nclass Login(EncryptedPasswordMixin, XMLObject, LoginAccountProviderMixin):\n  \"\"\"Login\n  \"\"\"\n  meta_type = \'ERP5 Login\'\n  portal_type = \'Login\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference\n                    , PropertySheet.Login\n                    , PropertySheet.LoginConstraint\n                    )'),(1509,'document.erp5.InvoiceMovementGroup InvoiceMovementGroup ##############################################################################\n#\n# Copyright (c) 2010 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\n\nclass InvoiceMovementGroup(MovementGroup):\n  \"\"\"\n  This movement group is used to collect movements related to the same\n  invoice. This movement group should be used in delivery level.\n  \"\"\"\n  meta_type = \'ERP5 Invoice Movement Group\'\n  portal_type = \'Invoice Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    return dict(_invoice_uid=self._getInvoiceUid(movement))\n\n  def test(self, document, property_dict, property_list=None, **kw):\n    if property_dict[\'_invoice_uid\'] != document.getUid():\n      return False, {}\n    else:\n      return True, {}\n\n  def _getInvoiceUid(self, simulation_movement):\n    parent_rule = simulation_movement.getParentValue()\n    portal = self.getPortalObject()\n    invoice_movement_types = portal.getPortalInvoiceMovementTypeList()\n    while not parent_rule.isRootAppliedRule():\n      parent_simulation_movement = parent_rule.getParentValue()\n      grand_parent_rule = parent_simulation_movement.getParentValue()\n      parent_delivery = parent_simulation_movement.getDeliveryValue()\n      if parent_delivery is not None and \\\n             parent_delivery.getPortalType() in invoice_movement_types:\n        return parent_delivery.getExplanationValue().getUid()\n      parent_rule = grand_parent_rule\n    return None'),(1510,'document.erp5.Image Image # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# Based on Photo by Ron Bickers\n# Copyright (c) 2001 Logic Etc, Inc.  All rights reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport os\nimport subprocess\nfrom io import BytesIO\nfrom AccessControl import ClassSecurityInfo\nfrom Acquisition import aq_base\n\nimport Products.ERP5\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Utils import bytes2str, fill_args_from_request\nfrom erp5.component.document.File import File\nfrom erp5.component.document.Document import Document, ConversionError,\\\n                     VALID_TEXT_FORMAT_LIST, VALID_TRANSPARENT_IMAGE_FORMAT_LIST,\\\n                     DEFAULT_DISPLAY_ID_LIST, _MARKER\n\nfrom OFS.Image import Image as OFSImage\nfrom OFS.Image import getImageInfo\nimport PIL.Image\nfrom zLOG import LOG, WARNING\n\nfrom erp5.component.module.ImageUtil import transformUrlToDataURI\n\n# import mixin\nfrom erp5.component.mixin.TextConvertableMixin import TextConvertableMixin\n\ndef getDefaultImageQuality(portal, format=None):  # pylint: disable=redefined-builtin\n  preference_tool = portal.portal_preferences\n  return preference_tool.getPreferredImageQuality()\n\nclass Image(TextConvertableMixin, File, OFSImage):\n  \"\"\"\n    An Image is a File which contains image data. It supports\n    various conversions of format, size, resolution through\n    imagemagick. imagemagick was preferred due to its ability\n    to support PDF files (incl. Adobe Illustrator) which make\n    it very useful in the context of a graphic design shop.\n\n    Image inherits from XMLObject and can be synchronized\n    accross multiple sites.\n\n    Subcontent: Image can only contain role information.\n\n    TODO:\n    * extend Image to support more image file formats,\n      including Xara Xtreme (http://www.xaraxtreme.org/)\n    * include upgrade methods so that previous images\n      in ERP5 get upgraded automatically to new class\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Image\'\n  portal_type = \'Image\'\n\n  # Default attribute values\n  width = 0\n  height = 0\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Version\n                    , PropertySheet.Reference\n                    , PropertySheet.Document\n                    , PropertySheet.Data\n                    , PropertySheet.ExternalDocument\n                    , PropertySheet.Url\n                    , PropertySheet.Periodicity\n                    )\n\n  #\n  # Original photo attributes\n  #\n\n  def _update_image_info(self):\n    \"\"\"\n      This method tries to determine the content type of an image and\n      its geometry.\n    \"\"\"\n    self.size = len(self.data)\n    content_type, width, height = getImageInfo(self.data)\n    if not content_type:\n      try:\n        image = PIL.Image.open(BytesIO(bytes(self.data)))\n      except IOError:\n        width = height = -1\n        content_type = \'application/unknown\'\n      else:\n        width, height = image.size\n        content_type = image.get_format_mimetype()\n        # normalize the mimetype using the registry\n        mimetype_list = self.getPortalObject().mimetypes_registry.lookup(content_type)\n        if mimetype_list:\n          content_type = mimetype_list[0].normalized()\n    self.height = height\n    self.width = width\n    self._setContentType(content_type)\n\n  def _upgradeImage(self):\n    \"\"\"\n      This method upgrades internal data structures is required\n    \"\"\"\n    # Quick hack to maintain just enough compatibility for existing sites\n    # Convert to new BTreeFolder2 based class\n    if getattr(aq_base(self), \'_count\', None) is None:\n      self._initBTrees()\n\n    # Make sure old Image objects can still be accessed\n    if not hasattr(aq_base(self), \'data\') and hasattr(self, \'_original\'):\n      self.data = self._original.data\n      self.height = self._original.height\n      self.width = self._original.width\n\n    # Make sure old Image objects can still be accessed\n    if not hasattr(aq_base(self), \'data\') and hasattr(aq_base(self), \'_data\'):\n      self.data = self._data\n\n    # Make sure size is defined\n    size = len(self.data)\n    if getattr(aq_base(self), \'size\', None) != size:\n      self.size = size\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getWidth\')\n  def getWidth(self):\n    \"\"\"\n      Tries to get the width from the image data.\n    \"\"\"\n    self._upgradeImage()\n    if self.hasData() and not self.width:\n      self._update_image_info()\n    return self.width\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getHeight\')\n  def getHeight(self):\n    \"\"\"\n      Tries to get the height from the image data.\n    \"\"\"\n    self._upgradeImage()\n    if self.hasData() and not self.height:\n      self._update_image_info()\n    return self.height\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getContentType\')\n  def getContentType(  # pylint: disable=arguments-differ\n      self,\n      default=_MARKER,\n    ):\n    \"\"\"Original photo content_type.\"\"\"\n    self._upgradeImage()\n    if self.hasData() and not self.hasContentType():\n      self._update_image_info()\n    if default is _MARKER:\n      return self._baseGetContentType()\n    else:\n      return self._baseGetContentType(default)\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'displayIds\')\n  def displayIds(self, exclude=(\'thumbnail\',)):\n    \"\"\"Return list of display Ids.\"\"\"\n    id_list = list(DEFAULT_DISPLAY_ID_LIST)\n    # Exclude specified displays\n    if exclude:\n      for id_ in exclude:\n        if id_ in id_list:\n          id_list.remove(id_)\n    # Sort by desired photo surface area\n    def getSurfaceArea(img):\n      x, y = self.getSizeFromImageDisplay(img)\n      return x * y\n    id_list.sort(key=getSurfaceArea)\n    return id_list\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'displayLinks\')\n  def displayLinks(self, exclude=(\'thumbnail\',)):\n    \"\"\"Return list of HTML <a> tags for displays.\"\"\"\n    links = []\n    for display in self.displayIds(exclude):\n      links.append(\'<a href=\"%s?display=%s\">%s</a>\' % (self.REQUEST[\'URL\'], display, display))\n    return links\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'displayMap\')\n  def displayMap(\n      self,\n      exclude=None,\n      format=None,  # pylint: disable=redefined-builtin\n      quality=_MARKER,\n      resolution=None,\n  ):\n    \"\"\"Return list of displays with size info.\"\"\"\n    displays = []\n    if quality is _MARKER:\n      quality = self.getDefaultImageQuality(format)\n    for id_ in self.displayIds(exclude):\n      if self._isGenerated(id_, format=format, quality=quality,\\\n                                                        resolution=resolution):\n        photo_width = self._photos[(id_,format)].width\n        photo_height = self._photos[(id_,format)].height\n        bytes_ = self._photos[(id_,format)]._size()\n        age = self._photos[(id_,format)]._age()\n      else:\n        (photo_width, photo_height, bytes_, age) = (None, None, None, None)\n      image_size = self.getSizeFromImageDisplay(id_)\n      displays.append({\'id\': id_,\n                        \'width\': image_size[0],\n                        \'height\': image_size[1],\n                        \'photo_width\': photo_width,\n                        \'photo_height\': photo_height,\n                        \'bytes\': bytes_,\n                        \'age\': age\n                        })\n    return displays\n\n\n  security.declarePrivate(\'_convertToText\')\n  def _convertToText(self, format):  # pylint: disable=redefined-builtin\n    \"\"\"\n    Convert the image to text with portaltransforms\n    \"\"\"\n    portal = self.getPortalObject()\n    mime_type = portal.mimetypes_registry.lookupExtension(\'name.%s\' % format)\n    mime_type = str(mime_type)\n    src_mimetype = self.getContentType()\n    content = self.getData()\n    portal_transforms = portal.portal_transforms\n    result = portal_transforms.convertToData(mime_type, content,\n                                             object=self, context=self,\n                                             filename=self.getFilename(),\n                                             mimetype=src_mimetype)\n    if result is None:\n      # portal_transforms fails to convert.\n      LOG(\'TextDocument.convert\', WARNING,\n          \'portal_transforms failed to convert to %s: %r\' % (mime_type, self))\n      result = \'\'\n    return mime_type, result\n\n  # Conversion API\n  def _convert(self, format, **kw):  # pylint: disable=redefined-builtin\n    \"\"\"\n    Implementation of conversion for Image files\n    \"\"\"\n    if format == \'svg\' and self.getContentType()==\'image/svg+xml\':\n      # SVG format is a textual data which can be returned as it is\n      # so client (browser) can draw an image out of it\n      return self.getContentType(), self.getData()\n\n    if format in VALID_TEXT_FORMAT_LIST:\n      try:\n        mime, data = self.getConversion(format=format)\n        return mime, bytes2str(data)\n      except KeyError:\n        mime_type, data = self._convertToText(format)\n        data = aq_base(data)\n        self.setConversion(data, mime=mime_type, format=format)\n        return mime_type, data\n    if not (format or kw):\n      # User asked for original content\n      return self.getContentType(), self.getData()\n    image_size = self.getSizeFromImageDisplay(kw.get(\'display\'))\n    # store all keys usefull to convert or resize an image\n    # \'display\' parameter can be discarded\n    quality = kw.get(\'quality\', _MARKER)\n    if quality is _MARKER:\n      quality = self.getDefaultImageQuality(format)\n    kw[\'format\'] = format\n    kw[\'quality\'] = quality\n    try:\n      mime, image_data = self.getConversion(**kw)\n    except KeyError:\n      # we need to convert string representation (i.e. display=small) to a\n      # pixel (number of it = 128x128)\n      kw[\'image_size\'] = image_size\n      display = kw.pop(\'display\', None)\n      crop = kw.pop(\'crop\', None)\n      mime, image_data = self._getContentTypeAndImageData(\n          format=format,\n          quality=quality,\n          resolution=kw.get(\'resolution\'),\n          frame=kw.get(\'frame\'),\n          image_size=image_size,\n          crop=crop,\n      )\n      # as image will always be requested through a display not by passing exact\n      # pixels we need to restore this way in cache\n      if display is not None:\n        # only set if we have a real value\n        kw[\'display\'] = display\n      if crop:\n        kw[\'crop\'] = crop\n      image_size = kw.pop(\'image_size\', None)\n      self.setConversion(image_data, mime, **kw)\n    return mime, image_data\n\n  # Display\n  security.declareProtected(Permissions.View, \'index_html\')\n  @fill_args_from_request(\'display\', \'quality\', \'resolution\', \'frame\', \'crop\')\n  def index_html(self, REQUEST, *args, **kw):\n    \"\"\"Return the image data.\"\"\"\n    self._upgradeImage()\n    return Document.index_html(self, REQUEST, *args, **kw)\n\n  #\n  # Photo processing\n  #\n\n  def _resize(\n      self,\n      quality,\n      width,\n      height,\n      format,  # pylint: disable=redefined-builtin\n      resolution,\n      frame,\n      crop=False,\n  ):\n    \"\"\"Resize and resample photo.\"\"\"\n    # https://github.com/saucecontrol/Compact-ICC-Profiles\n    icc_profile = os.path.join(os.path.dirname(Products.ERP5.__file__),\n                               \'misc\', \'sRGB-v2-magic.icc\')\n    parameter_list = [\'convert\', \'-colorspace\', \'sRGB\', \'-depth\', \'8\',\n                      \'-profile\', icc_profile]\n    if crop :\n      parameter_list += \'-thumbnail\', \'%sx%s^\' % (width, height),\\\n                        \'-gravity\', \'center\',\\\n                        \'-extent\',\'%sx%s\' % (width, height)\n    else:\n      parameter_list += \'-geometry\', \'%sx%s\' % (width, height)\n    parameter_list += \'-quality\', str(quality)\n    if format not in VALID_TRANSPARENT_IMAGE_FORMAT_LIST:\n      # ImageMagick way to remove transparent that works with multiple\n      # images. http://www.imagemagick.org/Usage/masking/#remove\n      parameter_list += \'-bordercolor\', \'white\', \'-border\', \'0\'\n    if resolution:\n      parameter_list += \'-density\', \'%sx%s\' % (resolution, resolution)\n    if frame is not None:\n      parameter_list.append(\'-[%s]\' % frame)\n    else:\n      parameter_list.append(\'-\')\n\n    if format:\n      # Is there a way to make \'convert\' fail if the format is unknown,\n      # instead of treating this whole parameter as an output file path?\n      # As a workaround, we run \'convert\' in a non-writeable directory.\n      if \'/\' in format or os.access(\'/\', os.W_OK):\n        raise ConversionError\n      parameter_list.append(\'%s:-\' % format)\n    else:\n      parameter_list.append(\'-\')\n\n    data = bytes(self.getData())\n    if self.getContentType() == \"image/svg+xml\":\n      data = transformUrlToDataURI(data)\n\n    env = os.environ.copy()\n    env.update({\'LC_NUMERIC\':\'C\'})\n    process = subprocess.Popen(parameter_list,\n                               env=env,\n                               stdin=subprocess.PIPE,\n                               stdout=subprocess.PIPE,\n                               stderr=subprocess.PIPE,\n                               cwd=\'/\',\n                               close_fds=True)\n    try:\n      # XXX: The only portable way is to pass what stdin.write can accept,\n      #      which is a string for PIPE.\n      image, err = process.communicate(data)\n    finally:\n      del process\n    if image:\n      return BytesIO(image)\n    raise ConversionError(\'Image conversion failed (%s).\' % err)\n\n  def _getContentTypeAndImageData(\n      self,\n      format,  # pylint: disable=redefined-builtin\n      quality,\n      resolution,\n      frame,\n      image_size,\n      crop,\n  ):\n    \"\"\"Return the content type and the image data as str or PData.\"\"\"\n    if crop:\n      width, height = image_size\n    else:\n      width, height = self._getAspectRatioSize(*image_size)\n    if ((width, height) == image_size or (width, height) == (0, 0))\\\n       and quality == self.getDefaultImageQuality(format) and resolution is None and frame is None\\\n       and not format:\n      # No resizing, no conversion, return raw image\n      return self.getContentType(), self.getData()\n    image_file = self._resize(quality, width, height, format, resolution, frame, crop)\n    image = OFSImage(\'\', \'\', image_file)\n    content_type = image.content_type\n    if content_type == \'application/octet-stream\':\n      # If OFS Image could not guess content type, try with PIL\n      image_file.seek(0)\n      try:\n        pil_image = PIL.Image.open(image_file)\n      except IOError:\n        pass\n      else:\n        content_type = pil_image.get_format_mimetype()\n        mimetype_list = self.getPortalObject().mimetypes_registry.lookup(content_type)\n        if mimetype_list:\n          content_type = mimetype_list[0].normalized()\n    return content_type, image.data\n\n  def _getAspectRatioSize(self, width, height):\n    \"\"\"Return proportional dimensions within desired size.\"\"\"\n    img_width, img_height = (self.getWidth(), self.getHeight())\n    if img_width == 0:\n      return (0, 0)\n\n    #XXX This is a temporary dirty fix!!!\n    width = int(width)\n    height = int(height)\n    img_width = int(img_width)\n    img_height = int(img_height)\n\n    if height > img_height * width / img_width:\n      height = img_height * width / img_width\n    else:\n      width =  img_width * height / img_height\n    return (width, height)\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getSizeFromImageDisplay\')\n  def getSizeFromImageDisplay(self, image_display):\n    \"\"\"Return the size for this image display,\n       or dimension of this image.\n    \"\"\"\n    if image_display in DEFAULT_DISPLAY_ID_LIST:\n      preference_tool = self.getPortalObject().portal_preferences\n      height_preference = \'preferred_%s_image_height\' % (image_display,)\n      width_preference = \'preferred_%s_image_width\' % (image_display,)\n      height = preference_tool.getPreference(height_preference)\n      width = preference_tool.getPreference(width_preference)\n      return (width, height)\n    return self.getWidth(), self.getHeight()\n\n  def _setFile(self, *args, **kw):\n    \"\"\"set the file content and reset image information.\n    \"\"\"\n    File._setFile(self, *args, **kw)\n    self._update_image_info()\n\n  def PUT(self, REQUEST, RESPONSE):\n    \"\"\"set the file content by HTTP/FTP and reset image information.\n    \"\"\"\n    File.PUT(self, REQUEST, RESPONSE)\n    self._update_image_info()\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getDefaultImageQuality\')\n  def getDefaultImageQuality(self, format=None):  # pylint: disable=redefined-builtin\n    \"\"\"\n    Get default image quality for a format.\n    \"\"\"\n    return getDefaultImageQuality(self.getPortalObject(), format)'),(1511,'document.erp5.GeographicalPoint GeographicalPoint # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2015 Nexedi SA and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.Url import Url\n\nclass GeographicalPoint(Url):\n  \"\"\"\n    A GeographicalPoint represent a point on the surface of the Earth\n    which is address by its coordinates.\n  \"\"\"\n\n  meta_type = \'ERP5 Geographical Location\'\n  portal_type = \'Geographical Location\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.CategoryCore\n                    , PropertySheet.SortIndex\n                    , PropertySheet.Url\n                    , PropertySheet.GeographicalPoint\n                    )\n\n  def asURL(self):\n    \"\"\"\n      Returns  the URL of coordinates.\n    \"\"\"\n    return self.asText()\n\n  def asText(self):\n    \"\"\"\n      Returns the coordinates as text.\n    \"\"\"\n    return \'%s %s\' %(self.getLongitude(), self.getLatitude())'),(1512,'document.erp5.GeographicalArea GeographicalArea # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2015 Nexedi SA and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.Url import Url\nfrom Products.ERP5.Document.Node import Node\n\n\nclass GeographicalArea(Node, Url):\n  \"\"\"\n  A Geographical Area represent an area of the Earth which is address by its Geographical Points.\n  \"\"\"\n\n  meta_type = \'ERP5 Geographical Area\'\n  portal_type = \'Geographical Area\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.CategoryCore\n                    , PropertySheet.SortIndex\n                    , PropertySheet.Url\n                    , PropertySheet.GeographicalPoint\n                    )\n\n  def asURL(self):\n    \"\"\"\n      Returns  the URL of coordinates.\n    \"\"\"\n    return self.asText()\n\n  def asText(self):\n    \"\"\"\n      Returns the coordinates as text.\n    \"\"\"\n    return \'%s %s\' %(self.getLongitude(), self.getLatitude())'),(1513,'document.erp5.GeographicAddress GeographicAddress ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Utils import deprecated\n\nfrom erp5.component.document.Coordinate import Coordinate\n\nclass GeographicAddress(Coordinate):\n  \"\"\"\n      A geographic address holds a complete set of\n      geographic coordinates including street, number,\n      city, zip code, region.\n\n      Geographic address is a terminating leaf\n      in the OFS. It can not contain anything.\n  \"\"\"\n  meta_type = \'ERP5 Geographic Address\'\n  portal_type = \'Address\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.SortIndex\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.GeographicAddress\n                    )\n\n\n  def _splitCoordinateText(self, coordinate_text):\n    \"\"\"return street_address, zip_code, city tuple parsed from string\n    \"\"\"\n    line_list = coordinate_text.splitlines()\n    street_address = zip_code = city = \'\'\n    zip_city = None\n    if len(line_list) > 1:\n      street_address = \'\'.join(line_list[0:-1])\n      zip_city = line_list[-1].split()\n    elif len(line_list):\n      street_address = \'\'\n      zip_city = line_list[-1].split()\n    if zip_city:\n      zip_code = zip_city[0]\n      if len(zip_city) > 1:\n        city = \'\'.join(zip_city[1:])\n    return street_address, zip_code, city\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'asText\')\n  def asText(self):\n    \"\"\"\n      Returns the address as a complete formatted string\n      with street address, zip, and city\n    \"\"\"\n    result = Coordinate.asText(self)\n    if result is None:\n      if self.isDetailed():\n        street_address = self.getStreetAddress(\'\')\n        zip_code = self.getZipCode(\'\')\n        city = self.getCity(\'\')\n      else:\n        street_address, zip_code, city = self._splitCoordinateText(self.getCoordinateText(\'\'))\n      result = \'%s\\n%s %s\' % (street_address, zip_code, city)\n    if not result.strip():\n      return \'\'\n    return result\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'fromText\')\n  @deprecated\n  def fromText(self, coordinate_text):\n    \"\"\"Save given data then continue parsing\n    (deprecated because computed values are stored)\n    \"\"\"\n    self._setCoordinateText(coordinate_text)\n    street_address, zip_code, city = self._splitCoordinateText(coordinate_text)\n    self.setStreetAddress(street_address)\n    self.setZipCode(zip_code)\n    self.setCity(city)\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'standardTextFormat\')\n  def standardTextFormat(self):\n    \"\"\"\n      Returns the standard text format for geographic addresses\n    \"\"\"\n    return (\"\"\"\\\nc/o Jean-Paul Sartre\n43, avenue Kleber\n75118 Paris Cedex 5\n\"\"\",\n)\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'isDetailed\')\n  def isDetailed(self):\n    return self.hasStreetAddress() or self.hasZipCode() or self.hasCity()'),(1514,'document.erp5.GeneratedDeliveryBuilder GeneratedDeliveryBuilder # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2005-2008 Nexedi SA and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.mixin.BuilderMixin import BuilderMixin\n\nclass GeneratedDeliveryBuilder(BuilderMixin):\n  \"\"\"\n    Order Builder objects allow to gather multiple Simulation Movements\n    into a single Delivery.\n\n    The initial quantity property of the Delivery Line is calculated by\n    summing quantities of related Simulation Movements.\n\n    Order Builder objects are provided with a set a parameters to achieve\n    their goal:\n\n    A path definition: source, destination, etc. which defines the general\n    kind of movements it applies.\n\n    simulation_select_method which defines how to query all Simulation\n    Movements which meet certain criteria (including the above path path\n    definition).\n\n    collect_order_list which defines how to group selected movements\n    according to gathering rules.\n\n    delivery_select_method which defines how to select existing Delivery\n    which may eventually be updated with selected simulation movements.\n\n    delivery_module, delivery_type and delivery_line_type which define the\n    module and portal types for newly built Deliveries and Delivery Lines.\n\n    Order Builders can also be provided with optional parameters to\n    restrict selection to a given root Applied Rule caused by a single Order\n    or to Simulation Movements related to a limited set of existing\n    Deliveries.\n  \"\"\"\n\n  # CMF Type Definition\n  meta_type = \'ERP5 Order Builder\'\n  portal_type = \'Order Builder\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Arrow\n                    , PropertySheet.Amount\n                    , PropertySheet.Comment\n                    , PropertySheet.DeliveryBuilder\n                    )\n\n  def _setDeliveryMovementProperties(self, delivery_movement,\n                                     simulation_movement, property_dict,\n                                     update_existing_movement=0,\n                                     force_update=0, activate_kw=None):\n    \"\"\"\n    Initialize or update delivery movement properties.\n    \"\"\"\n    property_dict[\'quantity\'] = simulation_movement.getQuantity()\n    property_dict[\'price\'] = simulation_movement.getPrice()\n    if update_existing_movement:\n      property_dict[\'quantity\'] = (delivery_movement.getQuantity() or 0.0) + property_dict[\'quantity\']\n    # Update properties on object (quantity, price...)\n    delivery_movement._edit(force_update=1, **property_dict)'),(1515,'document.erp5.FirstCausalityMovementGroup FirstCausalityMovementGroup # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#                           Łukasz Nowak <luke@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.CausalityMovementGroup import CausalityMovementGroup\n\nclass FirstCausalityMovementGroup(CausalityMovementGroup):\n  \"\"\"\n  Returns first found causality, using delivery of parent movements\n  Non modifiable version of DeliveryCausalityAssignmentMovementGroup\n  \"\"\"\n  meta_type = \'ERP5 First Causality Movement Group\'\n  portal_type = \'First Causality Movement Group\'\n\n  def test(self, movement, property_dict, **kw):\n    \"\"\"Compare explanation to now if it is possible to update delivery\"\"\"\n    explanation = property_dict.get(\'_explanation\',\'\')\n    if movement == movement.getDeliveryValue():\n      # XXX what is the expected behaviour of this movement group in\n      # delivery level?\n      if movement.getRelativeUrl() == explanation:\n        return True, {}\n      else:\n        return False, {}\n    else:\n      simulation_movement = movement.getDeliveryRelatedValue()\n      if simulation_movement is not None and \\\n         self._getExplanationRelativeUrl(simulation_movement) == explanation:\n        return True, {}\n      else:\n        return False, {}\n\n  def _getExplanationRelativeUrl(self, movement):\n    \"\"\" Get the order value for a movement \"\"\"\n    applied_rule = movement.getParentValue()\n    if applied_rule.isRootAppliedRule():\n      return None\n    parent_movement = applied_rule.getParentValue()\n    # Go upper into the simulation tree in order to find a delivery link\n    parent_delivery = parent_movement.getDeliveryValue()\n    applied_rule = parent_movement.getParentValue()\n    while parent_delivery is None and not applied_rule.isRootAppliedRule():\n      parent_movement = applied_rule.getParentValue()\n      parent_delivery = parent_movement.getDeliveryValue()\n      applied_rule = parent_movement.getParentValue()\n    delivery_movement = parent_delivery\n    delivery_url = None\n    if delivery_movement is not None:\n      delivery = delivery_movement.getExplanationValue()\n      if delivery is not None:\n        delivery_url = delivery.getRelativeUrl()\n    return delivery_url'),(1516,'document.erp5.EmbeddedFile EmbeddedFile # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan tyagov <ivan@nexedi.com>\n#\n# Based on Photo by Ron Bickers\n# Copyright (c) 2001 Logic Etc, Inc.  All rights reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.Image import Image\n\nclass EmbeddedFile(Image):\n  \"\"\"\n    An embedded file (which can act as an image as well).\n  \"\"\"\n\n  meta_type = \'ERP5 Embedded File\'\n  portal_type = \'Embedded File\''),(1517,'document.erp5.DeliveryCausalityAssignmentMovementGroup DeliveryCausalityAssignmentMovementGroup ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.CausalityAssignmentMovementGroup \\\n      import CausalityAssignmentMovementGroup\n\nclass DeliveryCausalityAssignmentMovementGroup(CausalityAssignmentMovementGroup):\n  \"\"\"Like CausalityAssignmentMovementGroup, but using the delivery relation of\n  simulation movements instead of order relation. This is intended to be used\n  in deeper level of simulation tree.\n  \"\"\"\n  meta_type = \'ERP5 Delivery Causality Assignment Movement Group\'\n  portal_type = \'Delivery Causality Assignment Movement Group\'\n\n  def _addCausalityToEdit(self, movement, property_dict):\n    if movement.getParentValue().isRootAppliedRule():\n      # Here movement probably comes from invoice rule, in that situation, we\n      # are not able to go up and find a delivery.\n      return property_dict\n\n    parent = movement.getParentValue().getParentValue()\n    # Go upper into the simulation tree in order to find a delivery link\n    while parent.getDeliveryValue() is None and not(parent.isRootAppliedRule()):\n      parent = parent.getParentValue()\n    delivery_movement = parent.getDeliveryValue()\n    if delivery_movement is not None:\n      delivery = delivery_movement.getExplanationValue()\n      causality = property_dict.setdefault(\'causality_list\', [])\n      delivery_url = delivery.getRelativeUrl()\n      if delivery_url not in causality:\n        causality.append(delivery_url)\n    return property_dict'),(1518,'document.erp5.DayMovementGroup DayMovementGroup \n##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\nfrom erp5.component.module.DateUtils import addToDate\nfrom DateTime import DateTime\n\nclass DayMovementGroup(MovementGroup):\n  \"\"\"\n  This movement group is used to group movements which belong to the same day\n  \"\"\"\n  meta_type = \'ERP5 Day Movement Group\'\n  portal_type = \'Day Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    property_dict = {}\n    start_date = self._getStartDate(movement)\n    property_dict[\'start_date\'] = start_date\n    property_dict[\'stop_date\'] = addToDate(start_date, day=1)\n    return property_dict\n\n  def test(self, document, property_dict, **kw):\n    start_date = property_dict[\'start_date\']\n    stop_date = property_dict[\'stop_date\']\n    if document.getStartDate() <= start_date < stop_date <= document.getStopDate():\n      return True, property_dict\n    else:\n      return False, property_dict\n\n  def _getStartDate(self, movement):\n    start_date = DateTime(movement.getStartDate() is not None and\\\n                          movement.getStartDate().Date() or None)\n    return start_date'),(1519,'document.erp5.Currency Currency ##############################################################################\n#\n# Copyright (c) 2002-2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                         Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5.Document.Resource import Resource\n\nclass Currency(Resource):\n  \"\"\"\n    Currency\n  \"\"\"\n\n  meta_type = \'ERP5 Currency\'\n  portal_type = \'Currency\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Price\n                    , PropertySheet.Resource\n                    , PropertySheet.Reference\n                    )\n\n  # Unit conversion\n  security.declareProtected(Permissions.AccessContentsInformation, \'convertQuantity\')\n  def convertQuantity(self, quantity, from_unit, to_unit, variation_list=(), transformed_resource=None, transformed_variation_list=()):\n    # \'variation_list\' parameter may be deprecated:\n    # cf Measure.getConvertedQuantity\n    return quantity\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'convertCurrency\')\n  def convertCurrency(self, quantity, to_currency):\n    if to_currency is self:\n      return quantity\n    return quantity\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'asNumericCode\')\n  def asNumericCode(self):\n    \"\"\"Return a numeric code defined in ISO 4217.\"\"\"\n    return self.Base_convertCurrencyCodeToNumericCode(self.getReference())'),(1520,'document.erp5.Coordinate Coordinate ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.interface.ICoordinate import ICoordinate\nfrom Products.ERP5Type.Base import Base\nfrom Products.ERP5Type.Utils import deprecated, formatRFC822Headers\nimport re\n\n_marker = object()\n\n@zope.interface.implementer(ICoordinate,)\nclass Coordinate(Base):\n  \"\"\"\n        Coordinates is a mix-in class which is used to store elementary\n        coordinates of an Entity (ex. Person, Organisation)\n\n        UNKNOWN Coordinates are treated as a document\n        with a subject (to find a given type of coordinate).\n\n        Coordinates use a URL approach. Any coordinate can\n        be rendered in a URL style. For example::\n\n            - tel:+33(0)662057614\n\n            - fax:+33(0)153010929\n\n            - mailto:jp@nexedi.com\n\n            - naf:722Z\n\n            - smail://Nexedi/Jean-Paul Smets/943, av de la Republique/59700\n                        Marcq-en-Baroeul/France\n\n        Coordinates are stored as content within an Entity. Coordinate ids\n        are generated as a combination of a so-called role (ex. shipping,\n        billing, etc.) and a class string. This way, coordinates can\n        be accessed as attributes of the containing Entity::\n\n            - default_phone\n\n            - default_fax\n\n            - billing_address\n\n            - shipping_address\n\n        In order to be able to list all coordinates of an Entity,\n        a list of Coordinate metatypes has to be defined and\n        stored somewhere. (TODO)\n  \"\"\"\n\n  meta_type = \'ERP5 Coordinate\'\n  portal_type = \'Coordinate\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security (replaces __ac_permissions__)\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.SimpleItem\n                    , PropertySheet.Coordinate\n                    )\n\n  ### helper methods\n  security.declareProtected( Permissions.AccessContentsInformation,\n                             \'getRegularExpressionFindAll\')\n  def getRegularExpressionFindAll(self, regular_expression, string):\n    \"\"\"\n    allows call of re.findall in a python script used for Coordinate\n    \"\"\"\n    return re.findall(regular_expression, string)\n\n  security.declareProtected( Permissions.AccessContentsInformation,\n                             \'getRegularExpressionGroups\')\n  def getRegularExpressionGroups(self, regular_expression, string):\n    \"\"\"\n    allows call of re.search.groups in a python script used for Coordinate\n    \"\"\"\n    match = re.search(regular_expression, string)\n    if match is None:\n      return ()\n    return re.search(regular_expression, string).groups()\n\n  ### Mix-in methods\n  security.declareProtected( Permissions.AccessContentsInformation,\n                             \'asText\' )\n  def asText(self):\n    \"\"\"\n    returns the coordinate as a text string\n    \"\"\"\n    script = self._getTypeBasedMethod(\'asText\')\n    if script is not None:\n      return script()\n\n  security.declareProtected( Permissions.AccessContentsInformation,\n                             \'getText\')\n  def getText(self):\n    \"\"\"\n    calls asText\n    \"\"\"\n    return self.asText()\n\n  security.declareProtected( Permissions.AccessContentsInformation,\n                             \'hasText\')\n  def hasText(self):\n    \"\"\"\n    calls asText\n    \"\"\"\n    return bool(self.asText())\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getCoordinateText\')\n  def getCoordinateText(self, default=_marker):\n    \"\"\"Fallback on splitted values (old API)\n    \"\"\"\n    if not self.hasCoordinateText() and self.isDetailed():\n      # Display old values (parsed ones)\n      # empty value is None, not \'\'\n      value = self.asText()\n      if value:\n        return value\n      if default is _marker:\n        return None\n      else:\n        return default\n    if default is _marker:\n      return self._baseGetCoordinateText()\n    return self._baseGetCoordinateText(default)\n\n  security.declareProtected( Permissions.ModifyPortalContent, \'fromText\' )\n  @deprecated\n  def fromText(self, coordinate_text):\n    \"\"\"\n    modifies the coordinate according to the input text\n    must be implemented by subclasses\n    \"\"\"\n    script = self._getTypeBasedMethod(\'fromText\')\n    if script is not None:\n      return script(text=coordinate_text)\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'_setText\')\n  def _setText(self, value):\n    \"\"\"\n    calls fromText\n    \"\"\"\n    return self.fromText(value)\n\n  security.declareProtected( Permissions.AccessContentsInformation,\n                             \'standardTextFormat\')\n  def standardTextFormat(self):\n    \"\"\"\n    Returns the standard text formats for telephone numbers\n    \"\"\"\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'isDetailed\')\n  def isDetailed(self):\n    return False\n\n  security.declareProtected( Permissions.View, \'manage_FTPget\' )\n  def manage_FTPget(self):\n    \"\"\"\n    Get the coordinate as text for WebDAV src / FTP download.\n    \"\"\"\n    hdrlist = self.getMetadataHeaders()\n    hdrtext = formatRFC822Headers( hdrlist )\n    bodytext = \'%s\\n\\n%s\' % ( hdrtext, self.asText() )\n\n    return bodytext\n\n  security.declareProtected( Permissions.View, \'get_size\' )\n  def get_size( self ):\n    \"\"\"\n    Used for FTP and apparently the ZMI now too\n    \"\"\"\n    return len(self.manage_FTPget())'),(1521,'document.erp5.CausalityMovementGroup CausalityMovementGroup \n##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\n\nclass CausalityMovementGroup(MovementGroup):\n  \"\"\"\n  The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.\n  \"\"\"\n  meta_type = \'ERP5 Causality Movement Group\'\n  portal_type = \'Causality Movement Group\'\n\n\n  def _getPropertyDict(self, movement, **kw):\n    return {\'_explanation\': self._getExplanationRelativeUrl(movement)}\n\n  def test(self, movement, property_dict, **kw):\n    # we don\'t care the difference of explanation url when updating\n    #return True, property_dict\n    return True, {}\n\n  def _getExplanationRelativeUrl(self, movement):\n    \"\"\" Get the order value for a movement \"\"\"\n    if hasattr(movement, \'getParentValue\'):\n      # This is a simulation movement\n      if movement.getParentValue() != movement.getRootAppliedRule() :\n        # get the explanation of parent movement if we have not been\n        # created by the root applied rule.\n        movement = movement.getParentValue().getParentValue()\n      explanation_value = movement.getExplanationValue()\n      if explanation_value is None:\n        raise ValueError(\'No explanation for movement %s\' % movement.getPath())\n    else:\n      # This is a temp movement\n      explanation_value = None\n    if explanation_value is None:\n      explanation_relative_url = None\n    else:\n      # get the enclosing delivery for this cell or line\n      if hasattr(explanation_value, \'getExplanationValue\') :\n        explanation_value = explanation_value.getExplanationValue()\n\n      explanation_relative_url = explanation_value.getRelativeUrl()\n    return explanation_relative_url'),(1522,'document.erp5.CausalityAssignmentMovementGroup CausalityAssignmentMovementGroup \n##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\n\nclass CausalityAssignmentMovementGroup(MovementGroup):\n  \"\"\"\n  The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.\n\n  This movement group is used in order to define the causality on lines\n  and cells.\n  \"\"\"\n  meta_type = \'ERP5 Causality Assignment Movement Group\'\n  portal_type = \'Causality Assignment Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    return self._addCausalityToEdit(movement, {})\n\n  def _separate(self, movement_list, **kw):\n    if not movement_list:\n      return []\n    property_dict = {}\n    for movement in movement_list:\n      self._addCausalityToEdit(movement, property_dict)\n    return [[movement_list, property_dict]]\n\n  def test(self, movement, property_dict, **kw):\n    causality_list = movement.getCausalityList()\n    if causality_list:\n      property_dict = property_dict.copy()\n      for causality in property_dict.get(\'causality_list\', ()):\n        if causality not in causality_list:\n          causality_list.append(causality)\n      property_dict[\'causality_list\'] = causality_list\n    return True, property_dict\n\n  def _addCausalityToEdit(self, movement, property_dict):\n    causality_list = property_dict.setdefault(\'causality_list\', [])\n    root_movement = movement.getRootSimulationMovement()\n    # \'order\' category is deprecated. it is kept for compatibility.\n    movement_list = root_movement.getOrderList() or \\\n                    root_movement.getDeliveryList()\n    for delivery_movement in movement_list:\n      if delivery_movement not in causality_list:\n        causality_list.append(delivery_movement)\n    return property_dict'),(1523,'document.erp5.CategoryMovementGroup CategoryMovementGroup ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom collections import OrderedDict\nfrom erp5.component.document.PropertyMovementGroup import PropertyMovementGroup\n\nclass CategoryMovementGroup(PropertyMovementGroup):\n  \"\"\"\n  The purpose of MovementGroup is to define how movements are grouped,\n  and how values are updated from simulation movements.\n\n  This movement group is used to group movements that have the same\n  categories (eg. source, destination, etc.).\n\n  Like for equivalence tester, \'specialise\' categories aren\'t sorted\n  alphabetically because the original order is important (see for example\n  CompositionMixin, and how Amount Generator Lines can override others).\n  \"\"\"\n  meta_type = \'ERP5 Category Movement Group\'\n  portal_type = \'Category Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    property_dict = OrderedDict()\n    getProperty = movement.getProperty\n    for prop in self.getTestedPropertyList():\n      list_prop = prop + \'_list\'\n      property_dict[list_prop] = (list if prop == \'specialise\' else\n                                  sorted)(getProperty(list_prop) or ())\n    return property_dict\n\n  def test(self, document, property_dict, property_list=None, **kw):\n    if self.isUpdateAlways():\n      return True, property_dict\n    if property_list not in (None, []):\n      target_property_list = [x for x in self.getTestedPropertyList() \\\n                              if x in property_list]\n    else:\n      target_property_list = self.getTestedPropertyList()\n    getProperty = document.getProperty\n    for prop in target_property_list:\n      list_prop = prop + \'_list\'\n      if property_dict[list_prop] != (list if prop == \'specialise\' else\n                                      sorted)(getProperty(list_prop)):\n        return False, property_dict\n    return True, property_dict'),(1524,'document.erp5.Career Career \n##############################################################################\n#\n# Copyright (c) 2003-2005 Nexedi SARL and Contributors. All Rights Reserved.\n#                         Jean-Paul Smets-Solanes <jp@nexedi.com>\n#                         Kevin Deldycke <kevin_AT_nexedi_DOT_com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\n\nfrom erp5.component.document.Path import Path\n\nclass Career(Path):\n  \"\"\"\n      Contains information about abilities, salary, grade, role... of a\n      Person at a certain career step.\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Career\'\n  portal_type = \'Career\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task\n                    , PropertySheet.Arrow\n                    , PropertySheet.Path\n                    , PropertySheet.Reference\n                    , PropertySheet.Assignment\n                    )'),(1525,'document.erp5.BaseVariantMovementGroup BaseVariantMovementGroup \n##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street - Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.document.MovementGroup import MovementGroup\n\nclass BaseVariantMovementGroup(MovementGroup):\n  \"\"\"\n  This movement group is used to group movements that have the same\n  base category list, without assining it.\n  \"\"\"\n  meta_type = \'ERP5 Base Variant Movement Group\'\n  portal_type = \'Base Variant Movement Group\'\n\n  def _getPropertyDict(self, movement, **kw):\n    return {\'_base_category_list\': sorted(movement.getVariationBaseCategoryList() or [])}\n\n  def test(self, document, property_dict, **kw):\n    # This movement group does not affect updating.\n    return True, {}'),(1526,'document.erp5.BankAccount BankAccount \n##############################################################################\n#\n# Copyright (c) 2002-2005 Nexedi SARL and Contributors. All Rights Reserved.\n#               Jean-Paul Smets-Solanes <jp@nexedi.com>\n#               Kevin Deldycke <kevin@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5.Document.Node import Node\nfrom erp5.component.document.Coordinate import Coordinate\n\nclass BankAccount(Node, Coordinate):\n  \"\"\"\n      A bank account number holds a collection of numbers and codes\n        (ex. SWIFT, RIB, etc.) which may be used to identify a bank account.\n\n      A Bank Account is owned by a Person or an Organisation. A Bank Account\n        contain Agents with Agent Privileges used by the owner to delegate the\n        management of the bank account to trusted third-party Persons.\n  \"\"\"\n\n  meta_type = \'ERP5 Bank Account\'\n  portal_type = \'Bank Account\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.CategoryCore\n                    , PropertySheet.Task\n                    , PropertySheet.Resource\n                    , PropertySheet.Reference\n                    , PropertySheet.BankAccount\n                    )\n\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getReference\')\n  def getReference(self, *args, **kw):\n    \"\"\"reference depends on the site configuration.\n    \"\"\"\n    value = self._baseGetReference(*args, **kw)\n    if value in (None, \'\'):\n      # Try to get a skin from type name\n      method = self._getTypeBasedMethod(\'getReference\')\n      if method is not None:\n        return method(*args, **kw)\n    return value\n\n# XXX The following \"helper methods\" have been commented out, and kept in the\n# code as an example.\n# It might be a potential hazard to have the system automatically fill in the\n# security keys. It is far more secure to have the user enter them manually,\n# and then have the system doucle-check them.\n# This can be accomplished in ERP5 through the use of Constraint.\n#\n#    security.declareProtected(Permissions.View, \'getBankCode\')\n#    def getBankCode(self, **kw):\n#      \"\"\"\n#        Never return None.\n#      \"\"\"\n#      if self.bank_code == None:\n#        return \'\'\n#      return self.bank_code\n#\n#\n#    security.declareProtected(Permissions.View, \'getBranch\')\n#    def getBranch(self, **kw):\n#      \"\"\"\n#        Never return None.\n#      \"\"\"\n#      if self.branch == None:\n#        return \'\'\n#      return self.branch\n#\n#\n#    security.declareProtected(Permissions.View, \'getBankAccountNumber\')\n#    def getBankAccountNumber(self, **kw):\n#      \"\"\"\n#        Never return None.\n#      \"\"\"\n#      if self.bank_account_number == None:\n#        return \'\'\n#      return self.bank_account_number\n#\n#\n#    security.declareProtected(Permissions.View, \'getBankCountryCode\')\n#    def getBankCountryCode(self, **kw):\n#      \"\"\"\n#        Never return None.\n#      \"\"\"\n#      if self.bank_country_code == None:\n#        return \'\'\n#      return self.bank_country_code\n#\n#\n#    security.declareProtected(Permissions.View, \'getIbanTextFormat\')\n#    def getIbanTextFormat(self):\n#      \"\"\"\n#        Returns the standard IBAN text format\n#      \"\"\"\n#      iban = self.getIban()\n#      l = 4\n#      s = \"IBAN\"\n#      for i in range((len(iban) / l) + 1):\n#        s += \' \' + iban[i*l : (i+1)*l]\n#      return s.strip()\n#\n#\n#    security.declareProtected(Permissions.View, \'getIbanTextFormat\')\n#    def getIban(self):\n#      \"\"\"\n#        The International Bank Account Number of this bank account.\n#        IBAN is an international standard for identifying bank accounts worldwide.\n#      \"\"\"\n#      key          = self.getIbanKey()\n#      country_code = self.getBankCountryCode()\n#      bban         = self.getBban()\n#      return (country_code + key + bban).upper().strip()\n#\n#\n#    security.declareProtected(Permissions.View, \'getIbanKey\')\n#    def getIbanKey(self):\n#      \"\"\"\n#        The IBAN key ensure the integry of the IBAN code.\n#        It\'s calculated with the ISO 7064 method (known as \"97-10 modulo\").\n#      \"\"\"\n#      # Construct the alpha to number translation table\n#      table = {}\n#      for i in range(26):\n#        table[chr(65+i)] = str(10+i)\n#      # Calcul the key\n#      country_code = self.getBankCountryCode() + \'00\'\n#      s = self.getBban() + country_code\n#      n = \'\'\n#      for c in s:\n#        if c.isalpha():\n#          n += table[c.upper()]\n#        if c.isdigit():\n#          n += c\n#      key = str(98 - (int(n) % 97))\n#      return key.zfill(2)\n#\n#\n#    security.declareProtected(Permissions.View, \'getBban\')\n#    def getBban(self):\n#      \"\"\"\n#        The Basic Bank Account Number (BBAN) is the last part of the IBAN.\n#        Usualy it correspond to the national bank account number.\n#      \"\"\"\n#      bank   = self.getBankCode()\n#      branch = self.getBranch()\n#      ban    = self.getBankAccountNumber()\n#      key    = self.getBbanKey()\n#      return (bank + branch + ban + key).upper().strip()\n#\n#\n#    security.declareProtected(Permissions.View, \'getBbanTextFormat\')\n#    def getBbanTextFormat(self, sep=\' \'):\n#      \"\"\"\n#        Returns a BBAN text format\n#      \"\"\"\n#      bank   = self.getBankCode()\n#      branch = self.getBranch()\n#      ban    = self.getBankAccountNumber()\n#      key    = self.getBbanKey()\n#      return sep.join([bank, branch, ban, key]).upper().strip()\n#\n#\n#    security.declareProtected(Permissions.View, \'getBbanKey\')\n#    def getBbanKey(self):\n#      \"\"\"\n#        The BBAN key ensure the integry of the BBAN code.\n#        This is the french BBAN key algorithm.\n#      \"\"\"\n#      def transcode(string):\n#        letter = \'ABCDEFGHIJ