#########################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\n\nfrom erp5.component.document.Path import Path\n\n\nclass Assignment(Path):\n  # CMF Type Definition\n  meta_type = \'ERP5 Assignment\'\n  portal_type = \'Assignment\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task\n                    , PropertySheet.Arrow\n                    , PropertySheet.Path\n                    , PropertySheet.Assignment\n                    )'),(1528,'document.erp5.AgentPrivilege AgentPrivilege ##############################################################################\n#\n# Copyright (c) 2005 Nexedi SARL and Contributors. All Rights Reserved.\n#               Kevin Deldycke <kevin@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\n\n\nclass AgentPrivilege(XMLObject):\n  \"\"\"\n  An Agent Privilege allow the Bank Account owner to give permissions to an Agent for a given period of time, for a maximum amount of money.\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Agent Privilege\'\n  portal_type = \'Agent Privilege\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task\n                    , PropertySheet.AgentPrivilege\n                    )'),(1529,'document.erp5.Agent Agent ##############################################################################\n#\n# Copyright (c) 2002-2005 Nexedi SARL and Contributors. All Rights Reserved.\n#               Sebastien Robin <seb@nexedi.com>\n#               Kevin Deldycke <kevin@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom erp5.component.document.Image import Image\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Core.Folder import Folder\n\n\nclass Agent(Folder, Image):\n  \"\"\"\n    An Agent is a Person who is permitted to perform some actions on the bank\n    account according to Privileges.\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Agent\'\n  portal_type = \'Agent\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task\n                    , PropertySheet.Agent\n                    )\n\n  # content_type property is also a method from PortalFolder, so we need a\n  # valid type by default.\n  content_type = \'\'\n\n  def __init__(self, *args, **kw):\n    Folder.__init__(self, *args, **kw)\n    Image.__init__(self, *args, **kw)\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'viewImage\')\n  viewImage = Image.index_html\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'importSignature\')\n  def importSignature(self, import_file=None, form_id=None, REQUEST=None, **kw):\n    \"\"\"\n      Imports a scan of a signature.\n    \"\"\"\n    if REQUEST is None:\n      REQUEST = getattr(self, \'REQUEST\', None)\n\n    if (import_file is None) or (len(import_file.read()) == 0) :\n      if REQUEST is not None :\n        REQUEST.RESPONSE.redirect(\"%s?portal_status_message=No+file+or+an+empty+file+was+specified\"\n                                  % self.absolute_url())\n        return\n      else :\n        raise RuntimeError(\'No file or an empty file was specified\')\n\n    import_file.seek(0)\n    self.manage_upload(file=import_file)\n    #    self._data = import_file.read()\n\n    if REQUEST is not None:\n      ret_url = self.absolute_url() + \'/\' + REQUEST.get(\'form_id\', \'view\')\n      REQUEST.RESPONSE.redirect(\"%s?portal_status_message=Signature+Imported+Successfully\"\n                                % ret_url)'),(1530,'module.erp5.XMLUtils XMLUtils \"\"\"\nThe purpose of this module is to have an XML parser capable of handling >50MB files\nwithout using too much RAM.\n\"\"\"\nfrom xml.etree.ElementTree import iterparse, Element, TreeBuilder, XMLParser\nfrom Products.ERP5Type.mixin.matrix import INFINITE_SET\n\nclass RestrictedElement(Element):\n  __allow_access_to_unprotected_subobjects__ = 1\n\nclass ChildDiscardingElement(RestrictedElement):\n  \"\"\"\n  Ignores any children added to it.\n\n  Useful to parse large files, so as many-children nodes actually discards\n  them to free memory.\n  \"\"\"\n  def __init__(self, tag, expected_tag_set):\n    super(ChildDiscardingElement, self).__init__(tag)\n    self.__expected_tag_set = expected_tag_set\n\n  def __single(self, child):\n    if not (\n          isinstance(child, ChildDiscardingElement) or\n          child.tag in self.__expected_tag_set\n        ):\n      raise ValueError(\'Unexpected discarded tag: %r (inside %r)\' % (\n        child.tag,\n        self.tag,\n      ))\n\n  append = __single\n\n  def extend(self, elements):\n    for child in elements:\n      self.__single(child)\n\n  def insert(self, index, element):\n    self.__single(element)\n\ndef parseStream(stream, child_discard_set, callback_dict, catchall=None):\n  \"\"\"\n  stream (opened read stream)\n    Where XML data is read from. Expects a \"read\" method following the\n    \"file\" API.\n\n  child_discard_set (anything implementing \'__in__\')\n    Set of tags whose children should be discarded while parsing.\n\n  callback_dict (dict)\n    Dict of callables per event and tag type, to be called for these\n    combinations when encountered. Expected structure is:\n    {\n      (event, tag): callable(element) -> None,\n    }\n    See xml.etree.ElementTree.iterparse for a list of possible events.\n\n  catchall (None, callable(element) -> None)\n    Callback triggered for all actually triggered events but not declared in\n    callback_dict.\n    If None, a ValueError exception will be raised when an element whose tag is\n    present in child_discard_set receives a non-child-discarding child for\n    which neither \"start\" nor \"end\" callback exist.\n  \"\"\"\n  if catchall is None:\n    catchall = lambda x: None\n    callback_set = {\n      y for x, y in callback_dict\n      if x in (\'start\', \'end\', None) # None is equivalent to \'end\'\n    }\n  else:\n    callback_set = INFINITE_SET\n  def elementFactory(tag, attrs):\n    if tag in child_discard_set:\n      return ChildDiscardingElement(tag, callback_set)\n    return RestrictedElement(tag, attrs)\n  for event, elem in iterparse(\n          stream,\n          events={x for x, _ in callback_dict},\n          parser=XMLParser(\n            target=TreeBuilder(\n              element_factory=elementFactory,\n            ),\n          ),\n        ):\n    callback_dict.get((event, elem.tag), catchall)(elem)\n\nfrom AccessControl.SecurityInfo import ModuleSecurityInfo\nModuleSecurityInfo(__name__).declarePublic(\'parseStream\')'),(1531,'module.erp5.TransformLib TransformLib # -*- coding: utf-8 -*-\n\nfrom Products.PortalTransforms.interfaces import ITransform\nfrom zope.interface import implementer\nfrom erp5.component.document.Document import DocumentConversionServerProxy, ConversionError, enc, dec\nfrom Products.ERP5Type.Utils import bytes2str, str2bytes\n@implementer(ITransform)\nclass DocumentConversionServerTransform:\n  \"\"\"\n  Transformer using Conversion Server\n  \"\"\"\n\n  # Name of the Transform as registered in portal_transforms\n  __name__ = None\n  # Tuple of source MIME types\n  inputs = ()\n  # Destination MIME type\n  output = \'\'\n\n  def __init__(self, name=None):\n    if name is not None:\n      self.__name__ = name\n\n  def name(self):\n    return self.__name__\n\n  def _getAllowedSourceMimetypeFromConversionServer(self, server_proxy):\n    for mimetype in self.inputs:\n      for allowed_mimetype, _ in server_proxy.getAllowedConversionFormatList(mimetype):\n        if mimetype == allowed_mimetype:\n          return mimetype\n\n    return None\n\n  def _getFormatFromMimetype(self, mimetype):\n    \"\"\"\n    XXX: This should not be done here but Conversion Server API to get\n         supported Format/Extension is deprecated (topic under discussion)\n    \"\"\"\n    import mimetypes\n    extension = mimetypes.guess_extension(mimetype)\n    if extension is None:\n      raise ConversionError(\"Could not guess extension from mimetype \'%s\'\" % mimetype)\n    return extension.split(\'.\', 1)[1]\n\n  def convert(self, orig, data, context=None, **kwargs):\n    server_proxy = DocumentConversionServerProxy(context)\n\n    source_mimetype = self._getAllowedSourceMimetypeFromConversionServer(server_proxy)\n    if source_mimetype is None:\n      raise ConversionError(\"Format(s) not allowed on Conversion Server %r\" % self.inputs)\n    source_format = self._getFormatFromMimetype(source_mimetype)\n    destination_format = self._getFormatFromMimetype(self.output)\n\n    data.setData(dec(str2bytes(server_proxy.convertFile(\n      bytes2str(enc(orig)),\n      source_format,\n      destination_format,\n      # Default values are ConversionServer default ones\n      kwargs.get(\'zip\', False),\n      kwargs.get(\'refresh\', False),\n      kwargs.get(\'conversion_kw\', {})))))\n\n    return data'),(1532,'module.erp5.TransformImageToPcx TransformImageToPcx from Products.PortalTransforms.libtransforms.imagemagick_transform import ImageMagickTransforms\n\nclass image_to_pcx(ImageMagickTransforms):\n  __name__  = \"image_to_pcx\"\n  inputs    = (\'image/*\', )\n  output    = \'image/vnd.zbrush.pcx\'\n  format    = \'pcx\'\n\ndef register():\n  return image_to_pcx()'),(1533,'module.erp5.TransformImageToBmp TransformImageToBmp from Products.PortalTransforms.libtransforms.imagemagick_transform import ImageMagickTransforms\n\nclass image_to_bmp(ImageMagickTransforms):\n  __name__  = \"image_to_bmp\"\n  inputs    = (\'image/*\', )\n  output    = \'image/bmp\'\n  format    = \'bmp\'\n\ndef register():\n  return image_to_bmp()'),(1534,'module.erp5.ImageUtil ImageUtil #############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport six.moves.urllib.request\nfrom lxml import etree\nfrom erp5.component.document.Document import ConversionError\nimport base64\nfrom Products.ERP5Type.Utils import bytes2str\n\nSVG_DEFAULT_NAMESPACE = \"http://www.w3.org/2000/svg\"\n\ndef getDataURI(url):\n  try:\n    data = six.moves.urllib.request.urlopen(url)\n  except Exception as e:\n    raise ConversionError(\"Error to transform url (%s) into data uri. ERROR = %s\" % (url, Exception(e)))\n  return \'data:%s;base64,%s\' % (data.info()[\"content-type\"],\n                                bytes2str(base64.b64encode(data.read())).replace(\'\\n\', \"\"))\n\ndef transformUrlToDataURI(content):\n  if content is None or len(content) == 0:\n    return content\n\n  root = etree.fromstring(content)\n\n  # Prevent namespace contains \"None\" included into svg by mistake\n  # and fix svg definition as in some images the namespace is not\n  # well defined by using xmlns=\"http://www.w3.org/2000/svg\" instead\n  # of xmlns:svg=\"http://www.w3.org/2000/svg\".\n  namespace_dict = root.nsmap.copy()\n  discarted = namespace_dict.pop(None, \"discard\")\n  if discarted == SVG_DEFAULT_NAMESPACE or \\\n       \"svg\" not in namespace_dict:\n    namespace_dict[\"svg\"] = SVG_DEFAULT_NAMESPACE\n\n  # Get all images which uses xlink:href\n  image_list = root.xpath(\"//svg:image[@xlink:href]\", namespaces=namespace_dict)\n  xlink_href = \"{%s}href\" % namespace_dict.get(\"xlink\", None)\n  # Transform all images which uses url, into data URI\n  for image in image_list:\n    url_value = image.get(xlink_href)\n    if url_value.startswith(\"http\"):\n      image.set(xlink_href, getDataURI(image.get(xlink_href)))\n\n  return etree.tostring(\n    root,\n    encoding=\"utf-8\",\n    xml_declaration=True,\n    standalone=\"no\",\n  )'),(1542,'Draft Default state of the document'),(1543,'User Account Workflow This workflow controls who can set user ids and passwords. user_account_workflow'),(1547,'Error message if validation failed'),(1551,'Succeed This transition is invoked when a target solver succeeds to solve divergences.'),(1552,'Start Solving This transition is invoked when a target solver begins to solve divergences.'),(1553,'Fail This transition is triggered when a target solver fails to solve divergences.'),(1554,'Solving A target solver is solving divergences.'),(1555,'Solved A target solver succeeded to solve divergences.'),(1556,'Failed A target solver failed to solve divergences.'),(1557,'Draft Default state of the document'),(1560,'Solver Workflow This workflow manages the state of the process of a target solver. solver_workflow'),(1564,'Error message if validation failed'),(1568,'Succeed This transition is invoked when a target solver succeeds to solve divergences.'),(1569,'Start Solving This transition is invoked when a target solver begins to solve divergences.'),(1570,'Fail This transition is triggered when a target solver fails to solve divergences.'),(1571,'Solving A target solver is solving divergences.'),(1572,'Solved A target solver succeeded to solve divergences.'),(1573,'Failed A target solver failed to solve divergences.'),(1574,'Draft Default state of the document'),(1575,'Solver Process Workflow This workflow manages the state of the process of a target solver. solver_process_workflow'),(1578,'Simulation Movement Interaction Workflow This workflow is used to update the causality state 