ode_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=500, credit=0,\n        final_debit_balance=500, final_credit_balance=0,\n        final_balance_if_debit=500, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=500, final_debit_balance=0,\n        final_credit_balance=500, final_balance_if_debit=0,\n        final_balance_if_credit=500,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=500,\n        credit=500, final_debit_balance=500, final_credit_balance=500,\n        final_balance_if_debit=500, final_balance_if_credit=500)\n\n  def testTrialBalanceNoProject(self):\n    # trial balance restricted to no project\n    self.createProjectAndFunctionDataSet()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'stopped\', \'delivered\']\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'project\'] = \'None\'\n    request_form[\'group_analytic\'] = []\n    request_form[\'show_detailed_balance_columns\'] = 1\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0], node_id=\'41\',\n        node_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=700, credit=0,\n        final_debit_balance=700, final_credit_balance=0,\n        final_balance_if_debit=700, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=700, final_debit_balance=0,\n        final_credit_balance=700, final_balance_if_debit=0,\n        final_balance_if_credit=700,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=700,\n        credit=700, final_debit_balance=700, final_credit_balance=700,\n        final_balance_if_debit=700, final_balance_if_credit=700)\n\n\n  def testTrialBalanceMirrorSectionRole(self):\n    # trial balance restricted to a mirror section role\n    self.createMirrorSectionRoleDataSet()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'stopped\', \'delivered\']\n    request_form[\'mirror_section_category_list\'] = [\'role/supplier\']\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'group_analytic\'] = []\n    request_form[\'show_detailed_balance_columns\'] = 1\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0], node_id=\'41\',\n        node_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=300, credit=0,\n        final_debit_balance=300, final_credit_balance=0,\n        final_balance_if_debit=300, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=300, final_debit_balance=0,\n        final_credit_balance=300, final_balance_if_debit=0,\n        final_balance_if_credit=300,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=300,\n        credit=300, final_debit_balance=300, final_credit_balance=300,\n        final_balance_if_debit=300, final_balance_if_credit=300)\n\n  def testTrialBalanceLedger(self):\n    # trial balance restricted to a ledger\n    self.createLedgerDataSet()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'stopped\', \'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'portal_type\'] = [\'Sale Invoice Transaction\']\n    request_form[\'group_analytic\'] = []\n    request_form[\'show_detailed_balance_columns\'] = 1\n\n    # only get transactions belonging to ledger.accounting.general\n    request_form[\'ledger\'] = \'ledger/accounting/general\'\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0], node_id=\'41\',\n        node_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=500, credit=0,\n        final_debit_balance=500, final_credit_balance=0,\n        final_balance_if_debit=500, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=500, final_debit_balance=0,\n        final_credit_balance=500, final_balance_if_debit=0,\n        final_balance_if_credit=500,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=500,\n        credit=500, final_debit_balance=500, final_credit_balance=500,\n        final_balance_if_debit=500, final_balance_if_credit=500)\n\n  def testTrialBalanceWithMultipleLedger(self):\n    # trial balance restricted to a ledger\n    self.createLedgerDataSet()\n\n    # get a report on both ledgers\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'stopped\', \'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'portal_type\'] = [\'Sale Invoice Transaction\']\n    request_form[\'group_analytic\'] = []\n    request_form[\'show_detailed_balance_columns\'] = 1\n    request_form[\'ledger\'] = [\'ledger/accounting/general\',\n                              \'ledger/accounting/detailed\']\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0], node_id=\'41\',\n        node_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=1000, credit=0,\n        final_debit_balance=1000, final_credit_balance=0,\n        final_balance_if_debit=1000, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=1000, final_debit_balance=0,\n        final_credit_balance=1000, final_balance_if_debit=0,\n        final_balance_if_credit=1000,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=1000,\n        credit=1000, final_debit_balance=1000, final_credit_balance=1000,\n        final_balance_if_debit=1000, final_balance_if_credit=1000)\n\n  def testTrialBalanceNoLedger(self):\n    # trial balance with no filter on ledger\n    # it is expected to return a report on all movements\n    self.createLedgerDataSet()\n\n    # Document with no ledger\n    self._makeOne(\n              portal_type=\'Sale Invoice Transaction\',\n              title=\'Ledger general\',\n              reference=\'noledger\',\n              simulation_state=\'delivered\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 2),\n              lines=(dict(source_value=self.portal.account_module.receivable,\n                          source_debit=400.0),\n                     dict(source_value=self.portal.account_module.goods_sales,\n                          source_credit=400.0)))\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'stopped\', \'delivered\']\n    request_form[\'ledger\'] = \'None\'\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'portal_type\'] = [\'Sale Invoice Transaction\']\n    request_form[\'group_analytic\'] = []\n    request_form[\'show_detailed_balance_columns\'] = 1\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0], node_id=\'41\',\n        node_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=400, credit=0,\n        final_debit_balance=400, final_credit_balance=0,\n        final_balance_if_debit=400, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=400, final_debit_balance=0,\n        final_credit_balance=400, final_balance_if_debit=0,\n        final_balance_if_credit=400,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=400,\n        credit=400, final_debit_balance=400, final_credit_balance=400,\n        final_balance_if_debit=400, final_balance_if_credit=400)\n\n  def testTrialBalanceAtDateLatestTime(self):\n    # account statement with at_date should include the transactions from that at_date\n    self.createAtDateDataSet()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 2, 2)\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'stopped\', \'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'portal_type\'] = [\'Sale Invoice Transaction\']\n    request_form[\'group_analytic\'] = []\n    request_form[\'show_detailed_balance_columns\'] = 1\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0], node_id=\'41\',\n        node_title=\'Receivable\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=500, credit=0,\n        final_debit_balance=500, final_credit_balance=0,\n        final_balance_if_debit=500, final_balance_if_credit=0,)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', initial_debit_balance=0,\n        initial_credit_balance=0, debit=0, credit=500, final_debit_balance=0,\n        final_credit_balance=500, final_balance_if_debit=0,\n        final_balance_if_credit=500,)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], node_id=None, node_title=None,\n        initial_debit_balance=0, initial_credit_balance=0, debit=500,\n        credit=500, final_debit_balance=500, final_credit_balance=500,\n        final_balance_if_debit=500, final_balance_if_credit=500)\n\n  def testGeneralLedger(self):\n    # Simple test of general ledger\n    # we will use the same data set as account statement\n    self.createAccountStatementDataSet(use_two_bank_accounts=0)\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(6, len(report_section_list))\n\n    self.assertEqual(\'40 - Payable (Client 1)\',\n                      report_section_list[0].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    # The box showing parameters summary in\n    # Account_viewAccountingTransactionList is not rendered here.\n    report_section = report_section_list[0]\n    report_section.pushReport(self.portal)\n    form = getattr(self.portal, report_section.form_id)\n    # we test that this form only shows a listbox\n    for group in form.get_groups():\n      if group != \'hidden\':\n        for field in form.get_fields_in_group(group):\n          if field.getId() != \'listbox\':\n            self.fail(\'Field %s should not be visible\' % field.getId())\n    report_section.popReport(self.portal)\n\n    # currency is present in the report\n    self.assertEqual(\'currency_module/euro\', self.portal.\n        AccountModule_viewGeneralLedgerReport.your_currency.get_value(\'default\'))\n\n    # report layout\n    self.assertEqual( [\'date\', \'Movement_getSpecificReference\', \'mirror_section_title\',\n        \'Movement_getExplanationTitleAndAnalytics\', \'debit_price\',\n        \'credit_price\', \'running_total_price\', \'grouping_reference\',\n        \'grouping_date\', \'getTranslatedSimulationStateTitle\'],\n        data_line_list[0].column_id_list)\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          mirror_section_title=\'Client 1\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 1\\nref1\',\n          date=DateTime(2006, 2, 1),\n          debit_price=0, credit_price=100, running_total_price=-100, )\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getSpecificReference=\'2\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 2\\nref2\',\n          date=DateTime(2006, 2, 1, 0, 1),\n          debit_price=200, credit_price=0, running_total_price=100, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          Movement_getSpecificReference=None,\n          Movement_getExplanationTitleAndAnalytics=None,\n          date=None,\n          debit_price=200, credit_price=100, )\n\n    self.assertEqual(\'41 - Receivable (Client 1)\',\n                      report_section_list[1].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(5, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 1\\nref1\',\n          date=DateTime(2006, 2, 1),\n          debit_price=100, credit_price=0, running_total_price=100, )\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getSpecificReference=\'2\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 2\\nref2\',\n          date=DateTime(2006, 2, 1, 0, 1),\n          debit_price=0, credit_price=200, running_total_price=-100, )\n\n    self.checkLineProperties(data_line_list[2],\n          Movement_getSpecificReference=\'3\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 3\\nref3\',\n          date=DateTime(2006, 2, 2, 0, 2),\n          debit_price=300, credit_price=0, running_total_price=200, )\n\n    self.checkLineProperties(data_line_list[3],\n          Movement_getSpecificReference=\'6\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 6\\nref6\',\n          date=DateTime(2006, 2, 2, 0, 5),\n          debit_price=600, credit_price=0, running_total_price=800, )\n\n    self.checkLineProperties(data_line_list[4],\n          Movement_getSpecificReference=\'8\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 8\\nref8\',\n          date=DateTime(2006, 2, 3),\n          debit_price=800, credit_price=0, running_total_price=1600, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          Movement_getSpecificReference=None,\n          Movement_getExplanationTitleAndAnalytics=None,\n          date=None,\n          debit_price=1800, credit_price=200, )\n\n    self.assertEqual(\'41 - Receivable (Client 2)\',\n                      report_section_list[2].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'4\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 4\\nref4\',\n          date=DateTime(2006, 2, 2, 0, 3),\n          debit_price=400, credit_price=0, running_total_price=400, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=400, credit_price=0, )\n\n    self.assertEqual(\'41 - Receivable (John Smith)\',\n                      report_section_list[3].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[3])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'5\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 5\\nref5\',\n          date=DateTime(2006, 2, 2, 0, 4),\n          debit_price=500, credit_price=0, running_total_price=500, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=500, credit_price=0, )\n\n    self.assertEqual(\'5 - Bank (Bank1)\',\n                      report_section_list[4].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[4])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(5, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'3\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 3\\nref3\',\n          date=DateTime(2006, 2, 2, 0, 2),\n          debit_price=0, credit_price=300, running_total_price=-300, )\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getSpecificReference=\'4\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 4\\nref4\',\n          date=DateTime(2006, 2, 2, 0, 3),\n          debit_price=0, credit_price=400, running_total_price=-700, )\n\n    self.checkLineProperties(data_line_list[2],\n          Movement_getSpecificReference=\'5\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 5\\nref5\',\n          date=DateTime(2006, 2, 2, 0, 4),\n          debit_price=0, credit_price=500, running_total_price=-1200, )\n\n    self.checkLineProperties(data_line_list[3],\n          Movement_getSpecificReference=\'6\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 6\\nref6\',\n          date=DateTime(2006, 2, 2, 0, 5),\n          debit_price=0, credit_price=600, running_total_price=-1800, )\n\n    self.checkLineProperties(data_line_list[4],\n          Movement_getSpecificReference=\'8\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 8\\nref8\',\n          date=DateTime(2006, 2, 3),\n          debit_price=0, credit_price=800, running_total_price=-2600, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=2600, )\n\n    self.assertEqual(\'Total\', report_section_list[5].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[5])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    # report layout\n    self.assertEqual([\'debit_price\', \'credit_price\'], data_line_list[0].column_id_list)\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=2900, credit_price=2900)\n\n  def testGeneralLedgerInitialBalance(self):\n    # Initial balance line on GL\n    # we will use the same data set as account statement\n    self.createAccountStatementDataSetOnTwoPeriods()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 2, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'gap_list\'] = [\n        \'my_country/my_accounting_standards/4/41\']\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(2, len(report_section_list))\n\n    self.assertEqual(\n        \'41 - Receivable (Client 1)\',\n        report_section_list[0].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(\n        data_line_list[0],\n        Movement_getSpecificReference=\'Previous Balance\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 1),\n        debit_price=300,\n        credit_price=0,\n        running_total_price=300, )\n\n    self.checkLineProperties(\n        data_line_list[1],\n        Movement_getSpecificReference=\'3\',\n        Movement_getExplanationTitleAndAnalytics=\'Transaction 3\\nref3\',\n        date=DateTime(2006, 2, 2),\n        debit_price=300,\n        credit_price=0,\n        running_total_price=600, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          Movement_getSpecificReference=None,\n          Movement_getExplanationTitleAndAnalytics=None,\n          date=None,\n          debit_price=600, credit_price=0, )\n\n    self.assertEqual(\'Total\', report_section_list[1].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(\n        data_line_list[0],\n        debit_price=600,\n        credit_price=0)\n\n  def testGeneralLedgerExportInitialBalance(self):\n    # Initial balance on GL export\n    # we will use the same data set as account statement\n    self.createAccountStatementDataSetOnTwoPeriods()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 2, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'gap_list\'] = [\n        \'my_country/my_accounting_standards/4/41\']\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = True\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    # export mode has no section headers\n    self.assertEqual(None, report_section_list[0].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(\n        data_line_list[0],\n        Movement_getSpecificReference=\'Previous Balance\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 1),\n        debit_price=300,\n        credit_price=0, )\n\n    self.checkLineProperties(\n        data_line_list[1],\n        Movement_getSpecificReference=\'3\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        debit_price=300,\n        credit_price=0, )\n\n    self.assertFalse(line_list[-1].isStatLine())\n\n  def testGeneralLedgerReceivableAccountNoMirrorSection(self):\n    self.createAccountStatementDataSetOnTwoPeriods()\n    # adjust the data to remove the mirror section, this create inconsistent\n    # transactions, but in practice it happened in scenarios like:\n    #  - account is not asset/receivable, transactions are recorded without\n    #    mirror section\n    #  - account is changed to asset/receivable\n    # the existing transactions would not be accepted with the new account\n    # configuration, but existing transactions are OK anyway.\n    for si in self.portal.accounting_module.contentValues(portal_type=\'Sale Invoice Transaction\'):\n      self.assertEqual(si.getDestinationSectionValue(), self.organisation_module.client_1)\n      si.setDestinationSection(None)\n    self.tic()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 2, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'gap_list\'] = [\n        \'my_country/my_accounting_standards/4/41\']\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = True\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    # export mode has no section headers\n    self.assertEqual(None, report_section_list[0].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(\n        data_line_list[0],\n        Movement_getSpecificReference=\'Previous Balance\',\n        mirror_section_title=\'\',\n        date=DateTime(2006, 2, 1),\n        debit_price=300,\n        credit_price=0, )\n\n    self.checkLineProperties(\n        data_line_list[1],\n        Movement_getSpecificReference=\'3\',\n        mirror_section_title=None,  # an implementation detail makes that this is None and not \'\' here\n        date=DateTime(2006, 2, 2),\n        debit_price=300,\n        credit_price=0, )\n\n  def testGeneralLedgerGAPFilter(self):\n    # General Ledger filtered by GAP category\n    # we will use the same data set as account statement\n    self.createAccountStatementDataSet(use_two_bank_accounts=0)\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'gap_list\'] = [\'my_country/my_accounting_standards/4/40\']\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(2, len(report_section_list))\n\n    self.assertEqual(\'40 - Payable (Client 1)\',\n                      report_section_list[0].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 1\\nref1\',\n          date=DateTime(2006, 2, 1),\n          debit_price=0, credit_price=100, running_total_price=-100, )\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getSpecificReference=\'2\',\n          Movement_getExplanationTitleAndAnalytics=\'Transaction 2\\nref2\',\n          date=DateTime(2006, 2, 1, 0, 1),\n          debit_price=200, credit_price=0, running_total_price=100, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          Movement_getSpecificReference=None,\n          Movement_getExplanationTitleAndAnalytics=None,\n          date=None,\n          debit_price=200, credit_price=100, )\n\n    self.assertEqual(\'Total\', report_section_list[1].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=200, credit_price=100)\n\n  def testGeneralLedgerGAPFilterSameGAPSelectedTwice(self):\n    # General Ledger filtered by GAP category. Edge case: selecting\n    # a gap and its parent. This use to double the amount because\n    # node is twice member of node_category\n\n    # we will use the same data set as account statement\n    self.createAccountStatementDataSetOnTwoPeriods()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 2, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    # Here we select 4 and 41\n    request_form[\'gap_list\'] = [\n        \'my_country/my_accounting_standards/4\',\n        \'my_country/my_accounting_standards/4/41\']\n\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(2, len(report_section_list))\n\n    self.assertEqual(\n        \'41 - Receivable (Client 1)\',\n        report_section_list[0].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(\n        data_line_list[0],\n        Movement_getSpecificReference=\'Previous Balance\',\n        date=DateTime(2006, 2, 1),\n        debit_price=300,\n        credit_price=0,\n        running_total_price=300, )\n\n    self.checkLineProperties(\n        data_line_list[1],\n        Movement_getSpecificReference=\'3\',\n        Movement_getExplanationTitleAndAnalytics=\'Transaction 3\\nref3\',\n        date=DateTime(2006, 2, 2),\n        debit_price=300,\n        credit_price=0,\n        running_total_price=600, )\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          Movement_getSpecificReference=None,\n          Movement_getExplanationTitleAndAnalytics=None,\n          date=None,\n          debit_price=600, credit_price=0, )\n\n    self.assertEqual(\'Total\', report_section_list[1].getTitle())\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(\n        data_line_list[0],\n        debit_price=600,\n        credit_price=0)\n\n  def testGeneralLedgerGAPRoot(self):\n    # General Ledger export, with a GAP root\n    self.createAccountStatementDataSet(use_two_bank_accounts=0)\n\n    # adjust accounts to have an account number on `another_country/another_standards`\n    payable_gap_list = self.account_module.payable.getGapList()\n\n    def cleanup(account, gap_list):\n      account.setGapList(gap_list)\n      self.tic()\n    self.addCleanup(cleanup, self.account_module.payable, payable_gap_list)\n    self.account_module.payable.setGapList(set(payable_gap_list + [\'another_country/another_standards/1\']))\n    self.tic()\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'gap_root\'] = \'gap/another_country/another_standards\'\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = True\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getNodeGapId=\'1\',\n          Movement_getSpecificReference=\'1\',\n          date=DateTime(2006, 2, 1),\n          debit_price=0, credit_price=100, )\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getNodeGapId=\'1\',\n          Movement_getSpecificReference=\'2\',\n          date=DateTime(2006, 2, 1, 0, 1),\n          debit_price=200, credit_price=0, )\n\n  def testGeneralLedgerFunction(self):\n    # general ledger restricted to a function\n    self.createProjectAndFunctionDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'function\'] = \'function/a\'\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          Movement_getExplanationTitleAndAnalytics=\n            \'Function a Project 1\\nFaP1\',\n          date=DateTime(2006, 2, 2),\n          debit_price=500, credit_price=0, running_total_price=500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=500, credit_price=0)\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          Movement_getExplanationTitleAndAnalytics=\n            \'Function a Project 1\\nFaP1\',\n          date=DateTime(2006, 2, 2),\n          debit_price=0, credit_price=500, running_total_price=-500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=500)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=500, credit_price=500)\n\n  def testGeneralLedgerNoProject(self):\n    # general ledger restricted to no project\n    self.createProjectAndFunctionDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'project\'] = \'None\'\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'3\',\n          Movement_getExplanationTitleAndAnalytics=\'No function no project\\nnono\',\n          date=DateTime(2006, 2, 2),\n          debit_price=700, credit_price=0, running_total_price=700, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=700, credit_price=0)\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'3\',\n          Movement_getExplanationTitleAndAnalytics=\'No function no project\\nnono\',\n          date=DateTime(2006, 2, 2),\n          debit_price=0, credit_price=700, running_total_price=-700, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=700)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=700,\n        credit_price=700)\n\n  def testGeneralLedgerProject(self):\n    # general ledger restricted to a project\n    self.createProjectAndFunctionDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'project\'] = self.project_1.getRelativeUrl()\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          Movement_getExplanationTitleAndAnalytics=\'Function a Project 1\\nFaP1\',\n          date=DateTime(2006, 2, 2),\n          debit_price=500, credit_price=0, running_total_price=500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=500, credit_price=0)\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'1\',\n          Movement_getExplanationTitleAndAnalytics=\'Function a Project 1\\nFaP1\',\n          date=DateTime(2006, 2, 2),\n          debit_price=0, credit_price=500, running_total_price=-500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=500)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=500, credit_price=500)\n\n  def testGeneralLedgerLedger(self):\n    # general ledger restricted to a ledger\n    self.createLedgerDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'ledger\'] = \'ledger/accounting/general\'\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getExplanationTitleAndAnalytics=\'Ledger general\\nlag\',\n          date=DateTime(2006, 2, 2),\n          debit_price=500, credit_price=0, running_total_price=500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=500, credit_price=0)\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getExplanationTitleAndAnalytics=\'Ledger general\\nlag\',\n          date=DateTime(2006, 2, 2),\n          debit_price=0, credit_price=500, running_total_price=-500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=500)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=500, credit_price=500)\n\n  def testGeneralLedgerMirrorSectionRole(self):\n    # general ledger restricted to a mirror section role\n    self.createMirrorSectionRoleDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'mirror_section_category_list\'] = [\'role/supplier\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'2\',\n          Movement_getExplanationTitleAndAnalytics=\'Invoice to a supplier\\nIs\',\n          date=DateTime(2006, 2, 2),\n          debit_price=300, credit_price=0, running_total_price=300, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=300, credit_price=0)\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n          Movement_getSpecificReference=\'2\',\n          Movement_getExplanationTitleAndAnalytics=\'Invoice to a supplier\\nIs\',\n          date=DateTime(2006, 2, 2),\n          debit_price=0, credit_price=300, running_total_price=-300, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=300)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=300,\n                             credit_price=300)\n\n  def testGeneralLedgerAtDateLatestTime(self):\n    # general ledger with at_date should include the transactions from that at_date\n    self.createAtDateDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 2, 2)\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTitleAndAnalytics=\'Invoice in the middle of day\\nI\',\n        date=DateTime(2006, 2, 2, 1, 2),\n        debit_price=500, credit_price=0, running_total_price=500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=500, credit_price=0)\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTitleAndAnalytics=\'Invoice in the middle of day\\nI\',\n        date=DateTime(2006, 2, 2, 1, 2),\n        debit_price=0, credit_price=500, running_total_price=-500, )\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=500)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0], debit_price=500,\n                             credit_price=500)\n\n  def testProfitAndLoss(self):\n    # Simple test of profit and loss\n    self.createAccountStatementDataSet(use_two_bank_accounts=1)\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    # for now, we simply check that that the report is rendered with no error\n    # and it produces valid odf\n    from Products.ERP5OOo.tests.utils import Validator\n    odf_validator = Validator()\n    odf = self.portal.account_module.AccountModule_viewProfitAndLossReport()\n    err_list = odf_validator.validate(odf)\n    if err_list:\n      self.fail(\'\'.join(err_list))\n\n\n  def testBalanceSheet(self):\n    # Simple test of balance sheet\n    self.createAccountStatementDataSet(use_two_bank_accounts=1)\n\n    # set request variables and render\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    # for now, we simply check that that the report is rendered with no error\n    # and it produces valid odf\n    from Products.ERP5OOo.tests.utils import Validator\n    odf_validator = Validator()\n    odf = self.portal.account_module.AccountModule_viewBalanceSheetReport()\n    err_list = odf_validator.validate(odf)\n    if err_list:\n      self.fail(\'\'.join(err_list))\n\n  def testOtherPartiesReport(self):\n    # Other parties report\n    account_module = self.portal.account_module\n    self._makeOne(\n              portal_type=\'Accounting Transaction\',\n              title=\'Transaction 1\',\n              source_reference=\'1\',\n              simulation_state=\'delivered\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 1),\n              lines=(dict(source_value=account_module.receivable,\n                          source_debit=100.0),\n                     dict(source_value=account_module.goods_sales,\n                          source_credit=100.0)))\n\n    self._makeOne(\n              portal_type=\'Accounting Transaction\',\n              title=\'Transaction 2\',\n              source_reference=\'2\',\n              simulation_state=\'delivered\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 1, 0, 1),\n              lines=(dict(source_value=account_module.payable,\n                          source_debit=200.0),\n                     dict(source_value=account_module.goods_sales,\n                          source_credit=200.0)))\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2006, 2, 1)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'omit_balanced_accounts\'] = False\n    request_form[\'omit_grouping_reference\'] = True\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountModule_viewOtherPartiesReport\')\n    self.assertEqual(1, len(report_section_list))\n    # the role is displayed in parenthesis\n    self.assertEqual(report_section_list[0].getTitle(),\n                      \'Client 1 (Client)\')\n    # currency is present in the report\n    self.assertEqual(\'currency_module/euro\', self.portal.\n        AccountModule_viewOtherPartiesReport.your_currency.get_value(\'default\'))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n          Movement_getExplanationTitle=\'Transaction 1\',\n          Movement_getExplanationTranslatedPortalType=\'Accounting Transaction\',\n          Movement_getNodeGapId=\'41\',\n          credit_price=0,\n          debit_price=100,\n          date=DateTime(\'2006/02/01\'),\n          getTranslatedSimulationStateTitle=\'Closed\',\n          running_total_price=100.0)\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getExplanationTitle=\'Transaction 2\',\n          Movement_getExplanationTranslatedPortalType=\'Accounting Transaction\',\n          Movement_getNodeGapId=\'40\',\n          credit_price=0,\n          debit_price=200,\n          date=DateTime(2006, 2, 1, 0, 1),\n          getTranslatedSimulationStateTitle=\'Closed\',\n          running_total_price=300.0)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          credit_price=0,\n          debit_price=300,)\n\n  def testOtherPartiesReportLedger(self):\n    # Other parties report with a filter on ledger\n    # This tests works because /for the moment/ any transaction between 2\n    # entities belong to the same ledger\n    self.createLedgerCategory()\n    account_module = self.portal.account_module\n    self._makeOne(\n              portal_type=\'Accounting Transaction\',\n              title=\'Transaction 1\',\n              source_reference=\'1\',\n              simulation_state=\'delivered\',\n              ledger=\'accounting/general\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 1),\n              lines=(dict(source_value=account_module.receivable,\n                          source_debit=100.0),\n                     dict(source_value=account_module.goods_sales,\n                          source_credit=100.0)))\n\n    self._makeOne(\n              portal_type=\'Accounting Transaction\',\n              title=\'Transaction 2\',\n              source_reference=\'2\',\n              simulation_state=\'delivered\',\n              ledger=\'accounting/general\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 1, 0, 1),\n              lines=(dict(source_value=account_module.payable,\n                          source_debit=200.0),\n                     dict(source_value=account_module.goods_sales,\n                          source_credit=200.0)))\n\n    self._makeOne(\n              portal_type=\'Accounting Transaction\',\n              title=\'Transaction 3\',\n              source_reference=\'3\',\n              simulation_state=\'delivered\',\n              ledger=\'accounting/detailed\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 1, 0, 2),\n              lines=(dict(source_value=account_module.payable,\n                          source_debit=400.0),\n                     dict(source_value=account_module.goods_sales,\n                          source_credit=400.0)))\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2006, 2, 1)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'ledger\'] = \'ledger/accounting/general\'\n    request_form[\'omit_balanced_accounts\'] = False\n    request_form[\'omit_grouping_reference\'] = True\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountModule_viewOtherPartiesReport\')\n    self.assertEqual(1, len(report_section_list))\n    # the role is displayed in parenthesis\n    self.assertEqual(report_section_list[0].getTitle(),\n                      \'Client 1 (Client)\')\n    # currency is present in the report\n    self.assertEqual(\'currency_module/euro\', self.portal.\n        AccountModule_viewOtherPartiesReport.your_currency.get_value(\'default\'))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n          Movement_getExplanationTitle=\'Transaction 1\',\n          Movement_getExplanationTranslatedPortalType=\'Accounting Transaction\',\n          Movement_getNodeGapId=\'41\',\n          credit_price=0,\n          debit_price=100,\n          date=DateTime(\'2006/02/01\'),\n          getTranslatedSimulationStateTitle=\'Closed\',\n          running_total_price=100.0)\n\n    self.checkLineProperties(data_line_list[1],\n          Movement_getExplanationTitle=\'Transaction 2\',\n          Movement_getExplanationTranslatedPortalType=\'Accounting Transaction\',\n          Movement_getNodeGapId=\'40\',\n          credit_price=0,\n          debit_price=200,\n          date=DateTime(2006, 2, 1, 0, 1),\n          getTranslatedSimulationStateTitle=\'Closed\',\n          running_total_price=300.0)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n          credit_price=0,\n          debit_price=300,)\n\n  def createAgedBalanceDataSet(self, use_ledger=False):\n    \"\"\"Create data set for aged balance:\n    2013/07/30: Purchase invoice 1 (500)\n    2013/07/30: Sale invoice 2 (300)\n    2013/09/09: Payment 1 (500)\n    2013/08/08: Payment 2 (300)\n    \"\"\"\n    account_module = self.account_module\n    bank1 = self.section.newContent(portal_type=\'Bank Account\', title=\'Bank1\')\n    bank1.validate()\n\n    purchase1 = self._makeOne(\n              portal_type=\'Purchase Invoice Transaction\',\n              title=\'Purchase invoice 1\',\n              destination_reference=\'1\',\n              source_reference=\'no\',\n              reference=\'ref1\',\n              simulation_state=\'delivered\',\n              ledger=(\'\' if not use_ledger else \'accounting/general\'),\n              source_section_value=self.organisation_module.supplier,\n              start_date=DateTime(2013, 7, 30),\n              lines=(dict(destination_value=account_module.goods_purchase,\n                          destination_debit=500.0),\n                     dict(destination_value=account_module.payable,\n                          destination_credit=500.0)))\n    sale2 = self._makeOne(\n              portal_type=\'Sale Invoice Transaction\',\n              title=\'Sale invoice 2\',\n              source_reference=\'2\',\n              destination_reference=\'no\',\n              reference=\'ref2\',\n              simulation_state=\'delivered\',\n              ledger=(\'\' if not use_ledger else \'accounting/general\'),\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2013, 7, 30),\n              lines=(dict(source_value=account_module.goods_sales,\n                          source_credit=300.0),\n                     dict(source_value=account_module.receivable,\n                          source_debit=300.0),))\n    self.tic()\n    payment3 = self._makeOne(\n              portal_type=\'Payment Transaction\',\n              title=\'Payment 1\',\n              source_reference=\'3\',\n              destination_reference=\'no\',\n              simulation_state=\'delivered\',\n              ledger=(\'\' if not use_ledger else \'accounting/general\'),\n              causality_value=purchase1,\n              payment_mode=\'payment_mode\',\n              destination_section_value=self.organisation_module.supplier,\n              start_date=DateTime(2013, 9, 9),\n              lines=(dict(source_value=account_module.payable,\n                          source_debit=500.0),\n                     dict(source_value=account_module.bank,\n                          source_credit=500.0)))\n\n    payment4 = self._makeOne(\n              portal_type=\'Payment Transaction\',\n              title=\'Payment 2\',\n              source_reference=\'4\',\n              destination_reference=\'4\',\n              simulation_state=\'delivered\',\n              causality_value=sale2,\n              payment_mode=\'payment_mode\',\n              ledger=(\'\' if not use_ledger else \'accounting/general\'),\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2013, 8, 8),\n              lines=(dict(source_value=account_module.bank,\n                          source_debit=300.0),\n                     dict(source_value=account_module.receivable,\n                          source_credit=300.0)))\n    self.tic()\n\n    transaction_list = [purchase1, sale2, payment3, payment4]\n\n    if use_ledger:\n      self.createLedgerCategory()\n\n      purchase5 = self._makeOne(\n            portal_type=\'Purchase Invoice Transaction\',\n            title=\'Purchase invoice 3\',\n            destination_reference=\'5\',\n            source_reference=\'no\',\n            reference=\'ref5\',\n            simulation_state=\'delivered\',\n            ledger=\'accounting/detailed\',\n            source_section_value=self.organisation_module.supplier,\n            start_date=DateTime(2013, 7, 30),\n            lines=(dict(destination_value=account_module.goods_purchase,\n                        destination_debit=700.0),\n                   dict(destination_value=account_module.payable,\n                        destination_credit=700.0)))\n      sale6 = self._makeOne(\n                portal_type=\'Sale Invoice Transaction\',\n                title=\'Sale invoice 4\',\n                source_reference=\'5\',\n                destination_reference=\'no\',\n                reference=\'ref6\',\n                simulation_state=\'delivered\',\n                ledger=\'accounting/detailed\',\n                destination_section_value=self.organisation_module.client_1,\n                start_date=DateTime(2013, 7, 30),\n                lines=(dict(source_value=account_module.goods_sales,\n                            source_credit=900.0),\n                       dict(source_value=account_module.receivable,\n                            source_debit=900.0),))\n      self.tic()\n\n      payment7 = self._makeOne(\n          portal_type=\'Payment Transaction\',\n          title=\'Payment 3\',\n          source_reference=\'6\',\n          destination_reference=\'no\',\n          simulation_state=\'delivered\',\n          ledger=\'accounting/detailed\',\n          causality_value=purchase5,\n          payment_mode=\'payment_mode\',\n          destination_section_value=self.organisation_module.supplier,\n          start_date=DateTime(2013, 9, 9),\n          lines=(dict(source_value=account_module.payable,\n                      source_debit=700.0),\n                 dict(source_value=account_module.bank,\n                      source_credit=700.0)))\n      payment8 = self._makeOne(\n              portal_type=\'Payment Transaction\',\n              title=\'Payment 4\',\n              source_reference=\'7\',\n              destination_reference=\'7\',\n              simulation_state=\'delivered\',\n              causality_value=sale6,\n              payment_mode=\'payment_mode\',\n              ledger=\'accounting/detailed\',\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2013, 8, 8),\n              lines=(dict(source_value=account_module.bank,\n                          source_debit=900.0),\n                     dict(source_value=account_module.receivable,\n                          source_credit=900.0)))\n      self.tic()\n\n      transaction_list.extend([purchase5, sale6, payment7, payment8])\n\n    # we should have all receivable and payable lines grouped.\n    for at in transaction_list:\n      for line in at.getMovementList():\n        if line.getSourceValue() in (account_module.receivable,\n                                     account_module.payable) or\\\n      line.getDestinationValue() in (account_module.receivable,\n                                     account_module.payable):\n          self.assertTrue(line.getGroupingReference())\n          self.assertTrue(line.getGroupingDate())\n\n  def test_simple_aged_creditor_report_detailed(self):\n    self.createAgedBalanceDataSet()\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = True\n    request_form[\'account_type\'] = \'account_type/asset/receivable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    report_section_list = self.getReportSectionList(\n                    self.portal.accounting_module,\n                    \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             date=DateTime(2013, 7, 30),\n                             mirror_section_title=\'Client 1\',\n                             portal_type=\'Sale Invoice Transaction\',\n                             explanation_title=\'Sale invoice 2\',\n                             total_price=300,\n                             period_1=300)\n\n  def test_simple_aged_creditor_report_summary(self):\n    self.createAgedBalanceDataSet()\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = False\n    request_form[\'account_type\'] = \'account_type/asset/receivable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    report_section_list = self.getReportSectionList(\n                    self.portal.accounting_module,\n                    \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             mirror_section_title=\'Client 1\',\n                             total_price=300,\n                             period_1=300)\n\n  def test_simple_aged_debtor_report_detailed(self):\n    self.createAgedBalanceDataSet()\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = True\n    request_form[\'account_type\'] = \'account_type/liability/payable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    report_section_list = self.getReportSectionList(\n                    self.portal.accounting_module,\n                    \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             date=DateTime(2013, 7, 30),\n                             mirror_section_title=\'Supplier\',\n                             portal_type=\'Purchase Invoice Transaction\',\n                             explanation_title=\'Purchase invoice 1\',\n                             total_price=500,\n                             period_1=500)\n\n  def test_simple_aged_debtor_report_summary(self):\n    self.createAgedBalanceDataSet()\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = False\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'account_type\'] = \'account_type/liability/payable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    report_section_list = self.getReportSectionList(\n                    self.portal.accounting_module,\n                    \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             mirror_section_title=\'Supplier\',\n                             total_price=500,\n                             period_1=500)\n\n  def test_simple_aged_creditor_with_ledger_report_summary(self):\n    # Same test as above, with a filter on ledger\n    # If ledger works properly, results should be the same as\n    # test_simple_aged_creditor_report_summary\n    self.createAgedBalanceDataSet(use_ledger=True)\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = False\n    request_form[\'account_type\'] = \'account_type/asset/receivable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'ledger\'] = \'ledger/accounting/general\'\n\n    report_section_list = self.getReportSectionList(\n                    self.portal.accounting_module,\n                    \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             mirror_section_title=\'Client 1\',\n                             total_price=300,\n                             period_1=300)\n\n  def test_simple_aged_debtor_with_ledger_report_summary(self):\n    # Same test as above, with a filter on ledger\n    # If ledger works properly, results should be the same as\n    # test_simple_aged_creditor_report_summary\n    self.createAgedBalanceDataSet(use_ledger=True)\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = False\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'account_type\'] = \'account_type/liability/payable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'ledger\'] = \'ledger/accounting/general\'\n\n    report_section_list = self.getReportSectionList(\n                    self.portal.accounting_module,\n                    \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             mirror_section_title=\'Supplier\',\n                             total_price=500,\n                             period_1=500)\n\n  def test_simple_aged_debtor_report_sort_order(self):\n    \"\"\"Check the sort order of aged balance report.\n\n    Lines must be sorted by third party, then by date.\n    \"\"\"\n    zzz_supplier = self.portal.organisation_module.newContent(\n        portal_type=\'Organisation\',\n        title=\'ZZZ Supplier\'\n    )\n    self._makeOne(\n        portal_type=\'Purchase Invoice Transaction\',\n        title=\'Purchase invoice 0\',\n        destination_reference=\'0\',\n        source_reference=\'no\',\n        description=\"This invoice should be last, because lines in aged balance \"\n                    \"are sorted by supplier names.\",\n        reference=\'ref0\',\n        simulation_state=\'delivered\',\n        source_section_value=zzz_supplier,\n        start_date=DateTime(2013, 6, 28),\n        lines=(dict(destination_value=self.portal.account_module.goods_purchase,\n                    destination_debit=300.0),\n               dict(destination_value=self.portal.account_module.payable,\n                    destination_credit=300.0)))\n    self.createAgedBalanceDataSet()\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2013, 8, 1)\n    request_form[\'section_category_strict\'] = False\n    request_form[\'detailed\'] = False\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'account_type\'] = \'account_type/liability/payable\'\n    request_form[\'period_list\'] = (1, 2, 3)\n    request_form[\'simulation_state\'] = [\'delivered\']\n\n    report_section_list = self.getReportSectionList(\n        self.portal.accounting_module,\n        \'AccountingTransactionModule_viewAgedBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             mirror_section_title=\'Supplier\',\n                             total_price=500,\n                             period_1=500)\n    self.checkLineProperties(data_line_list[1],\n                             mirror_section_title=\'ZZZ Supplier\',\n                             total_price=300,\n                             period_3=300)\n\n\nclass TestAccountingReportsWithAnalytic(AccountingTestCase, ERP5ReportTestCase):\n\n  def afterSetUp(self):\n    AccountingTestCase.afterSetUp(self)\n    self.login()\n\n    # change ownership of the preference\n    self.setSubtreeOwner(\n      document_value=self.portal.portal_preferences.accounting_zuite_preference,\n      user=getSecurityManager().getUser(),\n    )\n\n    # create some functions\n    function = self.portal.portal_categories.function\n    if function._getOb(\'a\', None) is None:\n      function.newContent(portal_type=\'Category\', id=\'a\')\n    self.function_a = function[\'a\']\n    if function._getOb(\'b\', None) is None:\n      function.newContent(portal_type=\'Category\', id=\'b\')\n    self.function_b = function[\'b\']\n\n    # create some product lines\n    product_line = self.portal.portal_categories.product_line\n    if product_line._getOb(\'pl1\', None) is None:\n      product_line.newContent(portal_type=\'Category\', id=\'pl1\')\n    self.product_line_1 = product_line[\'pl1\']\n\n    # create some projects\n    self.project_1 = self.portal.project_module.newContent(\n                          portal_type=\'Project\',\n                          reference=\'P1\',\n                          title=\'Project 1\')\n    self.project_2 = self.portal.project_module.newContent(\n                          portal_type=\'Project\',\n                          reference=\'P2\',\n                          title=\'Project 2\')\n\n    preference = self.portal.portal_preferences.getActivePreference()\n    preference._edit(\n        preferred_accounting_transaction_line_function_base_category=\'function\',\n        preferred_accounting_transaction_line_analytic_base_category_list=(\n                                              \'product_line\', ),)\n    account_module = self.portal.account_module\n    uid_list = sorted([\n        self.portal.portal_catalog.newUid(),\n        self.portal.portal_catalog.newUid(),\n        self.portal.portal_catalog.newUid(),])\n\n    self._makeOne(\n              portal_type=\'Sale Invoice Transaction\',\n              title=\'Detailed Transaction\',\n              reference=\'DT\',\n              source_reference=\'1\',\n              simulation_state=\'delivered\',\n              destination_section_value=self.portal.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 2),\n              lines=(dict(source_value=account_module.receivable,\n                          source_debit=1500.0),\n                     dict(source_value=account_module.goods_sales,\n                          uid=uid_list[0],\n                          source_function_value=self.function_a,\n                          source_project_value=self.project_1,\n                          product_line_value=self.product_line_1,\n                          source_credit=300.0),\n                     dict(source_value=account_module.goods_sales,\n                          uid=uid_list[1],\n                          source_function_value=self.function_b,\n                          source_project_value=self.project_1,\n                          product_line_value=self.product_line_1,\n                          source_credit=500.0),\n                     dict(source_value=account_module.goods_sales,\n                          uid=uid_list[2],\n                          source_function_value=self.function_b,\n                          source_project_value=self.project_2,\n                          product_line_value=None,\n                          source_credit=700.0),\n                     ))\n    self.tic()\n    self.loginByUserName(self.username)\n\n  def beforeTearDown(self):\n    AccountingTestCase.beforeTearDown(self)\n    preference = self.portal.portal_preferences.getActivePreference()\n    preference._edit(\n        preferred_accounting_transaction_line_function_base_category=None,\n        preferred_accounting_transaction_line_analytic_base_category_list=())\n    for module_id in (\'project_module\',):\n      module = self.portal[module_id]\n      object_ids = list(module.objectIds())\n      if object_ids:\n        module.manage_delObjects(object_ids)\n    self.commit()\n\n  def testJournalAnalyticsShown(self):\n    self.project_1.validate()\n    self.project_2.validate()\n    self.tic()\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'portal_type\'] = [\'Sale Invoice Transaction\']\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountingTransactionModule_viewJournalReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(4, len(data_line_list))\n\n    # test columns values\n    line = data_line_list[0]\n    self.assertEqual(line.column_id_list,\n        [ \'specific_reference\', \'date\', \'title\', \'parent_reference\',\n          \'function\', \'project\', \'product_line_translated_title\',\n          \'node_title\', \'mirror_section_title\', \'debit\', \'credit\'])\n\n    self.checkLineProperties(data_line_list[0],\n                             project=\'\',\n                             function=None,\n                             product_line_translated_title=None,\n                             node_title=\'41\',\n                             mirror_section_title=\'Client 1\',\n                             debit=1500,\n                             credit=0)\n    self.checkLineProperties(data_line_list[1],\n                             project=\'P1 - Project 1\',\n                             function=\'a\',\n                             product_line_translated_title=\'pl1\',\n                             node_title=\'7\',\n                             debit=0,\n                             credit=300)\n    self.checkLineProperties(data_line_list[2],\n                             project=\'P1 - Project 1\',\n                             function=\'b\',\n                             product_line_translated_title=\'pl1\',\n                             node_title=\'7\',\n                             debit=0,\n                             credit=500)\n    self.checkLineProperties(data_line_list[3],\n                             project=\'P2 - Project 2\',\n                             function=\'b\',\n                             product_line_translated_title=None,\n                             node_title=\'7\',\n                             debit=0,\n                             credit=700)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit=1500, credit=1500)\n\n  def testJournalAnalyticsHidden(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'portal_type\'] = [\'Sale Invoice Transaction\']\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = True\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountingTransactionModule_viewJournalReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(2, len(data_line_list))\n\n    # test columns values\n    line = data_line_list[0]\n    self.assertEqual(line.column_id_list,\n        [\'specific_reference\', \'date\', \'title\', \'parent_reference\',\n          \'node_title\', \'mirror_section_title\', \'debit\', \'credit\'])\n\n    self.checkLineProperties(data_line_list[0],\n                             node_title=\'41\',\n                             mirror_section_title=\'Client 1\',\n                             debit=1500,\n                             credit=0)\n    # this line is the aggregation of 3 lines\n    self.checkLineProperties(data_line_list[1],\n                             node_title=\'7\',\n                             debit=0,\n                             credit=1500)\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit=1500, credit=1500)\n\n  def testAccountStatementAnalyticsShown(self):\n    self.project_1.validate()\n    self.project_2.validate()\n    self.tic()\n    request_form = self.portal.REQUEST.form\n    request_form[\'node\'] = \\\n                self.portal.account_module.goods_sales.getRelativeUrl()\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group/sub1\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountModule_viewAccountStatementReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(3, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n        Movement_getExplanationTitleAndAnalytics=\'\'\'Detailed Transaction\nDT, a, P1 - Project 1, pl1\'\'\',\n        debit_price=0,\n        credit_price=300,\n        running_total_price=-300)\n    self.checkLineProperties(data_line_list[1],\n        Movement_getExplanationTitleAndAnalytics=\'\'\'Detailed Transaction\nDT, b, P1 - Project 1, pl1\'\'\',\n        debit_price=0,\n        credit_price=500,\n        running_total_price=-800)\n    self.checkLineProperties(data_line_list[2],\n        Movement_getExplanationTitleAndAnalytics=\'\'\'Detailed Transaction\nDT, b, P2 - Project 2\'\'\',\n        debit_price=0,\n        credit_price=700,\n        running_total_price=-1500)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=1500)\n\n  def testAccountStatementAnalyticsHidden(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'node\'] = \\\n                self.portal.account_module.goods_sales.getRelativeUrl()\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group/sub1\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = True\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountModule_viewAccountStatementReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n                             debit_price=0,\n                             credit_price=1500,\n                             running_total_price=-1500)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=1500)\n\n  def testAccountStatementAnalyticsExport(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'node\'] = \\\n                self.portal.account_module.goods_sales.getRelativeUrl()\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group/sub1\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = True\n\n    report_section_list = self.getReportSectionList(\n                               self.portal.accounting_module,\n                               \'AccountModule_viewAccountStatementReport\')\n    self.assertEqual(1, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(3, len(data_line_list))\n\n    self.assertEqual(\n        [\'Movement_getNodeGapId\', \'node_translated_title\', \'Movement_getNodeFinancialSectionTitle\',\n        \'section_title\', \'mirror_section_title\', \'date\', \'modification_date\',\n        \'Movement_getSpecificReference\',\n        \'Movement_getExplanationTranslatedPortalType\',\n        \'Movement_getExplanationTitle\', \'Movement_getExplanationReference\',\n        # those are analytics columns\n        \'function\', \'product_line_translated_title\',\n\n        \'debit_price\', \'credit_price\',\n        \'total_price\', \'Movement_getSectionPriceCurrency\', \'debit\', \'credit\',\n        \'total_quantity\', \'resource_reference\', \'Movement_getPaymentTitle\',\n        \'payment_mode_translated_title\', \'grouping_reference\', \'grouping_date\',\n        \'getTranslatedSimulationStateTitle\'],\n        data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0],\n        Movement_getNodeGapId=\'7\',\n        node_translated_title=\'Goods Sales\',\n        Movement_getNodeFinancialSectionTitle=\'Sales Revenues\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'a\',\n        product_line_translated_title=\'pl1\',\n        debit_price=0,\n        credit_price=300,\n        total_price=-300,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=0, credit=300, total_quantity=-300,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    self.checkLineProperties(data_line_list[1],\n        Movement_getNodeGapId=\'7\',\n        node_translated_title=\'Goods Sales\',\n        Movement_getNodeFinancialSectionTitle=\'Sales Revenues\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'b\',\n        product_line_translated_title=\'pl1\',\n        debit_price=0,\n        credit_price=500,\n        total_price=-500,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=0, credit=500, total_quantity=-500,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    self.checkLineProperties(data_line_list[2],\n        Movement_getNodeGapId=\'7\',\n        node_translated_title=\'Goods Sales\',\n        Movement_getNodeFinancialSectionTitle=\'Sales Revenues\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'b\',\n        product_line_translated_title=None,\n        debit_price=0,\n        credit_price=700,\n        total_price=-700,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=0, credit=700, total_quantity=-700,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    # There is no stat line in export\n    self.assertFalse(line_list[-1].isStatLine())\n\n  def testGeneralLedgerAnalyticsShown(self):\n    self.project_1.validate()\n    self.project_2.validate()\n    self.tic()\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual( [\'date\', \'Movement_getSpecificReference\',\n      \'mirror_section_title\', \'Movement_getExplanationTitleAndAnalytics\',\n      \'debit_price\', \'credit_price\', \'running_total_price\',\n      \'grouping_reference\', \'grouping_date\',\n      \'getTranslatedSimulationStateTitle\'],\n        data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0],\n        Movement_getExplanationTitleAndAnalytics=\'\'\'Detailed Transaction\nDT, a, P1 - Project 1, pl1\'\'\',\n        debit_price=0,\n        credit_price=300,\n        running_total_price=-300)\n    self.checkLineProperties(data_line_list[1],\n        Movement_getExplanationTitleAndAnalytics=\'\'\'Detailed Transaction\nDT, b, P1 - Project 1, pl1\'\'\',\n        debit_price=0,\n        credit_price=500,\n        running_total_price=-800)\n    self.checkLineProperties(data_line_list[2],\n        Movement_getExplanationTitleAndAnalytics=\'\'\'Detailed Transaction\nDT, b, P2 - Project 2\'\'\',\n        debit_price=0,\n        credit_price=700,\n        running_total_price=-1500)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=1500)\n\n    line_list = self.getListBoxLineList(report_section_list[2])\n\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n                             debit_price=1500,\n                             credit_price=1500,)\n\n  def testGeneralLedgerAnalyticsHidden(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = True\n    request_form[\'export\'] = False\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    self.assertEqual(3, len(report_section_list))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual( [\'date\', \'Movement_getSpecificReference\', \'mirror_section_title\',\n        \'Movement_getExplanationTitleAndAnalytics\', \'debit_price\',\n        \'credit_price\', \'running_total_price\', \'grouping_reference\',\n        \'grouping_date\', \'getTranslatedSimulationStateTitle\'],\n        data_line_list[0].column_id_list)\n    # receivable account\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n                             debit_price=1500,\n                             credit_price=0,\n                             running_total_price=1500)\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=1500, credit_price=0)\n    # good sales account\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n                             debit_price=0,\n                             credit_price=1500,\n                             running_total_price=-1500)\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1], debit_price=0, credit_price=1500)\n    # summary\n    line_list = self.getListBoxLineList(report_section_list[2])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n    self.checkLineProperties(data_line_list[0],\n                             debit_price=1500,\n                             credit_price=1500,)\n\n  def testGeneralLedgerExport(self):\n    self.project_1.validate()\n    self.project_2.validate()\n    self.tic()\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 12, 31)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'hide_analytic\'] = False\n    request_form[\'export\'] = True\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewGeneralLedgerReport\')\n    # There are two report sections, but in reality they are merged into one\n    self.assertEqual(2, len(report_section_list))\n    # because merge_report_section_list is set to true\n    self.assertTrue(self.portal.REQUEST.get(\'merge_report_section_list\'))\n\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(1, len(data_line_list))\n\n    # all the columns configured in AccountModule_getGeneralLedgerColumnItemList\n    # are displayed\n    self.assertEqual(\n        [\'Movement_getNodeGapId\', \'node_translated_title\', \'Movement_getNodeFinancialSectionTitle\',\n        \'section_title\', \'mirror_section_title\', \'date\', \'modification_date\',\n        \'Movement_getSpecificReference\',\n        \'Movement_getExplanationTranslatedPortalType\',\n        \'Movement_getExplanationTitle\', \'Movement_getExplanationReference\',\n        # those are analytics columns\n        \'function\', \'project\', \'product_line_translated_title\',\n\n        \'debit_price\', \'credit_price\',\n        \'total_price\', \'Movement_getSectionPriceCurrency\', \'debit\', \'credit\',\n        \'total_quantity\', \'resource_reference\', \'Movement_getPaymentTitle\',\n        \'payment_mode_translated_title\', \'grouping_reference\', \'grouping_date\',\n        \'getTranslatedSimulationStateTitle\'],\n        data_line_list[0].column_id_list)\n    self.assertEqual([x[0] for x in\n        self.portal.accounting_module.AccountModule_getGeneralLedgerColumnItemList()],\n        data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0],\n        Movement_getNodeGapId=\'41\',\n        node_translated_title=\'Receivable\',\n        Movement_getNodeFinancialSectionTitle=\'Accounts Receivable\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'\',\n        project=\'\',\n        product_line_translated_title=None,\n        debit_price=1500,\n        credit_price=0,\n        total_price=1500,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=1500, credit=0, total_quantity=1500,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    line_list = self.getListBoxLineList(report_section_list[1])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n    self.assertEqual(3, len(data_line_list))\n\n    self.checkLineProperties(data_line_list[0],\n        Movement_getNodeGapId=\'7\',\n        node_translated_title=\'Goods Sales\',\n        Movement_getNodeFinancialSectionTitle=\'Sales Revenues\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'a\',\n        project=\'P1 - Project 1\',\n        product_line_translated_title=\'pl1\',\n        debit_price=0,\n        credit_price=300,\n        total_price=-300,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=0, credit=300, total_quantity=-300,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    self.checkLineProperties(data_line_list[1],\n        Movement_getNodeGapId=\'7\',\n        node_translated_title=\'Goods Sales\',\n        Movement_getNodeFinancialSectionTitle=\'Sales Revenues\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'b\',\n        project=\'P1 - Project 1\',\n        product_line_translated_title=\'pl1\',\n        debit_price=0,\n        credit_price=500,\n        total_price=-500,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=0, credit=500, total_quantity=-500,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    self.checkLineProperties(data_line_list[2],\n        Movement_getNodeGapId=\'7\',\n        node_translated_title=\'Goods Sales\',\n        Movement_getNodeFinancialSectionTitle=\'Sales Revenues\',\n        section_title=\'My Organisation\',\n        mirror_section_title=\'Client 1\',\n        date=DateTime(2006, 2, 2),\n        Movement_getSpecificReference=\'1\',\n        Movement_getExplanationTranslatedPortalType=\n            \'Sale Invoice Transaction\',\n        Movement_getExplanationTitle=\'Detailed Transaction\',\n        Movement_getExplanationReference=\'DT\',\n        function=\'b\',\n        project=\'P2 - Project 2\',\n        product_line_translated_title=None,\n        debit_price=0,\n        credit_price=700,\n        total_price=-700,\n        Movement_getSectionPriceCurrency=\'EUR\',\n        debit=0, credit=700, total_quantity=-700,\n        resource_reference=\'EUR\',\n        Movement_getPaymentTitle=None,\n        payment_mode_translated_title=None,\n        grouping_reference=None,\n        grouping_date=None,\n        getTranslatedSimulationStateTitle=\'Closed\')\n\n    # There is no stat in export mode\n    self.assertFalse(line_list[-1].isStatLine())\n    # There is not stat section either\n\n  def testTrialBalanceGroupByProject(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'gap_list\'] = [\'my_country/my_accounting_standards/7\']\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'show_detailed_balance_columns\'] = 1\n    request_form[\'group_analytic\'] = [\'project\']\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n\n    self.assertEqual([\'node_id\', \'node_title\', \'project_uid\',\n      \'initial_debit_balance\', \'initial_credit_balance\', \'initial_balance\',\n      \'debit\', \'credit\', \'final_debit_balance\', \'final_credit_balance\',\n      \'final_balance\', \'final_balance_if_debit\', \'final_balance_if_credit\'],\n      data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0], node_id=\'7\',\n        node_title=\'Goods Sales\', project_uid=\'P1 - Project 1\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=800, final_debit_balance=0, final_credit_balance=800,\n        final_balance_if_debit=0, final_balance_if_credit=800)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', project_uid=\'P2 - Project 2\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=700, final_debit_balance=0, final_credit_balance=700,\n        final_balance_if_debit=0, final_balance_if_credit=700)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=1500, final_debit_balance=0, final_credit_balance=1500,\n        final_balance_if_debit=0, final_balance_if_credit=1500)\n\n  def testTrialBalanceGroupByFunction(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'gap_list\'] = [\'my_country/my_accounting_standards/7\']\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'show_detailed_balance_columns\'] = 1\n    request_form[\'group_analytic\'] = [\'function\']\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(2, len(data_line_list))\n\n    self.assertEqual([\'node_id\', \'node_title\', \'function_uid\',\n      \'initial_debit_balance\', \'initial_credit_balance\', \'initial_balance\',\n      \'debit\', \'credit\', \'final_debit_balance\', \'final_credit_balance\',\n      \'final_balance\', \'final_balance_if_debit\', \'final_balance_if_credit\'],\n      data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0], node_id=\'7\',\n        node_title=\'Goods Sales\', function_uid=\'a\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=300, final_debit_balance=0, final_credit_balance=300,\n        final_balance_if_debit=0, final_balance_if_credit=300)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', function_uid=\'b\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=1200, final_debit_balance=0, final_credit_balance=1200,\n        final_balance_if_debit=0, final_balance_if_credit=1200)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=1500, final_debit_balance=0, final_credit_balance=1500,\n        final_balance_if_debit=0, final_balance_if_credit=1500)\n\n  def testTrialBalanceGroupByProjectAndFunction(self):\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'gap_list\'] = [\'my_country/my_accounting_standards/7\']\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'show_detailed_balance_columns\'] = 1\n    request_form[\'group_analytic\'] = [\'function\', \'project\']\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(3, len(data_line_list))\n\n    self.assertEqual([\'node_id\', \'node_title\', \'function_uid\', \'project_uid\',\n      \'initial_debit_balance\', \'initial_credit_balance\', \'initial_balance\',\n      \'debit\', \'credit\', \'final_debit_balance\', \'final_credit_balance\',\n      \'final_balance\', \'final_balance_if_debit\',\n      \'final_balance_if_credit\'], data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0], node_id=\'7\',\n        node_title=\'Goods Sales\', function_uid=\'a\', project_uid=\'P1 - Project 1\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=300, final_debit_balance=0, final_credit_balance=300,\n        final_balance_if_debit=0, final_balance_if_credit=300)\n\n    self.checkLineProperties(data_line_list[1], node_id=\'7\',\n        node_title=\'Goods Sales\', function_uid=\'b\', project_uid=\'P1 - Project 1\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=500, final_debit_balance=0, final_credit_balance=500,\n        final_balance_if_debit=0, final_balance_if_credit=500)\n\n    self.checkLineProperties(data_line_list[2], node_id=\'7\',\n        node_title=\'Goods Sales\', function_uid=\'b\', project_uid=\'P2 - Project 2\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=700, final_debit_balance=0, final_credit_balance=700,\n        final_balance_if_debit=0, final_balance_if_credit=700)\n\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=1500, final_debit_balance=0, final_credit_balance=1500,\n        final_balance_if_debit=0, final_balance_if_credit=1500)\n\n  def testTrialBalanceGroupByProductLine(self):\n    self._makeOne(\n              portal_type=\'Sale Invoice Transaction\',\n              title=\'Noise\',\n              source_reference=\'2\',\n              simulation_state=\'delivered\',\n              destination_section_value=self.portal.organisation_module.client_1,\n              start_date=DateTime(2006, 2, 2),\n              lines=(dict(source_value=self.portal.account_module.receivable,\n                          source_debit=1100.0),\n                     dict(source_value=self.portal.account_module.payable,\n                          source_function_value=self.function_a,\n                          source_project_value=self.project_1,\n                          product_line_value=self.product_line_1,\n                          source_credit=1100.0),))\n\n    request_form = self.portal.REQUEST.form\n    request_form[\'from_date\'] = DateTime(2006, 1, 1)\n    request_form[\'at_date\'] = DateTime(2006, 2, 2)\n    request_form[\'section_category\'] = \'group/demo_group\'\n    request_form[\'section_category_strict\'] = False\n    request_form[\'simulation_state\'] = [\'delivered\']\n    request_form[\'show_empty_accounts\'] = 0\n    request_form[\'expand_accounts\'] = 0\n    request_form[\'gap_list\'] = [\'my_country/my_accounting_standards/7\']\n    request_form[\'per_account_class_summary\'] = 0\n    request_form[\'show_detailed_balance_columns\'] = 1\n    # in the dialog, categories are in the \'_translated_title\' form\n    request_form[\'group_analytic\'] = [\'product_line_translated_title\']\n    self.assertIn(\n        (\'Product Line\', \'product_line_translated_title\'),\n      self.portal.accounting_module.AccountModule_viewTrialBalanceReportDialog\\\n        .your_group_analytic.get_value(\'items\'))\n\n    report_section_list = self.getReportSectionList(\n                                    self.portal.accounting_module,\n                                    \'AccountModule_viewTrialBalanceReport\')\n    self.assertEqual(1, len(report_section_list))\n    line_list = self.getListBoxLineList(report_section_list[0])\n    data_line_list = [l for l in line_list if l.isDataLine()]\n\n    self.assertEqual(1, len(data_line_list))\n\n    self.assertEqual([\'node_id\', \'node_title\', \'strict_product_line_uid\',\n      \'initial_debit_balance\', \'initial_credit_balance\', \'initial_balance\',\n      \'debit\', \'credit\', \'final_debit_balance\', \'final_credit_balance\',\n      \'final_balance\', \'final_balance_if_debit\', \'final_balance_if_credit\'],\n      data_line_list[0].column_id_list)\n\n    self.checkLineProperties(data_line_list[0], node_id=\'7\',\n        node_title=\'Goods Sales\', strict_product_line_uid=\'pl1\',\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=800, final_debit_balance=0, final_credit_balance=800,\n        final_balance_if_debit=0, final_balance_if_credit=800)\n\n    # Lines that does not have a product line are not displayed. This is a\n    # technical limitation, we would have to left join to support this.\n    self.assertTrue(line_list[-1].isStatLine())\n    self.checkLineProperties(line_list[-1],\n        initial_debit_balance=0, initial_credit_balance=0, debit=0,\n        credit=800, final_debit_balance=0, final_credit_balance=800,\n        final_balance_if_debit=0, final_balance_if_credit=800)\n\n\ndef test_suite():\n  suite = unittest.TestSuite()\n  suite.addTest(unittest.makeSuite(TestAccountingReports))\n  suite.addTest(unittest.makeSuite(TestAccountingReportsWithAnalytic))\n  return suite');
INSERT INTO `full_text` VALUES (3448,'test.erp5.testAccounting testAccounting #############################################################################\n#\n# Copyright (c) 2004 Nexedi SARL and Contributors. All Rights Reserved.\n#          Jerome Perrin <jerome@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA 02111-1307, USA.\n#\n##############################################################################\n\n\"\"\"Tests some accounting functionality.\n\n\"\"\"\n\nfrom six import StringIO\nimport lxml\n\nfrom DateTime import DateTime\nfrom Products.CMFCore.utils import _checkPermission\n\nfrom Products.ERP5Type.tests.ERP5TypeTestCase import ERP5TypeTestCase\nfrom Products.ERP5Type.tests.utils import reindex\nfrom Products.ERP5Type.Core.Workflow import ValidationFailed\nfrom AccessControl.SecurityManagement import newSecurityManager\nfrom Products.ERP5Type.tests.Sequence import SequenceList\nfrom Products.ERP5Form.PreferenceTool import Priority\n\nfrom Products.ERP5Type.UnrestrictedMethod import UnrestrictedMethod\n\nSOURCE = \'source\'\nDESTINATION = \'destination\'\nRUN_ALL_TESTS = 1\nQUIET = 1\n\n# Associate transaction portal type to the corresponding line portal type.\ntransaction_to_line_mapping = {\n    \'Accounting Transaction\': \'Accounting Transaction Line\',\n    \'Balance Transaction\': \'Balance Transaction Line\',\n    \'Internal Invoice Transaction\': \'Internal Invoice Transaction Line\',\n    \'Purchase Invoice Transaction\': \'Purchase Invoice Transaction Line\',\n    \'Sale Invoice Transaction\': \'Sale Invoice Transaction Line\',\n    \'Payment Transaction\': \'Accounting Transaction Line\',\n  }\n\n\nclass AccountingTestCase(ERP5TypeTestCase):\n  \"\"\"A test case for all accounting tests.\n\n  Like in erp5_accounting_ui_test, the testing environment is made of:\n\n  Currencies:\n    * currency_module/euro (EUR) with precision 2\n    * currency_module/usd (USD) with precision 2\n    * currency_module/yen (JPY) with precision 0\n\n  Regions:\n    * region/europe/west/france\n\n  Group:\n    * group/demo_group\n    * group/demo_group/sub1\n    * group/demo_group/sub2\n    * group/client\n    * group/vendor\'\n\n  Payment Mode:\n    * payment_mode/cash\n    * payment_mode/check\n\n  Organisations:\n    * `self.section` an organisation using EUR as default currency, without any\n    openned accounting period by default. This organisation is member of\n    group/demo_group/sub1\n    * `self.main_section` an using EUR as default currency, without any\n    openned accounting period by default. This organisation is member of\n    group/demo_group. Both self.main_section and self.section are in the same\n    company from accounting point of view.\n    * self.client_1, self.client_2 & self.supplier, some other organisations\n\n  Accounts:\n      All accounts are associated to a virtual GAP category named \"My Accounting\n    Standards\":\n    * bank\n    * collected_vat\n    * equity\n    * fixed_assets\n    * goods_purchase\n    * goods_sales\n    * payable\n    * receivable\n    * refundable_vat\n    * stocks\n\n  Tests starts with a preference activated for self.my_organisation, logged in\n  as a user with Assignee, Assignor and Author role.\n\n  All documents created appart from this configuration will be deleted in\n  teardown. So users of this test case are encouraged to create new documents\n  rather than modifying default documents.\n  \"\"\"\n\n  username = \'username\'\n  business_process = \'business_process_module/erp5_default_business_process\'\n\n  @reindex\n  def _makeOne(self, portal_type=\'Accounting Transaction\', lines=None,\n               simulation_state=\'draft\', **kw):\n    \"\"\"Creates an accounting transaction, and edit it with kw.\n\n    The default settings is for self.section.\n    You can pass a list of mapping as lines, then lines will be created\n    using this information.\n    \"\"\"\n    created_by_builder = kw.pop(\'created_by_builder\', lines is not None)\n    kw.setdefault(\'start_date\', DateTime())\n    if \'resource_value\' not in kw:\n      kw.setdefault(\'resource\', \'currency_module/euro\')\n    if portal_type in (\'Purchase Invoice Transaction\',\n                       \'Balance Transaction\'):\n      if \'destination_section\' not in kw:\n        kw.setdefault(\'destination_section_value\', self.section)\n    else:\n      if \'source_section\' not in kw:\n        kw.setdefault(\'source_section_value\', self.section)\n    tr = self.accounting_module.newContent(portal_type=portal_type,\n                         created_by_builder=created_by_builder, **kw)\n    if self.business_process and not tr.getSpecialise():\n      tr._setSpecialise(self.business_process)\n    if lines:\n      for line in lines:\n        line.setdefault(\'portal_type\', transaction_to_line_mapping[portal_type])\n        tr.newContent(**line)\n    if simulation_state == \'planned\':\n      tr.plan()\n    elif simulation_state == \'confirmed\':\n      tr.confirm()\n    elif simulation_state in (\'stopped\', \'delivered\'):\n      tr.stop()\n      if simulation_state == \'delivered\':\n        tr.deliver()\n    return tr\n\n  def createUserAndlogin(self, name=username):\n    \"\"\"login with Assignee, Assignor & Author roles.\"\"\"\n    uf = self.getPortal().acl_users\n    uf._doAddUser(self.username, \'\', [\'Assignee\', \'Assignor\', \'Author\'], [])\n    user = uf.getUserById(self.username).__of__(uf)\n    newSecurityManager(None, user)\n\n  def afterSetUp(self):\n    super(AccountingTestCase, self).login()\n    self.account_module = self.portal.account_module\n    self.accounting_module = self.portal.accounting_module\n    self.organisation_module = self.portal.organisation_module\n    self.person_module = self.portal.person_module\n    self.currency_module = self.portal.currency_module\n    self.section = getattr(self.organisation_module, \'my_organisation\', None)\n    self.main_section = getattr(self.organisation_module, \'main_organisation\', None)\n\n    # make sure documents are validated\n    for module in (self.account_module, self.organisation_module,\n                   self.person_module):\n      for doc in module.objectValues():\n        if doc.getValidationState() != \'validated\':\n          doc.validate()\n\n    # and the preference enabled\n    pref = self.portal.portal_preferences._getOb(\n                  \'accounting_zuite_preference\', None)\n    if pref is not None:\n      pref.manage_addLocalRoles(self.username, (\'Auditor\', ))\n      if pref.getPreferenceState() != \'enabled\':\n        pref.enable()\n\n    self.validateRules()\n\n    self.createUserAndlogin(self.username)\n\n    # and all this available to catalog\n    self.tic()\n\n  def beforeTearDown(self):\n    \"\"\"Remove all documents, except the default ones.\n    \"\"\"\n    self.abort()\n    self.login()\n    def delObjects(container, ids):\n      if ids:\n        container.manage_delObjects(ids)\n    delObjects(self.accounting_module, list(self.accounting_module.objectIds()))\n    organisation_list = (\'my_organisation\', \'main_organisation\',\n                         \'client_1\', \'client_2\', \'supplier\')\n    delObjects(\n      self.organisation_module, [x for x in\n          self.organisation_module.objectIds() if x not in organisation_list])\n    for organisation_id in organisation_list:\n      organisation = self.organisation_module._getOb(organisation_id, None)\n      if organisation is not None:\n        delObjects(organisation, [x.getId() for x in\n                organisation.objectValues(\n                  portal_type=(\'Accounting Period\', \'Bank Account\'))])\n    delObjects(\n      self.person_module, [x for x in\n          self.person_module.objectIds() if x not in (\'john_smith\',)])\n    delObjects(\n      self.account_module, [x for x in\n          self.account_module.objectIds() if x not in (\'bank\', \'collected_vat\',\n            \'equity\', \'fixed_assets\', \'goods_purchase\', \'goods_sales\',\n            \'payable\', \'receivable\', \'refundable_vat\', \'stocks\',)])\n    delObjects(self.portal.portal_preferences, [x.getId() for x in\n          self.portal.portal_preferences.objectValues()\n          if x.getId() not in (\'accounting_zuite_preference\', \'default_site_preference\')\n          and x.getPriority() != Priority.SITE])\n    delObjects(self.portal.portal_simulation, list(self.portal.portal_simulation.objectIds()))\n    self.tic()\n\n  def getBusinessTemplateList(self):\n    \"\"\"Returns list of BT to be installed.\"\"\"\n    # note that this test case does *not* install erp5_invoicing, even if it\'s\n    # a dependancy of erp5_accounting_ui_test, because it\'s used to test\n    # standalone accounting and only installs erp5_accounting_ui_test to have\n    # some default content created.\n    return (\'erp5_core_proxy_field_legacy\',\n            \'erp5_base\', \'erp5_pdm\', \'erp5_simulation\', \'erp5_trade\',\n            \'erp5_accounting\', \'erp5_project\',\n            \'erp5_ods_style\',\n            \'erp5_configurator_standard_trade_template\',\n            \'erp5_invoicing\',\n            \'erp5_configurator_standard_accounting_template\',\n            \'erp5_configurator_standard_invoicing_template\',\n            \'erp5_simulation_test\', \'erp5_accounting_ui_test\')\n\n  @UnrestrictedMethod\n  def setUpLedger(self):\n   # Create Ledger Categories\n    ledger_category = self.portal.portal_categories.ledger\n    ledger_accounting_category = ledger_category.get(\'accounting\', None)\n    if ledger_accounting_category is None:\n      ledger_accounting_category = ledger_category.newContent(portal_type=\'Category\', id=\'accounting\')\n    if ledger_accounting_category.get(\'general\', None) is None:\n      ledger_accounting_category.newContent(portal_type=\'Category\', id=\'general\')\n    if ledger_accounting_category.get(\'detailed\', None) is None:\n      ledger_accounting_category.newContent(portal_type=\'Category\', id=\'detailed\')\n    if ledger_accounting_category.get(\'other\', None) is None:\n      ledger_accounting_category.newContent(portal_type=\'Category\', id=\'other\')\n\n    # Allow some ledgers on the \'Sale Invoice Transaction\' portal type\n    self.portal.portal_types[\'Sale Invoice Transaction\'].edit(\n      ledger=[\'accounting/general\', \'accounting/detailed\'])\n\n\n\nclass TestAccounts(AccountingTestCase):\n  \"\"\"Tests Accounts.\n  \"\"\"\n  def test_AccountValidation(self):\n    # Accounts need an account_type category to be valid\n    account = self.portal.account_module.newContent(portal_type=\'Account\')\n    self.assertEqual(\n        [str(m.getMessage()) for m in account.checkConsistency()],\n        [\'Account Type must be set\'])\n    account.setAccountType(\'equity\')\n    self.assertEqual([str(m.getMessage()) for m in account.checkConsistency()], [])\n\n    # non regression: this constraint is also properly verified during workflow\n    account.setAccountType(None)\n    with self.assertRaisesRegex(ValidationFailed, \'Account Type must be set\'):\n      self.portal.portal_workflow.doActionFor(account, \'validate_action\')\n    account.setAccountType(\'equity\')\n    self.portal.portal_workflow.doActionFor(account, \'validate_action\')\n    self.portal.portal_workflow.doActionFor(account, \'invalidate_action\')\n    account.setAccountType(None)\n    with self.assertRaisesRegex(ValidationFailed, \'Account Type must be set\'):\n      self.portal.portal_workflow.doActionFor(account, \'validate_action\')\n\n  def test_AccountWorkflow(self):\n    account = self.portal.account_module.newContent(portal_type=\'Account\')\n    self.assertEqual(\'draft\', account.getValidationState())\n    doActionFor = self.portal.portal_workflow.doActionFor\n    self.assertRaises(ValidationFailed, doActionFor, account,\n                          \'validate_action\')\n    account.setAccountType(\'equity\')\n    account.setGap(\'my_country/my_accounting_standards/1\')\n    doActionFor(account, \'validate_action\')\n    self.assertEqual(\'validated\', account.getValidationState())\n\n  def test_isCreditAccount(self):\n    \"\"\"Tests the \'credit_account\' property on account, which was named\n    is_credit_account, which generated isIsCreditAccount accessor\"\"\"\n    account = self.portal.account_module.newContent(portal_type=\'Account\')\n    # simulate an old object\n    account.is_credit_account = True\n    self.assertTrue(account.isCreditAccount())\n    self.assertTrue(account.getProperty(\'credit_account\'))\n\n    account.setCreditAccount(False)\n    self.assertFalse(account.isCreditAccount())\n\n  def test_ERP5Site_getAccountItemList_cache(self):\n    # added accounts are directly availble\n    account = self.portal.account_module.newContent(\n        portal_type=\'Account\',\n        gap=\'my_country/my_accounting_standards/1\',\n    )\n    account.validate()\n    self.tic()\n    self.assertIn(\n        account.getRelativeUrl(),\n        [x[1] for x in self.portal.ERP5Site_getAccountItemList(\n            section_category=\'\',\n            section_category_strict=False,\n            from_date=None)])\n\n    # changes to validated accounts are also reflected\n    account.setTitle(\'test account\')\n    self.tic()\n    self.assertIn(\n        account.Account_getFormattedTitle(),\n        [x[0] for x in self.portal.ERP5Site_getAccountItemList(\n            section_category=\'\',\n            section_category_strict=False,\n            from_date=None)])\n\n    # invalidated accounts are removed\n    account.invalidate()\n    self.tic()\n    self.assertNotIn(\n        account.getRelativeUrl(),\n        [x[1] for x in self.portal.ERP5Site_getAccountItemList(\n            section_category=\'\',\n            section_category_strict=False,\n            from_date=None)])\n\n  def test_AccountingTransactionLine_getNodeItemList_cache(self):\n    accounting_line = self._makeOne(lines=(dict(id=\'income\'),)).income\n    # added accounts are directly availble\n    account = self.portal.account_module.newContent(\n        portal_type=\'Account\',\n        account_type=\'income\'\n    )\n    account.validate()\n    self.tic()\n    self.assertIn(\n        account.getRelativeUrl(),\n        [x[1] for x in accounting_line.AccountingTransactionLine_getNodeItemList()])\n\n    # changes to validated accounts are also reflected\n    account.setTitle(\'test account\')\n    self.tic()\n    self.assertIn(\n        account.Account_getFormattedTitle(),\n        [x[0] for x in accounting_line.AccountingTransactionLine_getNodeItemList()])\n\n    # invalidated accounts are removed\n    account.invalidate()\n    self.tic()\n    self.assertNotIn(\n        account.getRelativeUrl(),\n        [x[1] for x in accounting_line.AccountingTransactionLine_getNodeItemList()])\n\n\nclass TestTransactionValidation(AccountingTestCase):\n  \"\"\"Test validations of accounting transactions.\n\n  In this test suite, the main section have a closed accounting period for\n  2006, and an open one for 2007.\n  \"\"\"\n  def afterSetUp(self):\n    super(TestTransactionValidation, self).afterSetUp()\n    self.organisation_module = self.portal.organisation_module\n    self.main_section = self.organisation_module.main_organisation\n\n    if \'accounting_period_2006\' not in self.main_section.objectIds():\n      accounting_period_2006 = self.main_section.newContent(\n                                  id=\'accounting_period_2006\',\n                                  portal_type=\'Accounting Period\',\n                                  start_date=DateTime(\'2006/01/01\'),\n                                  stop_date=DateTime(\'2006/12/31\'))\n      accounting_period_2006.start()\n      self.portal.portal_workflow.doActionFor(accounting_period_2006,\n          \'stop_action\',\n          profit_and_loss_account=self.portal.account_module.contentValues()[0].getRelativeUrl())\n      accounting_period_2007 = self.main_section.newContent(\n                                  id=\'accounting_period_2007\',\n                                  portal_type=\'Accounting Period\',\n                                  start_date=DateTime(\'2007/01/01\'),\n                                  stop_date=DateTime(\'2007/12/31\'))\n      accounting_period_2007.start()\n      self.tic()\n\n  def test_SaleInvoiceTransactionValidationDate(self):\n    # Accounting Period Date matters for Sale Invoice Transaction\n    accounting_transaction = self._makeOne(\n               portal_type=\'Sale Invoice Transaction\',\n               start_date=DateTime(\'2006/03/03\'),\n               destination_section_value=self.organisation_module.supplier,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n    # validation is refused, because period is closed\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # in 2007, it\'s OK\n    accounting_transaction.setStartDate(DateTime(\"2007/03/03\"))\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_PurchaseInvoiceTransactionValidationDate(self):\n    # Accounting Period Date matters for Purchase Invoice Transaction\n    accounting_transaction = self._makeOne(\n               portal_type=\'Purchase Invoice Transaction\',\n               stop_date=DateTime(\'2006/03/03\'),\n               source_section_value=self.organisation_module.supplier,\n               lines=(dict(destination_value=self.account_module.goods_purchase,\n                           destination_debit=500),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_credit=500)))\n    # validation is refused, because period is closed\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # in 2007, it\'s OK\n    accounting_transaction.setStopDate(DateTime(\"2007/03/03\"))\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_PaymentTransactionValidationDate(self):\n    # Accounting Period Date matters for Payment Transaction\n    accounting_transaction = self._makeOne(\n               portal_type=\'Payment Transaction\',\n               start_date=DateTime(\'2006/03/03\'),\n               destination_section_value=self.organisation_module.supplier,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n    # validation is refused, because period is closed\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # in 2007, it\'s OK\n    accounting_transaction.setStartDate(DateTime(\"2007/03/03\"))\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_DestinationPaymentTransactionValidationDate(self):\n    # Accounting Period Date matters for Payment Transaction\n    accounting_transaction = self._makeOne(\n               portal_type=\'Payment Transaction\',\n               stop_date=DateTime(\'2006/03/03\'),\n               source_section_value=self.organisation_module.supplier,\n               destination_section_value=self.section,\n               payment_mode=\'default\',\n               lines=(dict(destination_value=self.account_module.goods_purchase,\n                           destination_debit=500),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_credit=500)))\n    # validation is refused, because period is closed\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # in 2007, it\'s OK\n    accounting_transaction.setStopDate(DateTime(\"2007/03/03\"))\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_UnusedSectionTransactionValidationDate(self):\n    # If a section doesn\'t have any accounts on its side, we don\'t check the\n    # accounting period dates\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2006/03/03\'),\n               source_section_value=self.organisation_module.supplier,\n               destination_section_value=self.section,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           destination_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_credit=500)))\n\n    # 2006 is closed for destination_section\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # If we don\'t have accounts on destination side, validating transaction is\n    # not refused\n    for line in accounting_transaction.getMovementList():\n      line.setDestination(None)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_UnusedSectionTransactionValidationDateDestination(self):\n    # If a section doesn\'t have any accounts on its side, we don\'t check the\n    # accounting period dates. Symetric test of test_UnusedSectionTransactionValidationDate\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2006/03/03\'),\n               destination_section_value=self.organisation_module.supplier,\n               source_section_value=self.section,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           destination_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_credit=500)))\n\n    # 2006 is closed for source_section\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # If we don\'t have accounts on source side, validating transaction is\n    # not refused\n    for line in accounting_transaction.getMovementList():\n      line.setSource(None)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_UnusedSectionTransactionValidationDateWithSourceSetOnDelivery(self):\n    # If a section doesn\'t have any accounts on its side, we don\'t check the\n    # accounting period dates\n    # Corner case that a source organisation is set on the transaction.\n    # Acquisition should not be a problem.\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2006/03/03\'),\n               source_section_value=self.organisation_module.supplier,\n               source_value=self.organisation_module.supplier,\n               destination_section_value=self.section,\n               destination_value=self.section,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           destination_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_credit=500)))\n\n    # 2006 is closed for destination_section\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # If we don\'t have accounts on destination side, validating transaction is\n    # not refused\n    for line in accounting_transaction.getMovementList():\n      line.setDestination(None)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_UnusedSectionTransactionValidationDateDestinationWithDestinationSetOnDelivery(self):\n    # If a section doesn\'t have any accounts on its side, we don\'t check the\n    # accounting period dates.\n    # Symetric test of test_UnusedSectionTransactionValidationDateWithSourceSetOnDelivery\n    # Corner case that a destination organisation is set on the transaction.\n    # Acquisition should not be a problem.\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2006/03/03\'),\n               destination_section_value=self.organisation_module.supplier,\n               destination_value=self.organisation_module.supplier,\n               source_section_value=self.section,\n               source_value=self.section,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           destination_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_credit=500)))\n\n    # 2006 is closed for source_section\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # If we don\'t have accounts on source side, validating transaction is\n    # not refused\n    for line in accounting_transaction.getMovementList():\n      line.setSource(None)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_AccountingTransactionValidationStartDate(self):\n    # Check we can/cannot validate at date boundaries of the period\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2006/12/31\'),\n               destination_section_value=self.organisation_module.supplier,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n    # validation is refused, because period is closed\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    accounting_transaction.setStartDate(DateTime(\"2007/01/01\"))\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_AccountingTransactionValidationBeforePeriod(self):\n    # Check we cannot validate before the period\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2003/12/31\'),\n               destination_section_value=self.organisation_module.supplier,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n    # validation is refused, because there are no open period for 2008\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n\n  def test_AccountingTransactionValidationAfterPeriod(self):\n    # Check we cannot validate after the period\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2008/12/31\'),\n               destination_section_value=self.organisation_module.supplier,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n    # validation is refused, because there are no open period for 2008\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n\n  def test_AccountingTransactionValidationRecursivePeriod(self):\n    # Check we can/cannot validate when secondary period exists\n\n    accounting_period_2007 = self.main_section.accounting_period_2007\n    accounting_period_2007_1 = accounting_period_2007.newContent(\n                                portal_type=\'Accounting Period\',\n                                start_date=DateTime(\'2007/01/01\'),\n                                stop_date=DateTime(\'2007/01/31\'),)\n    accounting_period_2007_1.start()\n    accounting_period_2007_1.stop()\n\n    accounting_period_2007_2 = accounting_period_2007.newContent(\n                                portal_type=\'Accounting Period\',\n                                start_date=DateTime(\'2007/02/01\'),\n                                stop_date=DateTime(\'2007/02/28\'),)\n    accounting_period_2007_2.start()\n\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               source_section_value=self.main_section,\n               destination_section_value=self.organisation_module.supplier,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n    # validation is refused, because there are no open period for 2007-01\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # in 2007-02, it\'s OK\n    accounting_transaction.setStartDate(DateTime(\"2007/02/02\"))\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n\n  def test_PaymentTransactionWithEmployee(self):\n    # we have to set bank account if we use an asset/cash/bank account, but not\n    # for our employees\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.person_module.john_smith,\n               payment_mode=\'default\',\n               lines=(dict(source_value=self.account_module.bank,\n                           destination_value=self.account_module.bank,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_credit=500)))\n    # refused because no bank account\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # with validated bank account, it\'s OK\n    bank_account = self.section.newContent(portal_type=\'Bank Account\')\n    bank_account.validate()\n    self.tic()\n    accounting_transaction.setSourcePaymentValue(bank_account)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_PaymentTransactionValidationCheckBankAccountPriceCurrency(self):\n    # we have to declare a transaction with price_currency different from the\n    # bank account\n    bank_account = self.section.newContent(portal_type=\'Bank Account\',\n        price_currency_value=self.currency_module.euro)\n    bank_account.validate()\n    accounting_transaction = self._makeOne(\n               portal_type=\'Payment Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.person_module.john_smith,\n               payment_mode=\'default\',\n               resource_value=self.currency_module.usd,\n               source_payment_value=bank_account,\n               lines=(dict(source_value=self.account_module.bank,\n                           destination_value=self.account_module.bank,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_credit=500)))\n    # refused because bank account currency different from transaction resource\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    # with same currency in bank account and transaction, it\'s OK\n    accounting_transaction.setResourceValue(self.currency_module.euro)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_PaymentTransactionValidationCheckBankAccountValidationState(self):\n    for section, mirror_section in (\n      (self.main_section, self.portal.organisation_module.client_1),\n      (self.main_section, self.portal.person_module.newContent()),\n      # with person member of section\'s group\n      (self.main_section, self.portal.person_module.john_smith),\n      (self.section, self.portal.organisation_module.client_1),\n      (self.main_section, self.portal.person_module.newContent()),\n      (self.main_section, self.section),\n    ):\n      section_bank_account = section.newContent(\n        title=\'section bank account\',\n        portal_type=\'Bank Account\',\n        price_currency_value=self.currency_module.euro)\n      mirror_section_bank_account = mirror_section.newContent(\n        title=\'mirror section bank account\',\n        portal_type=\'Bank Account\',\n        price_currency_value=self.currency_module.euro)\n\n      accounting_transaction = self._makeOne(\n        portal_type=\'Payment Transaction\',\n        start_date=DateTime(\'2007/01/02\'),\n        source_section_value=section,\n        source_payment_value=section_bank_account,\n        destination_section_value=mirror_section,\n        destination_payment_value=mirror_section_bank_account,\n        payment_mode=\'default\',\n        resource_value=self.currency_module.euro,\n        lines=(\n          dict(source_value=self.account_module.bank, source_debit=500),\n          dict(source_value=self.account_module.receivable, source_credit=500)))\n\n      self.assertRaisesRegex(\n        ValidationFailed,\n        \"Bank Account section bank account is invalid.\",\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction,\n        \'stop_action\',\n      )\n      section_bank_account.validate()\n      self.tic()\n\n      self.assertRaisesRegex(\n        ValidationFailed,\n        \"Bank Account mirror section bank account is invalid.\",\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction,\n        \'stop_action\',\n      )\n      mirror_section_bank_account.validate()\n      self.tic()\n\n      self.portal.portal_workflow.doActionFor(\n        accounting_transaction, \'stop_action\')\n\n  def test_PaymentTransactionValidationCheckBankAccountOwner(self):\n    main_section_bank_account = self.main_section.newContent(\n      title=\'main section bank account\',\n      portal_type=\'Bank Account\',\n      price_currency_value=self.currency_module.euro)\n    main_section_bank_account.validate()\n    client_1_bank_account = self.portal.organisation_module.client_1.newContent(\n      title=\'client_1 bank account\',\n      portal_type=\'Bank Account\',\n      price_currency_value=self.currency_module.euro)\n    client_1_bank_account.validate()\n\n    # main_section_bank_account can be used by both main_section and section.\n    for section in self.main_section, self.section:\n      accounting_transaction = self._makeOne(\n        portal_type=\'Payment Transaction\',\n        start_date=DateTime(\'2007/01/02\'),\n        source_section_value=section,\n        source_payment_value=main_section_bank_account,\n        destination_section_value=self.portal.organisation_module.client_1,\n        destination_payment_value=client_1_bank_account,\n        payment_mode=\'default\',\n        resource_value=self.currency_module.euro,\n        lines=(\n          dict(source_value=self.account_module.bank, source_debit=500),\n          dict(source_value=self.account_module.receivable,\n               source_credit=500)))\n      self.portal.portal_workflow.doActionFor(\n        accounting_transaction, \'stop_action\')\n\n    # client_1\'s bank account can only be used with client 1, not with client 2\n    accounting_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      start_date=DateTime(\'2007/01/02\'),\n      source_section_value=self.main_section,\n      source_payment_value=main_section_bank_account,\n      destination_section_value=self.portal.organisation_module.client_2,\n      destination_payment_value=client_1_bank_account,\n      payment_mode=\'default\',\n      resource_value=self.currency_module.euro,\n      lines=(\n        dict(source_value=self.account_module.bank, source_debit=500),\n        dict(source_value=self.account_module.receivable, source_credit=500)))\n    self.assertRaisesRegex(\n      ValidationFailed,\n      \"Bank Account client_1 bank account is invalid.\",\n      self.portal.portal_workflow.doActionFor,\n      accounting_transaction,\n      \'stop_action\',\n    )\n\n  def test_NonBalancedAccountingTransaction(self):\n    # Accounting Transactions have to be balanced to be validated\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.payable,\n                           source_asset_debit=39,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_asset_credit=38.99,\n                           source_credit=500)))\n    # refused because not balanced\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    for line in accounting_transaction.getMovementList():\n      if line.getSourceId() == \'payable\':\n        line.setSourceAssetDebit(38.99)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedDestinationAccountingTransaction(self):\n    # Accounting Transactions have to be balanced to be validated,\n    # also for destination\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           destination_asset_debit=39,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           destination_asset_credit=38.99,\n                           source_credit=500)))\n    # refused because not balanced\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    for line in accounting_transaction.getMovementList():\n      if line.getDestinationId() == \'receivable\':\n        line.setDestinationAssetDebit(38.99)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedDestinationAccountingTransactionNoAccount(self):\n    # Accounting Transactions have to be balanced to be validated,\n    # also for destination\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_asset_debit=39,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           destination_asset_credit=38.99,\n                           source_credit=500)))\n    # This is not balanced but there are no accounts on destination\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    for line in accounting_transaction.getMovementList():\n      if line.getDestinationId() == \'receivable\':\n        line.setDestination(None)\n    # but if there are no accounts defined it\'s not a problem\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedAccountingTransactionSectionOnLines(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.goods_sales,\n                           destination_value=self.account_module.goods_purchase,\n                           destination_section_value=self.organisation_module.client_1,\n                           source_debit=500),\n                      dict(source_value=self.account_module.goods_purchase,\n                           source_credit=500)))\n\n    # This is not balanced for client 1\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n\n    for line in accounting_transaction.getMovementList():\n      line.setDestinationSection(None)\n    self.assertEqual([], accounting_transaction.checkConsistency())\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedAccountingTransactionDifferentSectionOnLines(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.goods_sales,\n                           destination_value=self.account_module.goods_purchase,\n                           destination_section_value=self.organisation_module.client_1,\n                           source_debit=500),\n                      dict(source_value=self.account_module.goods_purchase,\n                           destination_value=self.account_module.goods_sales,\n                           destination_section_value=self.organisation_module.client_2,\n                           source_credit=500)))\n\n    # This is not balanced for client 1 and client 2, but if you look globally,\n    # it looks balanced.\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    self.assertEqual(1, len(accounting_transaction.checkConsistency()),\n                         accounting_transaction.checkConsistency())\n\n    for line in accounting_transaction.getMovementList():\n      line.setDestinationSectionValue(\n          self.organisation_module.client_2)\n\n    self.assertEqual([], accounting_transaction.checkConsistency())\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedAccountingTransactionSectionPersonOnLines(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           destination_value=self.account_module.goods_purchase,\n                           destination_section_value=self.person_module.john_smith,\n                           source_debit=500),\n                      dict(source_value=self.account_module.goods_purchase,\n                           source_credit=500)))\n\n    # This is not balanced for john smith, but as he is a person, it\'s not a\n    # problem\n    self.assertEqual([], accounting_transaction.checkConsistency())\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedSourceAccountingTransactionNoAccountSourceAcquired(self):\n    # Accounting Transactions have to be balanced to be validated,\n    # the constraint should take care that the lines may acquire\n    # a source from the transaction\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               source_value=self.section,\n               resource=\'currency_module/yen\',\n               lines=(dict(destination_value=self.account_module.payable,\n                           source_asset_debit=39,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           source_asset_credit=38.99,\n                           source_credit=500)))\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    for line in accounting_transaction.getMovementList():\n      if line.getSourceId() == \'receivable\':\n        line.setSource(None)\n    # but if there are no accounts defined it\'s not a problem\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedDestinationAccountingTransactionNoAccountDestinationAcquired(self):\n    # Accounting Transactions have to be balanced to be validated,\n    # the constraint should take care that the lines may acquire\n    # a destination from the transaction\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               destination_value=self.organisation_module.client_1,\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_asset_debit=39,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.receivable,\n                           destination_asset_credit=38.99,\n                           source_credit=500)))\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    for line in accounting_transaction.getMovementList():\n      if line.getDestinationId() == \'receivable\':\n        line.setDestination(None)\n    # but if there are no accounts defined it\'s not a problem\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_NonBalancedSourceAccountingTransactionRounding(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               destination_value=self.organisation_module.client_1,\n               resource=\'currency_module/euro\',\n               lines=(dict(source_value=self.account_module.payable,\n                           source_debit=1),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=1/3.0),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=1/3.0),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=1/3.0),))\n    self.assertRaisesRegex(\n        ValidationFailed,\n        \'Transaction is not balanced for\',\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction,\n        \'stop_action\',\n    )\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statSourceDebit(), 1)\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statSourceAssetDebit(), 1)\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statSourceCredit(), 0.99)\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statSourceAssetCredit(), 0.99)\n\n  def test_NonBalancedDestinationAccountingTransactionRounding(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.section,\n               destination_value=self.section,\n               source_section_value=self.organisation_module.client_1,\n               source_value=self.organisation_module.client_1,\n               resource=\'currency_module/euro\',\n               lines=(dict(destination_value=self.account_module.payable,\n                           destination_debit=1),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_credit=1/3.0),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_credit=1/3.0),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_credit=1/3.0),))\n    self.assertRaisesRegex(\n        ValidationFailed,\n        \'Transaction is not balanced for\',\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction,\n        \'stop_action\',\n    )\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statSourceCredit(), 1)\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statDestinationAssetDebit(), 1)\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statSourceDebit(), 0.99)\n    self.assertEqual(accounting_transaction.AccountingTransactionLine_statDestinationAssetCredit(), 0.99)\n\n  def test_AccountingTransactionValidationRefusedWithCategoriesAsSections(self):\n    # Validating a transaction with categories as sections is refused.\n    # See http://wiki.erp5.org/Discussion/AccountingProblems\n    category = self.section.getGroupValue()\n    self.assertNotEqual(category, None)\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               source_section_value=category,\n               destination_section_value=self.organisation_module.client_1,\n               resource=\'currency_module/yen\',\n               lines=(dict(source_value=self.account_module.payable,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n    accounting_transaction.setSourceSectionValue(self.section)\n    accounting_transaction.setDestinationSectionValue(category)\n    self.assertRaises(ValidationFailed,\n        self.portal.portal_workflow.doActionFor,\n        accounting_transaction, \'stop_action\')\n\n    accounting_transaction.setDestinationSectionValue(self.organisation_module.client_1)\n    self.portal.portal_workflow.doActionFor(accounting_transaction, \'stop_action\')\n\n  def test_AccountingWorkflow(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           source_credit=500)))\n\n    doActionFor = self.portal.portal_workflow.doActionFor\n    self.assertEqual(\'draft\', accounting_transaction.getSimulationState())\n    self.assertTrue(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'plan_action\')\n    self.assertEqual(\'planned\', accounting_transaction.getSimulationState())\n    self.assertTrue(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'confirm_action\')\n    self.assertEqual(\'confirmed\', accounting_transaction.getSimulationState())\n    self.assertTrue(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'start_action\')\n    self.assertEqual(\'started\', accounting_transaction.getSimulationState())\n    self.assertTrue(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n    self.assertFalse(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'restart_action\')\n    self.assertEqual(\'started\', accounting_transaction.getSimulationState())\n    self.assertTrue(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n    self.assertFalse(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    doActionFor(accounting_transaction, \'deliver_action\')\n    self.assertEqual(\'delivered\', accounting_transaction.getSimulationState())\n    self.assertFalse(_checkPermission(\'Modify portal content\',\n      accounting_transaction))\n\n    another_accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           source_credit=500)))\n\n    doActionFor(another_accounting_transaction, \'cancel_action\')\n    self.assertEqual(\'cancelled\', another_accounting_transaction.getSimulationState())\n    self.assertTrue(_checkPermission(\'Modify portal content\',\n      another_accounting_transaction))\n\n  def test_UneededSourceAssetPrice(self):\n    # It is refunsed to validate an accounting transaction if lines have an\n    # asset price but the resource is the same as the accounting resource\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           source_debit=500,\n                           source_asset_debit=600),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500,\n                           source_asset_credit=600)))\n\n    section = accounting_transaction.getSourceSectionValue()\n    self.assertEqual(section.getPriceCurrency(),\n                      accounting_transaction.getResource())\n\n    # validation is refused\n    doActionFor = self.portal.portal_workflow.doActionFor\n    self.assertRaises(ValidationFailed, doActionFor, accounting_transaction,\n                      \'stop_action\')\n    # and the source conversion tab is visible\n    self.assertTrue(\n        accounting_transaction.AccountingTransaction_isSourceCurrencyConvertible())\n\n    # if asset price is set to the same value as quantity, validation is\n    # allowed\n    for line in accounting_transaction.getMovementList():\n      if line.getSourceValue() == self.account_module.payable:\n        line.setSourceAssetDebit(line.getSourceDebit())\n      elif line.getSourceValue() == self.account_module.receivable:\n        line.setSourceAssetCredit(line.getSourceCredit())\n      else:\n        self.fail(\'wrong line ?\')\n    doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n\n\n  def test_UneededDestinationAssetPrice(self):\n    # It is refunsed to validate an accounting transaction if lines have an\n    # asset price but the resource is the same as the accounting resource\n    accounting_transaction = self._makeOne(\n               portal_type=\'Purchase Invoice Transaction\',\n               stop_date=DateTime(\'2007/01/02\'),\n               source_section_value=self.organisation_module.client_1,\n               lines=(dict(destination_value=self.account_module.payable,\n                           destination_debit=500,\n                           destination_asset_debit=600),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_credit=500,\n                           destination_asset_credit=600)))\n\n    section = accounting_transaction.getDestinationSectionValue()\n    self.assertEqual(section.getPriceCurrency(),\n                      accounting_transaction.getResource())\n\n    # validation is refused\n    doActionFor = self.portal.portal_workflow.doActionFor\n    self.assertRaises(ValidationFailed, doActionFor, accounting_transaction,\n                      \'stop_action\')\n    # and the destination conversion tab is visible\n    self.assertTrue(\n        accounting_transaction.AccountingTransaction_isDestinationCurrencyConvertible())\n\n    # if asset price is set to the same value as quantity, validation is\n    # allowed\n    for line in accounting_transaction.getMovementList():\n      if line.getDestinationValue() == self.account_module.payable:\n        line.setDestinationAssetDebit(line.getDestinationDebit())\n      elif line.getDestinationValue() == self.account_module.receivable:\n        line.setDestinationAssetCredit(line.getDestinationCredit())\n      else:\n        self.fail(\'wrong line ?\')\n\n    doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n\n  def test_CancellationAmount(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           source_debit=-500,\n                           cancellation_amount=True\n                           )))\n\n    self.assertEqual([], accounting_transaction.checkConsistency())\n    self.portal.portal_workflow.doActionFor(accounting_transaction,\n                                            \'stop_action\')\n\n  def test_AccountingTransaction_checkConsistency(self):\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2008/12/31\'),\n               destination_section_value=self.organisation_module.supplier,\n               lines=(dict(id=\'line_with_wrong_quantity\',\n                           source_value=self.account_module.goods_purchase,\n                           source_debit=400),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=500)))\n\n    self.assertRaisesRegex(\n      ValidationFailed,\n      \'Transaction is not balanced\',\n      accounting_transaction.AccountingTransaction_checkConsistency,\n    )\n\n    accounting_transaction.line_with_wrong_quantity.setSourceDebit(500)\n    self.assertRaisesRegex(\n      ValidationFailed,\n      \'Date is not in a started Accounting Period\',\n      accounting_transaction.AccountingTransaction_checkConsistency,\n    )\n\n    accounting_transaction.setStartDate(DateTime(\'2007/11/11\'))\n    accounting_transaction.AccountingTransaction_checkConsistency()\n\n\nclass TestClosingPeriod(AccountingTestCase):\n  \"\"\"Various tests for closing the period.\n  \"\"\"\n  def test_createBalanceOnNode(self):\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Accounting Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.equity,\n                    source_debit=500),\n               dict(source_value=self.account_module.stocks,\n                    source_credit=500)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Accounting Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.stocks,\n                    source_debit=100),\n               dict(source_value=self.account_module.goods_purchase,\n                    source_credit=100)))\n\n    period.AccountingPeriod_createBalanceTransaction(\n                               profit_and_loss_account=None)\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(3, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n\n    # this should create a balance with 3 lines,\n    #   equity = 500 D\n    #   stocks =     400 C\n    #   pl     =     100 C\n    self.assertEqual(self.section,\n                      balance_transaction.getDestinationSectionValue())\n    self.assertEqual(None,\n                      balance_transaction.getSourceSection())\n    self.assertEqual([period], balance_transaction.getCausalityValueList())\n    self.assertEqual(DateTime(2007, 1, 1),\n                      balance_transaction.getStartDate())\n    self.assertEqual(\'currency_module/euro\',\n                      balance_transaction.getResource())\n    self.assertEqual(\'delivered\', balance_transaction.getSimulationState())\n    movement_list = balance_transaction.getMovementList()\n    self.assertEqual(3, len(movement_list))\n\n    equity_movement_list = [m for m in movement_list\n          if m.getDestinationValue() == self.account_module.equity]\n    self.assertEqual(1, len(equity_movement_list))\n    equity_movement = equity_movement_list[0]\n    self.assertEqual([], equity_movement.getValueList(\'resource\'))\n    self.assertEqual([], equity_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, equity_movement.getSource())\n    self.assertEqual(None, equity_movement.getSourceSection())\n    self.assertEqual(None, equity_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, equity_movement.getSourceTotalAssetPrice())\n    self.assertEqual(500., equity_movement.getDestinationDebit())\n\n    stock_movement_list = [m for m in movement_list\n          if m.getDestinationValue() == self.account_module.stocks]\n    self.assertEqual(1, len(stock_movement_list))\n    stock_movement = stock_movement_list[0]\n    self.assertEqual([], stock_movement.getValueList(\'resource\'))\n    self.assertEqual([], stock_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, stock_movement.getSource())\n    self.assertEqual(None, stock_movement.getSourceSection())\n    self.assertEqual(None, stock_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, stock_movement.getSourceTotalAssetPrice())\n    self.assertEqual(400., stock_movement.getDestinationCredit())\n\n    pl_movement_list = [m for m in movement_list\n                        if m.getDestinationValue() is None]\n    self.assertEqual(1, len(pl_movement_list))\n    pl_movement = pl_movement_list[0]\n    self.assertEqual([], pl_movement.getValueList(\'resource\'))\n    self.assertEqual([], pl_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, pl_movement.getSource())\n    self.assertEqual(None, pl_movement.getSourceSection())\n    self.assertEqual(None, pl_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, pl_movement.getSourceTotalAssetPrice())\n    self.assertEqual(100., pl_movement.getDestinationCredit())\n\n\n  def test_createBalanceOnMirrorSection(self):\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=100)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        destination_section_value=organisation_module.client_2,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=200),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=200)))\n\n    period.AccountingPeriod_createBalanceTransaction(\n                             profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(3, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n\n    # this should create a balance with 3 lines,\n    #   pl                 = 300 D\n    #   receivable/client1 =     200 C\n    #   receivable/client2 =     100 C\n    self.assertEqual(self.section,\n                      balance_transaction.getDestinationSectionValue())\n    self.assertEqual(None, balance_transaction.getSourceSection())\n    self.assertEqual(DateTime(2007, 1, 1),\n                      balance_transaction.getStartDate())\n    self.assertEqual(\'currency_module/euro\',\n                      balance_transaction.getResource())\n    self.assertEqual(\'delivered\', balance_transaction.getSimulationState())\n    movement_list = balance_transaction.getMovementList()\n    self.assertEqual(3, len(movement_list))\n\n    client1_movement_list = [m for m in movement_list\n     if m.getSourceSectionValue() == organisation_module.client_1]\n    self.assertEqual(1, len(client1_movement_list))\n    client1_movement = client1_movement_list[0]\n    self.assertEqual([], client1_movement.getValueList(\'resource\'))\n    self.assertEqual([], client1_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, client1_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      client1_movement.getDestinationValue())\n    self.assertEqual(organisation_module.client_1,\n                      client1_movement.getSourceSectionValue())\n    self.assertEqual(None, client1_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, client1_movement.getSourceTotalAssetPrice())\n    self.assertEqual(100., client1_movement.getDestinationCredit())\n\n    client2_movement_list = [m for m in movement_list\n     if m.getSourceSectionValue() == organisation_module.client_2]\n    self.assertEqual(1, len(client2_movement_list))\n    client2_movement = client2_movement_list[0]\n    self.assertEqual([], client2_movement.getValueList(\'resource\'))\n    self.assertEqual([], client2_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, client2_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      client2_movement.getDestinationValue())\n    self.assertEqual(organisation_module.client_2,\n                      client2_movement.getSourceSectionValue())\n    self.assertEqual(None, client2_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, client2_movement.getSourceTotalAssetPrice())\n    self.assertEqual(200., client2_movement.getDestinationCredit())\n\n    pl_movement_list = [m for m in movement_list\n                        if m.getDestinationValue() == pl]\n    self.assertEqual(1, len(pl_movement_list))\n    pl_movement = pl_movement_list[0]\n    self.assertEqual([], pl_movement.getValueList(\'resource\'))\n    self.assertEqual(None, pl_movement.getSource())\n    self.assertEqual(pl,\n                      pl_movement.getDestinationValue())\n    self.assertEqual(None,\n                      pl_movement.getSourceSection())\n    self.assertEqual(None, pl_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, pl_movement.getSourceTotalAssetPrice())\n    self.assertEqual(300., pl_movement.getDestinationDebit())\n    self.tic()\n\n  def test_createBalanceOnPayment(self):\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    bank1 = self.section.newContent(\n                    id=\'bank1\', reference=\'bank1\',\n                    portal_type=\'Bank Account\')\n    bank2 = self.section.newContent(\n                    id=\'bank2\', reference=\'bank2\',\n                    portal_type=\'Bank Account\')\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        destination_section_value=organisation_module.client_1,\n        source_payment_value=bank1,\n        title=\'bank 1\',\n        portal_type=\'Payment Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.receivable,\n                    source_debit=100),\n               dict(source_value=self.account_module.bank,\n                    source_credit=100)))\n\n    # we are destination on this one\n    self._makeOne(\n        stop_date=DateTime(2006, 1, 2),\n        destination_section_value=self.section,\n        destination_payment_value=bank2,\n        source_section_value=organisation_module.client_2,\n        title=\'bank 2\',\n        portal_type=\'Payment Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(destination_value=self.account_module.bank,\n                    destination_debit=200),\n               dict(destination_value=self.account_module.goods_purchase,\n                    destination_credit=200)))\n\n    period.AccountingPeriod_createBalanceTransaction(\n                             profit_and_loss_account=None)\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(3, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n\n    # this should create a balance with 4 lines,\n    #   receivable/client_1 = 100 D\n    #   bank/bank1          =     100 C\n    #   bank/bank2          = 200 D\n    #   pl                  =     200 C\n\n    self.assertEqual(self.section,\n                      balance_transaction.getDestinationSectionValue())\n    self.assertEqual(None,\n                      balance_transaction.getSourceSection())\n    self.assertEqual([period], balance_transaction.getCausalityValueList())\n    self.assertEqual(DateTime(2007, 1, 1),\n                      balance_transaction.getStartDate())\n    self.assertEqual(\'currency_module/euro\',\n                      balance_transaction.getResource())\n    self.assertEqual(\'delivered\', balance_transaction.getSimulationState())\n    movement_list = balance_transaction.getMovementList()\n    self.assertEqual(4, len(movement_list))\n\n    receivable_movement_list = [m for m in movement_list\n        if m.getDestinationValue() == self.account_module.receivable]\n    self.assertEqual(1, len(receivable_movement_list))\n    receivable_movement = receivable_movement_list[0]\n    self.assertEqual([], receivable_movement.getValueList(\'resource\'))\n    self.assertEqual(None, receivable_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      receivable_movement.getDestinationValue())\n    self.assertEqual(self.organisation_module.client_1,\n                      receivable_movement.getSourceSectionValue())\n    self.assertEqual(None, receivable_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, receivable_movement.getSourceTotalAssetPrice())\n    self.assertEqual(100., receivable_movement.getDestinationDebit())\n\n    bank1_movement_list = [m for m in movement_list\n                       if m.getDestinationPaymentValue() == bank1]\n    self.assertEqual(1, len(bank1_movement_list))\n    bank1_movement = bank1_movement_list[0]\n    self.assertEqual([], bank1_movement.getValueList(\'resource\'))\n    self.assertEqual(None, bank1_movement.getSource())\n    self.assertEqual(self.account_module.bank,\n                      bank1_movement.getDestinationValue())\n    self.assertEqual(bank1,\n                      bank1_movement.getDestinationPaymentValue())\n    self.assertEqual(None,\n                      bank1_movement.getSourceSectionValue())\n    self.assertEqual(None, bank1_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, bank1_movement.getSourceTotalAssetPrice())\n    self.assertEqual(100., bank1_movement.getDestinationCredit())\n\n    bank2_movement_list = [m for m in movement_list\n                         if m.getDestinationPaymentValue() == bank2]\n    self.assertEqual(1, len(bank2_movement_list))\n    bank2_movement = bank2_movement_list[0]\n    self.assertEqual([], bank2_movement.getValueList(\'resource\'))\n    self.assertEqual(None, bank2_movement.getSource())\n    self.assertEqual(self.account_module.bank,\n                      bank2_movement.getDestinationValue())\n    self.assertEqual(bank2,\n                      bank2_movement.getDestinationPaymentValue())\n    self.assertEqual(None,\n                      bank2_movement.getSourceSectionValue())\n    self.assertEqual(None, bank2_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, bank2_movement.getSourceTotalAssetPrice())\n    self.assertEqual(200., bank2_movement.getDestinationDebit())\n\n    pl_movement_list = [m for m in movement_list\n                         if m.getDestination() is None]\n    self.assertEqual(1, len(pl_movement_list))\n    pl_movement = pl_movement_list[0]\n    self.assertEqual([], pl_movement.getValueList(\'resource\'))\n    self.assertEqual(None, pl_movement.getSource())\n    self.assertEqual(None, pl_movement.getDestination())\n    self.assertEqual(None, pl_movement.getDestinationPaymentValue())\n    self.assertEqual(None, pl_movement.getSourceSectionValue())\n    self.assertEqual(None, pl_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, pl_movement.getSourceTotalAssetPrice())\n    self.assertEqual(200., pl_movement.getDestinationCredit())\n\n  def test_createBalanceOnLedgerWithTransactionsWithNoLedger(self):\n    self.setUpLedger()\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    pl = self.portal.account_module.newContent(\n          portal_type=\'Account\',\n          account_type=\'equity\')\n\n    # 2 Transactions for clients 1 and 2 on ledger accounting/general\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/general\',\n        destination_section_value=organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=100)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/general\',\n        destination_section_value=organisation_module.client_2,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=200),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=200)))\n\n    # 2 Transactions for clients 1 and 2 on ledger accounting/detailed\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/detailed\',\n        destination_section_value=organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=400),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=400)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/detailed\',\n        destination_section_value=organisation_module.client_2,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=800),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=800)))\n\n    # 2 Transactions for clients 1 and 2 with no ledger\n    transaction5 = self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        destination_section_value=organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=1600),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=1600)))\n    transaction5.setLedger(None)\n\n    transaction6 = self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Sale Invoice Transaction\',\n        destination_section_value=organisation_module.client_2,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=3200),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=3200)))\n    transaction6.setLedger(None)\n\n    self.tic()\n\n    period.AccountingPeriod_createBalanceTransaction(\n                               profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(9, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(3, len(balance_transaction_list))\n\n    # 1st balance has 3 lines :           # 2nd balance has 3 lines :\n    #   on ledger/accounting/general      #   on ledger/accounting/detailed\n    #   pl                 = 300 D        #   pl                 = 1200 D\n    #   receivable/client1 =      200 C   #   receivable/client1 =       800 C\n    #   receivable/client2 =      100 C   #   receivable/client2 =       400 C\n    # 3rd balance has 3 lines :\n    #   on no ledger\n    #   pl                 = 4800 D\n    #   receivable/client1 =       3200 C\n    #   receivable/client2 =       1600 C\n\n    result_mapping = {}\n    result_mapping[\'accounting/general\'] = {\'client1\': 100., \'client2\': 200., \'pl\': 300.}\n    result_mapping[\'accounting/detailed\'] = {\'client1\': 400., \'client2\': 800., \'pl\': 1200.}\n    result_mapping[None] = {\'client1\': 1600., \'client2\': 3200., \'pl\': 4800.}\n\n    for balance_transaction in balance_transaction_list:\n\n      self.assertEqual(self.section,\n                       balance_transaction.getDestinationSectionValue())\n      self.assertEqual(None, balance_transaction.getSourceSection())\n      self.assertEqual(DateTime(2007, 1, 1),\n                       balance_transaction.getStartDate())\n      self.assertEqual(\'currency_module/euro\',\n                       balance_transaction.getResource())\n      self.assertEqual(\'delivered\', balance_transaction.getSimulationState())\n      movement_list = balance_transaction.getMovementList()\n      self.assertEqual(3, len(movement_list))\n\n      current_ledger = balance_transaction.getLedger()\n      assert current_ledger in (None, \'accounting/general\', \'accounting/detailed\')\n      result = result_mapping[current_ledger]\n\n      client1_movement_list = [m for m in movement_list\n       if m.getSourceSectionValue() == organisation_module.client_1]\n      self.assertEqual(1, len(client1_movement_list))\n      client1_movement = client1_movement_list[0]\n      self.assertEqual([], client1_movement.getValueList(\'resource\'))\n      self.assertEqual([], client1_movement.getValueList(\'destination_section\'))\n      self.assertEqual(None, client1_movement.getSource())\n      self.assertEqual(self.account_module.receivable,\n                        client1_movement.getDestinationValue())\n      self.assertEqual(organisation_module.client_1,\n                        client1_movement.getSourceSectionValue())\n      self.assertEqual(None, client1_movement.getDestinationTotalAssetPrice())\n      self.assertEqual(None, client1_movement.getSourceTotalAssetPrice())\n      self.assertEqual(result[\'client1\'], client1_movement.getDestinationCredit())\n\n      client2_movement_list = [m for m in movement_list\n       if m.getSourceSectionValue() == organisation_module.client_2]\n      self.assertEqual(1, len(client2_movement_list))\n      client2_movement = client2_movement_list[0]\n      self.assertEqual([], client2_movement.getValueList(\'resource\'))\n      self.assertEqual([], client2_movement.getValueList(\'destination_section\'))\n      self.assertEqual(None, client2_movement.getSource())\n      self.assertEqual(self.account_module.receivable,\n                        client2_movement.getDestinationValue())\n      self.assertEqual(organisation_module.client_2,\n                        client2_movement.getSourceSectionValue())\n      self.assertEqual(None, client2_movement.getDestinationTotalAssetPrice())\n      self.assertEqual(None, client2_movement.getSourceTotalAssetPrice())\n      self.assertEqual(result[\'client2\'], client2_movement.getDestinationCredit())\n\n      pl_movement_list = [m for m in movement_list\n                          if m.getDestinationValue() == pl]\n      self.assertEqual(1, len(pl_movement_list))\n      pl_movement = pl_movement_list[0]\n      self.assertEqual([], pl_movement.getValueList(\'resource\'))\n      self.assertEqual(None, pl_movement.getSource())\n      self.assertEqual(pl,\n                        pl_movement.getDestinationValue())\n      self.assertEqual(None,\n                        pl_movement.getSourceSection())\n      self.assertEqual(None, pl_movement.getDestinationTotalAssetPrice())\n      self.assertEqual(None, pl_movement.getSourceTotalAssetPrice())\n      self.assertEqual(result[\'pl\'], pl_movement.getDestinationDebit())\n      self.tic()\n\n  def test_createBalanceOnLedgerWithAllTransactionsWithLedger(self):\n    self.setUpLedger()\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    pl = self.portal.account_module.newContent(\n          portal_type=\'Account\',\n          account_type=\'equity\')\n\n    # 2 Transactions for clients 1 and 2 on ledger accounting/general\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/general\',\n        destination_section_value=organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=100)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/general\',\n        destination_section_value=organisation_module.client_2,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=200),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=200)))\n\n    # 2 Transactions for clients 1 and 2 on ledger accounting/detailed\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/detailed\',\n        destination_section_value=organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=400),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=400)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Sale Invoice Transaction\',\n        ledger=\'accounting/detailed\',\n        destination_section_value=organisation_module.client_2,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=800),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=800)))\n\n    period.AccountingPeriod_createBalanceTransaction(\n                               profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(6, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(2, len(balance_transaction_list))\n\n    # 1st balance has 3 lines :           # 2nd balance has 3 lines :\n    #   on ledger/accounting/general      #   on ledger/accounting/detailed\n    #   pl                 = 300 D        #   pl                 = 1200 D\n    #   receivable/client1 =      200 C   #   receivable/client1 =       800 C\n    #   receivable/client2 =      100 C   #   receivable/client2 =       400 C\n\n    result_mapping = {}\n    result_mapping[\'accounting/general\'] = {\'client1\': 100., \'client2\': 200., \'pl\': 300.}\n    result_mapping[\'accounting/detailed\'] = {\'client1\': 400., \'client2\': 800., \'pl\': 1200.}\n\n    for balance_transaction in balance_transaction_list:\n\n      self.assertEqual(self.section,\n                       balance_transaction.getDestinationSectionValue())\n      self.assertEqual(None, balance_transaction.getSourceSection())\n      self.assertEqual(DateTime(2007, 1, 1),\n                       balance_transaction.getStartDate())\n      self.assertEqual(\'currency_module/euro\',\n                       balance_transaction.getResource())\n      self.assertEqual(\'delivered\', balance_transaction.getSimulationState())\n      movement_list = balance_transaction.getMovementList()\n      self.assertEqual(3, len(movement_list))\n\n      current_ledger = balance_transaction.getLedger()\n      assert current_ledger in (\'accounting/general\', \'accounting/detailed\')\n      result = result_mapping[current_ledger]\n\n      client1_movement_list = [m for m in movement_list\n       if m.getSourceSectionValue() == organisation_module.client_1]\n      self.assertEqual(1, len(client1_movement_list))\n      client1_movement = client1_movement_list[0]\n      self.assertEqual([], client1_movement.getValueList(\'resource\'))\n      self.assertEqual([], client1_movement.getValueList(\'destination_section\'))\n      self.assertEqual(None, client1_movement.getSource())\n      self.assertEqual(self.account_module.receivable,\n                        client1_movement.getDestinationValue())\n      self.assertEqual(organisation_module.client_1,\n                        client1_movement.getSourceSectionValue())\n      self.assertEqual(None, client1_movement.getDestinationTotalAssetPrice())\n      self.assertEqual(None, client1_movement.getSourceTotalAssetPrice())\n      self.assertEqual(result[\'client1\'], client1_movement.getDestinationCredit())\n\n      client2_movement_list = [m for m in movement_list\n       if m.getSourceSectionValue() == organisation_module.client_2]\n      self.assertEqual(1, len(client2_movement_list))\n      client2_movement = client2_movement_list[0]\n      self.assertEqual([], client2_movement.getValueList(\'resource\'))\n      self.assertEqual([], client2_movement.getValueList(\'destination_section\'))\n      self.assertEqual(None, client2_movement.getSource())\n      self.assertEqual(self.account_module.receivable,\n                        client2_movement.getDestinationValue())\n      self.assertEqual(organisation_module.client_2,\n                        client2_movement.getSourceSectionValue())\n      self.assertEqual(None, client2_movement.getDestinationTotalAssetPrice())\n      self.assertEqual(None, client2_movement.getSourceTotalAssetPrice())\n      self.assertEqual(result[\'client2\'], client2_movement.getDestinationCredit())\n\n      pl_movement_list = [m for m in movement_list\n                          if m.getDestinationValue() == pl]\n      self.assertEqual(1, len(pl_movement_list))\n      pl_movement = pl_movement_list[0]\n      self.assertEqual([], pl_movement.getValueList(\'resource\'))\n      self.assertEqual(None, pl_movement.getSource())\n      self.assertEqual(pl,\n                        pl_movement.getDestinationValue())\n      self.assertEqual(None,\n                        pl_movement.getSourceSection())\n      self.assertEqual(None, pl_movement.getDestinationTotalAssetPrice())\n      self.assertEqual(None, pl_movement.getSourceTotalAssetPrice())\n      self.assertEqual(result[\'pl\'], pl_movement.getDestinationDebit())\n      self.tic()\n\n    def testStockTableContent():\n      q = self.portal.erp5_sql_connection.manage_test\n      self.assertEqual(2, q(\n        \"SELECT count(*) FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\'\")[0][0])\n      self.assertEqual(300, q(\n        \"SELECT sum(total_price) FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\' AND ledger_uid=\"\n        \"%s GROUP BY ledger_uid\" %\n        self.portal.portal_categories.ledger.accounting.general.getUid())[0][0])\n      self.assertEqual(300, q(\n        \"SELECT sum(quantity) FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\' AND ledger_uid=\"\n        \"%s GROUP BY ledger_uid\" %\n        self.portal.portal_categories.ledger.accounting.general.getUid())[0][0])\n      self.assertEqual(1200, q(\n        \"SELECT sum(total_price) FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\' AND ledger_uid=\"\n        \"%s GROUP BY ledger_uid\" % self.portal.portal_categories.ledger.accounting.detailed.getUid())[0][0])\n      self.assertEqual(1200, q(\n        \"SELECT sum(quantity) FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\' AND ledger_uid=\"\n        \"%s GROUP BY ledger_uid\" % self.portal.portal_categories.ledger.accounting.detailed.getUid())[0][0])\n\n    # now check content of stock table\n    testStockTableContent()\n    balance_transaction.reindexObject()\n    self.tic()\n    testStockTableContent()\n\n  def test_createBalanceOnMirrorSectionMultiCurrency(self):\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        title=\'Yen\',\n        resource=\'currency_module/yen\',\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_asset_debit=1.1,\n                    source_debit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_asset_credit=1.1,\n                    source_credit=100)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        title=\'Dollar\',\n        resource=\'currency_module/usd\',\n        destination_section_value=organisation_module.client_2,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_asset_debit=2.2,\n                    source_debit=200),\n               dict(source_value=self.account_module.receivable,\n                    source_asset_credit=2.2,\n                    source_credit=200)))\n\n    period.AccountingPeriod_createBalanceTransaction(\n                      profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(3, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n\n    self.assertEqual(self.section,\n                      balance_transaction.getDestinationSectionValue())\n    self.assertEqual(None, balance_transaction.getSourceSection())\n    self.assertEqual(DateTime(2007, 1, 1),\n                      balance_transaction.getStartDate())\n    self.assertEqual(\'currency_module/euro\',\n                      balance_transaction.getResource())\n\n    # this should create a balance with 3 lines,\n    #   pl                 = 3.3 D     ( resource acquired )\n    #   receivable/client1 =     1.1 C ( resource yen ) qty=100\n    #   receivable/client2 =     2.2 C ( resource usd ) qyt=200\n\n    accounting_currency_precision = \\\n        self.portal.currency_module.euro.getQuantityPrecision()\n    self.assertEqual(accounting_currency_precision, 2)\n\n    movement_list = balance_transaction.getMovementList()\n    self.assertEqual(3, len(movement_list))\n    client1_movement_list = [m for m in movement_list\n     if m.getSourceSectionValue() == organisation_module.client_1]\n    self.assertEqual(1, len(client1_movement_list))\n    client1_movement = client1_movement_list[0]\n    self.assertEqual(\'currency_module/yen\',\n                      client1_movement.getResource())\n    self.assertEqual([], client1_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, client1_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      client1_movement.getDestinationValue())\n    self.assertEqual(organisation_module.client_1,\n                      client1_movement.getSourceSectionValue())\n    self.assertAlmostEqual(1.1,\n          client1_movement.getDestinationInventoriatedTotalAssetCredit(),\n          accounting_currency_precision)\n    self.assertEqual(None, client1_movement.getSourceTotalAssetPrice())\n    self.assertEqual(100, client1_movement.getDestinationCredit())\n\n    client2_movement_list = [m for m in movement_list\n     if m.getSourceSectionValue() == organisation_module.client_2]\n    self.assertEqual(1, len(client2_movement_list))\n    client2_movement = client2_movement_list[0]\n    self.assertEqual(\'currency_module/usd\',\n                      client2_movement.getResource())\n    self.assertEqual([], client2_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, client2_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      client2_movement.getDestinationValue())\n    self.assertEqual(organisation_module.client_2,\n                      client2_movement.getSourceSectionValue())\n    self.assertAlmostEqual(2.2,\n        client2_movement.getDestinationInventoriatedTotalAssetCredit(),\n        accounting_currency_precision)\n    self.assertEqual(None, client2_movement.getSourceTotalAssetPrice())\n    self.assertEqual(200., client2_movement.getDestinationCredit())\n\n    pl_movement_list = [m for m in movement_list\n                         if m.getDestinationValue() == pl]\n    self.assertEqual(1, len(pl_movement_list))\n    pl_movement = pl_movement_list[0]\n    self.assertEqual([], pl_movement.getValueList(\'resource\'))\n    self.assertEqual(None, pl_movement.getSource())\n    self.assertEqual(pl,\n                      pl_movement.getDestinationValue())\n    self.assertEqual(None,\n                      pl_movement.getSourceSection())\n    self.assertEqual(None, pl_movement.getDestinationTotalAssetPrice())\n    self.assertEqual(None, pl_movement.getSourceTotalAssetPrice())\n    self.assertAlmostEqual(3.3,\n                  pl_movement.getDestinationDebit(),\n                  accounting_currency_precision)\n\n    self.tic()\n\n    # now check content of stock table\n    q = self.portal.erp5_sql_connection.manage_test\n    # 3 lines, one with quantity 3.3, 2 with quantity 0\n    self.assertEqual(1, q(\n      \"SELECT count(*) FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertAlmostEqual(3.3, q(\n      \"SELECT total_price FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0],\n      accounting_currency_precision)\n    self.assertAlmostEqual(3.3, q(\n      \"SELECT quantity FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0],\n      accounting_currency_precision)\n    self.assertEqual(self.portal.currency_module.euro.getUid(), q(\n      \"SELECT resource_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(self.section.getUid(), q(\n      \"SELECT section_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(None, q(\n      \"SELECT mirror_section_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(pl.getUid(), q(\n      \"SELECT node_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(None, q(\n      \"SELECT mirror_node_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(DateTime(2007, 1, 1), q(\n      \"SELECT date FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n\n    # we can reindex again\n    balance_transaction.reindexObject()\n    self.tic()\n\n\n  def test_createBalanceOnMirrorSectionMultiCurrencySameMirrorSection(self):\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        title=\'Yen\',\n        resource=\'currency_module/yen\',\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_asset_debit=1.1,\n                    source_debit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_asset_credit=1.1,\n                    source_credit=100)))\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        title=\'Dollar\',\n        resource=\'currency_module/usd\',\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_asset_debit=2.2,\n                    source_debit=200),\n               dict(source_value=self.account_module.receivable,\n                    source_asset_credit=2.2,\n                    source_credit=200)))\n    self.tic()\n\n    period.AccountingPeriod_createBalanceTransaction(\n                          profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(3, len(accounting_transaction_list))\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n\n    self.assertEqual(self.section,\n                      balance_transaction.getDestinationSectionValue())\n    self.assertEqual(None, balance_transaction.getSourceSection())\n    self.assertEqual(DateTime(2007, 1, 1),\n                      balance_transaction.getStartDate())\n    self.assertEqual(\'currency_module/euro\',\n                      balance_transaction.getResource())\n\n    # this should create a balance with 3 lines,\n    #   pl                 = 3.3 D     ( resource acquired )\n    #   receivable/client1 =     1.1 C ( resource yen ) qty=100\n    #   receivable/client1 =     2.2 C ( resource usd ) qyt=200\n\n    accounting_currency_precision = \\\n        self.portal.currency_module.euro.getQuantityPrecision()\n    self.assertEqual(accounting_currency_precision, 2)\n\n    movement_list = balance_transaction.getMovementList()\n    self.assertEqual(3, len(movement_list))\n    client1_movement_list = [m for m in movement_list\n     if m.getSourceSectionValue() == organisation_module.client_1]\n    self.assertEqual(2, len(client1_movement_list))\n    yen_movement = [x for x in client1_movement_list if\n                    x.getResource() == \'currency_module/yen\'][0]\n    self.assertEqual([], yen_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, yen_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      yen_movement.getDestinationValue())\n    self.assertEqual(organisation_module.client_1,\n                      yen_movement.getSourceSectionValue())\n    self.assertAlmostEqual(1.1,\n          yen_movement.getDestinationInventoriatedTotalAssetCredit(),\n          accounting_currency_precision)\n    self.assertEqual(None, yen_movement.getSourceTotalAssetPrice())\n    self.assertEqual(100, yen_movement.getDestinationCredit())\n\n    dollar_movement = [x for x in client1_movement_list if\n                    x.getResource() == \'currency_module/usd\'][0]\n    self.assertEqual([], dollar_movement.getValueList(\'destination_section\'))\n    self.assertEqual(None, dollar_movement.getSource())\n    self.assertEqual(self.account_module.receivable,\n                      dollar_movement.getDestinationValue())\n    self.assertEqual(organisation_module.client_1,\n                      dollar_movement.getSourceSectionValue())\n    self.assertAlmostEqual(2.2,\n          dollar_movement.getDestinationInventoriatedTotalAssetCredit(),\n          accounting_currency_precision)\n    self.assertEqual(None, dollar_movement.getSourceTotalAssetPrice())\n    self.assertEqual(200, dollar_movement.getDestinationCredit())\n\n    self.tic()\n\n    # now check content of stock table\n    q = self.portal.erp5_sql_connection.manage_test\n    self.assertEqual(1, q(\n      \"SELECT count(*) FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertAlmostEqual(3.3, q(\n      \"SELECT total_price FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0],\n      accounting_currency_precision)\n    self.assertAlmostEqual(3.3, q(\n      \"SELECT quantity FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0],\n      accounting_currency_precision)\n    self.assertEqual(self.portal.currency_module.euro.getUid(), q(\n      \"SELECT resource_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(self.section.getUid(), q(\n      \"SELECT section_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(None, q(\n      \"SELECT mirror_section_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(pl.getUid(), q(\n      \"SELECT node_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(None, q(\n      \"SELECT mirror_node_uid FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(DateTime(2007, 1, 1), q(\n      \"SELECT date FROM stock WHERE portal_type=\"\n      \"\'Balance Transaction Line\'\")[0][0])\n\n    # we can reindex again\n    balance_transaction.reindexObject()\n    self.tic()\n\n  def test_createBalanceTransactionZeroInAccountingTransactionCurrencyNextYear(self):\n    pl = self.portal.account_module.newContent(\n      portal_type=\'Account\', account_type=\'equity\')\n    bank_account = self.section.newContent(portal_type=\'Bank Account\')\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n\n    self._makeOne(\n      start_date=DateTime(2006, 1, 1),\n      title=\'Yen\',\n      resource=\'currency_module/yen\',\n      destination_section_value=organisation_module.client_1,\n      portal_type=\'Sale Invoice Transaction\',\n      simulation_state=\'delivered\',\n      lines=(\n        dict(\n          source_value=self.account_module.goods_sales,\n          source_asset_debit=1,\n          source_debit=70,\n        ),\n        dict(\n          source_value=self.account_module.stocks,\n          source_asset_credit=1,\n          source_credit=30,\n        ),\n        # account by node\n        dict(\n          source_value=self.account_module.stocks,\n          source_asset_credit=0,\n          source_debit=70,\n        ),\n        # account by mirror_section\n        dict(\n          source_value=self.account_module.receivable,\n          source_asset_credit=0,\n          source_debit=30,\n        ),\n        # account by payment\n        dict(\n          source_value=self.account_module.bank,\n          source_payment_value=bank_account,\n          source_asset_credit=0,\n          source_credit=100,\n        ),\n      ))\n    self.tic()\n    period.AccountingPeriod_createBalanceTransaction(\n      profit_and_loss_account=pl.getRelativeUrl())\n    self.tic()\n\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(2, len(accounting_transaction_list))\n    balance_transaction, = self.accounting_module.contentValues(\n      portal_type=\'Balance Transaction\')\n\n    self.assertEqual(\n      self.section, balance_transaction.getDestinationSectionValue())\n    self.assertEqual(None, balance_transaction.getSourceSection())\n    self.assertEqual(DateTime(2007, 1, 1), balance_transaction.getStartDate())\n    self.assertEqual(\'currency_module/euro\', balance_transaction.getResource())\n\n    def check_balance_transaction_lines(bt):\n      self.assertEqual(\n        sorted(\n          [\n            (\n              line.getDestinationDebit(),\n              line.getDestinationCredit(),\n              line.getDestinationInventoriatedTotalAssetDebit(),\n              line.getDestinationInventoriatedTotalAssetCredit(),\n              line.getResourceTitle(),\n              line.getDestinationValue(),\n              line.getDestinationPaymentValue(),\n              line.getSourceSectionValue(),\n            ) for line in bt.contentValues()\n          ]), [\n            (\n              0.0,\n              100.0,\n              0.0,\n              0.0,\n              \'Yen\',\n              self.account_module.bank,\n              bank_account,\n              None,\n            ),\n            (\n              1.0,\n              0.0,\n              1.0,\n              0.0,\n              \'Euro\',\n              pl,\n              None,\n              None,\n            ),\n            (\n              30.0,\n              0.0,\n              0.0,\n              0.0,\n              \'Yen\',\n              self.account_module.receivable,\n              None,\n              organisation_module.client_1,\n            ),\n            (\n              40.0,\n              0.0,\n              0.0,\n              1.0,\n              \'Yen\',\n              self.portal.account_module.stocks,\n              None,\n              None,\n            ),\n          ])\n    check_balance_transaction_lines(balance_transaction)\n    q = self.portal.erp5_sql_connection.manage_test\n    self.assertEqual(\n      1,\n      q(\n        \"SELECT count(*) FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(\n      1,\n      q(\n        \"SELECT total_price FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\'\")[0][0])\n    self.assertEqual(\n      1,\n      q(\n        \"SELECT quantity FROM stock WHERE portal_type=\"\n        \"\'Balance Transaction Line\'\")[0][0])\n\n    # next year, if there are no transactions during period, closing should produce\n    # the same balance transaction.\n    period_next_year = self.section.newContent(portal_type=\'Accounting Period\')\n    period_next_year.setStartDate(DateTime(2007, 1, 1))\n    period_next_year.setStopDate(DateTime(2007, 12, 31))\n    period_next_year.AccountingPeriod_createBalanceTransaction(\n      profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(3, len(accounting_transaction_list))\n    balance_transaction_next_year, = [bt for bt in self.accounting_module.contentValues(\n      portal_type=\'Balance Transaction\') if bt != balance_transaction]\n    check_balance_transaction_lines(balance_transaction_next_year)\n\n    # we can reindex again\n    balance_transaction.reindexObject()\n    balance_transaction_next_year.reindexObject()\n    self.tic()\n\n  def test_AccountingPeriodWorkflow(self):\n    \"\"\"Tests that accounting_period_workflow creates a balance transaction.\n    \"\"\"\n    # open a period for our section\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    self.assertEqual(\'draft\', period.getSimulationState())\n    self.portal.portal_workflow.doActionFor(period, \'start_action\')\n    self.assertEqual(\'started\', period.getSimulationState())\n\n    # create a simple transaction in the period\n    self._makeOne(\n        start_date=DateTime(2006, 6, 30),\n        portal_type=\'Sale Invoice Transaction\',\n        destination_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.receivable,\n                    source_credit=100),\n               dict(source_value=self.account_module.goods_purchase,\n                    source_debit=100)))\n    self.assertEqual(1, len(self.accounting_module))\n\n    pl_account = self.portal.account_module.newContent(\n                    portal_type=\'Account\',\n                    account_type=\'equity\',\n                    gap=\'my_country/my_accounting_standards/1\',\n                    title=\'Profit & Loss\')\n    pl_account.validate()\n\n    # close the period\n    self.portal.portal_workflow.doActionFor(period, \'stop_action\',\n            profit_and_loss_account=pl_account.getRelativeUrl())\n    self.assertEqual(\'stopped\', period.getSimulationState())\n    self.tic()\n    # reopen it, then close it got real\n    self.portal.portal_workflow.doActionFor(period, \'restart_action\')\n    self.assertEqual(\'started\', period.getSimulationState())\n    self.tic()\n    self.portal.portal_workflow.doActionFor(period, \'stop_action\',\n            profit_and_loss_account=pl_account.getRelativeUrl())\n    self.assertEqual(\'stopped\', period.getSimulationState())\n    self.tic()\n\n    self.portal.portal_workflow.doActionFor(period, \'deliver_action\',)\n\n    self.tic()\n    self.assertEqual(\'delivered\', period.getSimulationState())\n\n    # this created a balance transaction\n    balance_transaction_list = self.accounting_module.contentValues(\n                                  portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n\n    # and this transaction must use the account we used in the workflow action.\n    self.assertEqual(1, len([m for m in\n                              balance_transaction.getMovementList()\n                              if m.getDestinationValue() == pl_account]))\n\n  def test_MultipleSection(self):\n    period = self.main_section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    period.start()\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Purchase Invoice Transaction\',\n        destination_section_value=self.main_section,\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=30),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=30)))\n\n    transaction_section = self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Purchase Invoice Transaction\',\n        destination_section_value=self.section,\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'stopped\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=20),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=20)))\n\n    # transaction_section is just stopped, so stopping the period is refused.\n    self.assertRaises(ValidationFailed,\n                      self.portal.portal_workflow.doActionFor,\n                      period,\n                      \'stop_action\')\n\n    transaction_section.deliver()\n    self.tic()\n\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n    self.portal.portal_workflow.doActionFor(period, \'stop_action\',\n              profit_and_loss_account=pl.getRelativeUrl())\n\n\n    self.tic()\n\n    created_balance_transaction_list = self.portal.accounting_module.contentValues(\n                                    portal_type=\'Balance Transaction\')\n    self.assertEqual(2, len(created_balance_transaction_list))\n\n    main_section_balance_transaction = [bt for bt in\n        created_balance_transaction_list if bt.getDestinationSectionValue() ==\n        self.main_section][0]\n    self.assertEqual(2, len(main_section_balance_transaction.getMovementList()))\n    self.assertEqual([], main_section_balance_transaction.checkConsistency())\n\n    section_balance_transaction = [bt for bt in\n        created_balance_transaction_list if bt.getDestinationSectionValue() ==\n        self.section][0]\n    self.assertEqual(2, len(section_balance_transaction.getMovementList()))\n    self.assertEqual([], section_balance_transaction.checkConsistency())\n\n    self.tic()\n    # we can reindex again\n    main_section_balance_transaction.reindexObject()\n    section_balance_transaction.reindexObject()\n    self.tic()\n\n  def test_MultipleSectionIndependant(self):\n    stool = self.portal.portal_simulation\n    period_main_section = self.main_section.newContent(portal_type=\'Accounting Period\')\n    period_main_section.setStartDate(DateTime(2006, 1, 1))\n    period_main_section.setStopDate(DateTime(2006, 12, 31))\n    period_main_section.start()\n\n    period_section = self.section.newContent(portal_type=\'Accounting Period\')\n    period_section.setStartDate(DateTime(2006, 1, 1))\n    period_section.setStopDate(DateTime(2006, 12, 31))\n    period_section.start()\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Purchase Invoice Transaction\',\n        destination_section_value=self.main_section,\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=30),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=30)))\n\n    transaction_section = self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Purchase Invoice Transaction\',\n        destination_section_value=self.section,\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'stopped\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=20),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=20)))\n\n    transaction_section.deliver()\n    self.tic()\n\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n    self.portal.portal_workflow.doActionFor(period_main_section, \'stop_action\',\n              profit_and_loss_account=pl.getRelativeUrl())\n\n    self.tic()\n\n    created_balance_transaction_list = self.portal.accounting_module.contentValues(\n                                    portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(created_balance_transaction_list))\n\n    self.assertEqual(30, stool.getInventory(\n                              section_uid=self.main_section.getUid(),\n                              node_uid=pl.getUid()))\n    self.assertEqual(-30, stool.getInventory(\n                              section_uid=self.main_section.getUid(),\n                              node_uid=self.portal.account_module.payable.getUid()))\n\n    # Section is not impacted at the moment\n    self.assertEqual(0, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=pl.getUid()))\n    self.assertEqual(-20, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=self.portal.account_module.payable.getUid()))\n\n    # Close section\'s period\n    self.portal.portal_workflow.doActionFor(period_section, \'stop_action\',\n              profit_and_loss_account=pl.getRelativeUrl())\n\n    self.tic()\n\n    created_balance_transaction_list = self.portal.accounting_module.contentValues(\n                                    portal_type=\'Balance Transaction\')\n    self.assertEqual(2, len(created_balance_transaction_list))\n\n    # section is now impacted\n    self.assertEqual(20, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=pl.getUid()))\n    self.assertEqual(-20, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=self.portal.account_module.payable.getUid()))\n\n    self.assertEqual(30, stool.getInventory(\n                              section_uid=self.main_section.getUid(),\n                              node_uid=pl.getUid()))\n    self.assertEqual(-30, stool.getInventory(\n                              section_uid=self.main_section.getUid(),\n                              node_uid=self.portal.account_module.payable.getUid()))\n\n  def test_MultipleSectionEmpty(self):\n    period = self.main_section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    period.start()\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Purchase Invoice Transaction\',\n        destination_section_value=self.main_section,\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=30),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=30)))\n\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n    self.portal.portal_workflow.doActionFor(period, \'stop_action\',\n              profit_and_loss_account=pl.getRelativeUrl())\n\n    self.tic()\n\n    created_balance_transaction_list = self.portal.accounting_module.contentValues(\n                                    portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(created_balance_transaction_list))\n    # no balance transaction has been created for section\n\n  def test_SecondAccountingPeriod(self):\n    \"\"\"Tests having two accounting periods.\n    \"\"\"\n    period1 = self.section.newContent(portal_type=\'Accounting Period\')\n    period1.setStartDate(DateTime(2006, 1, 1))\n    period1.setStopDate(DateTime(2006, 12, 31))\n    period1.start()\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Purchase Invoice Transaction\',\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=100),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=100)))\n    pl_account = self.portal.account_module.newContent(\n                    portal_type=\'Account\',\n                    account_type=\'equity\',\n                    gap=\'my_country/my_accounting_standards/1\',\n                    title=\'Profit & Loss\')\n    pl_account.validate()\n    self.portal.portal_workflow.doActionFor(\n            period1, \'stop_action\',\n            profit_and_loss_account=pl_account.getRelativeUrl())\n    self.tic()\n\n    balance_transaction_list = self.accounting_module.contentValues(\n                                  portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction1 = balance_transaction_list[0]\n\n    period2 = self.section.newContent(portal_type=\'Accounting Period\')\n    period2.setStartDate(DateTime(2007, 1, 1))\n    period2.setStopDate(DateTime(2007, 12, 31))\n    period2.start()\n\n    self._makeOne(\n        start_date=DateTime(2007, 1, 2),\n        portal_type=\'Accounting Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.equity,\n                    source_debit=100),\n               dict(source_value=pl_account,\n                    source_credit=100)))\n    self._makeOne(\n        start_date=DateTime(2007, 1, 3),\n        portal_type=\'Purchase Invoice Transaction\',\n        source_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(destination_value=self.account_module.goods_purchase,\n                    destination_debit=300),\n               dict(destination_value=self.account_module.payable,\n                    destination_credit=300)))\n\n    period2.AccountingPeriod_createBalanceTransaction(\n                profit_and_loss_account=pl_account.getRelativeUrl())\n    balance_transaction_list = [tr for tr in\n                          self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n                          if tr != balance_transaction1]\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction2 = balance_transaction_list[0]\n\n    self.assertEqual(DateTime(2008, 1, 1),\n                      balance_transaction2.getStartDate())\n    # this should create a balance with 3 lines,\n    #   equity          = 100 D\n    #   payable/client1 =       100 + 300 C\n    #   pl              = 300 D\n    movement_list = balance_transaction2.getMovementList()\n    self.assertEqual(3, len(movement_list))\n\n    equity_movement_list = [m for m in movement_list\n          if m.getDestinationValue() == self.account_module.equity]\n    self.assertEqual(1, len(equity_movement_list))\n    equity_movement = equity_movement_list[0]\n    self.assertEqual(100., equity_movement.getDestinationDebit())\n\n    payable_movement_list = [m for m in movement_list\n          if m.getDestinationValue() == self.account_module.payable]\n    self.assertEqual(1, len(payable_movement_list))\n    payable_movement = payable_movement_list[0]\n    self.assertEqual(400., payable_movement.getDestinationCredit())\n\n    pl_movement_list = [m for m in movement_list\n          if m.getDestinationValue() == pl_account]\n    self.assertEqual(1, len(pl_movement_list))\n    pl_movement = pl_movement_list[0]\n    self.assertEqual(300., pl_movement.getDestinationDebit())\n\n\n  def test_ProfitAndLossUsedInPeriod(self):\n    \"\"\"When the profit and loss account has a non zero balance at the end of\n    the period, AccountingPeriod_createBalanceTransaction script should add\n    this balance and the new calculated profit and loss to have only one line.\n    \"\"\"\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    pl_account = self.portal.account_module.newContent(\n                    portal_type=\'Account\',\n                    account_type=\'equity\',\n                    gap=\'my_country/my_accounting_standards/1\',\n                    title=\'Profit & Loss\')\n    pl_account.validate()\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Accounting Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_purchase,\n                    source_debit=400),\n               dict(source_value=pl_account,\n                    source_debit=100),\n               dict(source_value=self.account_module.stocks,\n                    source_credit=500)))\n\n    period.AccountingPeriod_createBalanceTransaction(\n                  profit_and_loss_account=pl_account.getRelativeUrl())\n\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n    balance_transaction.alternateReindexObject()\n    movement_list = balance_transaction.getMovementList()\n    self.assertEqual(2, len(movement_list))\n\n    pl_movement_list = [m for m in movement_list\n                      if m.getDestinationValue() == pl_account]\n    self.assertEqual(1, len(pl_movement_list))\n    self.assertEqual(500, pl_movement_list[0].getDestinationDebit())\n\n    stock_movement_list = [m for m in movement_list\n          if m.getDestinationValue() == self.account_module.stocks]\n    self.assertEqual(1, len(stock_movement_list))\n    self.assertEqual(500, stock_movement_list[0].getDestinationCredit())\n\n    self.tic()\n    balance_transaction.reindexObject()\n    self.tic()\n\n  def test_ProfitAndLossUsedInPeriodWithMultipleCurrency(self):\n    \"\"\"When the profit and loss account has a non zero balance at the end of\n    the period, AccountingPeriod_createBalanceTransaction script should add\n    a line for each currency used.\n    \"\"\"\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    pl_account = self.portal.account_module.newContent(\n                    portal_type=\'Account\',\n                    account_type=\'equity\',\n                    gap=\'my_country/my_accounting_standards/1\',\n                    title=\'Profit & Loss\')\n    pl_account.validate()\n\n    transaction1 = self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Accounting Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_purchase,\n                    source_debit=400),\n               dict(source_value=pl_account,\n                    source_debit=100),\n               dict(source_value=self.account_module.stocks,\n                    source_credit=500)))\n    self.assertEqual([], transaction1.checkConsistency())\n\n    transaction2 = self._makeOne(\n        start_date=DateTime(2006, 1, 2),\n        portal_type=\'Accounting Transaction\',\n        resource_value=self.portal.currency_module.yen,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_purchase,\n                    source_debit=9000,\n                    source_asset_debit=90),\n               dict(source_value=pl_account,\n                    source_debit=1000,\n                    source_asset_debit=10),\n               dict(source_value=self.account_module.stocks,\n                    source_credit=10000,\n                    source_asset_credit=100)))\n    self.assertEqual([], transaction2.checkConsistency())\n\n    period.AccountingPeriod_createBalanceTransaction(\n                  profit_and_loss_account=pl_account.getRelativeUrl())\n\n    balance_transaction_list = self.accounting_module.contentValues(\n                              portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(balance_transaction_list))\n    balance_transaction = balance_transaction_list[0]\n    balance_transaction.alternateReindexObject()\n    movement_list = balance_transaction.getMovementList()\n\n    pl_movement_list = [m for m in movement_list\n                      if m.getDestinationValue() == pl_account]\n    self.assertEqual(2, len(pl_movement_list))\n    # This is a 400 + 90 loss, plus the 100 using EUR\n    self.assertEqual(sorted([\n        (\n         100 + 490.,\n         None,\n         self.portal.currency_module.euro, ),\n        (\n         1000.,\n         10.,\n         self.portal.currency_module.yen, ),\n        ]), sorted([(\n            m.getQuantity(),\n            m.getDestinationTotalAssetPrice(),\n            m.getResourceValue(),\n            ) for m in pl_movement_list]))\n\n    self.tic()\n    balance_transaction.reindexObject()\n    self.tic()\n\n  def test_BalanceTransactionWhenProfitAndLossBalanceIsZero(self):\n    # The case of a balance transaction after all accounts have a 0 balance.\n    period1 = self.section.newContent(portal_type=\'Accounting Period\')\n    period1.setStartDate(DateTime(2006, 1, 1))\n    period1.setStopDate(DateTime(2006, 12, 31))\n    period2 = self.section.newContent(portal_type=\'Accounting Period\')\n    period2.setStartDate(DateTime(2007, 1, 1))\n    period2.setStopDate(DateTime(2007, 12, 31))\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        destination_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.receivable,\n                    source_debit=100),\n               dict(source_value=self.account_module.goods_sales,\n                    source_credit=100)))\n    self.tic()\n\n    period1.AccountingPeriod_createBalanceTransaction(\n                             profit_and_loss_account=pl.getRelativeUrl())\n    year_1_accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(2, len(year_1_accounting_transaction_list))\n    self.tic()\n\n    transaction2 = self._makeOne(\n        start_date=DateTime(2007, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        destination_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.receivable,\n                    source_debit=-100),\n               dict(source_value=self.account_module.goods_sales,\n                    source_credit=-100)))\n    self.tic()\n\n    period2.AccountingPeriod_createBalanceTransaction(\n                             profit_and_loss_account=pl.getRelativeUrl())\n    accounting_transaction_list = self.accounting_module.contentValues()\n    self.assertEqual(4, len(accounting_transaction_list))\n    self.tic()\n\n    balance_transaction, = [t for t in accounting_transaction_list if t not in\n        year_1_accounting_transaction_list and t != transaction2]\n    # Maybe we want to add line for each account in that case ?\n    line, = balance_transaction.contentValues()\n\n    self.assertEqual(line.getDestinationValue(), pl)\n    self.assertEqual(line.getQuantity(), 0)\n    self.assertEqual(line.getDestinationTotalAssetPrice(), None)\n\n\n  def test_InventoryIndexingNodeAndMirrorSection(self):\n    # Balance Transactions are indexed as Inventories.\n    transaction1 = self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Sale Invoice Transaction\',\n        destination_section_value=self.organisation_module.client_1,\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.receivable,\n                    source_debit=100),\n               dict(source_value=self.account_module.goods_sales,\n                    source_credit=100)))\n\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.receivable,\n                source_section_value=self.organisation_module.client_1,\n                destination_debit=100,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.stocks,\n                destination_credit=100,)\n    balance.stop()\n    balance.deliver()\n    self.tic()\n\n    # now check inventory\n    stool = self.getSimulationTool()\n    # the account \'receivable\' has a balance of 100\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    self.assertEqual(100, stool.getInventory(\n                    section_uid=self.section.getUid(),\n                    mirror_section_uid=self.organisation_module.client_1.getUid(),\n                    node_uid=node_uid))\n    self.assertEqual(100, stool.getInventoryAssetPrice(\n                    section_uid=self.section.getUid(),\n                    node_uid=node_uid))\n    # and only one movement is returned by getMovementHistoryList\n    movement_history_list = stool.getMovementHistoryList(\n                    section_uid=self.section.getUid(),\n                    node_uid=node_uid)\n    self.assertEqual(1, len(movement_history_list))\n    self.assertEqual([100], [x.total_price  for x in movement_history_list])\n\n    # the account \'goods_sales\' has a balance of -100\n    node_uid = self.account_module.goods_sales.getUid()\n    self.assertEqual(-100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n\n    # the account \'stocks\' has a balance of -100\n    node_uid = self.account_module.stocks.getUid()\n    self.assertEqual(-100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n\n    # we can reindex again\n    balance.reindexObject()\n    self.tic()\n    # the account \'receivable\' still has a balance of 100\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n\n    # Now check that even if we change the old movement and we\n    # reindex the balance, the stock will still be the same\n    getInventoryList = self.portal.portal_simulation.getInventoryList\n    def getInventoryQuantityList():\n      quantity_list = [x.inventory for x in getInventoryList(\n         section_uid=self.section.getUid(),\n         node_uid=node_uid)]\n      quantity_list.sort()\n      return quantity_list\n    # 100 for the transaction, 0 for the balance\n    # because in the balance we put exactly what we have in stock\n    self.assertEqual(getInventoryQuantityList(),\n                      [100])\n    def setQuantityOnTransaction1(quantity):\n      for line in transaction1.objectValues():\n        if line.getSourceDebit():\n          line.setSourceDebit(quantity)\n        if line.getSourceCredit():\n          line.setSourceCredit(quantity)\n      self.tic()\n      balance.reindexObject()\n      self.tic()\n    setQuantityOnTransaction1(99)\n    # 99 for the transaction, 1 for the balance\n    # because in the balance we have 100, which is 1 more\n    # than actual stock of 99\n    self.assertEqual(getInventoryQuantityList(),\n                      [1, 99])\n    setQuantityOnTransaction1(100)\n    # Then finally we check that we have again same thing\n    # as initial conditions\n    self.assertEqual(getInventoryQuantityList(),\n                      [100])\n\n  def test_InventoryIndexingNodeDiffOnNode(self):\n    # Balance Transactions are indexed as Inventories.\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        portal_type=\'Accounting Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.receivable,\n                    source_debit=100),\n               dict(source_value=self.account_module.stocks,\n                    source_credit=100)))\n\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.receivable,\n                destination_debit=150,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.stocks,\n                destination_credit=90,)\n    balance.stop()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of 150\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(150, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    # movement history list shows 2 movements, the initial with qty 100, and\n    # the balance with quantity 50\n\n    # the account \'stocks\' has a balance of -100\n    node_uid = self.account_module.stocks.getUid()\n    self.assertEqual(-90, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    # we can reindex again\n    balance.reindexObject()\n    self.tic()\n\n  def test_IndexingBalanceTransactionLinesWithSameNodes(self):\n    # Indexes balance transaction without any previous inventory.\n    # This make sure that indexing two balance transaction lines with same\n    # categories does not try to insert duplicate keys in category table.\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                source_section_value=self.organisation_module.client_1,\n                destination_value=self.account_module.receivable,\n                destination_debit=150,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                source_section_value=self.organisation_module.client_2,\n                destination_value=self.account_module.receivable,\n                destination_debit=30,)\n\n    balance.stop()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of 150 + 30\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(180, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    self.assertEqual(150, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              mirror_section_uid=self.organisation_module\\\n                                                    .client_1.getUid(),\n                              node_uid=node_uid))\n    self.assertEqual(30, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              mirror_section_uid=self.organisation_module\\\n                                                    .client_2.getUid(),\n                              node_uid=node_uid))\n    # we can reindex again\n    balance.reindexObject()\n    self.tic()\n\n  def test_BalanceTransactionLineBrainGetObject(self):\n    # Balance Transaction Line can be retrieved using Brain.getObject\n    self._makeOne(\n               start_date=DateTime(2006, 1, 31),\n               portal_type=\'Sale Invoice Transaction\',\n               simulation_state=\'delivered\',\n               lines=(dict(source_value=self.account_module.receivable,\n                           source_debit=30),\n                      dict(source_value=self.account_module.goods_sales,\n                           source_credit=30)))\n\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          id=\'different_from_line\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n    # this line already exists in stock table, only the difference will be\n    # indexed\n    balance_line = balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.receivable,\n                destination_debit=100,)\n    # this line does not already exist\n    balance_line2 = balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.payable,\n                destination_credit=100,)\n    balance.stop()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of 100\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    # there is one line in getMovementHistoryList:\n    mvt_history_list = stool.getMovementHistoryList(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid,\n                              sort_on=((\'date\', \'ASC\'), ))\n    self.assertEqual(2, len(mvt_history_list))\n    self.assertEqual(mvt_history_list[1].getObject(),\n                      balance_line)\n    self.assertEqual([30, 70], [b.total_price for b in mvt_history_list])\n\n    # There is also one line on payable account\n    node_uid = self.account_module.payable.getUid()\n    mvt_history_list = stool.getMovementHistoryList(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)\n    self.assertEqual(1, len(mvt_history_list))\n    self.assertEqual(mvt_history_list[0].getObject(),\n                      balance_line2)\n\n    # we can reindex again\n    balance.reindexObject()\n    self.tic()\n\n  def test_BalanceTransactionLineBrainGetObjectDifferentThirdParties(self):\n    # Balance Transaction Line can be retrieved using Brain.getObject, when\n    # the balance is for different third parties\n    self._makeOne(\n               start_date=DateTime(2006, 1, 30),\n               portal_type=\'Sale Invoice Transaction\',\n               simulation_state=\'delivered\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           source_debit=30),\n                      dict(source_value=self.account_module.goods_sales,\n                           source_credit=30)))\n    self._makeOne(\n               start_date=DateTime(2006, 1, 31),\n               portal_type=\'Sale Invoice Transaction\',\n               simulation_state=\'delivered\',\n               destination_section_value=self.organisation_module.client_2,\n               lines=(dict(source_value=self.account_module.receivable,\n                           source_debit=40),\n                      dict(source_value=self.account_module.goods_sales,\n                           source_credit=40)))\n\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          id=\'different_from_line\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n\n    balance_line = balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.receivable,\n                source_section_value=self.organisation_module.client_2,\n                destination_debit=100,)\n    balance_line2 = balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.payable,\n                destination_credit=100,)\n    balance.stop()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of 100 + 30\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(130, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid,))\n    # there is one line in getMovementHistoryList:\n    mvt_history_list = stool.getMovementHistoryList(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid,\n                              sort_on=((\'date\', \'ASC\'), ))\n    self.assertEqual(3, len(mvt_history_list))\n    self.assertEqual(mvt_history_list[2].getObject(),\n                      balance_line)\n    self.assertEqual([30, 40, 60], [b.total_price for b in mvt_history_list])\n\n    # There is also one line on payable account\n    node_uid = self.account_module.payable.getUid()\n    mvt_history_list = stool.getMovementHistoryList(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)\n    self.assertEqual(1, len(mvt_history_list))\n    self.assertEqual(mvt_history_list[0].getObject(),\n                      balance_line2)\n\n    balance.reindexObject()\n    self.tic()\n\n  def test_BalanceTransactionDate(self):\n    # check that dates are correctly used for Balance Transaction indexing\n    organisation_module = self.organisation_module\n\n    self._makeOne(\n        start_date=DateTime(2006, 12, 31),\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=100)))\n\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2007, 1, 1),\n                          resource_value=self.currency_module.euro,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.equity,\n                destination_debit=100,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                source_section_value=organisation_module.client_1,\n                destination_value=self.account_module.receivable,\n                destination_credit=100,)\n    balance.stop()\n    balance.deliver()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of -100\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(-100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    self.assertEqual(1, len(stool.getMovementHistoryList(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)))\n\n    # this is a transaction with the same date as the balance transaction, but\n    # this transaction should not be taken into account when we reindex the\n    # Balance Transaction.\n    self._makeOne(\n        start_date=DateTime(2007, 1, 1),\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_debit=50),\n               dict(source_value=self.account_module.receivable,\n                    source_credit=50)))\n    self.tic()\n    # let\'s try to reindex and check if values are still OK\n    balance.reindexObject()\n    self.tic()\n\n    self.assertEqual(-150, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    movement_history_list = stool.getMovementHistoryList(\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)\n    self.assertEqual(2, len(movement_history_list))\n    self.assertEqual(sorted([-50, -100]),\n      sorted([x.total_quantity for x in movement_history_list]))\n\n\n  def test_BalanceTransactionDateInInventoryAPI(self):\n    # check that dates are correctly used for Balance Transaction when making\n    # reports using inventory API\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.receivable,\n                destination_debit=100,)\n    balance.stop()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of 100 after 2006/12/31\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(100, stool.getInventory(\n                              at_date=DateTime(2006, 12, 31),\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    self.assertEqual(1, len(stool.getMovementHistoryList(\n                              at_date=DateTime(2006, 12, 31),\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)))\n    # and 0 before\n    self.assertEqual(0, stool.getInventory(\n                              at_date=DateTime(2005, 12, 31),\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    self.assertEqual(0, len(stool.getMovementHistoryList(\n                              at_date=DateTime(2005, 12, 31),\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)))\n\n\n  def test_BalanceTransactionLineInventoryAPIParentPortalType(self):\n    # related keys like parent_portal_type= can be used in inventory API to get\n    # balance transaction lines\n    balance = self.accounting_module.newContent(\n                          portal_type=\'Balance Transaction\',\n                          destination_section_value=self.section,\n                          start_date=DateTime(2006, 12, 31),\n                          resource_value=self.currency_module.euro,)\n    balance.newContent(\n                portal_type=\'Balance Transaction Line\',\n                destination_value=self.account_module.receivable,\n                destination_debit=100,)\n    balance.stop()\n    self.tic()\n\n    stool = self.portal.portal_simulation\n    # the account \'receivable\' has a balance of 100\n    node_uid = self.account_module.receivable.getUid()\n    self.assertEqual(100, stool.getInventory(\n                              parent_portal_type=\'Balance Transaction\',\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid))\n    # there is one line in getMovementHistoryList:\n    mvt_history_list = stool.getMovementHistoryList(\n                              parent_portal_type=\'Balance Transaction\',\n                              section_uid=self.section.getUid(),\n                              node_uid=node_uid)\n    self.assertEqual(1, len(mvt_history_list))\n\n  def test_TemporaryClosing(self):\n    organisation_module = self.organisation_module\n    stool = self.portal.portal_simulation\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    period.start()\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_credit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_debit=100)))\n\n    self.portal.portal_workflow.doActionFor(\n           period, \'stop_action\',\n           profit_and_loss_account=pl.getRelativeUrl())\n\n    self.tic()\n\n    self.assertEqual(100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=self.account_module.receivable.getUid()))\n\n    self.assertEqual(-100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=pl.getUid()))\n\n    # when period is temporary stopped, a balance transaction is created\n    created_balance_transaction_list = self.portal.accounting_module.contentValues(\n                                    portal_type=\'Balance Transaction\')\n    self.assertEqual(1, len(created_balance_transaction_list))\n\n    self.portal.portal_workflow.doActionFor(\n           period, \'restart_action\' )\n\n    self.tic()\n\n    # when we restart, then this balance transaction is deleted\n    created_balance_transaction_list = self.portal.accounting_module.contentValues(\n                                    portal_type=\'Balance Transaction\')\n    self.assertEqual(0, len(created_balance_transaction_list))\n\n    self.assertEqual(0, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=pl.getUid()))\n    self.assertEqual(100, stool.getInventory(\n                              section_uid=self.section.getUid(),\n                              node_uid=self.account_module.receivable.getUid()))\n\n  def test_ParrallelClosingRefused(self):\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    period.start()\n    period2 = self.section.newContent(portal_type=\'Accounting Period\')\n    period2.setStartDate(DateTime(2007, 1, 1))\n    period2.setStopDate(DateTime(2007, 12, 31))\n    period2.start()\n\n    pl = self.portal.account_module.newContent(\n              portal_type=\'Account\',\n              account_type=\'equity\')\n\n    self._makeOne(\n        start_date=DateTime(2006, 1, 1),\n        destination_section_value=organisation_module.client_1,\n        portal_type=\'Sale Invoice Transaction\',\n        simulation_state=\'delivered\',\n        lines=(dict(source_value=self.account_module.goods_sales,\n                    source_credit=100),\n               dict(source_value=self.account_module.receivable,\n                    source_debit=100)))\n\n    self.portal.portal_workflow.doActionFor(\n           period, \'stop_action\',\n           profit_and_loss_account=pl.getRelativeUrl())\n\n    with self.assertRaisesRegex(ValidationFailed,\n        \'.*Previous accounting periods has to be closed first.*\'):\n      self.getPortal().portal_workflow.doActionFor(\n        period2, \'stop_action\')\n\n  def test_PeriodClosingRefusedWhenTransactionAreNotStopped(self):\n    organisation_module = self.organisation_module\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    period.start()\n\n    self.portal.account_module.newContent(\n      portal_type=\'Account\',\n      account_type=\'equity\')\n\n    self._makeOne(\n      start_date=DateTime(2006, 1, 1),\n      destination_section_value=organisation_module.client_1,\n      portal_type=\'Sale Invoice Transaction\',\n      simulation_state=\'stopped\',\n      lines=(dict(source_value=self.account_module.goods_sales,\n                  source_credit=100),\n             dict(source_value=self.account_module.receivable,\n                  source_debit=100)))\n\n    with self.assertRaisesRegex(\n        ValidationFailed,\n       \'All Accounting Transactions for this organisation during\'\n       \' the period have to be closed first\'):\n      self.portal.portal_workflow.doActionFor(\n        period,\n        \'stop_action\')\n\n  def test_PeriodClosingRefusedWhenTransactionAreNotStoppedIgnoreInternalLine(self):\n    period = self.section.newContent(portal_type=\'Accounting Period\')\n    period.setStartDate(DateTime(2006, 1, 1))\n    period.setStopDate(DateTime(2006, 12, 31))\n    period.start()\n\n    pl = self.portal.account_module.newContent(\n      portal_type=\'Account\',\n      account_type=\'equity\')\n\n    # This transaction has lines that should block closing for `main_section`,\n    # but not for `section` because from `section` side there are no accounting lines.\n    self._makeOne(\n      start_date=DateTime(2006, 1, 1),\n      source_section_value=self.main_section,\n      source_value=self.main_section,\n      destination_section_value=self.section,\n      destination_value=self.section,\n      portal_type=\'Sale Invoice Transaction\',\n      simulation_state=\'stopped\',\n      lines=(dict(source_value=self.account_module.goods_sales,\n                  source_credit=100),\n             dict(source_value=self.account_module.receivable,\n                  source_debit=100)))\n\n    self.portal.portal_workflow.doActionFor(\n      period,\n      \'stop_action\',\n      profit_and_loss_account=pl.getRelativeUrl())\n    self.tic()\n\n\nclass TestAccountingExport(AccountingTestCase):\n  \"\"\"Test accounting export features with erp5_ods_style.\n  \"\"\"\n  def test_export_transaction(self):\n    # test we can export an accounting transaction as ODS\n    accounting_transaction = self._makeOne(lines=(\n              dict(source_value=self.account_module.payable,\n                   quantity=200),))\n    ods_data = accounting_transaction.Base_viewAsODS(\n                    form_id=\'AccountingTransaction_view\')\n    from Products.ERP5OOo.OOoUtils import OOoParser\n    parser = OOoParser()\n    parser.openFromBytes(ods_data)\n    content_xml = parser.oo_files[\'content.xml\']\n    # just make sure that we have the correct account name\n    self.assertEqual(\n        \'40 - Payable\',\n        self.account_module.payable.Account_getFormattedTitle())\n    # check that this account name can be found in the content\n    self.assertIn(b\'40 - Payable\', content_xml)\n    # check that we don\'t have unknown categories\n    self.assertNotIn(b\'???\', content_xml)\n\n\nclass TestTransactions(AccountingTestCase):\n  \"\"\"Test behaviours and utility scripts for Accounting Transactions.\n  \"\"\"\n\n  def getBusinessTemplateList(self):\n    return AccountingTestCase.getBusinessTemplateList(self) + \\\n        (\'erp5_simplified_invoicing\',)\n\n  def _resetIdGenerator(self):\n    # clear all existing ids in portal ids\n    portal_ids = self.portal.portal_ids\n    # ...except uid generator\n    new_uid, = portal_ids.generateNewIdList(\n      id_generator=\'uid\',\n      id_group=\'catalog_uid\',\n      id_count=1,\n    )\n    portal_ids.clearGenerator(all=True)\n    portal_ids.generateNewIdList(\n      id_generator=\'uid\',\n      id_group=\'catalog_uid\',\n      id_count=1,\n      default=new_uid,\n    )\n\n  def test_SourceDestinationReference(self):\n    # Check that source reference and destination reference are filled\n    # automatically.\n    self._resetIdGenerator()\n    section_period_2001 = self.section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2001\',\n                        start_date=DateTime(2001, 1, 1),\n                        stop_date=DateTime(2001, 12, 31))\n    section_period_2001.start()\n    section_period_2002 = self.section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2002\',\n                        start_date=DateTime(2002, 1, 1),\n                        stop_date=DateTime(2002, 12, 31))\n    section_period_2002.start()\n\n    accounting_transaction = self._makeOne(\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2001, 1, 1),\n              stop_date=DateTime(2001, 1, 1))\n    self.portal.portal_workflow.doActionFor(\n          accounting_transaction, \'stop_action\')\n    # The reference generated for the source section uses the short title from\n    # the accounting period\n    self.assertEqual(\'code-2001-1\', accounting_transaction.getSourceReference())\n    # This works, because we use\n    # \'AccountingTransaction_getAccountingPeriodForSourceSection\' script\n    self.assertEqual(section_period_2001, accounting_transaction\\\n              .AccountingTransaction_getAccountingPeriodForSourceSection())\n    # If no accounting period exists on this side, the transaction date is\n    # used.\n    self.assertEqual(\'2001-1\', accounting_transaction.getDestinationReference())\n\n    other_transaction = self._makeOne(\n              destination_section_value=self.organisation_module.client_2,\n              start_date=DateTime(2001, 1, 1),\n              stop_date=DateTime(2001, 1, 1))\n    self.portal.portal_workflow.doActionFor(other_transaction, \'stop_action\')\n    self.assertEqual(\'code-2001-2\', other_transaction.getSourceReference())\n    self.assertEqual(\'2001-1\', other_transaction.getDestinationReference())\n\n    next_year_transaction = self._makeOne(\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2002, 1, 1),\n              stop_date=DateTime(2002, 1, 1))\n    self.portal.portal_workflow.doActionFor(next_year_transaction, \'stop_action\')\n    self.assertEqual(\'code-2002-1\', next_year_transaction.getSourceReference())\n    self.assertEqual(\'2002-1\', next_year_transaction.getDestinationReference())\n\n  def test_SourceDestinationReferenceGroupAccounting(self):\n    # Check that source reference and destination reference are filled\n    # automatically when using multiple sections\n    self._resetIdGenerator()\n    section_period_2001 = self.main_section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2001\',\n                        start_date=DateTime(2001, 1, 1),\n                        stop_date=DateTime(2001, 12, 31))\n    section_period_2001.start()\n    section_period_2002 = self.main_section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2002\',\n                        start_date=DateTime(2002, 1, 1),\n                        stop_date=DateTime(2002, 12, 31))\n    section_period_2002.start()\n\n    accounting_transaction = self._makeOne(\n              source_section_value=self.main_section,\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2001, 1, 1),\n              stop_date=DateTime(2001, 1, 1))\n    self.portal.portal_workflow.doActionFor(\n          accounting_transaction, \'stop_action\')\n    # The reference generated for the source section uses the short title from\n    # the accounting period\n    self.assertEqual(\'code-2001-1\', accounting_transaction.getSourceReference())\n    # This works, because we use\n    # \'AccountingTransaction_getAccountingPeriodForSourceSection\' script\n    self.assertEqual(section_period_2001, accounting_transaction\\\n              .AccountingTransaction_getAccountingPeriodForSourceSection())\n    # If no accounting period exists on this side, the transaction date is\n    # used.\n    self.assertEqual(\'2001-1\', accounting_transaction.getDestinationReference())\n\n    other_section_transaction = self._makeOne(\n              destination_section_value=self.organisation_module.client_2,\n              start_date=DateTime(2001, 1, 1),\n              stop_date=DateTime(2001, 1, 1))\n    self.portal.portal_workflow.doActionFor(other_section_transaction, \'stop_action\')\n    # The numbering is shared by all the sections\n    self.assertEqual(\'code-2001-2\', other_section_transaction.getSourceReference())\n    self.assertEqual(\'2001-1\', other_section_transaction.getDestinationReference())\n\n  def test_SourceDestinationReferenceSecurity(self):\n    # Check that we don\'t need specific roles to set source reference and\n    # destination reference, as long as we can pass the workflow transition\n    self._resetIdGenerator()\n    section_period_2001 = self.section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2001\',\n                        start_date=DateTime(2001, 1, 1),\n                        stop_date=DateTime(2001, 12, 31))\n    section_period_2001.start()\n\n    accounting_transaction = self._makeOne(\n              destination_section_value=self.organisation_module.client_1,\n              start_date=DateTime(2001, 1, 1),\n              stop_date=DateTime(2001, 1, 1))\n    accounting_transaction.manage_permission(\'Modify portal content\',\n                                             roles=[\'Manager\'], acquire=0)\n    self.assertFalse(_checkPermission(\'Modify portal content\',\n                                      accounting_transaction))\n    accounting_transaction.stop()\n    self.assertEqual(\'code-2001-1\', accounting_transaction.getSourceReference())\n\n  def test_SearchableText(self):\n    accounting_transaction = self._makeOne(title=\'A new Transaction\',\n                                description=\"A description\",\n                                comment=\"Some comments\")\n    searchable_text = accounting_transaction.SearchableText()\n    self.assertIn(\'A new Transaction\', searchable_text)\n    self.assertIn(\'A description\', searchable_text)\n    self.assertIn(\'Some comments\', searchable_text)\n\n\n  def test_Organisation_getMappingRelatedOrganisation(self):\n    # the main section needs an accounting period to be treated as mapping\n    # related by Organisation_getMappingRelatedOrganisation\n    self.main_section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2001\',\n                        start_date=DateTime(2001, 1, 1),\n                        stop_date=DateTime(2001, 12, 31))\n\n    self.assertEqual(self.main_section,\n        self.section.Organisation_getMappingRelatedOrganisation())\n    self.assertEqual(self.main_section,\n        self.main_section.Organisation_getMappingRelatedOrganisation())\n\n    client = self.organisation_module.client_2\n    self.assertEqual(None, client.getGroupValue())\n    self.assertEqual(client,\n        client.Organisation_getMappingRelatedOrganisation())\n\n\n  # tests for Invoice_createRelatedPaymentTransaction\n  def _checkRelatedSalePayment(self, invoice, payment, payment_node, quantity):\n    \"\"\"Check payment of a Sale Invoice.\n    \"\"\"\n    eq = self.assertEqual\n    eq(\'Payment Transaction\', payment.getPortalTypeName())\n    eq([invoice], payment.getCausalityValueList())\n    eq(invoice.getSourceSection(), payment.getSourceSection())\n    eq(invoice.getDestinationSection(), payment.getDestinationSection())\n    eq(payment_node, payment.getSourcePaymentValue())\n    eq(self.getCategoryTool().payment_mode.check,\n       payment.getPaymentModeValue())\n    # test lines\n    eq(2, len(payment.getMovementList()))\n    for line in payment.getMovementList():\n      if line.getId() == \'bank\':\n        eq(quantity, line.getSourceCredit())\n        eq(self.account_module.bank, line.getSourceValue())\n      else:\n        eq(quantity, line.getSourceDebit())\n        eq(self.account_module.receivable, line.getSourceValue())\n    # this transaction can be validated\n    eq([], payment.checkConsistency())\n    self.portal.portal_workflow.doActionFor(payment, \'stop_action\')\n    eq(\'stopped\', payment.getSimulationState())\n\n  def test_Invoice_createRelatedPaymentTransactionSimple(self):\n    # Simple case of creating a related payment transaction.\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100)))\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self._checkRelatedSalePayment(invoice, payment, payment_node, 100)\n\n  def test_Invoice_createRelatedPaymentTransactionGroupedLines(self):\n    # Simple creating a related payment transaction when grouping reference of\n    # some lines is already set.\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=60),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=40,\n                           grouping_reference=\'A\'),))\n\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self._checkRelatedSalePayment(invoice, payment, payment_node, 60)\n\n  def test_Invoice_createRelatedPaymentTransactionDifferentSection(self):\n    # Simple creating a related payment transaction when we have two line for\n    # 2 different destination sections.\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=60),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=40,\n                           destination_section_value=self.organisation_module.client_2),))\n\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self._checkRelatedSalePayment(invoice, payment, payment_node, 60)\n\n  def test_Invoice_createRelatedPaymentTransactionRelatedInvoice(self):\n    # Simple creating a related payment transaction when we have related\n    # transactions.\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100),))\n    accounting_transaction = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               causality_value=invoice,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_credit=20),\n                      dict(source_value=self.account_module.receivable,\n                           source_debit=20),))\n\n    accounting_transaction.setCausalityValue(invoice)\n    self.portal.portal_workflow.doActionFor(accounting_transaction,\n                                           \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n    self.tic()\n\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self._checkRelatedSalePayment(invoice, payment, payment_node, 80)\n\n  def test_Invoice_createRelatedPaymentTransactionRelatedInvoiceDifferentSide(self):\n    # Simple creating a related payment transaction when we have related\n    # transactions with different side\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100),))\n    accounting_transaction = self._makeOne(\n               source_section_value=self.organisation_module.client_1,\n               destination_section_value=self.section,\n               causality_value=invoice,\n               lines=(dict(destination_value=self.account_module.goods_purchase,\n                           destination_credit=20),\n                      dict(destination_value=self.account_module.receivable,\n                           destination_debit=20),))\n    self.portal.portal_workflow.doActionFor(accounting_transaction,\n                                            \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n    self.tic()\n\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self._checkRelatedSalePayment(invoice, payment, payment_node, 80)\n\n  def test_Invoice_createRelatedPaymentTransactionRelatedInvoiceDraft(self):\n    # Simple creating a related payment transaction when we have related\n    # transactions in draft/cancelled state (they are ignored)\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100),))\n    self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               causality_value=invoice,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_credit=20),\n                      dict(source_value=self.account_module.receivable,\n                           source_debit=20),))\n\n    other_accounting_transaction = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               causality_value=invoice,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_credit=20),\n                      dict(source_value=self.account_module.receivable,\n                           source_debit=20),))\n\n    other_accounting_transaction.cancel()\n    self.tic()\n\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self._checkRelatedSalePayment(invoice, payment, payment_node, 100)\n\n  def test_Invoice_createRelatedPaymentTransactionDifferentCurrency(self):\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               resource_value=self.portal.currency_module.usd,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100,\n                           source_asset_debit=150),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           source_asset_credit=150),))\n\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self.assertEqual(self.portal.currency_module.usd,\n                      payment.getResourceValue())\n    line_list = payment.getMovementList()\n    self.assertEqual(2, len(line_list))\n    for line in line_list:\n      if line.getSourceValue() == self.account_module.receivable:\n        self.assertEqual(100, line.getSourceDebit())\n        # there\'s no asset price\n        self.assertEqual(None, line.getSourceTotalAssetPrice())\n      else:\n        self.assertEqual(self.account_module.bank, line.getSourceValue())\n        self.assertEqual(100, line.getSourceCredit())\n        self.assertEqual(None, line.getSourceTotalAssetPrice())\n\n  # tests for Invoice_getRemainingTotalPayablePrice\n  def test_Invoice_getRemainingTotalPayablePriceDeletedPayment(self):\n    \"\"\"Checks in case of deleted Payments related to invoice\"\"\"\n    # Simple case of creating a related payment transaction.\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n    payment_node.validate()\n    self.tic()\n    invoice = self._makeOne(\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100)))\n    payment = invoice.Invoice_createRelatedPaymentTransaction(\n                                  node=self.account_module.bank.getRelativeUrl(),\n                                  payment=payment_node.getRelativeUrl(),\n                                  payment_mode=\'check\',\n                                  batch_mode=1)\n    self.tic()\n    remaining_price = invoice.Invoice_getRemainingTotalPayablePrice()\n    self.assertEqual(-100, remaining_price)\n    payment.delete()\n    self.tic()\n    remaining_price = invoice.Invoice_getRemainingTotalPayablePrice()\n    self.assertEqual(-100, remaining_price)\n\n  # tests for Grouping References\n  def test_GroupingReferenceResetedOnCopyPaste(self):\n    accounting_module = self.portal.accounting_module\n    for portal_type in accounting_module.getVisibleAllowedContentTypeList():\n      accounting_transaction = accounting_module.newContent(\n                            portal_type=portal_type)\n      accounting_transaction.newContent(\n                  id = \'line_with_grouping_reference\',\n                  grouping_reference=\'A\',\n                  grouping_date=DateTime(),\n                  portal_type=transaction_to_line_mapping[portal_type])\n\n      cp = accounting_module.manage_copyObjects(ids=[accounting_transaction.getId()])\n      copy_id = accounting_module.manage_pasteObjects(cp)[0][\'new_id\']\n      self.assertFalse(accounting_module[copy_id]\\\n          .line_with_grouping_reference.getGroupingReference())\n      self.assertFalse(accounting_module[copy_id]\\\n          .line_with_grouping_reference.getGroupingDate())\n\n  def test_AccountingTransaction_lineResetGroupingReference(self):\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_with_grouping_reference\',\n                           grouping_date=DateTime(),\n                           grouping_reference=\'A\'),))\n    invoice_line = invoice.line_with_grouping_reference\n\n    other_account_invoice = self._makeOne(\n               title=\'Other Account Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.goods_sales,\n                           source_credit=100,\n                           id=\'line_with_grouping_reference\',\n                           grouping_date=DateTime(),\n                           grouping_reference=\'A\'),))\n    other_account_line = other_account_invoice.line_with_grouping_reference\n\n    other_section_invoice = self._makeOne(\n               title=\'Other Section Invoice\',\n               destination_section_value=self.organisation_module.client_2,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_with_grouping_reference\',\n                           grouping_date=DateTime(),\n                           grouping_reference=\'A\'),))\n    other_section_line = other_section_invoice.line_with_grouping_reference\n\n    other_letter_invoice = self._makeOne(\n               title=\'Other letter Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_with_grouping_reference\',\n                           grouping_date=DateTime(),\n                           grouping_reference=\'B\'),))\n    other_letter_line = other_letter_invoice.line_with_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_with_grouping_reference\',\n                           grouping_reference=\'A\',\n                           grouping_date=DateTime(),\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_with_grouping_reference\n\n    # reset from the payment line, the invoice line from the same group will be\n    # ungrouped\n    payment_line.AccountingTransactionLine_resetGroupingReference(asynchronous=False)\n    self.assertFalse(payment_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingDate())\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(invoice_line.getGroupingDate())\n\n    # other lines are not touched:\n    self.assertTrue(other_account_line.getGroupingReference())\n    self.assertTrue(other_account_line.getGroupingDate())\n    self.assertTrue(other_section_line.getGroupingReference())\n    self.assertTrue(other_section_line.getGroupingDate())\n    self.assertTrue(other_letter_line.getGroupingDate())\n\n  def test_GroupingReferenceResetedOnCancelWithDeleteRaceCondition(self):\n    \"\"\"Reproduction for a bug when transaction is cancelled and grouped line\n    is deleted before the reset-grouping-reference activity is executed, the\n    related grouped lines where not reset.\n    \"\"\"\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_with_grouping_reference\',\n                           grouping_date=DateTime(),\n                           grouping_reference=\'A\'),))\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_with_grouping_reference\',\n                           grouping_reference=\'A\',\n                           grouping_date=DateTime(),\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    self.tic()\n    invoice.cancel()\n    invoice.manage_delObjects([line.getId() for line in invoice.contentValues()])\n    self.tic()\n    self.assertFalse(payment.line_with_grouping_reference.getGroupingReference())\n\n  def test_grouping_reference_partial_grouping(self):\n    \"\"\"Check that automatic guess can group only some matching lines\n    \"\"\"\n    invoice = self._makeOne(\n               title=\'Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                          source_debit=0.3),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=0.3,\n                           id=\'line_1\')))\n    self.portal.portal_workflow._jumpToStateFor(invoice, \'stopped\')\n    payment = self._makeOne(\n               title=\'Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_2\',\n                           source_debit=0.3),\n                      dict(source_value=self.account_module.receivable,\n                           id=\'line_3\',\n                           source_credit=0.1),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=0.2,)))\n    self.portal.portal_workflow._jumpToStateFor(payment, \'stopped\')\n    self.tic()\n\n    # Ensure we are in the expected state\n    self.assertFalse(invoice.line_1.getGroupingReference())\n    self.assertFalse(payment.line_2.getGroupingReference())\n    self.assertFalse(payment.line_3.getGroupingReference())\n\n    # If lines are explicitely provided, no partial grouping is done\n    grouped = invoice.AccountingTransaction_guessGroupedLines(\n      accounting_transaction_line_uid_list=(\n        invoice.line_1.getUid(),\n        payment.line_2.getUid(),\n        payment.line_3.getUid(),\n    ))\n    self.assertEqual(\n      sorted(grouped),\n      sorted([])\n    )\n    self.assertFalse(invoice.line_1.getGroupingReference())\n    self.assertFalse(payment.line_2.getGroupingReference())\n    self.assertFalse(payment.line_3.getGroupingReference())\n\n    # If no lines are explicitely provided, partial grouping is executed\n    # and it will search accounting transaction with the causality relation\n    grouped = invoice.AccountingTransaction_guessGroupedLines()\n    self.assertEqual(\n      sorted(grouped),\n      sorted([])\n    )\n    self.assertFalse(invoice.line_1.getGroupingReference())\n    self.assertFalse(payment.line_2.getGroupingReference())\n    self.assertFalse(payment.line_3.getGroupingReference())\n\n    # So, set the causality relation to help\n    payment.setCausalityValue(invoice)\n    self.tic()\n    grouped = invoice.AccountingTransaction_guessGroupedLines()\n    self.assertEqual(\n      sorted(grouped),\n      sorted([\n        invoice.line_1.getRelativeUrl(),\n        payment.line_2.getRelativeUrl(),\n    ]))\n\n    self.assertTrue(invoice.line_1.getGroupingReference())\n    self.assertTrue(payment.line_2.getGroupingReference())\n    self.assertFalse(payment.line_3.getGroupingReference())\n    self.assertEqual(invoice.line_1.getGroupingReference(),\n                     payment.line_2.getGroupingReference())\n\n    self.tic()\n\n  def test_grouping_reference_rounding(self):\n    \"\"\"Reproduction of a bug that grouping was not possible because of rounding error\n\n    >>> 0.1 + 0.2 - 0.3 == 0\n    False\n    \"\"\"\n    invoice = self._makeOne(\n               title=\'Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                          source_debit=0.3),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=0.1,\n                           id=\'line_1\'),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=0.2,\n                           id=\'line_2\')))\n    payment = self._makeOne(\n               title=\'Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_3\',\n                           source_debit=0.3),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=0.3,)))\n    self.tic()\n    grouped = invoice.AccountingTransaction_guessGroupedLines(\n      accounting_transaction_line_uid_list=(\n        invoice.line_1.getUid(),\n        invoice.line_2.getUid(),\n        payment.line_3.getUid(),\n    ))\n    self.assertEqual(\n      sorted(grouped),\n      sorted([\n        invoice.line_1.getRelativeUrl(),\n        invoice.line_2.getRelativeUrl(),\n        payment.line_3.getRelativeUrl(),\n    ]))\n    self.tic()\n\n  def test_grouping_reference_rounding_without_accounting_currency_on_section(self):\n    accounting_currency = self.section.getPriceCurrency()\n    self.assertTrue(accounting_currency)\n    self.section.setPriceCurrency(None)\n    try:\n      self.test_grouping_reference_rounding()\n    finally:\n      self.abort()\n      self.section.setPriceCurrency(accounting_currency)\n      self.tic()\n\n  def test_automatically_setting_grouping_reference(self):\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               start_date=DateTime(2012, 1, 2),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               start_date=DateTime(2012, 1, 3),\n               causality_value=invoice,\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(invoice_line.getGroupingDate())\n    self.assertFalse(payment_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingDate())\n\n    # lines match, they are automatically grouped\n    invoice.stop()\n    self.assertTrue(invoice_line.getGroupingReference())\n    self.assertTrue(payment_line.getGroupingReference())\n    self.assertEqual(invoice_line.getGroupingReference(),\n                     payment_line.getGroupingReference())\n    # the grouping date is set to the latest date of all grouped lines\n    self.assertEqual(DateTime(2012, 1, 3), invoice_line.getGroupingDate())\n    self.assertEqual(DateTime(2012, 1, 3), payment_line.getGroupingDate())\n\n    # when restarting, grouping is removed\n    invoice.restart()\n    self.tic()\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(invoice_line.getGroupingDate())\n    self.assertFalse(payment_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingDate())\n\n    # when stopping again, grouping is set again\n    invoice.stop()\n    self.assertTrue(invoice_line.getGroupingReference())\n    self.assertTrue(payment_line.getGroupingReference())\n    self.assertEqual(invoice_line.getGroupingReference(),\n                     payment_line.getGroupingReference())\n    self.assertEqual(DateTime(2012, 1, 3), invoice_line.getGroupingDate())\n    self.assertEqual(DateTime(2012, 1, 3), payment_line.getGroupingDate())\n\n  def test_automatically_setting_grouping_reference_same_group(self):\n    # invoice is for section, payment is for main_section\n\n    # the main section needs an accounting period to be treated as mapping\n    # related by Organisation_getMappingRelatedOrganisation\n    self.main_section.newContent(\n                        portal_type=\'Accounting Period\',\n                        short_title=\'code-2001\',\n                        start_date=DateTime(2001, 1, 1),\n                        stop_date=DateTime(2001, 12, 31))\n\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               causality_value=invoice,\n               source_section_value=self.main_section,\n               source_payment_value=self.main_section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n    # lines match, they are automatically grouped\n    invoice.stop()\n    self.assertTrue(invoice_line.getGroupingReference())\n    self.assertTrue(payment_line.getGroupingReference())\n    self.assertEqual(invoice_line.getGroupingReference(),\n                     payment_line.getGroupingReference())\n\n    # when restarting, grouping is removed\n    invoice.restart()\n    self.tic()\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n    invoice.stop()\n    self.assertTrue(invoice_line.getGroupingReference())\n    self.assertTrue(payment_line.getGroupingReference())\n    self.assertEqual(invoice_line.getGroupingReference(),\n                     payment_line.getGroupingReference())\n\n  def test_automatically_setting_grouping_reference_only_related(self):\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               # payment is not related with invoice, so no automatic grouping\n               # will occur\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n    invoice.stop()\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n  def test_automatically_setting_grouping_reference_same_section(self):\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               causality_value=invoice,\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_2,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n    # different sections, no grouping\n    invoice.stop()\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n  def test_automatically_unsetting_grouping_reference_when_cancelling(self):\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               causality_value=invoice,\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    invoice.stop()\n    self.assertTrue(invoice_line.getGroupingReference())\n    self.assertTrue(payment_line.getGroupingReference())\n\n    invoice.cancel()\n    self.tic()\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n  def test_automatically_setting_grouping_reference_in_one_invoice(self):\n    # this invoice will group it itself\n    invoice = self._makeOne(\n               title=\'One Invoice\',\n               simulation_state=\'stopped\',\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100, )))\n    self.tic()\n    for line in invoice.contentValues():\n      self.assertTrue(line.getGroupingReference())\n\n    invoice.restart()\n    self.tic()\n    for line in invoice.contentValues():\n      self.assertFalse(line.getGroupingReference())\n\n    invoice.stop()\n    self.tic()\n    for line in invoice.contentValues():\n      self.assertTrue(line.getGroupingReference())\n\n  def test_automatically_setting_grouping_reference_when_same_ledger(self):\n    self.setUpLedger()\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               ledger_value=self.portal.portal_categories.ledger.accounting.general,\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               causality_value=invoice,\n               ledger_value=self.portal.portal_categories.ledger.accounting.general,\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    invoice.stop()\n    self.assertTrue(invoice_line.getGroupingReference())\n    self.assertTrue(payment_line.getGroupingReference())\n    self.assertEqual(invoice_line.getGroupingReference(),\n                     payment_line.getGroupingReference())\n\n  def test_not_automatically_setting_grouping_reference_when_different_ledger(self):\n    self.setUpLedger()\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               ledger_value=self.portal.portal_categories.ledger.accounting.general,\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_for_grouping_reference\',)))\n    invoice_line = invoice.line_for_grouping_reference\n\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               simulation_state=\'delivered\',\n               causality_value=invoice,\n               ledger_value=self.portal.portal_categories.ledger.accounting.detailed,\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_for_grouping_reference\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    payment_line = payment.line_for_grouping_reference\n\n    invoice.stop()\n    self.assertFalse(invoice_line.getGroupingReference())\n    self.assertFalse(payment_line.getGroupingReference())\n\n  def test_roundDebitCredit_does_nothing_if_big_difference(self):\n    invoice = self._makeOne(\n      portal_type=\'Sale Invoice Transaction\',\n      lines=(dict(source_value=self.account_module.goods_sales,\n                source_debit=100.032345),\n           dict(source_value=self.account_module.receivable,\n                source_credit=100.000001)))\n    invoice.newContent(portal_type=\'Invoice Line\', quantity=1, price=100)\n    self.assertEqual(\n      sorted([\n        m.getQuantity() for m in invoice.getMovementList(\n          portal_type=\'Sale Invoice Transaction Line\')]),\n      [-100.032345, 100.000001])\n\n  def test_roundDebitCredit_when_payable_is_different_total_price(self):\n    invoice = self._makeOne(\n      portal_type=\'Purchase Invoice Transaction\',\n      stop_date=DateTime(),\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.supplier,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                id=\"expense\",\n                destination_debit=100.000001),\n           dict(source_value=self.account_module.payable,\n                id=\"payable\",\n                destination_credit=100.012345)))\n    precision = invoice.getQuantityPrecisionFromResource(invoice.getResource())\n    invoice.newContent(portal_type=\'Invoice Line\', quantity=1, price=100)\n    line_list = invoice.getMovementList(\n                    portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertNotEqual(0.0,\n      sum([round(g.getQuantity(), precision) for g in line_list]))\n    invoice.AccountingTransaction_roundDebitCredit()\n    line_list = invoice.getMovementList(\n                 portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertEqual(0.0,\n      sum([round(g.getQuantity(), precision) for g in line_list]))\n    self.assertEqual(100.00, invoice.payable.getDestinationCredit())\n    self.assertEqual(100.00, invoice.expense.getDestinationDebit())\n    self.assertEqual([], invoice.checkConsistency())\n\n  def test_roundDebitCredit_when_payable_is_equal_total_price(self):\n    invoice = self._makeOne(\n      portal_type=\'Purchase Invoice Transaction\',\n      stop_date=DateTime(),\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.supplier,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                id=\"expense\",\n                destination_debit=100.012345),\n           dict(source_value=self.account_module.payable,\n                id=\"payable\",\n               destination_credit=100.000001)))\n    precision = invoice.getQuantityPrecisionFromResource(invoice.getResource())\n    invoice.newContent(portal_type=\'Invoice Line\', quantity=1, price=100)\n    line_list = invoice.getMovementList(\n                    portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertNotEqual(0.0,\n      sum([round(g.getQuantity(), precision) for g in line_list]))\n    invoice.AccountingTransaction_roundDebitCredit()\n    line_list = invoice.getMovementList(\n                 portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertEqual(0.0,\n      sum([round(g.getQuantity(), precision) for g in line_list]))\n    self.assertEqual(100.00, invoice.payable.getDestinationCredit())\n    self.assertEqual(100.00, invoice.expense.getDestinationDebit())\n    self.assertEqual([], invoice.checkConsistency())\n\n  def test_roundDebitCredit_when_receivable_is_equal_total_price(self):\n    invoice = self._makeOne(\n      portal_type=\'Sale Invoice Transaction\',\n      stop_date=DateTime(),\n      destination_section_value=self.section,\n      source_section_value=self.section,\n      lines=(dict(source_value=self.account_module.goods_sales,\n                id=\"income\",\n                source_credit=100.012345),\n           dict(source_value=self.account_module.receivable,\n                id=\"receivable\",\n                source_debit=100.000001)))\n    precision = invoice.getQuantityPrecisionFromResource(invoice.getResource())\n    invoice.newContent(portal_type=\'Invoice Line\', quantity=1, price=100)\n    line_list = invoice.getMovementList(\n                    portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertNotEqual(sum([round(g.getQuantity(), precision) for g in line_list]),\n      0.0)\n    invoice.AccountingTransaction_roundDebitCredit()\n    line_list = invoice.getMovementList(\n                 portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertEqual(sum([round(g.getQuantity(), precision) for g in line_list]),\n      0.0)\n    self.assertEqual(100.00, invoice.income.getSourceCredit())\n    self.assertEqual(100.00, invoice.receivable.getSourceDebit())\n    self.assertEqual([], invoice.checkConsistency())\n\n  def test_roundDebitCredit_when_receivable_is_different_total_price(self):\n    invoice = self._makeOne(\n      portal_type=\'Sale Invoice Transaction\',\n      stop_date=DateTime(),\n      destination_section_value=self.section,\n      source_section_value=self.section,\n      lines=(dict(source_value=self.account_module.goods_sales,\n                id=\"income\",\n                source_credit=100.000001),\n           dict(source_value=self.account_module.receivable,\n                id=\"receivable\",\n                source_debit=100.012345)))\n    precision = invoice.getQuantityPrecisionFromResource(invoice.getResource())\n    invoice.newContent(portal_type=\'Invoice Line\', quantity=1, price=100)\n    line_list = invoice.getMovementList(\n                    portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertNotEqual(sum([round(g.getQuantity(), precision) for g in line_list]),\n      0.0)\n    invoice.AccountingTransaction_roundDebitCredit()\n    line_list = invoice.getMovementList(\n                 portal_type=invoice.getPortalAccountingMovementTypeList())\n    self.assertEqual(sum([round(g.getQuantity(), precision) for g in line_list]),\n      0.0)\n    self.assertEqual(100.00, invoice.income.getSourceCredit())\n    self.assertEqual(100.00, invoice.receivable.getSourceDebit())\n    self.assertEqual([], invoice.checkConsistency())\n\n  def test_AccountingTransaction_getTotalDebitCredit(self):\n    # source view\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           source_credit=400)))\n    self.assertTrue(accounting_transaction.AccountingTransaction_isSourceView())\n    self.assertEqual(500, accounting_transaction.AccountingTransaction_getTotalDebit())\n    self.assertEqual(400, accounting_transaction.AccountingTransaction_getTotalCredit())\n\n    # destination view\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               source_section_value=self.organisation_module.client_1,\n               destination_section_value=self.section,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           destination_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           destination_credit=400)))\n    self.assertFalse(accounting_transaction.AccountingTransaction_isSourceView())\n    self.assertEqual(500, accounting_transaction.AccountingTransaction_getTotalDebit())\n    self.assertEqual(400, accounting_transaction.AccountingTransaction_getTotalCredit())\n\n    # source view, with conversion on our side\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           source_asset_debit=50,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           source_asset_credit=40,\n                           source_credit=400)))\n    self.assertTrue(accounting_transaction.AccountingTransaction_isSourceView())\n    self.assertEqual(50, accounting_transaction.AccountingTransaction_getTotalDebit())\n    self.assertEqual(40, accounting_transaction.AccountingTransaction_getTotalCredit())\n\n    # destination view, with conversion on our side\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               source_section_value=self.organisation_module.client_1,\n               destination_section_value=self.section,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           destination_asset_debit=50,\n                           destination_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           destination_asset_credit=40,\n                           destination_credit=400)))\n    self.assertFalse(accounting_transaction.AccountingTransaction_isSourceView())\n    self.assertEqual(50, accounting_transaction.AccountingTransaction_getTotalDebit())\n    self.assertEqual(40, accounting_transaction.AccountingTransaction_getTotalCredit())\n\n    # source view, with conversion on other side\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               destination_section_value=self.organisation_module.client_1,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           destination_asset_debit=50,\n                           source_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           destination_asset_credit=40,\n                           source_credit=400)))\n    self.assertTrue(accounting_transaction.AccountingTransaction_isSourceView())\n    self.assertEqual(500, accounting_transaction.AccountingTransaction_getTotalDebit())\n    self.assertEqual(400, accounting_transaction.AccountingTransaction_getTotalCredit())\n\n    # destination view, with conversion on other side\n    accounting_transaction = self._makeOne(\n               portal_type=\'Accounting Transaction\',\n               start_date=DateTime(\'2007/01/02\'),\n               source_section_value=self.organisation_module.client_1,\n               destination_section_value=self.section,\n               lines=(dict(source_value=self.account_module.payable,\n                           destination_value=self.account_module.receivable,\n                           source_asset_debit=50,\n                           destination_debit=500),\n                      dict(source_value=self.account_module.receivable,\n                           destination_value=self.account_module.payable,\n                           source_asset_credit=40,\n                           destination_credit=400)))\n    self.assertFalse(accounting_transaction.AccountingTransaction_isSourceView())\n    self.assertEqual(500, accounting_transaction.AccountingTransaction_getTotalDebit())\n    self.assertEqual(400, accounting_transaction.AccountingTransaction_getTotalCredit())\n\n  def test_AccountingTransaction_getListBoxColumnList_does_not_enable_section_column_when_only_two_sections(self):\n    # AccountingTransaction_getListBoxColumnList is the script returning the\n    # columns to display in AccountingTransaction_view.\n    at = self._makeOne(\n      portal_type=\'Accounting Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    self.assertNotIn(\n      (\'getDestinationSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=True))\n    self.assertNotIn(\n      (\'getSourceSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=False))\n\n  def test_AccountingTransaction_getListBoxColumnList_enables_destination_section_column_when_more_than_two_sections(self):\n    # AccountingTransaction_getListBoxColumnList is the script returning the\n    # columns to display in AccountingTransaction_view.\n    at = self._makeOne(\n      portal_type=\'Accounting Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  destination_section_value=self.organisation_module.client_2,\n                  source_credit=500)))\n    # Only the source view have one extra column, because from destination point\n    # of view, there is only one mirror section\n    self.assertIn(\n      (\'getDestinationSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=True))\n    self.assertNotIn(\n      (\'getSourceSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=False))\n\n  def test_AccountingTransaction_getListBoxColumnList_enables_source_section_column_when_more_than_two_sections(self):\n    at = self._makeOne(\n      portal_type=\'Accounting Transaction\',\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.client_1,\n      lines=(dict(destination_value=self.account_module.goods_purchase,\n                  destination_debit=500),\n             dict(destination_value=self.account_module.receivable,\n                  source_section_value=self.organisation_module.client_2,\n                  destination_credit=500)))\n    # Only the destination view have one extra column, because from source point\n    # of view, there is only one mirror section\n    self.assertNotIn(\n      (\'getDestinationSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=True))\n    self.assertIn(\n      (\'getSourceSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=False))\n\n  def test_AccountingTransaction_getListBoxColumnList_enables_source_section_column_when_same_section_both_sides(self):\n    # Edge case, source section from the transaction is also used as destination section on a line\n    # does not make much sense, but have to be visible when looking at transaction\n    at = self._makeOne(\n      portal_type=\'Accounting Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  destination_section_value=self.section, # Source section is also destination section here\n                  source_credit=500)))\n    self.assertIn(\n      (\'getDestinationSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=True))\n    self.assertNotIn(\n      (\'getSourceSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=False))\n\n  def test_AccountingTransaction_getListBoxColumnList_enables_destination_section_column_when_same_section_both_sides(self):\n    # Edge case, destination section from the transaction is also used as source section on a line\n    # does not make much sense, but have to be visible when looking at transaction\n    at = self._makeOne(\n      portal_type=\'Accounting Transaction\',\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.client_1,\n      lines=(dict(destination_value=self.account_module.goods_purchase,\n                  destination_debit=500),\n             dict(destination_value=self.account_module.receivable,\n                  source_section_value=self.section, # Destination section is also here section here\n                  destination_credit=500)))\n    self.assertNotIn(\n      (\'getDestinationSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=True))\n    self.assertIn(\n      (\'getSourceSectionTitle\', \'Third Party\'),\n      at.AccountingTransaction_getListBoxColumnList(source=False))\n\n  def test_AccountingTransaction_getListBoxColumnList_item_column(self):\n    item1 = self.portal.item_module.newContent(title=\'Item 1\')\n    item2 = self.portal.item_module.newContent(title=\'Item 2\')\n    aggregate_column_item = (\'aggregate_title_list\', \'Items\')\n\n    for view_id, at in (\n        (\n            \'view\',\n            self._makeOne(\n                portal_type=\'Accounting Transaction\',\n                source_section_value=self.section,\n                destination_section_value=self.organisation_module.client_1,\n                lines=(dict(id=\'line_with_aggregate\',\n                            source_value=self.account_module.goods_purchase,\n                            source_debit=500),\n                       dict(source_value=self.account_module.receivable,\n                            source_credit=500))),\n        ),\n        (\n            \'SaleInvoiceTransaction_viewAccounting\',\n            self._makeOne(\n                portal_type=\'Sale Invoice Transaction\',\n                source_section_value=self.section,\n                destination_section_value=self.organisation_module.client_1,\n                lines=(dict(id=\'line_with_aggregate\',\n                            source_value=self.account_module.goods_purchase,\n                            source_debit=500),\n                       dict(source_value=self.account_module.receivable,\n                            source_credit=500))),\n        ),\n        (\n            \'view\',\n            self._makeOne(\n                portal_type=\'Payment Transaction\',\n                source_section_value=self.section,\n                destination_section_value=self.organisation_module.client_1,\n                lines=(dict(id=\'line_with_aggregate\',\n                            source_value=self.account_module.goods_purchase,\n                            source_debit=500),\n                       dict(source_value=self.account_module.receivable,\n                            source_credit=500))),\n        ),\n        (\n            \'PurchaseInvoiceTransaction_viewAccounting\',\n            self._makeOne(\n                portal_type=\'Purchase Invoice Transaction\',\n                destination_section_value=self.section,\n                source_section_value=self.organisation_module.supplier,\n                lines=(dict(id=\'line_with_aggregate\',\n                            source_value=self.account_module.goods_purchase,\n                            source_debit=500),\n                       dict(source_value=self.account_module.receivable,\n                            source_credit=500))),\n        ),\n    ):\n      self.assertNotIn(\n          aggregate_column_item,\n          at.AccountingTransaction_getListBoxColumnList(source=True),\n      )\n      self.assertNotIn(\n          aggregate_column_item,\n          at.AccountingTransaction_getListBoxColumnList(source=False),\n      )\n\n      at.line_with_aggregate.setAggregateValueList((item1, item2))\n      html = getattr(at, view_id)()\n      tree = lxml.etree.parse(StringIO(html), lxml.etree.HTMLParser())\n      self.assertIn(\n          aggregate_column_item,\n          at.AccountingTransaction_getListBoxColumnList(source=True),\n      )\n      self.assertIn(\n          aggregate_column_item,\n          at.AccountingTransaction_getListBoxColumnList(source=False),\n      )\n      self.assertEqual(\n          tree.xpath(\n              \'//table[contains(@class, \"listbox-table\")]/thead/tr/th/text()\'),\n          [u\'\\xa0\', \'ID\', \'Account\', \'Items\', \'Debit\', \'Credit\'],\n      )\n      self.assertEqual(\n          tree.xpath(\n              \'//table[contains(@class, \"listbox-table\")]/tbody/tr[1]/td[4]/a/div/text()\'\n          ),\n          [\'Item 1\', \'Item 2\'],\n      )\n\n  def test_AccountingTransaction_getSourcePaymentItemList(self):\n    # AccountingTransaction_getSourcePaymentItemList allows to select bank accounts\n    # from section\n    bank_account = self.section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'BA-1\'\n    )\n    bank_account.validate()\n    self.tic()\n\n    at = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    self.assertIn(\n      (\'BA-1\', bank_account.getRelativeUrl()),\n      at.AccountingTransaction_getSourcePaymentItemList())\n\n  def test_AccountingTransaction_getDestinationPaymentItemList(self):\n    # AccountingTransaction_getDestinationPaymentItemList allows to select bank accounts\n    # from destination section\n    bank_account = self.section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'BA-1\'\n    )\n    bank_account.validate()\n    self.tic()\n\n    at = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.client_1,\n      lines=(dict(destination_value=self.account_module.goods_purchase,\n                  destination_debit=500),\n             dict(destination_value=self.account_module.receivable,\n                  destination_credit=500)))\n    self.assertIn(\n      (\'BA-1\', bank_account.getRelativeUrl()),\n      at.AccountingTransaction_getDestinationPaymentItemList())\n\n  def test_AccountingTransaction_getSourcePaymentItemList_no_section(self):\n    bank_account = self.section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'BA-1\'\n    )\n    bank_account.validate()\n    self.tic()\n\n    at = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    at.setSourceSectionValue(None)\n    at.setDestinationSectionValue(None)\n    self.assertEqual(\n      at.AccountingTransaction_getSourcePaymentItemList(), [(\'\', \'\')])\n    self.assertEqual(\n      at.AccountingTransaction_getDestinationPaymentItemList(), [(\'\', \'\')])\n\n  def test_AccountingTransaction_getSourcePaymentItemList_person_member_of_group(self):\n    bank_account = self.main_section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'should not be displayed\'\n    )\n    bank_account.validate()\n    self.tic()\n\n    source_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.person_module.john_smith,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    self.assertEqual(\n      source_transaction.AccountingTransaction_getSourcePaymentItemList(), [(\'\', \'\')])\n\n    destination_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      destination_section_value=self.section,\n      source_section_value=self.person_module.john_smith,\n      lines=(dict(destination_value=self.account_module.goods_purchase,\n                  destination_debit=500),\n             dict(destination_value=self.account_module.receivable,\n                  destination_credit=500)))\n    self.assertEqual(\n      destination_transaction.AccountingTransaction_getDestinationPaymentItemList(), [(\'\', \'\')])\n\n  def test_AccountingTransaction_getSourcePaymentItemList_parent_section(self):\n    # AccountingTransaction_getSourcePaymentItemList and AccountingTransaction_getDestinationPaymentItemList\n    # allows to select bank accounts from parent groups of source section\n    parent_bank_account = self.main_section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'from main section\'\n    )\n    parent_bank_account.validate()\n    main_section_accounting_period = self.main_section.newContent(\n      portal_type=\'Accounting Period\',\n    )\n    main_section_accounting_period.start()\n    bank_account = self.section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'from section\'\n    )\n    bank_account.validate()\n    self.tic()\n\n    source_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    self.assertIn(\n      (\'from main section\', parent_bank_account.getRelativeUrl()),\n      source_transaction.AccountingTransaction_getSourcePaymentItemList())\n    self.assertIn(\n      (\'from section\', bank_account.getRelativeUrl()),\n      source_transaction.AccountingTransaction_getSourcePaymentItemList())\n\n    # We include non selectable elements in the drop down to show which to which organisation\n    # the bank account belongs to.\n    self.assertEqual(\n      [(\'\', \'\'),\n       (self.main_section.getTitle(), None),\n       (\'from main section\', parent_bank_account.getRelativeUrl()),\n       (self.section.getTitle(), None),\n       (\'from section\', bank_account.getRelativeUrl()),\n      ],\n      source_transaction.AccountingTransaction_getSourcePaymentItemList())\n\n    destination_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.client_1,\n      lines=(dict(destination_value=self.account_module.goods_purchase,\n                  destination_debit=500),\n             dict(destination_value=self.account_module.receivable,\n                  destination_credit=500)))\n    self.assertIn(\n      (\'from main section\', parent_bank_account.getRelativeUrl()),\n      destination_transaction.AccountingTransaction_getDestinationPaymentItemList())\n    self.assertIn(\n      (\'from section\', bank_account.getRelativeUrl()),\n      destination_transaction.AccountingTransaction_getDestinationPaymentItemList())\n\n    main_section_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      source_section_value=self.main_section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    self.assertIn(\n      (\'from main section\', parent_bank_account.getRelativeUrl()),\n      main_section_transaction.AccountingTransaction_getSourcePaymentItemList())\n    self.assertNotIn(\n      (\'from section\', bank_account.getRelativeUrl()),\n      main_section_transaction.AccountingTransaction_getSourcePaymentItemList())\n\n    # We don\'t have this non selectable element when all bank accounts are from\n    # the same organisation\n    self.assertEqual(\n      [(\'\', \'\'),\n       (\'from main section\', parent_bank_account.getRelativeUrl()),\n      ],\n      main_section_transaction.AccountingTransaction_getSourcePaymentItemList())\n\n  def test_AccountingTransaction_getSourcePaymentItemList_parent_section_with_accounting_period(self):\n    # AccountingTransaction_getSourcePaymentItemList and AccountingTransaction_getDestinationPaymentItemList\n    # allows to select bank accounts from parent groups of source section, but not if\n    # the organisation has accounting periods, in this case it acts as an independant section.\n    parent_bank_account = self.main_section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'from main section\'\n    )\n    parent_bank_account.validate()\n    main_section_accounting_period = self.main_section.newContent(\n      portal_type=\'Accounting Period\',\n    )\n    main_section_accounting_period.start()\n    bank_account = self.section.newContent(\n      portal_type=\'Bank Account\',\n      reference=\'from section\'\n    )\n    bank_account.validate()\n    # open an accounting periods in this section, it will act as an independant section\n    # and will not allow bank accounts from parent sections.\n    section_accounting_period = self.section.newContent(\n      portal_type=\'Accounting Period\',\n    )\n    section_accounting_period.start()\n    self.tic()\n\n    source_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      source_section_value=self.section,\n      destination_section_value=self.organisation_module.client_1,\n      lines=(dict(source_value=self.account_module.goods_purchase,\n                  source_debit=500),\n             dict(source_value=self.account_module.receivable,\n                  source_credit=500)))\n    self.assertNotIn(\n      (\'from main section\', parent_bank_account.getRelativeUrl()),\n      source_transaction.AccountingTransaction_getSourcePaymentItemList())\n    self.assertIn(\n      (\'from section\', bank_account.getRelativeUrl()),\n      source_transaction.AccountingTransaction_getSourcePaymentItemList())\n\n    destination_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      destination_section_value=self.section,\n      source_section_value=self.organisation_module.client_1,\n      lines=(dict(destination_value=self.account_module.goods_purchase,\n                  destination_debit=500),\n             dict(destination_value=self.account_module.receivable,\n                  destination_credit=500)))\n    self.assertNotIn(\n      (\'from main section\', parent_bank_account.getRelativeUrl()),\n      destination_transaction.AccountingTransaction_getDestinationPaymentItemList())\n    self.assertIn(\n      (\'from section\', bank_account.getRelativeUrl()),\n      destination_transaction.AccountingTransaction_getDestinationPaymentItemList())\n\n  def test_AccountingTransaction_getSourcePaymentItemList_bank_accounts_from_other_entities(self):\n    client_1_bank_account = self.portal.organisation_module.client_1.newContent(\n      portal_type=\'Bank Account\',\n      title=\'client_1 bank account\'\n    )\n    client_1_bank_account.validate()\n\n    source_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      destination_section_value=self.section,\n      # section is client 2 but account is for client 1\n      source_section_value=self.organisation_module.client_2,\n      source_payment_value=client_1_bank_account,\n      lines=(\n        dict(\n          destination_value=self.account_module.goods_purchase,\n          destination_debit=500),\n        dict(\n          destination_value=self.account_module.receivable,\n          destination_credit=500)))\n    self.assertEqual(\n      [\n        (str(label), value) for (label, value) in\n        source_transaction.AccountingTransaction_getSourcePaymentItemList()\n      ],\n      [\n        (\'\', \'\'),\n        (\'Invalid bank account from Client 1\', None),\n        (\'??? (client_1 bank account)\', client_1_bank_account.getRelativeUrl()),\n      ],\n    )\n\n    destination_transaction = self._makeOne(\n      portal_type=\'Payment Transaction\',\n      source_section_value=self.section,\n      # section is client 2 but account is for client 1\n      destination_section_value=self.organisation_module.client_2,\n      destination_payment_value=client_1_bank_account,\n      lines=(\n        dict(\n          destination_value=self.account_module.goods_purchase,\n          destination_debit=500),\n        dict(\n          destination_value=self.account_module.receivable,\n          destination_credit=500)))\n    self.assertEqual(\n      [\n        (str(label), value) for (label, value) in destination_transaction.\n        AccountingTransaction_getDestinationPaymentItemList()\n      ],\n      [\n        (\'\', \'\'),\n        (\'Invalid bank account from Client 1\', None),\n        (\'??? (client_1 bank account)\', client_1_bank_account.getRelativeUrl()),\n      ],\n    )\n\n\nclass TestAccountingWithSequences(ERP5TypeTestCase):\n  \"\"\"The first test for Accounting\n  \"\"\"\n\n  def getBusinessTemplateList(self):\n    \"\"\"Returns list of BT to be installed.\"\"\"\n    return (\'erp5_core_proxy_field_legacy\', \'erp5_base\', \'erp5_pdm\',\n            \'erp5_simulation\', \'erp5_trade\', \'erp5_accounting\',\n            \'erp5_simulation_test\')\n\n  # XXX\n  def playSequence(self, sequence_string, quiet=1) :\n    sequence_list = SequenceList()\n    sequence_list.addSequenceString(sequence_string)\n    sequence_list.play(self, quiet=quiet)\n\n  account_portal_type           = \'Account\'\n  accounting_period_portal_type = \'Accounting Period\'\n  accounting_transaction_portal_type = \'Accounting Transaction\'\n  accounting_transaction_line_portal_type = \'Accounting Transaction Line\'\n  currency_portal_type          = \'Currency\'\n  organisation_portal_type      = \'Organisation\'\n  sale_invoice_portal_type      = \'Sale Invoice Transaction\'\n  sale_invoice_transaction_line_portal_type = \'Sale Invoice Transaction Line\'\n  purchase_invoice_portal_type      = \'Purchase Invoice Transaction\'\n  purchase_invoice_transaction_line_portal_type = \\\n                \'Purchase Invoice Transaction Line\'\n\n  start_date = DateTime(2004, 1, 1)\n  stop_date  = DateTime(2004, 12, 31)\n\n  default_region = \'europe/west/france\'\n\n  def getTitle(self):\n    return \"Accounting\"\n\n  def afterSetUp(self):\n    \"\"\"Prepare the test.\"\"\"\n    self.workflow_tool = self.portal.portal_workflow\n    self.organisation_module = self.portal.organisation_module\n    self.account_module = self.portal.account_module\n    self.accounting_module = self.portal.accounting_module\n    self.createCategories()\n    self.createCurrencies()\n    self.createEntities()\n    self.createAccounts()\n    self.validateRules()\n\n    # setup preference for the vendor group\n    self.pref = self.portal.portal_preferences.newContent(\n         portal_type=\'Preference\', preferred_section_category=\'group/vendor\',\n         preferred_accounting_transaction_section_category=\'group/vendor\',\n         priority=Priority.USER )\n    self.workflow_tool.doActionFor(self.pref, \'enable_action\')\n\n  def beforeTearDown(self):\n    \"\"\"Cleanup for next test.\n    \"\"\"\n    self.abort()\n    for folder in (self.accounting_module, self.portal.portal_simulation):\n      folder.manage_delObjects([i for i in folder.objectIds()])\n\n    # Some tests commits transaction, some other does not, so accounts and\n    # organisations created in this tests will not always be present at this\n    # point\n    folder = self.portal.account_module\n    for account in self.account_list:\n      if account.getId() in folder.objectIds():\n        folder.manage_delObjects([account.getId()])\n    folder = self.portal.organisation_module\n    for entity in (self.client, self.vendor, self.other_vendor):\n      if entity.getId() in folder.objectIds():\n        folder.manage_delObjects([entity.getId()])\n\n    self.tic()\n\n  def createCategories(self):\n    \"\"\"Create the categories for our test. \"\"\"\n    # create categories\n    for cat_string in self.getNeededCategoryList():\n      base_cat = cat_string.split(\"/\")[0]\n      path = self.getPortal().portal_categories[base_cat]\n      for cat in cat_string.split(\"/\")[1:]:\n        if not cat in path.objectIds():\n          path = path.newContent(\n            portal_type=\'Category\',\n            id=cat,)\n        else:\n          path = path[cat]\n\n    # check categories have been created\n    for cat_string in self.getNeededCategoryList() :\n      self.assertNotEqual(None,\n                self.getCategoryTool().restrictedTraverse(cat_string),\n                cat_string)\n\n  def getNeededCategoryList(self):\n    \"\"\"Returns a list of categories that should be created.\"\"\"\n    return (\'group/client\', \'group/vendor/sub1\', \'group/vendor/sub2\',\n            \'payment_mode/check\', \'region/%s\' % self.default_region, )\n\n  def createEntities(self):\n    \"\"\"Create entities. \"\"\"\n    self.client = self.getOrganisationModule().newContent(\n        title = \'Client\',\n        portal_type = self.organisation_portal_type,\n        group = \"client\",\n        price_currency = \"currency_module/USD\")\n    self.section = self.vendor = self.getOrganisationModule().newContent(\n        title = \'Vendor\',\n        portal_type = self.organisation_portal_type,\n        group = \"vendor/sub1\",\n        price_currency = \"currency_module/EUR\")\n    self.other_vendor = self.getOrganisationModule().newContent(\n        title = \'Other Vendor\',\n        portal_type = self.organisation_portal_type,\n        group = \"vendor/sub2\",\n        price_currency = \"currency_module/EUR\")\n    # validate entities\n    for entity in (self.client, self.vendor, self.other_vendor):\n      entity.setRegion(self.default_region)\n      self.getWorkflowTool().doActionFor(entity, \'validate_action\')\n    self.tic()\n\n  def stepCreateEntities(self, sequence, **kw) :\n    \"\"\"Create entities. \"\"\"\n    # TODO: remove this method\n    sequence.edit( client=self.client,\n                   vendor=self.vendor,\n                   other_vendor=self.other_vendor,\n                   organisation=self.vendor )\n\n  def stepCreateAccountingPeriod(self, sequence, **kw):\n    \"\"\"Creates an Accounting Period for the Organisation.\"\"\"\n    organisation = sequence.get(\'organisation\')\n    start_date = self.start_date\n    stop_date = self.stop_date\n    accounting_period = organisation.newContent(\n      portal_type = self.accounting_period_portal_type,\n      start_date = start_date, stop_date = stop_date )\n    sequence.edit( accounting_period = accounting_period,\n                   valid_date_list = [ start_date, start_date+1, stop_date],\n                   invalid_date_list = [start_date-1, stop_date+1] )\n\n  def stepUseValidDates(self, sequence, **kw):\n    \"\"\"Puts some valid dates in sequence.\"\"\"\n    sequence.edit(date_list = sequence.get(\'valid_date_list\'))\n\n  def stepUseInvalidDates(self, sequence, **kw):\n    \"\"\"Puts some invalid dates in sequence.\"\"\"\n    sequence.edit(date_list = sequence.get(\'invalid_date_list\'))\n\n  def stepOpenAccountingPeriod(self, sequence, **kw):\n    \"\"\"Opens the Accounting Period.\"\"\"\n    accounting_period = sequence.get(\'accounting_period\')\n    self.getPortal().portal_workflow.doActionFor(\n                        accounting_period,\n                        \'start_action\' )\n    self.assertEqual(accounting_period.getSimulationState(),\n                      \'started\')\n\n  def stepStopAccountingPeriod(self, sequence, **kw):\n    \"\"\"Stops the Accounting Period.\"\"\"\n    accounting_period = sequence.get(\'accounting_period\')\n    # take any account for profit and loss account, here we don\'t care\n    profit_and_loss_account = self.portal.account_module.contentValues()[0]\n    self.getPortal().portal_workflow.doActionFor(\n           accounting_period, \'stop_action\',\n           profit_and_loss_account=profit_and_loss_account.getRelativeUrl())\n    self.assertEqual(accounting_period.getSimulationState(),\n                      \'stopped\')\n\n  def stepCheckAccountingPeriodRefusesClosing(self, sequence, **kw):\n    \"\"\"Checks the Accounting Period refuses closing.\"\"\"\n    accounting_period = sequence.get(\'accounting_period\')\n    self.assertRaises(ValidationFailed,\n          self.getPortal().portal_workflow.doActionFor,\n          accounting_period, \'stop_action\' )\n\n  def stepDeliverAccountingPeriod(self, sequence, **kw):\n    \"\"\"Deliver the Accounting Period.\"\"\"\n    accounting_period = sequence.get(\'accounting_period\')\n    self.portal.portal_workflow.doActionFor(\n           accounting_period, \'deliver_action\', )\n    self.assertEqual(accounting_period.getSimulationState(),\n                      \'delivered\')\n\n  def stepCheckAccountingPeriodDelivered(self, sequence, **kw):\n    \"\"\"Check the Accounting Period is delivered.\"\"\"\n    accounting_period = sequence.get(\'accounting_period\')\n    self.assertEqual(accounting_period.getSimulationState(),\n                      \'delivered\')\n\n  def createCurrencies(self):\n    \"\"\"Create some currencies.\n    This script will reuse existing currencies, because we want currency ids to\n    be stable, as we use them as categories.\n    \"\"\"\n    currency_module = self.getCurrencyModule()\n    if not hasattr(currency_module, \'EUR\'):\n      self.EUR = currency_module.newContent(\n          portal_type = self.currency_portal_type,\n          reference = \"EUR\", id = \"EUR\" )\n      self.USD = currency_module.newContent(\n          portal_type = self.currency_portal_type,\n          reference = \"USD\", id = \"USD\" )\n      self.YEN = currency_module.newContent(\n          portal_type = self.currency_portal_type,\n          reference = \"YEN\", id = \"YEN\" )\n      self.tic()\n    else:\n      self.EUR = currency_module.EUR\n      self.USD = currency_module.USD\n      self.YEN = currency_module.YEN\n\n  def stepCreateCurrencies(self, sequence, **kw) :\n    \"\"\"Create some currencies. \"\"\"\n    sequence.edit(EUR=self.EUR, USD=self.USD, YEN=self.YEN)\n\n  def createAccounts(self):\n    \"\"\"Create some accounts.\n    \"\"\"\n    account_module = self.portal.account_module\n    receivable = self.receivable_account = account_module.newContent(\n          title = \'receivable\',\n          portal_type = self.account_portal_type,\n          account_type = \'asset/receivable\' )\n    payable = self.payable_account = account_module.newContent(\n          title = \'payable\',\n          portal_type = self.account_portal_type,\n          account_type = \'liability/payable\' )\n    expense = self.expense_account = account_module.newContent(\n          title = \'expense\',\n          portal_type = self.account_portal_type,\n          account_type = \'expense\' )\n    income = self.income_account = account_module.newContent(\n          title = \'income\',\n          portal_type = self.account_portal_type,\n          account_type = \'income\' )\n    collected_vat = self.collected_vat_account = account_module.newContent(\n          title = \'collected_vat\',\n          portal_type = self.account_portal_type,\n          account_type = \'liability/payable/collected_vat\' )\n    refundable_vat = self.refundable_vat_account = account_module.newContent(\n          title = \'refundable_vat\',\n          portal_type = self.account_portal_type,\n          account_type = \'asset/receivable/refundable_vat\' )\n    bank = self.bank_account = self.account_module.newContent(\n          title = \'bank\',\n          portal_type = self.account_portal_type,\n          account_type = \'asset/cash/bank\')\n\n    # set mirror accounts.\n    receivable.setDestinationValue(payable)\n    payable.setDestinationValue(receivable)\n    expense.setDestinationValue(income)\n    income.setDestinationValue(expense)\n    collected_vat.setDestinationValue(refundable_vat)\n    refundable_vat.setDestinationValue(collected_vat)\n    bank.setDestinationValue(bank)\n\n    self.account_list = [ receivable,\n                          payable,\n                          expense,\n                          income,\n                          collected_vat,\n                          refundable_vat,\n                          bank ]\n\n    for account in self.account_list :\n      account.validate()\n      self.assertNotIn(\'Site Error\', account.view())\n      self.assertEqual(account.getValidationState(), \'validated\')\n    self.tic()\n\n  def stepCreateAccounts(self, sequence, **kw) :\n    \"\"\"Create necessary accounts. \"\"\"\n    sequence.edit( receivable_account=self.receivable_account,\n                   payable_account=self.payable_account,\n                   expense_account=self.expense_account,\n                   income_account=self.income_account,\n                   collected_vat_account=self.collected_vat_account,\n                   refundable_vat_account=self.refundable_vat_account,\n                   bank_account=self.bank_account,\n                   account_list=self.account_list )\n\n\n  def getInvoicePropertyList(self):\n    \"\"\"Returns the list of properties for invoices, stored as\n      a list of dictionnaries. \"\"\"\n    # source currency is EUR\n    # destination currency is USD\n    return [\n      # in currency of destination, converted for source\n      { \'income\' : -200,             \'source_converted_income\' : -180,\n        \'collected_vat\' : -40,       \'source_converted_collected_vat\' : -36,\n        \'receivable\' : 240,          \'source_converted_receivable\' : 216,\n        \'currency\' : \'currency_module/USD\' },\n\n      # in currency of source, converted for destination\n      { \'income\' : -100,        \'destination_converted_expense\' : -200,\n        \'collected_vat\' : 10,   \'destination_converted_refundable_vat\' : 100,\n        \'receivable\' : 90,      \'destination_converted_payable\' : 100,\n        \'currency\' : \'currency_module/EUR\' },\n\n      { \'income\' : -100,        \'destination_converted_expense\' : -200,\n        \'collected_vat\' : 10,   \'destination_converted_refundable_vat\' : 100,\n        \'receivable\' : 90,      \'destination_converted_payable\' : 100,\n        \'currency\' : \'currency_module/EUR\' },\n\n      # in an external currency, converted for both source and dest.\n      { \'income\' : -300,\n                    \'source_converted_income\' : -200,\n                    \'destination_converted_expense\' : -400,\n        \'collected_vat\' : 40,\n                    \'source_converted_collected_vat\' : 36,\n                    \'destination_converted_refundable_vat\' : 50,\n        \'receivable\' : 260,\n                    \'source_converted_receivable\' : 164,\n                    \'destination_converted_payable\': 350,\n        \'currency\' : \'currency_module/YEN\' },\n\n      # currency of source, not converted for destination -> 0\n      { \'income\' : -100,\n        \'collected_vat\' : -20,\n        \'receivable\' : 120,\n        \'currency\' : \'currency_module/EUR\' },\n\n    ]\n\n  def stepCreateInvoices(self, sequence, **kw) :\n    \"\"\"Create invoices with properties from getInvoicePropertyList. \"\"\"\n    invoice_prop_list = self.getInvoicePropertyList()\n    invoice_list = []\n    date_list = sequence.get(\'date_list\')\n    if not date_list : date_list = [ DateTime(2004, 12, 31) ]\n    i = 0\n    for invoice_prop in invoice_prop_list :\n      i += 1\n      date = date_list[i % len(date_list)]\n      invoice = self.portal.accounting_module.newContent(\n          portal_type = self.sale_invoice_portal_type,\n          source_section_value = sequence.get(\'vendor\'),\n          source_value = sequence.get(\'vendor\'),\n          destination_section_value = sequence.get(\'client\'),\n          destination_value = sequence.get(\'client\'),\n          resource = invoice_prop[\'currency\'],\n          start_date = date, stop_date = date,\n          created_by_builder = 0,\n      )\n\n      for line_type in [\'income\', \'receivable\', \'collected_vat\'] :\n        source_account = sequence.get(\'%s_account\' % line_type)\n        line = invoice.newContent(\n          portal_type = self.sale_invoice_transaction_line_portal_type,\n          quantity = invoice_prop[line_type],\n          source_value = source_account\n        )\n        source_converted = invoice_prop.get(\n                          \'source_converted_%s\' % line_type, None)\n        if source_converted is not None :\n          line.setSourceTotalAssetPrice(source_converted)\n\n        destination_account = source_account.getDestinationValue(\n                                                portal_type = \'Account\' )\n        destination_converted = invoice_prop.get(\n                          \'destination_converted_%s\' %\n                          destination_account.getAccountTypeId(), None)\n        if destination_converted is not None :\n          line.setDestinationTotalAssetPrice(destination_converted)\n\n      invoice_list.append(invoice)\n    sequence.edit( invoice_list = invoice_list )\n\n  def stepCreateOtherSectionInvoices(self, sequence, **kw):\n    \"\"\"Create invoice for other sections.\"\"\"\n    other_source = self.getOrganisationModule().newContent(\n                      portal_type = \'Organisation\' )\n    other_destination = self.getOrganisationModule().newContent(\n                      portal_type = \'Organisation\' )\n    invoice = self.portal.accounting_module.newContent(\n        portal_type = self.sale_invoice_portal_type,\n        source_section_value = other_source,\n        source_value = other_source,\n        destination_section_value = other_destination,\n        destination_value = other_destination,\n        resource_value = sequence.get(\'EUR\'),\n        start_date = self.start_date,\n        stop_date = self.start_date,\n        created_by_builder = 0,\n    )\n\n    invoice.newContent(\n        portal_type = self.sale_invoice_transaction_line_portal_type,\n        quantity = 100, source_value = sequence.get(\'account_list\')[0])\n    invoice.newContent(\n        portal_type = self.sale_invoice_transaction_line_portal_type,\n        quantity = -100, source_value = sequence.get(\'account_list\')[1])\n    sequence.edit(invoice_list = [invoice])\n\n  def stepStopInvoices(self, sequence, **kw) :\n    \"\"\"Validates invoices.\"\"\"\n    invoice_list = sequence.get(\'invoice_list\')\n    for invoice in invoice_list:\n      self.getPortal().portal_workflow.doActionFor(\n          invoice, \'stop_action\')\n\n  def stepCheckStopInvoicesRefused(self, sequence, **kw) :\n    \"\"\"Checks that invoices cannot be validated.\"\"\"\n    invoice_list = sequence.get(\'invoice_list\')\n    for invoice in invoice_list:\n      self.assertRaises(ValidationFailed,\n          self.getPortal().portal_workflow.doActionFor,\n          invoice, \'stop_action\')\n\n  def stepCheckInvoicesAreDraft(self, sequence, **kw) :\n    \"\"\"Checks invoices are in draft state.\"\"\"\n    invoice_list = sequence.get(\'invoice_list\')\n    for invoice in invoice_list:\n      self.assertEqual(invoice.getSimulationState(), \'draft\')\n\n  def stepCheckInvoicesAreStopped(self, sequence, **kw) :\n    \"\"\"Checks invoices are in stopped state.\"\"\"\n    invoice_list = sequence.get(\'invoice_list\')\n    for invoice in invoice_list:\n      self.assertEqual(invoice.getSimulationState(), \'stopped\')\n\n  def checkAccountBalanceInCurrency(self, section, currency,\n                                          sequence, **kw) :\n    \"\"\" Checks accounts balances in a given currency.\"\"\"\n    invoice_list = sequence.get(\'invoice_list\')\n    for account_type in [ \'income\', \'receivable\', \'collected_vat\',\n                          \'expense\', \'payable\', \'refundable_vat\' ] :\n      account = sequence.get(\'%s_account\' % account_type)\n      calculated_balance = 0\n      for invoice in invoice_list :\n        for line in invoice.getMovementList():\n          # source\n          if line.getSourceValue() == account and\\\n             line.getResourceValue() == currency and\\\n             section == line.getSourceSectionValue() :\n            calculated_balance += (\n                    line.getSourceDebit() - line.getSourceCredit())\n          # dest.\n          elif line.getDestinationValue() == account and\\\n            line.getResourceValue() == currency and\\\n            section == line.getDestinationSectionValue() :\n            calculated_balance += (\n                    line.getDestinationDebit() - line.getDestinationCredit())\n\n      self.assertEqual(calculated_balance,\n          self.getPortal().portal_simulation.getInventory(\n            node_uid = account.getUid(),\n            section_uid = section.getUid(),\n            resource_uid = currency.getUid(),\n          ))\n\n  def stepCheckAccountBalanceLocalCurrency(self, sequence, **kw) :\n    \"\"\" Checks accounts balances in the organisation default currency.\"\"\"\n    for section in (sequence.get(\'vendor\'), sequence.get(\'client\')) :\n      currency = section.getPriceCurrencyValue()\n      self.checkAccountBalanceInCurrency(section, currency, sequence)\n\n  def stepCheckAccountBalanceExternalCurrency(self, sequence, **kw) :\n    \"\"\" Checks accounts balances in external currencies .\"\"\"\n    for section in (sequence.get(\'vendor\'), sequence.get(\'client\')) :\n      for currency in (sequence.get(\'USD\'), sequence.get(\'YEN\')) :\n        self.checkAccountBalanceInCurrency(section, currency, sequence)\n\n  def checkAccountBalanceInConvertedCurrency(self, section, sequence, **kw) :\n    \"\"\" Checks accounts balances converted in section default currency.\"\"\"\n    invoice_list = sequence.get(\'invoice_list\')\n    for account_type in [ \'income\', \'receivable\', \'collected_vat\',\n                          \'expense\', \'payable\', \'refundable_vat\' ] :\n      account = sequence.get(\'%s_account\' % account_type)\n      calculated_balance = 0\n      for invoice in invoice_list :\n        for line in invoice.getMovementList() :\n          if line.getSourceValue() == account and \\\n             section == line.getSourceSectionValue() :\n            calculated_balance += line.getSourceInventoriatedTotalAssetPrice()\n          elif line.getDestinationValue() == account and\\\n               section == line.getDestinationSectionValue() :\n            calculated_balance += \\\n                             line.getDestinationInventoriatedTotalAssetPrice()\n      self.assertEqual(calculated_balance,\n          self.getPortal().portal_simulation.getInventoryAssetPrice(\n            node_uid = account.getUid(),\n            section_uid = section.getUid(),\n          ))\n\n  def stepCheckAccountBalanceConvertedCurrency(self, sequence, **kw):\n    \"\"\"Checks accounts balances converted in the organisation default\n    currency.\"\"\"\n    for section in (sequence.get(\'vendor\'), sequence.get(\'client\')) :\n      self.checkAccountBalanceInConvertedCurrency(section, sequence)\n\n  def stepCheckAcquisition(self, sequence, **kw):\n    \"\"\"Checks acquisition and portal types configuration. \"\"\"\n    resource_value = sequence.get(\'EUR\')\n    source_section_title = \"Source Section Title\"\n    destination_section_title = \"Destination Section Title\"\n    source_section_value = self.getOrganisationModule().newContent(\n        portal_type = self.organisation_portal_type,\n        title = source_section_title,\n        group = \"group/client\",\n        price_currency = \"currency_module/USD\")\n    destination_section_value = self.getOrganisationModule().newContent(\n        portal_type = self.organisation_portal_type,\n        title = destination_section_title,\n        group = \"group/vendor\",\n        price_currency = \"currency_module/EUR\")\n\n    portal = self.getPortal()\n    accounting_module = portal.accounting_module\n    self.assertNotIn(\'Site Error\', accounting_module.view())\n    self.assertNotEqual(\n          len(portal.getPortalAccountingMovementTypeList()), 0)\n    self.assertNotEqual(\n          len(portal.getPortalAccountingTransactionTypeList()), 0)\n    for accounting_portal_type in accounting_module.allowedContentTypes():\n      accounting_transaction = accounting_module.newContent(\n            portal_type = accounting_portal_type.getId(),\n            source_section_value = source_section_value,\n            destination_section_value = destination_section_value,\n            resource_value = resource_value )\n      self.assertNotIn(\'Site Error\', accounting_transaction.view())\n      self.assertEqual( accounting_transaction.getSourceSectionValue(),\n                         source_section_value )\n      self.assertEqual( accounting_transaction.getDestinationSectionValue(),\n                         destination_section_value )\n      self.assertEqual( accounting_transaction.getResourceValue(),\n                         resource_value )\n      self.assertNotEqual(\n              len(accounting_transaction.allowedContentTypes()), 0)\n      tested_line_portal_type = 0\n      for line_portal_type in portal.getPortalAccountingMovementTypeList():\n        allowed_content_types = [x.id for x in\n                            accounting_transaction.allowedContentTypes()]\n        if line_portal_type in allowed_content_types :\n          line = accounting_transaction.newContent(\n            portal_type = line_portal_type, )\n          self.assertNotIn(\'Site Error\', line.view())\n          # section and resource is acquired from parent transaction.\n          self.assertEqual( line.getDestinationSectionValue(),\n                             destination_section_value )\n          self.assertEqual( line.getDestinationSectionTitle(),\n                             destination_section_title )\n          self.assertEqual( line.getSourceSectionValue(),\n                             source_section_value )\n          self.assertEqual( line.getSourceSectionTitle(),\n                             source_section_title )\n          self.assertEqual( line.getResourceValue(),\n                             resource_value )\n          tested_line_portal_type = 1\n      self.assertTrue(tested_line_portal_type, (\"No lines tested ... \" +\n                          \"getPortalAccountingMovementTypeList = %s \" +\n                          \"<%s>.allowedContentTypes = %s\") %\n                          (portal.getPortalAccountingMovementTypeList(),\n                            accounting_transaction.getPortalType(),\n                            allowed_content_types ))\n\n  def createAccountingTransaction(self,\n                        portal_type=accounting_transaction_portal_type,\n                        line_portal_type=accounting_transaction_line_portal_type,\n                        quantity=100, reindex=1, check_consistency=1, **kw): # pylint: disable=redefined-outer-name\n    \"\"\"Creates an accounting transaction.\n    By default, this transaction contains 2 lines, income and receivable.\n      quantity          - The quantity property on created lines.\n      reindex           - The transaction will be reindexed.\n      check_consistency - a consistency check will be performed on the\n                          transaction.\n    \"\"\"\n    kw.setdefault(\'resource_value\', self.EUR)\n    kw.setdefault(\'source_section_value\', self.vendor)\n    kw.setdefault(\'destination_section_value\', self.client)\n    if \'start_date\' not in kw:\n      start_date = DateTime(2000, 1, 1)\n      # get a valid date for source section\n      for openned_source_section_period in\\\n        kw[\'source_section_value\'].searchFolder(\n              portal_type=self.accounting_period_portal_type,\n              simulation_state=\'planned\' ):\n        start_date = openned_source_section_period.getStartDate() + 1\n      kw[\'start_date\'] = start_date\n\n    if \'stop_date\' not in kw:\n      # get a valid date for destination section\n      stop_date = DateTime(2000, 2, 2)\n      for openned_destination_section_period in\\\n        kw[\'destination_section_value\'].searchFolder(\n              portal_type=self.accounting_period_portal_type,\n              simulation_state=\'planned\' ):\n        stop_date = openned_destination_section_period.getStartDate() + 1\n      kw[\'stop_date\'] = stop_date\n\n    # create the transaction.\n    accounting_transaction = self.portal.accounting_module.newContent(\n      portal_type=portal_type,\n      start_date=kw[\'start_date\'],\n      stop_date=kw[\'stop_date\'],\n      resource_value=kw[\'resource_value\'],\n      source_section_value=kw[\'source_section_value\'],\n      destination_section_value=kw[\'destination_section_value\'],\n      created_by_builder = 1 # prevent the init script from\n                             # creating lines.\n    )\n    income = accounting_transaction.newContent(\n                  id=\'income\',\n                  portal_type=line_portal_type,\n                  quantity=-quantity,\n                  source_value=kw.get(\'income_account\', self.income_account),\n                  destination_value=kw.get(\'expense_account\',\n                                              self.expense_account), )\n    self.assertTrue(income.getSource() != None)\n    self.assertTrue(income.getDestination() != None)\n\n    receivable = accounting_transaction.newContent(\n                  id=\'receivable\',\n                  portal_type=line_portal_type,\n                  quantity=quantity,\n                  source_value=kw.get(\'receivable_account\',\n                                          self.receivable_account),\n                  destination_value=kw.get(\'payable_account\',\n                                            self.payable_account), )\n    self.assertTrue(receivable.getSource() != None)\n    self.assertTrue(receivable.getDestination() != None)\n    if reindex:\n      self.tic()\n    if check_consistency:\n      self.assertTrue(len(accounting_transaction.checkConsistency()) == 0,\n         \"Check consistency failed : %s\" % accounting_transaction.checkConsistency())\n    return accounting_transaction\n\n  def test_createAccountingTransaction(self):\n    \"\"\"Make sure acounting transactions created by createAccountingTransaction\n    method are valid.\n    \"\"\"\n    accounting_transaction = self.createAccountingTransaction()\n    self.assertEqual(self.vendor, accounting_transaction.getSourceSectionValue())\n    self.assertEqual(self.client, accounting_transaction.getDestinationSectionValue())\n    self.assertEqual(self.EUR, accounting_transaction.getResourceValue())\n    self.assertTrue(accounting_transaction.AccountingTransaction_isSourceView())\n\n    self.workflow_tool.doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(\'stopped\', accounting_transaction.getSimulationState())\n    self.assertEqual([] , accounting_transaction.checkConsistency())\n\n  def stepCreateValidAccountingTransaction(self, sequence,\n                                          sequence_list=None, **kw) :\n    \"\"\"Creates a valid accounting transaction and put it in\n    the sequence as `transaction` key. \"\"\"\n    accounting_transaction = self.createAccountingTransaction(\n                            resource_value=sequence.get(\'EUR\'),\n                            source_section_value=sequence.get(\'vendor\'),\n                            destination_section_value=sequence.get(\'client\'),\n                            income_account=sequence.get(\'income_account\'),\n                            expense_account=sequence.get(\'expense_account\'),\n                            receivable_account=sequence.get(\'receivable_account\'),\n                            payable_account=sequence.get(\'payable_account\'), )\n    sequence.edit(\n      transaction = accounting_transaction,\n      income = accounting_transaction.income,\n      receivable = accounting_transaction.receivable\n    )\n\n  def stepValidateNoDate(self, sequence, sequence_list=None, **kw) :\n    \"\"\"When no date is defined, validation should be impossible.\n\n    Actually, we could say that if we have source_section, we need start_date,\n    and if we have destination section, we need stop_date only, but we decided\n    to update a date (of start_date / stop_date) using the other one if one is\n    missing. (ie. stop_date defaults automatically to start_date if not set and\n    start_date is set to stop_date in the workflow script if not set.\n    \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    old_stop_date = accounting_transaction.getStopDate()\n    old_start_date = accounting_transaction.getStartDate()\n    accounting_transaction.setStopDate(None)\n    if accounting_transaction.getStopDate() != None :\n      accounting_transaction.setStartDate(None)\n      accounting_transaction.setStopDate(None)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n    accounting_transaction.setStartDate(old_start_date)\n    accounting_transaction.setStopDate(old_stop_date)\n    self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(accounting_transaction.getSimulationState(), \'stopped\')\n\n  def stepValidateNoSection(self, sequence, sequence_list=None, **kw) :\n    \"\"\"Check validation behaviour related to section & mirror_section.\n    When no source section is defined, we are in one of the following\n    cases :\n      o if we use payable or receivable account, the validation should\n        be refused.\n      o if we do not use any payable or receivable accounts and we have\n      a destination section, validation should be ok.\n    \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    old_source_section = accounting_transaction.getSourceSection()\n    old_destination_section = accounting_transaction.getDestinationSection()\n    # default transaction uses payable accounts, so validating without\n    # source section is refused.\n    accounting_transaction.setSourceSection(None)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n    # ... as well as validation without destination section\n    accounting_transaction.setSourceSection(old_source_section)\n    accounting_transaction.setDestinationSection(None)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n    # mirror section can be set only on the line\n    for line in accounting_transaction.getMovementList() :\n      line.setDestinationSection(old_destination_section)\n    try:\n      self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n      self.assertEqual(accounting_transaction.getSimulationState(), \'stopped\')\n    except ValidationFailed as err:\n      raise AssertionError(\"Validation failed : %s\" % err.msg)\n\n    # if we do not use any payable / receivable account, then we can\n    # validate the transaction without setting the mirror section.\n    for side in (SOURCE, ): # DESTINATION) :\n      # TODO: for now, we only test for source, as it makes no sense to use for\n      # destination section only. We could theoritically support it.\n\n      # get a new valid transaction\n      accounting_transaction = self.createAccountingTransaction()\n      expense_account = sequence.get(\'expense_account\')\n      for line in accounting_transaction.getMovementList() :\n        line.edit( source_value = expense_account,\n                   destination_value = expense_account )\n      if side == SOURCE :\n        accounting_transaction.setDestinationSection(None)\n      else :\n        accounting_transaction.setSourceSection(None)\n      try:\n        self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n        self.assertEqual(accounting_transaction.getSimulationState(), \'stopped\')\n      except ValidationFailed as err:\n        raise AssertionError(\"Validation failed : %s\" % err.msg)\n\n  def stepValidateNoCurrency(self, sequence, sequence_list=None, **kw) :\n    \"\"\"Check validation behaviour related to currency.\n    \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    accounting_transaction.setResource(None)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n    # setting a dummy relationship is not enough, resource must be a\n    # currency\n    accounting_transaction.setResourceValue(\n         self.portal.product_module.newContent(portal_type=\'Product\'))\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n\n  def stepValidateClosedAccount(self, sequence, sequence_list=None, **kw) :\n    \"\"\"Check validation behaviour related to closed accounts.\n    If an account is blocked, then it\'s impossible to validate a\n    transaction related to this account.\n    \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    account = accounting_transaction.getMovementList()[0].getSourceValue()\n    self.getWorkflowTool().doActionFor(account, \'invalidate_action\')\n    self.assertEqual(account.getValidationState(), \'invalidated\')\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n    # reopen the account for other tests\n    account.validate()\n    self.assertEqual(account.getValidationState(), \'validated\')\n\n  def stepValidateNoAccounts(self, sequence, sequence_list=None, **kw) :\n    \"\"\"Simple check that the validation is refused when we do not have\n    accounts correctly defined on lines.\n    \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    # no account at all is refused\n    for line in accounting_transaction.getMovementList():\n      line.setSource(None)\n      line.setDestination(None)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n\n    # only one line without account and with a quantity is also refused\n    accounting_transaction = self.createAccountingTransaction()\n    accounting_transaction.getMovementList()[0].setSource(None)\n    accounting_transaction.getMovementList()[0].setDestination(None)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n\n    # but if we have a line with 0 quantity on both sides, we can\n    # validate the transaction and delete this line.\n    accounting_transaction = self.createAccountingTransaction()\n    line_count = len(accounting_transaction.getMovementList())\n    accounting_transaction.newContent(\n        portal_type = self.accounting_transaction_line_portal_type)\n    self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(accounting_transaction.getSimulationState(), \'stopped\')\n    self.assertEqual(line_count, len(accounting_transaction.getMovementList()))\n\n    # 0 quantity, but a destination asset price => do not delete the\n    # line\n    accounting_transaction = self.createAccountingTransaction()\n    accounting_transaction.newContent(\n        portal_type = self.accounting_transaction_line_portal_type)\n    self.assertEqual(len(accounting_transaction.getMovementList()), 3)\n    line_list = accounting_transaction.getMovementList()\n    line_list[0].setDestinationTotalAssetPrice(100)\n    line_list[0]._setCategoryMembership(\n          \'destination\', sequence.get(\'expense_account\').getRelativeUrl())\n    line_list[1].setDestinationTotalAssetPrice(- 50)\n    line_list[1]._setCategoryMembership(\n          \'destination\', sequence.get(\'expense_account\').getRelativeUrl())\n    line_list[2].setDestinationTotalAssetPrice(- 50)\n    line_list[2]._setCategoryMembership(\n          \'destination\', sequence.get(\'expense_account\').getRelativeUrl())\n    try:\n      self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n      self.assertEqual(accounting_transaction.getSimulationState(), \'stopped\')\n    except ValidationFailed as err:\n      raise AssertionError(\"Validation failed : %s\" % err.msg)\n\n  def stepValidateNotBalanced(self, sequence, sequence_list=None, **kw) :\n    \"\"\"Check validation behaviour when transaction is not balanced.\n    \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    accounting_transaction.getMovementList()[0].setQuantity(4325)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n\n    # asset price have priority (ie. if asset price is not balanced,\n    # refuses validation even if quantity is balanced)\n    accounting_transaction = self.createAccountingTransaction(resource_value=self.YEN)\n    line_list = accounting_transaction.getMovementList()\n    line_list[0].setDestinationTotalAssetPrice(10)\n    line_list[1].setDestinationTotalAssetPrice(100)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n\n    accounting_transaction = self.createAccountingTransaction(resource_value=self.YEN)\n    line_list = accounting_transaction.getMovementList()\n    line_list[0].setSourceTotalAssetPrice(10)\n    line_list[1].setSourceTotalAssetPrice(100)\n    self.assertRaises(ValidationFailed,\n        self.getWorkflowTool().doActionFor,\n        accounting_transaction,\n        \'stop_action\')\n\n    # only asset price needs to be balanced\n    accounting_transaction = self.createAccountingTransaction(resource_value=self.YEN)\n    line_list = accounting_transaction.getMovementList()\n    line_list[0].setSourceTotalAssetPrice(100)\n    line_list[0].setDestinationTotalAssetPrice(100)\n    line_list[0].setQuantity(432432)\n    line_list[1].setSourceTotalAssetPrice(-100)\n    line_list[1].setDestinationTotalAssetPrice(-100)\n    line_list[1].setQuantity(32546787)\n    try:\n      self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n      self.assertEqual(accounting_transaction.getSimulationState(), \'stopped\')\n    except ValidationFailed as err:\n      raise AssertionError(\"Validation failed : %s\" % err.msg)\n\n  def stepValidateRemoveEmptyLines(self, sequence, sequence_list=None, **kw):\n    \"\"\"Check validating a transaction remove empty lines. \"\"\"\n    accounting_transaction = sequence.get(\'transaction\')\n    lines_count = len(accounting_transaction.getMovementList())\n    empty_lines_count = 0\n    for line in accounting_transaction.getMovementList():\n      if line.getSourceTotalAssetPrice() ==  \\\n         line.getDestinationTotalAssetPrice() == 0:\n        empty_lines_count += 1\n    if empty_lines_count == 0:\n      accounting_transaction.newContent(\n            portal_type=self.accounting_transaction_line_portal_type)\n\n    self.getWorkflowTool().doActionFor(accounting_transaction, \'stop_action\')\n    self.assertEqual(len(accounting_transaction.getMovementList()),\n                      lines_count - empty_lines_count)\n\n    # we don\'t remove empty lines if there is only empty lines\n    another_accounting_transaction = self.portal.accounting_module.newContent(\n                      portal_type=self.accounting_transaction_portal_type,\n                      start_date=accounting_transaction.getStartDate(),\n                      resource=accounting_transaction.getResource(),\n                      source_section=accounting_transaction.getSourceSection(),\n                      destination_section=accounting_transaction.getDestinationSection(),\n                      created_by_builder=1)\n    for _ in range(3):\n      another_accounting_transaction.newContent(\n            portal_type=self.accounting_transaction_line_portal_type)\n    lines_count = len(another_accounting_transaction.getMovementList())\n    self.getWorkflowTool().doActionFor(another_accounting_transaction, \'stop_action\')\n    self.assertEqual(len(another_accounting_transaction.getMovementList()), lines_count)\n\n  ############################################################################\n  ## Test Methods ############################################################\n  ############################################################################\n\n  def test_MultiCurrencyInvoice(self, quiet=QUIET, run=RUN_ALL_TESTS):\n    \"\"\"Basic test for multi currency accounting\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateCurrencies\n      stepCreateEntities\n      stepCreateAccounts\n      stepCreateInvoices\n      stepTic\n      stepCheckAccountBalanceLocalCurrency\n      stepCheckAccountBalanceExternalCurrency\n      stepCheckAccountBalanceConvertedCurrency\n    \"\"\", quiet=quiet)\n\n  def test_AccountingPeriodRefusesWrongDateTransactionValidation(\n        self, quiet=QUIET, run=RUN_ALL_TESTS):\n    \"\"\"Accounting Periods prevents transactions from being validated when there\n    is no oppened accounting period\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateCurrencies\n      stepCreateEntities\n      stepCreateAccounts\n      stepCreateAccountingPeriod\n      stepOpenAccountingPeriod\n      stepTic\n      stepUseInvalidDates\n      stepCreateInvoices\n      stepCheckStopInvoicesRefused\n      stepTic\n      stepCheckInvoicesAreDraft\n    \"\"\", quiet=quiet)\n\n  def test_AccountingPeriodNotStoppedTransactions(self, quiet=QUIET,\n                                                  run=RUN_ALL_TESTS):\n    \"\"\"Accounting Periods refuse to close when some transactions are\n      not stopped\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateCurrencies\n      stepCreateEntities\n      stepCreateAccounts\n      stepCreateAccountingPeriod\n      stepOpenAccountingPeriod\n      stepTic\n      stepCreateInvoices\n      stepTic\n      stepCheckAccountingPeriodRefusesClosing\n      stepTic\n      stepCheckInvoicesAreDraft\n    \"\"\", quiet=quiet)\n\n  def test_AccountingPeriodOtherSections(self, quiet=QUIET,\n                                                  run=RUN_ALL_TESTS):\n    \"\"\"Accounting Periods does not change other section transactions.\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateCurrencies\n      stepCreateEntities\n      stepCreateAccounts\n      stepCreateAccountingPeriod\n      stepOpenAccountingPeriod\n      stepTic\n      stepCreateOtherSectionInvoices\n      stepTic\n      stepStopAccountingPeriod\n      stepTic\n      stepDeliverAccountingPeriod\n      stepTic\n      stepCheckAccountingPeriodDelivered\n      stepCheckInvoicesAreDraft\n    \"\"\", quiet=quiet)\n\n  def test_Acquisition(self, quiet=QUIET, run=RUN_ALL_TESTS):\n    \"\"\"Tests acquisition, categories and portal types are well\n    configured. \"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateCurrencies\n      stepCheckAcquisition\n      \"\"\", quiet=quiet)\n\n  def test_AccountingTransactionValidationDate(self, quiet=QUIET,\n                                            run=RUN_ALL_TESTS):\n    \"\"\"Transaction validation and dates\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateEntities\n      stepCreateCurrencies\n      stepCreateAccounts\n      stepCreateValidAccountingTransaction\n      stepValidateNoDate\"\"\", quiet=quiet)\n\n\n  def test_AccountingTransactionValidationSection(self, quiet=QUIET,\n                                             run=RUN_ALL_TESTS):\n    \"\"\"Transaction validation and section\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateEntities\n      stepCreateCurrencies\n      stepCreateAccounts\n      stepCreateValidAccountingTransaction\n      stepValidateNoSection\"\"\", quiet=quiet)\n\n  def test_AccountingTransactionValidationCurrency(self, quiet=QUIET,\n                                           run=RUN_ALL_TESTS):\n    \"\"\"Transaction validation and currency\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateEntities\n      stepCreateCurrencies\n      stepCreateAccounts\n      stepCreateValidAccountingTransaction\n      stepValidateNoCurrency\"\"\", quiet=quiet)\n\n  def test_AccountingTransactionValidationAccounts(self, quiet=QUIET,\n                                           run=RUN_ALL_TESTS):\n    \"\"\"Transaction validation and accounts\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateEntities\n      stepCreateCurrencies\n      stepCreateAccounts\n      stepCreateValidAccountingTransaction\n      stepValidateClosedAccount\n      stepCreateValidAccountingTransaction\n      stepValidateNoAccounts\"\"\", quiet=quiet)\n\n  def test_AccountingTransactionValidationBalanced(self, quiet=QUIET,\n                                              run=RUN_ALL_TESTS):\n    \"\"\"Transaction validation and balance\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateEntities\n      stepCreateCurrencies\n      stepCreateAccounts\n      stepCreateValidAccountingTransaction\n      stepValidateNotBalanced\"\"\", quiet=quiet)\n\n  def test_AccountingTransactionValidationRemoveEmptyLines(self, quiet=QUIET,\n                                             run=RUN_ALL_TESTS):\n    \"\"\"Transaction validation removes empty lines\"\"\"\n    if not run : return\n    self.playSequence(\"\"\"\n      stepCreateEntities\n      stepCreateCurrencies\n      stepCreateAccounts\n      stepCreateValidAccountingTransaction\n      stepValidateRemoveEmptyLines\n    \"\"\", quiet=quiet)\n\n\nclass TestAccountingTransactionTemplate(AccountingTestCase):\n  \"\"\"A test for Accounting Transaction Template\n  \"\"\"\n\n  def getTitle(self):\n    return \"Accounting Transaction Template\"\n\n  def disableUserPreferenceList(self):\n    \"\"\"Disable existing User preferences.\"\"\"\n    for preference in self.portal.portal_preferences.objectValues():\n      if preference.getPriority() == Priority.USER:\n        preference.disable()\n\n  def test_Template(self):\n    self.disableUserPreferenceList()\n    self.createUserAndlogin(\'claudie\')\n    preference = self.portal.portal_preferences.newContent(\'Preference\')\n    preference.priority = Priority.USER\n    preference.enable()\n\n    self.tic()\n\n    document = self.accounting_module.newContent(\n                    portal_type=\'Accounting Transaction\')\n    document.edit(title=\'My Accounting Transaction\')\n    document.Base_makeTemplateFromDocument(form_id=None)\n\n    self.tic()\n\n    self.assertEqual(len(preference.objectIds()), 1)\n\n    # make sure that subobjects are not unindexed after making template.\n    subobject_uid = document.objectValues()[0].getUid()\n    self.assertEqual(len(self.portal.portal_catalog(uid=subobject_uid)), 1)\n\n    self.accounting_module.manage_delObjects(ids=[document.getId()])\n\n    self.tic()\n\n    template = preference.objectValues()[0]\n\n    cp = preference.manage_copyObjects(ids=[template.getId()],\n                                       REQUEST=None, RESPONSE=None)\n    new_document_list = self.accounting_module.manage_pasteObjects(cp)\n    new_document_id = new_document_list[0][\'new_id\']\n    new_document = self.accounting_module[new_document_id]\n    new_document.makeTemplateInstance()\n\n    self.tic()\n\n    self.assertEqual(new_document.getTitle(), \'My Accounting Transaction\')\n\n  def test_Base_doAction(self):\n    # test creating a template using Base_doAction script (this is what\n    # erp5_xhtml_style does)\n    self.disableUserPreferenceList()\n    self.createUserAndlogin(\'claudie\')\n    preference = self.portal.portal_preferences.newContent(\'Preference\')\n    preference.priority = Priority.USER\n    preference.enable()\n\n    self.tic()\n\n    document = self.accounting_module.newContent(\n                              portal_type=\'Accounting Transaction\')\n    document.edit(title=\'My Accounting Transaction\')\n    document.Base_makeTemplateFromDocument(form_id=None)\n\n    template = preference.objectValues()[0]\n    ret = self.accounting_module.Base_doAction(\n        select_action=\'template %s\' % template.getRelativeUrl(),\n        form_id=\'\', cancel_url=\'\')\n    self.assertTrue(\'Template%20created.\' in ret, ret)\n    self.assertEqual(2, len(self.accounting_module.contentValues()))\n\nclass TestInternalInvoiceTransaction(AccountingTestCase):\n  def afterSetUp(self):\n    AccountingTestCase.afterSetUp(self)\n    # Allow internal invoice in accounting module\n    module_allowed_type_list = self.portal.portal_types[\n        \'Accounting Transaction Module\'].getTypeAllowedContentTypeList()\n    self.portal.portal_types[\n        \'Accounting Transaction Module\'].setTypeAllowedContentTypeList(\n          module_allowed_type_list + [\'Internal Invoice Transaction\',])\n    # configure mirror accounts\n    self.portal.account_module.receivable.setDestinationValue(\n      self.portal.account_module.payable)\n\n  def test_internal_invoice_transaction(self):\n    # source accountant create internal invoice and set values for source side\n    internal_invoice = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'test invoice\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n    )\n    line_1, line_2 = internal_invoice.getMovementList()\n    line_1.edit(\n      source_value=self.portal.account_module.receivable,\n      source_debit=100)\n    line_2.edit(\n      source_value=self.portal.account_module.goods_sales,\n      source_credit=100)\n    self.commit()\n    internal_invoice.view() # no error on view..\n\n    self.portal.portal_workflow.doActionFor(\n        internal_invoice, \'start_action\')\n    self.assertEqual(\'started\', internal_invoice.getSimulationState())\n\n    # mirror accounts are initialised\n    self.assertEqual(self.portal.account_module.payable, line_1.getDestinationValue())\n    self.assertEqual(None, line_2.getDestinationValue())\n\n    # destination accountant set values for source side\n    internal_invoice.edit(\n      stop_date=DateTime(2015, 1, 2),\n    )\n    # the amounts can be split over multiple accounts\n    internal_invoice.newContent(\n      portal_type=\'Internal Invoice Transaction Line\',\n      destination_value=self.portal.account_module.refundable_vat,\n      destination_debit=30)\n    internal_invoice.newContent(\n      portal_type=\'Internal Invoice Transaction Line\',\n      destination_value=self.portal.account_module.goods_purchase,\n      destination_debit=70)\n\n    self.portal.portal_workflow.doActionFor(\n        internal_invoice, \'stop_action\')\n    self.assertEqual(\'stopped\', internal_invoice.getSimulationState())\n\n    # the lines are different on source and destination views\n    source_line_list = internal_invoice.InternalInvoiceTransaction_viewSource.listbox.get_value(\n      \'default\',\n      render_format=\'list\',\n      REQUEST=self.portal.REQUEST)\n    self.assertEqual(2, len([l for l in source_line_list if l.isDataLine()]))\n    stat_line, = [l for l in source_line_list if l.isStatLine()]\n    self.assertEqual(100, stat_line.getColumnProperty(\'source_debit\'))\n    self.assertEqual(100, stat_line.getColumnProperty(\'source_credit\'))\n\n    destination_line_list = internal_invoice.InternalInvoiceTransaction_viewDestination.listbox.get_value(\n      \'default\',\n      render_format=\'list\',\n      REQUEST=self.portal.REQUEST)\n    self.assertEqual(3, len([l for l in destination_line_list if l.isDataLine()]))\n    stat_line, = [l for l in destination_line_list if l.isStatLine()]\n    self.assertEqual(100, stat_line.getColumnProperty(\'destination_debit\'))\n    self.assertEqual(100, stat_line.getColumnProperty(\'destination_credit\'))\n\n  def test_internal_invoice_transaction_balanced_constraint(self):\n    internal_invoice = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'test invoice\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n    )\n    line_1, line_2 = internal_invoice.getMovementList()\n    line_1.edit(\n      source_value=self.portal.account_module.receivable,\n      source_debit=100)\n    line_2.edit(\n      source_value=self.portal.account_module.goods_sales,\n      source_credit=101)\n\n    with self.assertRaisesRegex(ValidationFailed,\n        \'.*Transaction is not balanced.*\'):\n      self.portal.portal_workflow.doActionFor(\n        internal_invoice, \'start_action\')\n\n    line_2.setSourceCredit(100)\n    self.portal.portal_workflow.doActionFor(\n      internal_invoice, \'start_action\')\n\n    self.assertEqual(\'started\', internal_invoice.getSimulationState())\n\n    self.assertEqual(self.portal.account_module.payable, line_1.getDestinationValue())\n    line_3 = internal_invoice.newContent(\n      portal_type=\'Internal Invoice Transaction Line\',\n      destination_value=self.portal.account_module.refundable_vat,\n      destination_debit=101)\n\n    with self.assertRaisesRegex(ValidationFailed,\n        \'.*Transaction is not balanced.*\'):\n      self.portal.portal_workflow.doActionFor(\n        internal_invoice, \'stop_action\')\n\n    line_3.setDestinationDebit(100)\n    self.portal.portal_workflow.doActionFor(\n        internal_invoice, \'stop_action\')\n    self.assertEqual(\'stopped\', internal_invoice.getSimulationState())\n\n  def test_internal_invoice_create_related_payment(self):\n    # \'Create Related Payment\' is available on internal invoice transaction\n    internal_invoice = self.portal.accounting_module.newContent(\n        portal_type=\'Internal Invoice Transaction\',\n        title=\'test invoice\',\n        source_section_value=self.section,\n        destination_section_value=self.main_section,\n        start_date=DateTime(2015, 1, 1),\n    )\n    line_1, line_2 = internal_invoice.getMovementList()\n    line_1.edit(\n        source_value=self.portal.account_module.receivable,\n        source_debit=100)\n    line_2.edit(\n        source_value=self.portal.account_module.goods_sales,\n        source_credit=100)\n    self.commit()\n\n    self.portal.portal_workflow.doActionFor(\n        internal_invoice, \'start_action\')\n    self.assertEqual(\'started\', internal_invoice.getSimulationState())\n\n    payment_node = self.section.newContent(portal_type=\'Bank Account\')\n\n    payment = internal_invoice.Invoice_createRelatedPaymentTransaction(\n        node=self.account_module.bank.getRelativeUrl(),\n        payment=payment_node.getRelativeUrl(),\n        payment_mode=\'check\',\n        batch_mode=True)\n    # on internal invoice transaction, we create a payment transaction\n    self.assertEqual(\n        \'Internal Invoice Transaction\',\n        payment.getPortalType())\n    self.assertEqual(internal_invoice, payment.getCausalityValue())\n    self.assertCountEqual(\n        [ (self.portal.account_module.bank, 100, 0),\n          (self.portal.account_module.receivable, 0, 100), ],\n        [ (line.getSourceValue(), line.getSourceDebit(), line.getSourceCredit())\n          for line in payment.getMovementList(\n              portal_type=\'Internal Invoice Transaction Line\')])\n\n  def test_InternalInvoiceTransaction_statInternalTransactionLineList(self):\n    internal_invoice = self.portal.accounting_module.newContent(\n        portal_type=\'Internal Invoice Transaction\',\n        source_section_value=self.section,\n        destination_section_value=self.main_section,\n        start_date=DateTime(2015, 1, 1),\n        created_by_builder=True,\n    )\n    # line1 counts for both source and destination\n    internal_invoice.newContent(\n      source_value=self.portal.account_module.receivable,\n      destination_value=self.portal.account_module.receivable,\n      source_debit=1, # destination_credit=1\n      source_asset_debit=0.1111111,\n      destination_asset_credit=0.222222,\n    )\n    # line2 does not count for source, it\'s another section\n    internal_invoice.newContent(\n      source_section_value=self.portal.organisation_module.client_1,\n      source_value=self.portal.account_module.receivable,\n      destination_value=self.portal.account_module.receivable,\n      destination_debit=3,\n      destination_asset_debit=0.44444,\n      source_asset_debit=10000,\n    )\n    # line3 does not count for destination, it\'s another section\n    internal_invoice.newContent(\n      source_value=self.portal.account_module.receivable,\n      destination_value=self.portal.account_module.receivable,\n      destination_section_value=self.portal.organisation_module.client_1,\n      source_credit=5,\n      source_asset_credit=0.555555,\n      destination_asset_debit=1000,\n    )\n\n    stat_internal_transaction, = internal_invoice.InternalInvoiceTransaction_statInternalTransactionLineList()\n    self.assertEqual(stat_internal_transaction.source_debit, 1) # line1\n    self.assertEqual(stat_internal_transaction.source_asset_debit, 0.11) # line1\n    self.assertEqual(stat_internal_transaction.source_credit, 5) # line3\n    self.assertEqual(stat_internal_transaction.source_asset_credit, 0.56) # line3\n\n    self.assertEqual(stat_internal_transaction.destination_debit, 3) # line2\n    self.assertEqual(stat_internal_transaction.destination_asset_debit, 0.44) # line2\n    self.assertEqual(stat_internal_transaction.destination_credit, 1) # line1\n    self.assertEqual(stat_internal_transaction.destination_asset_credit, 0.22) # line1\n\n  def test_grouping_reference_both_sides(self):\n    # Group together lines from two internal invoices:\n    #\n    # | Source Account | Debit | Credit | Grouping | Destination Account | Debit | Credit | Grouping |\n    # |----------------|-------|--------|----------|---------------------|-------|--------|----------|\n    # | receivable     | 10    |        | A        |                     |       |        |          |\n    # | sales          |       | 10     |          | purchase            | 10    |        |          |\n    # |                |       |        |          | payable             |       | 10     | B        |\n    # and\n    # | Source Account | Debit | Credit | Grouping | Destination Account | Debit | Credit | Grouping |\n    # |----------------|-------|--------|----------|---------------------|-------|--------|----------|\n    # | sales          | 10    |        |          | purchase            |       | 10     |          |\n    # | receivable     |       | 10     | A        |                     |       |        |          |\n    # |                |       |        |          | payable             | 10    |        | B        |\n    # This example does not really make sense from usage of internal invoices, because we usually\n    # use the same line for receivable and purchase in such a case, but it reproduces a case that did\n    # not group automatically.\n\n    internal_invoice1 = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'internal_invoice1\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n      created_by_builder=True,\n    )\n    # start before creating lines, because we don\'t want our lines to\n    # be initialized with mirror accounts.\n    internal_invoice1.start()\n    internal_invoice1.newContent(\n      id=\'line_a\',\n      source_value=self.portal.account_module.receivable,\n      source_debit=10,\n    )\n    internal_invoice1.newContent(\n      source_value=self.portal.account_module.goods_sales,\n      destination_value=self.portal.account_module.goods_purchase,\n      source_credit=10,\n    )\n    internal_invoice1.newContent(\n      id=\'line_b\',\n      destination_value=self.portal.account_module.payable,\n      destination_credit=10,\n    )\n    internal_invoice1.stop()\n    self.tic()\n\n    internal_invoice2 = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'internal_invoice2\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n      causality_value=internal_invoice1,\n      created_by_builder=True,\n    )\n    internal_invoice2.start()\n    internal_invoice2.newContent(\n      source_value=self.portal.account_module.goods_sales,\n      destination_value=self.portal.account_module.goods_purchase,\n      source_debit=10,\n    )\n    internal_invoice2.newContent(\n      id=\'line_a\',\n      source_value=self.portal.account_module.receivable,\n      source_credit=10,\n    )\n    internal_invoice2.newContent(\n      id=\'line_b\',\n      destination_value=self.portal.account_module.payable,\n      destination_debit=10,\n    )\n    internal_invoice2.stop()\n    self.tic()\n    self.assertTrue(internal_invoice1.line_a.getGroupingReference())\n    self.assertEqual(\n      internal_invoice1.line_a.getGroupingReference(),\n      internal_invoice2.line_a.getGroupingReference(),\n    )\n    self.assertTrue(internal_invoice1.line_b.getGroupingReference())\n    self.assertEqual(\n      internal_invoice1.line_b.getGroupingReference(),\n      internal_invoice2.line_b.getGroupingReference(),\n    )\n\n  def test_grouping_reference_no_group_when_mirror_accounts_are_different(self):\n    # Does not together lines from two internal invoices:\n    #\n    # | Source Account | Debit | Credit | Grouping | Destination Account | Debit | Credit | Grouping |\n    # |----------------|-------|--------|----------|---------------------|-------|--------|----------|\n    # | receivable     | 10    |        |  no  ->  | payable             |       | 10     |          |\n    # | sales          |       | 10     |          | purchase            | 10    |        |          |\n    # and\n    # | Source Account | Debit | Credit | Grouping | Destination Account | Debit | Credit | Grouping |\n    # |----------------|-------|--------|----------|---------------------|-------|--------|----------|\n    # | sales          | 10    |        |          | payable             |       | 10     |          |\n    # | receivable     |       | 10     |  no  ->  | purchase            | 10    |        |          |\n\n    internal_invoice1 = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'internal_invoice1\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n      created_by_builder=True,\n    )\n    internal_invoice1.start()\n    internal_invoice1.newContent(\n      id=\'line1\',\n      source_value=self.portal.account_module.receivable,\n      destination_value=self.portal.account_module.payable,\n      source_debit=10,\n    )\n    internal_invoice1.newContent(\n      id=\'line2\',\n      source_value=self.portal.account_module.goods_sales,\n      destination_value=self.portal.account_module.goods_purchase,\n      source_credit=10,\n    )\n    internal_invoice1.stop()\n    self.tic()\n\n    internal_invoice2 = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'internal_invoice2\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n      causality_value=internal_invoice1,\n      created_by_builder=True,\n    )\n    internal_invoice2.start()\n    internal_invoice2.newContent(\n      id=\'line1\',\n      source_value=self.portal.account_module.goods_sales,\n      destination_value=self.portal.account_module.payable,\n      source_debit=10,\n    )\n    internal_invoice2.newContent(\n      id=\'line2\',\n      source_value=self.portal.account_module.receivable,\n      destination_value=self.portal.account_module.goods_purchase,\n      source_debit=10,\n    )\n    internal_invoice2.stop()\n    self.tic()\n    self.assertFalse(internal_invoice1.line1.getGroupingReference())\n    self.assertFalse(internal_invoice1.line2.getGroupingReference())\n    self.assertFalse(internal_invoice2.line1.getGroupingReference())\n    self.assertFalse(internal_invoice2.line2.getGroupingReference())\n\n  def test_grouping_reference_both_sides_with_line_for_0(self):\n    # Lines for 0 are automatically grouped, but this takes care that the\n    # amount is also 0 for the mirror side.\n    # | Source Account | Debit | Credit | Grouping | Destination Account | Debit | Credit | Grouping |\n    # |----------------|-------|--------|----------|---------------------|-------|--------|----------|\n    # | receivable     | 0     |        | A        |                     |       |        |          |\n    # | sales          |       | 0      |          | purchase            | 10    |        |          |\n    # |                |       |        |          | payable             |       | 10     |          |\n    # |                |       |        |          | receivable          |       |  0     |  A       |\n    #\n    internal_invoice1 = self.portal.accounting_module.newContent(\n      portal_type=\'Internal Invoice Transaction\',\n      title=\'internal_invoice1\',\n      source_section_value=self.section,\n      destination_section_value=self.main_section,\n      start_date=DateTime(2015, 1, 1),\n      created_by_builder=True,\n    )\n    # start before creating lines, because we don\'t want our lines to\n    # be initialized with mirror accounts.\n    internal_invoice1.start()\n    internal_invoice1.newContent(\n      id=\'line_1\',\n      source_value=self.portal.account_module.receivable,\n      source_debit=0,\n    )\n    internal_invoice1.newContent(\n      id=\'line_2\',\n      source_value=self.portal.account_module.goods_sales,\n      destination_value=self.portal.account_module.goods_purchase,\n      source_credit=0,\n      destination_asset_debit=10,\n    )\n    internal_invoice1.newContent(\n      id=\'line_3\',\n      destination_value=self.portal.account_module.payable,\n      destination_asset_credit=10,\n    )\n    internal_invoice1.newContent(\n      id=\'line_4\',\n      destination_value=self.portal.account_module.receivable,\n      destination_credit=0,\n    )\n    internal_invoice1.stop()\n    self.tic()\n\n    self.assertTrue(internal_invoice1.line_1.getGroupingReference())\n    self.assertFalse(internal_invoice1.line_2.getGroupingReference())\n    self.assertFalse(internal_invoice1.line_3.getGroupingReference())\n    self.assertTrue(internal_invoice1.line_4.getGroupingReference())\n\n\nclass TestAccountingAlarms(AccountingTestCase):\n  def test_check_payable_receivable_account_grouped(self):\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               simulation_state=\'stopped\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=100),\n                      dict(source_value=self.account_module.goods_sales,\n                           id=\'line_to_group_with_itself\',\n                           source_debit=0),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=100,\n                           id=\'line_to_group\',),))\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               simulation_state=\'stopped\',\n               lines=(dict(source_value=self.account_module.receivable,\n                           id=\'line_to_group\',\n                           source_debit=100),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=100,)))\n    self.tic()\n\n    self.login()\n    alarm = self.portal.portal_alarms.check_payable_receivable_account_grouped\n    alarm.edit(section_category=\'group/demo_group\')\n\n    # this alarm detect problem\n    alarm.activeSense()\n    self.tic()\n    self.assertEqual(\n        [\'organisation_module/client_1 has a 0 balance but some not grouped transactions.\\n\'],\n        [x.getProperty(\'detail\') for x in alarm.getLastActiveProcess().getResultList()])\n    self.assertTrue(alarm.sense())\n\n    # and can fix problems\n    alarm.activeSense(fixit=True)\n    self.tic()\n    self.assertTrue(alarm.sense())\n    self.assertTrue(invoice.line_to_group.getGroupingReference())\n    self.assertEqual(\n        invoice.line_to_group.getGroupingReference(),\n        payment.line_to_group.getGroupingReference())\n    self.assertTrue(invoice.line_to_group_with_itself.getGroupingReference())\n\n  def test_check_grouping_reference_validity(self):\n    # Two transactions grouped together, but grouped quantities do not match (3 != 7)\n    invoice = self._makeOne(\n               title=\'First Invoice\',\n               destination_section_value=self.organisation_module.client_1,\n               simulation_state=\'stopped\',\n               lines=(dict(source_value=self.account_module.goods_purchase,\n                           source_debit=3),\n                      dict(source_value=self.account_module.receivable,\n                           source_credit=3,\n                           id=\'grouped_line\',\n                           grouping_reference=\'A\',\n                           grouping_date=DateTime(),),))\n    payment = self._makeOne(\n               title=\'First Invoice Payment\',\n               portal_type=\'Payment Transaction\',\n               source_payment_value=self.section.newContent(\n                                            portal_type=\'Bank Account\'),\n               destination_section_value=self.organisation_module.client_1,\n               simulation_state=\'stopped\',\n               lines=(dict(source_value=self.account_module.receivable,\n                           source_debit=7,\n                           id=\'grouped_line\',\n                           grouping_reference=\'A\',\n                           grouping_date=DateTime(),),\n                      dict(source_value=self.account_module.bank,\n                           source_credit=7,)))\n    self.tic()\n\n    self.login()\n    alarm = self.portal.portal_alarms.check_grouping_reference_validity\n\n    # this alarm detect problem\n    alarm.activeSense()\n    self.tic()\n    self.assertEqual(\n        sorted([\n            # 4.0 is the difference in grouping ( 7 - 3 )\n            \'{} has wrong grouping (4.0)\'.format(invoice.grouped_line.getRelativeUrl()),\n            \'{} has wrong grouping (4.0)\'.format(payment.grouped_line.getRelativeUrl()),]),\n        sorted([x.getProperty(\'detail\') for x in alarm.getLastActiveProcess().getResultList()]))\n    self.assertTrue(alarm.sense())\n\n\nclass TestAccountingPeriod(AccountingTestCase):\n\n  def test_generate_sub_accounting_periods(self):\n    accounting_period_2007 = self.section.newContent(\n                                portal_type=\'Accounting Period\',\n                                start_date=DateTime(\'2007/01/01\'),\n                                stop_date=DateTime(\'2007/12/31\'),)\n    accounting_period_2007.start()\n\n    accounting_period_2007.AccountingPeriod_createSecondaryPeriod(\n          frequency=\'monthly\', open_periods=1)\n    sub_period_list = sorted(accounting_period_2007.contentValues(),\n                              key=lambda x:x.getStartDate())\n    self.assertEqual(12, len(sub_period_list))\n    first_period = sub_period_list[0]\n    self.assertEqual(DateTime(2007, 1, 1), first_period.getStartDate())\n    self.assertEqual(DateTime(2007, 1, 31), first_period.getStopDate())\n    self.assertEqual(\'2007-01\', first_period.getShortTitle())\n    self.assertEqual(\'January\', first_period.getTitle())\n\n  def test_accounting_period_workflow_constraint(self):\n    first_accounting_period = self.section.newContent(\n        portal_type=\'Accounting Period\',\n        start_date=DateTime(\'2021/01/01\'),\n        stop_date=DateTime(\'2020/12/31\'),)\n    with self.assertRaisesRegex(ValidationFailed,\n        \'Start date is after stop date\'):\n      self.portal.portal_workflow.doActionFor(first_accounting_period, \'start_action\')\n\n    # make first accounting period valid, for the full 2021 year\n    first_accounting_period.setStopDate(DateTime(\'2021/12/31\'))\n    self.portal.portal_workflow.doActionFor(first_accounting_period, \'start_action\')\n    self.tic()\n\n    # check dates don\'t overlap\n    second_accounting_period = self.section.newContent(\n        portal_type=\'Accounting Period\',\n        start_date=DateTime(\'2021/01/01\'),\n        stop_date=DateTime(\'2022/12/31\'),)\n    with self.assertRaisesRegex(ValidationFailed,\n        \'2021/01/01 00:00:00 .* is already in an open accounting period.\'):\n      self.portal.portal_workflow.doActionFor(second_accounting_period, \'start_action\')\n\n    # check there are no \"holes\" between dates\n    second_accounting_period.setStartDate(\'2022/01/02\')\n    with self.assertRaisesRegex(ValidationFailed,\n        \'Last opened period ends on 2021/12/31.*, this period starts on 2022/01/02.*. Accounting Periods must be consecutive.\'):\n      self.portal.portal_workflow.doActionFor(second_accounting_period, \'start_action\')\n\n    # edge case, when the end date of previous period is a DST swich, this should not block\n    first_accounting_period.setStopDate(DateTime(\'2021/10/31 00:00:00 Europe/Paris\'))\n    second_accounting_period.setStartDate(DateTime(\'2021/11/01 00:00:00 Europe/Paris\'))\n    self.portal.portal_workflow.doActionFor(second_accounting_period, \'start_action\')\n\n    # reset first period to 2021 and second period 2022\n    first_accounting_period.setStopDate(DateTime(\'2021/12/31\'))\n    second_accounting_period.setStartDate(DateTime(\'2022/01/01\'))\n    second_accounting_period.setStopDate(DateTime(\'2022/12/31\'))\n\n    # check also with more than 2 periods\n    third_accounting_period = self.section.newContent(\n        portal_type=\'Accounting Period\',\n        start_date=DateTime(\'2023/01/01\'),\n        stop_date=DateTime(\'2023/12/31\'),)\n    self.portal.portal_workflow.doActionFor(third_accounting_period, \'start_action\')\n\n\nclass TestInvoice_getPaymentTransactionDueDate(AccountingTestCase):\n  \"\"\"Test Invoice_getPaymentTransactionDueDate.\n  \"\"\"\n\n  def test_due_date_calculation(self):\n    \"\"\"Test the rule to calculate the due date from payment condition properties.\n    \"\"\"\n    sale_trade_condition = self.portal.sale_trade_condition_module.newContent(\n        portal_type=\'Sale Trade Condition\',\n    )\n    invoice = self._makeOne(\n        portal_type=\'Sale Invoice Transaction\',\n        stop_date=DateTime(1970, 1, 1)\n    )\n\n    self.assertEqual(invoice.Invoice_getPaymentDueDate(), None)\n    invoice.setSpecialiseValue(sale_trade_condition)\n    self.assertEqual(invoice.Invoice_getPaymentDueDate(), None)\n    sale_trade_condition.setPaymentConditionTradeDate(\'invoice\')\n\n\n    for invoice_date, payment_term, payment_end_of_month, payment_additional_term, expected_date in (\n        (DateTime(\'2001/01/01\'), 10, False, 0, DateTime(\'2001/01/11\')),\n        (DateTime(\'2001/01/01\'), 10, True, 0, DateTime(\'2001/01/31\')),\n        (DateTime(\'2001/01/01\'), 10, True, 10, DateTime(\'2001/02/10\')),\n        (DateTime(\'2001/01/31\'), 10, False, 0, DateTime(\'2001/02/10\')),\n        (DateTime(\'2001/01/31\'), 10, True, 0, DateTime(\'2001/02/28\')),\n        (DateTime(\'2001/01/31\'), 10, True, 15, DateTime(\'2001/03/15\')),\n        # leap year\n        (DateTime(\'2004/01/31\'), 10, True, 0, DateTime(\'2004/02/29\')),\n        # this keeps hours/minutes and timezones\n        (DateTime(\'2001/01/01 01:02:03 GMT+2\'), 10, False, 0, DateTime(\'2001/01/11 01:02:03 GMT+2\')),\n        # and works well across daylight time switchs\n        (DateTime(\'2001/03/31 00:00:00 Europe/Paris\'), 10, False, 0, DateTime(\'2001/04/10 00:00:00 Europe/Paris\')),\n        (DateTime(\'2001/03/31 00:00:00 Europe/Paris\'), 0, False, 10, DateTime(\'2001/04/10 00:00:00 Europe/Paris\')),\n        (DateTime(\'2001/10/27 00:00:00 Europe/Paris\'), 10, False, 0, DateTime(\'2001/11/06 00:00:00 Europe/Paris\')),\n        (DateTime(\'2001/10/27 00:00:00 Europe/Paris\'), 0, False, 10, DateTime(\'2001/11/06 00:00:00 Europe/Paris\')),\n    ):\n      invoice.setStartDate(invoice_date)\n      sale_trade_condition.setPaymentConditionPaymentTerm(payment_term)\n      sale_trade_condition.setPaymentConditionPaymentEndOfMonth(payment_end_of_month)\n      sale_trade_condition.setPaymentConditionPaymentAdditionalTerm(payment_additional_term)\n      self.assertEqual(\n          invoice.Invoice_getPaymentDueDate(),\n          expected_date,\n          \"{actual} != {expected_date} for case invoice_date:{invoice_date}, \"\n          \"payment_term:{payment_term}, payment_end_of_month:{payment_end_of_month}, \"\n          \"payment_additional_term:{payment_additional_term}\".format(\n              actual=invoice.Invoice_getPaymentDueDate(),\n              **locals()\n          )\n      )\n\n  def test_sale_invoice_packing_list_or_order(self):\n    \"\"\"Test how the date is selected from invoice, packing list or order, for sales case\n    \"\"\"\n    sale_trade_condition = self.portal.sale_trade_condition_module.newContent(\n        portal_type=\'Sale Trade Condition\',\n        payment_condition_payment_term=10,\n    )\n    order = self.portal.sale_order_module.newContent(\n        portal_type=\'Sale Order\',\n        start_date=DateTime(2001, 1, 1),\n        stop_date=DateTime(1970, 1, 1),\n    )\n    delivery = self.portal.sale_packing_list_module.newContent(\n        portal_type=\'Sale Packing List\',\n        start_date=DateTime(1970, 1, 1),\n        stop_date=DateTime(2002, 1, 1),\n        causality_value=order,\n    )\n    invoice = self._makeOne(\n        portal_type=\'Sale Invoice Transaction\',\n        start_date=DateTime(2003, 1, 1),\n        stop_date=DateTime(1970, 1, 1),\n        specialise_value=sale_trade_condition,\n    )\n    trade_date = self.portal.portal_categories.trade_date\n    sale_trade_condition.setPaymentConditionTradeDate(trade_date.invoice.getRelativeUrl())\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        DateTime(2003, 1, 11))\n\n    sale_trade_condition.setPaymentConditionTradeDate(trade_date.packing_list.getRelativeUrl())\n    # no related delivery\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        None)\n    invoice.setCausalityValue(delivery)\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        DateTime(2002, 1, 11))\n\n    sale_trade_condition.setPaymentConditionTradeDate(trade_date.order.getRelativeUrl())\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        DateTime(2001, 1, 11))\n\n  def test_purchase_invoice_packing_list_or_order(self):\n    \"\"\"Test how the date is selected from invoice, packing list or order, for purchase case\n    \"\"\"\n    purchase_trade_condition = self.portal.purchase_trade_condition_module.newContent(\n        portal_type=\'Purchase Trade Condition\',\n        payment_condition_payment_term=10,\n    )\n    order = self.portal.purchase_order_module.newContent(\n        portal_type=\'Purchase Order\',\n        start_date=DateTime(2001, 1, 1),\n        stop_date=DateTime(1970, 1, 1),\n    )\n    delivery = self.portal.purchase_packing_list_module.newContent(\n        portal_type=\'Purchase Packing List\',\n        start_date=DateTime(1970, 1, 1),\n        stop_date=DateTime(2002, 1, 1),\n        causality_value=order,\n    )\n    invoice = self._makeOne(\n        portal_type=\'Purchase Invoice Transaction\',\n        start_date=DateTime(2003, 1, 1),\n        specialise_value=purchase_trade_condition,\n    )\n    trade_date = self.portal.portal_categories.trade_date\n    purchase_trade_condition.setPaymentConditionTradeDate(trade_date.invoice.getRelativeUrl())\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        DateTime(2003, 1, 11))\n\n    purchase_trade_condition.setPaymentConditionTradeDate(trade_date.packing_list.getRelativeUrl())\n    # no related delivery\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        None)\n    invoice.setCausalityValue(delivery)\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        DateTime(2002, 1, 11))\n\n    purchase_trade_condition.setPaymentConditionTradeDate(trade_date.order.getRelativeUrl())\n    self.assertEqual(\n        invoice.Invoice_getPaymentDueDate(),\n        DateTime(2001, 1, 11))'),(3455,'AccountingTransactionConstraint'),(3458,'AccountingTransactionBalanceConstraint'),(3460,'AccountTypeConstraint'),(3461,'document.erp5.PaymentSimulationRule PaymentSimulationRule # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2010 Nexedi SARL and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.mixin.RuleMixin import RuleMixin\nfrom erp5.component.mixin.MovementGeneratorMixin import MovementGeneratorMixin\nfrom erp5.component.mixin.MovementCollectionUpdaterMixin import MovementCollectionUpdaterMixin\nfrom erp5.component.interface.IRule import IRule\nfrom erp5.component.interface.IDivergenceController import IDivergenceController\nfrom erp5.component.interface.IMovementCollectionUpdater import IMovementCollectionUpdater\n\n@zope.interface.implementer(IRule,\n                            IDivergenceController,\n                            IMovementCollectionUpdater,)\nclass PaymentSimulationRule(RuleMixin, MovementCollectionUpdaterMixin):\n  \"\"\"\n  Payment Rule generates payment simulation movement from invoice\n  transaction simulation movements.\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Payment Simulation Rule\'\n  portal_type = \'Payment Simulation Rule\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = (\n    PropertySheet.Base,\n    PropertySheet.XMLObject,\n    PropertySheet.CategoryCore,\n    PropertySheet.DublinCore,\n    PropertySheet.Task,\n    PropertySheet.Predicate,\n    PropertySheet.Reference,\n    PropertySheet.Version,\n    PropertySheet.Rule\n    )\n\n  def _getMovementGenerator(self, context):\n    \"\"\"\n    Return the movement generator to use in the expand process\n    \"\"\"\n    return PaymentRuleMovementGenerator(applied_rule=context, rule=self)\n\n  def _isProfitAndLossMovement(self, movement):\n    # For a kind of trade rule, a profit and loss movement lacks source\n    # or destination.\n    return (movement.getSource() is None or movement.getDestination() is None)\n\nclass PaymentRuleMovementGenerator(MovementGeneratorMixin):\n\n  def _getUpdatePropertyDict(self, input_movement):\n    return {\'delivery\': None,\n            \'order\': None} # XXX is it useful ?\n\n  def _getInputMovementList(self, movement_list=None, rounding=None):\n    return [self._applied_rule.getParentValue(),]'),(3462,'document.erp5.Invoice Invoice ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.AccountingTransaction import AccountingTransaction\nfrom erp5.component.document.Delivery import Delivery\n\nclass Invoice(AccountingTransaction):\n  # CMF Type Definition\n  meta_type = \'ERP5 Invoice\'\n  portal_type = \'Invoice\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Delivery\n                    , PropertySheet.Order\n                    , PropertySheet.Task\n                    , PropertySheet.Arrow\n                    , PropertySheet.Movement\n                    , PropertySheet.Reference\n                    , PropertySheet.TradeCondition\n                    , PropertySheet.Folder\n                    )\n\n  security.declareProtected(\n      Permissions.AccessContentsInformation, \'getTotalPrice\')\n  def getTotalPrice(self, **kw):\n    \"\"\" Returns the total price for this invoice \"\"\"\n    kw.setdefault(\'portal_type\',\n                  self.getPortalInvoiceMovementTypeList())\n    return Delivery.getTotalPrice(self, **kw)\n\n  security.declareProtected(\n      Permissions.AccessContentsInformation, \'getTotalQuantity\')\n  def getTotalQuantity(self, **kw):\n    \"\"\" Returns the total quantity for this invoice \"\"\"\n    kw.setdefault(\'portal_type\',\n                  self.getPortalInvoiceMovementTypeList())\n    return Delivery.getTotalQuantity(self, **kw)'),(3463,'document.erp5.BalanceTransactionLine BalanceTransactionLine ##############################################################################\n#\n# Copyright (c) 2007 Nexedi SA and Contributors. All Rights Reserved.\n#                    Jerome Perrin <jerome@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions\nfrom Products.ERP5Type.Accessor.Constant import PropertyGetter as ConstantGetter\nfrom erp5.component.document.AccountingTransactionLine import \\\n                      AccountingTransactionLine\nfrom erp5.component.document.InventoryLine import InventoryLine\n\n\nclass BalanceTransactionLine(AccountingTransactionLine, InventoryLine):\n  \"\"\"A balance transaction line inherits price handling from accounting\n  transaction line, and indexing from inventory line.\n  \"\"\"\n\n  meta_type = \'ERP5 Balance Transaction Line\'\n  portal_type = \'Balance Transaction Line\'\n  add_permission = Permissions.AddPortalContent\n  isInventoryMovement = ConstantGetter(\'isInventoryMovement\', value=True)\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  reindexObject = InventoryLine.reindexObject\n  recursiveReindexObject = InventoryLine.recursiveReindexObject\n  immediateReindexObject = InventoryLine.immediateReindexObject'),(3464,'document.erp5.BalanceTransaction BalanceTransaction ##############################################################################\n#\n# Copyright (c) 2007 Nexedi SA and Contributors. All Rights Reserved.\n#                    Jerome Perrin <jerome@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom six.moves import UserDict\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.Inventory import Inventory\nfrom erp5.component.document.AccountingTransaction import AccountingTransaction\nfrom Products.ZSQLCatalog.SQLCatalog import Query\nimport types\n\n\nclass InventoryKey(UserDict):\n  \"\"\"Class to use as a key when defining inventory dicts.\n  \"\"\"\n  def __init__(self, **kw): # pylint: disable=super-init-not-called\n    self.data = {}\n    self.data.update(kw)\n\n  def _raise_immutable(self, *args, **kw):\n    raise TypeError(\'InventoryKey are immutable\')\n  clear = pop = update = __delitem__ = __setitem__ = _raise_immutable\n\n  def setdefault(self, key, *args, **kwargs):\n    if key in self.data:\n      return self.data[key]\n    raise TypeError(\'InventoryKey are immutable\')\n\n  def __hash__(self):\n    return hash(tuple(sorted(self.items())))\n\n\nclass BalanceTransaction(AccountingTransaction, Inventory):\n  \"\"\"Balance Transaction\n  \"\"\"\n\n  # CMF Type Definition\n  meta_type = \'ERP5 Balance Transaction\'\n  portal_type = \'Balance Transaction\'\n  add_permission = Permissions.AddPortalContent\n\n  #zope.interface.implements( interfaces.Inventory, )\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task\n                    , PropertySheet.Arrow\n                    , PropertySheet.Movement\n                    , PropertySheet.Delivery\n                    , PropertySheet.Amount\n                    , PropertySheet.Reference\n                    , PropertySheet.PaymentCondition\n                    )\n\n\n  def _getGroupByNodeMovementList(self):\n    \"\"\"Returns movements that implies only grouping by node.\"\"\"\n    movement_list = []\n    for movement in self.getMovementList(\n              portal_type=self.getPortalAccountingMovementTypeList()):\n      if getattr(movement, \'isAccountable\', 1):\n        if not (movement.getSourceSection() or\n                movement.getDestinationPayment()):\n          movement_list.append(movement)\n    return movement_list\n\n  def _getGroupByPaymentMovementList(self):\n    \"\"\"Returns movements that implies grouping by node and payment\"\"\"\n    movement_list = []\n    for movement in self.getMovementList(\n              portal_type=self.getPortalAccountingMovementTypeList()):\n      if getattr(movement, \'isAccountable\', 1):\n        if movement.getDestinationPayment():\n          movement_list.append(movement)\n    return movement_list\n\n  def _getGroupByMirrorSectionMovementList(self):\n    \"\"\"Returns movements that implies only grouping by node and mirror section\"\"\"\n    movement_list = []\n    for movement in self.getMovementList(\n              portal_type=self.getPortalAccountingMovementTypeList()):\n      if getattr(movement, \'isAccountable\', 1):\n        if movement.getSourceSection():\n          movement_list.append(movement)\n    return movement_list\n\n\n  def _getCurrentStockDict(self):\n    \"\"\"Looks the current stock by calling getInventoryList, and building a\n    dictionnary of InventoryKey\n    \"\"\"\n    current_stock = {}\n    getInventoryList = self.getPortalObject()\\\n                            .portal_simulation.getInventoryList\n    section_uid = self.getDestinationSectionUid()\n    ledger_uid = self.getLedgerUid()\n    if ledger_uid is None:\n      ledger_uid = Query(ledger_uid=None)\n\n    precision = 2\n    if section_uid is not None:\n      accounting_currency = \\\n          self.getDestinationSectionValue().getPriceCurrencyValue()\n      if accounting_currency is not None:\n        precision = accounting_currency.getQuantityPrecision()\n    inventory_date = self.getStartDate()\n    if inventory_date:\n      inventory_date = inventory_date.earliestTime()\n    default_inventory_params = dict(\n                        to_date=inventory_date,\n                        section_uid=section_uid,\n                        precision=precision,\n                        portal_type=self.getPortalAccountingMovementTypeList(),\n                        simulation_state=(\'delivered\', ),\n                        ledger_uid=ledger_uid)\n\n    # node\n    for movement in self._getGroupByNodeMovementList():\n      node_uid = movement.getDestinationUid()\n      if not node_uid:\n        raise ValueError(\"No destination uid for %s\" % movement)\n      resource_uid = movement.getResourceUid()\n\n      stock_list = current_stock.setdefault(\n                         InventoryKey(node_uid=node_uid,\n                                      section_uid=section_uid), [])\n      for inventory in getInventoryList(\n                              node_uid=node_uid,\n                              resource_uid=resource_uid,\n                              group_by_node=1,\n                              group_by_resource=1,\n                              **default_inventory_params):\n        if inventory.total_price or inventory.total_quantity:\n          stock_list.append(\n              dict(destination_uid=node_uid,\n                   destination_section_uid=section_uid,\n                   resource_uid=resource_uid,\n                   relative_url=movement.getRelativeUrl(),\n                   uid=movement.getUid(),\n                   quantity=inventory.total_quantity,\n                   total_price=inventory.total_price, ))\n\n    # mirror section\n    for movement in self._getGroupByMirrorSectionMovementList():\n      node_uid = movement.getDestinationUid()\n      if not node_uid:\n        raise ValueError(\"No destination uid for %s\" % movement)\n      mirror_section_uid = movement.getSourceSectionUid()\n      resource_uid = movement.getResourceUid()\n\n      stock_list = current_stock.setdefault(\n                         InventoryKey(node_uid=node_uid,\n                                      mirror_section_uid=mirror_section_uid,\n                                      section_uid=section_uid), [])\n      for inventory in getInventoryList(\n                              node_uid=node_uid,\n                              mirror_section_uid=mirror_section_uid,\n                              resource_uid=resource_uid,\n                              group_by_node=1,\n                              group_by_mirror_section=1,\n                              group_by_resource=1,\n                              **default_inventory_params):\n        if inventory.total_price or inventory.total_quantity:\n          stock_list.append(\n              dict(destination_uid=node_uid,\n                   destination_section_uid=section_uid,\n                   source_section_uid=mirror_section_uid,\n                   relative_url=movement.getRelativeUrl(),\n                   uid=movement.getUid(),\n                   resource_uid=resource_uid,\n                   quantity=inventory.total_quantity,\n                   total_price=inventory.total_price, ))\n\n    # payment\n    for movement in self._getGroupByPaymentMovementList():\n      node_uid = movement.getDestinationUid()\n      if not node_uid:\n        raise ValueError(\"No destination uid for %s\" % movement)\n      payment_uid = movement.getDestinationPaymentUid()\n      resource_uid = movement.getResourceUid()\n\n      stock_list = current_stock.setdefault(\n                         InventoryKey(node_uid=node_uid,\n                                      section_uid=section_uid,\n                                      payment_uid=payment_uid), [])\n      for inventory in getInventoryList(\n                              node_uid=node_uid,\n                              payment_uid=payment_uid,\n                              resource_uid=resource_uid,\n                              group_by_node=1,\n                              group_by_payment=1,\n                              group_by_resource=1,\n                              **default_inventory_params):\n        if inventory.total_price or inventory.total_quantity:\n          stock_list.append(\n              dict(destination_uid=node_uid,\n                   destination_section_uid=section_uid,\n                   destination_payment_uid=payment_uid,\n                   relative_url=movement.getRelativeUrl(),\n                   uid=movement.getUid(),\n                   resource_uid=resource_uid,\n                   quantity=inventory.total_quantity,\n                   total_price=inventory.total_price, ))\n\n    return current_stock\n\n\n  def _getNewStockDict(self):\n    \"\"\"Looks the new stock on lines in this inventory, and building a\n    dictionnary of InventoryKey\n    \"\"\"\n    new_stock = {}\n    # node\n    for movement in self._getGroupByNodeMovementList():\n      node_uid = movement.getDestinationUid()\n      if not node_uid:\n        raise ValueError(\"No destination uid for %s\" % movement)\n      section_uid = movement.getDestinationSectionUid()\n\n      stock_list = new_stock.setdefault(\n                 InventoryKey(node_uid=node_uid,\n                              section_uid=section_uid), [])\n      stock_list.append(\n              dict(destination_uid=node_uid,\n                   destination_section_uid=section_uid,\n                   resource_uid=movement.getResourceUid(),\n                   id=movement.getId(),\n                   uid=movement.getUid(),\n                   relative_url=movement.getRelativeUrl(),\n                   quantity=movement.getQuantity(),\n                   total_price=movement\\\n                    .getDestinationInventoriatedTotalAssetPrice(),\n                   ledger_uid=movement.getLedgerUid(), ))\n\n    # mirror section\n    for movement in self._getGroupByMirrorSectionMovementList():\n      node_uid = movement.getDestinationUid()\n      if not node_uid:\n        raise ValueError(\"No destination uid for %s\" % movement)\n      section_uid = movement.getDestinationSectionUid()\n      mirror_section_uid = movement.getSourceSectionUid()\n\n      stock_list = new_stock.setdefault(\n                 InventoryKey(node_uid=node_uid,\n                              mirror_section_uid=mirror_section_uid,\n                              section_uid=section_uid), [])\n      stock_list.append(\n              dict(destination_uid=node_uid,\n                   destination_section_uid=section_uid,\n                   source_section_uid=mirror_section_uid,\n                   resource_uid=movement.getResourceUid(),\n                   id=movement.getId(),\n                   uid=movement.getUid(),\n                   relative_url=movement.getRelativeUrl(),\n                   quantity=movement.getQuantity(),\n                   total_price=movement\\\n                    .getDestinationInventoriatedTotalAssetPrice(),\n                   ledger_uid=movement.getLedgerUid(), ))\n\n    # payment\n    for movement in self._getGroupByPaymentMovementList():\n      node_uid = movement.getDestinationUid()\n      if not node_uid:\n        raise ValueError(\"No destination uid for %s\" % movement)\n      section_uid = movement.getDestinationSectionUid()\n      payment_uid = movement.getDestinationPaymentUid()\n\n      stock_list = new_stock.setdefault(\n                 InventoryKey(node_uid=node_uid,\n                              payment_uid=payment_uid,\n                              section_uid=section_uid), [])\n      stock_list.append(\n              dict(destination_uid=node_uid,\n                   destination_section_uid=section_uid,\n                   destination_payment_uid=payment_uid,\n                   resource_uid=movement.getResourceUid(),\n                   id=movement.getId(),\n                   uid=movement.getUid(),\n                   relative_url=movement.getRelativeUrl(),\n                   quantity=movement.getQuantity(),\n                   total_price=movement\\\n                    .getDestinationInventoriatedTotalAssetPrice(),\n                   ledger_uid=movement.getLedgerUid(), ))\n\n    return new_stock\n\n\n  def _computeStockDifferenceList(self, current_stock_dict, new_stock_dict):\n    \"\"\"Compute the difference between the result of _getCurrentStockDict and\n    _getNewStockDict. Returns a list of dictionnaries with similar keys that\n    the ones on inventory brains (node, section, mirror_section ...)\n    \"\"\"\n    precision = self.getResourceValue().getQuantityPrecision()\n\n    def computeStockDifference(current_stock_list, new_stock_list):\n      # helper function to compute difference between two stock lists.\n      if not current_stock_list:\n        return new_stock_list\n\n      stock_diff_list = current_stock_list[::] # deep copy ?\n\n      for new_stock in new_stock_list:\n        matching_diff = None\n        for diff in stock_diff_list:\n          for prop in [k for k in diff.keys() if k not in (\'quantity\',\n                          \'total_price\', \'id\', \'uid\', \'relative_url\')]:\n            if diff[prop] != new_stock.get(prop):\n              break\n          else:\n            matching_diff = diff\n\n        # matching_diff are negated later\n        if matching_diff:\n          matching_diff[\'quantity\'] = round(\n            matching_diff[\'quantity\'] - new_stock[\'quantity\'],\n            precision)\n          # Matching_diff and new_stock must be consistent.\n          # both with total price or none.\n          if matching_diff[\'total_price\'] and new_stock[\'total_price\']:\n            matching_diff[\'total_price\'] -= new_stock[\'total_price\']\n        else:\n          stock_diff_list.append(new_stock)\n\n\n      # we were doing with reversed calculation, so negate deltas again.\n      # Also we remove stocks that have 0 quantity and price.\n      return [negateStock(s) for s in stock_diff_list]\n\n    def negateStock(stock):\n      negated_stock = stock.copy()\n      negated_stock[\'quantity\'] = -stock[\'quantity\']\n      if stock[\'total_price\']:\n        negated_stock[\'total_price\'] = -stock[\'total_price\']\n      return negated_stock\n\n    delta_list = []\n    for current_stock_key, current_stock_value_list in \\\n                            current_stock_dict.items():\n      if current_stock_key in new_stock_dict:\n        delta_list.extend(computeStockDifference(\n                              current_stock_value_list,\n                              new_stock_dict[current_stock_key]))\n      else:\n        delta_list.extend(\n            [negateStock(s) for s in current_stock_value_list])\n\n    # now add every thing in new stock which was not in current stock\n    for new_stock_key, new_stock_value_list in \\\n                                new_stock_dict.items():\n      if new_stock_key not in current_stock_dict:\n        delta_list.extend(new_stock_value_list)\n\n    return delta_list\n\n\n  def _getTempObjectFactory(self):\n    \"\"\"Returns the factory method that will create temp object.\n\n    This method must return a function that accepts properties keywords\n    arguments and returns a temp object edited with those properties.\n    \"\"\"\n    # When have to reindex temp objects with quantity 0 in\n    # order to update stock if delta become 0, but but redefining\n    # isMovement we do not insert 0 lines in stock\n    def isMovement(self):\n      return self.getProperty(\'total_price\', 0) != 0 or \\\n             self.getProperty(\'quantity\', 0) != 0\n    def factory(*args, **kw):\n      doc = self.newContent(temp_object=True,\n                            portal_type=\'Accounting Transaction Line\',\n                            id=kw.pop(\'id\', self.getId()),\n                            uid=self.getUid())\n      doc.portal_type = \'Balance Transaction Line\'\n      relative_url = kw.pop(\'relative_url\', None)\n      destination_total_asset_price = kw.pop(\'total_price\', None)\n      if destination_total_asset_price is not None:\n        kw[\'destination_total_asset_price\'] = destination_total_asset_price\n      doc._edit(*args, **kw)\n      doc.isMovement = types.MethodType(isMovement, doc)\n\n      if relative_url:\n\n        def URLGetter(url):\n          def getRelativeUrl():\n            return url\n          return getRelativeUrl\n        doc.getRelativeUrl = URLGetter(relative_url)\n\n        def PathGetter(path):\n          def getPath():\n            return path\n          return getPath\n        doc.getPath = PathGetter(relative_url)\n\n      return doc\n\n    return factory\n\n  def _immediateReindexObject(self, *args, **kw):\n    \"\"\"Reindexes the object.\n    This is different indexing that the default Inventory indexing, because\n    we want to take into account that lines in this balance transaction to\n    represent the balance of an account (node) with different parameters,\n    based on the account_type of those accounts:\n      - on standards accounts: it\'s simply the balance for node, section\n       (and maybe resource, like all of thoses)\n      - on payable / receivable accounts: for node, section and mirror\n        section\n      - on bank accounts: for node, section and payment\n\n    Also this uses total_price (and quantity), and ignores variations and\n    subvariations as it does not exist in accounting.\n    \"\"\"\n    sql_catalog_id = kw.pop(\"sql_catalog_id\", None)\n    disable_archive = kw.pop(\"disable_archive\", 0)\n    immediate_reindex_archive = sql_catalog_id is not None\n\n    if self.getSimulationState() in self.getPortalDraftOrderStateList() + (\n                                            \'deleted\',):\n      # this prevent from trying to calculate stock\n      # with not all properties defined and thus making\n      # request with no condition in mysql\n      self.portal_catalog.catalogObjectList(\n                    [self],\n                    sql_catalog_id = sql_catalog_id,\n                    disable_archive=disable_archive,\n                    immediate_reindex_archive=immediate_reindex_archive)\n      return\n\n    current_stock_dict = self._getCurrentStockDict()\n    new_stock_dict = self._getNewStockDict()\n    diff_list = self._computeStockDifferenceList(\n                                    current_stock_dict,\n                                    new_stock_dict)\n    temp_object_factory = self._getTempObjectFactory()\n    stock_object_list = []\n    add_obj = stock_object_list.append\n    for diff in diff_list:\n      add_obj(temp_object_factory(**diff))\n\n    # Catalog this transaction as a standard document\n    self.portal_catalog.catalogObjectList([self])\n\n    # Catalog differences calculated from lines\n    if stock_object_list:\n      self.portal_catalog.catalogObjectList(stock_object_list[::],\n           method_id_list=(\'z_catalog_stock_list\',),\n           disable_cache=1, check_uid=0,\n           sql_catalog_id=sql_catalog_id,\n           disable_archive=disable_archive,\n           immediate_reindex_archive=immediate_reindex_archive)'),(3465,'document.erp5.AccountingTransactionRootSimulationRule AccountingTransactionRootSimulationRule ##############################################################################\n#\n# Copyright (c) 2010 Nexedi SARL and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\n\nfrom erp5.component.mixin.RuleMixin import RuleMixin\nfrom erp5.component.mixin.MovementCollectionUpdaterMixin import MovementCollectionUpdaterMixin\nclass AccountingTransactionRootSimulationRule(RuleMixin, MovementCollectionUpdaterMixin):\n  \"\"\"\n  Accounting Transaction Root Simulation Rule is a root level rule for\n  Accounting Transaction.\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Accounting Transaction Root Simulation Rule\'\n  portal_type = \'Accounting Transaction Root Simulation Rule\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  def _getMovementGenerator(self, context):\n    \"\"\"\n    Return the movement generator to use in the expand process\n    \"\"\"\n    return AccountingTransactionRuleMovementGenerator(applied_rule=context,\n                                                      rule=self)\n\n  ## XXX: From here on, copy/paste from DeliveryRootSimulationRule to avoid a\n  ##      dependency on erp5_trade. Is this Rule really actually used/useful?\n  #\n  # Default Properties\n  property_sheets = (\n    PropertySheet.Base,\n    PropertySheet.XMLObject,\n    PropertySheet.CategoryCore,\n    PropertySheet.DublinCore,\n    PropertySheet.Task,\n    PropertySheet.Predicate,\n    PropertySheet.Reference,\n    PropertySheet.Version,\n    PropertySheet.Rule\n    )\n  def _isProfitAndLossMovement(self, movement):\n    # For a kind of trade rule, a profit and loss movement lacks source\n    # or destination.\n    return (movement.getSource() is None or movement.getDestination() is None)\n\nfrom erp5.component.mixin.MovementGeneratorMixin import MovementGeneratorMixin\nclass AccountingTransactionRuleMovementGenerator(MovementGeneratorMixin):\n\n  def _getPortalDeliveryMovementTypeList(self):\n    return self._rule.getPortalObject().getPortalAccountingMovementTypeList()\n\n  def _getInputMovementList(self, movement_list=None, rounding=None):\n    \"\"\"\n    Input movement list comes from delivery\n\n    XXX: Copy/paste from DeliveryRootSimulationRule to avoid a dependency on\n         erp5_trade. Is this Rule really actually used/useful?\n    \"\"\"\n    delivery = self._applied_rule.getDefaultCausalityValue()\n    if delivery is None:\n      return []\n    else:\n      result = []\n      movement_kw = {}\n      movement_type_list = self._getPortalDeliveryMovementTypeList()\n      if movement_type_list:\n        movement_kw[\"portal_type\"] = movement_type_list\n      for movement in delivery.getMovementList(**movement_kw):\n        simulation_movement_list = movement.getDeliveryRelatedValueList()\n        if not simulation_movement_list or self._applied_rule in (\n            simulation_movement.getParentValue()\n            for simulation_movement in simulation_movement_list):\n          result.append(movement)\n      return result'),(3466,'document.erp5.AccountingTransactionLine AccountingTransactionLine ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.DeliveryLine import DeliveryLine\nfrom erp5.component.document.Amount import Amount\n\n\nclass AccountingTransactionLine(DeliveryLine):\n  \"\"\"\n  Accounting Transaction Lines allow to move some quantity of money from\n  a source to a destination\n  \"\"\"\n\n  meta_type = \'ERP5 Accounting Transaction Line\'\n  portal_type = \'Accounting Transaction Line\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.SimpleItem\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.Amount\n                    , PropertySheet.Task\n                    , PropertySheet.Arrow\n                    , PropertySheet.Price\n                    , PropertySheet.PaymentCondition\n                    )\n\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getInventoriatedQuantity\')\n  def getInventoriatedQuantity(self):\n    \"\"\"\n      Redefine this method here, because AccountingTransactionLine does\n      not have target values.\n    \"\"\"\n    return Amount.getInventoriatedQuantity(self)\n\n  # Pricing in standard currency\n  security.declareProtected(Permissions.AccessContentsInformation, \'getPrice\')\n  def getPrice(self, context=None): # pylint: disable=arguments-differ\n    \"\"\"\n      On accounting transaction lines, the price is always set to 1.\n      We use the `quantity` property for the default quantity, and the\n      converted value for source in getSourceInventoriatedTotalAssetPrice\n      and getDestinationInventoriatedTotalAssetPrice for destination.\n    \"\"\"\n    return 1.0\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getSourceAssetPrice\')\n  def getSourceAssetPrice(self):\n    \"\"\"\n      The price is set to 1.0 because we do not want to implement\n      automatic currency conversion in accounting. Users must define the\n      conversion manually in accounting. One can not account USD (in a EUR\n      based company) without defining the equivalent in EUR.\n    \"\"\"\n    return 1.0\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getDestinationAssetPrice\')\n  def getDestinationAssetPrice(self):\n    \"\"\"\n      The price is set to 1.0 because we do not want to implement\n      automatic currency conversion in accounting. Users must define the\n      conversion manually in accounting. One can not account USD (in a EUR\n      based company) without defining the equivalent in EUR.\n    \"\"\"\n    return 1.0\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'setGroupingReference\')\n  def setGroupingReference(self, value):\n    # Sets the grouping reference.\n    # This method is redefined here to override security definition.\n    # In the case of an accounting transaction line, we want to be able to\n    # set a grouping reference on a line after the point where we remove the\n    # Modify portal content permission, as long as this method cannot be called\n    # directly from the URL, that\'s why this method is without docstring.\n    self._baseSetGroupingReference(value)\n    self.reindexObject()\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'setGroupingDate\')\n  def setGroupingDate(self, value):\n    # Sets the grouping date.\n    # See also setGroupingReference.\n    self._baseSetGroupingDate(value)\n    self.reindexObject()\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'isMovingItem\')\n  def isMovingItem(self, item):\n    \"\"\"\n      We often like to aggregate items to Accounting Transaction Line\n      for traceability, but this movements does not physically move the item\n      to the destination of this account.\n    \"\"\"\n    return False'),(3467,'document.erp5.AccountingTransactionBalanceConstraint AccountingTransactionBalanceConstraint ##############################################################################\n#\n# Copyright (c) 2007-2010 Nexedi SA and Contributors. All Rights Reserved.\n#                         Jerome Perrin <jerome@nexedi.com>\n#                         Arnaud Fontaine <arnaud.fontaine@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport collections\n\nfrom Products.ERP5Type.mixin.constraint import ConstraintMixin\nfrom Products.ERP5Type import PropertySheet\n\nclass AccountingTransactionBalanceConstraint(ConstraintMixin):\n  \"\"\"\n  Check that accounting transaction total debit and total credit are equal.\n\n  This is only relevant for ZODB Property Sheets (filesystem Property\n  Sheets rely on Products.ERP5.Constraint.AccountingTransactionBalance\n  instead).\n  \"\"\"\n  meta_type = \'ERP5 Accounting Transaction Balance Constraint\'\n  portal_type = \'Accounting Transaction Balance Constraint\'\n\n  property_sheets = ConstraintMixin.property_sheets + \\\n                    (PropertySheet.AccountingTransactionBalanceConstraint,)\n\n  def _checkConsistency(self, obj, fixit=0):\n    \"\"\"\n    Check the object\'s consistency\n    \"\"\"\n    error_list = []\n    source_sum = collections.defaultdict(list)\n    destination_sum = collections.defaultdict(list)\n    for line in obj.getMovementList(\n          portal_type=obj.getPortalAccountingMovementTypeList()):\n      if line.getSourceValue(portal_type=\'Account\') is not None:\n        section = line.getSourceSectionValue()\n        source_sum[section].append(line.getSourceInventoriatedTotalAssetPrice() or 0)\n      if line.getDestinationValue(portal_type=\'Account\') is not None:\n        section = line.getDestinationSectionValue()\n        destination_sum[section].append(line.getDestinationInventoriatedTotalAssetPrice() or 0)\n\n    for section, amount_list in source_sum.items():\n      precision = 2\n      if amount_list and section is not None and\\\n          section.getPortalType() == \'Organisation\':\n        section_currency = section.getPriceCurrencyValue()\n        if section_currency is not None:\n          precision = section_currency.getQuantityPrecision()\n        if round(sum((round(amount, precision) for amount in amount_list)), precision) != 0:\n          error_list.append(self._generateError(obj, self._getMessage(\n                \'message_transaction_not_balanced_for_source\'),\n                mapping=dict(section_title=section.getTranslatedTitle())))\n          break\n\n    for section, amount_list in destination_sum.items():\n      precision = 2\n      if amount_list and section is not None and\\\n          section.getPortalType() == \'Organisation\':\n        section_currency = section.getPriceCurrencyValue()\n        if section_currency is not None:\n          precision = section_currency.getQuantityPrecision()\n        if round(sum((round(amount, precision) for amount in amount_list)), precision) != 0:\n          error_list.append(self._generateError(obj, self._getMessage(\n                \'message_transaction_not_balanced_for_destination\'),\n                mapping=dict(section_title=section.getTranslatedTitle())))\n          break\n\n    return error_list\n\n  _message_id_tuple = (\'message_transaction_not_balanced_for_source\',\n                       \'message_transaction_not_balanced_for_destination\')'),(3468,'document.erp5.AccountingTransaction AccountingTransaction ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\n\nfrom erp5.component.document.Delivery import Delivery\n\nclass AccountingTransaction(Delivery):\n  \"\"\"\n    A Transaction object allows to add\n    elementary accounting transactions in the general ledger\n  \"\"\"\n  # CMF Type Definition\n  meta_type = \'ERP5 Accounting Transaction\'\n  portal_type = \'Accounting Transaction\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task\n                    , PropertySheet.Arrow\n                    , PropertySheet.Movement\n                    , PropertySheet.Delivery\n                    , PropertySheet.Order\n                    , PropertySheet.Reference\n                    , PropertySheet.Comment\n                    , PropertySheet.PaymentCondition\n                    )\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'hasSourceSectionAccounting\')\n  def hasSourceSectionAccounting(self):\n    \"\"\"Return true if we should take into account accounting for source\n    section.\n    \"\"\"\n    section = self.getSourceSectionValue()\n    if section is not None:\n      return section.getPortalType() != \'Person\'\n    return False\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'hasDestinationSectionAccounting\')\n  def hasDestinationSectionAccounting(self):\n    \"\"\"Return true if we should take into account accounting for destination\n    section.\n    \"\"\"\n    section = self.getDestinationSectionValue()\n    if section is not None:\n      return section.getPortalType() != \'Person\'\n    return False\n\n# Compatibility\n# It may be necessary to create an alias after removing the Transaction class\n# Products.ERP5Type.Document.Transaction = AccountingTransaction'),(3469,'document.erp5.AccountTypeConstraint AccountTypeConstraint ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#          Jerome Perrin <jerome@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom Products.ERP5Type.mixin.constraint import ConstraintMixin\nfrom Products.ERP5Type import PropertySheet\ntranslateString = lambda msg: msg  # just to extract messages\n_MARKER = []\n\nclass AccountTypeConstraint(ConstraintMixin):\n  \"\"\"Account type constraint is a base class to check that account_type\n  category is consistent with the gap category.\n  This is an abstract class, subclasses have to define a mapping as a class\n  attribute, like this one:\n\n  _account_type_map = (\n    (\'gap/fr/pcg/4/40\', (\'liability/payable\',),\n    (\'gap/fr/pcg/4\', (\'asset/receivable\', \'liability/payable\'),\n  )\n\n  In this example, the constraint will check that if \'gap/fr/pcg/4\' is used, we\n  must be member of \'account_type/asset/receivable\' or\n  \'account_type/liability/payable\'.\n  The order is important, ie. that if the account is member of\n  \'gap/fr/pcg/4/40\', it must be member of \'account_type/liability/payable\'.\n\n  This constraints supports fixing consistency.\n  \"\"\"\n\n  property_sheets = ConstraintMixin.property_sheets + \\\n                    (PropertySheet.AccountTypeConstraint,)\n\n  def _checkConsistency(self, obj, fixit=0):\n    \"\"\"Implement here the consistency checker\n    \"\"\"\n    # self, the constraint is a temp object without acquisition wrappers, for\n    # now we need to add acquisition wrappers for category accessors\n    self_in_context = self.__of__(obj.getPortalObject())\n    error_list = []\n    errors = []\n    if getattr(obj, \'getAccountType\', _MARKER) is _MARKER:\n      errors.append(self._generateError(\n        obj,\n        translateString(\"Account does not have account_type category\")))\n    else:\n      constraint_line_list = self_in_context.objectValues(sort_on=\'int_index\')\n      if len(constraint_line_list) == 0:\n        raise NotImplementedError(\n           \"AccountTypeConstraint does not define an account type mapping lines\")\n      for constraint_line in constraint_line_list:\n        gap = constraint_line.getGap(base=1)\n        account_type_list = constraint_line.getAccountTypeList()\n        if obj.isMemberOf(gap):\n          if obj.getAccountType() not in account_type_list:\n            error_list.append(self._generateError(obj,\n                self._getMessage(\'message_inconsistent_account_type\'),\n                # XXX we should probably print translated logical path of\n                # categories instead of category path.\n                    mapping=dict(category=gap,\n                                 account_type_list=\n                                    \', \'.join(account_type_list))))\n            if fixit:\n              obj.setAccountType(account_type_list[0])\n          break\n    return error_list\n\n  _message_id_tuple = (\'message_inconsistent_account_type\',)'),(3470,'document.erp5.Account Account ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5.Document.Node import Node\n\n\nclass Account(Node):\n  \"\"\"An account is an abstract node which holds currencies and is used in\n  accounting.\n\n  Accounts are member of categories that are used to do aggregated reporting\n  of accounting movements. Typically, the following categories are used::\n    * GAP: This category represents the classification as defined by the\n      legislations that the organisatation have to comply to. Accounts can be\n      associated to multiple GAP category trees at the same time, and\n      therefore it allows to generate reports for multiple legislations from\n      the same accounting data.\n    * Financial Section: This category is the representation of the financial\n      structure as seen by the company, regardless of the fiscal\n      requirements.  Balance Sheets and Profit & Loss reports can be\n      generated using those categories.\n    * Account Type: This category is used to describe what is the type of\n      this account, and usually has impact on the behaviour of the\n      application and reportings. For instance, when using a \"payable\"\n      account in an accounting transaction, we set the supplier organisation\n      as mirror section, and reports such as trial balance can display a\n      breakdown of this account for each supplier.\n  \"\"\"\n  meta_type = \'ERP5 Account\'\n  portal_type = \'Account\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Account\n                    , PropertySheet.Arrow\n                    , PropertySheet.Reference\n                    )'),(3485,'Post Transaction Action This action will post the transaction to the General Ledger. It can be journalised again thanks to the restart action'),(3486,'Post Transaction This action will post the transaction to the General Ledger. It can be journalised again thanks to the restart action'),(3487,'Journalise Transaction Action Marks the transaction that has been recorded in a journal as debit and credit'),(3489,'Journalise Transaction Marks the transaction that has been recorded in a journal as debit and credit'),(3490,'Restart Transaction Action Restarts a document that would have been closed previously, in order to modify it, such as an accounting period'),(3492,'Restart Transaction Restarts a document that would have been closed previously, in order to modify it, such as an accounting period'),(3493,'Plan Transaction Action Plan will set the document State as planned in ERP5'),(3494,'Plan Transaction A planned transaction is planned to be processed. The further step will be to confirm the transaction.'),(3495,'Definitively Close Transaction Action Mark transaction that belongs to \"closed\" accounting periods'),(3496,'Definitively Close Transaction Mark transaction that belongs to \"closed\" accounting periods: the transaction has been fully processed.'),(3497,'Delete Transaction Action mark the transaction as deleted, it will no longer be visible'),(3498,'Delete'),(3499,'Confirm Transaction Action validate a planified transactions that have to be turned into real accounting transactions'),(3500,'Confirm Transaction validate a planned transaction that will be turned into real accounting transactions'),(3501,'Cancel Transaction Action cancel a transaction which has been done by mistake'),(3502,'Cancel Transaction Action Cancel the transaction, when it already have a meaning from accounting point of view'),(3503,'Cancel Transaction cancel a transaction which has been done by mistake'),(3504,'Auto Plan plan an order (automatically done by the system)'),(3505,'Posted to General Ledger Posted State is used for accounting transactions that have been properly posted to the ledger accounts and validated by an accountant.'),(3506,'Journalised Journalised State is use for accounting transaction that have been recorded in a journal as a debit and a credit.'),(3507,'Planned Planned State is used for accounting transactions that have some probability to be turned into real accounting transactions in the future.'),(3508,'Draft Draft is the initial workflow state for accounting transactions'),(3509,'Closed Closed State is used for accounting transactions that belong to \"closed\" accounting periods. Basically, the transaction has been completely processed.'),(3510,'Deleted Documents in this state were deleted by the user as a result of clicking on the trash button or calling the delete action'),(3511,'Confirmed Confirmed State is used for accounting transactions that have to be turned into real accounting transactions. This is generally the manager role to confirm a transaction, before it is processed by the accountant.'),(3512,'Cancelled Cancelled state is used for accounting transactions that have been created mistakenly or which should no longer be taken into account'),(3513,'Auto Planned'),(3520,'Internal Invoices Workflow This workflow defines the different steps of an internal invoice transaction internal_invoice_transaction_simulation_workflow'),(3534,'Post Transaction Action This action will post the transaction to the General Ledger. It can be journalised again thanks to the restart action'),(3535,'Post Transaction This action will post the transaction to the General Ledger. It can be journalised again thanks to the restart action'),(3536,'Journalise Transaction Action Marks the transaction that has been recorded in a journal as debit and credit'),(3537,'Journalise Transaction Marks the transaction that has been recorded in a journal as debit and credit'),(3538,'Restart Transaction Action Restarts a document that would have been closed previously, in order to modify it, such as an accounting period'),(3539,'Restart Transaction Restarts a document that would have been closed previously, in order to modify it, such as an accounting period'),(3540,'Plan Transaction Action Plan will set the document State as planned in ERP5'),(3541,'Plan Transaction A planned transaction is planned to be processed. The further step will be to confirm the transaction.'),(3542,'Definitively Close Transaction Action Mark transaction that belongs to \"closed\" accounting periods'),(3543,'Definitively Close Transaction Mark transaction that belongs to \"closed\" accounting periods: the transaction has been fully processed.'),(3544,'Delete Transaction Action mark the transaction as deleted, it will no longer be visible'),(3545,'Delete'),(3546,'Confirm Transaction Action validate a planified transactions that have to be turned into real accounting transactions'),(3547,'Confirm Transaction validate a planned transaction that will be turned into real accounting transactions'),(3548,'Cancel Transaction Action cancel a transaction which has been done by mistake'),(3549,'Cancel Transaction Action Cancel the transaction, when it already have a meaning from accounting point of view'),(3550,'Cancel Transaction cancel a transaction which has been done by mistake'),(3551,'Auto Plan plan an order (automatically done by the system)'),(3552,'Posted to General Ledger Posted State is used for accounting transactions that have been properly posted to the ledger accounts and validated by an accountant.'),(3553,'Journalised Journalised State is use for accounting transaction that have been recorded in a journal as a debit and a credit.'),(3554,'Planned Planned State is used for accounting transactions that have some probability to be turned into real accounting transactions in the future.'),(3555,'Draft Draft is the initial workflow state for accounting transactions'),(3556,'Closed Closed State is used for accounting transactions that belong to \"closed\" accounting periods. Basically, the transaction has been completely processed.'),(3557,'Deleted Documents in this state were deleted by the user as a result of clicking on the trash button or calling the delete action'),(3558,'Confirmed Confirmed State is used for accounting transactions that have to be turned into real accounting transactions. This is generally the manager role to confirm a transaction, before it is processed by the accountant.'),(3559,'Cancelled Cancelled state is used for accounting transactions that have been created mistakenly or which should no longer be taken into account'),(3560,'Auto Planned'),(3567,'Accounting Workflow This workflow defines the different steps of an accounting transaction accounting_workflow'),(3577,'Temporarily Stop Accounting Period Action The Accounting Period will be temporarily stopped, but can be restarted. In this state it is not possible to post transactions during this period until the period is restarted.'),(3578,'Temporarily Stop Accounting Period The Accounting Period will be temporarily stopped, but can be restarted. In this state it is not possible to post transactions during this period until the period is restarted.'),(3579,'Start Accounting Period Action Starts the accounting period in order to input transactions.'),(3580,'Start Accounting Period Starts the accounting period in order to input transactions.'),(3581,'Restart Accounting Period Action Restarts an accounting period that has been stopped, in order to input new transactions'),(3582,'Restart Accounting Period Restarts the accounting period in order to input transactions.\nThis removes existing balance transactions.'),(3584,'Stop Accounting Period Action Stop the accounting period, can\'t be restarted later, no more transaction can be input on this accounting period.'),(3585,'Stop Accounting Period Stop the accounting period, can\'t be restarted later, no more transaction can be input on this accounting period.'),(3586,'Delete Accounting Period Action Delete a document in ERP5'),(3587,'Delete Accounting Period Delete a document in ERP5'),(3588,'Cancel Accounting Period Action Cancel a document in ERP5'),(3589,'Cancel Accounting Period Cancel a document in ERP5'),(3590,'Temporarily Stopped The Accounting Period is temporarily stopped, but can be restarted. In this state it is not possible to post transactions during this period.'),(3591,'Started The Accounting Period is started. It is therefore possible to post accounting.'),(3592,'Draft Default state of the document'),(3593,'Stopped The Accounting Period is stopped. It is no longer possible to add accounting transactions in this period. A balance transaction has been created.'),(3594,'Deleted Documents in this state were deleted by the user as a result of clicking on the trash button or calling the delete action'),(3595,'Cancelled State of a document that has been cancelled'),(3600,'Accounting Period Workflow Defines the different steps of the accounting period and allows user to input transactions when it is open. accounting_period_workflow'),(3615,'Accounting Transaction Balance Constraint'),(3619,'Validate Workflow Action'),(3622,'Create Secondary Periods'),(3630,'Accounting Period'),(3644,'Account'),(3654,'Account Field Library'),(3675,'Account'),(3677,'Account'),(3698,'Account'),(3708,'Account'),(3724,'Account Type Constraint'),(3728,'Account Type Constraint Line'),(3751,'Trial Balance'),(3767,'Trial Balance'),(3770,'Search'),(3782,'Field Library for Accounting Reports'),(3795,'Profit and Loss'),(3810,'Other Parties'),(3823,'Other Parties'),(3827,'Summary'),(3848,'General Ledger'),(3865,'General Ledger'),(3880,'Field Library for Accounting Report Dialogs'),(3886,'Bank Accounts'),(3897,'Bank Accounts'),(3911,'Accounting Transaction'),(3915,'Create Reversal Transaction'),(3918,'Convert Price'),(3921,'Convert Price'),(3924,'Add Accounting Transaction Lines'),(3945,'Accounting Transaction'),(3995,'Summary Aged Balance'),(4012,'Search'),(4017,'Journal Section'),(4030,'Journal'),(4046,'Journal'),(4065,'Grouping Reference Fast Input'),(4077,'Detailed Aged Balance'),(4081,'Create Reversal Transactions'),(4085,'Create Related Payments'),(4098,'Aged Balance'),(4106,'AccountingTransactionModule_viewAgedBalanceReport Aged Balance'),(4116,'Accounting Transactions'),(4123,'Accounting Line Report'),(4127,'Accounting Line Report'),(4128,'AccountingTransactionModule_viewAccountingLineReportReport Accounting Line Report'),(4170,'Accounting Transaction Line'),(4191,'Accounting Transaction Line'),(4224,'Create Related Payment'),(4251,'Internal Invoice Transaction'),(4272,'Internal Invoice Transaction'),(4293,'Internal Invoice Transaction'),(4313,'Transactions'),(4328,'Transactions'),(4341,'Import CSV File'),(4346,'Cash Register'),(4353,'Accounting Report This form is used to contain fields that are useful to print accounting reports'),(4363,'Default Accounting Field Library'),(4381,'Transactions'),(4394,'Transactions'),(4417,'Balance Transaction'),(4420,'Payable and Receivable Accounts Grouped Check'),(4440,'Accounting Transaction'),(4473,'Accounting Transaction Field Library'),(4494,'Accounting Transaction'),(4565,'Accounting'),(4586,'Profile'),(4606,'Sale Invoice Transaction'),(4627,'Sale Invoice Transaction'),(4647,'Purchase Invoice Transaction'),(4666,'Profile'),(4687,'Purchase Invoice Transaction'),(4708,'Purchase Invoice Transaction'),(4722,'Accounting Preferences'),(4745,'Payment Transaction'),(4768,'Payment Transaction'),(4792,'Payment Transaction'),(4801,'Measure Cell'),(4802,'Measure'),(4803,'Internal Supply Module Folders allow to store a large number of documents (1,000,000 should not\r\nbe a problem).'),(4804,'Internal Supply Line A supply line.'),(4805,'Internal Supply Cell A supply cell.'),(4806,'Internal Supply A Supply defines precise pricing and shipping conditions between two trade parties for a limited selection of traded products, components, services, etc. It can be used to represent price catalogs, product referencing, pricing policy, etc.'),(4807,'Component Module Folders allow to store a large number of documents (1,000,000 should not\nbe a problem).'),(4808,'Component Individual Variation A Variation'),(4809,'Component A Component is a tangible good which can be traded (ex. a screw, a label, fabric). Components may define multiple variations. Trading information such as price, customer, reference, etc. may be defined on a Component, although it is recommended in complex environments to use Purchase Supplies for that purpose. In a production environment, Components are procured and Products are sold.'),(4810,'test.erp5.testResourceVariation testResourceVariation #############################################################################\n#\n# Copyright (c) 2007 Nexedi SA and Contributors. All Rights Reserved.\n#                    Daniel Feliubadalo  <daniel@sip2000.com>\n#                    Romain Courteaud  <romain@nexedi.com>\n#                    Alexandre Boeglin  <alex@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA 02111-1307, USA.\n#\n##############################################################################\n\n\"\"\"\nTests Resource Variations\n\"\"\"\nimport unittest\nfrom Testing import ZopeTestCase\nfrom zLOG import LOG\nfrom Products.ERP5Type.tests.ERP5TypeTestCase import ERP5TypeTestCase\nfrom Products.ERP5Type.tests.utils import reindex\n\nclass ResourceVariationTestCase(ERP5TypeTestCase):\n  \"\"\"Tests starts with a preference activated for self.my_organisation, logged in\n  as a user with Manager role.\n\n  All documents created appart from this configuration will be deleted in\n  teardown. So users of this test case are encouraged to create new documents\n  rather than modifying default documents.\n  \"\"\"\n  def logMessage(self, msg, tab=0): # pylint: disable=arguments-differ\n    \"\"\"\n    Log a message.\n    \"\"\"\n    if tab:\n      msg = \'  %s\' % msg\n    ZopeTestCase._print(\'\\n%s\' % msg)\n    LOG(\'testResource.play\', 0, msg)\n\n  def _doWorkflowAction(self, ob, action, **kw):\n    self.portal.portal_workflow.doActionFor(ob, action,\n                                            comment = \'for unit test\',**kw)\n\n  @reindex\n  def _makeOneResource(self, portal_type=\'Product\',\n                       validation_state=\'draft\', **kw):\n    \"\"\"\n    Creates an resource\n\n    The default settings is for self.section.\n    You can pass a list of mapping as lines, then lines will be created\n    using this information.\n    \"\"\"\n    rs = self.portal.getDefaultModule(portal_type).newContent(\n                              portal_type=portal_type,**kw)\n\n    if validation_state == \'validated\':\n      rs.validate()\n    return rs\n\n  @reindex\n  def _makeOneResourceIndividualVariation(self, resource, **kw):\n    \"\"\"\n    Creates a Individual variation sub object, and edit it with kw.\n    \"\"\"\n    iv = resource.newContent(portal_type=\'%s Individual Variation\' % \\\n                              resource.getPortalType(), **kw)\n    return iv\n\n  def afterSetUp(self):\n    \"\"\"\n    - create categories\n    - create preference\n    - make sure categories are included to portal types\n    \"\"\"\n    self.portal = self.getPortal()\n    self.portal_categories = self.portal.portal_categories\n    self.portal_preferences = self.portal.portal_preferences\n    self.product_module = self.portal.product_module\n    self.service_module = self.portal.service_module\n    self.component_module = self.portal.component_module\n\n    # create variation categories\n    category_type=(\'line\', \'variation\')\n    if not self.portal_categories.hasContent(\'required_size\'):\n      size = self.portal_categories.newContent(portal_type=\'Base Category\',\n                                title=\'Required Size\',\n                                reference=\'required_size\',\n                                id=\'required_size\',\n                                category_type=category_type)\n    else:\n      size = self.portal_categories[\'required_size\']\n\n    size.newContent(portal_type=\'Category\', title=\'Large\',\n                    reference=\'l\',id=\'l\')\n    size.newContent(portal_type=\'Category\', title=\'Medium\',\n                    reference=\'l\',id=\'m\')\n    size.newContent(portal_type=\'Category\', title=\'Small\',\n                    reference=\'l\',id=\'s\')\n    size.newContent(portal_type=\'Category\', title=\'XL\',\n                    reference=\'l\',id=\'xl\')\n    size.newContent(portal_type=\'Category\', title=\'XXL\',\n                    reference=\'l\',id=\'xxl\')\n\n    if not self.portal_categories.hasContent(\'option_colour\'):\n      colour = self.portal_categories.newContent(portal_type=\'Base Category\',\n                                title=\'Optional Colour\',\n                                reference=\'option_colour\',\n                                id=\'option_colour\',\n                                category_type=category_type)\n    else:\n      colour = self.portal_categories[\'option_colour\']\n\n    colour.newContent(portal_type=\'Category\', title=\'Blue\',\n                      reference=\'l\',id=\'blue\')\n    colour.newContent(portal_type=\'Category\', title=\'Green\',\n                      reference=\'l\',id=\'green\')\n    colour.newContent(portal_type=\'Category\', title=\'Red\',\n                      reference=\'l\',id=\'red\')\n\n    if not self.portal_categories.hasContent(\'individual_aspect\'):\n      aspect = self.portal_categories.newContent(portal_type=\'Base Category\',\n                                title=\'Individual Aspect\',\n                                reference=\'individual_aspect\',\n                                id=\'individual_aspect\',\n                                category_type=category_type)\n    else:\n      aspect = self.portal_categories[\'individual_aspect\']\n\n    aspect.newContent(portal_type=\'Category\', title=\'Aspect 1\',\n                      reference=\'A1\',id=\'a1\')\n    aspect.newContent(portal_type=\'Category\', title=\'Aspect 2\',\n                      reference=\'A2\',id=\'a2\')\n\n    #create resource variation preferences\n    preference = getattr(self.portal_preferences, \'test_site_preference\', None)\n    if preference is None:\n      preference = self.portal_preferences.newContent(portal_type=\'Preference\',\n                                title=\'Default Site Preference\',\n                                id=\'test_site_preference\')\n      preference.enable()\n\n    value=\'individual_aspect\'\n    preference.setPreferredProductIndividualVariationBaseCategory(value)\n    preference.setPreferredServiceIndividualVariationBaseCategory(value)\n    preference.setPreferredComponentIndividualVariationBaseCategory(value)\n\n    value=(\'required_size\',)\n    preference.setPreferredProductVariationBaseCategoryList(value)\n    preference.setPreferredServiceVariationBaseCategoryList(value)\n    preference.setPreferredComponentVariationBaseCategoryList(value)\n\n    value=(\'option_colour\',)\n    preference.setPreferredProductOptionalVariationBaseCategory(value)\n    preference.setPreferredServiceOptionalVariationBaseCategory(value)\n    preference.setPreferredComponentOptionalVariationBaseCategory(value)\n    self.preference = preference\n\n    # all this available to catalog\n\n    #adding to base categories of resources\n    #for use setRequiredSizeList and setOptionColourList methods\n    self.portal.portal_types[\'Product\']._setTypeBaseCategoryList([\n                                            \'required_size\',\n                                            \'option_colour\',\n                                            \'individual_aspect\'])\n    self.portal.portal_types[\'Service\']._setTypeBaseCategoryList([\n                                            \'required_size\',\n                                            \'option_colour\',\n                                            \'individual_aspect\'])\n    self.portal.portal_types[\'Component\']._setTypeBaseCategoryList([\n                                            \'required_size\',\n                                            \'option_colour\',\n                                            \'individual_aspect\'])\n    self.tic()\n\n  def beforeTearDown(self):\n    \"\"\"Remove all documents.\n    \"\"\"\n    self.abort()\n    for module in self.product_module, self.service_module, self.component_module:\n      object_ids = list(self.service_module.objectIds())\n      if object_ids:\n        module.manage_delObjects(object_ids)\n\n    self.portal_categories.manage_delObjects((\n      [\'required_size\', \'individual_aspect\',\'option_colour\']))\n\n    self.tic()\n\n  def getBusinessTemplateList(self):\n    \"\"\"Returns list of BT to be installed.\"\"\"\n    return (\'erp5_base\', \'erp5_pdm\')\n\n  def _testResourceDefaultConfig(self,resource):\n    \"\"\"\n    Check variation API when creating a default resource.\n    This should use what is defined in preferences.\n    \"\"\"\n    # XXX Check default config\n    self.assertSameSet([\'required_size\',\n                        \'option_colour\',\n                        \'individual_aspect\'],\n                        resource.getVariationBaseCategoryList())\n\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'individual_aspect/a1\',\n                        \'individual_aspect/a2\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\'],\n                        resource.getVariationRangeCategoryList())\n\n    self.assertSameSet([], resource.getVariationCategoryList())\n\n  def _testResourceWithoutVariation(self,resource):\n    \"\"\"\n    Check variation API when creating a resource and removing its variation\n    axes\n    \"\"\"\n    resource.edit(variation_base_category_list=[],\n                  optional_variation_base_category_list=[],\n                  individual_variation_base_category_list=[])\n\n    self.assertSameSet([], resource.getVariationBaseCategoryList())\n    self.assertSameSet([], resource.getVariationRangeCategoryList())\n    self.assertSameSet([], resource.getVariationCategoryList())\n\n    # XXX What happens when we create an individual variation\n    self._makeOneResourceIndividualVariation(\n              resource,\n              id=\'1\',\n              title=\'Circular\')\n\n    self.assertSameSet([], resource.getVariationBaseCategoryList())\n    self.assertSameSet([], resource.getVariationRangeCategoryList())\n    self.assertSameSet([], resource.getVariationCategoryList())\n\n  def _testResourceCategoryVariation(self,resource):\n    \"\"\"\n    Check variation API when defining only category as variation\n    axes\n    \"\"\"\n    # Define variations\n    resource.setRequiredSizeList([\'l\', \'m\',\'s\'])\n\n    resource.setOptionColourList([\'blue\'])\n\n    self.assertSameSet([\'required_size\',\'option_colour\',\'individual_aspect\'],\n                       resource.getVariationBaseCategoryList())\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'option_colour/blue\'],\n                       resource.getVariationCategoryList())\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/a1\',\n                        \'individual_aspect/a2\'],\n                        resource.getVariationRangeCategoryList())\n\n    # Now, define aspect categories, which should not be used as variation\n    resource.setIndividualAspectList([\'a1\'])\n\n    self.assertSameSet([\'required_size\',\'option_colour\',\'individual_aspect\'],\n                       resource.getVariationBaseCategoryList())\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'option_colour/blue\'],\n                       resource.getVariationCategoryList())\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/a1\',\n                        \'individual_aspect/a2\'],\n                       resource.getVariationRangeCategoryList())\n\n  def _testResourceIndividualVariation(self,resource):\n    \"\"\"\n    Check variation API when defining individual variation\n    \"\"\"\n    # Creating individual variations of resource\n    resource_iv1 = self._makeOneResourceIndividualVariation(resource,\n              id=\'1\',\n              title=\'Circular\',\n    )\n\n    resource_iv2 = self._makeOneResourceIndividualVariation(resource,\n              id=\'2\',\n              title=\'Triangular\',\n    )\n\n    resource_iv3 = self._makeOneResourceIndividualVariation(resource,\n              id=\'3\',\n              title=\'Square\',\n    )\n    # Check default parameter\n    self.assertSameSet([],\n                       resource.getVariationCategoryList())\n    self.assertSameSet([\'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                        resource.getVariationCategoryList(\n                                omit_individual_variation=0))\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                        resource.getVariationRangeCategoryList())\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                        resource.getVariationRangeCategoryList(\n                                omit_individual_variation=0))\n\n    # Now, define aspect categories, which should not be used as variation\n    resource.setIndividualAspectList([\'a1\'])\n\n    # Check default parameter\n    self.assertSameSet([],\n                       resource.getVariationCategoryList())\n    self.assertSameSet([\'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                       resource.getVariationCategoryList(\n                                omit_individual_variation=0))\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                       resource.getVariationRangeCategoryList())\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                       resource.getVariationRangeCategoryList(\n                                omit_individual_variation=0))\n\n  def _testResourceVariation(self,resource):\n    \"\"\"\n    Combine individual and category variations\n    \"\"\"\n    resource.setRequiredSizeList([\'l\', \'m\', \'s\'])\n\n    resource.setOptionColourList([\'blue\'])\n\n    # creating individual variations of resource\n    resource_iv1=self._makeOneResourceIndividualVariation(resource,\n              id=\'1\',\n              title=\'Circular\',\n    )\n\n    resource_iv2=self._makeOneResourceIndividualVariation(resource,\n              id=\'2\',\n              title=\'Triangular\',\n    )\n\n    resource_iv3=self._makeOneResourceIndividualVariation(resource,\n              id=\'3\',\n              title=\'Square\',\n    )\n\n    self.assertSameSet([\'option_colour\',],\n                             resource.getOptionalVariationBaseCategoryList())\n\n    self.assertSameSet([\'individual_aspect\',],\n                             resource.getIndividualVariationBaseCategoryList())\n\n    # Check default parameters\n    self.assertSameSet([\'required_size\',\'option_colour\',\'individual_aspect\'],\n                             resource.getVariationBaseCategoryList())\n\n    self.assertSameSet([\'required_size\',\'option_colour\',\'individual_aspect\'],\n                             resource.getVariationBaseCategoryList(\n                                         omit_individual_variation=0,\n                                         omit_optional_variation=0))\n\n    self.assertSameSet([\'required_size\',\'option_colour\'],\n                             resource.getVariationBaseCategoryList(\n                                         omit_individual_variation=1,\n                                         omit_optional_variation=0))\n\n    self.assertSameSet([\'required_size\',],\n                             resource.getVariationBaseCategoryList(\n                                         omit_individual_variation=1,\n                                         omit_optional_variation=1))\n\n    # Check default parameters\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'option_colour/blue\'],\n                             resource.getVariationCategoryList())\n\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'option_colour/blue\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                             resource.getVariationCategoryList(\n                                         omit_individual_variation=0))\n\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'option_colour/blue\'],\n                             resource.getVariationCategoryList(\n                                         omit_individual_variation=1))\n\n    # Check default parameters\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                             resource.getVariationRangeCategoryList())\n\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\',\n                        \'individual_aspect/\'+resource_iv1.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv2.getRelativeUrl(),\n                        \'individual_aspect/\'+resource_iv3.getRelativeUrl()],\n                             resource.getVariationRangeCategoryList(\n                                         omit_individual_variation=0))\n\n    self.assertSameSet([\'required_size/l\',\n                        \'required_size/m\',\n                        \'required_size/s\',\n                        \'required_size/xl\',\n                        \'required_size/xxl\',\n                        \'option_colour/blue\',\n                        \'option_colour/green\',\n                        \'option_colour/red\'],\n                            resource.getVariationRangeCategoryList(\n                                         omit_individual_variation=1))\n\nclass TestResourceVariation(ResourceVariationTestCase):\n  \"\"\"\n  Test Resource Variation\n\n  Test basic cases of gathering data to render forms, the purpose of those\n  tests is to exercise basic variation results.\n  \"\"\"\n  def getTitle(self):\n    return \"Resource Variations\"\n\n  def testResourceDefaultConfig(self):\n    \"\"\"\n    Check variation API when creating a default resource.\n    This should use what is defined in preferences.\n    \"\"\"\n    self.logMessage(\'testResourceDefaultConfig\')\n    # Create Product\n    product = self._makeOneResource(\n              id=\'1\',\n              portal_type=\'Product\',\n              title=\'Product One\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceDefaultConfig(product)\n    # Create Service\n    service = self._makeOneResource(\n              id=\'1\',\n              portal_type=\'Service\',\n              title=\'Service One\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceDefaultConfig(service)\n    # Create Component\n    component = self._makeOneResource(\n              id=\'1\',\n              portal_type=\'Component\',\n              title=\'Component One\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceDefaultConfig(component)\n\n  def testResourceWithoutVariation(self):\n    \"\"\"\n    Check variation API when creating a resource and removing its variation\n    axes\n    \"\"\"\n    self.logMessage(\'testResourceWithoutVariation\')\n    # Create Product\n    product = self._makeOneResource(\n              id=\'2\',\n              portal_type=\'Product\',\n              title=\'Product Two\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceWithoutVariation(product)\n    # Create Service\n    service = self._makeOneResource(\n              id=\'2\',\n              portal_type=\'Service\',\n              title=\'Service Two\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceWithoutVariation(service)\n    # Create Component\n    component = self._makeOneResource(\n              id=\'2\',\n              portal_type=\'Component\',\n              title=\'Component Two\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceWithoutVariation(component)\n\n  def testResourceCategoryVariation(self):\n    \"\"\"\n    Check variation API when defining only category as variation\n    axes\n    \"\"\"\n    self.logMessage(\'testResourceCategoryVariation\')\n    # Create Product\n    product = self._makeOneResource(\n              id=\'3\',\n              portal_type=\'Product\',\n              title=\'Product Three\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceCategoryVariation(product)\n    # Create Service\n    service = self._makeOneResource(\n              id=\'3\',\n              portal_type=\'Service\',\n              title=\'Service Three\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceCategoryVariation(service)\n    # Create Component\n    component = self._makeOneResource(\n              id=\'3\',\n              portal_type=\'Component\',\n              title=\'Component Three\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceCategoryVariation(component)\n\n  def testResourceIndividualVariation(self):\n    \"\"\"\n    Check variation API when defining individual variation\n    \"\"\"\n    self.logMessage(\'testResourceIndividualVariation\')\n    # Create Product\n    product = self._makeOneResource(\n              id=\'4\',\n              portal_type=\'Product\',\n              title=\'Product Four\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceIndividualVariation(product)\n    # Create Service\n    service = self._makeOneResource(\n              id=\'4\',\n              portal_type=\'Service\',\n              title=\'Service Four\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceIndividualVariation(service)\n    # Create Component\n    component = self._makeOneResource(\n              id=\'4\',\n              portal_type=\'Component\',\n              title=\'Component Four\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceIndividualVariation(component)\n\n  def testResourceVariation(self):\n    \"\"\"\n    Combine individual and category variations\n    \"\"\"\n    # Resource Variation test.\n    self.logMessage(\'testResourceVariation\')\n    # Create Product\n    product = self._makeOneResource(\n              id=\'5\',\n              portal_type=\'Product\',\n              title=\'Product Five\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceVariation(product)\n    # Create Service\n    service = self._makeOneResource(\n              id=\'5\',\n              portal_type=\'Service\',\n              title=\'Service Five\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceVariation(service)\n    # Create Component\n    component = self._makeOneResource(\n              id=\'5\',\n              portal_type=\'Component\',\n              title=\'Component Five\',\n              validation_state=\'validated\',\n              variation_base_category=\'required_size\',\n              optional_variation_base_category=\'option_colour\',\n              individual_variation_base_category=\'individual_aspect\')\n    self._testResourceVariation(component)\n\n  def testResourceGetVariationBaseCategoryValueAfterChangePreference(self):\n    # Resource Variation test.\n    self.logMessage(\'testResourceGetVariationBaseCategoryValueAfterChangePreference\')\n    product = self._makeOneResource(\n              id=\'6\',\n              portal_type=\'Product\',\n              title=\'Product Six\',\n              validation_state=\'validated\')\n    self.tic()\n    self.assertEqual([(\'Individual Aspect\', \'individual_aspect\')], product.Resource_getIndividualVariationBaseCategoryItemList())\n    self.assertEqual([(\'Optional Colour\', \'option_colour\')], product.Resource_getOptionalVariationBaseCategoryItemList())\n    self.assertEqual([(\'Required Size\', \'required_size\')], product.Resource_getVariationBaseCategoryItemList())\n    self.preference.setPreferredProductIndividualVariationBaseCategoryList([])\n    self.preference.setPreferredProductVariationBaseCategoryList([])\n    self.preference.setPreferredProductOptionalVariationBaseCategoryList([])\n    self.tic()\n    self.assertEqual([], product.Resource_getIndividualVariationBaseCategoryItemList())\n    self.assertEqual([], product.Resource_getOptionalVariationBaseCategoryItemList())\n    self.assertEqual([], product.Resource_getVariationBaseCategoryItemList())\n\ndef test_suite():\n  suite = unittest.TestSuite()\n  suite.addTest(unittest.makeSuite(TestResourceVariation))\n  return suite'),(4811,'test.erp5.testPDM testPDM # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2009 Nexedi KK, Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\nimport unittest\nfrom Products.ERP5Type.tests.ERP5TypeTestCase import ERP5TypeTestCase\nfrom Products.CMFCore.exceptions import AccessControl_Unauthorized\n\n\nclass TestPDMWithSecurity(ERP5TypeTestCase):\n  \"\"\"\n  Test PDM with Security\n  \"\"\"\n\n  def getTitle(self):\n    return \'Test PDM with Security\'\n\n  def getBusinessTemplateList(self):\n\n    return (\'erp5_base\',\n            \'erp5_pdm\',\n            )\n\n  def afterSetUp(self):\n    if getattr(self.portal, \'_run_after_setup\', None) is not None:\n      return\n\n\n    self.portal._run_after_setup = True\n\n    user_folder = self.getPortal().acl_users\n    user_folder._doAddUser(\'author\', \'\', [\'Auditor\', \'Author\'], [])\n    user_folder._doAddUser(\'assignor\', \'\', [\'Auditor\', \'Author\', \'Assignor\'], [])\n    user_folder._doAddUser(\'assignee\', \'\', [\'Auditor\', \'Author\', \'Assignee\'], [])\n\n    self.tic()\n\n  def testValidatedProductCanContainMeasure(self):\n    \"\"\"\n    Make sure that validated product can contain measure.\n    \"\"\"\n    self.loginByUserName(\'author\')\n    product = self.portal.product_module.newContent(portal_type=\'Product\',\n                                                    title=\'Chair\')\n\n    self.tic()\n\n    # Author try to add a measure to validated product and succeed.\n    product.newContent(portal_type=\'Measure\')\n\n    self.tic()\n\n    self.assertEqual(len(product.contentValues(portal_type=\'Measure\')), 1)\n\n    self.loginByUserName(\'assignor\')\n    self.portal.portal_workflow.doActionFor(product, \'validate_action\')\n\n    self.tic()\n\n    self.assertEqual(product.getValidationState(), \'validated\')\n\n    # Change to author and try to add a measure to validated product and fail.\n    self.loginByUserName(\'author\')\n    self.assertRaises(AccessControl_Unauthorized,\n                      product.newContent, portal_type=\'Measure\')\n\n    # Change to assignee and try to add a measure to validated product and succeed.\n    self.loginByUserName(\'assignee\')\n    product.newContent(portal_type=\'Measure\')\n\n    self.tic()\n\n    self.assertEqual(len(product.contentValues(portal_type=\'Measure\')),\n                     2)\n\n\nclass TestResourceMeasureConstraint(ERP5TypeTestCase):\n  def afterSetUp(self):\n    quantity_unit = self.portal.portal_categories.quantity_unit\n    if \'unit\' not in quantity_unit.contentIds():\n      quantity_unit.newContent(portal_type=\'Category\', id=\'unit\')\n    if \'piece\' not in quantity_unit.unit.contentIds():\n      quantity_unit.unit.newContent(portal_type=\'Category\', id=\'piece\')\n    self.tic()\n\n    quantity_unit_conversion_module = self.portal.quantity_unit_conversion_module\n    if \'unit\' not in quantity_unit_conversion_module.contentIds():\n      unit_group = quantity_unit_conversion_module.newContent(\n          id=\'unit\',\n          portal_type=\'Quantity Unit Conversion Group\',\n          quantity_unit_value=quantity_unit.unit.piece)\n      unit_group.newContent(\n          portal_type=\'Quantity Unit Conversion Definition\',\n          quantity_unit_value=quantity_unit.unit.piece,\n          quantity=1).validate()\n      unit_group.validate()\n    self.tic()\n\n    metric_type = self.portal.portal_categories.metric_type\n    if \'unit\' not in metric_type.contentIds():\n      metric_type.newContent(portal_type=\'Category\', id=\'unit\')\n    if \'a\' not in metric_type.unit.contentIds():\n      metric_type.unit.newContent(portal_type=\'Category\', id=\'a\')\n\n    self.constraint = self.portal.portal_trash.newContent(\n      portal_type=\'Resource Measures Consistency Constraint\',\n      temp_object=True\n    )\n    self.resource = self.portal.product_module.newContent(\n      portal_type=\'Product\',\n      quantity_unit_value=quantity_unit.unit.piece,\n    )\n    self.tic()\n\n  def _check_consistency(self):\n    return [str(m.getMessage()) for m in self.constraint._checkConsistency(self.resource)]\n\n  def test_measure_consistency(self):\n    m = self.resource.newContent(portal_type=\'Measure\')\n    m.setMetricType(\'unit/a\')\n    self.assertIn(\n      \"Measure for metric_type \'unit/a\' doesn\'t have a valid quantity_unit\",\n      self._check_consistency())\n    m.setQuantityUnit(\'unit/piece\')\n    self.assertIn(\n      \"Measure for metric_type \'unit/a\' doesn\'t have a valid quantity value\",\n      self._check_consistency())\n    m.setQuantity(1)\n    self.assertFalse(self._check_consistency())\n\n\nclass DefaultSupplyLineTestCase(ERP5TypeTestCase):\n  def _makeOne(self):\n    raise NotImplementedError()\n\n  def afterSetUp(self):\n    super(DefaultSupplyLineTestCase, self).afterSetUp()\n    if self.portal.portal_categories.quantity_unit.get(\'time\') is None:\n      self.portal.portal_categories.quantity_unit.newContent(id=\'time\')\n    if self.portal.portal_categories.quantity_unit.time.get(\'hour\') is None:\n      self.portal.portal_categories.quantity_unit.time.newContent(id=\'hour\')\n    self.resource = self._makeOne()\n\n  def test_purchase_supply_line(self):\n    self.resource.edit(purchase_supply_line_base_price=123)\n    self.assertEqual(self.resource.getPurchaseSupplyLineBasePrice(), 123)\n    self.resource.edit(purchase_supply_line_priced_quantity=2)\n    self.assertEqual(self.resource.getPurchaseSupplyLinePricedQuantity(), 2)\n    self.resource.edit(purchase_supply_line_quantity_unit=\'time/hour\')\n    self.assertEqual(\n        self.resource.getPurchaseSupplyLineQuantityUnitValue(),\n        self.portal.portal_categories.quantity_unit.time.hour)\n    self.assertEqual(\n        self.resource.default_psl.getPortalType(), \'Purchase Supply Line\')\n\n  def test_internal_supply_line(self):\n    self.resource.edit(internal_supply_line_base_price=123)\n    self.assertEqual(self.resource.getInternalSupplyLineBasePrice(), 123)\n    self.resource.edit(internal_supply_line_priced_quantity=2)\n    self.assertEqual(self.resource.getInternalSupplyLinePricedQuantity(), 2)\n    self.resource.edit(internal_supply_line_quantity_unit=\'time/hour\')\n    self.assertEqual(\n        self.resource.getInternalSupplyLineQuantityUnitValue(),\n        self.portal.portal_categories.quantity_unit.time.hour)\n    self.assertEqual(\n        self.resource.default_isl.getPortalType(), \'Internal Supply Line\')\n\n  def test_sale_supply_line(self):\n    self.resource.edit(sale_supply_line_base_price=123)\n    self.assertEqual(self.resource.getSaleSupplyLineBasePrice(), 123)\n    self.resource.edit(sale_supply_line_priced_quantity=2)\n    self.assertEqual(self.resource.getSaleSupplyLinePricedQuantity(), 2)\n    self.resource.edit(sale_supply_line_quantity_unit=\'time/hour\')\n    self.assertEqual(\n        self.resource.getSaleSupplyLineQuantityUnitValue(),\n        self.portal.portal_categories.quantity_unit.time.hour)\n    self.assertEqual(\n        self.resource.default_ssl.getPortalType(), \'Sale Supply Line\')\n\n\nclass TestProductDefaultSupplyLine(DefaultSupplyLineTestCase):\n  def _makeOne(self):\n    return self.portal.product_module.newContent(portal_type=\'Product\')\n\n\nclass TestServiceDefaultSupplyLine(DefaultSupplyLineTestCase):\n  def _makeOne(self):\n    return self.portal.service_module.newContent(portal_type=\'Service\')\n\n\nclass TestComponentDefaultSupplyLine(DefaultSupplyLineTestCase):\n  def _makeOne(self):\n    return self.portal.component_module.newContent(portal_type=\'Component\')\n\n\ndef test_suite():\n  suite = unittest.TestSuite()\n  suite.addTest(unittest.makeSuite(TestPDMWithSecurity))\n  suite.addTest(unittest.makeSuite(TestResourceMeasureConstraint))\n  suite.addTest(unittest.makeSuite(TestProductDefaultSupplyLine))\n  suite.addTest(unittest.makeSuite(TestServiceDefaultSupplyLine))\n  suite.addTest(unittest.makeSuite(TestComponentDefaultSupplyLine))\n  return suite'),(4817,'ResourceMeasuresConsistencyConstraint'),(4819,'ResourceConstraint'),(4820,'document.erp5.Variation Variation ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\n\n#from Products.ERP5.Core import Variation\n\n#class Variation(XMLObject, Variation):\nclass Variation(XMLObject):\n  \"\"\"\n  A Variation\n  \"\"\"\n  meta_type = \'ERP5 Variation\'\n  portal_type = \'Variation\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Price\n                    , PropertySheet.Variation\n                    , PropertySheet.VariationRange\n                    , PropertySheet.Reference\n                    )'),(4821,'document.erp5.TransformedResource TransformedResource # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2002, 2004 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#                    Romain Courteaud <romain@nexedi.com>\n# Copyright (c) 2010 Nexedi SA and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.AmountGeneratorLine import AmountGeneratorLine\n\n\nclass TransformedResource(AmountGeneratorLine):\n  \"\"\"\n    TransformedResource defines which resource is being transformed\n    in order to produce a product define in the parent Transformation\n    document.\n\n    TODO:\n    - transformations used to work perfectly for more than 3 dimensions\n      of variations. However, this feature was broken with time and\n      is no longer usable. It is time to reimplement it. This is\n      completely unrelated to MatrixBox reimplementation unlike\n      what is stated in some comments.\n  \"\"\"\n\n  meta_type = \'ERP5 Transformed Resource\'\n  portal_type = \'Transformed Resource\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = (PropertySheet.TransformedResource, )\n\n  ### Mapped Value Definition\n  # Provide default mapped value properties and categories if\n  # not defined\n  def getMappedValuePropertyList(self):\n    result = self._baseGetMappedValuePropertyList()\n    if not result:\n      # Since MappedValue does not inherit Amount, and type class of\n      # Transformation {Operation,Transformed Resource} Cell\n      # was changed to TransformedResource as a workaround,\n      # we also need to check if \'self\' has a quantity.\n      # Otherwise, generated amounts could have 0 quantity\n      # (overridden by cells that only define variation).\n      result = [\'quantity\']\n      # Take into account variation_property_list for each variation\n      # for which hasProperty is true...\n      # FIXME: Why the resource and not the model line itself ? Or both ??\n      resource = self.getDefaultResourceValue()\n      if resource is not None:\n        result += resource.getVariationPropertyList()\n      result = filter(self.hasProperty, result)\n    return result\n\n  def getMappedValueBaseCategoryList(self, *args, **kw):\n    result = list(self._baseGetMappedValueBaseCategoryList())\n    if not result:\n      if not self.hasCellContent(base_id=\'variation\'):\n        result = list(self.getVariationRangeBaseCategoryList()) # The current resource variation\n      if \'trade_phase\' not in result:\n        result.append(\'trade_phase\')\n      if \'industrial_phase\' not in result:\n        result.append(\'industrial_phase\')\n    return result\n\n  def getCellAggregateKey(self):\n    \"\"\"Define a key in order to aggregate amounts at cell level\"\"\"\n    return None\n\n  @classmethod\n  def getBaseAmountQuantity(cls, delivery_amount, base_application, rounding, *args, **kw):\n    value = delivery_amount.getGeneratedAmountQuantity(base_application)\n    if base_application == \'base_amount/produced_quantity\':\n      value += delivery_amount.getConvertedQuantity()\n    return value\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getBaseApplication\')\n  def getBaseApplication(self):\n    \"\"\"\n    \"\"\"\n    return self.getBaseApplicationList()[0]\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getBaseApplicationList\')\n  def getBaseApplicationList(self):\n    \"\"\"\n    \"\"\"\n    # It is OK to try to acquire\n    return self._categoryGetBaseApplicationList() \\\n        or [\'base_amount/produced_quantity\']\n\n  ### Variation matrix definition\n  # XXX-JPS Some explanation needed\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'updateVariationCategoryList\')\n  def updateVariationCategoryList(self):\n    \"\"\"\n        Check if variation category list of the resource changed and\n        update transformed resource by doing a set cell range\n    \"\"\"\n    self.setQVariationBaseCategoryList(self.getQVariationBaseCategoryList())\n    self.setVVariationBaseCategoryList(self.getVVariationBaseCategoryList())\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'_setQVariationBaseCategoryList\')\n  def _setQVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Quantity value (Q)\n        variate on\n    \"\"\"\n    self._baseSetQVariationBaseCategoryList(value)\n    self._updateCellRange(\'quantity\')\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'_setVVariationBaseCategoryList\')\n  def _setVVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Variation value (V)\n        variate on\n    \"\"\"\n    self._baseSetVVariationBaseCategoryList(value)\n    # XXX calling updatecellRange is better\n    self._updateCellRange(\'variation\')\n    # XXX-JPS This should be handled by interaction workflow or interactor\n    # XXX-JPS SO many cases are not handled well...\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'setVVariationBaseCategoryList\')\n  def setVVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Variation value (V)\n        variate on and reindex the object\n    \"\"\"\n    self._setVVariationBaseCategoryList(value)\n    self.reindexObject()'),(4822,'document.erp5.Transformation Transformation # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2002 Coramy SAS and Contributors. All Rights Reserved.\n#                    Thierry_Faucher <Thierry_Faucher@coramy.com>\n# Copyright (c) 2004-2010 Nexedi SA and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Łukasz Nowak <luke@nexedi.com>\n#                    Jean-Paul Smets <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\nfrom warnings import warn\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.CMFCategory.Renderer import Renderer\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.Amount import Amount\nfrom erp5.component.document.MappedValue import MappedValue\n\nfrom erp5.component.mixin.AmountGeneratorMixin import AmountGeneratorMixin\nfrom Products.ERP5.mixin.variated import VariatedMixin\n\n# XXX Give priority to VariatedMixin (over Amount) due to conflicting\n#     implementations of getVariationBaseCategoryList\nclass Transformation(MappedValue, VariatedMixin, Amount, AmountGeneratorMixin):\n  \"\"\"\n  Build of material - contains a list of transformed resources\n\n  Use of default_resource... (to define the variation range,\n  to ...)\n\n  XXX Transformation works only for a maximum of 3 variation base category...\n  Matrixbox must be rewritten for a clean implementation of n base category\n  \"\"\"\n  meta_type = \'ERP5 Transformation\'\n  portal_type = \'Transformation\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Comment\n                    , PropertySheet.Version\n                    #, PropertySheet.Resource\n                    , PropertySheet.TransformedResource\n                    , PropertySheet.Transformation\n                    , PropertySheet.Order\n                    , PropertySheet.Task\n                    )\n\n  def getAggregatedAmountList(self, *args, **kw):\n    \"\"\"\n    \"\"\"\n    getAggregatedAmountList = \\\n      super(Transformation, self).getAggregatedAmountList\n    # Detect old use of getAggregatedAmountList\n    if \'context\' in kw:\n      context = kw.pop(\'context\')\n    else:\n      if not args or isinstance(args[0], (list, tuple)):\n        return getAggregatedAmountList(*args, **kw)\n      context, args = args[0], args[1:]\n    warn(\"The API of getAggregatedAmountList has changed:\"\n         \" it must be called on the context instead of passing\"\n         \" the context as first parameter\", DeprecationWarning)\n    # XXX add a \'transformation_amount_generator\' group type\n    kw[\'amount_generator_type_list\'] = (\'Transformation\',\n                                        \'Transformed Resource\',\n                                        \'Transformation Operation\',\n                                        \'Assorted Resource\')\n    if context is not None:\n      context = (context,)\n    return getAggregatedAmountList(context, *args, **kw)\n\n  def getQuantity(self, default=None):\n    # Used for amount generation\n    # (Transformation is defined for 1 unit of target resource)\n    return 1.\n\n  # Predicate Value implementation\n  #   asPredicate takes into account the resource\n  # XXX-JPS not Impl.\n\n  # Mapped Value implementation\n  #  Transformation itself provides no properties or categories\n  def getMappedValuePropertyList(self):\n    return ()\n\n  def getMappedValueBaseCategoryList(self, *args, **kw):\n    return ()\n\n  # IVariationRange and IVariated Implementation\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'updateVariationCategoryList\')\n  def updateVariationCategoryList(self):\n    \"\"\"\n    Check if variation category list of the resource has changed and update\n    transformation and transformation line\n    \"\"\"\n    self.setVariationBaseCategoryList(self.getVariationBaseCategoryList())\n    transformation_line_list = self.contentValues()\n    for transformation_line in transformation_line_list:\n      transformation_line.updateVariationCategoryList()\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getVariationRangeBaseCategoryList\')\n  def getVariationRangeBaseCategoryList(self):\n    \"\"\"\n    Returns possible variation base_category ids of the\n    default resource which can be used as variation axis\n    in the transformation.\n    \"\"\"\n    resource = self.getResourceValue()\n    if resource is not None:\n      result = resource.getVariationBaseCategoryList()\n    else:\n      # XXX result = self.getBaseCategoryIds()\n      # Why calling this method ?\n      # Get a global variable which define a list of variation base category\n      result = self.getPortalVariationBaseCategoryList()\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getVariationRangeBaseCategoryItemList\')\n  def getVariationRangeBaseCategoryItemList(self, display_id=\'getTitleOrId\', **kw):\n    \"\"\"\n    Returns possible variations of the transformation\n    as a list of tuples (id, title). This is mostly\n    useful in ERP5Form instances to generate selection\n    menus.\n    \"\"\"\n    return self.portal_categories.getItemList(\n                              self.getVariationRangeBaseCategoryList(),\n                              display_id=display_id, **kw)\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getVariationRangeCategoryItemList\')\n  def getVariationRangeCategoryItemList(self, base_category_list=(),\n                                        omit_individual_variation=0,\n                                        display_base_category=1, **kw):\n    \"\"\"\n    Returns possible variation category values for the\n    transformation according to the default resource.\n    Possible category values are provided as a list of\n    tuples (id, title). This is mostly\n    useful in ERP5Form instances to generate selection\n    menus.\n    User may want to define generic transformation without\n    any defined resource.\n    \"\"\"\n    if base_category_list == ():\n      base_category_list = self.getVariationBaseCategoryList()\n\n    resource = self.getResourceValue()\n    if resource is not None:\n      result = resource.getVariationCategoryItemList(\n                        base_category_list=base_category_list,\n                        omit_individual_variation=omit_individual_variation,\n                        display_base_category=display_base_category,**kw)\n    else:\n      # No resource is define on transformation.\n      # We want to display content of base categories\n      result = self.portal_categories.getCategoryChildTitleItemList(\n                         base_category_list, base=1, display_none_category=0)\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'setVariationBaseCategoryList\')\n  def setVariationBaseCategoryList(self, value):\n    \"\"\"\n    Define the possible base categories and reindex object\n    \"\"\"\n    self._setVariationBaseCategoryList(value)\n    self.reindexObject()\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getVariationCategoryItemList\')\n  def getVariationCategoryItemList(self, base_category_list=(), base=1,\n                                   display_id=\'title\',\n                                   current_category=None,\n                                   **kw):\n    \"\"\"\n    Returns the list of possible variations\n    XXX Copied and modified from VariatedMixin\n    Result is left display.\n    \"\"\"\n    variation_category_item_list = []\n    if base_category_list == ():\n      base_category_list = self.getVariationBaseCategoryList()\n\n    category_renderer = Renderer(\n                             is_right_display=0,\n                             display_none_category=0, base=base,\n                             current_category=current_category,\n                             display_id=\'logical_path\', **kw)\n\n    for base_category in base_category_list:\n      variation_category_list = self.getVariationCategoryList(\n                                            base_category_list=[base_category])\n\n      category_list = []\n      object_list = []\n      for variation_category in variation_category_list:\n        resource = self.portal_categories.resolveCategory(variation_category)\n        if resource.getPortalType() == \'Category\':\n          category_list.append(resource)\n        else:\n          object_list.append(resource)\n\n      variation_category_item_list.extend(category_renderer.\\\n                                              render(category_list))\n\n      variation_category_item_list.extend(Renderer(\n                               is_right_display=0,\n                               base_category=base_category,\n                               display_none_category=0, base=base,\n                               current_category=current_category,\n                               display_id=display_id,**kw).\\\n                                                 render(object_list))\n    return variation_category_item_list'),(4823,'document.erp5.ResourceMeasuresConsistencyConstraint ResourceMeasuresConsistencyConstraint ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom Products.ERP5Type.mixin.constraint import ConstraintMixin\nfrom Products.ERP5Type import PropertySheet\n\n\nclass ResourceMeasuresConsistencyConstraint(ConstraintMixin):\n  \"\"\"\n  Check that measures defined on a resource are not meaningless.\n\n  Choosing quantity units for a resource without defining measures is\n  tolerated, for compatibility, although conversion between units\n  won\'t be possible.\n\n  This is only relevant for ZODB Property Sheets (filesystem Property\n  Sheets rely on Products.ERP5.Constraint.ResourceMeasuresConsistency\n  instead).\n  \"\"\"\n  meta_type = \'ERP5 Resource Measures Consistency Constraint\'\n  portal_type = \'Resource Measures Consistency Constraint\'\n\n  property_sheets = ConstraintMixin.property_sheets + \\\n                    (PropertySheet.ResourceMeasuresConsistencyConstraint,)\n\n  def _checkConsistency(self, obj, fixit=0):\n    \"\"\"\n    Check the object\'s consistency\n    \"\"\"\n    error_list = []\n    portal = obj.getPortalObject()\n\n    error = lambda msg, **kw: error_list.append(\n      self._generateError(obj, self._getMessage(msg), mapping=kw))\n\n    getCategoryValue = portal.portal_categories.getCategoryValue\n    display = lambda *args, **kw: \\\n      getCategoryValue(*args, **kw).getCompactLogicalPath()\n\n    top = lambda relative_url: relative_url.split(\'/\', 1)[0]\n\n    quantity_map = {}\n    metric_type_set = set()\n\n    quantity_unit_definition_dict = obj._getQuantityUnitDefinitionDict()\n\n    for measure in obj.getMeasureList():\n      metric_type = measure.getMetricType()\n      if metric_type:\n        quantity = top(metric_type)\n        default_or_generic = quantity_map.setdefault(quantity, [0, 0])\n        if measure.getDefaultMetricType():\n          default_or_generic[0] += 1\n        if quantity == metric_type:\n          default_or_generic[1] += 1\n\n        if not measure.getConvertedQuantityUnit():\n          error(\'message_measure_no_quantity_unit\',\n                metric_type=display(metric_type, \'metric_type\'))\n        elif not measure.asCatalogRowList(quantity_unit_definition_dict):\n          error(\'message_measure_no_quantity\',\n                metric_type=display(metric_type, \'metric_type\'))\n        if metric_type in metric_type_set:\n          error(\'message_duplicate_metric_type\',\n                metric_type=display(metric_type, \'metric_type\'))\n        else:\n          metric_type_set.add(metric_type)\n      #else:\n      # pass # we don\'t care about undefined measures\n\n    for i, quantity_unit in enumerate(obj.getQuantityUnitList()):\n      quantity = top(quantity_unit)\n      default, generic = quantity_map.get(quantity, (0, 0))\n      if (default or generic) > 1:\n        error(\'message_duplicate_default_measure\',\n              quantity_unit=display(quantity_unit, \'quantity_unit\'))\n      elif not (default or generic):\n        if i:\n          pass # tolerate quantity units without any measure associated to them\n        else: # management unit: check we can create an implicit measure\n          if getCategoryValue(quantity, \'metric_type\') is None:\n            error(\'message_missing_metric_type\', metric_type=quantity)\n\n    return error_list\n\n  _message_id_tuple = (\'message_measure_no_quantity_unit\',\n                       \'message_measure_no_quantity\',\n                       \'message_duplicate_metric_type\',\n                       \'message_duplicate_default_measure\',\n                       \'message_missing_metric_type\')'),(4824,'document.erp5.QuantityUnitConversionGroup QuantityUnitConversionGroup ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SARL and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Permissions import AccessContentsInformation\nfrom Products.ERP5Type.XMLObject import XMLObject\n\n\nclass QuantityUnitConversionGroup(XMLObject):\n  \"\"\"\n    Quantity Unit Conversion Group defined per-product.\n  \"\"\"\n\n  meta_type = \'ERP5 Quantity Unit Conversion Group\'\n  portal_type = \'Quantity Unit Conversion Group\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.Amount\n                    )\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getTitle\')\n  def getTitle(self):\n    \"\"\"\n      Set a title that includes the Quantity Unit\n    \"\"\"\n    default_title = self._baseGetTitle()\n\n    quantity_unit = self.getQuantityUnitValue()\n    if quantity_unit is not None:\n      return \"%s Conversion Group\" % quantity_unit.getParentValue().getTitle()\n\n    return default_title'),(4825,'document.erp5.QuantityUnitConversionDefinition QuantityUnitConversionDefinition ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SARL and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Permissions import AccessContentsInformation\nfrom Products.ERP5Type.XMLObject import XMLObject\n\n\nclass QuantityUnitConversionDefinition(XMLObject):\n  \"\"\"\n    Quantity Unit Conversion Definition\n  \"\"\"\n\n  meta_type = \'ERP5 Quantity Unit Conversion Definition\'\n  portal_type = \'Quantity Unit Conversion Definition\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.Amount\n                    , PropertySheet.QuantityUnitConversionDefinition\n                    )\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getTitle\')\n  def getTitle(self):\n    \"\"\"\n      Set a title that includes the Quantity Unit\n    \"\"\"\n    default_title = self._baseGetTitle()\n\n    quantity_unit = self.getQuantityUnitValue()\n    if quantity_unit is not None:\n      # only the last part is relevant\n      return \"%s Definition\" % quantity_unit.getTitle()\n\n    return default_title\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getConversionRatio\')\n  def getConversionRatio(self):\n    \"\"\"\n      Compute conversion ratio associated with this definition\n    \"\"\"\n    quantity = self.getQuantity()\n\n    if quantity != 0 and self.isInverse():\n      quantity = 1.0/quantity\n\n    return quantity'),(4826,'document.erp5.Measure Measure ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SARL and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom zLOG import LOG, WARNING\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import PropertySheet\nfrom Products.ERP5Type.Permissions import AccessContentsInformation\nfrom Products.ERP5Type.XMLMatrix import XMLMatrix\n\n\nclass Measure(XMLMatrix):\n  \"\"\"\n    A Measure\n  \"\"\"\n\n  meta_type = \'ERP5 Measure\'\n  portal_type = \'Measure\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.Measure\n                    )\n\n  security.declareProtected(AccessContentsInformation, \'getResourceValue\')\n  def getResourceValue(self):\n    \"\"\"\n    Gets the resource object described by this measure.\n    \"\"\"\n    return self.getDefaultResourceValue()\n\n  ##\n  #  Forms.\n\n  security.declareProtected(AccessContentsInformation, \'getVariationRangeCategoryItemList\')\n  def getVariationRangeCategoryItemList(self, variation):\n    \"\"\"\n    Returns possible variation category values for the selected variation.\n    variation is a 0-based index and possible category values is provided\n    as a list of tuples (id, title). This is mostly useful for matrixbox.\n    \"\"\"\n    mvbc_list = self.getMeasureVariationBaseCategoryList()\n    if len(mvbc_list) <= variation:\n      return ()\n    return self.getResourceValue().getVariationCategoryItemList(\n      is_right_display=1,\n      base_category_list=(mvbc_list[variation],),\n      omit_individual_variation=0,\n      display_base_category=0,\n      sort_id=\'id\')\n\n  security.declareProtected(AccessContentsInformation, \'getQuantityUnitItemList\')\n  def getQuantityUnitItemList(self):\n    \"\"\"\n    Returns the list of possible quantity units for the current metric type.\n    This is mostly useful in ERP5Form instances to generate selection menus.\n    \"\"\"\n    metric_type = self.getMetricType()\n    if not metric_type:\n      return (\'\', \'\'),\n    portal = self.getPortalObject()\n    return getattr(\n      portal.portal_categories.getCategoryValue(metric_type.split(\'/\', 1)[0],\n                                                \'quantity_unit\'),\n      portal.portal_preferences.getPreference(\n        \'preferred_category_child_item_list_method_id\',\n        \'getCategoryChildCompactLogicalPathItemList\')\n    )(recursive=0, local_sort_id=\'quantity\', checked_permission=\'View\')\n\n  security.declareProtected(AccessContentsInformation, \'getLocalQuantityUnit\')\n  def getLocalQuantityUnit(self):\n    \"\"\"\n    Returns the \'quantity_unit\' category without acquisition.\n    Used in Resource_viewMeasure and Measure_view.\n    \"\"\"\n    quantity_unit_list = self.getPortalObject().portal_categories \\\n      .getSingleCategoryMembershipList(self, \'quantity_unit\')\n    if quantity_unit_list:\n      return quantity_unit_list[0]\n\n  ##\n  #  Measures associated to a quantity unit of the resource\n  #  have a specific behaviour.\n\n  security.declareProtected(AccessContentsInformation, \'isDefaultMeasure\')\n  def isDefaultMeasure(self, quantity_unit=None):\n    \"\"\"\n    Checks if self is a default measure for the associated resource.\n    \"\"\"\n    default = self.getResourceValue().getDefaultMeasure(quantity_unit)\n    return default is not None \\\n       and self.getRelativeUrl() == default.getRelativeUrl()\n\n  ##\n  #  Conversion.\n\n  security.declareProtected(AccessContentsInformation, \'getConvertedQuantityUnit\')\n  def getConvertedQuantityUnit(self):\n    \"\"\"\n    Gets the quantity unit ratio, in respect to the base quantity unit.\n    \"\"\"\n    quantity_unit = self.getQuantityUnitValue()\n    metric_type = self.getMetricType()\n    if quantity_unit is not None and metric_type and \\\n        quantity_unit.getParentId() == metric_type.split(\'/\', 1)[0]:\n      return self.getQuantityUnitDefinitionRatio(quantity_unit)\n\n  security.declareProtected(AccessContentsInformation, \'getConvertedQuantity\')\n  def getConvertedQuantity(self, variation_list=()):\n    \"\"\"\n    Gets the measure value for a specified variation,\n    in respected to the base quantity unit.\n\n    Should it be reimplemented using predicates?\n    If so, \'variation_list\' parameter is deprecated.\n    \"\"\"\n    quantity_unit = self.getConvertedQuantityUnit()\n    if not quantity_unit:\n      return\n    quantity = self.getQuantity()\n    if variation_list:\n      variation_set = set(variation_list)\n      for cell in self.objectValues():\n        # if cell.test(context): # XXX\n        if variation_set.issuperset(\n            cell.getMembershipCriterionCategoryList()):\n          quantity = cell.getQuantity()\n          break\n    return quantity * quantity_unit\n\n  ##\n  #  Cataloging.\n\n  security.declareProtected(AccessContentsInformation, \'asCatalogRowList\')\n  def asCatalogRowList(self, quantity_unit_definition_dict):\n    \"\"\"\n    Returns the list of rows to insert in the measure table of the catalog.\n    Called by Resource.getMeasureRowList.\n    \"\"\"\n    # The only purpose of the defining a default measure explicitly is to\n    # set a specific metric_type for the management unit.\n    # Therefore, the measure mustn\'t be variated and the described quantity\n    # (quantity * quantity_unit) must match the management unit.\n    # If the conditions aren\'t met, return an empty list.\n    default = self.isDefaultMeasure()\n\n    resource = self.getResourceValue()\n    resource_uid = resource.getUid()\n\n    quantity_unit_value = self.getQuantityUnitValue()\n    if default and quantity_unit_value is None:\n      # for default measure candidates, we do not care if the\n      # quantity is not set: use the resource quantity unit!\n      quantity_unit_value = resource.getQuantityUnitValue()\n\n    metric_type = self.getMetricType()\n    if quantity_unit_value is None or not metric_type or \\\n        quantity_unit_value.getParentId() != metric_type.split(\'/\', 1)[0]:\n      return ()\n\n    def getQuantity(quantity_unit_value):\n      quantity_unit_uid = quantity_unit_value.getUid()\n      try:\n        return quantity_unit_definition_dict[quantity_unit_uid][1]\n      except KeyError:\n        LOG(\"Measure\", WARNING,\n            \"could not find an Unit Definition for \'%s\' while \" \\\n            \"indexing Measure \'%s\'\" % \\\n                (quantity_unit_value.getRelativeUrl(),\n                 self.getRelativeUrl()))\n        return None\n\n    uid = self.getUid()\n    metric_type_uid = self.getMetricTypeUid()\n    quantity = self.getQuantity()\n\n    quantity_unit = getQuantity(quantity_unit_value)\n    if quantity_unit is None:\n      return ()\n\n    measure_variation_base_category_list = \\\n      self.getMeasureVariationBaseCategoryList()\n    if not measure_variation_base_category_list:\n      # Easy case: there is no variation axe for this metric_type,\n      # so we simply return 1 row.\n      if quantity is not None:\n        quantity *= quantity_unit\n        management_unit_value = resource.getQuantityUnitValue()\n        management_unit_quantity = None\n        if management_unit_value is not None:\n          management_unit_quantity = getQuantity(management_unit_value)\n\n        if (not default or quantity == management_unit_quantity):\n          return (dict(uid=uid, resource_uid=resource_uid,\n                       variation=\'^\', metric_type_uid=metric_type_uid,\n                       quantity=quantity)),\n      return ()\n\n    if default:\n      return ()\n\n    # 1st step: Build a list of possible variation combinations.\n    # Each element of the list (variation_list) is a pair of lists, where:\n    #  * first list\'s elements are regex tokens:\n    #    they\'ll be used to build the \'variation\' values (in the result).\n    #  * the second list is a combination of categories, used to find\n    #    the measure cells containing the \'quantity\' values.\n    #\n    # This step is done by starting from a 1-element list (variation_list).\n    # For each variation axe (if variation_base_category in\n    # measure_variation_base_category_list), we rebuild variation_list entirely\n    # and its size is multiplied by the number of categories in this axe.\n    # For other variation base categories (variation_base_category not in\n    # measure_variation_base_category_list), we simply\n    # update variation_list to add 1 regex token to each regex list.\n    #\n    # Example:\n    #  * variation base categories: colour, logo, size\n    #  * variation axes: colour, size\n    #\n    #  variation_list (tokens are simplified for readability):\n    # 0. []\n    # 1. [([colour/red],   [\'colour/red\']),\n    #     ([colour/green], [\'colour/green\']),\n    #     ([colour/blue],  [\'colour/blue\'])]\n    # 2. [([colour/red,   logo/*], [\'colour/red\']),\n    #     ([colour/green, logo/*], [\'colour/green\']),\n    #     ([colour/blue,  logo/*], [\'colour/blue\'])]\n    # 3. [([colour/red,   logo/*, size/small], [\'colour/red\',   \'size/small\']),\n    #     ([colour/green, logo/*, size/small], [\'colour/green\', \'size/small\']),\n    #     ([colour/blue,  logo/*, size/small], [\'colour/blue\',  \'size/small\']),\n    #     ([colour/red,   logo/*, size/medium], [\'colour/red\',   \'size/medium\']),\n    #     ([colour/green, logo/*, size/medium], [\'colour/green\', \'size/medium\']),\n    #     ([colour/blue,  logo/*, size/medium], [\'colour/blue\',  \'size/medium\']),\n    #     ([colour/red,   logo/*, size/big], [\'colour/red\',   \'size/big\']),\n    #     ([colour/green, logo/*, size/big], [\'colour/green\', \'size/big\']),\n    #     ([colour/blue,  logo/*, size/big], [\'colour/blue\',  \'size/big\'])]\n\n    # Note that from this point, we always work with sorted lists of\n    # categories (or regex tokens).\n\n    variation_list = ([], []),\n    optional_variation_base_category_set = \\\n      set(resource.getOptionalVariationBaseCategoryList())\n    for variation_base_category in sorted(\n        resource.getVariationBaseCategoryList(omit_optional_variation=0)):\n      if variation_base_category in measure_variation_base_category_list:\n        # This is where we rebuild variation_list entirely. Size of\n        # variation_list is multiplied by len(getVariationCategoryList).\n        # The lists of each pairs in variation_list get one more element:\n        # variation_category.\n        variation_list = [(regex_list + [variation_category, \'\\n\'],\n                           variation_base_category_list + [variation_category])\n          for regex_list, variation_base_category_list in variation_list\n          for variation_category in resource.getVariationCategoryList(\n            base_category_list=(variation_base_category,),\n            omit_individual_variation=0)]\n      else:\n        variation_base_category_regex = variation_base_category + \'/[^\\n]+\\n\'\n        if variation_base_category in optional_variation_base_category_set:\n          variation_base_category_regex = \\\n            \'(%s)*\' % (variation_base_category_regex, )\n        for regex_list, variation_base_category_list in variation_list:\n          regex_list.append(variation_base_category_regex)\n\n    # 2nd step: Retrieve all measure cells in a dictionary for fast lookup.\n    cell_map = {}\n    for cell in self.objectValues():\n      cell_map[tuple(sorted(cell.getMembershipCriterionCategoryList()))] \\\n        = cell.getQuantity()\n\n    # 3rd step: Build the list of rows to return,\n    # by merging variation_list (1st step) and cell_map (2nd step).\n    row_list = []\n    for regex_list, variation_base_category_list in variation_list:\n      cell = cell_map.get(tuple(variation_base_category_list))\n      if cell is None:\n        if quantity is None:\n          continue\n        cell = quantity\n      row_list.append(dict(uid=uid,\n                       resource_uid=resource_uid,\n                       variation=\'^%s$\' % \'\'.join(regex_list),\n                       metric_type_uid=metric_type_uid,\n                       quantity=cell * quantity_unit))\n\n    return row_list'),(4827,'document.erp5.Consumption Consumption ##############################################################################\n#\n# Copyright (c) 2002 Coramy SAS and Contributors. All Rights Reserved.\n#                    Thierry_Faucher <Thierry_Faucher@coramy.com>\n# Copyright (c) 2004 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Courteaud_Romain <romain@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.XMLMatrix import XMLMatrix\nfrom Products.ERP5.mixin.variated import VariatedMixin\n\n\nclass Consumption(XMLObject, XMLMatrix, VariatedMixin):\n  \"\"\"\n    A matrix which provides default quantities\n    for a given quantity\n  \"\"\"\n\n  meta_type = \'ERP5 Consumption\'\n  portal_type = \'Consumption\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.VariationRange\n                    )\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'_setVariationCategoryList\')\n  def _setVariationCategoryList(self, value, base_category_list=()):\n    \"\"\"\n      Set consumption variation category list.\n      Set matrix cell range.\n    \"\"\"\n    self._setCategoryMembership(self.getVariationRangeBaseCategoryList(),\n                                value, base=1)\n    # XXX Must use in futur this method, but it failed today\n    #VariatedMixin._setVariationCategoryList(self, value)\n    # XXX FIXME: Use a interaction workflow instead\n    # Kept for compatibility.\n    self.updateCellRange(base_id=\'quantity\')\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'setVariationCategoryList\')\n  def setVariationCategoryList(self, value, base_category_list=()):\n    \"\"\"\n      Set consumption variation category list.\n      Reindex Object.\n    \"\"\"\n    self._setVariationCategoryList(value)\n    self.reindexObject()\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'getVariationRangeBaseCategoryItemList\')\n  def getVariationRangeBaseCategoryItemList(\n      self,\n      base=1,\n      display_id=\'getTitle\',\n      current_category=None):\n    \"\"\"\n      Return range of base variation item\n      Left display\n    \"\"\"\n    # XXX get TitleOrId\n    return [(x, x) for x in self.getVariationRangeBaseCategoryList()]\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                            \'getQuantityRatio\')\n  def getQuantityRatio(self, variation_category_line,\n                        variation_category_column):\n    \"\"\"\n      Return quantity ratio for a virtual cell.\n      Return None if not result can be return.\n    \"\"\"\n    cell_quantity_ratio_list = []\n\n    for variation_category in (variation_category_line,\n                                variation_category_column):\n      cell = self.getCell(variation_category, base_id=\'quantity\')\n      if cell is None:\n        return None\n      else:\n        cell_quantity_ratio = cell.getProperty(\'quantity\')\n        if cell_quantity_ratio in [None, 0, \'\']:\n          return None\n        else:\n          cell_quantity_ratio_list.append( cell_quantity_ratio )\n\n    return cell_quantity_ratio_list[1] / cell_quantity_ratio_list[0]'),(4828,'document.erp5.AssortedResource AssortedResource ##############################################################################\n#\n# Copyright (c) 2002 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Jean-Paul Smets-Solanes <jp@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\n\nfrom Products.ERP5Type import Permissions, Constraint\nfrom Products.ERP5Type.XMLMatrix import XMLMatrix\nfrom Products.ERP5Type.Utils import cartesianProduct\nfrom erp5.component.document.AmountGeneratorLine import AmountGeneratorLine\nfrom erp5.component.document.TransformedResource import TransformedResource\n\nfrom Products.CMFCore.Expression import Expression\n\nclass AssortedResource(TransformedResource):\n  \"\"\"\n        This code was copied from TransformedResource very stupidly.\n        Therefore it is necessaery to review all the code. -yo\n\n        AssortedResource defines which\n        resource is being assorted\n\n        - variation\n        - quantity\n\n        Maybe defined by mapped values inside the transformed resource\n\n        WARNING: the notion of category range is quite complex in this case.\n           getVariationRangeCategoryList -> possible variations of the transformed\n                                            resource ie. getVariationCategoryList\n                                            of the resource\n           getVariationCategoryList      -> variation value of the transformed\n                                            resource (ie. default variation)\n\n           getVariationRangeBaseCategoryList -> possible variation base categories\n                                                of the transformed resource\n                                                (ie. getVariationBaseCategoryList\n                                                of the resource)\n           getVariationBaseCategoryList      -> choice of variation base categories\n                                                defined by the transformed resource\n                          (should be the same as getVariationRangeBaseCategoryList)\n\n           getTransformationVariationRangeBaseCategoryList OK\n                                              -> possible variation base categories\n                                                  which can be used the the\n                                                 transformation matrix\n                                                 (based on resource)\n           getTransformationVariationBaseCategoryList OK\n                                              -> choice of variation base categories\n                                                  which can be used the the\n                                                 transformation matrix\n                                                 (based on resource)\n\n           getTransformationVariationRangeCategoryList OK\n                                              -> possible category values\n                                                 which can be used in the\n                                                 transformation matrix\n                                                 (based on resource)\n           getTransformationVariationCategoryList OK\n                                              -> choice of category values\n                                                 which can be used in the\n                                                 transformation matrix\n\n           XXX WE HAVE an issue here:\n           - the variation range of the transformation\n             defines both the variation range of the main resource\n             and the variation range for matrices\n\n           - where do we define default variation value\n             for the resource produced by the transformation ?\n             (probably in the domain fields)\n\n           - where do we define selection parameters ?\n\n           getResourceVariationCategoryList\n           getResourceVariationRangeCategoryList\n\n      setValueUids could be overriden to provide quick and dirty\n      behaviour of range update\n\n  \"\"\"\n\n  meta_type = \'ERP5 Assorted Resource\'\n  portal_type = \'Assorted Resource\'\n  add_permission = Permissions.AddPortalContent\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Local property sheet\n  _properties = (\n      { \'id\'          : \'variation_base_category\',\n        \'storage_id\'  : \'variation_base_category_list\', # Coramy Compatibility\n        \'description\' : \"\",\n        \'type\'        : \'tokens\',\n        \'acquisition_base_category\' : (\'resource\',),\n        \'acquisition_portal_type\'   : Expression(\'python: portal.getPortalResourceTypeList()\'),\n        \'acquisition_copy_value\'    : 0,\n        \'acquisition_mask_value\'    : 0,\n        \'acquisition_accessor_id\'   : \'getVariationBaseCategoryList\', ### XXX BUG\n        \'acquisition_depends\'       : None,\n        \'mode\'        : \'w\' },\n  )\n\n  getCellAggregateKey = AmountGeneratorLine.getCellAggregateKey\n  security.declareProtected(Permissions.AccessContentsInformation, \'getAssortedVariationCategoryList\')\n  def getAssortedVariationCategoryList(self, cell_index):\n    \"\"\"\n        Nice for A\n    \"\"\"\n    transformation = self.getParentValue()\n    transformation_category_list = transformation.getVariationCategoryList()\n    variation_category_list = []\n    for p in cell_index:\n      if p is not None and p not in transformation_category_list:\n        variation_category_list.append(p)\n    #LOG(\'getAssortedVariationCategoryList\', 0, repr(cell_index))\n    #LOG(\'getAssortedVariationCategoryList\', 0, repr(variation_category_list))\n    return variation_category_list\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getAssortedVariationBaseCategoryList\')\n  def getAssortedVariationBaseCategoryList(self):\n    \"\"\"\n        Nice for A\n    \"\"\"\n    return self.getQVariationBaseCategoryList()\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getAssortmentVariationCategoryList\')\n  def getAssortmentVariationCategoryList(self, cell_index):\n    \"\"\"\n        Nice for C\n    \"\"\"\n    transformation = self.getParentValue()\n    transformation_category_list = transformation.getVariationCategoryList()\n    variation_category_list = []\n    for p in cell_index:\n      if p is not None and p in transformation_category_list:\n        variation_category_list.append(p)\n    #LOG(\'getAssortmentVariationCategoryList\', 0, repr(cell_index))\n    #LOG(\'getAssortmentVariationCategoryList\', 0, repr(variation_category_list))\n    return variation_category_list\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getAssortmentVariationBaseCategoryList\')\n  def getAssortmentVariationBaseCategoryList(self):\n    \"\"\"\n        Nice for C\n    \"\"\"\n    #LOG(\'getAssortmentVariationBaseCategoryList\', 0, repr(self))\n    transformation = self.getParentValue()\n    return transformation.getVariationBaseCategoryList()\n\n  # XXX Should be moved to somewhere more global, as this is general.\n  #     This does not depend even on self.\n  #\n  # Return a sorted list of base categories. This makes views of matrices consistent.\n  # Use the global variables, \'column_base_category_list\' and \'line_base_category_list\'\n  # (but not \'tab_base_category_list\' at the moment).\n  def _getSortedBaseCategoryList(self, base_category_list):\n    base_category_list = base_category_list[:]  # Work on a copy.\n    base_category_list.sort()\n    column = None\n    line = None\n    sorted_list = [None, None]\n    for category in self.getPortalColumnBaseCategoryList():\n      if category in base_category_list:\n        if column is None:\n          column = category\n        else:\n          sorted_list.append(category)\n        base_category_list.remove(category)\n    for category in self.getPortalLineBaseCategoryList():\n      if category in base_category_list:\n        if line is None:\n          line = category\n        else:\n          sorted_list.append(category)\n        base_category_list.remove(category)\n    sorted_list.extend(base_category_list)\n    sorted_list[0] = line\n    sorted_list[1] = column\n    return sorted_list\n\n  # Update the range of cells according to the currently selected base categories.\n  def _updateCellRange(self, base=1, current_category=None, *args, **kw):\n    transformation = self.getParentValue()\n    kwd = {\'base_id\': \'quantity\'}\n    kw = []\n    base_category_list = self._getSortedBaseCategoryList(self.getQVariationBaseCategoryList())\n    for base_category in base_category_list:\n      # FIXME: Actually, getVariationRangeCategoryList should be used here.\n      #        But getVariationRangeCategoryList is inconsistent with\n      #        getVariationRangeCategoryItemList, because getVariationRangeCategoryItemList\n      #        is overrided in Amount and Resource. -yo\n      if base_category is None:\n        category_item_list = [(None,\'\')]\n      else:\n        category_item_list = self.getVariationRangeCategoryItemList(base_category_list = [base_category],\n                                                                    base=1)\n      category_list = []\n      for item in category_item_list:\n        category_list.append(item[0])\n      kw.append(category_list)\n    kw.append(transformation.getVariationCategoryList())\n    #LOG(\'_updateCellRange\', 20, str(kw))\n    self.setCellRange(*kw, **kwd)\n\n  ### Variation matrix definition\n  #\n  security.declareProtected(Permissions.ModifyPortalContent, \'_setQVariationBaseCategoryList\')\n  def _setQVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Quantity value (Q)\n        variate on\n    \"\"\"\n    self._baseSetQVariationBaseCategoryList(value)\n    self._updateCellRange()\n    # And fix it in case the cells are not renamed (XXX this will be removed in the future)\n    self._checkConsistency(fixit=1)\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'setQVariationBaseCategoryList\')\n  def setQVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Quantity value (Q)\n        variate on and reindex the object\n    \"\"\"\n    self._setQVariationBaseCategoryList(value)\n    self.reindexObject()\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'_setVVariationBaseCategoryList\')\n  def _setVVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Variation value (V)\n        variate on\n    \"\"\"\n    self._baseSetVVariationBaseCategoryList(value)\n    kwd = {}\n    kwd[\'base_id\'] = \'variation\'\n    kw = []\n    transformation = self.getParentValue()\n    line_id = transformation.getVariationBaseCategoryLine()\n    column_id = transformation.getVariationBaseCategoryColumn()\n    line = [[None]]\n    column = [[None]]\n    for v in value:\n      if v == line_id:\n        line = [transformation.getCategoryMembershipList(v,base=1)]\n      elif v == column_id:\n        column = [transformation.getCategoryMembershipList(v,base=1)]\n      else:\n        kw += [transformation.getCategoryMembershipList(v,base=1)]\n    kw = line + column + kw\n    self.setCellRange(*kw, **kwd)\n    # Empty cells if no variation\n    if line == [[None]] and column == [[None]]:\n      self.delCells(base_id=\'variation\')\n    # And fix it in case the cells are not renamed (XXX this will be removed in the future)\n    self._checkConsistency(fixit=1)\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'setVVariationBaseCategoryList\')\n  def setVVariationBaseCategoryList(self, value):\n    \"\"\"\n        Defines the possible base categories which Variation value (V)\n        variate on and reindex the object\n    \"\"\"\n    self._setVVariationBaseCategoryList(value)\n    self.reindexObject()\n\n  # Methods for matrix UI widgets\n  security.declareProtected(Permissions.AccessContentsInformation, \'getQLineItemList\')\n  def getQLineItemList(self, display_id=\'getTitle\', base=1, current_category=None):\n    \"\"\"\n    \"\"\"\n    line_category = self._getSortedBaseCategoryList(self.getQVariationBaseCategoryList())[0]\n    #LOG(\'getQLineItemList\', 0, \"%s\" % str(line_category))\n    if line_category is None:\n      result = [(None,\'\')]\n    else:\n      result = self.getVariationRangeCategoryItemList(base_category_list = [line_category],\n                                                      display_id=display_id,\n                                                      base=base,\n                                                      current_category=current_category)\n    #LOG(\'getQLineItemList\', 10, \"%s\" % str(result))\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getQColumnItemList\')\n  def getQColumnItemList(self, display_id=\'getTitle\', base=1, current_category=None):\n    \"\"\"\n    \"\"\"\n    column_category = self._getSortedBaseCategoryList(self.getQVariationBaseCategoryList())[1]\n    #LOG(\'getQColumnItemList\', 0, \"%s\" % str(column_category))\n    if column_category is None:\n      result = [(None,\'\')]\n    else:\n      result = self.getVariationRangeCategoryItemList(base_category_list = [column_category],\n                                                      display_id=display_id,\n                                                      base=base,\n                                                      current_category=current_category)\n    #LOG(\'getQColumnItemList\', 0, \"%s\" % str(result))\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getQTabItemList\')\n  def getQTabItemList(self, display_id=\'getTitle\', base=1, current_category=None):\n    \"\"\"\n        Returns a list of items which can be used as index for\n        each tab of a matrix or to define a cell range.\n    \"\"\"\n    tab_category_list = self._getSortedBaseCategoryList(self.getQVariationBaseCategoryList())[2:]\n    tab_category_item_list_list = []\n    for tab_category in tab_category_list:\n      tab_category_item_list = self.getVariationRangeCategoryItemList(base_category_list = [tab_category],\n                                                                      display_id=display_id,\n                                                                      base=base,\n                                                                      current_category=current_category)\n      tab_category_item_list_list.append(tab_category_item_list)\n    transformation = self.getParentValue()\n    transformation_category_item_list = transformation.getVariationCategoryItemList(\n                                                        display_id=display_id,\n                                                        base=base,\n                                                        current_category=current_category)\n    tab_category_item_list_list.append(transformation_category_item_list)\n    if len(tab_category_item_list_list) > 0:\n      product_list = cartesianProduct(tab_category_item_list_list)\n      result = []\n      for item_list in product_list:\n        value_list = []\n        label_list = []\n        for item in item_list:\n          value_list.append(item[0])\n          label_list.append(item[1])\n        result.append((value_list, label_list))\n    else:\n      result = [(None,\'\')]\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getVLineItemList\')\n  def getVLineItemList(self):\n    base_category = self.getParentValue().getVariationBaseCategoryLine()\n    if base_category in self.getVVariationBaseCategoryList():\n      clist = self.getParentValue().getCategoryMembershipList(base_category, base=1)\n    else:\n      clist = [None]\n    result = []\n    for c in clist:\n      result += [(c,c)]\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getVColumnItemList\')\n  def getVColumnItemList(self):\n    base_category = self.getParentValue().getVariationBaseCategoryColumn()\n    if base_category in self.getVVariationBaseCategoryList():\n      clist = self.getParentValue().getCategoryMembershipList(base_category, base=1)\n    else:\n      clist = [None]\n    result = []\n    for c in clist:\n      result += [(c,c)]\n\n    result.sort() # XXX Temp until set / list issue solved\n\n    return result\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getVTabItemList\')\n  def getVTabItemList(self):\n    transformation = self.getParentValue()\n    line_id = transformation.getVariationBaseCategoryLine()\n    column_id = transformation.getVariationBaseCategoryColumn()\n    base_category_list = transformation.getVariationBaseCategoryList()\n    base_category = []\n    for c in base_category_list:\n      if not c in (line_id, column_id):\n        if c in self.getVVariationBaseCategoryList():\n          base_category += [transformation.getCategoryMembershipList(c, base=1)]\n    if len(base_category) > 0:\n      clist = cartesianProduct(base_category)\n      result = []\n      for c in clist:\n        result += [(c,c)]\n    else:\n      result = [(None,\'\')]\n\n    result.sort() # XXX Temp until set / list issue solved\n\n    return result\n\n  security.declareProtected( Permissions.ModifyPortalContent, \'newCell\' )\n  def newCell(self, *kw, **kwd):\n    result = XMLMatrix.newCell(self, *kw, **kwd)\n    result._setPredicateOperator(\"SUPERSET_OF\")\n    membership_list = []\n    for c in kw:\n      if c is not None:\n        membership_list += [c]\n    result._setPredicateValueList(membership_list)\n    base_id = kwd.get(\'base_id\', \'cell\')\n    if base_id == \'quantity\':\n      result._setDomainBaseCategoryList(self.getQVariationBaseCategoryList())\n    elif base_id == \'variation\':\n      result._setDomainBaseCategoryList(self.getVVariationBaseCategoryList())\n\n    return result\n\n  security.declareProtected( Permissions.ModifyPortalContent, \'newCellContent\' )\n  def newCellContent(self, id, portal_type=\'Set Mapped Value\', **kw): # pylint: disable=redefined-builtin\n    \"\"\"Overriden to specify default portal type\n    \"\"\"\n    return self.newContent(id=id, portal_type=portal_type, **kw)\n\n  security.declarePrivate(\'_checkConsistency\')\n  def _checkConsistency(self, fixit=0):\n    \"\"\"\n        Check the constitency of transformation elements\n    \"\"\"\n    transformation = self.getParentValue()\n    transformation_category_list = transformation.getVariationCategoryList()\n\n    error_list = XMLMatrix._checkConsistency(self, fixit=fixit)\n\n    # Quantity should be empty if no variation\n    q_range = self.getCellRange(base_id = \'quantity\')\n    if q_range is not None:\n      range_is_empty = 1\n      for q_list in q_range:\n        if q_list is not None:\n          range_is_empty = 0\n          break\n      if range_is_empty:\n        matrix_is_not_empty = 0\n        for k in self.getCellIds(base_id = \'quantity\'):\n          if hasattr(self, k):matrix_is_not_empty = 1\n        if matrix_is_not_empty:\n          if fixit:\n            self.delCells(base_id = \'quantity\')\n            error_message =  \"Variation cells for quantity should be empty (fixed)\"\n          else:\n            error_message =  \"Variation cells for quantity should be empty\"\n          error_list += [(self.getRelativeUrl(),\n                        \'TransformedResource inconsistency\', 100, error_message)]\n\n    # First quantity\n    # We build an attribute equality and look at all cells\n    q_constraint = Constraint.AttributeEquality(\n      domain_base_category_list = self.getQVariationBaseCategoryList(),\n      predicate_operator = \'SUPERSET_OF\',\n      mapped_value_property_list = [\'quantity\'] )\n    for kw in self.getCellKeys(base_id = \'quantity\'):\n      kwd={\'base_id\': \'quantity\'}\n      c = self.getCell(*kw, **kwd)\n      if c is not None:\n        predicate_value_list = []\n        categories_list = []\n        for p in kw:\n          if p is not None:\n            if p in transformation_category_list:\n              if p not in predicate_value_list:\n                predicate_value_list.append(p)\n            else:\n              if p not in categories_list:\n                categories_list.append(p)\n        q_constraint.edit(predicate_value_list = predicate_value_list,\n                          categories_list = categories_list)\n        if fixit:\n          error_list += q_constraint.fixConsistency(c)\n        else:\n          error_list += q_constraint.checkConsistency(c)\n\n    return error_list\n\