   duration = 0.0\n      is_variated_quantity = 0 # The variated quantity is 0 by default\n      # Try to update some attributes based on the resource attributes\n      if resource.hasDefaultBasePrice():\n        base_price = resource.getBasePrice()\n        try:\n          base_price = float(base_price)\n        except TypeError:\n          base_price = 0.0\n          error_list += [\"Default base price could not be converted for resource %s\" % resource_id]\n      if resource.hasSourceBasePrice():\n        source_base_price = resource.getSourceBasePrice()\n        try:\n          source_base_price = float(source_base_price)\n        except TypeError:\n          source_base_price = 0.0\n          error_list += [\"Source base price could not be converted for resource %s\" % resource_id]\n      resource_quantity_unit = resource.getDefaultQuantityUnit()\n      # This is very dirty and we must do some real unit conversion here XXXXXXX\n      if quantity_unit == \"Temps/Minute\":\n        duration = quantity\n      # Now, let us update variations and quantities\n      # We will browse the mapped values and dermine which apply\n      for mapped_value in self.objectValues():\n        if mapped_value.test(REQUEST):\n          # Start filing the value holder with what we have now\n          # Maybe we should define a ValueHolder class XXXXXXXXXXXXXXXXXXXXXX\n          # First we create a object which id is the id of this assorted resource\n          line_item = TempBase(self.id)\n          # We are going to try to find which variation applies to the current REQUEST\n          # First we initialize variation to the default variation value define by\n          # the transformed resource\n          variation = self.getVariationCategoryList()\n          variation_base_category_list = resource.getVariationBaseCategoryList()\n          self.portal_categories.setCategoryMembership(line_item,\n                                  variation_base_category_list, variation, base=1)\n          # and update the price with the variation price if necessary\n          for resource_variation in self.getValueList(\n                              variation_base_category_list, portal_type=self.getPortalVariationTypeList()):\n            if resource_variation.hasDefaultBasePrice():\n              new_base_price = resource_variation.getBasePrice()\n              try:\n                new_base_price = float(new_base_price)\n              except TypeError:\n                new_base_price = 0.0\n                error_list += [\"Default base price could not be converted for resource variation %s\"\n                    % resource_variation.id]\n              if new_base_price > 0.0:\n                base_price = new_base_price\n                line_item.base_price_defined_by = resource_variation.getId()\n              new_source_base_price = resource_variation.getSourceBasePrice()\n            if resource_variation.hasSourceBasePrice():\n              try:\n                new_source_base_price = float(new_source_base_price)\n              except TypeError:\n                new_source_base_price = 0.0\n                error_list += [\"Source base price could not be converted for resource variation %s\"\n                      % resource_variation.id]\n              if new_source_base_price > 0.0:\n                source_base_price = new_source_base_price\n                line_item.source_base_price_defined_by = resource_variation.getId()\n          # and then call edit to update its attributed\n          # XXXXXXXXXXXXX bad: this call will call reindex() which is not needed at all\n          # How can we create standard objects which are temporary and not indexed ???\n          #LOG(\"Quantity Unit\", 0, str(quantity_unit))\n          #LOG(\"Quantity Unit\", 0, str(resource))\n          line_item.edit(\n              transformation = transformation,\n              transformed_resource = self,\n              resource = resource,\n              transformation_id = transformation.getId(),\n              resource_id = resource.getId(),\n              resource_relative_url = resource.getRelativeUrl(),\n              specialise_id = transformation.getId(),\n              specialise_relative_url = transformation.getRelativeUrl(),\n              description =  self.getDescription(),\n              quantity_unit = quantity_unit,\n              duration = duration,\n              quantity = quantity,\n              efficiency = efficiency,\n              base_price = base_price,\n              source_base_price = source_base_price,\n              total_source_base_price = 0.0,\n              total_base_price = 0.0,\n              total_duration = 0.0,\n              base_price_defined_by = \'\',\n              source_base_price_defined_by = \'\',\n              quantity_defined_by = \'\',\n              variation_defined_by = \'\',\n              resource_quantity_unit = resource_quantity_unit\n            )\n          # Update attributes defined by the mapped value\n          for attribute in mapped_value.getMappedValuePropertyList():\n            setattr(line_item, attribute, mapped_value.get(attribute))\n            if attribute == \'quantity\':\n              line_item.quantity_defined_by = mapped_value.getId()\n              # If we have to do this, then there is a problem....\n              # We\'d better have better API for this, like an update function in the mapped_value\n              try:\n                quantity = float(mapped_value.quantity)\n                is_variated_quantity = 1 # The variated quantity is 1\n                #                          when the quantity is defined by a variation matrix\n              except TypeError:\n                error_list += [\"Quantity defined by %s is not a float\" % mapped_value.id]\n          # Update categories defined by the mapped value\n          base_category_list = mapped_value.getMappedValueBaseCategoryList()\n          if len(base_category_list) > 0:\n            line_item.variation_defined_by = mapped_value.getId()\n            self.portal_categories.setCategoryMembership(line_item, base_category_list,\n                    mapped_value.getCategoryMembershipList(base_category_list, base=1), base=1)\n            for resource_variation in mapped_value.getValueList(base_category_list,\n                                                                portal_type=self.getPortalVariationTypeList()):\n              if resource_variation.hasDefaultBasePrice():\n                new_base_price = resource_variation.getBasePrice()\n                try:\n                  new_base_price = float(new_base_price)\n                except TypeError:\n                  new_base_price = 0.0\n                  error_list += \\\n                      [\"Default base price could not be converted for resource variation %s\"\n                                                            % resource_variation.id]\n                if new_base_price > 0.0:\n                  base_price = new_base_price\n                  line_item.base_price_defined_by = resource_variation.getId()\n              if resource_variation.hasSourceBasePrice():\n                new_source_base_price = resource_variation.getSourceBasePrice()\n                try:\n                  new_source_base_price = float(new_source_base_price)\n                except TypeError:\n                  new_source_base_price = 0.0\n                  error_list += \\\n                      [\"Source base price could not be converted for resource variation %s\"\n                                                            % resource_variation.id]\n                if new_source_base_price > 0.0:\n                  source_base_price = new_source_base_price\n                  line_item.source_base_price_defined_by = resource_variation.getId()\n          # Convert Quantities\n          converted_quantity = resource.convertQuantity(quantity, quantity_unit,\n                                                                  resource_quantity_unit)\n          try:\n            converted_quantity = float(converted_quantity)\n          except TypeError:\n            converted_quantity = 0.0\n            error_list += [\"Quantity could not be converted for resource %s\" % resource.id]\n          # Convert price to unit price\n          unit_base_price = base_price / priced_quantity\n          unit_source_base_price = source_base_price / priced_quantity\n          variation = self.portal_categories.getCategoryMembershipList(line_item,\n                                                variation_base_category_list, base=1)\n          total_base_price = converted_quantity * unit_base_price / efficiency\n          total_source_base_price = converted_quantity * unit_source_base_price / efficiency\n          # Define variated price\n          if is_variated_quantity:\n            total_variated_base_price = total_base_price\n            total_variated_source_base_price = total_source_base_price\n          else:\n            total_variated_base_price = 0.0\n            total_variated_source_base_price = 0.0\n          # Create a nice presentation of the variation\n          pretty_variation = \'\'\n          for variation_item in variation:\n            pretty_variation += \"<br>%s\" % str(variation_item)\n          # Update the value and calculate total\n          line_item.edit(\n            converted_quantity = converted_quantity,\n            base_price = base_price,\n            unit_base_price = unit_base_price,\n            total_base_price = total_base_price,\n            source_base_price = source_base_price,\n            unit_source_base_price = unit_source_base_price,\n            total_source_base_price = total_source_base_price,\n            variation = variation,\n            variation_category_list = variation,\n            quantity = quantity,\n            pretty_variation = pretty_variation,\n            error_list = error_list\n          )\n          line_item_list.append(line_item)\n          total_base_price_list.append(total_base_price)\n          total_source_base_price_list.append(total_source_base_price)\n          total_variated_base_price_list.append(total_variated_base_price)\n          total_variated_source_base_price_list.append(total_variated_source_base_price)\n      return line_item_list, \\\n            reduce(operator.add, total_base_price_list, 0), \\\n            reduce(operator.add, total_source_base_price_list, 0), \\\n            reduce(operator.add, total_variated_base_price_list, 0), \\\n            reduce(operator.add, total_variated_source_base_price_list, 0), \\\n            duration\n\"\"\"'),(4829,'Transition timestamp'),(4830,'Portal type (used as filter for worklists)'),(4831,'Provides access to workflow history'),(4832,'Error message if validation failed'),(4833,'Comment about transition'),(4834,'Name of the user who performed transition'),(4835,'Transition id'),(4836,'ShowAction'),(4837,'Show'),(4838,'HideAction'),(4839,'Hide'),(4840,'DeleteAction'),(4841,'Delete'),(4842,'Visible'),(4843,'Hidden'),(4844,'Deleted Documents in this state were deleted by the user as a result of clicking on the trash button or calling the delete action'),(4845,'Visibility Workflow visibility_workflow'),(4848,'Transformation Interaction Workflow transformation_interaction_workflow'),(4868,'Supply Line Interaction Workflow supply_line_interaction_workflow'),(4871,'Supply Cell Interaction Workflow supply_cell_interaction_workflow'),(4877,'Reindex resource after Transformation edit When a new Line is added, or when Variations are changed.'),(4878,'Reindex old and new resources when changing the target resource'),(4880,'invalidate Universal cache after object invalidation'),(4881,'Update related resources Update parent Resource after changing local Quantity Unit Conversion Definition, or update all Resources that define a Local Quantity Unit Conversion Definition when a Global Quantity Unit Conversion Definition is modified.'),(4883,'Interaction Workflow Definition conversion_interaction_workflow'),(4885,'erp5_pdm ERP5 Product Data Management'),(4905,'Start'),(4913,'Submit'),(4915,'Stop Form'),(4921,'Wizard Field Library'),(4927,'Launch Configuration'),(4931,'Configutator Settings'),(4934,'Configurator Settings'),(4938,'Spreadsheet Configuration'),(4943,'Configuration Item'),(4949,'Configuration Save'),(4959,'Business Configuration'),(4966,'Ready'),(4968,'Business Configurations'),(5001,'Configurator Field Library'),(5003,'Business Configurations'),(5004,'Current State'),(5005,'System Preference Configurator Item  Setup an Accounting Account.'),(5006,'Standard BT5 Configurator Item  This class will install standard ERP5 template from a repository to\n  fake site.'),(5007,'Solver Configurator Item'),(5008,'Site Property Configurator Item Set up site properties.'),(5009,'Service Configurator Item Set up default service documents.'),(5010,'Security Category Mapping Configurator Item  Setup an Alarm'),(5011,'Sale Trade Condition Configurator Item'),(5012,'Rule Configurator Item'),(5013,'Role Configurator Item  Setup role per module basis.'),(5014,'Purchase Trade Condition Configurator Item'),(5015,'Preference Configurator Item  Setup preference. \n      XXX: also configure oood'),(5016,'Portal Type Roles Spreadsheet Configurator Item Import a portal type roles spreadsheet.'),(5017,'Portal Type Configurator Item Configure Portal Type.'),(5018,'Person Configurator Item  Setup user.'),(5019,'Permission Configurator Item  Set permission matrix on module.'),(5020,'Organisation Configurator Item  This class install a Organisation.'),(5021,'Customer BT5 Configurator Item  Create a new bt5 for customer configuration.'),(5022,'Currency Configurator Item  Setup currency.'),(5023,'Configurator Tool'),(5024,'Configuration Save Save parameters entered by the user during the configurator process.'),(5025,'Category Configurator Item This class is meta build step for customization of ERP5 site.'),(5026,'Categories Spreadsheet Configurator Item Setup Categories Spreadsheet'),(5027,'Catalog Keyword Key Configurator Item Set up catalog keyword keys.'),(5028,'Business Process Configurator Item'),(5029,'Business Configuration Module Folders allow to store a large number of documents (1,000,000 should not\nbe a problem).'),(5030,'Business Configuration Business Configuration is used to represent the highest level of configuration of \"something\" - like ERP5 Site. Additional documents (deliveries) are used to \"glue\" all information together.'),(5031,'Bank Account Configurator Item  Setup a Bank Account'),(5032,'Alarm Configurator Item  Setup an Alarm'),(5033,'Advanced Sale Trade Condition Configurator Item A bank account number holds a collection of numbers and codes (ex. SWIFT, RIB, etc.) which may be used to identify a bank account. It is owned by a Person or an Organisation. A Bank Account contains Agents with Agent Privileges used by the owner to delegate the management of the bank account to trusted third-party Persons.\n\nBankAccount inherits from Base and from the mix-in Coordinate.'),(5034,'Advanced Purchase Trade Condition Configurator Item A bank account number holds a collection of numbers and codes (ex. SWIFT, RIB, etc.) which may be used to identify a bank account. It is owned by a Person or an Organisation. A Bank Account contains Agents with Agent Privileges used by the owner to delegate the management of the bank account to trusted third-party Persons.\n\nBankAccount inherits from Base and from the mix-in Coordinate.'),(5035,'Accounting Period Configurator Item  Setup an Accounting Period.'),(5036,'Account Configurator Item  Setup an Accounting Account.'),(5037,'Configurations'),(5038,'test.erp5.testConfiguratorTool testConfiguratorTool ##############################################################################\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                     Lucas Carvalho <lucas@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\n\nfrom AccessControl import Unauthorized\nfrom erp5.component.module.ConfiguratorTestMixin import \\\n                                             TestLiveConfiguratorWorkflowMixin\n\n\nclass TestConfiguratorTool(TestLiveConfiguratorWorkflowMixin):\n  \"\"\"\n    Test the Configurator Tool\n  \"\"\"\n\n  def getBusinessTemplateList(self):\n    return (\'erp5_core_proxy_field_legacy\',\n            \'erp5_full_text_mroonga_catalog\',\n            \'erp5_base\',\n            \'erp5_configurator\',\n            \'erp5_configurator_standard\',)\n\n  def test_anonymous_can_not_view_configurator_tool(self):\n    \"\"\"\n      The Anonymous user can not have access to view the Configurator Tool.\n    \"\"\"\n    checkPermission = self.portal.portal_membership.checkPermission\n    configurator_tool = self.portal.portal_configurator\n    self.logout()\n    self.assertEqual(None, checkPermission(\'View\', configurator_tool))\n    self.assertRaises(Unauthorized, configurator_tool)'),(5039,'test.erp5.testConfiguratorItem testConfiguratorItem ##############################################################################\n# Copyright (c) 2012 Nexedi SA and Contributors. All Rights Reserved.\n#                     Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\n\nimport uuid\nfrom DateTime import DateTime\nfrom Products.ERP5Type.tests.utils import createZODBPythonScript\nfrom erp5.component.module.ConfiguratorTestMixin import \\\n                                             TestLiveConfiguratorWorkflowMixin\n\nfrom Products.ERP5 import tests as test_folder\n\nclass TestConfiguratorItem(TestLiveConfiguratorWorkflowMixin):\n  \"\"\"\n    Test the Configurator Tool\n  \"\"\"\n\n  def getBusinessTemplateList(self):\n    return (\'erp5_core_proxy_field_legacy\',\n            \'erp5_full_text_mroonga_catalog\',\n            \'erp5_base\',\n            \'erp5_configurator\',\n            \'erp5_simulation\',\n            \'erp5_pdm\',\n            \'erp5_trade\',\n            \'erp5_accounting\',\n            \'erp5_configurator_standard_trade_template\')\n\n  def createConfigurationSave(self):\n    \"\"\" Create a Business Configuration and a Configuration Save\n    \"\"\"\n    bc = self.portal.business_configuration_module.newContent()\n    return bc.newContent(portal_type=\"Configuration Save\")\n\n\n  def newUniqueUID(self):\n    \"\"\" Return a unique number id\"\"\"\n    return str(uuid.uuid1())\n\n  def testOrganisationConfiguratorItem(self):\n    \"\"\"\n      The Anonymous user can not have access to view the Configurator Tool.\n    \"\"\"\n    configuration_save = self.createConfigurationSave()\n\n    group_id = \"some_group\"\n\n    title = \"test_%s\" % self.newUniqueUID()\n    kw = { \'title\': title,\n           \'corporate_name\': \"test_corporate_name\",\n           \'default_address_city\': \'test_default_address_city\',\n           \'default_email_text\': \'test_default@emailtext.com\',\n           \'default_telephone_text\': \'+55(0)22-123456789\',\n           \'default_address_zip_code\': \'test_default_address_zip_code\',\n           \'default_address_region\': \'test_default_address_region\',\n           \'default_address_street_address\': \'test_default_address_street_address\',\n         }\n\n\n    item = configuration_save.addConfigurationItem(\n      \"Organisation Configurator Item\",\n      group=group_id, site=\'main\', **kw)\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    organisation = self.portal.portal_catalog.getResultValue(\n                       portal_type=\"Organisation\",\n                       title = title)\n\n    self.assertNotEqual(organisation, None)\n\n    self.assertEqual(group_id, organisation.getGroup())\n    self.assertEqual(kw[\'title\'], organisation.getTitle())\n    self.assertEqual(kw[\'corporate_name\'], organisation.getCorporateName())\n    self.assertEqual(kw[\'default_address_city\'],\n                      organisation.getDefaultAddressCity())\n    self.assertEqual(kw[\'default_email_text\'],\n                      organisation.getDefaultEmailText())\n    self.assertEqual(kw[\'default_telephone_text\'],\n                      organisation.getDefaultTelephoneText())\n    self.assertEqual(kw[\'default_address_zip_code\'],\n                      organisation.getDefaultAddressZipCode())\n    self.assertEqual(kw[\'default_address_region\'],\n                      organisation.getDefaultAddressRegion())\n\n    self.assertEqual(kw[\'default_address_street_address\'],\n                      organisation.getDefaultAddressStreetAddress())\n\n    self.assertEqual(\'main\', organisation.getSite())\n    self.assertEqual(\'validated\', organisation.getValidationState())\n\n\n  def testCategoryConfiguratorItem(self):\n    \"\"\" Test Category Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n\n    category_id_0 = \"test_category_%s\" % self.newUniqueUID()\n    item0 = configuration_save.addConfigurationItem(\n                                        \"Category Configurator Item\",\n                                        category_root=\'group\',\n                                        object_id=category_id_0,\n                                        title=\"title_%s\" % category_id_0)\n\n    category_id_1 = \"test_category_%s\" % self.newUniqueUID()\n    item1 = configuration_save.addConfigurationItem(\n                                        \"Category Configurator Item\",\n                                        category_root=\'group\',\n                                        object_id=category_id_1,\n                                        title=\"title_%s\" % category_id_1)\n\n    self.tic()\n    item0.fixConsistency()\n    self.tic()\n\n    category_0 = getattr(self.portal.portal_categories.group, category_id_0, None)\n    self.assertNotEqual(category_0, None)\n    self.assertEqual(category_0.getTitle(), \"title_%s\" % category_id_0)\n\n    category_1 = getattr(self.portal.portal_categories.group, category_id_1, None)\n    self.assertEqual(category_1, None)\n\n    item1.fixConsistency()\n    self.tic()\n\n    category_1 = getattr(self.portal.portal_categories.group, category_id_1, None)\n    self.assertNotEqual(category_1, None)\n    self.assertEqual(category_1.getTitle(), \"title_%s\" % category_id_1)\n\n    # recreate category_1 with new title\n\n    item2 = configuration_save.addConfigurationItem(\n                                        \"Category Configurator Item\",\n                                        category_root=\'group\',\n                                        object_id=category_id_1,\n                                        title=\"new_title_%s\" % category_id_1)\n\n    item2.fixConsistency()\n    self.tic()\n\n    category_1 = getattr(self.portal.portal_categories.group,\n                         category_id_1, None)\n    self.assertNotEqual(category_1, None)\n    self.assertEqual(category_1.getTitle(), \"new_title_%s\" % category_id_1)\n\n  def testCurrencyConfiguratorItem(self):\n    \"\"\" Test Category Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n\n    eur_currency_id = \"EUR\"\n    eur_currency_title = \"Euro\"\n    item_eur = configuration_save.addConfigurationItem(\n                             \"Currency Configurator Item\",\n                             reference = eur_currency_id,\n                             base_unit_quantity = 0.01,\n                             title = eur_currency_title,)\n\n    brl_currency_id = \"BRL\"\n    brl_currency_title = \"Brazillian Real\"\n    item_brl = configuration_save.addConfigurationItem(\n                             \"Currency Configurator Item\",\n                             reference = brl_currency_id,\n                             base_unit_quantity = 0.01,\n                             title = brl_currency_title,)\n\n    self.tic()\n\n    item_eur.fixConsistency()\n    self.tic()\n\n    eur = getattr(self.portal.currency_module, eur_currency_id , None)\n    self.assertNotEqual(eur, None)\n    self.assertEqual(eur.getTitle(), eur_currency_title)\n\n    brl = getattr(self.portal.currency_module, brl_currency_id , None)\n    self.assertEqual(brl, None)\n\n    item_brl.fixConsistency()\n    self.tic()\n\n    brl = getattr(self.portal.currency_module, brl_currency_id , None)\n    self.assertNotEqual(brl, None)\n    self.assertEqual(brl.getTitle(), brl_currency_title)\n\n    # Build several times to not break portal.\n\n    item_brl.fixConsistency()\n    self.tic()\n    item_brl.fixConsistency()\n    self.tic()\n\n  def testSecurityCategoryMappingConfiguratorItem(self):\n    \"\"\" Test Security Category Mapping Configurator Item\n        XXX This test and the Security Category Mapping should be improved to\n            allow provide the name of skin folder and the script/categories to\n            be used for the script oucome. For now it does the minimum.\n    \"\"\"\n    configuration_save = self.createConfigurationSave()\n\n    expect_script_outcome = (\n           (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'function\']),\n           (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'follow_up\']),\n           (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'function\', \'follow_up\']),\n           (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'group\']),\n           (\'ERP5Type_getSecurityCategoryRoot\', [\'group\']),)\n\n\n    item = configuration_save.addConfigurationItem(\n                  \"Security Category Mapping Configurator Item\")\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    # XXX Skin folder should be part of configuration and not always custom\n    security_script = getattr(self.portal.portal_skins.custom,\n                              \"ERP5Type_getSecurityCategoryMapping\", None)\n\n    self.assertNotEqual(None, security_script)\n    self.assertEqual(security_script(), expect_script_outcome)\n\n  def testAccountConfiguratorItem(self):\n    \"\"\" Test Account Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n    account_module = self.portal.account_module\n\n    account_dict = {\n             \'account_type\': \'asset/receivable\',\n             \'account_id\': \'receivable\',\n             \'title\': \'Customers\',\n             \'gap\': \'ias/ifrs/4/41\',\n             \'financial_section\': \'asset/current_assets/trade_receivables\'}\n\n    item = configuration_save.addConfigurationItem(\n                  \"Account Configurator Item\", **account_dict)\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    account = getattr(account_module, account_dict[\'account_id\'], None)\n    self.assertNotEqual(account, None)\n    self.assertEqual(account.getTitle(), account_dict[\'title\'])\n    self.assertEqual(account.getGap(), account_dict[\'gap\'])\n    self.assertEqual(account.getFinancialSection(),\n                      account_dict[\'financial_section\'])\n    self.assertEqual(account.getAccountType(),\n                      account_dict[\'account_type\'])\n\n    # Update Account dict and try to create again the same account,\n    # the account should be only updated instead a new account be created.\n    account_dict[\'title\'] = \'Clientes\'\n    previous_gap = account_dict[\'gap\']\n    account_dict[\'gap\'] = \'br/pcg/1/1.1/1.1.2\'\n\n    item = configuration_save.addConfigurationItem(\n                  \"Account Configurator Item\", **account_dict)\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    same_account = getattr(account_module, account_dict[\'account_id\'], None)\n    self.assertEqual(account, same_account)\n    self.assertEqual(account.getTitle(), account_dict[\'title\'])\n    self.assertSameSet(account.getGapList(), [previous_gap,\n                                              account_dict[\'gap\']])\n    self.assertEqual(account.getFinancialSection(),\n                      account_dict[\'financial_section\'])\n    self.assertEqual(account.getAccountType(),\n                      account_dict[\'account_type\'])\n\n  def testAlarmConfiguratorItem(self):\n    \"\"\" Test Alarm Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n\n    property_map = {\n      \"active_sense_method_id\" : \"Base_setDummy\",\n      \"periodicity_hour_list\" : [5, 6],\n      \"periodicity_minute_list\": [30, 31],\n      \"periodicity_minute_frequency\": 5,\n      \"periodicity_month_list\": [1, 2],\n      \"periodicity_month_day_list\": [3, 4],\n      \"periodicity_week_list\": [6, 7],\n                        }\n\n    item = configuration_save.addConfigurationItem(\n                  \"Alarm Configurator Item\",\n                  id=\"my_test_alarm\",\n                  title=\"My Test Alarm\",\n                  **property_map)\n\n    createZODBPythonScript(self.getPortal().portal_skins.custom,\n                                    property_map[\"active_sense_method_id\"],\n                                    \"\", \"context.setEnabled(0)\")\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    alarm = getattr(self.portal.portal_alarms, \"my_test_alarm\", None)\n    self.assertNotEqual(None, alarm)\n\n    self.assertEqual(alarm.getEnabled(), True)\n    self.assertEqual(alarm.getTitle(), \"My Test Alarm\")\n    self.assertEqual(alarm.getPeriodicityMinuteFrequency(),\n                      property_map[\"periodicity_minute_frequency\"])\n    self.assertEqual(alarm.getPeriodicityMonthList(),\n                      property_map[\"periodicity_month_list\"])\n    self.assertEqual(alarm.getPeriodicityMonthDayList(),\n                      property_map[\"periodicity_month_day_list\"])\n    self.assertEqual(alarm.getPeriodicityHourList(),\n                      property_map[\"periodicity_hour_list\"])\n    self.assertEqual(alarm.getPeriodicityHourList(),\n                      property_map[\"periodicity_hour_list\"])\n    self.assertEqual(alarm.getActiveSenseMethodId(),\n                      property_map[\"active_sense_method_id\"])\n    self.assertNotEqual(alarm.getPeriodicityStartDate(), None)\n    self.assertTrue(alarm.getPeriodicityStartDate() < DateTime())\n    alarm.activeSense()\n    self.tic()\n    self.assertEqual(alarm.getEnabled(), 0)\n\n  def testPortalTypeRolesSpreadsheetConfiguratorItem(self):\n    \"\"\" Test Portal Type Roles Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n    category_tool = self.portal.portal_categories\n\n    test_folder_path = \'/\'.join(test_folder.__file__.split(\'/\')[:-1])\n\n    with open(\n      \"%s/test_data/test_standard_portal_type_roles.ods\" % test_folder_path, \"rb\") as f:\n      data = f.read()\n\n    if getattr(category_tool.group, \"my_group\", None) is None:\n      category_tool.group.newContent(id=\"my_group\")\n\n    item = configuration_save.addConfigurationItem(\n      \"Portal Type Roles Spreadsheet Configurator Item\",\n      configuration_spreadsheet_data = data)\n\n\n    person_type = self.portal.portal_types[\"Person\"]\n    person_module_type = self.portal.portal_types[\"Person Module\"]\n\n    role_list = [i for i in person_type.objectValues(\n                 portal_type=\"Role Information\")\n                 if i.getTitle() == \"TestRole_Person\"]\n\n    if len(role_list) > 0:\n      person_type.manage_delObjects([i.id for i in role_list])\n\n    role_list = [i for i in person_module_type.objectValues(\n                 portal_type=\"Role Information\")\n                if i.getTitle() == \"TestRole_PersonModule\"]\n\n    if len(role_list) > 0:\n      person_module_type.manage_delObjects([i.id for i in role_list])\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    role_list = [i for i in person_type.objectValues(\n                 portal_type=\"Role Information\")\n                if i.getTitle() == \"TestRole_Person\"]\n\n    self.assertEqual(len(role_list), 1)\n\n    self.assertEqual(role_list[0].getDescription(),\n                      \"Configured by ERP5 Configurator\")\n\n    self.assertEqual(role_list[0].getRoleNameList(),\n                      [\'Auditor\', \'Author\', \'Assignee\'])\n\n    self.assertEqual(role_list[0].getRoleCategoryList(),\n                      [\'group/my_group\',])\n\n\n    role_list = [i for i in person_module_type.objectValues(\n                 portal_type=\"Role Information\")\n                if i.getTitle() == \"TestRole_PersonModule\"]\n\n    self.assertEqual(len(role_list), 1)\n\n    self.assertEqual(role_list[0].getDescription(),\n                      \"Configured by ERP5 Configurator\")\n\n    self.assertEqual(role_list[0].getRoleNameList(),\n                      [\'Auditor\', \'Author\'])\n\n    self.assertEqual(role_list[0].getRoleCategoryList(),\n                      [\'group/my_group\',])\n\n\n  def testCategoriesSpreadsheetConfiguratorItem(self):\n    \"\"\" Test Portal Type Roles Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n    category_tool = self.portal.portal_categories\n\n    test_folder_path = \'/\'.join(test_folder.__file__.split(\'/\')[:-1])\n\n    with open(\"%s/test_data/test_standard_categories.ods\" \\\n               % test_folder_path, \"rb\") as f:\n      data = f.read()\n\n    item = configuration_save.addConfigurationItem(\n      \"Categories Spreadsheet Configurator Item\",\n      configuration_spreadsheet_data = data)\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    base_category_list = [\"group\", \"site\", \"business_application\",\n                          \"function\", \"region\"]\n\n    for base_category_id in base_category_list:\n      # Check first Level\n      base_category = getattr(category_tool, base_category_id)\n      my_test = getattr(base_category, \"my_test\", None)\n      self.assertNotEqual(my_test, None)\n      self.assertEqual(my_test.getTitle(), \"TEST\")\n      self.assertEqual(my_test.getDescription(), \"TEST\")\n      self.assertEqual(my_test.getCodification(), \"TEST\")\n      self.assertEqual(my_test.getIntIndex(), 1)\n      # Check Second level\n      my_test = getattr(my_test, \"my_test\", None)\n      self.assertNotEqual(my_test, None)\n      self.assertEqual(my_test.getTitle(), \"TEST\")\n      self.assertEqual(my_test.getDescription(), \"TEST\")\n      self.assertEqual(my_test.getCodification(), \"TEST\")\n      self.assertEqual(my_test.getIntIndex(), 2)\n\n      # Check Thrid level\n      my_test = getattr(my_test, \"my_test\", None)\n      self.assertNotEqual(my_test, None)\n      self.assertEqual(my_test.getTitle(), \"TEST\")\n      self.assertEqual(my_test.getDescription(), \"TEST\")\n      self.assertEqual(my_test.getCodification(), \"TEST\")\n      self.assertEqual(my_test.getIntIndex(), 3)\n\n  def testRuleConfiguratorItem(self):\n    \"\"\" Test Rules Configurator Item \"\"\"\n    configuration_save = self.createConfigurationSave()\n    category_tool = self.portal.portal_categories\n    rule_tool = self.portal.portal_rules\n\n    if getattr(category_tool.trade_phase, \"testing\", None) is None:\n      category_tool.trade_phase.newContent(id=\"testing\")\n\n    if getattr(category_tool.trade_phase.testing, \"order\", None) is None:\n      category_tool.trade_phase.testing.newContent(id=\"order\")\n\n    item = configuration_save.addConfigurationItem(\n      \"Rule Configurator Item\",\n      reference = \"testing_configurator_rule\",\n      id = \"rule_do_not_exist\")\n\n    self.tic()\n    self.assertRaises(ValueError, item.fixConsistency)\n\n    rule_reference = \"testing_configurator_rule_%s\" % self.newUniqueUID()\n    item = configuration_save.addConfigurationItem(\n      \"Rule Configurator Item\",\n      reference = rule_reference,\n      id = \"new_delivery_simulation_rule\",\n      trade_phase_list = [\'testing/order\'])\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    rule_list = rule_tool.searchFolder(\n          portal_type=self.portal.getPortalRuleTypeList(),\n          validation_state=\"validated\", reference=rule_reference)\n\n    self.assertEqual(len(rule_list), 1)\n    self.assertEqual([\'testing/order\'], rule_list[0].getTradePhaseList())\n\n  def testBusinessProcessConfiguratorItem(self):\n    configuration_save = self.createConfigurationSave()\n\n    test_folder_path = \'/\'.join(test_folder.__file__.split(\'/\')[:-1])\n\n    with open(\"%s/test_data/test_standard_business_process.ods\" \\\n               % test_folder_path, \"rb\") as f:\n      data = f.read()\n\n    reference = \"testing_business_process_%s\" % self.newUniqueUID()\n    item = configuration_save.addConfigurationItem(\n      \"Business Process Configurator Item\",\n      configuration_spreadsheet_data = data,\n      reference = reference)\n\n    self.tic()\n    item.fixConsistency()\n    self.tic()\n\n    business_process = self.portal.portal_catalog.getResultValue(\n          portal_type=\"Business Process\",\n          reference=reference)\n\n    self.assertNotEqual(business_process, None)\n\n    order_path = getattr(business_process, \"order_path\", None)\n    self.assertNotEqual(order_path, None)\n    self.assertEqual(order_path.getEfficiency(), 1.0)\n    self.assertEqual(order_path.getTradePhase(), \'trade/order\')\n    self.assertEqual(order_path.getTradeDate(), \'trade_phase/trade/order\')\n    self.assertEqual(order_path.getTestMethodId(), None)\n\n    delivery_path = getattr(business_process, \"delivery_path\", None)\n    self.assertNotEqual(delivery_path, None)\n    self.assertEqual(delivery_path.getEfficiency(), 1.0)\n    self.assertEqual(delivery_path.getTradePhase(), \'trade/delivery\')\n    self.assertEqual(delivery_path.getTradeDate(), \'trade_phase/trade/order\')\n    self.assertEqual(delivery_path.getTestMethodId(), None)\n\n    invoicing_path = getattr(business_process, \"invoicing_path\", None)\n    self.assertNotEqual(invoicing_path, None)\n    self.assertEqual(invoicing_path.getEfficiency(), 1.0)\n    self.assertEqual(invoicing_path.getTradePhase(), \'trade/invoicing\')\n    self.assertEqual(invoicing_path.getTradeDate(), \'trade_phase/trade/delivery\')\n    self.assertEqual(invoicing_path.getTestMethodId(), None)\n    self.assertEqual(invoicing_path.getMembershipCriterionBaseCategoryList(), [])\n    self.assertEqual(invoicing_path.getMembershipCriterionCategoryList(), [])\n\n    accounting_debit_path = getattr(business_process, \"accounting_debit_path\", None)\n    self.assertNotEqual(accounting_debit_path, None)\n    self.assertEqual(accounting_debit_path.getEfficiency(), 1.0)\n    self.assertEqual(accounting_debit_path.getTradePhase(), \'trade/accounting\')\n    self.assertEqual(accounting_debit_path.getTradeDate(), \'trade_phase/trade/invoicing\')\n    self.assertEqual(accounting_debit_path.getTestMethodId(), \"isAccountingMovementType\")\n    self.assertEqual(\n        accounting_debit_path.getMembershipCriterionBaseCategoryList(),\n        [\'trade_phase\'])\n    self.assertEqual(\n        accounting_debit_path.getMembershipCriterionCategoryList(),\n        [\'trade_phase/trade/invoicing\', \'trade_phase/trade/delivery\',])\n\n    accounting_credit_path = getattr(business_process, \"accounting_credit_path\", None)\n    self.assertNotEqual(accounting_credit_path, None)\n    self.assertEqual(accounting_credit_path.getEfficiency(), -1.0)\n    self.assertEqual(accounting_credit_path.getTradePhase(), \'trade/accounting\')\n    self.assertEqual(accounting_credit_path.getTradeDate(), \'trade_phase/trade/invoicing\')\n    self.assertEqual(accounting_credit_path.getTestMethodId(), \"isAccountingMovementType\")\n    self.assertEqual(\n        accounting_credit_path.getMembershipCriterionBaseCategoryList(),\n        [\'trade_phase\'])\n    self.assertEqual(\n        accounting_credit_path.getMembershipCriterionCategoryList(),\n        [\'trade_phase/trade/delivery\',])\n\n    order_link = getattr(business_process, \"order_link\", None)\n    self.assertNotEqual(order_link, None)\n    #self.assertTrue(order_link.getDeliverable())\n    self.assertEqual(order_link.getSuccessor(), \"trade_state/trade/ordered\")\n    self.assertEqual(order_link.getPredecessor(),None)\n    self.assertEqual(order_link.getCompletedStateList(),[\"confirmed\"])\n    self.assertEqual(order_link.getFrozenState(), None)\n    self.assertEqual(order_link.getDeliveryBuilder(), None)\n    self.assertEqual(order_link.getTradePhase(),\'trade/order\')\n\n    deliver_link = getattr(business_process, \"deliver_link\", None)\n    self.assertNotEqual(deliver_link, None)\n    #self.assertTrue(deliver_link.getDeliverable())\n    self.assertEqual(deliver_link.getSuccessor(),\"trade_state/trade/delivered\")\n    self.assertEqual(deliver_link.getPredecessor(),\"trade_state/trade/ordered\")\n    self.assertEqual(deliver_link.getCompletedStateList(),[\'delivered\',\'started\',\'stopped\'])\n    self.assertEqual(deliver_link.getFrozenStateList(),[\'delivered\',\'stopped\'])\n    self.assertEqual(deliver_link.getTradePhase(),\'trade/delivery\')\n\n    self.assertEqual(deliver_link.getDeliveryBuilderList(),\n           [\"portal_deliveries/sale_packing_list_builder\",\n            \"portal_deliveries/internal_packing_list_builder\",\n            \"portal_deliveries/purchase_packing_list_builder\"])\n\n    invoice_link = getattr(business_process, \"invoice_link\", None)\n    self.assertNotEqual(invoice_link, None)\n    #self.assertFalse(invoice_link.getDeliverable())\n    self.assertEqual(invoice_link.getSuccessor(),\"trade_state/trade/invoiced\")\n    self.assertEqual(invoice_link.getPredecessor(),\"trade_state/trade/delivered\")\n    self.assertEqual(invoice_link.getCompletedStateList(),\n                        [\'confirmed\',\'delivered\',\'started\',\'stopped\'])\n    self.assertEqual(invoice_link.getFrozenStateList(),[\'delivered\',\'stopped\'])\n    self.assertEqual(invoice_link.getTradePhase(),\'trade/invoicing\')\n\n    self.assertEqual(invoice_link.getDeliveryBuilderList(),\n           [\"portal_deliveries/purchase_invoice_builder\",\n            \"portal_deliveries/purchase_invoice_transaction_trade_model_builder\",\n            \"portal_deliveries/sale_invoice_builder\",\n            \"portal_deliveries/sale_invoice_transaction_trade_model_builder\"])\n\n    account_link = getattr(business_process, \"account_link\", None)\n    self.assertNotEqual(account_link, None)\n    #self.assertFalse(account_link.getDeliverable())\n    self.assertEqual(account_link.getSuccessor(),\"trade_state/trade/accounted\")\n    self.assertEqual(account_link.getPredecessor(),\"trade_state/trade/invoiced\")\n    self.assertEqual(account_link.getCompletedStateList(),[\'delivered\',\'started\',\'stopped\'])\n    self.assertEqual(account_link.getFrozenStateList(),[\'delivered\',\'stopped\'])\n    self.assertEqual(account_link.getTradePhase(), \'trade/accounting\')\n\n    self.assertSameSet(account_link.getDeliveryBuilderList(),\n           [\"portal_deliveries/purchase_invoice_transaction_builder\",\n            \"portal_deliveries/sale_invoice_transaction_builder\"])\n\n    pay_link = getattr(business_process, \"pay_link\", None)\n    self.assertNotEqual(pay_link, None)\n    #self.assertFalse(pay_link.getDeliverable())\n    self.assertEqual(pay_link.getTradePhase(), \'trade/payment\')\n    self.assertEqual(pay_link.getSuccessor(), None)\n    self.assertEqual(pay_link.getPredecessor(),\"trade_state/trade/accounted\")\n    self.assertEqual(pay_link.getCompletedState(), None)\n    self.assertEqual(pay_link.getFrozenState(), None)\n\n    self.assertEqual(pay_link.getDeliveryBuilderList(),\n           [\"portal_deliveries/payment_transaction_builder\"])\n\n  def test_configurator_item_mixin(self):\n    \"\"\"ConfiguratorItemMixin is available for TTW definition of portal types.\n    \"\"\"\n    self.assertIn(\n        \'ConfiguratorItemMixin\',\n        self.portal.portal_types.newContent(\n            portal_type=\'Base Type\',\n            temp_object=True).getMixinTypeList())'),(5040,'extension.erp5.migrateWorkflowModuleToPortalWorkflow migrateWorkflowModuleToPortalWorkflow def titleToReference(title):\n  reference = title.replace(\' \', \'_\').lower()\n  return reference\n\ndef migrateToERP5Workflow(portal_workflow, configurator_workflow):\n  \"\"\"\n  Convert Configurator Workflow (workflow_module/*) to ERP5 Workflow.\n  \"\"\"\n  workflow_id = configurator_workflow.getId()\n  relative_url = \"%s/%s\" % (portal_workflow.getRelativeUrl(), workflow_id)\n  def getCategoryList(prefix, category_value_list):\n    return [\'%s/%s%s\' % (relative_url, prefix, titleToReference(o.getTitle()))\n            for o in category_value_list ]\n\n  workflow = portal_workflow.newContent(\n    portal_type=\'Workflow\',\n    reference=configurator_workflow.getId(),\n    comment=configurator_workflow.getComment(),\n    description=configurator_workflow.getDescription(),\n    state_base_category=configurator_workflow.getProperty(\'state_base_category\'),\n    state_variable=configurator_workflow.getProperty(\'state_variable_name\'),\n    source_list=getCategoryList(\'state_\', configurator_workflow.getSourceValueList()),\n    # ConfiguratorWorkflow PropertySheet\n    configuration_after_script_id=configurator_workflow.getConfigurationAfterScriptId())\n  for business_configuration in configurator_workflow.getRelatedValueList(\n      portal_type=\'Business Configuration\'):\n    business_configuration.setResourceValue(workflow)\n\n  for subobject in configurator_workflow.objectValues():\n    title = subobject.getTitle()\n    reference = titleToReference(title)\n\n    if subobject.getPortalType() == \'State\':\n      state = workflow.newContent(\n        portal_type=\'Workflow State\',\n        reference=reference,\n        title=title,\n        destination_list=getCategoryList(\'transition_\', subobject.getDestinationValueList()),\n        comment=subobject.getComment(),\n        description=subobject.getDescription())\n      for business_configuration in subobject.getRelatedValueList(\n          portal_type=\'Business Configuration\'):\n        business_configuration.setCurrentStateValue(state)\n\n    elif subobject.getPortalType() == \'Transition\':\n# XXX_1: Workflows only call Workflow Script and do not call Python Script in\n#        portal_skins but Configurator Workflows do. For now leave them as they\n#        ({before,after}_script_id property) but they should be migrated later on.\n#\n#      def addWorkflowScript(script_id_property):\n#        old_script_id = getattr(subobject.aq_base, script_id_property, None)\n#        if old_script_id:\n#          old_script = portal_workflow.getPortalObject().unrestrictedTraverse(old_script_id)\n#          script = workflow.newContent(id=workflow.getScriptIdByReference(old_script.id),\n#                                       portal_type=\'Workflow Script\')\n#          script.defeault_reference = old_script.id\n#          script.setTitle(old_script.title)\n#          script.setParameterSignature(\'state_change\')\n#          script.setBody(old_script._body)\n#          script.setProxyRole(old_script._proxy_roles)\n#          return script\n#      before_script_value = addWorkflowScript(\'before_script_id\')\n#      after_script_value = addWorkflowScript(\'after_script_id\')\n\n      transition = workflow.newContent(\n        portal_type=\'Workflow Transition\',\n        reference=reference,\n        title=title,\n        destination_list=getCategoryList(\'state_\', subobject.getDestinationValueList()),\n        comment=subobject.getComment(),\n        description=subobject.getDescription(),\n# XXX_1: before_script_value=before_script_value,\n#        after_script_value=after_script_value,\n        guard_expression=subobject.getProperty(\'guard_expression\'),\n        # ConfiguratorWorkflowTransition Property Sheet\n        transition_form_id=subobject.getProperty(\'transition_form_id\'))\n# XXX_1: Should use the normal {before,after}_script Workflow Property.\n      try:\n        transition.before_script_id = subobject.aq_base.before_script_id\n      except AttributeError:\n        pass\n      try:\n        transition.after_script_id = subobject.aq_base.after_script_id\n      except AttributeError:\n        pass\n      # XXX: Transition Variable: Not used in erp5.git, used elsewhere?\n\n    elif subobject.getPortalType() == \'Variable\':\n      if reference in (\'action\',\n                       \'actor\',\n                       \'comment\',\n                       \'error_message\',\n                       \'history\',\n                       \'portal_type\',\n                       \'time\'):\n        continue\n\n      workflow.newContent(\n        portal_type=\'Workflow Variable\',\n        reference=reference,\n        title=title,\n        description=subobject.getDescription(),\n        automatic_update=subobject.getAutomaticUpdate(),\n        variable_default_expression=subobject.aq_base.initial_value,\n        comment=subobject.getComment())\n\n    # default_image\n    elif subobject.getPortalType() == \'Embedded File\':\n      copy_data = configurator_workflow.manage_copyObjects([subobject.getId()])\n      workflow.manage_pasteObjects(copy_data)\n\n    else:\n      raise NotImplementedError(\n        \"%s: Portal Type \'%s\'\" % (subobject.getRelativeUrl(),\n                                  subobject.getPortalType()))\n\n  return workflow\n\ndef migrateWorkflowModuleToPortalWorkflow(self, recreate=False):\n  \"\"\"\n  Migrate workflow_module to new-style ERP5Workflows: workflow_module was implemented\n  for Configurators, based on DCWorkflow (portal_workflow), and a step towards migrating\n  DCWorkflows to ERP5 Objects. Now that portal_workflow is a real ERP5 Object, these must\n  be migrated to portal_workflow.\n  \"\"\"\n  portal = self.getPortalObject()\n  try:\n    workflow_module = portal.workflow_module\n  except AttributeError:\n    return \"Nothing to do as workflow_module does not exist.\"\n  portal_workflow = portal.portal_workflow\n  assert portal_workflow.getPortalType() == \'Workflow Tool\'\n\n  from zLOG import LOG\n  for configurator_workflow in workflow_module.objectValues():\n    id_ = configurator_workflow.getId()\n    if id_ in portal_workflow:\n      if not recreate:\n        continue\n      portal_workflow._delOb(id_)\n\n    new_workflow = migrateToERP5Workflow(portal_workflow, configurator_workflow)\n    LOG(\"migrateWorkflowModuleToPortalWorkflow\", 0,\n             \"Migrated %s to %s\" % (configurator_workflow.getRelativeUrl(),\n                                                    new_workflow.getRelativeUrl()))\n\n  return \'Done\''),(5041,'extension.erp5.ConfigurationTemplate_readOOoCalcFile ConfigurationTemplate_readOOoCalcFile ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\n# This extension should be replaced by a clever parser provided by\n# ERP5OOo or probably by CloudOOo itself.\n\nimport six\n\nfrom io import BytesIO\nfrom Products.ERP5Type.Utils import unicode2str\n\ndef read(self, filename, data):\n  \"\"\"\n  Return a OOCalc as a BytesIO\n  \"\"\"\n  if data is None:\n    oo_template_file = getattr(self, filename)\n    fp = BytesIO(bytes(oo_template_file))\n  else:\n    fp = BytesIO(data)\n  fp.filename = filename\n  return fp\n\ndef getIdFromString(string):\n  \"\"\"\n    This function transform a string to a safe id.\n    It is used here to create a safe category id from a string.\n  \"\"\"\n  if string is None:\n    return None\n  clean_id = \'\'\n  translation_map = { \"a\": [\'\\xe0\']\n                    , \"e\": [\'\\xe9\', \'\\xe8\']\n                    }\n  #string = string.lower()\n  string = string.strip()\n  # oocalc inserts some strange chars when you press - key in a text cell.\n  # Following line is a workaround for this,\n  # because \\u2013 does not exist in latin1\n  string = string.replace(u\'\\u2013\', \'-\')\n  if six.PY2:\n    string = unicode2str(string)\n  for char in string:\n    if char == \'_\' or char.isalnum():\n      clean_id += char\n    elif char.isspace() or char in (\'+\', \'-\'):\n      clean_id += \'_\'\n    else:\n      for (safe_char, char_list) in translation_map.items():\n        if char in char_list:\n          clean_id += safe_char\n          break\n  return clean_id\n\ndef convert(self, filename, data=None):\n  from Products.ERP5OOo.OOoUtils import OOoParser\n  OOoParser = OOoParser()\n  import_file = read(self, filename, data)\n\n  # Extract tables from the speadsheet file\n  OOoParser.openFile(import_file)\n  filename = OOoParser.getFilename()\n  spreadsheets = OOoParser.getSpreadsheetsMapping()\n\n  table_dict = {}\n  for table_name, table in spreadsheets.items():\n    if not table:\n      continue\n    # Get the header of the table\n    columns_header = table[0]\n    # Get the mapping to help us to know the property according a cell index\n    property_map = {}\n    column_index = 0\n    for column in columns_header:\n      column_id = getIdFromString(column)\n      # The column has no header information\n      # The column has a normal header\n      property_map[column_index] = column_id\n      column_index += 1\n\n    # Construct categories data (with absolut path) from table lines\n    object_list = []\n\n    for line in table[1:]:\n      object_property_dict = {}\n\n      # Exclude empty lines\n      if line.count(\'\') + line.count(None) == len(line):\n        continue\n\n      # Analyse every cells of the line\n      cell_index = 0\n      for cell in line:\n        # Ignore empty cells, do the test on the generated id\n        # because getIdFromString() is more restrictive\n        cell_id = getIdFromString(cell)\n        if cell_id not in (\'\', None):\n          # Get the property corresponding to the cell data\n          property_id = property_map[cell_index]\n          # Convert the value to something like \'\\xc3\\xa9\' not \'\\xc3\\xa9\'\n          if six.PY2:\n            cell = unicode2str(cell)\n          object_property_dict[property_id] = cell\n        cell_index += 1\n\n      if len(object_property_dict) > 0:\n        object_list.append(object_property_dict)\n    if six.PY2:\n      table_name = unicode2str(table_name)\n    table_dict[table_name] = object_list\n\n  if len(table_dict.keys()) == 1:\n    return object_list\n  else:\n    return table_dict'),(5043,'ConfiguratorWorkflowTransition'),(5046,'ConfiguratorWorkflow'),(5047,'tool.erp5.ConfiguratorTool ConfiguratorTool ##############################################################################\n#\n# Copyright (c) 2006-2010 Nexedi SA and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Ivan Tyagov <ivan@nexedi.com>\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type.Accessor.Constant import PropertyGetter as \\\n    ConstantGetter\nfrom Products.ERP5Type.Tool.BaseTool import BaseTool\nfrom Products.ERP5Type import Permissions\nfrom Products.Formulator.Errors import FormValidationError\nfrom DateTime import DateTime\n\nreferer = None\ninstallation_status = {\'bt5\': {\'current\': 0,\n                               \'all\': 0, },\n                       \'activity_list\': [], }\n\n# cookie name to store user\'s preferred language name\nLANGUAGE_COOKIE_NAME = \'configurator_user_preferred_language\'\nBUSINESS_CONFIGURATION_COOKIE_NAME = \'business_configuration_key\'\n\ndef _validateFormToRequest(form, REQUEST, **kw):\n  \"\"\" Validate form to REQUEST. \"\"\"\n  form_kw = {}\n  REQUEST.form = kw\n  try:\n    form.validate_all_to_request(REQUEST)\n    validation_status = 0\n    validation_errors = None\n  except FormValidationError as e:\n    ## not all fields valid\n    validation_status = 1\n    validation_errors = e\n  except Exception as e:\n    ## missing fields\n    validation_status = 2\n    validation_errors = e\n  ## extract form arguments and remove leading prefixes\n  if validation_status == 0:\n    for field in form.get_fields():\n      field_id = field.id\n      value = getattr(REQUEST, field_id, None)\n      for prefix in (\'my_\', \'your_\',):\n        if field_id.startswith(prefix):\n          attr_id = field_id[len(prefix):]\n          form_kw[attr_id] = value\n          for del_key in (field.generate_field_key(validation=1), field_id):\n            try:\n              REQUEST.other.pop(del_key)\n            except KeyError:\n              pass\n  return validation_status, form_kw, validation_errors\n\n\nclass ConfiguratorTool(BaseTool):\n  \"\"\"This tool provides a Configurator Tool.\n  \"\"\"\n\n  id = \'portal_configurator\'\n  title = \'Configurations\'\n  meta_type = \'ERP5 Configurator Tool\'\n  portal_type = \'Configurator Tool\'\n\n  isPortalContent = ConstantGetter(\'isPortalContent\', value=True)\n\n  security = ClassSecurityInfo()\n\n  security.declareProtected(Permissions.ManagePortal, \'manage_overview\')\n\n  def login(self, REQUEST):\n    \"\"\" Login client and show next form. \"\"\"\n    bc = REQUEST.get(\'field_your_business_configuration\')\n    user_preferred_language = REQUEST.get(\n        \'field_my_user_preferred_language\', None)\n    if user_preferred_language:\n      # Set language value to request so that next page after login\n      # can get the value. Because cookie value is available from\n      # next request.\n      REQUEST.set(LANGUAGE_COOKIE_NAME, user_preferred_language)\n      REQUEST.RESPONSE.setCookie(LANGUAGE_COOKIE_NAME,\n                                   user_preferred_language,\n                                   path=\'/\',\n                                   expires=(DateTime() + 30).rfc822())\n\n    expires = (DateTime() + 1).toZone(\'GMT\').rfc822()\n    REQUEST.RESPONSE.setCookie(BUSINESS_CONFIGURATION_COOKIE_NAME,\n                               bc,\n                               expires=expires)\n    REQUEST.set(BUSINESS_CONFIGURATION_COOKIE_NAME, bc)\n    return self.next(REQUEST=REQUEST)\n\n  #security.declareProtected(Permissions.ModifyPortalContent, \'next\')\n  def next(self, REQUEST):\n    \"\"\" Validate settings and return a new form to the user.  \"\"\"\n    # check if user is allowed to access service\n    portal = self.getPortalObject()\n    kw = self.REQUEST.form.copy()\n    business_configuration = REQUEST.get(BUSINESS_CONFIGURATION_COOKIE_NAME)\n    bc = portal.restrictedTraverse(business_configuration)\n    if bc is None:\n      REQUEST.set(\'portal_status_message\',\n                   self.Base_translateString(\n                     \'You cannot Continue. Unable to find your Business Configuration.\'))\n      return self.view()\n    response = self._next(business_configuration=bc, kw=kw)\n    ## Parse server response\n    if response[\"command\"] == \"show\":\n      return self.ConfiguratorTool_dialogForm(previous=response[\'previous\'],\n                                        form_html=response[\"data\"],\n                                        next=response[\'next\'])\n    elif response[\"command\"] == \"install\":\n      return self.startInstallation(bc, REQUEST=REQUEST)\n\n  def _next(self, business_configuration, kw):\n    \"\"\" Return next configuration form and validate previous. \"\"\"\n    form_kw = {}\n    need_validation = 1\n    validation_errors = None\n    response = {}\n\n    business_configuration.initializeWorkflow()\n\n    ## initial state no previous form to validate\n    if business_configuration.isInitialConfigurationState():\n      need_validation = 0\n\n    ## client can not go further hist business configuration is already built\n    if business_configuration.isEndConfigurationState() or \\\n         business_configuration.getNextTransition() == None:\n      return self._terminateConfigurationProcess(response)\n\n    isMultiEntryTransition = business_configuration._isMultiEntryTransition()\n    ## validate multiple forms\n    if isMultiEntryTransition:\n      html_forms = []\n      failed_forms_counter = 0\n      transition = business_configuration.getNextTransition()\n      form = getattr(business_configuration, transition.getTransitionFormId())\n      for form_key in [x for x in kw.keys() if x.startswith(\'field_\')]:\n        form_kw[form_key] = kw[form_key]\n      ## iterate all forms\n      for form_counter in range(0, isMultiEntryTransition):\n        single_form_kw = {}\n        for key, value in form_kw.items():\n          if isinstance(value, list) or isinstance(value, tuple):\n            ## we have more than one form shown\n            single_form_kw[key] = value[form_counter]\n            # save original value in request in some cases of multiple forms\n            # we need it for validation\n            single_form_kw[\'_original_%s\' % key] = value\n          else:\n            ## even though we have multiple entry transition customer wants\n            ## ONE form!\n            single_form_kw[key] = value\n        ## update properly REQUEST with current form data\n        for key, value in single_form_kw.items():\n          self.REQUEST.set(key, value)\n        ## get validation status\n        validation_status, dummy, validation_errors = \\\n           business_configuration._validateNextForm(**single_form_kw)\n\n        ## clean up REQUEST from traces from validate_all_to_request\n        ## otherwise next form will use previous forms details\n        cleanup_keys = [x for x in self.REQUEST.other.keys() if x.startswith(\'my_\') or x.startswith(\'your_\')]\n        for key in cleanup_keys:\n          self.REQUEST.other.pop(key, None)\n        ## render HTML code\n        if validation_status != 0:\n          failed_forms_counter += 1\n          ## XXX: form can fail because a new\n          ## http://localhost:9080/erp5/portal_wizard/next is issued\n          ## without arguments. Improve this\n          try:\n            self.REQUEST.set(\'field_errors\',\n                form.ErrorFields(validation_errors))\n          except Exception:\n            pass\n          single_form_html = form()\n          self.REQUEST.other.pop(\'field_errors\', None)\n          self.REQUEST.form = {}\n        else:\n          single_form_html = form()\n        ## wrap in form template\n        single_form_html = self.Base_mainConfiguratorFormTemplate(\n                                current_form_number = form_counter + 1,\n                                max_form_numbers = isMultiEntryTransition,\n                                form_html = single_form_html)\n        ## add to list of forms as html code\n        html_forms.append(single_form_html)\n      ## return if failure\n      if failed_forms_counter > 0:\n        next_state = self.restrictedTraverse(business_configuration.getNextTransition()\\\n            .getDestination())\n        html_data = self.Base_mainConfiguratorTemplate(\n            form_html = \"\\n\".join(html_forms),\n            current_state = next_state,\n            business_configuration = business_configuration)\n        response.update(command = \"show\",\n                  previous = self.Base_translateString(\"Previous\"),\n                  next = self.Base_translateString(transition.getTitle()),\n                  data = html_data)\n        return response\n\n    ## show next form in transitions\n    html = None\n    rendered = False\n    while rendered is False:\n      if need_validation == 1:\n        if isMultiEntryTransition:\n          ## multiple forms must be validated before\n          validation_status = 0\n        else:\n          validation_status, form_kw, validation_errors = \\\n              business_configuration._validateNextForm(**kw)\n        if validation_status == 1:\n          need_validation = 0\n        elif validation_status == 2:\n          rendered = True\n          need_validation = 0\n          if business_configuration.getNextTransition() == None:\n            ### client can not continue at the momen\n            return self._terminateConfigurationProcess(response)\n          response[\"previous\"], html, _, response[\"next\"] \\\n                  = business_configuration._displayNextForm()\n        else:\n          ## validation passed\n          need_validation = 0\n          business_configuration._executeTransition(form_kw=form_kw, request_kw=kw)\n      elif need_validation == 0:\n        if business_configuration.getNextTransition() == None:\n          return self._terminateConfigurationProcess(response)\n        ## validation failure\n        rendered = True\n        response[\"previous\"], html, _, response[\"next\"] =\\\n            business_configuration._displayNextForm(\n                validation_errors=validation_errors)\n\n    if html is None:\n      ## we have no more forms proceed to build\n      response.update(command=\"install\", data=None)\n    else:\n      ## we have more forms\n      next_state = self.restrictedTraverse(business_configuration.getNextTransition()\\\n          .getDestination())\n      html_data = self.Base_mainConfiguratorTemplate(\n          form_html = html,\n          current_state = next_state,\n          business_configuration = business_configuration)\n      response.update(command = \"show\", data = html_data)\n    return response\n\n  def _terminateConfigurationProcess(self, response):\n    \"\"\" Terminate process and return some explanations to client why\n        he can no longer continue. \"\"\"\n    response.update(command=\"show\",\n                    next=None, \\\n                    previous=None,\n                    data=self.BusinessConfiguration_viewStopForm())\n    return response\n\n  #security.declareProtected(Permissions.ModifyPortalContent, \'previous\')\n  def previous(self, REQUEST):\n    \"\"\" Display the previous form. \"\"\"\n    # check if user is allowed to access service\n    portal = self.getPortalObject()\n    kw = self.REQUEST.form.copy()\n    business_configuration = REQUEST.get(BUSINESS_CONFIGURATION_COOKIE_NAME)\n    bc = portal.restrictedTraverse(business_configuration)\n    response = self._previous(business_configuration=bc, kw=kw)\n    return self.ConfiguratorTool_dialogForm(previous=response[\'previous\'],\n                                      form_html=response[\'data\'],\n                                      next=response[\'next\'])\n\n  def _previous(self, business_configuration, kw):\n    \"\"\" Returns previous form. \"\"\"\n    response = {}\n    ## client can not go further his business configuration is already built\n    if business_configuration is None or \\\n         business_configuration.isEndConfigurationState():\n      form_html = self.BusinessConfiguration_viewStopForm()\n      return self.ConfiguratorTool_dialogForm(form_html = form_html,\n                                        next = \"Next\")\n\n    response[\'previous\'], form_html, _, response[\'next\'] = \\\n        business_configuration._displayPreviousForm()\n\n    next_state = self.restrictedTraverse(\n        business_configuration.getNextTransition().getDestination())\n\n    response[\'data\'] = self.Base_mainConfiguratorTemplate(\n        form_html=form_html,\n        current_state=next_state,\n        business_configuration=business_configuration)\n    return response\n\n  security.declarePublic(\'getInstallationStatusReport\')\n  def getInstallationStatusReport(self,\n                          active_process_id=None, REQUEST=None):\n    \"\"\" Query local ERP5 instance for installation status.\n        If installation is over the installation activities and reindexing\n        activities should not exists.\n    \"\"\"\n    portal_activities = self.getPortalObject().portal_activities\n\n    if 0 == len(portal_activities.getMessageList()):\n      html = self.ConfiguratorTool_viewSuccessfulConfigurationMessageRenderer()\n    else:\n      # only if bt5s are installed start tracking number of activities\n      activity_list = portal_activities.getMessageList()\n      installation_status[\'activity_list\'].append(len(activity_list))\n      html = self.ConfiguratorTool_viewRunningInstallationMessage(\n          installation_status = installation_status)\n    # set encoding as this is usually called from asynchronous JavaScript call\n    self.REQUEST.RESPONSE.setHeader(\'Content-Type\',\n        \'text/html; charset=utf-8\')\n    return html\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'startInstallation\')\n  def startInstallation(self, business_configuration, REQUEST):\n    \"\"\" Start installation process as an activity which will\n        download/install bt5 template files and meanwhile offer\n        user a nice GUI to observe what\'s happening. \"\"\"\n\n    # init installation status\n    installation_status[\'bt5\'][\'all\'] = 1\n    installation_status[\'bt5\'][\'current\'] = 0\n    installation_status[\'activity_list\'] = []\n    active_process = self.portal_activities.newActiveProcess()\n    REQUEST.set(\'active_process_id\', active_process.getId())\n    business_configuration.activate(\n           active_process=active_process, tag=\'initialERP5Setup\'\n        ).build()\n    return self.ConfiguratorTool_viewInstallationStatus(REQUEST)'),(5048,'mixin.erp5.SkinConfiguratorItemMixin SkinConfiguratorItemMixin ##############################################################################\n#\n# Copyright (c) 2006-2012 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Ivan Tyagov <ivan@nexedi.com>\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom zLOG import LOG, INFO\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\n\n\nclass SkinConfiguratorItemMixin(ConfiguratorItemMixin):\n  \"\"\" Mixin which allows to create python scripts and/or skin\n      elements during the configuration.\n  \"\"\"\n\n  def install(self, skinfolder, business_configuration, prefix=\'\'):\n    \"\"\"\n    \"\"\"\n    bt5_obj = business_configuration.getSpecialiseValue()\n    if bt5_obj is None:\n      LOG(\'ConfiguratorItem\', INFO,\n          \'Unable to find related business template to %s\' % \\\n            business_configuration.getRelativeUrl())\n      return\n\n    template_skin_id_list = list(bt5_obj.getTemplateSkinIdList())\n    if skinfolder.getId() not in template_skin_id_list:\n      template_skin_id_list.append(skinfolder.getId())\n    bt5_obj.edit(template_skin_id_list=template_skin_id_list)\n\n  def _createSkinFolder(self, folder_id=\"custom\"):\n    \"\"\" Creates a new skin folder id if it do not exists and\n        update Skin information \"\"\"\n    folder = getattr(self.portal_skins, folder_id, None)\n    if folder is not None:\n      return folder\n\n    folder = self.portal_skins.manage_addProduct[\'OFSP\'].manage_addFolder(folder_id)\n    # Register on all skin selections.\n    raise NotImplementedError\n\n  def _createZODBPythonScript(self, container, script_id, script_params,\n                            script_content):\n    \"\"\"Creates a Python script `script_id` in the given `container`, with\n    `script_params` and `script_content`.\n\n    If the container already contains an object with id `script_id`, this\n    object is removed first.\n    \"\"\"\n    if script_id in container.objectIds():\n      container.manage_delObjects([script_id])\n\n    container.manage_addProduct[\'PythonScripts\']\\\n                  .manage_addPythonScript(id = script_id)\n    script = container._getOb(script_id)\n    script.ZPythonScript_edit(script_params, script_content)\n    container.getPortalObject().changeSkin(None)\n    return script'),(5049,'mixin.erp5.ConfiguratorItemMixin ConfiguratorItemMixin ##############################################################################\n#\n# Copyright (c) 2006-2012 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Ivan Tyagov <ivan@nexedi.com>\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom Products.ERP5Type.ConsistencyMessage import ConsistencyMessage\nfrom zLOG import LOG, INFO\n\nclass ConfiguratorItemMixin:\n  \"\"\" This is the base class for all configurator item. \"\"\"\n\n  def getBusinessConfigurationValue(self):\n    item = self\n    while item.getPortalType() != \'Business Configuration\':\n      item = item.getParentValue()\n    return item\n\n  def _createConstraintMessage(self, message):\n    return ConsistencyMessage(self,\n        object_relative_url=self.getRelativeUrl(),\n        message=message)\n\n  def install(self, document, business_configuration, prefix=\'\'):\n    \"\"\" Add object to customer customization template. \"\"\"\n    bt5_obj = business_configuration.getSpecialiseValue()\n    if bt5_obj is None:\n      LOG(\'ConfiguratorItem\', INFO,\n          \'Unable to find related business template to %s\' % \\\n            business_configuration.getRelativeUrl())\n      return\n\n    if document.getPortalType() in [\'Category\', \'Base Category\']:\n      prefix = \"portal_categories/\"\n    template_path_list = [\'%s%s\' % (prefix, document.getRelativeUrl()),\n                          \'%s%s/**\' % (prefix, document.getRelativeUrl())]\n\n    current_template_path_list = list(bt5_obj.getTemplatePathList())\n    current_template_path_list.extend(template_path_list)\n    bt5_obj.edit(template_path_list=current_template_path_list)'),(5050,'interface.erp5.ISpreadsheetConfiguratorItem ISpreadsheetConfiguratorItem # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2020 Nexedi SA and Contributors. All Rights Reserved.\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom zope.interface import Interface\n\nclass ISpreadsheetConfiguratorItem(Interface):\n  \"\"\"Configurator Item using spreadsheet as data source for configuration\n  \"\"\"'),(5051,'interface.erp5.IConfiguratorItem IConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2010 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom zope.interface import Interface\n\nclass IConfiguratorItem(Interface):\n  \"\"\"\n   Configurator Item interface specification.\n\n   Documents which implement the IConfiguratorItem interface\n   can be used to build an ERP5 Configuration Save.\n  \"\"\"\n\n  def _build(business_configuration):\n    \"\"\"\n    Build new ERP5 Documents based on stored parameters during\n    the configuraton process.\n\n    business_configuration - Business Configuration Document that is\n                             been used to configure.\n    \"\"\"'),(5052,'document.erp5.SystemPreferenceConfiguratorItem SystemPreferenceConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass SystemPreferenceConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup System preference. \"\"\"\n\n  meta_type = \'ERP5 System Preference Configurator Item\'\n  portal_type = \'System Preference Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _getPreferenceNameList(self):\n    \"\"\"Return names of preference properties.\n    \"\"\"\n    property_id_list = []\n    portal = self.getPortalObject()\n    for property_sheet_id in portal.portal_types[\n                     \'System Preference\'].getTypePropertySheetList():\n      property_sheet = portal.portal_property_sheets[property_sheet_id]\n      for prop in property_sheet.contentValues():\n        if prop.getProperty(\'preference\'):\n          list_prefix = \'\'\n          if prop.getProperty(\'multivalued\') or (\n               prop.getProperty(\'elementary_type\') in (\n                 \'lines\', \'multiple selection\', \'tokens\')):\n            list_prefix = \'_list\'\n          property_id_list.append(\'%s%s\' % (prop.getReference(), list_prefix))\n    return property_id_list\n\n  def _checkConsistency(self, fixit=False, **kw):\n    error_list = []\n    portal = self.getPortalObject()\n    preference = portal.portal_preferences._getOb(self.object_id, None)\n    if preference is None:\n      error_list.append(self._createConstraintMessage(\n        \"System Preference %s should be created\" % self.object_id))\n      if fixit:\n        preference = portal.portal_preferences.newContent(\n                                portal_type = \'System Preference\',\n                                id = self.object_id,\n                                title = self.title,\n                                description = self.description,\n                                priority = 1)\n      else:\n        return error_list\n\n    preference_dict = {}\n\n    marker = []\n    for preference_name in self._getPreferenceNameList():\n      preference_value = getattr(self, preference_name,\n                     preference.getProperty(preference_name, marker))\n      if preference_value is not marker and preference_value is not None:\n        preference_dict[preference_name] = preference_value\n\n    if self.portal_workflow.isTransitionPossible(preference, \'enable\'):\n      preference.enable()\n\n    preference.edit(**preference_dict)\n    business_configuration = self.getBusinessConfigurationValue()\n    bt5_obj = business_configuration.getSpecialiseValue()\n    current_template_preference_list = list(bt5_obj.getTemplatePreferenceList())\n    if preference.getId() not in current_template_preference_list:\n      current_template_preference_list.append(preference.getId())\n      bt5_obj.edit(template_preference_list=current_template_preference_list,)\n\n    return error_list'),(5053,'document.erp5.StandardBT5ConfiguratorItem StandardBT5ConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\nfrom Products.ERP5Type.Cache import CachingMethod\nfrom zLOG import LOG, INFO\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass StandardBT5ConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" This class will install standard ERP5 template from a repository to\n  fake site. \"\"\"\n\n  meta_type = \'ERP5 Standard BT5 Configurator Item\'\n  portal_type = \'Standard BT5 Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.StandardBT5ConfiguratorItem\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    template_tool = self.getPortalObject().portal_templates\n    bt5_id = self.getBt5Id().split(\'.\')[0]\n\n    if bt5_id in template_tool.getInstalledBusinessTemplateTitleList():\n      LOG(\"StandardBT5ConfiguratorItem\", INFO,\n        \"Business Template already Installed: %s for %s\" % (bt5_id, self.getRelativeUrl()))\n      return []\n\n    def _getRepositoryBusinessTemplateTitleList():\n      return [bt.getTitle() for bt in \\\n              template_tool.getRepositoryBusinessTemplateList()]\n    repository_bt_title_list = CachingMethod(\n                         _getRepositoryBusinessTemplateTitleList,\n                         id=\'StandardBT5_getRepositoryBusinessTemplateTitleList\',\n                         cache_factory=\'erp5_content_long\')()\n\n    if bt5_id in repository_bt_title_list:\n      if fixit:\n        template_tool.installBusinessTemplateListFromRepository([bt5_id],\n                                  update_catalog=self.getUpdateCatalog(0),\n                                  install_dependency=self.getInstallDependency(1),\n                                  activate=True)\n\n      return [self._createConstraintMessage(\'%s should be installed\' % bt5_id),]\n\n    raise ValueError(\"The business template %s was not found on available \\\n                         sources.\" % bt5_id)'),(5054,'document.erp5.SolverConfiguratorItem SolverConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                   Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\nimport six\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass SolverConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Solvers. \"\"\"\n\n  meta_type = \'ERP5 Solver Configurator Item\'\n  portal_type = \'Solver Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n      business_configuration = self.getBusinessConfigurationValue()\n\n      solver = getattr(portal.portal_solvers, self.getId(), None)\n      if solver is None:\n        solver_property_dict = \\\n            business_configuration.BusinessConfiguration_getSolverPropertyDict()\n        property_dict = solver_property_dict.get(self.getId())\n        argument_dict = {}\n\n        for k, v in six.iteritems(property_dict):\n          if k not in (\"content_list\",) and k in self.showDict():\n            argument_dict[k] = v\n\n        solver = portal.portal_solvers.newContent(portal_type=\"Solver Type\",\n                                                  id=argument_dict.pop(\'id\'))\n        solver.edit(**argument_dict)\n\n        for information_dict in self.content_list:\n          portal_type = information_dict.pop(\'portal_type\')\n          action = solver.newContent(portal_type=portal_type, id=information_dict.pop(\'id\'))\n          action.edit(**information_dict)\n\n      self.install(solver, business_configuration)\n\n    return [self._createConstraintMessage(\'Solvers should be created\')]'),(5055,'document.erp5.SitePropertyConfiguratorItem SitePropertyConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Yoshinori Okuji <yo@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass SitePropertyConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"Set up site properties.\"\"\"\n\n  meta_type = \'ERP5 Site Property Configurator Item\'\n  portal_type = \'Site Property Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.ConfiguratorItem )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    portal = self.getPortalObject()\n    id_list = []\n    for id_, value, prop_type in self.getConfigurationList():\n      if fixit:\n        if portal.hasProperty(id_):\n          portal._delProperty(id_)\n        portal._setProperty(id_, value, type=prop_type)\n      id_list.append(id_)\n\n    if fixit:\n      business_configuration = self.getBusinessConfigurationValue()\n      bt = business_configuration.getSpecialiseValue()\n      bt.edit(template_site_property_id_list=id_list)\n\n    return [self._createConstraintMessage(\"The property %s should set on portal\" % id_) for id_ in id_list]'),(5056,'document.erp5.ServiceConfiguratorItem ServiceConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#                    TAHARA Yusei <yusei@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom warnings import warn\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\nfrom six import string_types as basestring\n\n@zope.interface.implementer(IConfiguratorItem)\nclass ServiceConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"Create default service documents.\"\"\"\n\n  meta_type = \'ERP5 Service Configurator Item\'\n  portal_type = \'Service Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.ConfiguratorItem )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    portal = self.getPortalObject()\n    error_list = []\n    for service_id, service_dict in iter(self.getConfigurationListList()):\n      if isinstance(service_dict, basestring):\n        warn(DeprecationWarning,\n          \"ServiceConfiguratorItem now use (service_id, service_dict) as configuration list\")\n        service_dict = dict(title=service_dict)\n\n      document = getattr(portal.service_module, service_id, None)\n      if document is None:\n        error_list.append(self._createConstraintMessage(\n          \"Service %s should be created\"))\n        if fixit:\n          document = portal.service_module.newContent(portal_type=\'Service\',\n                                    id=service_id, **service_dict)\n          document.validate(comment=translateString(\"Validated by Configurator\"))\n\n      if document:\n        ## add to customer template\n        business_configuration = self.getBusinessConfigurationValue()\n        self.install(document, business_configuration)\n\n    return error_list'),(5057,'document.erp5.SecurityCategoryMappingConfiguratorItem SecurityCategoryMappingConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2012 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.SkinConfiguratorItemMixin import \\\n                                       SkinConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass SecurityCategoryMappingConfiguratorItem(SkinConfiguratorItemMixin,\n                                              XMLObject):\n  \"\"\" Setup the ERP5Type_getSecurityCategoryMapping Python Script which\n      is the onde that defines the Security Mapping for the user login. \"\"\"\n\n  meta_type = \'ERP5 Security Category Mapping Configurator Item\'\n  portal_type = \'Security Category Mapping Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    )\n  def _checkConsistency(self, fixit=False, **kw):\n    script_id = \'ERP5Type_getSecurityCategoryMapping\'\n    error_list = [self._createConstraintMessage(\'%s should be created\' % script_id,)]\n    if fixit:\n      script_content = \"\"\"return (\n  (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'function\']),\n  (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'follow_up\']),\n  (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'function\', \'follow_up\']),\n  (\'ERP5Type_getSecurityCategoryFromAssignmentStrict\', [\'group\']),\n  (\'ERP5Type_getSecurityCategoryRoot\', [\'group\']),\n  )\"\"\"\n\n      folder = self._createSkinFolder()\n      self._createZODBPythonScript(folder,\n                                   script_id,\n                                    \'\', script_content)\n\n      ## add to customer template\n      business_configuration = self.getBusinessConfigurationValue()\n      self.install(folder, business_configuration)\n\n    return error_list'),(5058,'document.erp5.SaleTradeConditionConfiguratorItem SaleTradeConditionConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass SaleTradeConditionConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Sale Trade Conditions. \"\"\"\n\n  meta_type = \'ERP5 Sale Trade Condition Configurator Item\'\n  portal_type = \'Sale Trade Condition Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n\n      business_configuration = self.getBusinessConfigurationValue()\n      business_process_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'sale_business_process_id\') or \\\n        business_configuration.getGlobalConfigurationAttr(\'business_process_id\')\n\n      organisation_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'organisation_id\')\n\n      currency_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'currency_id\')\n\n      trade_condition = portal.sale_trade_condition_module.newContent(\n                                            portal_type=\"Sale Trade Condition\",\n                                            reference=self.getReference(),\n                                            title=self.getTitle())\n\n      trade_condition.setSpecialise(\"business_process_module/%s\" %\\\n                        business_process_id)\n\n      trade_condition.setSource(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setSourceSection(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setPriceCurrency(\"currency_module/%s\" % currency_id)\n\n      trade_condition.validate(comment=translateString(\"Validated by Configurator\"))\n\n      self.install(trade_condition, business_configuration)\n\n    return [self._createConstraintMessage(\'Sale Trade Condition with reference %s should be created\' % \\\n        self.getReference(),)]'),(5059,'document.erp5.RuleConfiguratorItem RuleConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2012 Nexedi SA and Contributors. All Rights Reserved.\n#                    Lucas Carvalho <lucas@nexedi.com>\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n@zope.interface.implementer(IConfiguratorItem)\nclass RuleConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Rules. \"\"\"\n\n  meta_type = \'ERP5 Rule Configurator Item\'\n  portal_type = \'Rule Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n      template_id = self.getId()\n\n      if getattr(portal.portal_rules, template_id, None) is not None:\n        cb_data = portal.portal_rules.manage_copyObjects([template_id])\n        copied, = portal.portal_rules.manage_pasteObjects(cb_data)\n        rule = portal.portal_rules[copied[\"new_id\"]]\n        if self.getReference() is not None:\n          rule.edit(reference=self.getReference())\n        rule.setVersion(str(int(rule.getVersion(0)) + 1))\n        if len(self.getTradePhaseList()) > 0:\n          rule.setTradePhaseList(self.getTradePhaseList())\n        rule.validate()\n      else:\n        raise ValueError(\"Unable to find rule template with id %s\" % template_id)\n\n      business_configuration = self.getBusinessConfigurationValue()\n      self.install(rule, business_configuration)\n    return [self._createConstraintMessage(\'Rule should be defined\')]'),(5060,'document.erp5.RoleConfiguratorItem RoleConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom Acquisition import aq_base\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\nfrom zLOG import LOG, INFO\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass RoleConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup role per module basis. \"\"\"\n\n  meta_type = \'ERP5 Role Configurator Item\'\n  portal_type = \'Role Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    error_list = [self._createConstraintMessage(\'Roles should imported and created\')]\n    if fixit:\n      business_configuration = self.getBusinessConfigurationValue()\n      object_list = business_configuration.ConfigurationTemplate_readOOCalcFile(self.filename)\n      portal = self.getPortalObject()\n\n      portal_type_dict = {}\n      # we may pass some override dynamic values from outside\n      # Example:we post \'group_id\' and in column we have it then\n      # it will be replaced with value if not configuration file matters\n      dynamic_values = dict(group_id = getattr(aq_base(self), \'group_id\', None),\n                            function_id = getattr(aq_base(self), \'function_id\', None),\n                            site_id = getattr(aq_base(self), \'site_id\', None),)\n      for oo_module_dict in object_list:\n        mod_conf_list = []\n        portal_type = oo_module_dict.pop(\'portal_type\')\n        for category, role_list_string in oo_module_dict.items():\n          # passed from outside (it has higher priority than configuration file)\n          category = dynamic_values.get(category, category)\n          title = category.replace(\'/\', \'_\')\n          role_name_list = [x.strip() for x in role_list_string.split(\';\')]\n          role_category_list = [category]\n          conf_dict =  {\'title\': title,\n                        \'description\': \'Configured by ERP5 Configurator\',\n                        \'role_name_list\': role_name_list,\n                        \'role_category_list\': role_category_list}\n\n          mod_conf_list.append(conf_dict)\n        portal_type_dict[portal_type] = mod_conf_list\n      ## Update fake site\n      # XXX rafael: improve this, the ignore list is quite ugly.\n      ignore_list = []\n      portal_type_id_list = portal.portal_types.objectIds()\n      for portal_type, role_list in portal_type_dict.items():\n        for role_dict in role_list:\n          if portal_type in portal_type_id_list:\n            portal.portal_types[portal_type].newContent(portal_type=\'Role Information\', \\\n                                                        **role_dict)\n          else:\n            ignore_list.append(portal_type)\n            LOG(\"CONFIGURATOR\", INFO, \"Fail to define Roles for %s\" % portal_type)\n\n      ## Update BT5\n\n      bt5_obj = business_configuration.getSpecialiseValue()\n      # keep existing roles definition (from previous configuration saves)\n      for existing_type in bt5_obj.getTemplatePortalTypeRoleList():\n        portal_type_dict[existing_type] = 1\n      bt5_obj.edit(template_portal_type_role_list=[i for i in portal_type_dict.keys() if i not in ignore_list])\n\n    return error_list'),(5061,'document.erp5.PurchaseTradeConditionConfiguratorItem PurchaseTradeConditionConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass PurchaseTradeConditionConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Purchase Trade Conditions. \"\"\"\n\n  meta_type = \'ERP5 Purchase Trade Condition Configurator Item\'\n  portal_type = \'Purchase Trade Condition Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n      business_configuration = self.getBusinessConfigurationValue()\n      business_process_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'purchase_business_process_id\') or\\\n        business_configuration.getGlobalConfigurationAttr(\'business_process_id\')\n\n      organisation_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'organisation_id\')\n\n      currency_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'currency_id\')\n\n      trade_condition = portal.purchase_trade_condition_module.newContent(\n                                            portal_type=\"Purchase Trade Condition\",\n                                            reference=self.getReference(),\n                                            title=self.getTitle(), )\n\n      trade_condition.setSpecialise(\"business_process_module/%s\" %\\\n                        business_process_id)\n\n      trade_condition.setDestination(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setDestinationSection(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setPriceCurrency(\"currency_module/%s\" % currency_id)\n\n      trade_condition.validate(comment=translateString(\"Validated by Configurator\"))\n\n      self.install(trade_condition, business_configuration)\n\n    return [self._createConstraintMessage(\n            \'Purchase Trade Condition with reference %s should be created\' % self.getReference())]'),(5062,'document.erp5.PreferenceConfiguratorItem PreferenceConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass PreferenceConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup preference. \"\"\"\n\n  meta_type = \'ERP5 Preference Configurator Item\'\n  portal_type = \'Preference Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _getPreferenceNameList(self):\n    \"\"\"Return names of preference properties.\n    \"\"\"\n    property_id_list = []\n    portal = self.getPortalObject()\n    for property_sheet_id in portal.portal_types.Preference.getTypePropertySheetList():\n      property_sheet = portal.portal_property_sheets[property_sheet_id]\n      for prop in property_sheet.contentValues():\n        if prop.getProperty(\'preference\'):\n          list_prefix = \'\'\n          if prop.getProperty(\'multivalued\') or (\n               prop.getProperty(\'elementary_type\') in (\n                 \'lines\', \'multiple selection\', \'tokens\')):\n            list_prefix = \'_list\'\n          property_id_list.append(\'%s%s\' % (prop.getReference(), list_prefix))\n    return property_id_list\n\n  def _checkConsistency(self, fixit=False, **kw):\n    error_list = []\n    portal = self.getPortalObject()\n    preference = portal.portal_preferences._getOb(self.object_id, None)\n    if preference is None:\n      error_list.append(self._createConstraintMessage(\n        \"Preference %s should be created\" % self.object_id))\n      if fixit:\n        preference = portal.portal_preferences.newContent(\n                                portal_type = \'Preference\',\n                                id = self.object_id,\n                                title = self.title,\n                                description = self.description,\n                                priority = 1)\n      else:\n        return error_list\n\n    preference_dict = {}\n\n    marker = []\n    for preference_name in self._getPreferenceNameList():\n      preference_value = getattr(self, preference_name,\n                     preference.getProperty(preference_name, marker))\n      if preference_value is not marker and preference_value is not None:\n        preference_dict[preference_name] = preference_value\n\n    if self.portal_workflow.isTransitionPossible(preference, \'enable\'):\n      preference.enable()\n\n    business_configuration = self.getBusinessConfigurationValue()\n    organisation_id = business_configuration.\\\n                                 getGlobalConfigurationAttr(\'organisation_id\')\n    organisation_path = \'organisation_module/%s\' % organisation_id\n    preference_dict[\'preferred_accounting_transaction_source_section\'] = \\\n                                                          organisation_path\n    preference_dict[\'preferred_section\'] = organisation_path\n    preference.edit(**preference_dict)\n    bt5_obj = business_configuration.getSpecialiseValue()\n    current_template_preference_list = list(bt5_obj.getTemplatePreferenceList())\n    if preference.getId() not in current_template_preference_list:\n      current_template_preference_list.append(preference.getId())\n      bt5_obj.edit(template_preference_list=current_template_preference_list,)\n\n    return error_list'),(5063,'document.erp5.PortalTypeRolesSpreadsheetConfiguratorItem PortalTypeRolesSpreadsheetConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#                    Jerome Perrin <jerome@nexedi.com>\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom zLOG import LOG, INFO\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass PortalTypeRolesSpreadsheetConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"Import a portal type roles spreadsheet.\n  \"\"\"\n\n  meta_type = \'ERP5 Portal Type Roles Spreadsheet Configurator Item\'\n  portal_type = \'Portal Type Roles Spreadsheet Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.ConfiguratorItem\n                    )\n  def _checkConsistency(self, fixit=False, **kw):\n    portal = self.getPortalObject()\n    portal_type_role_dict = self._getPortalTypeRoleDict()\n    error_list = []\n    for type_name, role_list in portal_type_role_dict.items():\n      portal_type = portal.portal_types.getTypeInfo(type_name)\n      if portal_type is None:\n        LOG(\"CONFIGURATOR\", INFO, \"Fail to define Roles for %s\" % portal_type)\n        continue\n\n      for role in role_list:\n        # rebuild a category from Group / Site & Function\n        category_list = []\n        for bc in (\'Group\', \'Site\', \'Function\'):\n          if role.get(bc):\n            category_list.append(role[bc])\n        #category = \'\\n\'.join(category_list)\n        role_name_list = [x.strip() for x in role.get(\'Role\', \'\').split(\';\')]\n        error_list.append(self._createConstraintMessage(\n          \"Add roles(%s) to %s are required\" %  (role_name_list, portal_type)))\n        if fixit:\n          role_dict = {\n                      \'title\': role.get(\'Name\', \'Default\'),\n                      \'description\': role.get(\'Description\', \'Configured by ERP5 Configurator\'),\n                      \'role_name_list\': role_name_list,\n                      \'role_category_list\': category_list,\n                      \'role_base_category_list\': role.get(\'Base_Category\', \'\'),\n                      \'role_base_category_script_id\': role.get(\'Base_Category_Script\',\n                                            role.get(\'Script\', \'\'))}\n          portal_type.newContent(portal_type=\'Role Information\', \\\n                                **role_dict)\n\n    if fixit:\n      ## Update BT5\n      business_configuration = self.getBusinessConfigurationValue()\n      bt5_obj = business_configuration.getSpecialiseValue()\n      if bt5_obj is not None:\n        bt5_obj.edit(template_portal_type_role_list=list(portal_type_role_dict))\n\n    return error_list\n\n  def checkSpreadSheetConsistency(self):\n    \"\"\"Check that the spread sheet is consistent with categories spreadsheet.\n\n     - all roles have a name (\'Name\' or \'Role\')\n     - all roles have a portal type (\'Name\' or \'Role\')\n     - all roles uses valid group & function categories\n\n    XXX do we want to use constraint framework here ?\n    \"\"\"\n\n  def _getPortalTypeRoleDict(self):\n    \"\"\"Read the spreadsheet and provide processed dict.\n    \"\"\"\n    role_dict = {}\n    info_dict = self.ConfigurationTemplate_readOOCalcFile(\n                      \"portal_roles_spreadsheet.ods\",\n                      data=self.getDefaultConfigurationSpreadsheetData())\n\n    for table in info_dict.values():\n      for line in table:\n        if \'Portal_Type\' in line:\n          ptype_role_list = role_dict.setdefault(line[\'Portal_Type\'], [])\n          ptype_role_list.append(line)\n\n    return role_dict'),(5064,'document.erp5.PortalTypeConfiguratorItem PortalTypeConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#                    TAHARA Yusei <yusei@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass PortalTypeConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"Configure Portal Type.\"\"\"\n\n  meta_type = \'ERP5 Portal Type Configurator Item\'\n  portal_type = \'Portal Type Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    portal = self.getPortalObject()\n\n    # Support adding new property sheet to portal type information.\n    # arguments:\n    #  * target_portal_type\n    #  * add_propertysheet_list\n    portal_type_value = portal.portal_types[self.target_portal_type]\n    property_sheet_list = portal_type_value.getTypePropertySheetList()\n    extra_property_sheet_list = []\n    for name in self.add_propertysheet_list:\n      if name not in property_sheet_list:\n        extra_property_sheet_list.append(name)\n    # TODO: This class must support many other portal types features.\n    business_template_value = self.getBusinessConfigurationValue().getSpecialiseValue()\n    if extra_property_sheet_list:\n      if fixit:\n        portal_type_value.setTypePropertySheetList(\n          property_sheet_list + extra_property_sheet_list,\n        )\n        business_template_value.edit(\n          template_portal_type_property_sheet_list=list(\n            business_template_value.getTemplatePortalTypePropertySheetList()\n          ) + [\n            \'%s | %s\' % (self.target_portal_type, name)\n            for name in extra_property_sheet_list\n          ],\n        )\n      return [\n        self._createConstraintMessage(\n          \'Associate Property Sheets %r to %r in %r\' % (\n            extra_property_sheet_list,\n            self.target_portal_type,\n            business_template_value.getTitle(),\n          )\n        )\n      ]\n    return []'),(5065,'document.erp5.PersonConfiguratorItem PersonConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom Acquisition import aq_base\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom DateTime import DateTime\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass PersonConfiguratorItem(XMLObject, ConfiguratorItemMixin):\n  \"\"\" Setup user. \"\"\"\n\n  meta_type = \'ERP5 Person Configurator Item\'\n  portal_type = \'Person Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference\n                    , PropertySheet.Person\n                    , PropertySheet.Login)\n\n  def _checkConsistency(self, fixit=False, **kw):\n    error_list = []\n    person_list = self.acl_users.searchUsers(id=self.Person_getUserId(), exact_match=True)\n    if not person_list:\n      error_list.append(self._createConstraintMessage(\"Person %s should be created\" % self.Person_getUserId()))\n      if fixit:\n        person_module = self.getPortalObject().person_module\n        person = person_module.newContent(portal_type=\"Person\")\n        group_id = getattr(aq_base(self), \'group_id\', None)\n        site_id = getattr(aq_base(self), \'site_id\', None)\n\n        business_configuration = self.getBusinessConfigurationValue()\n        organisation_id = getattr(aq_base(self), \'organisation_id\', None)\n        if organisation_id is None:\n          organisation_id = business_configuration.\\\n                              getGlobalConfigurationAttr(\'organisation_id\')\n        if organisation_id is not None:\n          person.setCareerSubordination(\'organisation_module/%s\' % \\\n                                         organisation_id)\n\n        # save\n        person.edit(**{\'default_email_text\': self.getDefaultEmailText(),\n                      \'default_telephone_text\': self.getDefaultTelephoneText(),\n                      \'first_name\': self.getFirstName(),\n                      \'career_function\': self.getFunction(),\n                      \'last_name\': self.getLastName(),\n                      \'reference\': self.getReference(),\n                        })\n\n        assignment = person.newContent(portal_type=\"Assignment\",\n                                      function = self.getFunction(),\n                                      group = group_id,\n                                      site = site_id)\n\n        login = person.newContent(portal_type=\'ERP5 Login\',\n                                  reference=self.getReference(),\n                                  password=self.getPassword())\n\n        # Set dates are required to create valid assigments.\n        now = DateTime()\n        assignment.setStartDate(now)\n        # XXX Is it required to set stop date?\n        # Define valid for 10 years.\n        assignment.setStopDate(now + (365*10))\n\n        # Validate the Person, Assigment and Login\n        person.validate(comment=translateString(\"Validated by Configurator\"))\n        assignment.open(comment=translateString(\"Open by Configuration\"))\n        login.validate(comment=translateString(\"Validated by Configurator\"))\n        current_career = person.getDefaultCareerValue()\n        current_career.Career_setEmployeeNumber(batch=1)\n\n        ## add to customer template\n        business_configuration = self.getBusinessConfigurationValue()\n        self.install(person, business_configuration)\n\n    return error_list'),(5066,'document.erp5.PermissionConfiguratorItem PermissionConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass PermissionConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Set permission matrix on module.\"\"\"\n\n  meta_type = \'ERP5 Permission Configurator Item\'\n  portal_type = \'Permission Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    template_module_id_list = []\n    error_list = []\n    module_permissions_map = {}\n    business_configuration = self.getBusinessConfigurationValue()\n    sheets_dict = business_configuration.ConfigurationTemplate_readOOCalcFile(\\\n                           self.filename)\n    for module_id, permissions in sheets_dict.items():\n      module_permissions = {}\n      for permission in permissions:\n        roles = []\n        permission_name = permission.pop(\'permission\')\n        for role, checked in permission.items():\n          if checked == \'1\':  roles.append(role)\n        module_permissions[permission_name] = roles\n      # add to module map\n      module_permissions_map[module_id] = module_permissions\n\n    # set permissions in fake site\n    portal = self.getPortalObject()\n    for module_id, permissions_map in module_permissions_map.items():\n      if permissions_map != {}:\n        template_module_id_list.append(module_id)\n        module = portal[module_id]\n        for permission_name, roles in permissions_map.items():\n          # we must alway include additionally \'Manager\' and \'Owner\'\n          roles.extend([\'Manager\', \'Owner\'])\n          if fixit:\n            module.manage_permission(permission_name, tuple(roles), 0)\n          error_list.append(self._createConstraintMessage(\n            \'%s should be set to %s\' % (\',\'.join(roles), module.getId())))\n\n    # add customized module to customer\'s bt5\n    if len(template_module_id_list) and fixit:\n      bt5_obj = business_configuration.getSpecialiseValue()\n      bt5_obj.setTemplateModuleIdList(template_module_id_list)\n\n    return error_list'),(5067,'document.erp5.OrganisationConfiguratorItem OrganisationConfiguratorItem ##############################################################################\n#\n\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass OrganisationConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" This class install a Organisation.\"\"\"\n\n  meta_type = \'ERP5 Organisation Configurator Item\'\n  portal_type = \'Organisation Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Organisation )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    \"\"\" Setup organisation. \"\"\"\n    if fixit:\n      portal = self.getPortalObject()\n      organisation = portal.organisation_module.newContent(portal_type=\"Organisation\")\n\n      org_dict = {\'price_currency\': \'currency_module/%s\' % self.getPriceCurrency(),\n                  \'group\': self.getGroup(),\n                  \'title\': self.getTitle(),\n                  \'corporate_name\': self.getCorporateName(),\n                  \'default_address_city\': self.getDefaultAddressCity(),\n                  \'default_email_text\': self.getDefaultEmailText(),\n                  \'default_telephone_text\': self.getDefaultTelephoneText(),\n                  \'default_address_zip_code\': self.getDefaultAddressZipCode(),\n                  \'default_address_region\': self.getDefaultAddressRegion(),\n                  \'default_address_street_address\': self.getDefaultAddressStreetAddress(),\n                  \'site\':\'main\', # First customer\'s organisation is always main site.\n                  }\n      organisation.edit(**org_dict)\n\n      business_configuration = self.getBusinessConfigurationValue()\n      # store globally organization_id\n      business_configuration.setGlobalConfigurationAttr(organisation_id=organisation.getId())\n\n      if self.portal_workflow.isTransitionPossible(organisation, \'validate\'):\n        organisation.validate(comment=translateString(\"Validated by Configurator\"))\n\n      ## add to customer template\n      self.install(organisation, business_configuration)\n    return [self._createConstraintMessage(\'Organisation should be created\')]'),(5068,'document.erp5.CustomerBT5ConfiguratorItem CustomerBT5ConfiguratorItem ##############################################################################\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass CustomerBT5ConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Create a new bt5 for customer configuration.\n\n      This business template is not installed locally, only build.\n  \"\"\"\n\n  meta_type = \'ERP5 Customer BT5 Configurator Item\'\n  portal_type = \'Customer BT5 Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    template_tool = self.getPortalObject().portal_templates\n    error_list = []\n    if self.bt5_title not in template_tool.getBuiltBusinessTemplateList():\n      error_list.append(self._createConstraintMessage(\n        \'%s should be created\' % self.bt5_title))\n\n    if fixit:\n      bt5 = template_tool.newContent(portal_type=\"Business Template\",\n          title=self.bt5_title)\n      business_configuration = self.getBusinessConfigurationValue()\n      business_configuration.setSpecialise(bt5.getRelativeUrl())\n\n    return error_list'),(5069,'document.erp5.CurrencyConfiguratorItem CurrencyConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass CurrencyConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup currency. \"\"\"\n\n  meta_type = \'ERP5 Currency Configurator Item\'\n  portal_type = \'Currency Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Price\n                    , PropertySheet.Resource\n                    , PropertySheet.Reference )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    currency_module = self.getPortalObject().currency_module\n    error_list = []\n    title = self.getTitle()\n    reference = self.getReference()\n    # XXX FIXME This is not exactly desired behaviour\n    currency = self.portal_catalog.getResultValue(id=reference,\n                                                  portal_type=\"Currency\")\n    if currency is None:\n      error_list.append(self._createConstraintMessage(\n        \"Currency %s should be created\" % reference))\n      if fixit:\n        currency = currency_module.newContent(portal_type = \"Currency\",\n                                            id = reference,\n                                            title = title,\n                                            reference = reference,\n                                            base_unit_quantity=self.getBaseUnitQuantity())\n        currency.validate(comment=translateString(\"Validated by Configurator\"))\n\n    if currency:\n      business_configuration = self.getBusinessConfigurationValue()\n      business_configuration.setGlobalConfigurationAttr(currency_id=currency.getId())\n      ## add to customer template\n      self.install(currency, business_configuration)\n\n    return error_list'),(5070,'document.erp5.ConfigurationSave ConfigurationSave ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.Path import Path\n\nclass ConfigurationSave(Path):\n  \"\"\" This class is the base class for all template items. \"\"\"\n\n  portal_type = \'Configuration Save\'\n  meta_type = \'ERP5 Configuration Save\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.SortIndex )\n\n  def addConfigurationItem(self, configuration_item_class_name, **kw):\n    \"\"\" Add new configuration item. \"\"\"\n    ## remove manually specified a configration title\n    return self.newContent(portal_type=configuration_item_class_name,\n                           **kw)'),(5071,'document.erp5.CategoryConfiguratorItem CategoryConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass CategoryConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"This class is meta build step for customization of ERP5 site.\"\"\"\n\n  meta_type = \'ERP5 Category Configurator Item\'\n  portal_type = \'Category Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore)\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n      category_root = portal.portal_categories[self.category_root]\n      object_id = self.object_id\n      if object_id in category_root.objectIds():\n        category_root.manage_delObjects(object_id)\n      category = category_root.newContent(portal_type=\'Category\',\n                                          id = object_id,\n                                          title = self.getTitle())\n      ## add to customer template\n      business_configuration = self.getBusinessConfigurationValue()\n      self.install(category, business_configuration)\n    return [self._createConstraintMessage(\'Category %s should be created\' % self.getTitle())]'),(5072,'document.erp5.CategoriesSpreadsheetConfiguratorItem CategoriesSpreadsheetConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#                    Jerome Perrin <jerome@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nimport io\nfrom Acquisition import aq_base\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\nimport six\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass CategoriesSpreadsheetConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"Import a categories spreadsheet.\n  \"\"\"\n\n  meta_type = \'ERP5 Categories Spreadsheet Configurator Item\'\n  portal_type = \'Categories Spreadsheet Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.ConfiguratorItem\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    portal = self.getPortalObject()\n    ctool = portal.portal_categories\n\n    self._readSpreadSheet()\n    cache = self._category_cache\n    object_id_list = ctool.objectIds()\n    error_list = []\n    for bc_id, category_list in cache.items():\n      if bc_id in object_id_list:\n        bc = ctool._getOb(bc_id)\n      else:\n        # TODO: test bc creation\n        # the bc should be added as base category in bt5 ?\n        error_list.append(self._createConstraintMessage(\n          \"Base Category %s should be created\" % bc_id))\n        if fixit:\n          bc = ctool.newContent(id=bc_id)\n        else:\n          continue\n\n      if fixit:\n        for category_info in category_list:\n          path = bc\n          for cat in category_info[\'path\'].split(\"/\")[1:]:\n            if not cat in path.objectIds():\n              path = path.newContent(\n                portal_type=\'Category\',\n                id=cat,)\n            else:\n              path = path[cat]\n          edit_dict = category_info.copy()\n          edit_dict.pop(\'path\')\n          edit_dict.pop(\'id\', None)\n          path.edit(**edit_dict)\n          ## add to customer template\n          business_configuration = self.getBusinessConfigurationValue()\n          self.install(path, business_configuration)\n      else:\n        error_list.extend([\n            self._createConstraintMessage(\"%s should be created\" % category[\'path\'])\n            for category in category_list])\n\n    return error_list\n\n  def _readSpreadSheet(self):\n    \"\"\"Read the spreadsheet and prepare internal category cache.\n    \"\"\"\n    aq_self = aq_base(self)\n    if getattr(aq_self, \'_category_cache\', None) is None:\n      # TODO use a invalid_spreadsheet_error_handler to report invalid\n      # spreadsheet messages (see http://svn.erp5.org?rev=24908&view=rev )\n      aq_self._category_cache = self.Base_getCategoriesSpreadSheetMapping(\n                    io.BytesIO(self.getDefaultConfigurationSpreadsheetData()))\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                           \'setDefaultConfigurationSpreadsheetFile\')\n  def setDefaultConfigurationSpreadsheetFile(self, *args, **kw):\n    \"\"\"Reset the spreadsheet cache.\"\"\"\n    self._setDefaultConfigurationSpreadsheetFile(*args, **kw)\n    self._category_cache = None\n    self.reindexObject()\n\n  security.declareProtected(Permissions.ModifyPortalContent,\n                           \'setConfigurationSpreadsheetFile\')\n  setConfigurationSpreadsheetFile = setDefaultConfigurationSpreadsheetFile\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                           \'getCategoryTitleItemList\')\n  def getCategoryTitleItemList(self, base_category_id, base=0):\n    \"\"\"Returns title item list for a base category contained in this\n    spreadsheet.\n    \"\"\"\n    self._readSpreadSheet()\n    cache = self._category_cache\n\n    result = [(\'\', \'\')]\n    if base_category_id not in cache:\n      return result # TODO: return some kind of default. Where is this\n                    # default ??? configurator_%s % base_category_id ?\n                    # If we add default here, it should also be used in build\n                    # ...\n\n    category_path_dict = {item[\'path\']: item\n      for item in cache[base_category_id]}\n\n    for path in six.iterkeys(category_path_dict):\n      # the first item in this list is the base category itself, so we skip it.\n      if path == base_category_id:\n        continue\n\n      # recreate logical path\n      path_element_list = []\n      title_list = []\n      for path_element in path.split(\'/\'):\n        path_element_list.append(path_element)\n        title_list.append(category_path_dict[\'/\'.join(path_element_list)][\'title\'])\n\n      if base:\n        result.append((\'/\'.join(title_list[1:]), path))\n      else:\n        result.append((\'/\'.join(title_list[1:]),\n                       \'/\'.join(path.split(\'/\')[1:])))\n\n    return sorted(result)'),(5073,'document.erp5.CatalogKeywordKeyConfiguratorItem CatalogKeywordKeyConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Yoshinori Okuji <yo@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\n\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass CatalogKeywordKeyConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\"Set up catalog keyword keys.\"\"\"\n\n  meta_type = \'ERP5 Catalog Keyword Key Configurator Item\'\n  portal_type = \'Catalog Keyword Key Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    error_list = []\n    portal = self.getPortalObject()\n    catalog = portal.portal_catalog.getSQLCatalog()\n    key_list = list(catalog.getSqlCatalogSearchKeysList())\n    for k in self.key_list:\n      if k not in key_list:\n        error_list.append(self._createConstraintMessage(\n          \"%s should be in sql_catalog_keyword_search_keys\" % k))\n        key_list.append(k)\n    key_list = tuple(key_list)\n    if fixit:\n      catalog._setPropValue(\'sql_catalog_keyword_search_keys\', key_list)\n      business_configuration = self.getBusinessConfigurationValue()\n      bt = business_configuration.getSpecialiseValue()\n      bt.edit(template_catalog_keyword_key_list=key_list)\n\n    return error_list'),(5074,'document.erp5.BusinessProcessConfiguratorItem BusinessProcessConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass BusinessProcessConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Rules. \"\"\"\n\n  meta_type = \'ERP5 Business Process Configurator Item\'\n  portal_type = \'Business Process Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.ConfiguratorItem\n                    , PropertySheet.Reference\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    error_list = [\n        self._createConstraintMessage(\"Business Process %s should be created\" % self.getReference())]\n    if fixit:\n      portal = self.getPortalObject()\n      business_process = portal.business_process_module.newContent(\n                                            portal_type=\"Business Process\",\n                                            reference=self.getReference(),\n                                            title=self.getTitle())\n      business_configuration = self.getBusinessConfigurationValue()\n      business_configuration.setGlobalConfigurationAttr(\\\n                    business_process_id=business_process.getId())\n      # XXX for the standard cases, also set configuration attributes that\n      # Sale/Purchase Configurator Item will use.\n      if self.getReference() == \'default_erp5_sale_business_process\':\n        business_configuration.setGlobalConfigurationAttr(\n            sale_business_process_id=business_process.getId())\n      elif self.getReference() == \'default_erp5_purchase_business_process\':\n        business_configuration.setGlobalConfigurationAttr(\n            purchase_business_process_id=business_process.getId())\n\n      business_process_dict = self._getBusinessProcessDict()\n      int_index = 0\n      for path_dict in business_process_dict[\"Trade Model Path\"]:\n        int_index += 1\n        path_dict.setdefault(\"int_index\", int_index)\n        title = path_dict.pop(\'title\')\n        trade_phase = path_dict.pop(\'trade_phase\')\n        trade_date = path_dict.pop(\'trade_date\')\n        for key in list(path_dict):\n          if path_dict[key] is None:\n            path_dict.pop(key)\n        self._addTradeModelPath(business_process=business_process,\n                                title=title,\n                                trade_phase=trade_phase,\n                                trade_date=trade_date,\n                                **path_dict)\n\n      int_index = 0\n      for link_dict in business_process_dict[\"Business Link\"]:\n        int_index += 1\n        link_dict.setdefault(\"int_index\", int_index)\n        title = link_dict.pop(\'title\')\n        trade_phase = link_dict.pop(\'trade_phase\')\n        delivery_builder = link_dict.pop(\'delivery_builder\', None)\n        predecessor = link_dict.pop(\'predecessor\', None)\n        successor = link_dict.pop(\'successor\', None)\n        for key in list(link_dict):\n          if link_dict[key] is None:\n            link_dict.pop(key)\n\n        self._addBusinessLink(business_process=business_process,\n                              title=title,\n                              trade_phase = trade_phase,\n                              predecessor = predecessor,\n                              successor = successor,\n                              delivery_builder = delivery_builder,\n                              **link_dict)\n\n      business_process.validate(comment=translateString(\'Validated by configurator\'))\n      self.install(business_process, business_configuration)\n\n    return error_list\n\n  def _getBusinessProcessDict(self):\n    \"\"\" Read the spreadsheet and return the configuration for\n        Trade Model Paths and Business Links.\n    \"\"\"\n    return self.ConfigurationTemplate_readOOCalcFile(\n                      \"standard_business_process.ods\",\n                      data=self.getDefaultConfigurationSpreadsheetData())\n\n\n\n  def _addTradeModelPath(\n      self,\n      business_process,\n      title,\n      trade_phase,\n      trade_date,\n      membership_criterion_base_category_list=None,\n      membership_criterion_category_list=None,\n      **kw):\n    \"\"\" Add a trade model path to the business process.\n    \"\"\"\n    reference = \"TMP-%s\" % \"-\".join(title.upper().strip().split(\" \"))\n    path_id = \"%s_path\" %  \"_\".join(title.lower().strip().split(\" \"))\n    trade_model_path = business_process.newContent(\n                                portal_type = \"Trade Model Path\",\n                                id = path_id,\n                                title = title,\n                                reference = reference, **kw)\n\n    trade_model_path.setTradePhase(trade_phase)\n    if trade_date is not None:\n      trade_model_path.setTradeDate(\'trade_phase/%s\' % trade_date)\n\n    if membership_criterion_base_category_list:\n      trade_model_path.setMembershipCriterionBaseCategoryList(\n          membership_criterion_base_category_list.split(\",\"))\n    if membership_criterion_category_list:\n      trade_model_path.setMembershipCriterionCategoryList(\n          membership_criterion_category_list.split(\",\"))\n\n  def _addBusinessLink(self, business_process, title, trade_phase, predecessor,\n                             successor, delivery_builder, **kw):\n    link_id = \"%s_link\" %  \"_\".join(title.lower().strip().split(\" \"))\n    business_link = business_process.newContent(\n                                portal_type = \"Business Link\",\n                                id=link_id,\n                                title = title,**kw)\n\n    completed_state = kw.pop(\"completed_state\", None)\n    if completed_state is not None:\n      business_link.setCompletedStateList(completed_state.split(\",\"))\n\n    frozen_state = kw.pop(\"frozen_state\", None)\n    if frozen_state is not None:\n      business_link.setFrozenStateList(frozen_state.split(\",\"))\n\n    business_link.setTradePhase(trade_phase)\n    if successor is not None:\n      business_link.setSuccessor(\"trade_state/%s\" % successor)\n    if predecessor is not None:\n      business_link.setPredecessor(\"trade_state/%s\" % predecessor)\n\n    if delivery_builder is not None:\n      business_link.setDeliveryBuilderList(\n             [\"delivery_builder/portal_deliveries/%s\" % \\\n                  i for i in delivery_builder.split(\",\")])'),(5075,'document.erp5.BusinessConfiguration BusinessConfiguration ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Persistence import PersistentMapping\nfrom Acquisition import aq_base\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom zLOG import LOG, ERROR\n\nfrom erp5.component.tool.ConfiguratorTool import _validateFormToRequest\nfrom erp5.component.document.Item import Item\n\n## Workflow states definitions\nINITIAL_STATE_TITLE = \'Start\'\nDOWNLOAD_STATE_TITLE = \'Download\'\nEND_STATE_TITLE = \'End\'\n\n## Methods defined in Configurator Workflow (workflow_module) implementation\n## but not needed for generic ERP5 Workflow (portal_workflow) implementation\ndef initializeDocument(workflow, document):\n  \"\"\"\n  Set initial state on the Document\n  \"\"\"\n  state_bc_id = workflow.getStateBaseCategory()\n  document.setCategoryMembership(state_bc_id, workflow.getSource())\n\n  obj = workflow.getStateChangeInformation(document, workflow.getSourceValue())\n\n  # Initialize workflow history\n  status_dict = {state_bc_id: workflow.getSource()}\n  for variable in workflow.getVariableValueList():\n    status_dict[variable.getTitle()] = variable.getVariableDefaultExpression(object=obj)\n  _updateWorkflowHistory(workflow, document, status_dict)\ndef _generateHistoryKey(workflow):\n  \"\"\"\n  Generate a key used in the workflow history.\n  \"\"\"\n  return workflow.getReference()\ndef getWorkflowHistory(state, document, remove_undo=0, remove_not_displayed=0):\n  \"\"\"\n  Return history tuple\n  \"\"\"\n  wh = document.workflow_history[_generateHistoryKey(state.getParentValue())]\n  result = []\n  # Remove undo\n  if not remove_undo:\n    result = [x.copy() for x in wh]\n  else:\n    result = []\n    for x in wh:\n      if \'undo\' in x and x[\'undo\'] == 1:\n        result.pop()\n      else:\n        result.append(x.copy())\n  return result\ndef _updateWorkflowHistory(workflow, document, status_dict):\n  \"\"\"\n  Change the state of the object.\n  \"\"\"\n  if workflow.getPortalType() in (\'Interaction Workflow\', \'InteractionWorkflowDefinition\'):\n    return\n\n  # Create history attributes if needed\n\n  if getattr(aq_base(document), \'workflow_history\', None) is None:\n    document.workflow_history = PersistentMapping()\n    # XXX this _p_changed is apparently not necessary\n    document._p_changed = 1\n\n  # Add an entry for the workflow in the history\n  workflow_key = workflow.getReference()\n  if workflow_key not in document.workflow_history:\n    document.workflow_history[workflow_key] = ()\n\n  # Update history\n  document.workflow_history[workflow_key] += (status_dict,)\n  # XXX this _p_changed marks the document modified, but only the\n  # PersistentMapping is modified\n  # document._p_changed = 1\n  # XXX this _p_changed is apparently not necessary\n  #document.workflow_history._p_changed = 1\ndef undoTransition(state, document):\n  \"\"\"\n  Reverse previous transition\n  \"\"\"\n  workflow = state.getParentValue()\n  wh = getWorkflowHistory(state, document, remove_undo=1)\n  status_dict = wh[-2]\n  # Update workflow state\n  state_bc_id = state.getParentValue().getStateBaseCategory()\n  document.setCategoryMembership(\n    state_bc_id,\n    workflow.getStateValueByReference(status_dict[state_bc_id]).getRelativeUrl())\n  # Update workflow history\n  status_dict[\'undo\'] = 1\n  _updateWorkflowHistory(workflow, document, status_dict)\n  # XXX\n  LOG(\"State, undo\", ERROR, \"Variable (like DateTime) need to be updated!\")\ndef _checkPermission(transition, document):\n  \"\"\"\n  Check if transition is allowed.\n  \"\"\"\n  expr_value = transition.getGuardExpression(evaluate=0)\n  if expr_value is not None:\n    # do not use \'getGuardExpression\' to calculate tales because\n    # it caches value which is bad. Instead do it manually\n    from Products.ERP5Type.Accessor.Base import _evaluateTales\n    value = _evaluateTales(document, expr_value)\n  else:\n    value = True\n  #print \"CALC\", expr_value, \'-->\', value\n  return value\ndef getAvailableTransitionList(state, document):\n  \"\"\"\n  Return available transitions only if they are accessible for the current document.\n  \"\"\"\n  result_list = []\n  for transition in state.getDestinationValueList():\n    value = _checkPermission(transition, document)\n    if value:\n      result_list.append(transition)\n  return result_list\nclass StateError(Exception):\n  \"\"\"\n  Must call only an available transition\n  \"\"\"\ndef executeTransition(state, transition, document, form_kw=None):\n  \"\"\"\n  Execute transition on the object.\n  \"\"\"\n  if transition not in getAvailableTransitionList(state, document):\n    raise StateError\n  else:\n    execute(transition, document, form_kw=form_kw)\ndef _executeBeforeScript(self, document, form_kw=None):\n  \"\"\"\n  Execute pre transition script.\n  \"\"\"\n  if form_kw is None:\n    form_kw = {}\n  script_id = getattr(self.aq_base, \'before_script_id\', None)\n  if script_id is not None:\n    script = getattr(document, script_id)\n    script(**form_kw)\ndef _changeState(self, document):\n  \"\"\"\n  Change the state of the object.\n  \"\"\"\n  state = self.getDestination()\n  if state is not None:\n    # Some transitions don\'t update the state\n    state_bc_id = self.getParentValue().getStateBaseCategory()\n    document.setCategoryMembership(state_bc_id, state)\ndef _executeAfterScript(self, document, form_kw=None):\n  \"\"\"\n  Execute post transition script.\n  \"\"\"\n  if form_kw is None:\n    form_kw = {}\n  script_id = getattr(self.aq_base, \'after_script_id\', None)\n  if script_id is not None:\n    script = getattr(document, script_id)\n    script(**form_kw)\ndef execute(self, document, form_kw=None):\n  \"\"\"\n  Execute transition.\n  \"\"\"\n  workflow = self.getParentValue()\n  # Call the before script\n  _executeBeforeScript(self, document)\n\n  # Modify the state\n  _changeState(self, document)\n\n  # Get variable values\n  status_dict = workflow.getCurrentStatusDict(document)\n  status_dict[\'undo\'] = 0\n\n  # Modify workflow history\n  state_bc_id = workflow.getStateBaseCategory()\n  state_object = document.unrestrictedTraverse(document.getCategoryMembershipList(state_bc_id)[0])\n  status_dict[state_bc_id] = state_object.getReference()\n  object_ = workflow.getStateChangeInformation(document, state_object, transition=self)\n\n  # Update all variables\n  expression_context = None\n  for variable in workflow.getVariableValueList():\n    if variable.getAutomaticUpdate():\n      # if we have it in form get it from there\n      # otherwise use default\n      variable_title = variable.getTitle()\n      if variable_title in form_kw:\n        status_dict[variable_title] = form_kw[variable_title]\n      else:\n        expression = variable.getVariableDefaultExpressionInstance()\n        if expression is not None:\n          if expression_context is None:\n            from Products.ERP5Type.Core.Workflow import createExpressionContext, StateChangeInfo\n            expression_context = createExpressionContext(StateChangeInfo(document, self, status_dict))\n          status_dict[variable_title] = expression(expression_context)\n\n  # Update all transition variables\n  if form_kw is not None:\n    object_.REQUEST.other.update(form_kw)\n  for variable in self.getTransitionVariableValueList():\n    status_dict[variable.getCausalityTitle()] = variable.getInitialValue(object=object_)\n\n  _updateWorkflowHistory(workflow, document, status_dict)\n\n  # Call the after script\n  _executeAfterScript(self, document, form_kw=form_kw)\n\nclass BusinessConfiguration(Item):\n  \"\"\"\n    BusinessConfiguration store the values enter by the wizard.\n  \"\"\"\n\n  meta_type = \'ERP5 Business Configuration\'\n  portal_type = \'Business Configuration\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Item\n                    , PropertySheet.Arrow\n                    , PropertySheet.BusinessConfiguration\n                    , PropertySheet.Comment\n                    )\n\n  security.declareProtected(Permissions.View, \'isInitialConfigurationState\')\n  def isInitialConfigurationState(self):\n    \"\"\" Check if the Business Configuration is on initial workflow state\n    \"\"\"\n    workflow = self.getResourceValue()\n    if workflow is not None:\n      return self.getCurrentState() == workflow.getSource()\n    return None\n\n  security.declareProtected(Permissions.View, \'isDownloadConfigurationState\')\n  def isDownloadConfigurationState(self):\n    \"\"\" Check if the Business Configuration is on Download State\n    \"\"\"\n    return self.getCurrentStateTitle() == DOWNLOAD_STATE_TITLE\n\n  security.declareProtected(Permissions.View, \'isEndConfigurationState\')\n  def isEndConfigurationState(self):\n    \"\"\" Check if the Business Configuration is on End State\n    \"\"\"\n    return self.getCurrentStateTitle() == END_STATE_TITLE\n\n  security.declareProtected(Permissions.ModifyPortalContent, \\\n      \'initializeWorkflow\')\n  def initializeWorkflow(self):\n    \"\"\" Initialize Related Workflow\"\"\"\n    workflow = self.getResourceValue()\n    if workflow is None:\n      return\n\n    workflow_history = getattr(self, \'workflow_history\', {})\n    if workflow.getReference() not in workflow_history:\n      if len(self.objectValues(\"ERP5 Configuration Save\")) > 0:\n        raise ValueError(\"Business Configuration Cannot be initialized, \\\n                          it contains one or more Configurator Save\")\n\n      # XXX: `state_base_category` points to the state category (usually\n      # \'current_state\'). Without this, getCurrentState() is None and nothing\n      # happens because getNextTransition() returns None in such case.\n      #\n      # But does the state category really need to be configured, or should\n      # state_base_category be removed and `current_state` used by default?\n      #   * No field to modify `state_base_category`.\n      #   * In erp5.git, it is always `current_state`.\n      #   * Some code using directly `getCurrentState()`.\n      self.setCategoryMembership(workflow.getStateBaseCategory(),\n                                 workflow.getSource())\n\n      workflow.notifyCreated(self)\n\n  security.declareProtected(Permissions.View, \'getNextTransition\')\n  def getNextTransition(self):\n    \"\"\" Return next transition. \"\"\"\n    current_state = self.getCurrentStateValue()\n    if current_state is None:\n      return None\n    transition_list = getAvailableTransitionList(current_state, self)\n    transition_number = len(transition_list)\n    if transition_number > 1:\n      raise TypeError(\"More than one transition is available.\")\n    elif transition_number == 0:\n      return None\n\n    return transition_list[0]\n\n  security.declarePrivate(\'_executeTransition\')\n  def _executeTransition(self, \\\n                        form_kw=None,\n                        request_kw=None):\n    \"\"\" Execute the transition. \"\"\"\n    if form_kw is None:\n      form_kw = {}\n    current_state = self.getCurrentStateValue()\n    transition = self.getNextTransition()\n    ## it\'s possible that we have already saved a configuration save object\n    ## in workflow_history for this state so we use it\n    configuration_save = self._getConfSaveForStateFromWorkflowHistory()\n    if configuration_save is None:\n      ## we haven\'t saved any configuration save for this state so create new one\n      configuration_save = self.newContent(portal_type=\'Configuration Save\',\n                                           title=current_state.getTitle())\n    else:\n      ## we have already created configuration save for this state\n      ## so remove from it already existing configuration items\n      if configuration_save != self:  # don\'t delete ourselves\n        existing_conf_items = list(configuration_save.objectIds())\n        if existing_conf_items:\n          configuration_save.manage_delObjects(existing_conf_items)\n\n    modified_form_kw = {}\n    for k in form_kw.keys():\n      if form_kw[k].__class__.__name__ != \'FileUpload\':\n        modified_form_kw[k] = form_kw[k]\n    configuration_save.edit(**modified_form_kw)\n    ## Add some variables so we can get use them in workflow after scripts\n    form_kw[\'configuration_save_url\'] = configuration_save.getRelativeUrl()\n    form_kw[\'transition\'] = transition.getRelativeUrl()\n    executeTransition(current_state, transition, self, form_kw=form_kw)\n\n  security.declarePrivate(\'_displayNextForm\')\n  def _displayNextForm(self, \\\n                       validation_errors=None, \\\n                       context=None, \\\n                       transition=None):\n    \"\"\" Render next form. \"\"\"\n    if transition is None:\n      transition = self.getNextTransition()\n    while transition is not None:\n      form_id = transition.getTransitionFormId()\n      if self.isDownloadConfigurationState():\n        ## exec next transition for this business configuration\n        self._executeTransition()\n        transition = self.getNextTransition()\n        return None, None, None, None\n      if form_id is None:\n        ## go on until you find a form\n        self._executeTransition()\n        transition = self.getNextTransition()\n      else:\n        if context is None:\n          ## examine workflow_history for already saved\n          ## \'Configuration Save\' objects for this state\n          context = self._getConfSaveForStateFromWorkflowHistory()\n        ## get form object in a proper context\n        form_html, form_title = self._renderFormInContext(form_id, context, validation_errors)\n        ## check if we\'ve can shown \'Previous\' button\n        previous = None\n        translate = self.Base_translateString\n        if self._isAlreadyConfSaveInWorkflowHistory(transition):\n          previous = translate(\"Previous\")\n        return previous, form_html, form_title, \\\n               translate(transition.getTitle())\n\n  security.declarePrivate(\'_renderFormInContext\')\n  def _renderFormInContext(self, form_id, context, validation_errors):\n    html = \"\"\n    html_forms = []\n    isMultiEntryTransition = self._isMultiEntryTransition()\n    forms_number = isMultiEntryTransition\n    if context is None:\n      form = getattr(self, form_id)\n      if not isMultiEntryTransition:\n        if validation_errors is not None:\n          self.REQUEST.set(\'field_errors\', form.ErrorFields(validation_errors))\n        html = form()\n      else:\n        template_html = form()\n        for form_counter in range(0, forms_number):\n          form_html = self.Base_mainConfiguratorFormTemplate(\n                                  current_form_number=form_counter + 1,\n                                  max_form_numbers=forms_number,\n                                  form_title=form.title,\n                                  form_html=template_html)\n          html_forms.append(form_html)\n    else:\n      if not isMultiEntryTransition:\n        ## only one form saved under this context\n        form = getattr(context, form_id)\n        if validation_errors is not None:\n          self.REQUEST.set(\'field_errors\', form.ErrorFields(validation_errors))\n        html = form()\n      else:\n        ## we have many forms saved under this context\n        form = getattr(self, form_id)\n        field_ids = form.get_fields()\n        for form_counter in range(0, forms_number):\n          ## fill REQUEST with data as it will be used to render form\n          for field in field_ids:\n            field_value = getattr(context, \"field_%s\" % field.id, None)\n            if field_value is not None and len(field_value) > form_counter:\n              field_value = field_value[form_counter]\n              self.REQUEST.set(field.id, field_value)\n            else:\n              self.REQUEST.set(field.id, \'\')\n          form_html = self.Base_mainConfiguratorFormTemplate( \\\n                             current_form_number=form_counter + 1,\\\n                             max_form_numbers=forms_number,\\\n                             form_html=getattr(context, form_id)())\n          html_forms.append(form_html)\n    if html_forms != []:\n      html = \"\\n\".join(html_forms)\n    title = form.title\n    return html, title\n\n  security.declarePrivate(\'_displayPreviousForm\')\n  def _displayPreviousForm(self):\n    \"\"\" Render previous form using workflow history. \"\"\"\n    workflow_history = getWorkflowHistory(self.getCurrentStateValue(), self, remove_undo=1)\n    workflow_history.reverse()\n    for wh in workflow_history:\n      ## go one step back\n      current_state = self.getCurrentStateValue()\n      undoTransition(current_state, self)\n      if not wh[\'transition\']:\n        raise ValueError(\"Empty URL for transition in workflow history.\")\n      transition = self.unrestrictedTraverse(wh[\'transition\'])\n      conf_save = self.unrestrictedTraverse(wh[\'configuration_save_url\'])\n      ## check if this transition can be shown to user ...\n      if _checkPermission(transition, self) and \\\n           transition.getTransitionFormId() is not None:\n        return  self._displayNextForm(context=conf_save, transition=transition)\n\n  security.declarePrivate(\'_validateNextForm\')\n  def _validateNextForm(self, **kw):\n    \"\"\" Validate the form displayed to the user. \"\"\"\n    REQUEST = self.REQUEST\n    form = getattr(self, self.getNextTransition().getTransitionFormId())\n    return _validateFormToRequest(form, REQUEST, **kw)\n\n  security.declarePrivate(\'_getConfSaveForStateFromWorkflowHistory\')\n  def _getConfSaveForStateFromWorkflowHistory(self):\n    \"\"\" Get from workflow history configuration save for this state \"\"\"\n    configuration_save = None\n    current_state = self.getCurrentStateValue()\n    transition = self.getNextTransition()\n    next_state = self.unrestrictedTraverse(transition.getDestination())\n    workflow = current_state.getParentValue()\n    for wh in getWorkflowHistory(current_state, self):\n      if next_state == workflow.getStateValueByReference(wh[\'current_state\']):\n        configuration_save = self.unrestrictedTraverse(wh[\'configuration_save_url\'])\n    return configuration_save\n\n  security.declarePrivate(\'_isAlreadyConfSaveInWorkflowHistory\')\n  def _isAlreadyConfSaveInWorkflowHistory(self, transition):\n    \"\"\" check if we have an entry in worklow history for this state \"\"\"\n    current_state = self.getCurrentStateValue()\n    workflow = current_state.getParentValue()\n    workflow_history = getWorkflowHistory(current_state, self, remove_undo=1)\n    workflow_history.reverse()\n    for wh in workflow_history:\n      wh_state = workflow.getStateValueByReference(wh[\'current_state\'])\n      for wh_transition in getAvailableTransitionList(wh_state, self):\n        if wh_transition.getTransitionFormId() is not None and \\\n           wh_transition != transition:\n          return True\n    return False\n\n  security.declarePrivate(\'_isMultiEntryTransition\')\n  def _isMultiEntryTransition(self):\n    \"\"\" Return number of multiple forms to show for a transition. \"\"\"\n    next_transition = self.getNextTransition()\n    if next_transition is not None:\n      if getattr(aq_base(self), \'_multi_entry_transitions\', None) is not None:\n        multi_forms = self._multi_entry_transitions.get(next_transition.getRelativeUrl(), 0)\n        if multi_forms == 1:\n          # we have set \'1\' which means show one form which is not multiple forms\n          multi_forms = 0\n        return multi_forms\n      else:\n        return 0\n    else:\n      ## no transitions available\n      return 0\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'setMultiEntryTransition\')\n  def setMultiEntryTransition(self, transition_url, max_entry_number):\n    \"\"\" Set a transition as multiple - i.e max_entry_number of forms\n        which will be rendered. This method is called in after scripts\n        and usually this number is set by user in a web form. \"\"\"\n    if getattr(aq_base(self), \'_multi_entry_transitions\', None) is None:\n      self._multi_entry_transitions = PersistentMapping()\n    self._multi_entry_transitions[transition_url] = max_entry_number\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'setGlobalConfigurationAttr\')\n  def setGlobalConfigurationAttr(self, **kw):\n    \"\"\" Set global business configuration attribute. \"\"\"\n    if getattr(aq_base(self),\n               \'_global_configuration_attributes\', None) is None:\n      self._global_configuration_attributes = PersistentMapping()\n    for key, value in kw.items():\n      self._global_configuration_attributes[key] = value\n\n  security.declareProtected(Permissions.View, \'getGlobalConfigurationAttr\')\n  def getGlobalConfigurationAttr(self, key, default=None):\n    \"\"\" Get global business configuration attribute. \"\"\"\n    return getattr(self, \'_global_configuration_attributes\', {}).get(key, default)\n\n  ############# Instance and Business Configuration ########################\n  security.declareProtected(Permissions.ModifyPortalContent, \'buildConfiguration\')\n  def buildConfiguration(self):\n    \"\"\"\n      Build list of business templates according to already saved\n      Configuration Saves (i.e. user input).\n      This is the actual implementation which can be used from workflow\n      actions and Configurator requets\n    \"\"\"\n    kw = dict(tag=\"start_configuration_%s\" % self.getId(),\n              after_method_id=[\"updateBusinessTemplateFromUrl\",\n                               \"immediateReindexObject\"])\n    # build\n    configuration_save_list = self.contentValues(portal_type=\'Configuration Save\')\n    configuration_save_list.sort(key=lambda x: (x.getIntIndex(x.getIntId()) or 0))\n    for configuration_save in configuration_save_list:\n      # XXX: check which items are configure-able\n      configuration_item_list = configuration_save.contentValues()\n      configuration_item_list.sort(key=lambda x: (x.getIntId() or 0))\n\n      for configurator_item in configuration_item_list:\n        configurator_item.activate(**kw).fixConsistency(\n            filter={\"constraint_type\":\"configuration\"})\n        kw[\"after_tag\"] = kw[\"tag\"]\n        kw[\"tag\"] = \"configurator_item_%s_%s\" % (configurator_item.getId(),\n                                                 configurator_item.getUid())\n\n    kw[\"tag\"] = \"final_configuration_step_%s\" % self.getId()\n    kw[\"after_method_id\"] = [\"fixConsistency\", \'immediateReindexObject\']\n\n    self.activate(**kw).ERP5Site_afterConfigurationSetup()\n\n    if self.portal_workflow.isTransitionPossible(self, \'install\'):\n      self.activate(after_tag=kw[\"tag\"]).install()\n\n  # Business Configuration are Item, which inherits from Amount and expect the\n  # resource category document to be an actual resource, but in the case of\n  # Business Configuration it is a Workflow.\n  security.declareProtected(Permissions.AccessContentsInformation, \'getPrice\')\n  def getPrice(self, *args, **kw):\n    \"\"\"Business Configuration have no price\n    \"\"\"\n    return None\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getBaseUnitPrice\')\n  def getBaseUnitPrice(self, *args, **kw):\n    \"\"\"Business Configuration have no base unit price\n    \"\"\"\n    return None\n\n  security.declareProtected(Permissions.AccessContentsInformation, \'getVariationBaseCategoryList\')\n  def getVariationBaseCategoryList(self, *args, **kw):\n    \"\"\"Business Configuration have no variation base category list\n    \"\"\"\n    return []'),(5076,'document.erp5.BankAccountConfiguratorItem BankAccountConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom DateTime import DateTime\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass BankAccountConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup bank account. \"\"\"\n\n  meta_type = \'ERP5 Bank Account Configurator Item\'\n  portal_type = \'Bank Account Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.BankAccount )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    organisation_module = self.getPortalObject().organisation_module\n    error_list = []\n\n    business_configuration = self.getBusinessConfigurationValue()\n    organisation_id = business_configuration.\\\n                         getGlobalConfigurationAttr(\'organisation_id\')\n    organisation = organisation_module.get(organisation_id, None)\n    if organisation is not None:\n      bank_account_list = organisation.objectValues(portal_type=\'Bank Account\')\n      if not bank_account_list:\n        error_list.append(self._createConstraintMessage(\n           \"Bank Account should be created\"))\n\n        if fixit:\n          bank_account = organisation.newContent(portal_type=\"Bank Account\")\n\n          now = DateTime()\n          start_date = self.getStartDate(now)\n          stop_date = self.getStopDate(now + (365*10))\n\n          bank_dict = {\'bank_account_holder_name\' : self.getBankAccountHolderName(),\n                  \'title\': self.getTitle(),\n                  \'bank_account_key\': self.getBankAccountKey(),\n                  \'bank_account_number\': self.getBankAccountNumber(),\n                  \'bank_code\': self.getBankCode(),\n                  \'bank_country_code\': self.getBankCountryCode(),\n                  \'bic_code\': self.getBicCode(),\n                  \'branch\': self.getBranch(),\n                  \'iban\': self.getIban(),\n                  \'internal_bank_account_number\': self.getInternalBankAccountNumber(),\n                  \'overdraft_facility\': self.getOverdraftFacility(),\n                  \'start_date\': start_date,\n                  \'stop_date\': stop_date,\n                  }\n          bank_account.edit(**bank_dict)\n\n          # store globally bank_account_id\n          business_configuration.setGlobalConfigurationAttr(bank_account_id=bank_account.getId())\n\n          if self.portal_workflow.isTransitionPossible(bank_account, \'validate\'):\n            bank_account.validate(comment=translateString(\"Validated by Configurator\"))\n\n    return error_list'),(5077,'document.erp5.AlarmConfiguratorItem AlarmConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2012 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\nfrom DateTime import DateTime\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass AlarmConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup an Alarm \"\"\"\n\n  meta_type = \'ERP5 Alarm Configurator Item\'\n  portal_type = \'Alarm Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Alarm\n                    , PropertySheet.Periodicity\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    portal_alarms = self.getPortalObject().portal_alarms\n    error_list = []\n    property_dict = {\n      \"active_sense_method_id\" : self.getActiveSenseMethodId(),\n      \"periodicity_hour_list\" : self.getPeriodicityHourList(),\n      \"periodicity_minute_list\": self.getPeriodicityMinuteList(),\n      \"periodicity_minute_frequency\": self.getPeriodicityMinuteFrequency(),\n      \"periodicity_month_list\": self.getPeriodicityMonthList(),\n      \"periodicity_month_day_list\": self.getPeriodicityMonthDayList(),\n      \"periodicity_start_date\": DateTime() - 1,\n      #\"periodicity_stop_date\": self.getPeriodicityStopDate(),\n      \"periodicity_week_list\": self.getPeriodicityWeekList(),\n                        }\n\n    alarm_id = self.getId()\n    alarm = getattr(portal_alarms, alarm_id, None)\n    if alarm is None:\n      error_list.append(self._createConstraintMessage(\n        \"Alarm %s should be created\" % alarm_id))\n      if fixit:\n        alarm = portal_alarms.newContent(id=alarm_id,\n                                        title=self.getTitle())\n        alarm.edit(**property_dict)\n\n        # Always enabled\n        alarm.setEnabled(True)\n\n    if alarm and fixit:\n      ## add to customer template\n      business_configuration = self.getBusinessConfigurationValue()\n      self.install(alarm, business_configuration)\n\n    return error_list'),(5078,'document.erp5.AdvancedSaleTradeConditionConfiguratorItem AdvancedSaleTradeConditionConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass AdvancedSaleTradeConditionConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Sale Trade Conditions. \"\"\"\n\n  meta_type = \'ERP5 Advanced Sale Trade Condition Configurator Item\'\n  portal_type = \'Advanced Sale Trade Condition Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n\n      business_configuration = self.getBusinessConfigurationValue()\n      business_process_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'sale_business_process_id\') or\\\n        business_configuration.getGlobalConfigurationAttr(\'business_process_id\')\n\n      organisation_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'organisation_id\')\n\n      currency_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'currency_id\')\n\n      bank_account_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'bank_account_id\')\n\n      trade_condition = portal.sale_trade_condition_module.newContent(\n                                            portal_type=\"Sale Trade Condition\",\n                                            reference=self.getReference(),\n                                            title=self.getTitle())\n\n      trade_condition.setSpecialise(\"business_process_module/%s\" %\\\n                        business_process_id)\n\n      trade_condition.setSource(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setSourceSection(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setPriceCurrency(\"currency_module/%s\" % currency_id)\n\n      trade_condition.setSourceDecision(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setSourceAdministration(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setSourcePayment(\"organisation_module/%s/%s\" % (organisation_id, bank_account_id))\n\n      trade_condition.validate(comment=translateString(\"Validated by Configurator\"))\n\n      self.install(trade_condition, business_configuration)\n\n    return [self._createConstraintMessage(\'Sale Trade Condition with reference %s should be created\' % \\\n        self.getReference(),)]'),(5079,'document.erp5.AdvancedPurchaseTradeConditionConfiguratorItem AdvancedPurchaseTradeConditionConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2011 Nexedi SA and Contributors. All Rights Reserved.\n#                    Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass AdvancedPurchaseTradeConditionConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup Purchase Trade Conditions. \"\"\"\n\n  meta_type = \'ERP5 Advanced Purchase Trade Condition Configurator Item\'\n  portal_type = \'Advanced Purchase Trade Condition Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Reference\n                    )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    if fixit:\n      portal = self.getPortalObject()\n      business_configuration = self.getBusinessConfigurationValue()\n      business_process_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'purchase_business_process_id\') or\\\n        business_configuration.getGlobalConfigurationAttr(\'business_process_id\')\n\n      organisation_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'organisation_id\')\n\n      currency_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'currency_id\')\n\n      bank_account_id = \\\n        business_configuration.getGlobalConfigurationAttr(\'bank_account_id\')\n\n      trade_condition = portal.purchase_trade_condition_module.newContent(\n                                            portal_type=\"Purchase Trade Condition\",\n                                            reference=self.getReference(),\n                                            title=self.getTitle(), )\n\n      trade_condition.setSpecialise(\"business_process_module/%s\" %\\\n                        business_process_id)\n\n      trade_condition.setDestination(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setDestinationSection(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setPriceCurrency(\"currency_module/%s\" % currency_id)\n\n      trade_condition.setDestinationDecision(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setDestinationAdministration(\"organisation_module/%s\" % organisation_id)\n      trade_condition.setDestinationPayment(\"organisation_module/%s/%s\" % (organisation_id, bank_account_id))\n\n      trade_condition.validate(comment=translateString(\"Validated by Configurator\"))\n\n      self.install(trade_condition, business_configuration)\n\n    return [self._createConstraintMessage(\'Purchase Trade Condition with reference %s should be created\' % \\\n        self.getReference(),)]'),(5080,'document.erp5.AccountingPeriodConfiguratorItem AccountingPeriodConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2008 Nexedi SA and Contributors. All Rights Reserved.\n#                    Jerome Perrin <jerome@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass AccountingPeriodConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup an Accounting Period. \"\"\"\n\n  meta_type = \'ERP5 Accounting Period Configurator Item\'\n  portal_type = \'Accounting Period Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Task )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    portal = self.getPortalObject()\n    business_configuration = self.getBusinessConfigurationValue()\n    organisation_id = business_configuration.\\\n                                 getGlobalConfigurationAttr(\'organisation_id\')\n    organisation = portal.organisation_module._getOb(organisation_id)\n    if fixit:\n      period = organisation.newContent(\n                              portal_type=\'Accounting Period\',\n                              start_date=self.getStartDate(),\n                              stop_date=self.getStopDate(),\n                              short_title=self.getShortTitle(),\n                              title=self.getTitle())\n\n      if self.portal_workflow.isTransitionPossible(period, \'start\'):\n        period.start(comment=\"Started by Configurator\")\n\n    # no need to \'install\' in the business template, because it\'s contain as\n    # subobject of an organisation we already added.\n    return [self._createConstraintMessage(\'Accounting Period %s should be created\' % self.getTitle())]'),(5081,'document.erp5.AccountConfiguratorItem AccountConfiguratorItem ##############################################################################\n#\n# Copyright (c) 2006 Nexedi SARL and Contributors. All Rights Reserved.\n#                    Ivan Tyagov <ivan@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\nimport zope.interface\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.XMLObject import XMLObject\nfrom Products.ERP5Type.Message import translateString\nfrom erp5.component.mixin.ConfiguratorItemMixin import ConfiguratorItemMixin\nfrom erp5.component.interface.IConfiguratorItem import IConfiguratorItem\n\n\n@zope.interface.implementer(IConfiguratorItem)\nclass AccountConfiguratorItem(ConfiguratorItemMixin, XMLObject):\n  \"\"\" Setup an Accounting Account. \"\"\"\n\n  meta_type = \'ERP5 Account Configurator Item\'\n  portal_type = \'Account Configurator Item\'\n  add_permission = Permissions.AddPortalContent\n  isPortalContent = 1\n  isRADContent = 1\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Declarative properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Account )\n\n  def _checkConsistency(self, fixit=False, **kw):\n    account_module = self.getPortalObject().account_module\n    account = None\n    account_id = getattr(self, \'account_id\', None)\n\n    error_list = []\n    error_list_append = lambda msg: error_list.append(\n        self._createConstraintMessage(msg))\n    extra_kw = {}\n    if account_id:\n      extra_kw[\'id\'] = account_id\n      account = getattr(account_module, account_id, None)\n\n    if account is None:\n      error_list_append(\"Account %s should be created\" % self.getTitle())\n      if fixit:\n        account = account_module.newContent(\n                    portal_type=\'Account\',\n                    title=self.getTitle(),\n                    account_type=self.getAccountType(),\n                    gap=self.getGap(),\n                    financial_section=self.getFinancialSection(),\n                    credit_account=self.isCreditAccount(),\n                    description=self.getDescription(),\n                    **extra_kw)\n    else:\n      error_list_append(\"Account %s should be updated\" % account.getRelativeUrl())\n      if fixit:\n        # Update existing account\n        if (self.getAccountType() != account.getAccountType()) and \\\n            (self.getFinancialSection() != account.getFinancialSection()):\n          raise ValueError(\"The Configurator is trying to overwrite previous configuration information (%s)\" % account.getRelativeUrl())\n\n        account.edit(title=self.getTitle(), description=self.getDescription())\n        gap_list = account.getGapList()\n        # Only include only the additional gap that do not collide.\n        if self.getGap() not in gap_list:\n          gap_list.append(self.getGap())\n          account.setGapList(gap_list)\n        account.setCreditAccount(self.isCreditAccount())\n\n    if account and fixit:\n      if self.portal_workflow.isTransitionPossible(account, \'validate\'):\n        account.validate(comment=translateString(\"Validated by Configurator\"))\n\n      ## add to customer template\n      business_configuration = self.getBusinessConfigurationValue()\n      self.install(account, business_configuration)\n\n    return error_list'),(5082,'module.erp5.ConfiguratorTestMixin ConfiguratorTestMixin ##############################################################################\n# coding: utf-8\n# Copyright (c) 2010 Nexedi SA and Contributors. All Rights Reserved.\n#                     Rafael Monnerat <rafael@nexedi.com>\n#                     Ivan Tyagov <ivan@nexedi.com>\n#                     Lucas Carvalho <lucas@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsability of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# garantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n#\n##############################################################################\n\n\nfrom DateTime import DateTime\nfrom AccessControl import Unauthorized\nfrom Products.ERP5Type.tests.ERP5TypeTestCase import ERP5TypeTestCase\nfrom Products.ERP5Type.tests.SecurityTestCase import SecurityTestCase\nfrom AccessControl.SecurityManagement import newSecurityManager\n\nclass TestLiveConfiguratorWorkflowMixin(SecurityTestCase):\n  \"\"\"\n    Configurator Mixin Class\n  \"\"\"\n  # The list of standard business templates that the configurator should force\n  # to install\n  expected_bt5_list = (\'erp5_simulation\',\n                       \'erp5_dhtml_style\',\n                       \'erp5_jquery\',\n                       \'erp5_jquery_ui\',\n                       \'erp5_ingestion_mysql_innodb_catalog\',\n                       \'erp5_ingestion\',\n                       \'erp5_web\',\n                       \'erp5_dms\',\n                       \'erp5_crm\',\n                       \'erp5_pdm\',\n                       \'erp5_trade\',\n                       \'erp5_knowledge_pad\',\n                       \'erp5_accounting\',\n                       \'erp5_invoicing\',\n                       \'erp5_configurator_standard_solver\',\n                       \'erp5_configurator_standard_trade_template\',\n                       \'erp5_configurator_standard_accounting_template\',\n                       \'erp5_configurator_standard_invoicing_template\',\n                       \'erp5_trade_knowledge_pad\',\n                       \'erp5_crm_knowledge_pad\',\n                       \'erp5_simplified_invoicing\',\n                       \'erp5_ods_style\',\n                       \'erp5_odt_style\',\n                       \'erp5_ooo_import\')\n\n  standard_bt5_list = (\'erp5_dhtml_style\',\n                         \'erp5_jquery_ui\',\n                         \'erp5_ingestion_mysql_innodb_catalog\',\n                         \'erp5_dms\',\n                         \'erp5_accounting\',\n                         \'erp5_crm\',\n                         \'erp5_graph_editor\',\n                         \'erp5_simplified_invoicing\',\n                         \'erp5_trade_knowledge_pad\',\n                         \'erp5_crm_knowledge_pad\',\n                         \'erp5_configurator_standard_solver\',\n                         \'erp5_configurator_standard_trade_template\',\n                         \'erp5_configurator_standard_accounting_template\',\n                         \'erp5_configurator_standard_invoicing_template\',\n                         \'erp5_ods_style\',\n                         \'erp5_odt_style\',\n                         \'erp5_ooo_import\',\n                         \'erp5_osoe_web_renderjs_ui\',\n)\n\n  def getBusinessTemplateList(self):\n    return (\'erp5_core_proxy_field_legacy\',\n        \'erp5_full_text_mroonga_catalog\',\n        \'erp5_base\',\n        \'erp5_configurator\',\n        \'erp5_configurator_standard\',)\n\n  def stepLogin(self, quiet=0, run=1, **kw):\n    uf = self.getPortal().acl_users\n    uf._doAddUser(\'test_configurator_user\', \'\',\n                              [\'Manager\', \'Assignee\', \'Assignor\',\n                               \'Associate\', \'Auditor\', \'Author\'], [])\n    user = uf.getUserById(\'test_configurator_user\').__of__(uf)\n    newSecurityManager(None, user)\n\n  def afterSetUp(self):\n    self.stepLogin()\n    self.loginByUserName(user_name=\'test_configurator_user\')\n    # XXX (lucas): The request is not clean between tests.\n    # So, we need to force the test to use a clean REQUEST\n    # Otherwise the next test will fail trying to validate the form,\n    # because the REQUEST has data from the previous step/test.\n    if getattr(self.app.REQUEST, \'default_other\', None) is None:\n      self.app.REQUEST.default_other = self.app.REQUEST.other.copy()\n    else:\n      self.stepCleanUpRequest()\n\n    self.restricted_security = 0\n    self.setupAutomaticBusinessTemplateRepository(\n                 searchable_business_template_list=[\"erp5_core\", \"erp5_base\"])\n\n    # it is required by SecurityTestCase\n    self.workflow_tool = self.portal.portal_workflow\n    self.portal.portal_activities.unsubscribe()\n\n  def beforeTearDown(self):\n    self.portal.portal_activities.subscribe()\n    ERP5TypeTestCase.beforeTearDown(self)\n\n  def setBusinessConfigurationWorkflow(self, business_configuration, workflow):\n    \"\"\" Set configurator workflow \"\"\"\n    business_configuration.setResource(workflow)\n\n  def assertCurrentStep(self, step_title, server_response):\n    \"\"\" Checks the current step title. \"\"\"\n    self.assertTrue(\n      \'<h2>%s</h2>\' % step_title in server_response[\'data\'],\n      \'Unable to guess current step title (expected:%s) in: \\n%s\' %\n      (step_title, server_response))\n\n  ### STEPS\n\n  def stepCleanUpRequest(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Restore clean up the request \"\"\"\n    self.app.REQUEST.other = self.app.REQUEST.default_other.copy()\n\n  def stepConfiguratorNext(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Go Next into Configuration \"\"\"\n    business_configuration = sequence.get(\"business_configuration\")\n    next_dict = sequence.get(\"next_dict\")\n    response_dict = self.portal.portal_configurator._next(\n                            business_configuration, next_dict)\n    sequence.edit(response_dict=response_dict)\n\n  def stepConfiguratorPrevious(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Go to the previous form. \"\"\"\n    business_configuration = sequence.get(\"business_configuration\")\n    next_dict = sequence.get(\"next_dict\")\n    response_dict = self.portal.portal_configurator._previous(\n                            business_configuration, next_dict)\n    sequence.edit(response_dict=response_dict)\n\n  def stepCheckBT5ConfiguratorItem(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check if the Configuration Item list is correct \"\"\"\n    business_configuration = sequence.get(\"business_configuration\")\n    # second one: install some standard business templates\n    standard_bt5_config_save = business_configuration[\'1\']\n    self.assertEqual(\n      set(self.standard_bt5_list),\n      {x.bt5_id for x in standard_bt5_config_save.contentValues()})\n\n    # third one: we create a business template to store customer configuration\n    custom_bt5_config_save = business_configuration[\'2\']\n    custom_bt5_config_item = custom_bt5_config_save[\'1\']\n    self.assertEqual(custom_bt5_config_item.getPortalType(),\n                      \'Customer BT5 Configurator Item\')\n    self.assertEqual(custom_bt5_config_item.bt5_title,\n          \'_\'.join(business_configuration.getTitle().strip().lower().split()))\n\n  def stepCheckConfigureOrganisationForm(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check if Confire Organisation step was showed \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    if \'command\' in response_dict:\n      self.assertEqual(\'show\', response_dict[\'command\'])\n    self.assertEqual(\'Configure Organisation\', response_dict[\'next\'])\n    self.assertCurrentStep(\'Your organisation\', response_dict)\n\n  def stepSetupOrganisationConfiguratorItem(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Create one Organisation \"\"\"\n    default_address_city = sequence.get(\'organisation_default_address_city\')\n    default_address_region = sequence.get(\'organisation_default_address_region\')\n    next_dict = dict(\n        field_your_title=\'My Organisation\',\n        field_your_default_email_text=\'me@example.com\',\n        field_your_default_telephone_text=\'01234567890\',\n        field_your_default_address_street_address=\'.\',\n        field_your_default_address_zip_code=\'59000\',\n        field_your_default_address_city=default_address_city,\n        field_your_default_address_region=default_address_region)\n    next_dict.update(**kw)\n    sequence.edit(next_dict=next_dict)\n\n  def stepCheckConfigureUserAccountNumberForm(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check if Configure Organisation step was showed \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    if \'command\' in response_dict:\n      self.assertEqual(\'show\', response_dict[\'command\'])\n    self.assertEqual(\'Configure user accounts number\', response_dict[\'next\'])\n    self.assertEqual(\'Previous\', response_dict[\'previous\'])\n    self.assertCurrentStep(\'Number of user accounts\', response_dict)\n\n  def stepSetupUserAccounNumberSix(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Create one more user account \"\"\"\n    next_dict = dict(\n          field_your_company_employees_number=self.company_employees_number)\n    sequence.edit(next_dict=next_dict)\n\n  def stepCheckConfigureMultipleUserAccountForm(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the multiple user account form \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    if \'command\' in response_dict:\n      self.assertEqual(\'show\', response_dict[\'command\'])\n    self.assertEqual(\'Previous\', response_dict[\'previous\'])\n    self.assertEqual(\'Configure user accounts\', response_dict[\'next\'])\n    self.assertCurrentStep(\'User accounts configuration\', response_dict)\n\n  def stepSetupMultipleUserAccountSix(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Create multiple user account \"\"\"\n    next_dict = {}\n    for user in self.user_list:\n      for k, v in user.items():\n        next_dict.setdefault(k, []).append(v)\n    sequence.edit(next_dict=next_dict)\n\n  def _getUserIdList(self, login_list):\n    user_id_dict = {\n      x[\'login\']: x[\'id\'] for x in self.portal.acl_users.searchUsers(\n        login=login_list,\n        exact_match=True,\n      )\n    }\n    self.assertSameSet(user_id_dict, login_list)\n    return user_id_dict.values()\n\n\n  def stepCheckMultiplePersonConfigurationItem(self, sequence=None, sequence_list=None, **kw):\n    \"\"\"\n      Check if multiple Person Configuration Item of the Business\n      Configuration have been created successfully.\n    \"\"\"\n    business_configuration = sequence.get(\"business_configuration\")\n    self.assertEqual(int(self.company_employees_number),\n                          business_configuration.getGlobalConfigurationAttr(\n                                                 \"company_employees_number\"))\n\n    configuration_save_list = business_configuration.contentValues(\n                                             portal_type=\'Configuration Save\')\n    person_business_configuration_save = None\n    for configuration_save in configuration_save_list:\n      person_item_list = configuration_save.contentValues(\n                                 portal_type=\'Person Configurator Item\')\n      if person_item_list:\n        person_business_configuration_save = configuration_save\n        break\n\n\n    self.assertEqual(int(self.company_employees_number),\n        len(person_business_configuration_save.contentValues()))\n    return person_business_configuration_save\n\n  def stepCheckConfigureAccountingForm(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the accounting form configuration. \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    if \'command\' in response_dict:\n      self.assertEqual(\'show\', response_dict[\'command\'])\n    self.assertEqual(\'Previous\', response_dict[\'previous\'])\n    self.assertEqual(\'Configure accounting\', response_dict[\'next\'])\n    self.assertCurrentStep(\'Accounting\', response_dict)\n\n  def stepSetupAccountingConfiguration(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Setup up the accounting configuration \"\"\"\n    accounting_plan=sequence.get(\'configuration_accounting_plan\')\n    next_dict = dict(field_your_accounting_plan=accounting_plan,\n                subfield_field_your_period_start_date_year=\'2008\',\n                subfield_field_your_period_start_date_month=\'01\',\n                subfield_field_your_period_start_date_day=\'01\',\n                subfield_field_your_period_stop_date_year=\'2008\',\n                subfield_field_your_period_stop_date_month=\'12\',\n                subfield_field_your_period_stop_date_day=\'31\',\n                field_your_period_title=\'2008\'\n           )\n    sequence.edit(next_dict=next_dict)\n\n  def stepCheckConfigurePreferenceForm(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the preference form \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    if \'command\' in response_dict:\n      self.assertEqual(\'show\', response_dict[\'command\'])\n    self.assertEqual(\'Previous\', response_dict[\'previous\'])\n    self.assertEqual(\'Configure ERP5 Preferences\', response_dict[\'next\'])\n    self.assertCurrentStep(\'Application preferences\', response_dict)\n\n  def _stepCheckAccountingConfigurationItemList(self, business_configuration,\n                                                      bt5_id,\n                                                      accounting_transaction_gap,\n                                                      gap):\n    \"\"\" Check the French accounting configuration item list \"\"\"\n    # 1. the localization business template\n    accounting_business_configuration_save = business_configuration.\\\n                      contentValues(portal_types=\'Configuration Save\')[-1]\n    bt5_business_configuration_item =\\\n          accounting_business_configuration_save[\'1\']\n    self.assertEqual(\'Standard BT5 Configurator Item\',\n            bt5_business_configuration_item.getPortalType())\n    self.assertEqual(bt5_id, bt5_business_configuration_item.bt5_id)\n\n    # 2. a preference\n    preference_buisiness_configurator_item_list =\\\n       accounting_business_configuration_save.contentValues(\n           portal_type=\'Preference Configurator Item\')\n    self.assertEqual(1, len(preference_buisiness_configurator_item_list))\n    preference_buisiness_configurator_item = \\\n        preference_buisiness_configurator_item_list[0]\n    self.assertEqual(accounting_transaction_gap,\n           preference_buisiness_configurator_item.getProperty(\n              \'preferred_accounting_transaction_gap\'))\n    self.assertEqual(self.preference_group,\n           preference_buisiness_configurator_item.getProperty(\n              \'preferred_accounting_transaction_section_category\'))\n\n    # 3. some pre-configured accounts\n    account_business_configuration_item =\\\n          accounting_business_configuration_save[\'2\']\n    self.assertEqual(\'Account Configurator Item\',\n            account_business_configuration_item.getPortalType())\n    self.assertEqual(\'capital\',\n        getattr(account_business_configuration_item, \'account_id\', \'not set\'))\n    self.assertEqual(\'equity\',\n            account_business_configuration_item.getAccountType())\n    self.assertEqual(gap, account_business_configuration_item.getGap())\n    self.assertEqual(\'equity/share_capital\',\n            account_business_configuration_item.getFinancialSection())\n\n    # title is translated here\n    title = account_business_configuration_item.getTitle()\n    self.assertIn(title, (\'Capital\', \'Gezeichnetes Kapital\', \'Уставный капитал\'))\n\n    # 4. An accounting period configuration item\n    accounting_period_configuration_item = \\\n        accounting_business_configuration_save[\'14\']\n    # this [\'14\'] will break when we\'ll add more accounts\n    self.assertEqual(\'Accounting Period Configurator Item\',\n        accounting_period_configuration_item.getPortalType())\n\n    self.assertEqual(DateTime(2008, 1, 1),\n        accounting_period_configuration_item.getStartDate())\n    self.assertEqual(DateTime(2008, 12, 31),\n        accounting_period_configuration_item.getStopDate())\n    self.assertEqual(\'2008\',\n        accounting_period_configuration_item.getShortTitle())\n\n  def stepCheckAccountingConfigurationItemListFrance(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the French accounting configuration item \"\"\"\n    self._stepCheckAccountingConfigurationItemList(\n                business_configuration=sequence.get(\"business_configuration\"),\n                bt5_id=\'erp5_accounting_l10n_fr\',\n                accounting_transaction_gap=\'gap/fr/pcg\',\n                gap=\'fr/pcg/1/10/101\')\n\n  def stepCheckAccountingConfigurationItemListGermany(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the German accounting configuration item \"\"\"\n    self._stepCheckAccountingConfigurationItemList(\n                business_configuration=sequence.get(\"business_configuration\"),\n                bt5_id=\'erp5_accounting_l10n_de_skr04\',\n                accounting_transaction_gap=\'gap/de/skr04\',\n                gap=\'de/skr04/3/1/2/1/1\')\n\n  def stepCheckAccountingConfigurationItemListBrazil(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the Brazilian accounting configuration item \"\"\"\n    self._stepCheckAccountingConfigurationItemList(\n                business_configuration=sequence.get(\"business_configuration\"),\n                bt5_id=\'erp5_accounting_l10n_br_extend\',\n                accounting_transaction_gap=\'gap/br/pcg\',\n                gap=\'br/pcg/2/2.4/2.4.1/2.4.1.01\')\n\n  def stepCheckAccountingConfigurationItemListRussia(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the Russian accounting configuration item \"\"\"\n    self._stepCheckAccountingConfigurationItemList(\n                business_configuration=sequence.get(\"business_configuration\"),\n                bt5_id=\'erp5_accounting_l10n_ru\',\n                accounting_transaction_gap=\'gap/ru/ru2000\',\n                gap=\'ru/ru2000/80\')\n\n  def stepSetupPreferenceConfiguration(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Setup the preference configuration \"\"\"\n\n    lang = sequence.get(\'configuration_lang\')\n    price_currency = sequence.get(\'configuration_price_currency\')\n    next_dict = dict(field_your_price_currency=price_currency,\n                field_your_preferred_date_order=\'dmy\',\n                field_your_lang=lang,\n                default_field_your_lang=1,)\n\n    currency_id = sequence.get(\'configuration_currency_reference\')\n    sequence.edit(next_dict=next_dict, currency_id=currency_id)\n\n  def stepCheckPreferenceConfigurationItemList(self, sequence=None, sequence_list=None, **kw):\n    \"\"\"\n      Check the creation of:\n      - Currency Configurator Item\n      - Service Configurator Item\n      - System Preference Configurator Item\n      - Standard BT5 Configurator Item\n    \"\"\"\n    currency_title = sequence.get(\'configuration_currency_title\')\n    currency_reference = sequence.get(\'configuration_currency_reference\')\n    bt5_id = sequence.get(\'configuration_lang\')\n    business_configuration = sequence.get(\"business_configuration\")\n\n    # this created a currency\n    preferences_business_configuration_save = business_configuration.\\\n                      contentValues(portal_types=\'Configuration Save\')[-1]\n\n    currency_business_configuration_item =\\\n          preferences_business_configuration_save[\'1\']\n    self.assertEqual(\'Currency Configurator Item\',\n          currency_business_configuration_item.getPortalType())\n    self.assertEqual(currency_title,\n          currency_business_configuration_item.getTitle())\n    self.assertEqual(0.01,\n          currency_business_configuration_item.getBaseUnitQuantity())\n    self.assertEqual(currency_reference,\n          currency_business_configuration_item.getReference())\n    # some services\n    # TODO\n    service_business_configuration_item =\\\n          preferences_business_configuration_save[\'2\']\n    self.assertEqual(\'Service Configurator Item\',\n                     service_business_configuration_item.getPortalType())\n    # and a preference\n    preference_business_configuration_item =\\\n          preferences_business_configuration_save[\'3\']\n    self.assertEqual(\'Preference Configurator Item\',\n        preference_business_configuration_item.getPortalType())\n    # that uses the currency\n    self.assertEqual(\'currency_module/%s\' % currency_reference,\n        preference_business_configuration_item.getProperty(\n             \'preferred_accounting_transaction_currency\'))\n\n    # system preferences\n    system_pref_configurator_item =\\\n        preferences_business_configuration_save[\'4\']\n    self.assertEqual(\'System Preference Configurator Item\',\n        system_pref_configurator_item.getPortalType())\n\n    # a standard bt5 for localisation\n    bt5_business_configuration_item =\\\n          preferences_business_configuration_save[\'5\']\n    self.assertEqual(\'Standard BT5 Configurator Item\',\n            bt5_business_configuration_item.getPortalType())\n    self.assertEqual(bt5_id,\n            bt5_business_configuration_item.bt5_id)\n\n  def stepCheckConfigureInstallationForm(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the installation form \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    # configuration is finished. We are at the Install state.\n    self.assertEqual(\'show\', response_dict[\'command\'])\n    self.assertEqual(\'Previous\', response_dict[\'previous\'])\n    self.assertEqual(\'Install\', response_dict[\'next\'])\n\n    self.assertCurrentStep(\'Download\', response_dict)\n\n  def stepSetupInstallConfiguration(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Install the Configuration \"\"\"\n    sequence.edit(next_dict={})\n\n  def stepCheckInstallConfiguration(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Check the installation of the configuration \"\"\"\n    response_dict = sequence.get(\"response_dict\")\n    self.assertEqual(\'install\', response_dict[\'command\'])\n\n  def _stepCheckInstanceIsConfigured(self, business_configuration, bt5_tuple):\n    \"\"\" Check if the instance is configured with proper business templates \"\"\"\n    # XXX FIXME (lucas): it should be a property of business configuration\n    bc_id = \'_\'.join(business_configuration.getTitle().strip().lower().split())\n\n    # check if bt5 are installed.\n    bt5_title_list = self.portal.portal_templates.getInstalledBusinessTemplateTitleList()\n    expected_list = self.expected_bt5_list + bt5_tuple\n    self.assertEqual([i for i in expected_list if i not in bt5_title_list], [])\n\n    self.assertNotIn(bc_id, bt5_title_list)\n\n    bt = business_configuration.getSpecialiseValue(portal_type=\"Business Template\")\n    self.assertEqual(bc_id, bt.getTitle())\n    self.assertEqual(bt.getInstallationState(), \'not_installed\')\n\n  def stepCheckConfiguredInstancePreference(self, sequence=None,  sequence_list=None, **kw):\n    \"\"\" Check if the configured instance  has appropriate configuration\"\"\"\n\n  def stepCheckInstanceIsConfiguredFrance(self, sequence=None,  sequence_list=None, **kw):\n    \"\"\" Check if the instance is configured with French business templates \"\"\"\n    self._stepCheckInstanceIsConfigured(\n                business_configuration=sequence.get(\'business_configuration\'),\n                bt5_tuple=(\'erp5_accounting_l10n_fr\', \'erp5_l10n_fr\',))\n\n  def stepCheckInstanceIsConfiguredGermany(self, sequence=None,  sequence_list=None, **kw):\n    \"\"\" Check if the instance is configured with German business templates \"\"\"\n    self._stepCheckInstanceIsConfigured(\n                business_configuration=sequence.get(\'business_configuration\'),\n                bt5_tuple=(\'erp5_accounting_l10n_de_skr04\', \'erp5_l10n_de\',))\n\n  def stepCheckInstanceIsConfiguredBrazil(self, sequence=None,  sequence_list=None, **kw):\n    \"\"\" Check if the instance is configured with Brazilian business templates \"\"\"\n    self._stepCheckInstanceIsConfigured(\n             business_configuration=sequence.get(\'business_configuration\'),\n             bt5_tuple=(\'erp5_accounting_l10n_br_extend\', \'erp5_l10n_pt-BR\',))\n\n  def stepCheckInstanceIsConfiguredRussia(self, sequence=None,  sequence_list=None, **kw):\n    \"\"\" Check if the instance is configured with Russian business templates \"\"\"\n    self._stepCheckInstanceIsConfigured(\n             business_configuration=sequence.get(\'business_configuration\'),\n             bt5_tuple=(\'erp5_accounting_l10n_ru\', \'erp5_l10n_ru\',))\n\n  def stepStartConfigurationInstallation(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Starts the installation \"\"\"\n    business_configuration = sequence.get(\"business_configuration\")\n    self.portal.portal_configurator.startInstallation(\n         business_configuration, REQUEST=self.portal.REQUEST)\n\n\n  ###################################\n  ## Test Configurator Security\n  ###################################\n  def stepViewAddGadget(self, sequence=None, sequence_list=None, **kw):\n    \"\"\"\n       Test if gadget system is working.\n    \"\"\"\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      knowledge_pad_module = self.portal.knowledge_pad_module\n      knowledge_pad = knowledge_pad_module.newContent(portal_type=\'Knowledge Pad\')\n      self.failUnlessUserCanViewDocument(user_id, knowledge_pad)\n      self.failUnlessUserCanAccessDocument(user_id, knowledge_pad)\n      # only in visible state we can add Gadgets (i.e. Knowledge Boxes)\n      knowledge_pad.visible()\n      knowledge_box = knowledge_pad.newContent(portal_type=\'Knowledge Box\')\n      self.failUnlessUserCanViewDocument(user_id, knowledge_box)\n      self.failUnlessUserCanAccessDocument(user_id, knowledge_box)\n\n  def stepViewEventModule(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Everybody can view events. \"\"\"\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, self.portal.event_module)\n      self.failUnlessUserCanAccessDocument(user_id, self.portal.event_module)\n\n  def stepAddEvent(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" Everybody can add events. \"\"\"\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanAddDocument(user_id, self.portal.event_module)\n      for event_type in (\'Visit\', \'Web Message\', \'Letter\', \'Note\',\n                         \'Phone Call\', \'Mail Message\', \'Fax Message\'):\n        self._loginAsUser(user_id)\n        event = self.portal.event_module.newContent(portal_type=event_type)\n        self.failUnlessUserCanViewDocument(user_id, event)\n        self.failUnlessUserCanAccessDocument(user_id, event)\n\n  def stepSentEventWorkflow(self, sequence=None, sequence_list=None, **kw):\n    for event_type in (\'Visit\', \'Web Message\', \'Letter\', \'Note\',\n                       \'Phone Call\', \'Mail Message\', \'Fax Message\'):\n      event = self.portal.event_module.newContent(portal_type=event_type)\n      # in draft state, we can view & modify\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanAccessDocument(user_id, event)\n        self.failUnlessUserCanViewDocument(user_id, event)\n        self.failUnlessUserCanModifyDocument(user_id, event)\n\n      # everybody can cancel from draft\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'cancel_action\', event)\n\n      # everybody can plan\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'plan_action\', event)\n\n      event.plan()\n      self.assertEqual(\'planned\', event.getSimulationState())\n\n      # everybody can confirm or send a planned event\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'confirm_action\', event)\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'start_action\', event)\n\n      event.start()\n      self.assertEqual(\'started\', event.getSimulationState())\n\n      # everybody can deliver a sent event\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'deliver_action\', event)\n      event.deliver()\n      self.assertEqual(\'delivered\', event.getSimulationState())\n\n  ## Accounts {{{\n  def stepViewAccountModule(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" everybody can view and access account module. \"\"\"\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id,\n                              self.portal.account_module)\n      self.failUnlessUserCanAccessDocument(user_id,\n                              self.portal.account_module)\n\n  def stepAddAccountModule(self, sequence=None, sequence_list=None, **kw):\n    \"\"\" only accountants can add accounts. \"\"\"\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanAddDocument(user_id,\n                    self.portal.account_module)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanAddDocument(user_id,\n                      self.portal.account_module)\n\n  def stepViewAccount(self, sequence=None, sequence_list=None, **kw):\n    account = self.portal.account_module.newContent(\n        portal_type=\'Account\',\n        account_type=\'expense\',\n    )\n    # in draft state,\n    self.assertEqual(\'draft\', account.getValidationState())\n    # everybody can see\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, account)\n      self.failUnlessUserCanAccessDocument(user_id, account)\n\n    # only accountants can modify\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, account)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, account)\n\n    # only accountants can validate\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n                  user_id, \'validate_action\', account)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(\n                    user_id, \'validate_action\', account)\n\n    account.validate()\n    self.assertEqual(\'validated\', account.getValidationState())\n    # in validated state, every body can view, but *nobody* can modify\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, account)\n      self.failUnlessUserCanAccessDocument(user_id, account)\n      self.failIfUserCanModifyDocument(user_id, account)\n\n    # only accountants can invalidate\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n                  user_id, \'invalidate_action\', account)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(\n                  user_id, \'invalidate_action\', account)\n\n    account.invalidate()\n    self.assertEqual(\'invalidated\', account.getValidationState())\n    # back in invalidated state, everybody can view\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, account)\n      self.failUnlessUserCanAccessDocument(user_id, account)\n    # only accountants can modify\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, account)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, account)\n\n    account.delete()\n    # nobody can view delete object, but we can still access, for safety\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failIfUserCanViewDocument(user_id, account)\n\n  def stepCopyPasteAccount(self, sequence=None, sequence_list=None, **kw):\n    # tests copy / pasting accounts from account module\n    account = self.portal.account_module.newContent(\n        portal_type=\'Account\',\n        account_type=\'expense\',\n    )\n    # in draft state,\n    self.assertEqual(\'draft\', account.getValidationState())\n\n    # everybody can see\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, account)\n      self.failUnlessUserCanAccessDocument(user_id, account)\n\n  def stepViewEntityModules(self, sequence=None, sequence_list=None, **kw):\n    # Everybody can view entities.\n    for user_id in self._getUserIdList(self.all_username_list):\n      for module in [self.portal.person_module,\n                     self.portal.organisation_module]:\n        self.failUnlessUserCanViewDocument(user_id, module)\n        self.failUnlessUserCanAccessDocument(user_id, module)\n\n  def stepAddEntityModules(self, sequence=None, sequence_list=None, **kw):\n    # Everybody can add entities.\n    for user_id in self._getUserIdList(self.all_username_list):\n      for module in [self.portal.person_module,\n                     self.portal.organisation_module]:\n        self.failUnlessUserCanAddDocument(user_id, module)\n\n  def stepCopyAndPastePerson(self, sequence=None, sequence_list=None, **kw):\n    # copy & paste in person module\n    person = self.portal.person_module.newContent(\n                                    portal_type=\'Person\')\n\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      person.Base_createCloneDocument()\n\n  def stepCopyAndPasteOrganisation(self, sequence=None, sequence_list=None, **kw):\n    # copy & paste in organisation module\n    organisation = self.portal.organisation_module.newContent(\n                                    portal_type=\'Organisation\')\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      organisation.Base_createCloneDocument()\n\n  def stepEntityWorkflow(self, sequence=None, sequence_list=None, **kw):\n    for module in [self.portal.person_module,\n                   self.portal.organisation_module]:\n      entity = module.newContent()\n      # in draft state, we can view, modify & add\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanAccessDocument(user_id, entity)\n        self.failUnlessUserCanViewDocument(user_id, entity)\n        self.failUnlessUserCanModifyDocument(user_id, entity)\n        self.failUnlessUserCanAddDocument(user_id, entity)\n\n      # everybody can validate\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'validate_action\', entity)\n      entity.validate()\n      self.assertEqual(\'validated\', entity.getValidationState())\n\n      # in validated state, we can still modify\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanAccessDocument(user_id, entity)\n        self.failUnlessUserCanViewDocument(user_id, entity)\n        self.failUnlessUserCanModifyDocument(user_id, entity)\n        self.failUnlessUserCanAddDocument(user_id, entity)\n\n      # and invalidate\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanPassWorkflowTransition(\n                    user_id, \'invalidate_action\', entity)\n\n  def stepViewCreatedPersons(self, sequence=None, sequence_list=None, **kw):\n    self.loginByUserName(user_name=\'test_configurator_user\')\n    business_configuration = sequence.get(\'business_configuration\')\n    person_list = self.getBusinessConfigurationObjectList(business_configuration, \'Person\')\n    self.assertNotEqual(0, len(person_list))\n\n    for entity in person_list:\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanAccessDocument(user_id, entity)\n        self.failUnlessUserCanViewDocument(user_id, entity)\n\n  def stepViewCreatedOrganisations(self, sequence=None, sequence_list=None, **kw):\n    self.loginByUserName(user_name=\'test_configurator_user\')\n    business_configuration = sequence.get(\'business_configuration\')\n    organisation_list = self.getBusinessConfigurationObjectList(business_configuration, \'Organisation\')\n    self.assertNotEqual(0, len(organisation_list))\n\n    for entity in organisation_list:\n      for user_id in self._getUserIdList(self.all_username_list):\n        self.failUnlessUserCanAccessDocument(user_id, entity)\n        self.failUnlessUserCanViewDocument(user_id, entity)\n\n  def stepViewCreatedAssignemnts(self, sequence=None, sequence_list=None, **kw):\n    self.loginByUserName(user_name=\'test_configurator_user\')\n    business_configuration = sequence.get(\'business_configuration\')\n    person_list = self.getBusinessConfigurationObjectList(business_configuration, \'Person\')\n    self.assertNotEqual(0, len(person_list))\n\n    for person in person_list:\n      found_one = 0\n      for assignment in person.contentValues(portal_type=\'Assignment\'):\n        found_one = 1\n        for user_id in self._getUserIdList(self.all_username_list):\n          self.failUnlessUserCanAccessDocument(user_id, assignment)\n          self.failUnlessUserCanViewDocument(user_id, assignment)\n      self.assertTrue(found_one, \'No assignment found in %s\' % person)\n\n  # }}}\n\n  ## Accounting Periods {{{\n  def stepAddAccoutingPeriod(self, sequence=None, sequence_list=None, **kw):\n    # Everybody can add accounting periods.\n    organisation = self.portal.organisation_module.newContent(\n                          portal_type=\'Organisation\')\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      self.assertIn(\'Accounting Period\',\n            organisation.getVisibleAllowedContentTypeList())\n\n  def stepValidatedAccountingPeriods(self, sequence=None, sequence_list=None, **kw):\n\n    currency_id = sequence.get(\"currency_id\")\n    currency_value = getattr(self.portal.currency_module, currency_id)\n\n    organisation = self.portal.organisation_module.newContent(\n                          portal_type=\'Organisation\',\n                          price_currency_value=currency_value,\n                          group=\'my_group\')\n    accounting_period = organisation.newContent(\n                          portal_type=\'Accounting Period\',\n                          start_date=DateTime(2001, 1, 1),\n                          stop_date=DateTime(2002, 12, 31))\n    self.assertEqual(accounting_period.getSimulationState(), \'draft\')\n\n    # accountants can modify the period\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, accounting_period)\n    # accountants can cancel the period\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n          user_id, \'cancel_action\', accounting_period)\n    # accountants can start the period\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n          user_id, \'start_action\', accounting_period)\n\n    # once the period is started, nobody can modify\n    accounting_period.start()\n    self.assertEqual(\'started\', accounting_period.getSimulationState())\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failIfUserCanModifyDocument(user_id, accounting_period)\n    # accountants can still cancel the period\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n          user_id, \'cancel_action\', accounting_period)\n    # accountants can stop the period\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n          user_id, \'stop_action\', accounting_period)\n    # and reopen it\n    accounting_period.stop()\n    self.assertEqual(\'stopped\', accounting_period.getSimulationState())\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(\n          user_id, \'restart_action\', accounting_period)\n    # but only accounting manager can close it\n    accounting_manager_id, = self._getUserIdList([self.accounting_manager_reference])\n    self.failUnlessUserCanPassWorkflowTransition(\n          accounting_manager_id, \'deliver_action\', accounting_period)\n    if self.restricted_security:\n      accounting_agent_id, = self._getUserIdList([self.accounting_agent_reference])\n      self.failIfUserCanPassWorkflowTransition(\n          accounting_agent_id, \'deliver_action\', accounting_period)\n\n  # }}}\n\n  ## Payment Nodes (Bank Account & Credit Cards) {{{\n  def stepViewBankAccount(self, sequence=None, sequence_list=None, **kw):\n    # Everybody can view bank accounts.\n    entity = self.portal.organisation_module.newContent(\n                                               portal_type=\'Organisation\')\n    bank_account = entity.newContent(portal_type=\'Bank Account\')\n    # everybody can view in draft ...\n    self.assertEqual(\'draft\', bank_account.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, bank_account)\n      self.failUnlessUserCanAccessDocument(user_id, bank_account)\n    # ... and validated states\n    bank_account.validate()\n    self.assertEqual(\'validated\', bank_account.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, bank_account)\n      self.failUnlessUserCanAccessDocument(user_id, bank_account)\n\n  def stepViewCreditCard(self, sequence=None, sequence_list=None, **kw):\n    # Everybody can view credit cards\n    entity = self.portal.organisation_module.newContent(\n                                               portal_type=\'Organisation\')\n    ext_payment = entity.newContent(portal_type=\'Credit Card\')\n    # every body can view in draft ...\n    self.assertEqual(\'draft\', ext_payment.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, ext_payment)\n      self.failUnlessUserCanAccessDocument(user_id, ext_payment)\n    # ... and validated states\n    ext_payment.validate()\n    self.assertEqual(\'validated\', ext_payment.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id, ext_payment)\n      self.failUnlessUserCanAccessDocument(user_id, ext_payment)\n\n  def stepValidateAndModifyBankAccount(self, sequence=None, sequence_list=None, **kw):\n    # Every body can modify Bank Accounts\n    entity = self.portal.organisation_module.newContent(\n                                               portal_type=\'Organisation\')\n    bank_account = entity.newContent(portal_type=\'Bank Account\')\n    # draft\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, bank_account)\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                \'validate_action\', bank_account)\n    # validated\n    bank_account.validate()\n    self.assertEqual(\'validated\', bank_account.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, bank_account)\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                \'invalidate_action\', bank_account)\n    # invalidated\n    bank_account.invalidate()\n    self.assertEqual(\'invalidated\', bank_account.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, bank_account)\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                \'validate_action\', bank_account)\n\n  def stepValidateAndModifyCreditCard(self, sequence=None, sequence_list=None, **kw):\n    # Every body can modify Credit Card\n    entity = self.portal.organisation_module.newContent(\n                                               portal_type=\'Organisation\')\n    credit_card = entity.newContent(portal_type=\'Credit Card\')\n    # draft\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, credit_card)\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                \'validate_action\', credit_card)\n    # validated\n    credit_card.validate()\n    self.assertEqual(\'validated\', credit_card.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, credit_card)\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                \'invalidate_action\', credit_card)\n    # invalidated\n    credit_card.invalidate()\n    self.assertEqual(\'invalidated\', credit_card.getValidationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, credit_card)\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                \'validate_action\', credit_card)\n\n  def stepAddPaymentNodeInPerson(self, sequence=None, sequence_list=None, **kw):\n    person = self.portal.person_module.newContent(portal_type=\'Person\')\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      self.failUnlessUserCanAddDocument(user_id, person)\n      self.assertIn(\'Bank Account\',\n                    person.getVisibleAllowedContentTypeList())\n      self.assertIn(\'Credit Card\',\n                    person.getVisibleAllowedContentTypeList())\n    # when the entity is validated, we can still add some payment nodes\n    person.validate()\n    self.portal.portal_caches.clearAllCache()\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      self.failUnlessUserCanAddDocument(user_id, person)\n      self.assertIn(\'Bank Account\',\n                    person.getVisibleAllowedContentTypeList())\n      self.assertIn(\'Credit Card\',\n                    person.getVisibleAllowedContentTypeList())\n\n  def stepAddPaymentNodeInOrganisation(self, sequence=None, sequence_list=None, **kw):\n    org = self.portal.organisation_module.newContent(\n                                    portal_type=\'Organisation\')\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      self.failUnlessUserCanAddDocument(user_id, org)\n      self.assertIn(\'Bank Account\',\n                    org.getVisibleAllowedContentTypeList())\n      self.assertIn(\'Credit Card\',\n                    org.getVisibleAllowedContentTypeList())\n    # when the entity is validated, we can still add some payment nodes\n    org.validate()\n    self.portal.portal_caches.clearAllCache()\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      self.failUnlessUserCanAddDocument(user_id, org)\n      self.assertIn(\'Bank Account\',\n                    org.getVisibleAllowedContentTypeList())\n      self.assertIn(\'Credit Card\',\n                    org.getVisibleAllowedContentTypeList())\n\n  def stepCopyAndPasteBankAccountInPerson(self, sequence=None, sequence_list=None, **kw):\n    # everybody can cp bank accounts in persons\n    person = self.portal.organisation_module.newContent(\n                                    portal_type=\'Organisation\')\n    bank_account = person.newContent(\n                              portal_type=\'Bank Account\')\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      bank_account.Base_createCloneDocument()\n\n  def stepCopyAndPasteBankAccountInOrganisation(self, sequence=None, sequence_list=None, **kw):\n    # everybody can cp bank accounts in organisation\n    organisation = self.portal.organisation_module.newContent(\n                                    portal_type=\'Organisation\')\n    bank_account = organisation.newContent(\n                              portal_type=\'Bank Account\')\n    for user_id in self._getUserIdList(self.all_username_list):\n      self._loginAsUser(user_id)\n      bank_account.Base_createCloneDocument()\n\n  # }}}\n\n  ## Accounting Module {{{\n  def stepViewAccountingTransactionModule(self, sequence=None, sequence_list=None, **kw):\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanViewDocument(user_id,\n              self.portal.accounting_module)\n      self.failUnlessUserCanAccessDocument(user_id,\n              self.portal.accounting_module)\n\n  def stepAddAccountingTransactionModule(self, sequence=None, sequence_list=None, **kw):\n    # Anyone can adds accounting transactions\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.failUnlessUserCanAddDocument(user_id,\n              self.portal.accounting_module)\n\n  def stepCopyAndPasteAccountingTransactions(self, sequence=None, sequence_list=None, **kw):\n    # Anyone can copy and paste accounting transaction.\n    for portal_type in self._getAccountingTransactionTypeList():\n      if portal_type != \'Balance Transaction\':\n        transaction = self.portal.accounting_module.newContent(\n                                        portal_type=portal_type)\n        for user_id in self._getUserIdList(self.all_username_list):\n          self._loginAsUser(user_id)\n          transaction.Base_createCloneDocument()\n\n  def _getAccountingTransactionTypeList(self):\n    module = self.portal.accounting_module\n    return [ti for ti in module.getVisibleAllowedContentTypeList()\n               if ti not in (\'Balance Transaction\', )]\n\n  def stepAccountingTransaction(self, sequence=None, sequence_list=None, **kw):\n    transaction = self.portal.accounting_module.newContent(\n                      portal_type=\'Accounting Transaction\',\n                      start_date=DateTime(2001, 1, 1),\n                      stop_date=DateTime(2001, 1, 1))\n    self.assertEqual(\'draft\', transaction.getSimulationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, transaction)\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, transaction)\n      self.failUnlessUserCanAddDocument(user_id, transaction)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'cancel_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'plan_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'confirm_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'start_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'stop_action\',\n                                                 transaction)\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'cancel_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'plan_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'confirm_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'stop_action\',\n                                               transaction)\n      # TODO\n      ### self.failUnlessUserCanPassWorkflowTransition(user_id,\n      ###                                          \'delete_action\',\n      ###                                          transaction)\n\n    # (skip some states)\n    transaction.start()\n    self.assertEqual(\'started\', transaction.getSimulationState())\n    self.tic()\n\n    for user_id in self._getUserIdList(self.all_username_list):\n      # everybody can view\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n\n    # only accountant can modify\n    if self.restricted_security:\n      for user_id in  self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, transaction)\n        self.failIfUserCanAddDocument(user_id, transaction)\n\n    if self.restricted_security:\n      # only accountant can \"stop\"\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'stop_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'deliver_action\',\n                                                 transaction)\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'stop_action\',\n                                               transaction)\n\n    transaction.stop()\n    self.assertEqual(\'stopped\', transaction.getSimulationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      # everybody can view\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n      # nobody can modify\n      self.failIfUserCanModifyDocument(user_id, transaction)\n      self.failIfUserCanAddDocument(user_id, transaction)\n\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'restart_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'deliver_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'cancel_action\',\n                                                 transaction)\n\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'restart_action\',\n                                               transaction)\n    # in started state, we can modify again, and go back to stopped state\n    transaction.restart()\n    self.assertEqual(\'started\', transaction.getSimulationState())\n    self.tic()\n\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                  \'stop_action\',\n                                                  transaction)\n\n    # go back to stopped state\n    transaction.stop()\n    self.assertEqual(\'stopped\', transaction.getSimulationState())\n\n    # only accounting_manager can validate\n    accounting_manager_id, = self._getUserIdList([self.accounting_manager_reference])\n    self.failUnlessUserCanPassWorkflowTransition(accounting_manager_id,\n                                            \'deliver_action\',\n                                             transaction)\n    if self.restricted_security:\n      accounting_agent_id, = self._getUserIdList([self.accounting_agent_reference])\n      self.failIfUserCanPassWorkflowTransition(accounting_agent_id,\n                                              \'deliver_action\',\n                                               transaction)\n\n  def stepSaleInvoiceTransaction(self, sequence=None, sequence_list=None, **kw):\n    transaction = self.portal.accounting_module.newContent(\n                      portal_type=\'Sale Invoice Transaction\',\n                      start_date=DateTime(2001, 1, 1),\n                      stop_date=DateTime(2001, 1, 1))\n    self.assertEqual(\'draft\', transaction.getSimulationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, transaction)\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, transaction)\n      self.failUnlessUserCanAddDocument(user_id, transaction)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list -\n                       self.sales_and_purchase_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'cancel_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'plan_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'confirm_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'stop_action\',\n                                                 transaction)\n\n    for user_id in self._getUserIdList(self.sales_and_purchase_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                   \'cancel_action\',\n                                                    transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                   \'plan_action\',\n                                                    transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                   \'confirm_action\',\n                                                    transaction)\n\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'cancel_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'plan_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'confirm_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'stop_action\',\n                                               transaction)\n      # TODO\n      ### self.failUnlessUserCanPassWorkflowTransition(user_id,\n      ###                                          \'delete_action\',\n      ###                                          transaction)\n\n    # (skip some states)\n    transaction.start()\n    self.assertEqual(\'started\', transaction.getSimulationState())\n    self.tic()\n\n    for user_id in self._getUserIdList(self.all_username_list):\n      # everybody can view\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n\n    # only accountant can modify\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, transaction)\n        self.failIfUserCanAddDocument(user_id, transaction)\n\n    if self.restricted_security:\n      # only accountant can \"stop\"\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'stop_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'deliver_action\',\n                                                 transaction)\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'stop_action\',\n                                               transaction)\n\n    transaction.stop()\n    self.assertEqual(\'stopped\', transaction.getSimulationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      # everybody can view\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n      # nobody can modify\n      self.failIfUserCanModifyDocument(user_id, transaction)\n      self.failIfUserCanAddDocument(user_id, transaction)\n\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'restart_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'deliver_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'cancel_action\',\n                                                 transaction)\n\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'restart_action\',\n                                               transaction)\n    # in started state, we can modify again, and go back to stopped state\n    transaction.restart()\n    self.assertEqual(\'started\', transaction.getSimulationState())\n    self.tic()\n\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                  \'stop_action\',\n                                                  transaction)\n\n    # go back to stopped state\n    transaction.stop()\n    self.assertEqual(\'stopped\', transaction.getSimulationState())\n\n    # only accounting_manager can validate\n    accounting_manager_id, = self._getUserIdList([self.accounting_manager_reference])\n    self.failUnlessUserCanPassWorkflowTransition(accounting_manager_id,\n                                            \'deliver_action\',\n                                             transaction)\n    if self.restricted_security:\n      accounting_agent_id, = self._getUserIdList([self.accounting_agent_reference])\n      self.failIfUserCanPassWorkflowTransition(accounting_agent_id,\n                                              \'deliver_action\',\n                                               transaction)\n\n\n  def stepPurchaseInvoiceTransaction(self, sequence=None, sequence_list=None, **kw):\n    transaction = self.portal.accounting_module.newContent(\n                      portal_type=\'Purchase Invoice Transaction\',\n                      start_date=DateTime(2001, 1, 1),\n                      stop_date=DateTime(2001, 1, 1))\n    self.assertEqual(\'draft\', transaction.getSimulationState())\n    for user_id in self._getUserIdList(self.all_username_list):\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, transaction)\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanModifyDocument(user_id, transaction)\n      self.failUnlessUserCanAddDocument(user_id, transaction)\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list -\n                       self.sales_and_purchase_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'cancel_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'plan_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'confirm_action\',\n                                                 transaction)\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'stop_action\',\n                                                 transaction)\n\n    for user_id in self._getUserIdList(self.sales_and_purchase_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                   \'cancel_action\',\n                                                    transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                   \'plan_action\',\n                                                    transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                                   \'confirm_action\',\n                                                    transaction)\n      # XXX would require to go to confirmed state first\n      # self.failIfUserCanPassWorkflowTransition(user_id,\n      #                                         \'start_action\',\n      #                                         transaction)\n\n\n    for user_id in self._getUserIdList(self.accountant_username_list):\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'cancel_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'plan_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'confirm_action\',\n                                               transaction)\n      self.failUnlessUserCanPassWorkflowTransition(user_id,\n                                               \'stop_action\',\n                                               transaction)\n      # TODO\n      ### self.failUnlessUserCanPassWorkflowTransition(user_id,\n      ###                                          \'delete_action\',\n      ###                                          transaction)\n\n    # (skip some states)\n    transaction.start()\n    self.assertEqual(\'started\', transaction.getSimulationState())\n    self.tic()\n\n    for user_id in self._getUserIdList(self.all_username_list):\n      # everybody can view\n      self.assertUserCanViewDocument(user_id, transaction)\n      self.assertUserCanAccessDocument(user_id, transaction)\n\n    # only accountant can modify\n    if self.restricted_security:\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanModifyDocument(user_id, transaction)\n        self.failIfUserCanAddDocument(user_id, transaction)\n\n    if self.restricted_security:\n      # only accountant can \"stop\"\n      for user_id in self._getUserIdList(self.all_username_list - self.accountant_username_list):\n        self.failIfUserCanPassWorkflowTransition(user_id,\n                                                 \'stop_action\',\n                       