/ html.ui-mobile body th a, html.ui-mobile\nbody td a, html.ui-mobile body th a.ui-btn, html.ui-mobile body td a.ui-btn,\nhtml.ui-mobile body .ui-header .ui-title .ui-btn { font-size: 100%; } /*\nresponsive listview-table */ @media (max-width: 48em) { html table tbody tr\ntd:first-child ~ td a, html table tbody tr th:first-child ~ th a, html table\ntbody tr td:first-child ~ td a, html table tbody tr th:first-child ~ th a {\nfont-size: 85%; } } /* force all code to look like code */ html.ui-mobile body\ndiv pre * { font-family: inherit; font-size: inherit; } /* from here on in % of\nwhatever is set above */ .ui-content-header-section .ui-content-title {\nfont-size: 500%; letter-spacing: -0.05em; } .ui-content-header-fullwidth\n.ui-content-title, .ui-content-header-plain .ui-content-title { font-size:\n150%; } .ui-content-header-fullwidth .ui-content-subtitle,\n.ui-content-header-section .ui-content-subtitle { font-size: 100%; } @media\n(max-width: 62em) { .ui-content-header-section .ui-content-title { font-size:\n300%; } .ui-content-header-fullwidth .ui-content-title,\n.ui-content-header-plain .ui-content-title { font-size: 150%; } } @media\n(max-width: 48em) { .ui-content-header-section .ui-content-title { font-size:\n150%; } .ui-content-header-fullwidth .ui-content-title,\n.ui-content-header-plain .ui-content-title { font-size: 100%; } } /* ==========\n=============================================================== ===============\n========== panel f&$* up =============================== ======================\n=================================================== */ /* @media (min-width:\n64em) { div[data-gadget-scope=\'header\'] > div, article { margin-left: 17em;\nwidth: auto; } html body button.responsive[data-i18n=\'Menu\'] { display: none; }\n.jqm-navmenu-panel .ui-header .ui-controlgroup-controls form .ui-btn { display:\nnone; } } */ /* ===============================================================\n========== ======================== overwriting widgets =======================\n==== =========================================================================\n*/ /* -------------------------------------------------------------------------\n------------------------------- Loader ----------------------------------\n------------------------------------------------------------------------- */ /*\ndon\'t fade spinner */ html body .ui-icon-spinner.ui-icon-spin { opacity: 1; } /\n* -------------------------------------------------------------------------\n-------------------------------- Page -----------------------------------\n------------------------------------------------------------------------- */ /*\npage theme backgrounds */ html body, html body .ui-page, html body .ui-page\n.ui-panel-wrapper { background: none; border-color: transparent; color:\ninherit; text-shadow: none; } /* page padding - JQM tries to set this through\nthe wrapping page-div. Once this is gone, remove rule */ html body\n.ui-page-header-fixed { padding-top: 41px !important; } /*\n-------------------------------------------------------------------------\n------------------------------- Content ---------------------------------\n------------------------------------------------------------------------- */ /*\ndimensions inset header/content */ .ui-content-header-section,\n.ui-content-section { border-style: solid; border-width: 1px; /* max-width:\n85%; */ margin: 0 auto; } .ui-content-header-plain { /* max-width: 85%; */\nmargin: 0 auto; } /* MOVE: icon positioning */ .ui-content-header-plain\n.ui-content-title span { padding-right: .5em; } /* fullwidth header box-shadow\nand max-height */ .ui-content-header-fullwidth { padding: 1em; border-width: 0;\nborder-bottom-width: 1px; -webkit-box-shadow: 0 1px 3px #aaa; -moz-box-shadow:\n0 1px 3px #aaa; box-shadow: 0 1px 3px #aaa; max-height: 5em;\n-webkit-box-sizing: border-box; -moz-box-sizing: border-box; box-sizing:\nborder-box; /* with navbar margin: 5em -1em 0; */ margin: -0.5em -1em 0; width:\nauto; } /* 