ncellation throw new Error(\"Service should not have been stopped!\"); }) .push\n(undefined, function (error) { // Always disconnect in case of error if\n(context.props.connection !== undefined) { context.props.connection.close(); }\nthrow error; }); }) .declareMethod(\'createSocket\', function (address) { //\nImprove to support multiple sockets? this.props.socket = new WebSocket\n(address); this.props.socket_defer = RSVP.defer();\nthis.props.socket.addEventListener(\'open\', deferOnOpen.bind(this));\nthis.props.socket.addEventListener(\'close\', deferOnClose.bind(this));\nthis.props.socket.addEventListener(\'message\', deferOnMessage.bind(this));\nthis.props.socket.addEventListener(\'error\', deferErrorHandler.bind(this));\nreturn this.props.socket_defer.promise; }) .declareMethod(\'send\', function\n(message) { this.props.socket.send(message); }) .declareMethod(\'close\',\nfunction () { if (this.props.socket === undefined) { return; }\nthis.props.socket.close(); delete this.props.socket; }); }(rJS, window,\nWebSocket, RSVP));'),(14385,'WebSocket Gadget gadget_websocket.html 001'),(14386,'WebRTC Gadget JS gadget_webrtc.js 001 /*jslint indent: 2*/ /*global rJS, RSVP, window*/ (function (rJS, RSVP, window)\n{ \"use strict\"; var RTCPeerConnection = window.RTCPeerConnection ||\nwindow.mozRTCPeerConnection || window.webkitRTCPeerConnection ||\nwindow.msRTCPeerConnection, RTCSessionDescription =\nwindow.RTCSessionDescription || window.mozRTCSessionDescription ||\nwindow.webkitRTCSessionDescription || window.msRTCSessionDescription; function\nenqueueDefer(gadget, callback) { var deferred = gadget.props.current_deferred;\n// Unblock queue if (deferred !== undefined) { deferred.resolve(\"Another event\nadded\"); } // Add next callback try { gadget.props.service_queue.push\n(callback); } catch (error) { throw new Error(\"Connection gadget already\ncrashed... \" + gadget.props.service_queue.rejectedReason.toString()); } //\nBlock the queue deferred = RSVP.defer(); gadget.pro