e) { var gadget = this, webrtc =\nthis.props.webrtc; return webrtc.createConnection.apply(webrtc,\nconnection_options) .push(function () { return webrtc.createDataChannel(title,\ndata_channel_options); }) .push(function () { return webrtc.createOffer\n(offer_contraints); }) .push(function (local_description) { return\nwebrtc.setLocalDescription(local_description); }) .push(function () { return\ngadget.props.description_defer.promise; }); }) .declareMethod(\'registerAnswer\',\nfunction (description) { var gadget = this; return\ngadget.props.webrtc.setRemoteDescription(description) .push(function () {\nreturn gadget.props.channel_defer.promise; }); }) .declareMethod\n(\'createAnswer\', function (title, description) { var gadget = this, webrtc =\nthis.props.webrtc; return webrtc.createConnection.apply(webrtc,\nconnection_options) .push(function () { return webrtc.setRemoteDescription\n(description); }) .push(function () { return webrtc.createAnswer\n(offer_contraints); }) .push(function (local_description) { return\nwebrtc.setLocalDescription(local_description); }) .push(function () { return\ngadget.props.description_defer.promise; }); }) .declareMethod\n(\'waitForConnection\', function () { return this.props.channel_defer.promise; })\n.declareMethod(\'send\', function () { var webrtc = this.props.webrtc; return\nwebrtc.send.apply( webrtc, arguments ); }); }(rJS, window, RSVP));'),(14389,'WebRTC DataChannel Gadget gadget_webrtc_datachannel.html 001'),(14390,'Gadget Translation JS gadget_translation.js /*global document, window, RSVP, rJS, translation_data */ /*jslint nomen: true,\nindent: 2 */ (function (document, window, RSVP, rJS, translation_data) { \"use\nstrict\"; function getSelectedLanguage(gadget, callback) { if (!\ngadget.state.language) { return gadget.getSettingList([ \"selected_language\",\n\"default_selected_language\" ]) .push(function (result_list) {\ngadget.state.language = result_list[0] || result_list[1]; return callback\n(gadget.state.language); }); } return callback(gadget.state.language); }\nfunction translate(string, gadget) { if (translation_data\n[gadget.state.language]) { return translation_data[gadget.state.language]\n[string] || string; } return string; } // translate a list of elements passed\nand returned as string function translateHtml(string, gadget) { var temp,\nelement_list, i, i_len, element, lookup, translate_list, target, route_text,\nhas_breaks, l, l_len, j, j_len; // NOTE:\ncannot be used for everything... (like table rows) // XXX: currently I only\nupdate where needed. Eventually all calls to // translateHtml should pass\n\"their\" proper wrapping element temp = document.createElement(\"div\");\ntemp.innerHTML = string; element_list = temp.querySelectorAll(\"[data-i18n]\");\nfor (i = 0, i_len = element_list.length; i < i_len; i += 1) { element =\nelement_list[i]; lookup = element.getAttribute(\"data-i18n\"); if (lookup) {\ntranslate_list = lookup.split(\";\"); for (l = 0, l_len = translate_list.length;\nl < l_len; l += 1) { target = translate_list[l].split(\"]\"); switch (target[0])\n{ case \"[placeholder\": case \"[alt\": case \"[title\": element.setAttribute(target\n[0].substr(1), translate(target[1], gadget)); break; case \"[value\": has_breaks\n= element.previousSibling.textContent.match(/\\n/g); // JQM inputs > this avoids\ncalling checkboxRadio(\"refresh\")! if (element.tagName === \"INPUT\") { switch\n(element.type) { case \"submit\": case \"reset\": case \"button\": route_text = true;\nbreak; } } if (route_text && (has_breaks || []).length === 0) {\nelement.previousSibling.textContent = translate(target[1], gadget); }\nelement.value = translate(target[1], gadget); break; case \"[parent\":\nelement.parentNode.childNodes[0].textContent = translate(target[1], gadget);\nbreak; case \"[node\": element.childNodes[0].textContent = translate(target[1],\ngadget); break; case \"[last\": // if null, append, if textnode replace, if span,\nappned if (element.lastChild && element.lastChild.nodeType === 3) {\nelement.lastChild.textContent = translate(target[1], gadget); } else {\nelement.appendChild(document.createTextNode(translate(target[1], gadget))); }\nbreak; case \"[html\": element.innerHTML = translate(target[1], gadget); break;\ndefault: if (element.hasChildNodes()) { for (j = 0, j_len =\nelement.childNodes.length; j < j_len; j += 1) { if (element.childNodes\n[j].nodeType === 3) { element.childNodes[j].textContent = translate\n(translate_list[l], gadget); } } } else { element.textContent = translate\n(translate_list[l], gadget); } break; } } } } // return string return\ntemp.innerHTML; } function translateList(gadget, string_list, only_first) { var\ni, result_list = []; for (i = 0; i < string_list.length; i += 1) {\nresult_list.push(translate(string_list[i], gadget)); } if (only_first) { return\nresult_list[0]; } return result_list; } function promiseTranslateList(gadget,\nstring_list, only_first) { return getSelectedLanguage(gadget, function () {\nreturn translateList(gadget, string_list, only_first); }); } rJS(window)\n.declareAcquiredMethod(\"getSettingList\", \"getSettingList\") .declareMethod\n(\'getSelectedLanguage\', function () { return getSelectedLanguage(this, function\n(language) { return language; }); }) .declareMethod(\'getTranslationList\',\nfunction (string_list) { return promiseTranslateList(this, string_list); })\n.declareMethod(\'getTranslationDict\', function (string_list) { return new\nRSVP.Queue(promiseTranslateList(this, string_list)) .push(function\n(translation_list) { var i, translation_dict = {}; for (i = 0; i <\nstring_list.length; i += 1) { translation_dict[string_list[i]] =\ntranslation_list[i]; } return translation_dict; }); }) .declareMethod\n(\'translate\', function (string) { return promiseTranslateList(this, [string],\ntrue); }) .declareMethod(\'translateHtml\', function (string) { var gadget =\nthis; return getSelectedLanguage(gadget, function () { return translateHtml\n(string, gadget); }); }); }(document, window, 