, input; if (this.state.editable) {\ninput = this.element.querySelector(\'textarea\'); result[input.getAttribute\n(\'name\')] = input.value; // Change the value state in place // This will\nprevent the gadget to be changed if // its parent call render with the same\nvalue // (as ERP5 does in case of formulator error) this.state.value =\ninput.value; } return result; }) .declareAcquiredMethod(\"notifyValid\",\n\"notifyValid\") .declareMethod(\'checkValidity\', function checkValidity() { var\ntextarea = this.element.querySelector(\'textarea\'), result =\ntextarea.checkValidity(); if (result) { return this.notifyValid() .push\n(function () { return result; }); } if (this.state.error_text) { return\nthis.notifyInvalid(this.state.error_text) .push(function () { return result;\n}); } return result; }) .declareJob(\'deferErrorText\', function deferErrorText\n(error_text) { return this.changeState({ error_text: error_text }); }, {mutex:\n\'changestate\'}) .declareAcquiredMethod(\"notifyChange\", \"notifyChange\") .onEvent\n(\'change\', function change() { return RSVP.all([ this.checkValidity(),\nthis.notifyChange(\"change\") ]); }, false, false) .onEvent(\'input\', function\ninput() { return RSVP.all([ this.checkValidity(), this.notifyChange(\"input\")\n]); }, false, false) .declareAcquiredMethod(\"notifyFocus\", \"notifyFocus\")\n.onEvent(\'focus\', function focus() { return this.notifyFocus(); }, true, false)\n.declareAcquiredMethod(\"notifyBlur\", \"notifyBlur\") .onEvent(\'blur\', function\nblur() { return this.notifyBlur(); }, true, false) .declareAcquiredMethod\n(\"notifyInvalid\", \"notifyInvalid\") .onEvent(\'invalid\', function invalid(evt) {\n// invalid event does not bubble return RSVP.all([ this.deferErrorText\n(evt.target.validationMessage), this.notifyInvalid\n(evt.target.validationMessage) ]); }, true, false) .declareAcquiredMethod\n(\"notifySubmit\", \"notifySubmit\") .onEvent(\'keydown\', function keydown(evt) {\nvar textarea = this.element.querySelector(\'textarea\'); if (evt.keyCode === 83 &\n& (navigator.platform.match(\"Mac\") ? evt.metaKey : evt.ctrlKey)) { //Textarea\'s\nchange event is generally launched by browser when press a predefined key //\nCall preventDefault prevent change event evt.preventDefault(); //When lose\nfocus, change event is launched //Without this, after saving, then click other\nfields or go to other view //Change event will be trigged and there will have a\nunsaved warning for textarea textarea.blur(); //Refocus for consistency\ntextarea.focus(); return this.notifySubmit(); } }, false, false); }(window,\nrJS, RSVP, navigator));'),(14700,'erp5_code_mirror This  Business Template contains CodeMirror code.'),(14701,'Draft Default state of the document'),(14702,'Deleted Documents in this state were deleted by the user as a result of clicking on the trash button or calling the delete action'),(14703,'Approved'),(14705,'Review Validation Workflow Validation helps confirming the entered data by relevant agents before it is shared. review_workflow'),(14707,'erp5_run_my_doc RunMyDoc allows you to create easily your tutorial and tests'),(14712,'Smart Assistant Text'),(14714,'Smart Assistant Texts'),(14720,'Smart Assistant Sound'),(14722,'Smart Assistant Sounds'),(14728,'Smart Assistant Image'),(14730,'Smart Assistant Images'),(14735,'Smart Assistant File'),(14737,'Smart Assistant Files'),(14745,'Create Person'),(14750,'Create Expense'),(14756,'Create Event'),(14764,'Query'),(14769,'Smart Assistant Sounds'),(14770,'Smart Assistant Texts'),(14771,'Smart Assistant Images'),(14772,'Smart Assistant Files'),(14773,'Smart Assistant Text Module'),(14774,'Smart Assistant Text'),(14775,'Smart Assistant Sound Module'),(14776,'Smart Assistant Sound'),(14777,'Smart Assistant Image Module'),(14778,'Smart Assistant Image'),(14779,'Smart Assistant File Module'),(14780,'Smart Assistant File'),(14781,'interface.erp5.ISmartAssistant ISmartAssistant # -*- coding: utf-8 -*-\n#############################################