iled'),(14794,'Comment about transition'),(14795,'Name of the user who performed transition'),(14796,'Transition id'),(14797,'Finish Processing Notify everyone that the processing of this smart assistant document has been completed successfully.'),(14798,'Validate'),(14799,'Start Processing Notify everyone that the processing of a smart assistant document has started.'),(14800,'Process'),(14801,'Cancel Processing Notify everyone that the processing of this document could be completed successfully and has thus been cancelled.'),(14802,'Cancel'),(14803,'Validated Processing done'),(14804,'Processing The ERP5 user is processing the SA document'),(14805,'Draft'),(14806,'Cancelled The request cancelled'),(14807,'Smart Assistant Workflow smart_assistant_workflow'),(14809,'erp5_smart_assistant'),(14817,'Video'),(14819,'Videos'),(14838,'Sound'),(14840,'Sounds'),(14842,'Videos'),(14843,'Sounds'),(14844,'Video Module'),(14845,'Video'),(14846,'Sound Module'),(14847,'Sound'),(14848,'document.erp5.Sound Sound # -*- coding: utf-8 -*-\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom erp5.component.document.File import File, _MARKER\nfrom ZPublisher import HTTPRangeSupport\nfrom Products.CMFCore.utils import _setCacheHeaders, _ViewEmulator\nfrom Products.CMFCore.utils import _checkConditionalGET\n\nfrom zExceptions import Forbidden\n\nclass Sound(File):\n\n  meta_type = \'ERP5 Sound\'\n  portal_type = \'Sound\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Version\n                    , PropertySheet.Reference\n                    , PropertySheet.Document\n                    , PropertySheet.Data\n                    , PropertySheet.ExternalDocument\n                    , PropertySheet.Url\n                    , PropertySheet.Periodicity\n    )\n\n  security.declareProtected(Permissions.View, \'index_html\')\n  def index_html(self, REQUEST, RESPONSE, format=_MARKER, inline=_MARKER, **kw):\n    \"\"\"XXXXXX\"\"\"\n    range = REQUEST.get_header(\'Range\', None)\n    if range is None:\n      start = None\n      end = None\n    else:\n      ranges = HTTPRangeSupport.parseRange(range)\n      (start, end) =  ranges[0]\n\n    if (format is _MARKER) and (not kw) and (range is None):\n      # conversion parameters is mandatory to download the converted content.\n      # By default allways return view action.\n      # for all WevDAV access return raw content.\n      return self.view()\n\n    if format is _MARKER:\n      format = None\n\n    web_cache_kw = kw.copy()\n    if format:\n      web_cache_kw[\'format\'] = format\n    view = _ViewEmulator().__of__(self)\n    # call caching policy manager.\n    _setCacheHeaders(view, web_cache_kw)\n    # If we have a conditional get, set status 304 and return\n    # no content\n    if _checkConditionalGET(view, web_cache_kw):\n      return \'\'\n\n    if not self.checkConversionFormatPermission(format, **kw):\n      raise Forbidden(\'You are not allowed to get this document in this \' \\\n                      \'format\')\n    mime, data = self.convert(format, **kw)\n    total_length = len(data)\n    if end is None:\n      end = total_length\n    if start is not None:\n      data = data[start:end-1]\n\n    RESPONSE.setHeader(\'Content-Length\', len(data))\n    RESPONSE.setHeader(\'Content-Type\', mime)\n    filename = self.getStandardFilename(format=format)\n    # workaround for IE\'s bug to download files over SSL\n    RESPONSE.setHeader(\'Pragma\', \'\')\n    RESPONSE.setHeader(\'Content-Disposition\',\n                       \'attachment; filename=\"%s\"\' % filename)\n    RESPONSE.setHeader(\'Accept-Ranges\', \'bytes\')\n    if start is None:\n      RESPONSE.setStatus(200)\n    else:\n      RESPONSE.setHeader(\'Content-Range\',\n                         \'bytes %s-%s/%s\' % (start, end-1, total_length))\n      RESPONSE.setStatus(206)\n    return bytes(data)'),(14850,'erp5_multimedia'),(15031,'Notebook Edit'),(15032,'Download'),(15036,'View'),(15039,'Notebooks'),(15041,'Notebooks'),(15042,'Notebook Module'),(15043,'Notebook'),(15045,'erp5_notebook'),(15079,'See as a Book Chapter'),(15083,'See as a Book'),(15088,'Update Report'),(15090,'Test Page'),(15092,'Test Page'),(15094,'Slideshow'),(15107,'Edit Slide'),(15118,'Add a New Slide'),(15124,'Launch Selenium Test'),(15137,'Test Page'),(15139,'Export Test Report'),(15141,'See as Selenium Test'),(15145,'Test Page'),(15147,'Edit Slideshow'),(15151,'Test Page'),(15172,'Test Page'),(15189,'Test Pages'),(15197,'Create Test Page'),(15200,'Convert to Web Pages'),(15203,'Convert from Web Pages to Test Pages'),(15216,'Add one more Chapter'),(15227,'Import a Web Page'),(15230,'View Annotations'),(15249,'Review'),(15254,'Reviews'),(15255,'Creation Wizard Gadget Preferences Form'),(15268,'Test Page Field Library'),(15271,'Test Creation Wizard'),(15272,'Test Pages'),(15273,'Reviews'),(15274,'Test Page Module'),(15275,'Test Page A Test Page is an HTML document which contains a Selenium Test and embedded files (images, files...)'),(15276,'Review Module'),(15277,'Review'),(15278,'test.erp5.testRunMyDoc testRunMyDoc ##############################################################################\n#\n# Copyright (c) 2002-2012 Nexedi SA and Contributors. All Rights Reserved.\n#               Rafael Monnerat <rafael@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\n# programmers who take the whole responsibility of assessing all potential\n# consequences resulting from its eventual inadequacies and bugs\n# End users who are looking for a ready-to-use solution with commercial\n# guarantees and support are strongly adviced to contract a Free Software\n# Service Company\n#\n# This program is Free Software; you can redistribute it and/or\n# modify it under the terms of the GNU General Public License\n# as published by the Free Software Foundation; either version 2\n# of the License, or (at your option) any later version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.\n#\n##############################################################################\n\nfrom erp5.component.test.testDms import DocumentUploadTestCase\nfrom time import time\nimport base64\n\n\nclass TestRunMyDoc(DocumentUploadTestCase):\n  \"\"\"\n   Basic Test for internal implementation of RunMyDocs\n  \"\"\"\n  maxDiff = None\n  def getTitle(self):\n    return \"Run My Doc\"\n\n  def getBusinessTemplateList(self):\n    \"\"\"\n    Tuple of Business Templates we need to install\n    \"\"\"\n    return (\'erp5_base\',\n            \'erp5_jquery\',\n            \'erp5_jquery_ui\',\n            \'erp5_knowledge_pad\',\n            \'erp5_ingestion_mysql_innodb_catalog\',\n            \'erp5_ingestion\',\n            \'erp5_web\',\n            \'erp5_dms\',\n            \'erp5_slideshow_style\',\n            \'erp5_ui_test_core\',\n            \'erp5_run_my_doc\')\n\n  def afterSetUp(self):\n    \"\"\"\n    This is ran before anything, used to set the environment\n    \"\"\"\n    # here, you can create the categories and objects your test will depend on\n\n  website_id = \"test_page_web_site\"\n\n  def test_getDocumentListWithTestPage(self):\n    \"\"\"\n     Assert if Test Page works with getDocumentList\n    \"\"\"\n    test_page_reference = \"developer-my.test.page\"\n    website = getattr(self.portal.web_site_module, self.website_id, None)\n    if website is None:\n      website = self.portal.web_site_module.newContent(\n                                   portal_type=\'Web Site\',\n                                   id=self.website_id)\n      website.publish()\n      self.tic()\n\n    test_page = self.portal.test_page_module.newContent(\n              portal_type=\"Test Page\",\n              reference=test_page_reference,\n              language=\"en\",\n              version=\"001\")\n\n    test_page.publish()\n    self.tic()\n\n    document = website.WebSection_getDocumentValue(test_page_reference)\n\n    self.assertNotEqual(None, document)\n    self.assertEqual(document.getRelativeUrl(),\n                      test_page.getRelativeUrl())\n\n  def test_Zuite_uploadScreenShot(self):\n    \"\"\"\n      Test Screeshot upload script used by Zelenium to\n      update screenshots of the documents.\n    \"\"\"\n    image_upload = self.makeFileUpload(\'TEST-en-002.png\')\n    self.assertNotEqual(None, image_upload)\n\n    # Create a web page, and check if the content is not overwriten\n    web_page_reference = \"WEB-PAGE-REFERENCE\"\n    web_page = self.portal.web_page_module.newContent(\n                                     reference=web_page_reference,\n                                     language=\"en\", version=\"001\")\n    web_page.publishAlive()\n    self.tic()\n\n    image_reference = \"IMAGE-REFERENCE-%s\" % str(time())\n    image_page = self.portal.image_module.newContent(\n                                   reference=image_reference,\n                                   language=\"en\", version=\"001\")\n    image_page.publishAlive()\n    self.tic()\n    image_page_2 = self.portal.image_module.newContent(\n                                   reference=image_reference,\n                                   language=\"en\", version=\"002\")\n    image_page_2.publishAlive()\n    self.tic()\n\n    self.portal.REQUEST.form[\'data_uri\'] = image_upload\n    fake_image_reference = \"DO-NOT-EXISTANT-IMAGE\"\n    self.assertNotEqual(None,\n                   self.portal.Zuite_uploadScreenshot(image_upload, fake_image_reference))\n\n    self.assertNotEqual(None,\n                   self.portal.Zuite_uploadScreenshot(image_upload, web_page_reference))\n\n    self.assertEqual(None,\n                   self.portal.Zuite_uploadScreenshot(image_upload, image_reference))\n\n    self.tic()\n    # The right image were updated.\n    image_upload.seek(0)\n    self.assertEqual(image_page_2.getData(), base64.b64decode(image_upload.read()))\n    self.assertEqual(image_page_2.getFilename(), image_reference + \'.png\')\n    self.assertEqual(image_page.getData(), b\'\')\n\n  def test_viewSeleniumTest(self):\n    \"\"\"\n      Test the script that extracts Selenium Test from HTML body.\n    \"\"\"\n    test_page_html = \"\"\"<section><h1>TITLE</h1><details>DETAILS<details>\n    <test><table class=\"test\" style=\"display: none;\"> <tbody> </tbody></table> </test>\n    </section>\n    <section><h1>TITLE</h1><details>DETAILS<details><test>\n      <table class=\"test\" style=\"display: none;\">\n        <tbody>\n          <tr>\n            <td colspan=\"3\">&lt;span metal:use-macro=&quot;container/Zuite_viewTestMacroLibrary/macros/init_test_environment&quot; style=&quot;display: none;&quot;&gt;init&lt;/span&gt;</td>\n          </tr>\n          <tr>\n            <td>selectAndWait</td>\n            <td>name=select_module</td>\n            <td>label=Test Pages</td>\n          </tr>\n          <tr>\n            <td>verifyTextPresent</td>\n            <td>Test Pages</td>\n            <td> <br /> </td>\n          </tr>\n          <tr style=\"opacity: 1;\">\n            <td>clickAndWait</td>\n            <td>css=a.fast_input &gt; span.image</td>\n            <td> <br /> </td>\n          </tr> </tbody></table> </test>\n    </section>\n    <section><h1>TITLE</h1><details>DETAILS<details><test>\n      <table class=\"test\" style=\"display: none;\"> <tbody>\n          <tr>\n            <td>verifyTextPresent</td>\n            <td>Test Pages</td>\n            <td> <br /> </td>\n          </tr> </tbody></table> </test>\n    </section>\"\"\"\n\n    expected_test_html = u\"\"\"<html>\n  <head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\">\n    <title>TEST</title>\n  </head>\n  <body>\n    <table name=\"SELENIUM-TEST\" cellpadding=\"1\" cellspacing=\"1\" border=\"1\">\n      <thead>\n        <tr class=\"title\">\n          <td colspan=\"3\">TEST</td>\n        </tr>\n      </thead>\n      <tbody>\n        <span metal:use-macro=\"container/Zuite_CommonTemplate/macros/init\" style=\"display: none;\">init</span>\n        <tr>\n          <td>storeEval</td>\n          <td>selenium.getCookieByName(\"manager_username\")</td>\n          <td>base_user</td>\n        </tr>\n        <tr>\n          <td>storeEval</td>\n          <td>selenium.getCookieByName(\"manager_password\")</td>\n          <td>base_password</td>\n        </tr>\n        <span metal:use-macro=\"container/Zuite_viewTestMacroLibrary/macros/init_test_environment\" style=\"display: none;\">init</span><tr>\n            <td>selectAndWait</td>\n            <td>name=select_module</td>\n            <td>label=Test Pages</td>\n          </tr>\n          <tr>\n            <td>verifyTextPresent</td>\n            <td>Test Pages</td>\n            <td> <br> </td>\n          </tr>\n          <tr style=\"opacity: 1;\">\n            <td>clickAndWait</td>\n            <td>css=a.fast_input &gt; span.image</td>\n            <td> <br> </td>\n          </tr> <tr>\n            <td>verifyTextPresent</td>\n            <td>Test Pages</td>\n            <td> <br> </td>\n          </tr>\n      </tbody>\n    </table>\n  </body>\n</html>\"\"\"\n\n    test_page = self.portal.test_page_module.newContent(title=\"TEST\",\n                                                        reference=\'TESTPAGEREFERENCE\',\n                                                        text_content=test_page_html)\n    self.assertEqual(\n      test_page.TestPage_viewSeleniumTest(), expected_test_html)\n\n    self.tic()\n    test_page.TestPage_runSeleniumTest()\n\n    zuite = getattr(self.portal.portal_tests, \'TESTPAGEREFERENCE\', None)\n    self.assertNotEqual(zuite, None)\n\n    zptest = getattr(zuite, \"TEST\", None)\n    self.assertNotEqual(zptest, None)\n\n    self.assertEqual(zptest._text, expected_test_html.strip())\n\n    expected_test_html = u\"\"\"<html>\n  <head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\">\n    <title>TEST</title>\n  </head>\n  <body>\n    <table name=\"SELENIUM-TEST\" cellpadding=\"1\" cellspacing=\"1\" border=\"1\">\n      <thead>\n        <tr class=\"title\">\n          <td colspan=\"3\">TEST</td>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td>store</td>\n          <td>http://toto.com</td>\n          <td>base_url</td>\n        </tr>\n        <tr>\n          <td>store</td>\n          <td>titi</td>\n          <td>base_user</td>\n        </tr>\n        <tr>\n          <td>store</td>\n          <td>toto</td>\n          <td>base_password</td>\n        </tr>\n        <span metal:use-macro=\"container/Zuite_viewTestMacroLibrary/macros/init_test_environment\" style=\"display: none;\">init</span><tr>\n            <td>selectAndWait</td>\n            <td>name=select_module</td>\n            <td>label=Test Pages</td>\n          </tr>\n          <tr>\n            <td>verifyTextPresent</td>\n            <td>Test Pages</td>\n            <td> <br> </td>\n          </tr>\n          <tr style=\"opacity: 1;\">\n            <td>clickAndWait</td>\n            <td>css=a.fast_input &gt; span.image</td>\n            <td> <br> </td>\n          </tr> <tr>\n            <td>verifyTextPresent</td>\n            <td>Test Pages</td>\n            <td> <br> </td>\n          </tr>\n      </tbody>\n    </table>\n  </body>\n</html>\"\"\"\n\n\n    # Mimic usage of TestPage_viewSeleniumTest?url=...\n    self.portal.REQUEST[\'url\'] = \"http://toto.com\"\n    self.portal.REQUEST[\'user\'] = \"titi\"\n    self.portal.REQUEST[\'password\'] = \"toto\"\n\n    self.assertEqual(test_page.TestPage_viewSeleniumTest(REQUEST=self.portal.REQUEST),\n                      expected_test_html)\n    self.tic()\n    test_page.TestPage_runSeleniumTest()\n\n    zuite = getattr(self.portal.portal_tests, \'TESTPAGEREFERENCE\', None)\n    self.assertNotEqual(zuite, None)\n\n    zptest = getattr(zuite, \"TEST\", None)\n    self.assertNotEqual(zptest, None)\n\n    self.assertEqual(zptest._text, expected_test_html.strip())'),(15279,'extension.erp5.ERP5RunMyDocs ERP5RunMyDocs \"\"\"\n  Parse the test report\n\"\"\"\ndef parseTestReport(text):\n  from lxml import etree\n  parser = etree.HTMLParser(remove_comments=True)\n  parser.feed(text)\n  root = parser.close()\n  table = root.xpath(\'//table[@id=\"SELENIUM-TEST\"]\')[0]\n  report = dict()\n  header = table[0][0]\n  report[\'status\'] = header.attrib[\'class\'].find(\'passed\') > -1\n  report[\'name\'] = header[0].text\n  report[\"row_list\"] = []\n  report[\"column_list\"] = [0,0,0]\n  i=0\n  for row in table[1]:\n    report[\"row_list\"].append(dict(cell_list=[], passed=False, failed=False, done=False, not_done=False))\n    row_report = report[\"row_list\"][i]\n    if row.attrib[\'class\'].find(\'failed\') > -1:\n      row_report[\'failed\'] = True\n    elif row.attrib[\'class\'].find(\'done\') > -1:\n      row_report[\'done\'] = True\n    elif row.attrib[\'class\'].find(\'passed\') > -1:\n      row_report[\'passed\'] = True\n    else:\n      row_report[\'not_done\'] = True\n    for column in row:\n      row_report[\"cell_list\"].append(column.text)\n    i += 1\n  return report\n\n\"\"\"\n  Return the content of a web page\n\"\"\"\ndef urlread(url):\n  from six.moves.urllib.request import urlopen\n  return urlopen(url).read()\n\n\"\"\"\n  Remove everything but the test in a webpage\n\"\"\"\nfrom Products.ERP5Type.Utils import unicode2str\ndef extractTest(text):\n  import lxml.html\n  root = lxml.html.fromstring(text)\n  table_list = root.xpath(\'//test\')\n  testcode = \"\"\n  for table in table_list:\n    table = table[0]\n    if len(table) > 0:\n      for row in table[-1]:\n        if len(row) == 1:\n          # Include Macros as it is defined by the user.\n          testcode += row[0].text\n        else:\n          testcode += unicode2str(lxml.html.tostring(row, encoding=\'unicode\'))\n  return testcode.strip()\n\n\"\"\"\n  HTML5 Presentation validador\n\"\"\"\ndef validateHTML5Document(text):\n  import lxml.html\n  root = lxml.html.fromstring(text)\n  section_list = root.xpath(\'//section\')\n  count = 0\n  error_list = []\n  # XXX Lack of translation support here.\n  for section in section_list:\n    count += 1\n    if section.xpath(\"h1\") == []:\n      error_list.append(\"Section %s had no h1.\" % count)\n\n    if section.get(\"class\") in [\"screenshot\", \"illustration\"]:\n      if section.xpath(\"img\") == []:\n        error_list.append(\"Section %s has class %s but it doesn\'t have any image.\" % (count, section.get(\"class\")))\n      else:\n        if section.xpath(\"img\")[0].get(\"title\") == None:\n          error_list.append(\"At section %s, img has no title attribute.\" % count)\n\n        if section.xpath(\"img\")[0].get(\"alt\") == None:\n          error_list.append(\"At section %s, img has no alt attribute.\" % count)\n\n    if section.xpath(\"details\") == []:\n      error_list.append(\"Section %s has no details tag.\" % (count))\n\n  return error_list'),(15281,'TestPage Test Page property sheet'),(15283,'Review Property sheets for Review Portal Type'),(15291,'SubmitAction'),(15292,'Submit'),(15293,'Reject Action'),(15294,'Reject'),(15295,'Delete Action Delete a document in ERP5'),(15296,'Delete Delete a document in ERP5'),(15297,'ApproveAction'),(15298,'Approve'),(15299,'Submitted'),(15300,'Rejected'),(15301,'Gadget Media Player Document List JS gadget_erp5_page_ojs_media_player_document_list.js 001 /*global window, rJS, RSVP */ /*jslint nomen: true, indent: 2, maxerr: 3 */\n(function (window, rJS, RSVP) { \"use strict\"; rJS(window) /////////////////////\n//////////////////////////////////////////// // Acquired methods //////////////\n/////////////////////////////////////////////////// .declareAcquiredMethod\n(\"updateHeader\", \"updateHeader\") .declareAcquiredMethod(\"getUrlParameter\",\n\"getUrlParameter\") .declareAcquiredMethod(\"getUrlFor\", \"getUrlFor\")\n.declareAcquiredMethod(\"jio_allDocs\", \"jio_allDocs\") .declareAcquiredMethod\n(\"getSetting\", \"getSetting\") //////////////////////////////////////////////////\n/////////////// // declared methods ///////////////////////////////////////////\n////////////////////// .allowPublicAcquisition(\"jio_allDocs\", function\n(param_list) { var gadget = this; return gadget.jio_allDocs(param_list[0])\n.push(function (result) { var i, date, len = result.data.total_rows; for (i =\n0; i < len; i += 1) { if (result.data.rows[i].value.hasOwnProperty\n(\"modification_date\")) { date = new Date(result.data.rows\n[i].value.modification_date); result.data.rows[i].value.modification_date = {\nfield_gadget_param: { allow_empty_time: 0, ampm_time_style: 0, css_class:\n\"date_field\", date_only: 0, description: \"The Date\", editable: 0, hidden: 0,\nhidden_day_is_last_day: 0, \"default\": date.toUTCString(), key:\n\"modification_date\", required: 0, timezone_style: 0, title: \"Modification\nDate\", type: \"DateTimeField\" } }; result.data.rows[i].value[\"listbox_uid:list\"]\n= { key: \"listbox_uid:list\", value: 2713 }; } } return result; }); })\n.allowPublicAcquisition(\'notifySubmit\', function () { return this.triggerSubmit\n(); }) .declareMethod(\"triggerSubmit\", function () { var argument_list =\narguments; return this.getDeclaredGadget(\'form_list\') .push(function (gadget) {\nreturn gadget.tri