_allDocs({ query: query, limit: 10000, sort_on:\n[[\'delivery.start_date\', \'ascending\']], //select_list: [\'reference\', \'title\',\n\'uid\'] select_list: [\'reference\', \'title\', \'start_date\', \'stop_date\', \'uid\']\n}); }) .push(function (order_list) { var query, delivery_uid_list,\nempty_causality_delivery_list = [], i, order;\ngadget.property_dict.empty_causality_delivery_list =\nempty_causality_delivery_list; order_list = order_list.data.rows; console.log\n(\"order_list\", order_list); console.log(\"order_list.length\",\norder_list.length); for (i = 0; i < order_list.length; i = i + 1) { order =\norder_list[i].value; order.gantt_color = \"rgb(208, 72, 72)\";\nempty_causality_delivery_list.push(order); } console.log\n(\"empty_causality_delivery_list with orders\", empty_causality_delivery_list); /\n/ Then search all production report not finished to find out the // list of\nproduction orders still having work on them query = \'portal_type:=\n\"Manufacturing Execution\" AND NOT simulation_state: (\"draft\", \"cancelled\",\n\"delivered\")\'; delivery_uid_list = option_dict.delivery_uid_list; if\n((delivery_uid_list !== undefined) && (delivery_uid_list.length > 0)) { query =\nquery + \' AND uid: (\' + delivery_uid_list.join(\', \') + \')\'; } return\ngadget.jio_allDocs({ query: query, limit: 10000, sort_on:\n[[\'delivery.start_date\', \'ascending\']], select_list: [\'reference\', \'title\',\n\'start_date\', \'stop_date\', \'uid\', \'causality_uid\'] }); }) .push(function\n(delivery_list) { // try to search for other manufacturing execution having\nsame causality as // other manufacturing execution already found var\ncausality_uid_list = [0], // Initiliaze with 0 to make sure to have at least\none uid to search for i, delivery, query, empty_causality_delivery_list =\ngadget.property_dict.empty_causality_delivery_list, delivery_uid_list;\ndelivery_list = delivery_list.data.rows; for (i = 0; i < delivery_list.length;\ni = i + 1) { delivery = delivery_list[i].v