       });\n              }\n              if (result_list_length === 1 &&\n                  (gadget.state.auto_redirect === true ||\n                    command !== \"\")) {\n                // if 1 result, and redirect or command ,we go there\n                return gadget.redirect({\n                  command: \'raw\',\n                  options: {\n                    url: query_result.data.rows[0].value.url_string +\n                      parameter\n                  }\n                });\n              }\n              return gadget.redirect({\n                command: \'display\',\n                options: {\n                  page: \"ojs_bookmark_list\",\n                  extended_search: search\n                }\n              });\n            });\n        }\n      });\n  }\n\n  rJS(window)\n    .declareAcquiredMethod(\"getUrlFor\", \"getUrlFor\")\n    .declareAcquiredMethod(\"redirect\", \"redirect\")\n    .declareAcquiredMethod(\"updateHeader\", \"updateHeader\")\n    .declareAcquiredMethod(\'getSetting\', \'getSetting\')\n    .declareAcquiredMethod(\"jio_allDocs\", \"jio_allDocs\")\n    .declareAcquiredMethod(\"getSetting\", \"getSetting\")\n    .declareAcquiredMethod(\"setSetting\", \"setSetting\")\n    .declareAcquiredMethod(\"notifySubmitting\", \"notifySubmitting\")\n\n\n\n    .declareMethod(\'triggerSubmit\', function () {\n      return this.element.querySelector(\'button[type=\"submit\"]\').click();\n    })\n\n    .declareMethod(\"render\", function (options) {\n      var gadget = this;\n      return new RSVP.Queue()\n        .push(function () {\n          return gadget.updateHeader({\n            page_title: \'Search in Bookmarks\',\n            submit_action: true\n          });\n        })\n        .push(function () {\n          return RSVP.all([\n            gadget.getSetting(\'portal_type\'),\n            gadget.getSetting(\'bookmark_auto_redirect\', true),\n            gadget.getSetting(\n              \'bookmark_search_engine\',\n              \"https://duckduckgo.com/?q=\"\n            )\n          ]);\n        })\n        .push(function (result) {\n          return gadget.changeState({\n            search: options.search || \"\",\n            portal_type: result[0],\n            auto_redirect: result[1],\n            search_engine: result[2],\n            extended_search: options.extended_search || \"\"\n          });\n        });\n    })\n\n    .onStateChange(function (modification_dict) {\n      var gadget = this;\n      if (modification_dict.search) {\n        return redirectFromSearch(gadget, gadget.state.search);\n      }\n      if (modification_dict.extended_search) {\n        return redirectFromSearch(gadget, modification_dict.extended_search);\n      }\n      return gadget.getDeclaredGadget(\'erp5_searchfield\')\n        .push(function (search_gadget) {\n          return search_gadget.render({\n            field_json: {\n              value: gadget.state.search,\n              editable: true,\n              title: \"Search\",\n              required: true,\n              key: \"search\"\n            }\n          });\n        });\n    })\n    .allowPublicAcquisition(\"notifyFocus\", function notifyFocus() {\n      // All html5 fields in ERP5JS triggers this method when focus\n      // is triggered. This is usefull to display error text.\n      // But, in the case of this gadget, we don\'t need to handle anything.\n      return;\n    })\n    .allowPublicAcquisition(\"notifyBlur\", function notifyFocus() {\n      // All html5 fields in ERP5JS triggers this method when blur\n      // is triggered now. This is usefull to display error text.\n      // But, in the case of this gadget, we don\'t need to handle anything.\n      return;\n    })\n    .allowPublicAcquisition(\"notifyValid\", function () {\n      return true;\n    })\n    .allowPublicAcquisition(\"notifyInvalid\", function () {\n      return true;\n    })\n    .onEvent(\"submit\", function () {\n      var gadget = this;\n      return gadget.notifySubmitting()\n        .push(function () {\n          return gadget.getDeclaredGadget(\'erp5_searchfield\');\n        })\n        .push(function (search_gadget) {\n          return search_gadget.getContent();\n        })\n        .push(function (content) {\n          return redirectFromSearch(gadget, content.search);\n        });\n    });\n\n}(window, RSVP, rJS));'),(15407,'OfficeJS Add Bookmark gadget_erp5_page_ojs_add_bookmark.html 001'),(15408,'OfficeJS Add Bookmark JS gadget_erp5_page_ojs_add_bookmark.js 001 /*global window, rJS, RSVP */ /*jslint nomen: true, indent: 2, maxerr: 3 */\n(function (window, rJS, RSVP) { \"use strict\"; rJS(window) /////////////////////\n//////////////////////////////////////////// // Acquired methods //////////////\n/////////////////////////////////////////////////// .declareAcquiredMethod\n(\"updateHeader\", \"updateHeader\") .declareAcquiredMethod(\"getSetting\",\n\"getSetting\") .declareAcquiredMethod(\"getUrlFor\", \"getUrlFor\")\n.declareAcquiredMethod(\"redirect\", \"redirect\") .declareAcquiredMethod\n(\"jio_post\", \"jio_post\") //////////////////////////////////////////////////////\n/////////// // declared methods ///////////////////////////////////////////////\n////////////////// .onEvent(\'submit\', function () { var gadget = this; return\ngadget.getDeclaredGadget(\'form_view\') .push(function (form_gadget) { return\nform_gadget.getContent(); }) .push(function (doc) { doc.modification_date =\n(new Date()).toUTCString(); return gadget.jio_post(doc); }) .push(function () {\n// Workaround, find a way to open document without break gadget. return\ngadget.redirect({\"command\": \"change\", \"options\": {\"page\":\n\"ojs_bookmark_list\"}}); }); }) .declareMethod(\"triggerSubmit\", function () {\nreturn this.element.querySelector(\'button[type=\"submit\"]\').click(); }, {mutex:\n\'render\'}) .declareMethod(\"render\", function (options) { var gadget = this;\nreturn RSVP.Queue() .push(function () { return RSVP.all([\ngadget.getDeclaredGadget(\'form_view\'), gadget.getSetting(\'portal_type\'),\ngadget.getSetting(\'parent_relative_url\') ]); }) .push(function (result) {\nreturn result[0].render({ erp5_document: { \"_embedded\": {\"_view\": {\n\"my_reference\": { \"description\": \"The name of a document in ERP5\", \"title\":\n\"Reference\", \"default\": \"\", \"css_class\": \"\", \"required\": 0, \"editable\": 1,\n\"key\": \"reference\", \"hidden\": 0, \"type\": \"StringField\" }, \"my_title\": {\n\"description\": \"The name of a document in ERP5\", \"title\": \"Title\", \"default\":\n\"\", \"css_class\": \"\", \"required\": 0, \"editable\": 1, \"key\": \"title\", \"hidden\": 0,\n\"type\": \"StringField\" }, \"my_url_string\": { \"description\": \"\", \"title\": \"Url\",\n\"default\": options.url_string || \"\", \"css_class\": \"\", \"required\": 1,\n\"editable\": 1, \"key\": \"url_string\", \"hidden\": 0, \"type\": \"StringField\" },\n\"my_description\": { \"description\": \"\", \"title\": \"Description\", \"default\": \"\",\n\"css_class\": \"\", \"required\": 0, \"editable\": 1, \"key\": \"description\", \"hidden\":\n0, \"type\": \"TextAreaField\" }, \"my_portal_type\": { \"description\": \"The name of a\ndocument in ERP5\", \"title\": \"Portal Type\", \"default\": result[1], \"css_class\":\n\"\", \"required\": 1, \"editable\": 1, \"key\": \"portal_type\", \"hidden\": 1, \"type\":\n\"StringField\" }, \"my_parent_relative_url\": { \"description\": \"\", \"title\":\n\"Parent Relative Url\", \"default\": result[2], \"css_class\": \"\", \"required\": 1,\n\"editable\": 1, \"key\": \"parent_relative_url\", \"hidden\": 1, \"type\": \"StringField\"\n} }}, \"_links\": { \"type\": { // form_list display portal_type in header name: \"\"\n} } }, form_definition: { group_list: [[ \"left\", [[\"my_reference\"],\n[\"my_title\"], [\"my_url_string\"], [\"my_description\"], [\"my_portal_type\"],\n[\"my_parent_relative_url\"]] ]] } }); }) .push(function () { return\ngadget.updateHeader({ page_title: \"New Bookmark\", save_action: true }); }); },\n{mutex: \'render\'}); }(window, rJS, RSVP));'),(15409,'OfficeJS Bookmark Manager router Gadget gadget_officejs_bookmark_manager_router.html 001'),(15410,'OfficeJS Application Panel Gadget gadget_erp5_ojs_bookmark_panel.html 001'),(15411,'Officejs Bookmark Manager Manifest gadget_officejs_bookmark.json 001 { \"short_name\": \"Web Bookmark\", \"name\": \"OfficeJS Web Bookmark Manager\",\n\"description\": \"Web Based Bookmark Manager\", \"icons\": [{ \"src\":\n\"bookmark_manager_logo.svg\", \"sizes\": \"any\", \"type\": \"image/svg\" }],\n\"start_url\": \"../../\", \"display\": \"standalone\" }'),(15412,'index.html test/index.html 001 <html><body><h1>It works!</h1> <p>This is the default web page for this server.\n</p> <p>The web server software is running but no content has been added, yet.\n</p> </body></html>'),(15413,'computers.html resources/computers.html 001 <!DOCTYPE html> <html> <head> <meta http-equiv=\"Content-type\" content=\"text/\nhtml; charset=utf-8\" /> <meta name=\"viewport\" content=\"width=device-width\" />\n<title>Nexedi ERP5 | Computers</title> <!-- TODO: gadget mobile meta --> <!--\nTODO: schema.org? --> <!-- TODO: all JQM widgets should have enhanced markup vs\nletting JQM enhance --> <!-- normalize --> <link rel=\"stylesheet\" href=\"css/\nnormalize.css\"> <!-- JQM structure --> <link rel=\"stylesheet\" href=\"css/\njquery-mobile/jquery-mobile.latest.css\"> <!-- JQM extensions --> <link rel=\n\"stylesheet\" href=\"css/extensions.css\"> <!-- fontawesome icons --> <link rel=\n\"stylesheet\" href=\"css/fontawesome.css\"> <!-- JQM custom themes (slapos-white,\nslapos-black, slapos-active) --> <link rel=\"stylesheet\" href=\"css/themes.css\">\n<!-- generic CSS --> <link rel=\"stylesheet\" href=\"css/css.css\"> </head> <body>\n<div id=\"computers\" data-role=\"page\" data-theme=\"slapos-white\"> <!-- left panel\n--> <div data-role=\"panel\" id=\"menu_computers\" data-theme=\"slapos-black\" class=\n\"pa