"internal_server_error\": 500,\n  \"not_implemented\": 501,\n  \"bad_gateway\": 502,\n  \"service_unavailable\": 503,\n  \"gateway_timeout\": 504,\n  \"insufficient_storage\": 507\n};\n\nconstants.http_action = {\n  \"0\": \"error\",\n  \"550\": \"error\",\n  \"551\": \"error\",\n  \"Unknown\": \"error\",\n  \"Internal JIO Error\": \"error\",\n  \"Internal Storage Error\": \"error\",\n  \"unknown\": \"error\",\n  \"internal_jio_error\": \"error\",\n  \"internal_storage_error\": \"error\",\n\n  \"200\": \"success\",\n  \"201\": \"success\",\n  \"204\": \"success\",\n  \"205\": \"success\",\n  \"206\": \"success\",\n  \"400\": \"error\",\n  \"401\": \"error\",\n  \"402\": \"error\",\n  \"403\": \"error\",\n  \"404\": \"error\",\n  \"405\": \"error\",\n  \"406\": \"error\",\n  \"407\": \"error\",\n  \"408\": \"error\",\n  \"409\": \"error\",\n  \"410\": \"error\",\n  \"411\": \"error\",\n  \"412\": \"error\",\n  \"413\": \"error\",\n  \"414\": \"error\",\n  \"415\": \"error\",\n  \"416\": \"error\",\n  \"417\": \"error\",\n  \"418\": \"error\",\n  \"419\": \"retry\",\n  \"500\": \"retry\",\n  \"501\": \"error\",\n  \"502\": \"error\",\n  \"503\": \"retry\",\n  \"504\": \"retry\",\n  \"507\": \"error\",\n\n  \"Ok\": \"success\",\n  \"Created\": \"success\",\n  \"No Content\": \"success\",\n  \"Reset Content\": \"success\",\n  \"Partial Content\": \"success\",\n  \"Bad Request\": \"error\",\n  \"Unauthorized\": \"error\",\n  \"Payment Required\": \"error\",\n  \"Forbidden\": \"error\",\n  \"Not Found\": \"error\",\n  \"Method Not Allowed\": \"error\",\n  \"Not Acceptable\": \"error\",\n  \"Proxy Authentication Required\": \"error\",\n  \"Request Timeout\": \"error\",\n  \"Conflict\": \"error\",\n  \"Gone\": \"error\",\n  \"Length Required\": \"error\",\n  \"Precondition Failed\": \"error\",\n  \"Request Entity Too Large\": \"error\",\n  \"Request-URI Too Long\": \"error\",\n  \"Unsupported Media Type\": \"error\",\n  \"Requested Range Not Satisfiable\": \"error\",\n  \"E