e later\n//       params = priv.splitSearchParams(),\n//       callback = function () {\n//         $.mobile.changePage(\"computers.html\", {\n//           \"transition\":\"fade\",\n//           \"reverse\":\"true\"\n//         });\n//       };\n//\n//     for (i = 0; i < params.length; i += 1) {\n//       parameter = params[i].split(\"=\");\n//       if (parameter[0] === \"mode\") {\n//         switch (parameter[1]) {\n//           case \"edit\":\n//             method = \"put\";\n//             break;\n//           case \"clone\":\n//           case \"add\":\n//             method = \"post\";\n//             break;\n//         }\n//         if (method !== undefined) {\n//           object = priv.validateObject(\n//             priv.serializeObject($(\".display_object\"))\n//           );\n//           // fallback to eliminate _id on clone\n//           // TODO: do somewhere else!\n//           if (method === \"post\") {\n//             delete object._id;\n//           }\n//           priv.modifyObject(object, method, callback);\n//         } else {\n//           alert(\"missing command!, cannot store\");\n//         }\n//       }\n//     }\n//   })\n//   // update navbar depending on item selected\n//   .on(\"change\", \"table tbody th input[type=checkbox]\", function(e) {\n//     var allChecks = $(e.target).closest(\"tbody\").find(\"th input[type=checkbox]:checked\"),\n//       selected = allChecks.length,\n//       trigger = $(\".navbar .new_item\");\n//\n//     if (selected === 1) {\n//       trigger.addClass(\"ui-btn-active clone_item\").attr(\"href\",\"computer.html?mode=clone&item=\" + e.target.id);\n//     } else {\n//       trigger.removeClass(\"ui-btn-active clone_item\").attr(\"href\",\"computer.html?mode=add\");\n//     }\n//\n//   });\n\n\n\n\n\n\n \n\n\n\n\n  //       //TODO: can\'t set bindings, because we don\'t have a parent?\n  //       // or always set on document for local and global should be autoset?\n  //       // popup content handling\n  //       if (search_popup) {\n  //         $parent.on(\"click\", \"a.extended_search\", function (e) {\n  //           priv.generatePopupContents(e, \"self\", portal_type, settings.view, gadget_id);\n  //         });\n  //       }\n  //\n  //       // table actions\n  //       if (search_popup) {\n  //         // NOTE: can\'t bind to $parent, because JQM moves the popup\n  //         // outside of $parent\n  //         page = $parent.closest(\"div.ui-page\");\n  //\n  //         if (page.data(\"bindings\") === undefined) {\n  //           page.data(\"bindings\", {});\n  //         }\n  //         if (page.data(\"bindings\")[\"table_action\"] === undefined) {\n  //           page.data(\"bindings\")[\"table_action\"] = true;\n  //\n  //           $(document).on(\"click\", \"a.table_action\", function (e) {\n  //             var target,\n  //               action = e.target.getAttribute(\"data-action\"),\n  //               popup = $(e.target).closest(\".ui-popup\"),\n  //               form = popup.find(\"form\");\n  //\n  //             if (form.length === 0) {\n  //               target = popup.find(\".ui-content\");\n  //             } else {\n  //               target = form;\n  //             }\n  //             switch (action) {\n  //               case \"add_criteria_search\":\n  //                 target.append(priv.generateSearchCriteria(e.target))\n  //                   .enhanceWithin();\n  //               break;\n  //\n  //               case \"add_criteria_config\":\n  //                 target.append(priv.generateConfigCriteria(e.target))\n  //                   .enhanceWithin();\n  //               break;\n  //               case \"delete_criteria\":\n  //                 $(e.target).closest(\"div.ui-grid-row\").remove();\n  //               break;\n  //             }\n  //           });\n  //         }\n  //       }\n  //\n//   });'),(15436,'Officejs Appstore Index gadget_officejs_appstore.html 001 沪ICP备14008524号\n<!DOCTYPE html> <html> <head> <meta http-equiv=\"Content-type\" content=\"text/\nhtml; charset=utf-8\" /> <meta name=\"viewport\" content=\"width=device-width\" />\n<title></title> <link rel=\"stylesheet\" href=\"css/jquery-mobile/\njquery-mobile.latest.css\"> <link rel=\"stylesheet\" href=\"css/extensions.css\">\n<link rel=\"stylesheet\" href=\"css/fontawesome.css\"> <link rel=\"stylesheet\" href=\n\"css/themes.css\"> <link rel=\"stylesheet\" href=\"css/css.css\"> </head> <body> <!\n-- global panel --> <!-- global header --> <div id=\"dashboard\" data-role=\"page\"\ndata-theme=\"slapos-white\" data-module=\"dashboard\"> <div class=\"ui-content\"> <!\n-- nothing to see here --> </div> <div style=\"text-align:center;\"> <a href=\n\"http://www.miibeian.gov.cn/\" style=\"color:white\">沪ICP备14008524号</a> </div>\n</div> <!-- global footer (not used) --> <!-- global popup --> <!-- JQM -->\n<script src=\"js/libs/jquery/jquery.js\"></script> <script src=\"js/libs/\njquery-mobile/jquery-mobile.js\"></script> <script src=\"js/extensions.js\"></\nscript> <!-- JIO --> <script src=\"js/libs/jio/sha256.amd.js\"></script> <script\nsrc=\"js/libs/jio/rsvp-custom.js\"></script> <script src=\"js/libs/jio/jio.js\"></\nscript> <script src=\"js/libs/jio/complex_queries.js\"></script> <script src=\"js/\nlibs/jio/localstorage.js\"></script> <!-- plugins --> <script src=\"js/plugins/\nvalidval/jquery.validVal.js\"></script> <script src=\"js/plugins/i18next/\ni18next.js\"></script> <!-- stuff happens here --> <script src=\"js/\nerp5_loader.js\"></script> </body> </html>'),(15437,'index.html dev/index.html 001 <!DOCTYPE html> <!--[if lt IE 7]> <html class=\"no-js lt-ie9 lt-ie8 lt-ie7\"> <!\n[endif]--> <!--[if IE 7]> <html class=\"no-js lt-ie9 lt-ie8\"> <![endif]--> <!--\n[if IE 8]> <html class=\"no-js lt-ie9\"> <![endif]--> <!--[if gt IE 8]><!-->\n<html class=\"no-js\"><!--<![endif]--><head> <meta http-equiv=\"content-type\"\ncontent=\"text/html; charset=UTF-8\"> <meta charset=\"utf-8\"> <meta http-equiv=\n\"X-UA-Compatible\" content=\"IE=edge,chrome=1\"> <title>OfficeJS 初步说明</title>\n<meta name=\"description\" content=\"\"> <meta name=\"viewport\" content=\"width=\ndevice-width\"> <meta name=\"description\" content=\"\"> <meta name=\"viewport\"\ncontent=\"width=device-width\"> <link href=\'http://fonts.googleapis.com/css?\nfamily=Open+Sans:400,300,600,700,800&subset=latin,cyrillic-ext\' rel=\n\'stylesheet\' type=\'text/css\'> <link rel=\"stylesheet\" href=\"css/\nnormalize.min.css\"> <link rel=\"stylesheet\" href=\"css/main.css\"> <script src=\"js\n/vendor/modernizr-2.6.2-respond-1.1.0.min.js\"></script> <!--<link href=\n\"dev_files/css.css\" rel=\"stylesheet\" type=\"text/css\"> <link rel=\"stylesheet\"\nhref=\"dev_files/normalize.css\"> <link rel=\"stylesheet\" href=\"dev_files/\nmain.css\"> <script src=\"dev_files/modernizr-2.html\"></script>--> </head> <body>\n<!--[if lt IE 7]> <p class=\"chromeframe\">You are using an <strong>outdated</\nstrong> browser. Please <a href=\"http://browsehappy.com/\">upgrade your browser\n</a> or <a href=\"http://www.google.com/chromeframe/?redirect=true\">activate\nGoogle Chrome Frame</a> to improve your experience.</p> <![endif]--> <div class\n=\"main-container\"> <div class=\"main wrapper clearfix\"> <article> <h1 class=\n\"page_title\">OfficeJS 初步说明 </h1> <p>Version: 001 - 2013-11-19</p> <p>这篇文\n章详述了OfficeJS离线HTML5应用的初步说明。 </p> <h2>耦合性</h2> <p>OfficeJS 应用\n依赖于以下的库：</p> <ul> <li><a href=\"http://jquerymobile.com/\">jQuery 移动</\na>: 独立平台用户界面控件(<a href=\"http://jquerymobile.com/gbs/\"> 被至少30种网络\n浏览器支持</a>)</li> <li><a href=\"http://j-io.org/\">J-IO</a>: 独立后端的持久数\n据管理(离线, 在线, 复制，ryption等)</li> <li><a href=\"http://renderjs.org/\">\nRenderJS</a>: 可重复使用的组件系统 (可选的)</li> </ul> <p>提交给OfficeJS HTML5\n应用商店的应用必须依照以下规则为这些库提供支持:</p> <p> </p><table align=\n\"center\" border=\"1\"> <tbody><tr> <th></th> <th>jQuery Mobile</th> <th>JIO</th>\n<th>RenderJS</th> </tr> <tr> <td>无可持续性数据的应用</td> <td>推荐</td> <td>可\n选</td> <td>可选</td> </tr> <tr> <td>有可持续性数据的应用</td> <td>推荐</td>\n<td>必选</td> <td>可选</td> </tr> <tr> <td>应用数据可被嵌入另一应用程序中</td>\n<td>推荐</td> <td>必选</td> <td>必选</td> </tr> </tbody></table> <p></p> <h2>结\n构</h2> <p>一个OfficeJS应用程序就是一个定义了元数据和耦合性（CSS，JS）的HTML5文\n档。你可以从使用以下的OfficeJS 应用程序模板开始。</p> <code></code><pre style=\n\"font-size:80%\"><code>&lt;!DOCTYPE html&gt; &lt;html manifest=\n\"manifest.appcache\"&gt; &lt;head&gt; &lt;meta http-equiv=\"Content-type\" content\n=\"text/html; charset=utf-8\"&gt; &lt;meta name=\"viewport\" content=\"width=\ndevice-width\" /&gt; &lt;!-- required meta tags/information --&gt; &lt;title&gt;\nApplication Title&lt;/title&gt; &lt;meta name=\"description\" content=\n\"Application Description\"/&gt; &lt;meta name=\"keywords\" content=\"Category_1,\nCategory_2\"&gt; &lt;meta name=\"author\" content=\"John Doe|johndoe@internetl.com\"\n/&gt; &lt;!-- CSS --&gt; &lt;link rel=\"stylesheet\" href=\"http://code.jquery.com\n/mobile/git/jquery.mobile-git.css\"&gt; &lt;!-- Custom Stylesheets --&gt; &lt;\nlink rel=\"stylesheet\" href=\"path/to/stylesheet_a\"&gt; &lt;!-- JQUERY/JQUERY\nMOBILE --&gt; &lt;script type=\"text/javascript\" src=\"http://code.jquery.com/\njquery-1.10.1.js\"&gt;&lt;/script&gt; &lt;script type=\"text/javascript\" src=\n\"http://code.jquery.com/mobile/git/jquery.mobile-git.js\"&gt;&lt;/script&gt; &\nlt;!-- JIO --&gt; &lt;script type=\"text/javascript\" src=\"path/to/sha256.amd.js\"\n&gt;&lt;/script&gt; &lt;script type=\"text/javascript\" src=\"path/to/\nrsvp-custom.js\"&gt;&lt;/script&gt; &lt;script type=\"text/javascript\" src=\"path/\nto/jio.js\"&gt;&lt;/script&gt; &lt;script type=\"text/javascript\" src=\"path/to/\ncomplex_queries.js\"&gt;&lt;/script&gt; &lt;!-- JIO storages, for example --&gt;\n&lt;script type=\"text/javascript\" src=\"path/to/localstorage.js\"&gt;&lt;/script&\ngt; &lt;!-- RenderJS --&gt; &lt;script type=\"text/javascript\" src=\"path/to/\nrenderjs.js\"&gt;&lt;/script&gt; &lt;!-- 3rd Party Plugins/Custom Scripts --&gt;\n&lt;script type=\"text/javascript\" src=\"path/to/plugin_a.js\"&gt;&lt;/script&gt;\n&lt;script type=\"text/javascript\" src=\"path/to/plugin_b.js\"&gt;&lt;/script&gt;\n&lt;/head&gt; &lt;body&gt; &lt;!-- Content of application --&gt; &lt;/body&gt;\n&lt;/html&gt; </code></pre> <p> <b>请注意:</b> </p><ul> <li>应用程序都应该有一\n个manifest资源配置文件明确指出被贮藏的文件。</li> <li>自定义脚本和添加的插件可\n以被容易的添加到HTML5文档内容的后面。容易融入的插件例子包括有： <ul> <li>表单验\n证 - <a href=\"http://validval.frebsite.nl/\">Validval</a></li> <li>i18n 支持 -\n<a href=\"http://jamuhl.github.io/i18next/\">i18next</a></li> </ul> </li> <li>在\n开发HTML5应用程序时注意 <a href=\"http://view.jquerymobile.com/master/demos/\nnavigation/\">jQuery Mobile Ajax 基础导航</a>。</li> </ul> <p></p> <h2>应用案例\n</h2> <ul> <li><a href=\"http://www.officejs.com/app/task_manager/\">任务管理</a>\n提供了一个基于JIO技术的简明的关于持续应用的 JQuery Mobile 案例。</li></ul> <br>\n<h2>提交你的应用程序</h2> <p>你可以在此提交你的应用: &nbsp; <a href=\"http://\nofficejs.com/#apps\">到 officejs.com上提交应用</a></p><a href=\"http://\nofficejs.com/#apps\"> </a></article><a href=\"http://officejs.com/#apps\"> </a></\ndiv><a href=\"http://officejs.com/#apps\"> <!-- #main --> </a></div><a href=\n\"http://officejs.com/#apps\"> </a></body></html>'),(15438,'index.en.html dev/index.en.html 001 <!DOCTYPE html> <!--[if lt IE 7]> <html class=\"no-js lt-ie9 lt-ie8 lt-ie7\"> <!\n[endif]--> <!--[if IE 7]> <html class=\"no-js lt-ie9 lt-ie8\"> <![endif]--> <!--\n[if IE 8]> <html class=\"no-js lt-ie9\"> <![endif]--> <!--[if gt IE 8]><!-->\n<html class=\"no-js\"> <!--<![endif]--> <head> <meta charset=\"utf-8\"> <meta\nhttp-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\"> <title></title> <meta\nname=\"description\" content=\"\"> <meta name=\"viewport\" content=\"width=\ndevice-width\"> <link href=\'http://fonts.googleapis.com/css?family=\nOpen+Sans:400,300,600,700,800&subset=latin,cyrillic-ext\' rel=\'stylesheet\' type=\n\'text/css\'> <link rel=\"stylesheet\" href=\"css/normalize.min.css\"> <link rel=\n\"stylesheet\" href=\"css/main.css\"> <script src=\"js/vendor/\nmodernizr-2.6.2-respond-1.1.0.min.js\"></script> </head> <body> <!--[if lt IE\n7]> <p class=\"chromeframe\">You are using an <strong>outdated</strong> browser.\nPlease <a href=\"http://browsehappy.com/\">upgrade your browser</a> or <a href=\n\"http://www.google.com/chromeframe/?redirect=true\">activate Google Chrome Frame\n</a> to improve your experience.</p> <![endif]--> <div class=\"main-container\">\n<div class=\"main wrapper clearfix\"> <article > <h1 class=\"page_title\">OfficeJS\nPreliminary Specification</h1> <p>Version: 001 - 2013-11-19</p> <p>This\ndocuments defines the specification of OfficeJS offline HTML5 applications. </\np> <h2>Dependencies</h2> <p>OfficeJS applications depends on the following\nlibraries:</p> <ul> <li><a href=\"http://jquerymobile.com/\">jQuery Mobile</a>:\nplatform independent user interface widgets (<a href=\"http://jquerymobile.com/\ngbs/\">more than 30 Web browsers supported</a>)</li> <li><a href=\"http://\nj-io.org/\">J-IO</a>: backend independent persistent data management (offline,\nonline, replication, encryption, etc.)</li> <li><a href=\"http://renderjs.org/\">\nRenderJS</a>: reusable component system (optional)</li> </ul> <p>Applications\nsubmitted to OfficeJS HTML5 appstore must provide support for these libraries\nbased on the following rules:</p> <p> <table border=\"1\" align=\"center\"> <tr>\n<th></th> <th>jQuery Mobile</th> <th>JIO</th> <th>RenderJS</th> </tr> <tr> <td>\nApplication has no persistent data</td> <td>recommended</td> <td>optional</td>\n<td>optional</td> </tr> <tr> <td>Application has persistent data</td> <td>\nrecommended</td> <td>required</td> <td>optional</td> </tr> <tr> <td>Application\ndata can be embedded by another application</td> <td>recommended</td> <td>\nrequired</td> <td>required</td> </tr> </table> </p> <h2>Structure</h2> <p>An\nOfficeJS application is an HTML5 file that defines metadata and dependencies\n(CSS, JS) of the application. You can use the OfficeJS application template\nbelow to start.</p> <code><pre style=\"font-size:80%\"> &lt;!DOCTYPE html&gt; &\nlt;html manifest=\"manifest.appcache\"&gt; &lt;head> &lt;meta http-equiv=\n\"Content-type\" content=\"text/html; charset=utf-8\"&gt; &lt;meta name=\"viewport\"\ncontent=\"width=device-width\" /&gt; &lt;!-- required meta tags/information --&\ngt; &lt;title>Application Title&lt;/title&gt; &lt;meta name=\"description\"\ncontent=\"Application Description\"/&gt; &lt;meta name=\"keywords\" content=\n\"Category_1, Category_2\"> &lt;meta name=\"author\" content=\"John Doe|\njohndoe@internetl.com\"/&gt; &lt;!-- CSS --&gt; &lt;link rel=\"stylesheet\" href=\n\"http://code.jquery.com/mobile/git/jquery.mobile-git.css\"&gt; &lt;!-- Custom\nStylesheets --&gt; &lt;link rel=\"stylesheet\" href=\"path/to/stylesheet_a\"&gt; &\nlt;!-- JQUERY/JQUERY MOBILE --&gt; &lt;script type=\"text/javascript\" src=\"http:\n//code.jquery.com/jquery-1.10.1.js\"&gt;&lt;/script&gt; &lt;script type=\"text/\njavascript\" src=\"http://code.jquery.com/mobile/git/jquery.mobile-git.js\"&gt;&\nlt;/script&gt; &lt;!-- JIO --&gt; &lt;script type=\"text/javascript\" src=\"path/\nto/sha256.amd.js\"&gt;&lt;/script&gt; &lt;script type=\"text/javascript\" src=\n\"path/to/rsvp-custom.js\"&gt;&lt;/script&gt; &lt;script type=\"text/javascript\"\nsrc=\"path/to/jio.js\"&gt;&lt;/script&gt; &lt;script type=\"text/javascript\" src=\n\"path/to/complex_queries.js\"&gt;&lt;/script&gt; &lt;!-- JIO storages, for\nexample --&gt; &lt;script type=\"text/javascript\" src=\"path/to/localstorage.js\"&\ngt;&lt;/script&gt; &lt;!-- RenderJS --&gt; &lt;script type=\"text/javascript\"\nsrc=\"path/to/renderjs.js\"&gt;&lt;/script&gt; &lt;!-- 3rd Party Plugins/Custom\nScripts --&gt; &lt;script type=\"text/javascript\" src=\"path/to/plugin_a.js\"&gt;&\nlt;/script&gt; &lt;script type=\"text/javascript\" src=\"path/to/plugin_b.js\"&gt;&\nlt;/script&gt; &lt;/head&gt; &lt;body&gt; &lt;!-- Content of application --&gt;\n&lt;/body&gt; &lt;/html&gt; </code></pre> <p> <b>Please note:</b> <ul> <li>\nApplications should have a manifest file specifying files to be cached</li>\n<li>Custom script and additional plugins can simply be added at the end of the\nHTML5 file\'s body. Examples of easy to integrate plugins include: <ul> <li>Form\nValidation - <a href=\"http://validval.frebsite.nl/\">Validval</a></li> <li>i18n\nSupport - <a href=\"http://jamuhl.github.io/i18next/\">i18next</a></li> </ul> </\nli> <li>Beware of the <a href=\"http://view.jquerymobile.com/master/demos/\nnavigation/\">jQuery Mobile Ajax based navigation</a> when creating an HTML5\napplication.</li> </ul> </p> <h2>Application Examples</h2> <ul> <li><a href=\n\"http://www.officejs.com/app/task_manager/\">Task Manager</a> provides a simple\nJQuery Mobile example of a persistent application based on JIO.</ul> </ul> <br\n/> <h2>Submitting your own application</h2> <p>You can submit your own\napplications here: &nbsp; <a href=\"http://officejs.com/#apps\">Submit\napplication on officejs.com</p> </article> </div> <!-- #main --> </div> </body>\n</html>'),(15439,'index.cz.html dev/index.cz.html 001 <!DOCTYPE html> <!--[if lt IE 7]> <html class=\"no-js lt-ie9 lt-ie8 lt-ie7\"> <!\n[endif]--> <!--[if IE 7]> <html class=\"no-js lt-ie9 lt-ie8\"> <![endif]--> <!--\n[if IE 8]> <html class=\"no-js lt-ie9\"> <![endif]--> <!--[if gt IE 8]><!-->\n<html class=\"no-js\"> <!--<![endif]--> <head> <meta charset=\"utf-8\"> <meta\nhttp-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\"> <title>无数据中心：”后\n云“闻见录</title> <meta name=\"description\" content=\"\"> <meta name=\"viewport\"\ncontent=\"width=device-width\"> <link href=\'http://fonts.googleapis.com/css?\nfamily=Open+Sans:400,300,600,700,800&subset=latin,cyrillic-ext\' rel=\n\'stylesheet\' type=\'text/css\'> <link rel=\"stylesheet\" href=\"css/\nnormalize.min.css\"> <link rel=\"stylesheet\" href=\"css/main.css\"> <script src=\"js\n/vendor/modernizr-2.6.2-respond-1.1.0.min.js\"></script> </head> <body> <!--[if\nlt IE 7]> <p class=\"chromeframe\">You are using an <strong>outdated</strong>\nbrowser. Please <a href=\"http://browsehappy.com/\">upgrade your browser</a> or\n<a href=\"http://www.google.com/chromeframe/?redirect=true\">activate Google\nChrome Frame</a> to improve your experience.</p> <![endif]--> <div class=\n\"main-container\"> <div class=\"main wrapper clearfix\"> <article > <h1 class=\n\"page_title\">无数据中心：”后云“闻见录</h1> <p>Version: 001</p> <p>这个闻见录介\n绍了一个最终将会取代云计算的技术。 </p> <p>我是一个软件开发师. 朋友们都叫我”四\n眼哥“。我从1989年开始使用因特网，并从1993年开始使用互联网。我于1981年开发了我的\n第一个商务软件，现在我在上海有一家小的软件公司。</p> <p>现如今因特网已成为商务\n竞争的一个重要工具，云计算通过使商务软件调配自动化来削减成本。但是，现代网络和\n云计算却经历着新的灾难: <a href=\"http://iwgcr.org/\navailability-ranking-of-world-cloud-computing-2012-update/\">缺少弹性力</a>, <a\nhref=\"http://www.europarl.europa.eu/RegData/etudes/etudes/join/1999/168184/\nDG-4-JOIN_ET%281999%29168184_EN.pdf\">缺少交易私密性</a>, <a href=\"http://\nwww.infoworld.com/d/cloud-computing/\nthe-danger-the-coming-big-cloud-monopolies-114\">缺少竞争</a> and <a href=\"http:\n//latimesblogs.latimes.com/technology/2011/04/\ngreenpeace-report-cloud-and-internet-use-sucks-energy-emits-co2.html\">高二氧化\n碳排放量</a>.</p> <p>所有的灾难都来源于一个地方：数据中心。</p> <p>近几年兴起了\n许多尝试修补数据中心灾难的项目。所有的项目都失败了，或者将会失败。</p> <p>数据\n中心产生了无可修复的裂缝因为它们为抵制商务竞争的实际运用制造了一个“没有弹性”的\n诱因，并将最终促成它的短命。<a href=\"XXX\">Richard Stallman是正确的</a> 归根结\n底, 经济还是我们的首要动力。 </p> <p>这个见闻录将从经济方面长远的利益出发，关注\n理论，商务模型及能够引导消除数据中心的技术。感谢HTML5技术及中国开发的低成本移动\n科技, 这个目标将不再是学术人员的一个梦想. </p> <p>非常重要: 如果你开发了或者发\n现了一个可以取代云计算的新技术，请告诉我，我来为你发表。</p> <p>四眼哥<br/>上\n海, 11月19日, 2013<br/> nodatacenter@suomi24.fi </p> <h2>第一章: 分散化理论</\nh2> <p>我们需要知道一个成功的分散式制造系统中哪一项因素是引向成功的关键。目前为\n止，我们可以鉴别出四个要素：智能终端（因特网）, 零边际成本（自由/开源软件）, 零\n知识 (弹性云) 以及零排放（应用商店）。</p> <p><b>智能终端</b>. 将网络智能放置在\n终端的主意促成了 <a href=\"http://en.wikipedia.org/wiki/\nHistory_of_the_Internet\">因特网</a> 弹性。终端比网络本身</i>更需要对<i>可靠的数\n据传送负责。</p> <p><b>零边际成本</b>. 能够使小公司在不需要很多资本的情况下和大\n公司竞争的就是他能够用零边际成本向成千上万的用户输送产品和服务的能力。<a href=\n\"http://en.wikipedia.org/wiki/Open_source\">开源软件</a> 和 <a href=\"http://\nen.wikipedia.org/wiki/Linux\">Linux</a> 是使用零边际成本商务模式在十年内击败大型\n企业的典型案例。</p> <p><b>零知识</b>. 能够使一个电脑系统保护交易秘密的方法就是\n密码术和系统架构的结合，从而可以不保存用户是如何进入交易的。</p> <p><b>零排放</\nb>. 能够消除二氧化碳排放的要么是关掉计算机设备，要么是重复使用所有的热能来给室\n内加热。</p> <p>以下的表格比较了传统云，理想后云以及两种”云代替云“的技术：弹性\n计算和离线HTML5。</p> <p> <table border=\"1\" align=\"center\"> <tr> <th> </th>\n<th>传统云 </th> <th>后云 </th> <th>弹性计算 </th> <th>离线HTML5 </th> </tr>\n<tr> <td>智能终端 </td> <td>不能 </td> <td>能 </td> <td>能 </td> <td>能 </td>\n</tr> <tr> <td>零边际成本 </td> <td>不能 </td> <td>能 </td> <td>可能 </td> <td>\n能 </td> </tr> <tr> <td>零知识 </td> <td>有难度 </td> <td>能 </td> <td>能 </td>\n<td>能 </td> <tr> <td>零排放 </td> <td>不能 </td> <td>能 </td> <td>可能 </td>\n<td>能 </td> </tr> </table> </p> <h2>第二章: 弹性计算</h2> <p>通过分散服务器到\n家庭或办公室，弹性计算解决了云计算缺乏弹性的问题。它使用和云计算相同的技术来处\n理准备金提取，开账单等操作。弹性计算和许多现存的应用都能兼容(Linux, Windows等).\n它的运用对迁移程序或者重新开发没有要求。</p> <p>弹性计算同时也能解决云计算中许\n多其他的问题。但是, 目前还缺乏这个领域足够的支持 (消费者电子设备，电信设备), 零\n边际成本还不能被实现。这目前局限了它在利基市场的运用: 重要任务应用, 政府安全,\n高性能计算。</p> <p>弹性计算需要现代路由技术帮助回避电信公司之间经常发生的由操\n作错误或漏洞引起的连接问题。又被称作可以在网络之上创造一个虚拟网络提供完整的网\n络弹性和有独立服务协议的供应商的 <b>覆盖</b> 网络。</p> <h3>时间轴:</h3> <ul>\n<li>2010 - <a href=\"http://www.cio.com/article/596689/\nViFiB_Wants_You_to_Host_Cloud_Computing_At_Home\">VIFIB</a> 将弹性计算作为云计算\n中一个更安全，更便宜的选择来介绍，并且它还可以给室内加热。VIFIB依赖于<a href=\n\"http://community.slapos.org\">SlapOS</a> 开源技术. VIFIB现在用于实施为<a href=\n\"http://www.cio-online.com/actualites/\nlire-bipetgo-lance-sa-vente-en-ligne-avec-un-module-dedie-dans-le-cloud-5422-page-1.html\">\n法国高速</a>工作的ERP系统的关键使命。 </li> <li>2010 - <a href=\"http://\nwww.qarnot-computing.com/\">Qarnot Computing</a> introduces servers that act as\nelectric heaters for households. Qarnot provides a platform to allocate high\nperformance computing tasks on its servers. </li> <li>2011 - <a href=\"http://\nresearch.microsoft.com/apps/pubs/default.aspx?id=150265\">Microsoft Research</a>\npublishes a research paper by Jie Liu. This paper explains how by placing data\ncenters in buildings, buildings could be heated by the heat of servers. </li>\n<li>2012 - <a href=\"http://git.erp5.org/gitweb/re6stnet.git?js=1\">re6st overaly\nnetwork</a>). re6st provides stable connectivity between servers located in\ndifferent homes, offices or datacenters. IPv6 routing and service level\nagreement (SLA) is handled by a peer-to-peer public mesh of end points. It was\nadopted by <a href=\"http://community.slapos.org\">SlapOS</a>. </li> </ul> <p><i>\nto be completed...</i></p> <h2>Chapter 3: Offline HTML5</h2> <p><a href=\"http:/\n/diveintohtml5.info/offline.html\">Offline HTML5</a> eliminates data centers by\neliminating servers. This approach requires to redevelop all applications in a\nquite different way. Redevelopment effort can be costly even though migration\ntools exist. </p> <p>Offline HTML5 is compatible with Zero Marginal Cost\nbusiness model. This is a huge advantage over Resilient Computing in order to\naccelerate adoption. Considering the growing importance of HTML5 in mobile\ndevice (phones, tablets) and the growing importance of Javascript in enteprise\ncomputing, Offline HTML5 is probably the appropriate approach for the long term\nwhereas resilient computing satisfies short term needs and niche markets (ex.\nbig data).</p> <h3>Timeline:</h3> <ul> <li>2008 - <a href=\"http://\nen.wikipedia.org/wiki/HTML5\">HTML5 first proposal</a> introduces key concepts\nthat will lead to offline apps. </li> <li>2010 - <a href=\"http://\nwww.ung-project.org/project/ungdoc\">UNG is Not Google</a> proves that it is\npossible to develop a clone of Google Docs as a pure client side application\nthat no longer requires an application server. </li> <li>2011 - <a href=\"http:/\n/en.wikipedia.org/wiki/WebRTC\">WebRTC</a> provides the bases for\nbrowser-to-browser networking. </li> <li>2011 - <a href=\"http://bellard.org/\njslinux/\">LinuxJS</a> proves that Javascript is fast enough to emulate a PC.\nThis opens in theory the way to Resilient Computing based on HTML5 that uses\nweb browsers as servers. </li> <li>2011 - <a href=\"http://j-io.org/\">JIO</a>\nprovides an abstraction to access local and remote content in offline HTML5\napps. </li> <li>2013 - <a href=\"\">???</a>. Chrome Web browser is able to act as\na generic server that can listen on a socket. </li> <li>2013 - <a href=\"http://\nozan.io/p/\">P</a> provides a resilient overlay network based on WebRTC. This\nopens in theory the way to Resilient Computing based on HTML5 that WebRTC based\noverlay networks. </li> <li>2013 - <a href=\"http://www.benjamincburns.com/2013/\n11/10/jor1k-ethmac-support.html\">jor1k ethmac</a> network virtualization in\nJavascript opens the possibility to implement IP stack in Javascript and\nincrease network security of HTML5 beyond the limitations of proprietary\noperating systems. </li> <li>2013 - <a href=\"http://www.officejs.com\">OfficeJS\n</a> introduced at Tech Crunch Shanghai is the first platform independent\nappstore of Offline HTML5 apps. </li> </ul> <h2>Chapter 4: Cookbook</h2> <h3>\nRecipe 1: JQM + JIO</h3> <p><i>coming soon</i></p> <h3>Recipe 2: Emscripten</\nh3> <p><i>coming soon</i></p> <h2>References</h2> <ul> <li><a href=\"http://\niwgcr.org/availability-ranking-of-world-cloud-computing-2012-update\">\nAvailability Ranking of World Cloud Computing – June 2013 Update</a></li> <li>\n<a href=\"http://www.huffingtonpost.com/john-glaser/\namerica-as-economic-spy-n_b_4190948.html\">America as Economic Spy: NSA\'s\nMission Is Self-Aggrandizement, Not Fighting Terrorism</a></li> <li><a href=\n\"http://www.europarl.europa.eu/RegData/etudes/etudes/join/1999/168184/\nDG-4-JOIN_ET%281999%29168184_EN.pdf\">DEVELOPMENT OF SURVEILLANCE TECHNOLOGY AND\nRISK OF ABUSE OF ECONOMIC INFORMATION</a></li> <li><a href=\"http://\nwww.infoworld.com/d/cloud-computing/\nthe-danger-the-coming-big-cloud-monopolies-114\">The danger of the coming \'big\ncloud\' monopolies</a></li> <li><a href=\"http://latimesblogs.latimes.com/\ntechnology/2011/04/\ngreenpeace-report-cloud-and-internet-use-sucks-energy-emits-co2.html\">Cloud\ncomputing and Internet use suck energy, emit CO2, says Greenpeace</a></li> <li>\n<a href=\"https://github.com/redecentralize/alternative-internet\">Alternative\nInternet</a></li> <li><a href=\"\"></a></li> <li><a href=\"\"></a></li> <li><a href\n=\"\"></a></li> <li><a href=\"\"></a></li> </ul> <h2>About this page</h2> <p>This\npage is hosted in a private home using a micro-server. Content is brought to\nyou by a proxy cache hosted by <a href=\"http://aliyun.com/\">Aliyun</a> in\nChina.</p> </article> </div> <!-- #main --> </div> </body> </html>'),(15440,'normalize.min.css dev/css/normalize.min.css 001 /*! normalize.css v1.1.2 | MIT License | git.io/normalize */article,aside,details,figcaption,figure,footer,header,hgroup,main,nav,section,summary{display:block}audio,canvas,video{display:inline-block;*display:inline;*zoom:1}audio:not([controls]){display:none;height:0}[hidden]{display:none}html{font-size:100%;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%}html,button,input,select,textarea{font-family:sans-serif}body{margin:0}a:focus{outline:thin dotted}a:active,a:hover{outline:0}h1{font-size:2em;margin:.67em 0}h2{font-size:1.5em;margin:.83em 0}h3{font-size:1.17em;margin:1em 0}h4{font-size:1em;margin:1.33em 0}h5{font-size:.83em;margin:1.67em 0}h6{font-size:.67em;margin:2.33em 0}abbr[title]{border-bottom:1px dotted}b,strong{font-weight:bold}blockquote{margin:1em 40px}dfn{font-style:italic}hr{-moz-box-sizing:content-box;box-sizing:content-box;height:0}mark{background:#ff0;color:#000}p,pre{margin:1em 0}code,kbd,pre,samp{font-family:monospace,serif;_font-family:\'courier new\',monospace;font-size:1em}pre{white-space:pre;white-space:pre-wrap;word-wrap:break-word}q{quotes:none}q:before,q:after{content:\'\';content:none}small{font-size:80%}sub,sup{font-size:75%;line-height:0;position:relative;vertical-align:baseline}sup{top:-0.5em}sub{bottom:-0.25em}dl,menu,ol,ul{margin:1em 0}dd{margin:0 0 0 40px}menu,ol,ul{padding:0 0 0 40px}nav ul,nav ol{list-style:none;list-style-image:none}img{border:0;-ms-interpolation-mode:bicubic}svg:not(:root){overflow:hidden}figure{margin:0}form{margin:0}fieldset{border:1px solid silver;margin:0 2px;padding:.35em .625em .75em}legend{border:0;padding:0;white-space:normal;*margin-left:-7px}button,input,select,textarea{font-size:100%;margin:0;vertical-align:baseline;*vertical-align:middle}button,input{line-height:normal}button,select{text-transform:none}button,html input[type=\"button\"],input[type=\"reset\"],input[type=\"submit\"]{-webkit-appearance:button;cursor:pointer;*overflow:visible}button[disabled],html input[disabled]{cursor:default}input[type=\"checkbox\"],input[type=\"radio\"]{box-sizing:border-box;padding:0;*height:13px;*width:13px}input[type=\"search\"]{-webkit-appearance:textfield;-moz-box-sizing:content-box;-webkit-box-sizing:content-box;box-sizing:content-box}input[type=\"search\"]::-webkit-search-cancel-button,input[type=\"search\"]::-webkit-search-decoration{-webkit-appearance:none}button::-moz-focus-inner,input::-moz-focus-inner{border:0;padding:0}textarea{overflow:auto;vertical-align:top}table{border-collapse:collapse;border-spacing:0}'),(15441,'normalize.css dev/css/normalize.css 001 /*! normalize.css v1.1.2 | MIT License | git.io/normalize */\n\n/* ==========================================================================\n   HTML5 display definitions\n   ========================================================================== */\n\n/**\n * Correct `block` display not defined in IE 6/7/8/9 and Firefox 3.\n */\n\narticle,\naside,\ndetails,\nfigcaption,\nfigure,\nfooter,\nheader,\nhgroup,\nmain,\nnav,\nsection,\nsummary {\n    display: block;\n}\n\n/**\n * Correct `inline-block` display not defined in IE 6/7/8/9 and Firefox 3.\n */\n\naudio,\ncanvas,\nvideo {\n    display: inline-block;\n    *display: inline;\n    *zoom: 1;\n}\n\n/**\n * Prevent modern browsers from displaying `audio` without controls.\n * Remove excess height in iOS 5 devices.\n */\n\naudio:not([controls]) {\n    display: none;\n    height: 0;\n}\n\n/**\n * Address styling not present in IE 7/8/9, Firefox 3, and Safari 4.\n * Known issue: no IE 6 support.\n */\n\n[hidden] {\n    display: none;\n}\n\n/* ==========================================================================\n   Base\n   ========================================================================== */\n\n/**\n * 1. Correct text resizing oddly in IE 6/7 when body `font-size` is set using\n *    `em` units.\n * 2. Prevent iOS text size adjust after orientation change, without disabling\n *    user zoom.\n */\n\nhtml {\n    font-size: 100%; /* 1 */\n    -ms-text-size-adjust: 100%; /* 2 */\n    -webkit-text-size-adjust: 100%; /* 2 */\n}\n\n/**\n * Address `font-family` inconsistency between `textarea` and other form\n * elements.\n */\n\nhtml,\nbutton,\ninput,\nselect,\ntextarea {\n    font-family: sans-serif;\n}\n\n/**\n * Address margins handled incorrectly in IE 6/7.\n */\n\nbody {\n    margin: 0;\n}\n\n/* ==========================================================================\n   Links\n   ========================================================================== */\n\n/**\n * Address `outline` inconsistency between Chrome and other browsers.\n */\n\na:focus {\n    outline: thin dotted;\n}\n\n/**\n * Improve readability when focused and also mouse hovered in all browsers.\n */\n\na:active,\na:hover {\n    outline: 0;\n}\n\n/* ==========================================================================\n   Typography\n   ========================================================================== */\n\n/**\n * Address font sizes and margins set differently in IE 6/7.\n * Address font sizes within `section` and `article` in Firefox 4+, Safari 5,\n * and Chrome.\n */\n\nh1 {\n    font-size: 2em;\n    margin: 0.67em 0;\n}\n\nh2 {\n    font-size: 1.5em;\n    margin: 0.83em 0;\n}\n\nh3 {\n    font-size: 1.17em;\n    margin: 1em 0;\n}\n\nh4 {\n    font-size: 1em;\n    margin: 1.33em 0;\n}\n\nh5 {\n    font-size: 0.83em;\n    margin: 1.67em 0;\n}\n\nh6 {\n    font-size: 0.67em;\n    margin: 2.33em 0;\n}\n\n/**\n * Address styling not present in IE 7/8/9, Safari 5, and Chrome.\n */\n\nabbr[title] {\n    border-bottom: 1px dotted;\n}\n\n/**\n * Address style set to `bolder` in Firefox 3+, Safari 4/5, and Chrome.\n */\n\nb,\nstrong {\n    font-weight: bold;\n}\n\nblockquote {\n    margin: 1em 40px;\n}\n\n/**\n * Address styling not present in Safari 5 and Chrome.\n */\n\ndfn {\n    font-style: italic;\n}\n\n/**\n * Address differences between Firefox and other browsers.\n * Known issue: no IE 6/7 normalization.\n */\n\nhr {\n    -moz-box-sizing: content-box;\n    box-sizing: content-box;\n    height: 0;\n}\n\n/**\n * Address styling not present in IE 6/7/8/9.\n */\n\nmark {\n    background: #ff0;\n    color: #000;\n}\n\n/**\n * Address margins set differently in IE 6/7.\n */\n\np,\npre {\n    margin: 1em 0;\n}\n\n/**\n * Correct font family set oddly in IE 6, Safari 4/5, and Chrome.\n */\n\ncode,\nkbd,\npre,\nsamp {\n    font-family: monospace, serif;\n    _font-family: \'courier new\', monospace;\n    font-size: 1em;\n}\n\n/**\n * Improve readability of pre-formatted text in all browsers.\n */\n\npre {\n    white-space: pre;\n    white-space: pre-wrap;\n    word-wrap: break-word;\n}\n\n/**\n * Address CSS quotes not supported in IE 6/7.\n */\n\nq {\n    quotes: none;\n}\n\n/**\n * Address `quotes` property not supported in Safari 4.\n */\n\nq:before,\nq:after {\n    content: \'\';\n    content: none;\n}\n\n/**\n * Address inconsistent and variable font size in all browsers.\n */\n\nsmall {\n    font-size: 80%;\n}\n\n/**\n * Prevent `sub` and `sup` affecting `line-height` in all browsers.\n */\n\nsub,\nsup {\n    font-size: 75%;\n    line-height: 0;\n    position: relative;\n    vertical-align: baseline;\n}\n\nsup {\n    top: -0.5em;\n}\n\nsub {\n    bottom: -0.25em;\n}\n\n/* ==========================================================================\n   Lists\n   ========================================================================== */\n\n/**\n * Address margins set differently in IE 6/7.\n */\n\ndl,\nmenu,\nol,\nul {\n    margin: 1em 0;\n}\n\ndd {\n    margin: 0 0 0 40px;\n}\n\n/**\n * Address paddings set differently in IE 6/7.\n */\n\nmenu,\nol,\nul {\n    padding: 0 0 0 40px;\n}\n\n/**\n * Correct list images handled incorrectly in IE 7.\n */\n\nnav ul,\nnav ol {\n    list-style: none;\n    list-style-image: none;\n}\n\n/* ==========================================================================\n   Embedded content\n   ========================================================================== */\n\n/**\n * 1. Remove border when inside `a` element in IE 6/7/8/9 and Firefox 3.\n * 2. Improve image quality when scaled in IE 7.\n */\n\nimg {\n    border: 0; /* 1 */\n    -ms-interpolation-mode: bicubic; /* 2 */\n}\n\n/**\n * Correct overflow displayed oddly in IE 9.\n */\n\nsvg:not(:root) {\n    overflow: hidden;\n}\n\n/* ==========================================================================\n   Figures\n   ========================================================================== */\n\n/**\n * Address margin not present in IE 6/7/8/9, Safari 5, and Opera 11.\n */\n\nfigure {\n    margin: 0;\n}\n\n/* ==========================================================================\n   Forms\n   ========================================================================== */\n\n/**\n * Correct margin displayed oddly in IE 6/7.\n */\n\nform {\n    margin: 0;\n}\n\n/**\n * Define consistent border, margin, and padding.\n */\n\nfieldset {\n    border: 1px solid #c0c0c0;\n    margin: 0 2px;\n    padding: 0.35em 0.625em 0.75em;\n}\n\n/**\n * 1. Correct color not being inherited in IE 6/7/8/9.\n * 2. Correct text not wrapping in Firefox 3.\n * 3. Correct alignment displayed oddly in IE 6/7.\n */\n\nlegend {\n    border: 0; /* 1 */\n    padding: 0;\n    white-space: normal; /* 2 */\n    *margin-left: -7px; /* 3 */\n}\n\n/**\n * 1. Correct font size not being inherited in all browsers.\n * 2. Address margins set differently in IE 6/7, Firefox 3+, Safari 5,\n *    and Chrome.\n * 3. Improve appearance and consistency in all browsers.\n */\n\nbutton,\ninput,\nselect,\ntextarea {\n    font-size: 100%; /* 1 */\n    margin: 0; /* 2 */\n    vertical-align: baseline; /* 3 */\n    *vertical-align: middle; /* 3 */\n}\n\n/**\n * Address Firefox 3+ setting `line-height` on `input` using `!important` in\n * the UA stylesheet.\n */\n\nbutton,\ninput {\n    line-height: normal;\n}\n\n/**\n * Address inconsistent `text-transform` inheritance for `button` and `select`.\n * All other form control elements do not inherit `text-transform` values.\n * Correct `button` style inheritance in Chrome, Safari 5+, and IE 6+.\n * Correct `select` style inheritance in Firefox 4+ and Opera.\n */\n\nbutton,\nselect {\n    text-transform: none;\n}\n\n/**\n * 1. Avoid the WebKit bug in Android 4.0.* where (2) destroys native `audio`\n *    and `video` controls.\n * 2. Correct inability to style clickable `input` types in iOS.\n * 3. Improve usability and consistency of cursor style between image-type\n *    `input` and others.\n * 4. Remove inner spacing in IE 7 without affecting normal text inputs.\n *    Known issue: inner spacing remains in IE 6.\n */\n\nbutton,\nhtml input[type=\"button\"], /* 1 */\ninput[type=\"reset\"],\ninput[type=\"submit\"] {\n    -webkit-appearance: button; /* 2 */\n    cursor: pointer; /* 3 */\n    *overflow: visible;  /* 4 */\n}\n\n/**\n * Re-set default cursor for disabled elements.\n */\n\nbutton[disabled],\nhtml input[disabled] {\n    cursor: default;\n}\n\n/**\n * 1. Address box sizing set to content-box in IE 8/9.\n * 2. Remove excess padding in IE 8/9.\n * 3. Remove excess padding in IE 7.\n *    Known issue: excess padding remains in IE 6.\n */\n\ninput[type=\"checkbox\"],\ninput[type=\"radio\"] {\n    box-sizing: border-box; /* 1 */\n    padding: 0; /* 2 */\n    *height: 13px; /* 3 */\n    *width: 13px; /* 3 */\n}\n\n/**\n * 1. Address `appearance` set to `searchfield` in Safari 5 and Chrome.\n * 2. Address `box-sizing` set to `border-box` in Safari 5 and Chrome\n *    (include `-moz` to future-proof).\n */\n\ninput[type=\"search\"] {\n    -webkit-appearance: textfield; /* 1 */\n    -moz-box-sizing: content-box;\n    -webkit-box-sizing: content-box; /* 2 */\n    box-sizing: content-box;\n}\n\n/**\n * Remove inner padding and search cancel button in Safari 5 and Chrome\n * on OS X.\n */\n\ninput[type=\"search\"]::-webkit-search-cancel-button,\ninput[type=\"search\"]::-webkit-search-decoration {\n    -webkit-appearance: none;\n}\n\n/**\n * Remove inner padding and border in Firefox 3+.\n */\n\nbutton::-moz-focus-inner,\ninput::-moz-focus-inner {\n    border: 0;\n    padding: 0;\n}\n\n/**\n * 1. Remove default vertical scrollbar in IE 6/7/8/9.\n * 2. Improve readability and alignment in all browsers.\n */\n\ntextarea {\n    overflow: auto; /* 1 */\n    vertical-align: top; /* 2 */\n}\n\n/* ==========================================================================\n   Tables\n   ========================================================================== */\n\n/**\n * Remove most spacing between table cells.\n */\n\ntable {\n    border-collapse: collapse;\n    border-spacing: 0;\n}'),(15442,'main.css dev/css/main.css 001 /* ==========================================================================\n   HTML5 Boilerplate styles\n   ========================================================================== */\n\nhtml,\nbutton,\ninput,\nselect,\ntextarea {\n    color: rgb(107,139,155);\n}\n\nbody {\n    font-size: 1em;\n    line-height: 1.4;\n}\n\n::-moz-selection {\n    background: #b3d4fc;\n    text-shadow: none;\n}\n\n::selection {\n    background: #b3d4fc;\n    text-shadow: none;\n}\n\nhr {\n    display: block;\n    height: 1px;\n    border: 0;\n    border-top: 1px solid #ccc;\n    margin: 1em 0;\n    padding: 0;\n}\n\nimg {\n    vertical-align: middle;\n}\n\nfieldset {\n    border: 0;\n    margin: 0;\n    padding: 0;\n}\n\ntextarea {\n    resize: vertical;\n}\n\n.chromeframe {\n    margin: 0.2em 0;\n    background: #ccc;\n    color: #000;\n    padding: 0.2em 0;\n}\n\nbody {\n    font: 18px/26px \'Open Sans\', Helvetica, Helvetica Neue, Arial;\n}\n\n.wrapper {\n    width: 90%;\n    margin: 0 5%;\n}\n\n.header-container {\n\n}\n\n.footer-container,\n.main aside {\n\n}\n\n.header-container,\n.footer-container,\n.main aside {\n\n}\n\n.title {\n\n}\n\n/* ==============\n    MOBILE: Menu\n   ============== */\n\nnav {\n  clear: both;\n	margin-top: 22px;\n}\n\nnav ul {\n    margin: 0;\n    padding: 0;\n}\n\nnav ul li {\n\n}\n\nnav a {\n    display: block;\n    margin-bottom: 10px;\n    padding: 2px;\n    \n    text-align: left;\n    text-transform: uppercase;\n    text-decoration: none;\n    letter-spacing: 0.15em;\n    font-size: 18px;\n    line-height: 18px;\n\n    color: white;\n    background: none;\n    \n    border: 1px solid rgb(175,199,211);\n}\n\nnav a span {\n	display: inline-block;\n	width: 100%;\n	height: 100%;\n	background: rgb(107,139,155) url(../img/butn-arrow.png) no-repeat right center;\n	padding: 8px 0;\n	text-indent: 20px;\n	transition: all 300ms ease-in-out;\n		-moz-transition: all 300ms ease-in-out;\n			-webkit-transition: all 300ms ease-in-out;\n				-o-transition: all 300ms ease-in-out;\n}\n\nnav a:hover,\nnav a:visited {\n    color: white;\n}\n\nnav a:hover {\n    text-decoration: none;\n}\n\nnav a:hover span {\n	background-color: rgb(62,102,122);\n	transition: all 200ms ease-in-out;\n		-moz-transition: all 200ms ease-in-out;\n			-webkit-transition: all 200ms ease-in-out;\n				-o-transition: all 200ms ease-in-out;\n}\n\n/* ==============\n    MOBILE: Main\n   ============== */\n\n.main {\n    padding: 0px 0;\n}\n\n.main .clear {\n	width: 100%;\n	height: 15px;\n	clear: both;\n}\n\n/* ==============\n    MOBILE: Offers\n   ============== */\n\n.main .offer {\n	background: rgb(234,246,246);\n}\n\n.main .offer ul {\n	margin: 0;\n	padding: 31px 0 0 0;\n	list-style-type: none;\n	text-align: center;\n}\n\n.main .offer ul li {\n	display: inline;\n	width: 278px;\n	padding: 0;\n	margin: 0;\n}\n\n.main .offer ul li .theoffer {\n	display: inline-block;\n	width: 277px;\n	color: #fff;\n	margin: 0 auto 45px auto;\n	text-decoration: none;\n}\n\n.main .offer ul li .theoffer span {\n	display: block;\n}\n\n.main .offer .top {\n	background: rgb(107,139,155);\n	-webkit-box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n        -moz-box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n            box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n}\n\n.main .offer .butn {\n	margin-top: 1px;\n}\n\n.main .offer .butn a {\n	display: inline-block;\n	width: 100%;\n	height: 36px;\n	line-height: 34px;\n	background: rgb(46,168,168);\n	text-decoration: none;\n	text-transform: uppercase;\n	letter-spacing: 0.1em;\n	color: #fff;\n	-webkit-box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n        -moz-box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n            box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n}\n\n.main .offer .butn a:nth-of-type(1) {\n	margin-right: 1px;\n}\n\n.main .offer .butn a:hover {\n	background: rgb(20,144,144);\n}\n\n.main .offer .conditions {\n	width: 100%;\n	margin-top: 1px;\n	background: rgb(119,158,177);\n	-webkit-box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n        -moz-box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n            box-shadow: inset 0 0px 70px rgba(0,0,0,0.1);\n}\n\n.main .offer .system,\n.main .offer .terms {\n	font-size: 0.9em;\n	text-transform: uppercase;\n	padding: 17px 0;\n}\n\n.main .offer .offername {\n	font-size: 3.7em;\n	font-weight: 700;\n	padding: 12px 0 14px 0;\n}\n\n.main .offer .conditions h3 {\n	padding: 12px 0 8px 0;\n	margin: 0;\n	font-size: 1.6em;\n	font-weight: 600;\n	text-transform: uppercase;\n}\n\n.main .offer .desc {\n	padding: 0 0 10px 0;\n	font-size: 0.9em;\n}\n\n/* =========================\n    MOBILE: Content Article\n   ========================= */\n\n.main article {\n 	margin: 37px 0;\n    padding: 0;\n}\n\n.main article h1 {\n    font-size: 1.5em;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.07em;\n    line-height: 1.45em;\n    margin: 0 0 20px 0;\n}\n\n.main article h1.page_title {\n    font-size: 2em;\n    color: rgb(45,163,163);\n    line-height: 1.45em;\n}\n\n.main article h2 {\n    font-size: 1.2em;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n    line-height: 1.45em;\n    margin: 0 0 20px 0;\n}\n\n.main article p {\n 	margin: 0;\n    padding: 0 0 36px 0;\n    line-height: 1.7em;\n}\n\n.main article p img {\n	float: left;\n	margin: 9px 24px 9px 0;\n}\n\n.main article h1,\n.main article h2,\n.main article h3,\n.main article h4,\n.main article p,\n.main article pre {\n	padding-left: 10px;\n	padding-right: 10px;\n}\n\n.main article hr {\n	border-top: 1px solid rgb(204,215,220);\n	margin: 5px 0 0 0;\n	height: 40px;\n}\n\n.main article pre {\n	text-align: left;\n	white-space: pre-line;\n	word-wrap: break-word;\n	padding-top: 10px;\n	padding-bottom: 36px;\n}\n\n.main article pre code {\n	display: block;\n	padding: 20px;\n	background: rgb(234,246,246);\n}\n\n.footer-container footer {\n    padding: 5px 0;\n    margin-bottom: 56px;\n    border-top: 1px solid rgb(190,229,229);\n   	border-bottom: 1px solid rgb(190,229,229);\n   	font-size: 0.9em;\n}\n\n.footer-container footer .footerin {\n	width: 100%;\n	padding: 0 0 15px 0;\n	background: rgb(246,247,248);\n}\n\nfooter .list {\n	display: inline;\n	float: left;\n	width: 100%;\n	text-align: center;\n	margin-bottom: 12px;\n}\n\nfooter ul {\n	margin: 0;\n	padding: 0;\n	list-style-type: none;\n	line-height: 1.8em;\n}\n\nfooter ul a {\n	text-decoration: none;\n	color: rgb(107,139,155);\n}\n\nfooter h4 {\n	padding: 20px 0 4px 0;\n	font-size: 1.1em;\n	text-transform: uppercase;\n	letter-spacing: 0.1em;\n	font-weight: 600;\n	margin: 0;\n}\n\nfooter .clear {\n	width: 100%;\n	height: 15px;\n	clear: both;\n}\n\n/* ===============\n    ALL: IE Fixes\n   =============== */\n\n.ie7 .title {\n    padding-top: 20px;\n}\n\n/* ==========================================================================\n   Author\'s custom styles\n   ========================================================================== */\n\n.header-container {\n	margin-top: 38px;\n	margin-bottom: 33px;\n}\n\n.title.logo {\n    display: block;\n    \n    height: 117px;\n    background: url(../img/vifib-logo.png) no-repeat 0 0;\n    margin: 0;\n}\n\n.title.logo a {\n	display: block;\n    width: 100px;\n    height: 117px;\n	float: left;\n	text-indent: -999px;\n}\n\nspan.claim {\n	display: block;\n	overflow: hidden;\n	height: 19px;\n	width: 180px;\n	text-align: right;\n	padding: 0;\n	margin-right: 4px;\n	float: right;\n	font-size: 17px;\n	text-transform: uppercase;\n	line-height: 1em;\n	font-weight: 100;\n	letter-spacing: 0.27em;\n	background: url(../img/claim.png) no-repeat right 2px;\n	background-size: 180px auto;\n	position: relative;\n	top: 106px;\n	text-indent: 999px;\n}\n\n.headteaser {\n	border-top: 1px solid rgb(190,229,229);\n	border-bottom: 1px solid rgb(190,229,229);\n	padding: 5px 0;\n}\n\n.headteaser .teaserin {\n	padding: 32px 20px;\n	background: rgb(46,168,168);\n	text-align: center;\n	color: #fff;\n	font-size: 28px;\n	line-height: 36px;\n	-webkit-box-shadow: inset 0 0px 70px rgba(0,0,0,0.15);\n           -moz-box-shadow: inset 0 0px 70px rgba(0,0,0,0.15);\n                box-shadow: inset 0 0px 70px rgba(0,0,0,0.15);\n}\n\n.breadcrumb {\n	border-bottom: 1px solid rgb(190,229,229);\n	padding: 2px 0;\n}\n\n.breadcrumb ul {\n	margin: 0;\n	padding: 0;\n	list-style-type: none;\n	background: rgb(246,247,248);\n	padding: 4px 12px;\n}\n\n.breadcrumb ul li {\n	margin: 0;\n	padding: 0;\n	font-size: 15px;\n	color: rgb(107,139,155);\n}\n\n.breadcrumb ul li a {\n	margin: 0;\n	padding: 0;\n	float: left;\n	padding-right: 14px;\n	margin-right: 7px;\n	text-decoration: none;\n	color: rgb(45,163,163);\n	background: url(../img/breadmarker.png) no-repeat right 10px;\n	transition: all 300ms ease-in-out;\n		-moz-transition: all 300ms ease-in-out;\n			-webkit-transition: all 300ms ease-in-out;\n				-o-transition: all 300ms ease-in-out;\n}\n\n.breadcrumb ul li a:hover {\n	color: rgb(62,102,122);\n	transition: all 200ms ease-in-out;\n		-moz-transition: all 200ms ease-in-out;\n			-webkit-transition: all 200ms ease-in-out;\n				-o-transition: all 200ms ease-in-out;\n}\n\na {\n	color: rgb(45,163,163);\n	transition: all 300ms ease-in-out;\n		-moz-transition: all 300ms ease-in-out;\n			-webkit-transition: all 300ms ease-in-out;\n				-o-transition: all 300ms ease-in-out;\n}\n\na:visited {\n	color: rgb(107,139,155);\n}\n\na:hover {\n	color: rgb(62,102,122);\n	transition: all 200ms ease-in-out;\n		-moz-transition: all 200ms ease-in-out;\n			-webkit-transition: all 200ms ease-in-out;\n				-o-transition: all 200ms ease-in-out;\n}\n\n\n/* ==========================================================================\n   Media Queries\n   ========================================================================== */\n\n@media only screen and (min-width: 480px) {\n\n/* ====================\n    INTERMEDIATE: Menu\n   ==================== */\n   \n	.title.logo {\n    	width: 100%;\n    }\n   \n	span.claim {\n		width: 250px;\n		text-align: right;\n		padding: 0 0 0 50px;\n		float: none;\n		background-size: auto auto;\n		top: 102px;\n	}\n	\n	nav {\n		clear: both;\n		margin-top: 22px;\n	}\n   \n    nav a {\n        margin-bottom: 0;\n    }\n\n    nav li:first-child a {\n        margin-left: 0;\n    }\n\n    nav li:last-child a {\n        margin-right: 0;\n    }\n    \n    footer .list {\n		margin: 0 5%;\n	}\n	\n	.main .offer ul li .theoffer {\n		margin: 0 30px 45px 30px;\n	}\n	\n	.footer-container footer {\n  	 	font-size: 0.7em;\n	}\n	\n	footer .list {\n		display: inline;\n		float: left;\n		width: auto;\n		margin: 0 5%;\n		text-align: left;\n	}\n\n	footer .list.a,\n	footer .list.c {\n		width: 100px;\n	}\n\n\n    \n\n/* ========================\n    INTERMEDIATE: IE Fixes\n   ======================== */\n\n    nav ul li {\n        display: inline;\n    }\n\n    .oldie nav a {\n        margin: 0 0.7%;\n    }\n}\n\n@media only screen and (min-width: 768px) {\n\n/* ============\n    WIDE: Menu\n   ============ */\n\n    .title {\n        float: left;\n    }\n\n    nav {\n        float: right;\n        width: 140px;\n    }\n\n/* ============\n    WIDE: Main\n   ============ */\n\n	.title.logo {\n    	width: 70%;\n    }\n    \n    nav {\n		clear: none;\n		margin-top: 89px;\n	}\n\n}\n\n@media only screen and (min-width: 1140px) {\n\n/* ===============\n    Maximal Width\n   =============== */\n\n    .wrapper {\n        width: 960px; /* 1140px - 10% for margins */\n        margin: 0 auto;\n    }\n	\n}\n\n/* ==========================================================================\n   Helper classes\n   ========================================================================== */\n\n.ir {\n    background-color: transparent;\n    border: 0;\n    overflow: hidden;\n    *text-indent: -9999px;\n}\n\n.ir:before {\n    content: \"\";\n    display: block;\n    width: 0;\n    height: 150%;\n}\n\n.hidden {\n    display: none !important;\n    visibility: hidden;\n}\n\n.visuallyhidden {\n    border: 0;\n    clip: rect(0 0 0 0);\n    height: 1px;\n    margin: -1px;\n    overflow: hidden;\n    padding: 0;\n    position: absolute;\n    width: 1px;\n}\n\n.visuallyhidden.focusable:active,\n.visuallyhidden.focusable:focus {\n    clip: auto;\n    height: auto;\n    margin: 0;\n    overflow: visible;\n    position: static;\n    width: auto;\n}\n\n.invisible {\n    visibility: hidden;\n}\n\n.clearfix:before,\n.clearfix:after {\n    content: \" \";\n    display: table;\n}\n\n.clearfix:after {\n    clear: both;\n}\n\n.clearfix {\n    *zoom: 1;\n}\n\n/* ==========================================================================\n   Print styles\n   ========================================================================== */\n\n@media print {\n    * {\n        background: transparent !important;\n        color: #000 !important; /* Black prints faster: h5bp.com/s */\n        box-shadow: none !important;\n        text-shadow: none !important;\n    }\n\n    a,\n    a:visited {\n        text-decoration: underline;\n    }\n\n    a[href]:after {\n        content: \" (\" attr(href) \")\";\n    }\n\n    abbr[title]:after {\n        content: \" (\" attr(title) \")\";\n    }\n\n    /*\n     * Don\'t show links for images, or javascript/internal links\n     */\n\n    .ir a:after,\n    a[href^=\"javascript:\"]:after,\n    a[href^=\"#\"]:after {\n        content: \"\";\n    }\n\n    pre,\n    blockquote {\n        border: 1px solid #999;\n        page-break-inside: avoid;\n    }\n\n    thead {\n        display: table-header-group; /* h5bp.com/t */\n    }\n\n    tr,\n    img {\n        page-break-inside: avoid;\n    }\n\n    img {\n        max-width: 100% !important;\n    }\n\n    @page {\n        margin: 0.5cm;\n    }\n\n    p,\n    h2,\n    h3 {\n        orphans: 3;\n        widows: 3;\n    }\n\n    h2,\n    h3 {\n        page-break-after: avoid;\n    }\n}'),(15443,'themes.css css/themes.css 001 /* GLOBALS */\n/* Font: */\n/* colors: consider #353535 */\n  /* BASE */\nbody, input, select, textarea, button, p, legend, html.ui-mobile label, .ui-btn, .ui-li-static {\n  font-family: Helvetica, Arial, sans-serif;\n  font-size: 95%;\n}\nbody .ui-controlgroup-label legend {\n  font-size: 82.5%;\n}\n@media (max-width: 40em) {\n  body, input, select, textarea, button, p, legend, html.ui-mobile label, .ui-btn, body .ui-controlgroup-label legend {\n    font-size: 92.5%;\n  }\n}\n/* Modified on BASE */\nhtml .listview .ui-li-divider {\n  font-size: 80%;\n}\n\n/* Watermark NOTE: breaks links if ui-content is kept position:static \n.ui-page-active:before,\n.ui-page-active .ui-panel-wrapper:before {\n  background: url(\"../img/slapos.png\") no-repeat center center;\n  background-attachment: fixed;\n  content: \"\"