 232, 0.5);\n}\n/* form & fieldcontain */\n/* set label/input width on large screens */\n/* TODO: form fields should auto-expand to full width */\n@media (min-width: 40em) {\n  .ui-fieldcontain label:not(.ui-btn),\n  .ui-fieldcontain div.ui-input-text,\n  .ui-fieldcontain div.ui-input-search,\n  .ui-fieldcontain div.ui-select {\n    display: inline-block;\n    vertical-align: middle;\n  }\n  .ui-fieldcontain label:not(.ui-btn) {\n    width: 46% /*40%*/;\n  }\n  .ui-fieldcontain div.ui-input-text,\n  .ui-fieldcontain div.ui-input-search {\n    width: 50%;\n  }\n  .ui-fieldcontain div.ui-select {\n    width: 56%;\n  }\n  .ui-fieldcontain div.ui-select .ui-btn {\n    -webkit-box-shadow: none;\n    -moz-box-shadow: none;\n    box-shadow: none;\n    min-height: 19px;\n    padding-top: 5px;\n    padding-bottom: 5px;\n  }\n  .ui-fieldcontain div.ui-select .ui-btn.ui-btn-icon-right:after {\n    right: 0.25em;\n  }\n}\n\n/* ============================= forms ============================= */\n/*\nform {\n  font-size: .85em;\n}\nform p {\n  font-size: 1em;\n}\n@media (max-width: 40em) {\n  form {\n    font-size: 1em;\n  }\n}\n*/\n/* ============================= content grid ============================= */\n.span_1, .span_2 {\n  display: inline-block;\n  vertical-align: middle;\n  width: 45%;\n  padding-left: 2%;\n  padding-right: 2%;\n  /* ~ 98% for 2 col layout */\n  padding-top: 2%;\n}\n.span_1 textarea {\n  width: 56%;\n  display: inline-block;\n  vertical-align: middle;\n}\n.span_2 {\n  width: 96% /* 2% padding-left/right */\n}\n/* is this padding really necessary? */\n.span_1 .ui-controlgroup-vertical,\n.span_2 .ui-controlgroup-vertical,\n.span_1 .ui-controlgroup-horizontal,\n.span_2 .ui-controlgroup-horizontal,\n.span_1 form,\n.span_2 form {\n  margin-top: 1em;\n  margin-bottom: 1em;\n  vertical-align: middle;\n}\n@media (max-width: 40em) {\n  .span_1, .span_2 {\n    width: 100%;\n    padding: 0;\n  }\n  .span_1 textarea {\n    width: 100%;\n  }\n}\n.span_1 .ui-input-search,\n.span_2 .ui-input-search {\n  width: 50%;\n}\n.span_1 .ui-table-wrapper .ui-input-search,\n.span_2 .ui-table-wrapper .ui-input-search{\n  width: auto;\n  margin: 0;\n  box-shadow: none;\n  -webkit-box-shadow: none;\n  border-width: 0;\n  border-bottom-width: 1px;\n}\n@media (max-width: 45em) {\n  .span_1 .ui-input-search,\n  .span_2 .ui-input-search {\n    width: 100%;\n  }\n}\n@media (min-width: 45em) {\n  .span_1 .ui-input-search,\n  .span_2 .ui-input-search {\n    width: 60%;\n  }\n}\n/* ============================= content elements ============================= */\n/* TODO: merge with span_1 span_2... */\nhtml div.ui-page div.ui-content .ui-content-element {\n  /* TODO: should have corners and shadow - but not like this!*/\n  /*\n  -webkit-box-shadow: 0 1px 3px rgba(0,0,0,.15);\n  -moz-box-shadow: 0 1px 3px rgba(0,0,0,.15);\n  box-shadow: 0 1px 3px rgba(0,0,0,.15);\n  */\n  -webkit-border-radius:  .3125em;\n  border-radius: .3125em;\n  border: 1px solid #aaa;\n  padding: 1em;\n  margin: 1em auto;\n  text-align: center;\n}\nhtml div.ui-page div.ui-content .ui-content-element > .ui-btn {\n  max-width: 10%;\n  margin: 1em auto 0;\n  display: block;\n}\n\n\n.panel .ui-panel-inner .panel_element {\n  margin-left: -1em;\n  margin-right: -1em;\n}\n.panel .ui-panel-inner .panel_element.panel_element_first {\n  margin-top: -1em;\n}\n.panel .ui-panel-inner .panel_element.panel_element_last {\n  margin-bottom: -1em;\n}\n.panel .panel_element.panel_header {\n  border-width: 0;\n  padding-top: 1px;\n  top: -1px;\n}\n\n/* navbar */\n.navbar ul li a.ui-btn-active.clone_item span.navbar_clone {\n  font-weight: bold;\n}\n/* controlgroup */\n.ui-header .ui-controlgroup,\n.ui-header .ui-controlgroup fieldset.ui-controlgroup,\n/* controlgroup header outside of page */\n.ui-controlgroup,\n.ui-controlgroup fieldset.ui-controlgroup{\n  padding: 0;\n  margin: 0;\n  height: 100%;\n}\n.ui-header .ui-controlgroup-controls {\n  height: 100%;\n}\n/* single button controlgroup */\n.ui-controlgroup.ui-corner-all .ui-controlgroup-controls .ui-btn.ui-first-child.ui-last-child {\n  border-radius: inherit;\n}\n/* button  */\n.ui-header a.ui-btn ,\nhtml .ui-header a.ui-btn ,\nhtml body .ui-header a.ui-btn,\nhtml body .ui-header .ui-controlgroup .ui-controlgroup-controls div.ui-select .ui-btn{\n  height: 100%;\n  margin: 0;\n  position: relative; /* otherwise multiple buttons break */\n  padding-top: 0;\n  padding-bottom: 0;\n  border-radius: 0;\n  -webkit-border-radius: 0;\n}\nhtml .ui-btn, label.ui-btn {\n  font-weight: normal;\n}\n\n/* no bold buttons */\nhtml .ui-btn, label.ui-btn {\n  font-weight: normal;\n}\n/* fix svg icon positioning */\n.ui-btn-icon-notext:after,\n.ui-btn-icon-left:after,\n.ui-btn-icon-right:after,\n.ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after {\n  margin-top: -15px;\n}\n/* reset fix */\n.ui-nosvg .ui-btn-icon-notext:after,\n.ui-nosvg .ui-btn-icon-left:after,\n.ui-nosvg .ui-btn-icon-right:after,\n.ui-nosvg .ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after,\n.ui-input-clear.ui-btn-icon-notext:after {\n  margin-top: -11px;\n}\n/* fix text-indent when trying to use custom icons on iconpos-notext buttons */\n.ui-btn-icon-notext {\n  text-indent: -9999px;\n}\n.ui-btn-icon-notext:after {\n  text-indent: 0px;\n}\n/* fix font-size on notext buttons, so icons don\'t zoom, JQMs-px font-size */\n.ui-header .ui-btn-icon-notext,\n.ui-footer .ui-btn-icon-notext {\n  font-size: 12.5px;\n}\n\n/* popup */\n.ui-popup {\n  max-width: 20em; /* so... all popups should get this??? */\n  /* width: 25%; does not work, because max-width will still be screen-padding */\n  min-width: 20em;\n  margin: 0 auto;\n}\n.ui-popup.ui-popup-wide {\n  max-width: 40em;\n  min-width: 40em;\n}\n@media (max-width: 40em) {\n  .ui-popup, html .ui-popup.ui-popup-wide {\n    min-width: 0;\n    margin: 0;\n    width: auto;\n  }\n}\n.ui-popup fieldset {\n  display: block; /* fix offset caused when using display: table-column */\n}\n\n/* all of this should go into a single wrapper/toolbar widget */\n.ui-popup.ui-popup-wide form.draggable div.ui-grid-row {\n  cursor: move;\n}\n.ui-popup.ui-popup-wide form div.ui-grid-row {\n  padding-top: .25em;\n  border-bottom: 1px solid rgba(0, 0, 0, .1);\n}\n.ui-popup.ui-popup-wide form .ui-grid-title {\n  max-width: 25%;\n}\n.ui-popup.ui-popup-wide form .ui-grid-search {\n  min-width: 35%;\n  width: auto;\n}\n@media (max-width: 40em) {\n.ui-popup.ui-popup-wide form .ui-grid-search {\n  max-width: 35%;\n}\n}\n.ui-popup.ui-popup-wide form .ui-grid-action {\n  max-width: 5%;\n}\n.ui-popup.ui-popup-wide form .ui-block-a,\n.ui-popup.ui-popup-wide form .ui-block-b,\n.ui-popup.ui-popup-wide form .ui-block-c,\n.ui-popup.ui-popup-wide form .ui-block-d {\n  height: 2.5em;\n  line-height: 2.5em;\n  vertical-align: middle;\n}\n.ui-popup.ui-popup-wide div > p {\n  padding: 0 15px;\n  text-align: center;\n}\n.ui-popup.ui-popup-wide .ui-slider.ui-mini {\n  margin-top: 0;\n  margin-bottom: 0;\n}\n.ui-popup.ui-popup-wide form .ui-grid-title span {\n  display: table-cell;\n  padding: 0.25em 0 0.25em 0.5em;\n  font-size: .9em;\n}\n.ui-popup.ui-popup-wide form .ui-input-text {\n  margin: 0 0.5em;\n}\n.ui-popup.ui-popup-wide .ui-grid-3,\n.ui-popup.ui-popup-narrow .ui-grid-3,\n.ui-popup.ui-popup-wide .ui-grid-2,\n.ui-popup.ui-popup-narrow .ui-grid-2 {\n  margin: 0;\n}\n.ui-popup.ui-popup-wide .ui-popup-menu,\n.ui-popup.ui-popup-narrow .ui-popup-menu {\n  text-align: center;\n  margin-bottom: .5em;\n}\n.ui-popup.ui-popup-wide .ui-popup-menu .ui-controlgroup-controls .ui-btn,\n.ui-popup.ui-popup-wide .ui-grid-row .ui-select .ui-btn,\n.ui-popup.ui-popup-narrow .ui-popup-menu .ui-controlgroup-controls .ui-btn {\n  font-size: 85%;\n}\n.ui-popup.ui-popup-wide .ui-grid-row .ui-select,\n.ui-popup.ui-popup-wide .ui-grid-row .ui-checkbox {\n  margin-top: 0;\n  margin-bottom: 0;\n}\n.ui-popup.ui-popup-wide .ui-popup-menu .ui-controlgroup-controls .ui-btn:after,\n.ui-popup.ui-popup-narrow .ui-popup-menu .ui-controlgroup-controls .ui-btn:after{\n  margin-top: -12px;\n}\n.ui-popup.ui-popup-wide .ui-grid-3.ui-controlgroup-controls,\n.ui-popup.ui-popup-wide .ui-grid-2.ui-controlgroup-controls,\n.ui-popup.ui-popup-narrow .ui-grid-3.ui-controlgroup-controls,\n.ui-popup.ui-popup-narrow .ui-grid-2.ui-controlgroup-controls {\n  width: 100%;\n}\n.ui-popup.ui-popup-wide .ui-grid-3 a.ui-btn,\n.ui-popup.ui-popup-narrow .ui-grid-3 a.ui-btn{\n  width: 33.33%;\n  box-sizing: padding-box;\n  -moz-box-sizing: padding-box;\n  -webkit-box-sizing: padding-box;\n  border-width: 0px;\n}\n.ui-popup.ui-popup-wide .ui-grid-2 a.ui-btn,\n.ui-popup.ui-popup-narrow .ui-grid-2 a.ui-btn{\n  width: 50%;\n  box-sizing: padding-box;\n  -moz-box-sizing: padding-box;\n  -webkit-box-sizing: padding-box;\n  border-width: 0px;\n}\n\n\n/* panel */\n.ui-panel {\n  border-width: 0px; /* overwrite border-width reset by panel-swatch ui-overlay... */\n}\n/* panel closer */\nhtml .ui-panel-inner .ui-btn.panel-close {\n  background-color: transparent;\n  background-image: none;\n  margin: 12px 0.3125em 0; /* no friend ... */\n}\nhtml .ui-panel-inner .ui-btn.panel-close:hover {\n  border-color: transparent;\n}\nhtml .ui-panel-inner .ui-btn.panel-close:after {\n  font-size: 1.25em;\n  margin-top: -12px; /* no friend ... */\n}\nhtml .ui-btn.panel-close {\n  position: absolute !important;\n  top: -9999px;\n  left: -9999px;\n  clip: rect(1px 1px 1px 1px);\n  display: none;\n}\n@media (max-width: 30em) {\n  html .ui-btn.panel-close {\n    right: 0;\n    top: 0;\n    left: auto;\n    clip: auto;\n    display: block;\n  }\n}\n/* panel search input overriding width */\nhtml .ui-panel-inner .ui-input-search {\n  margin: 2% 1%;\n}\n@media (max-width: 30em) {\n  html .ui-panel-inner .ui-input-search {\n    width: 77%;\n  }\n}\n\n@media (max-width: 25em) {\n  html .ui-panel-inner .ui-input-search {\n    width: 77%;\n  }\n}\n@media (max-width: 20em) {\n  html .ui-panel-inner .ui-input-search {\n    width: 77%;\n  }\n}\n/* filterable */\nhtml .ui-filterable {\n  width: 75%;\n  margin: 0 auto;\n}\n@media (max-width: 40em) {\n  html .ui-filterable  {\n    width: 100%;\n    margin: 0.5em 0;\n  }\n}\n\n/* extend panel to fullwidth on small screens */\n@media (max-width: 30em) {\n  /* override JQM 17em */\n  .ui-panel {\n    width: 100%;\n  }\n  /* positioning: panel */\n  /* panel left  */\n  .ui-panel-position-left {\n    left: -100%;\n  }\n  /* animated: panel left (for overlay and push) */\n  .ui-panel-animate.ui-panel-position-left.ui-panel-display-overlay,\n  .ui-panel-animate.ui-panel-position-left.ui-panel-display-push {\n    left: 0;\n    -webkit-transform: translate3d(-100%,0,0);\n    -moz-transform: translate3d(-100%,0,0);\n    transform: translate3d(-100%,0,0);\n  }\n  /* panel left open */\n  .ui-panel-position-left.ui-panel-display-reveal, /* negate \"panel left\" for reveal */\n  .ui-panel-position-left.ui-panel-open {\n    left: 0;\n  }\n  /* animated: panel left open (for overlay and push) */\n  .ui-panel-animate.ui-panel-position-left.ui-panel-open.ui-panel-display-overlay,\n  .ui-panel-animate.ui-panel-position-left.ui-panel-open.ui-panel-display-push {\n    -webkit-transform: translate3d(0,0,0);\n    transform: translate3d(0,0,0);\n    -moz-transform: none;\n  }\n  /* panel right */\n  .ui-panel-position-right {\n    right: -100%;\n  }\n  /* animated: panel right (for overlay and push) */\n  .ui-panel-animate.ui-panel-position-right.ui-panel-display-overlay,\n  .ui-panel-animate.ui-panel-position-right.ui-panel-display-push {\n    right: 0;\n    -webkit-transform: translate3d(100%,0,0);\n    -moz-transform: translate3d(100%,0,0);\n    transform: translate3d(100%,0,0);\n  }\n  /* panel right open */\n  .ui-panel-position-right.ui-panel-display-reveal,  /* negate \"panel right\" for reveal */\n  .ui-panel-position-right.ui-panel-open {\n    right: 0;\n  }\n  /* animated: panel right open (for overlay and push) */\n  .ui-panel-animate.ui-panel-position-right.ui-panel-open.ui-panel-display-overlay,\n  .ui-panel-animate.ui-panel-position-right.ui-panel-open.ui-panel-display-push {\n    -webkit-transform: translate3d(0,0,0);\n    transform: translate3d(0,0,0);\n    -moz-transform: none;\n  }\n  /* positioning: pages, fixed toolbars and dismiss */\n  /* panel left open */\n  .ui-panel-page-content-position-left.ui-panel-page-content-open,\n  .ui-panel-dismiss-position-left.ui-panel-dismiss-open {\n    left: 100%;\n    right: -100%;\n  }\n  /* animated: panel left open (for reveal and push) */\n  .ui-panel-animate.ui-panel-page-content-position-left.ui-panel-page-content-open.ui-panel-page-content-display-reveal,\n  .ui-panel-animate.ui-panel-page-content-position-left.ui-panel-page-content-open.ui-panel-page-content-display-push {\n    left: 0;\n    right: 0;\n    -webkit-transform: translate3d(100%,0,0);\n    -moz-transform: translate3d(100%,0,0);\n    transform: translate3d(100%,0,0);\n  }\n  /* panel right open */\n  .ui-panel-page-content-position-right.ui-panel-page-content-open,\n  .ui-panel-dismiss-position-right.ui-panel-dismiss-open {\n    left: -100%;\n    right: 100%;\n  }\n  /* animated: panel right open (for reveal and push) */\n  .ui-panel-animate.ui-panel-page-content-position-right.ui-panel-page-content-open.ui-panel-page-content-display-reveal,\n  .ui-panel-animate.ui-panel-page-content-position-right.ui-panel-page-content-open.ui-panel-page-content-display-push {\n    left: 0;\n    right: 0;\n    -webkit-transform: translate3d(-100%,0,0);\n    -moz-transform: translate3d(-100%,0,0);\n    transform: translate3d(-100%,0,0);\n  }\n  /* negate \"panel left/right open\" for overlay */\n  .ui-panel-page-content-open.ui-panel-page-content-display-overlay {\n    left: 0;\n  }\n}\n\n/* allow interaction with page on large displays */\n@media (min-width: 30em) {\n  /* wrap on wide viewports once open */\n  .ui-page-panel-open .ui-panel-content-fixed-toolbar-display-push.ui-panel-content-fixed-toolbar-position-left,\n  .ui-page-panel-open .ui-panel-content-fixed-toolbar-display-reveal.ui-panel-content-fixed-toolbar-position-left,\n  .ui-page-panel-open .ui-panel-content-wrap-display-push.ui-panel-content-wrap-position-left,\n  .ui-page-panel-open .ui-panel-content-wrap-display-reveal.ui-panel-content-wrap-position-left {\n    margin-right: 17em;\n  }\n  .ui-page-panel-open .ui-panel-content-fixed-toolbar-display-push.ui-panel-content-fixed-toolbar-position-right,\n  .ui-page-panel-open .ui-panel-content-fixed-toolbar-display-reveal.ui-panel-content-fixed-toolbar-position-right,\n  .ui-page-panel-open .ui-panel-content-wrap-display-push.ui-panel-content-wrap-position-right,\n  .ui-page-panel-open .ui-panel-content-wrap-display-reveal.ui-panel-content-wrap-position-right {\n    margin-left: 17em;\n  }\n  .ui-page-panel-open .ui-panel-content-fixed-toolbar-display-push,\n  .ui-page-panel-open .ui-panel-content-fixed-toolbar-display-reveal {\n    width: auto;\n  }\n  /* disable \"dismiss\" on wide viewports */\n  .ui-panel-dismiss {\n    display: none;\n  }\n  /* same as the above but for panels with display mode \"push\" only */\n  .ui-panel-dismiss-display-push {\n    display: none;\n  }\n}\n/* action/input buttons */\n.bare_button,\n.bare_button .ui-btn-inner,\n.bare_button .ui-icon {\n  background: 0 none;\n  border: 0 none;\n  box-shadow: none !important;\n  -webkit-box-shadow: none !important;\n}\n.bare_button .ui-icon {\n  bottom: 0;\n  line-height: 1em;\n  margin: 0;\n  text-align: center;\n  top: 31%;\n  font-size: 1.25em;\n  border-radius: 0px !important;\n  -webkit-border-radius: 0px !important;\n}\n\n\n\n/* listview/list */\n/* plain list */\n.list {\n  list-style: none;\n  text-align: center;\n  padding: 0;\n  margin: 0.5em 0;\n}\n.list li a {\n  text-decoration: none;\n}\n\n/* ============================== RESPONSIVE ============================== */\n/* hide button text on small screens */\n@media (max-width: 40em) {\n  .responsive.ui-btn,\n  .ui-select span.responsive /*,\n .responsive .ui-btn */ {\n    text-indent: -9999px;\n    white-space: nowrap !important;\n  }\n  .responsive.ui-btn:after /*,\n  .responsive .ui-btn:after*/ {\n    text-indent: 0px;\n    left: 10px;\n  }\n}\n\n/* responsive listview */\n.ui-listview.responsive > li.ui-first-child:only-child {\n  border-bottom-right-radius: .3125em;\n  border-bottom-left-radius: .3125em;\n  -webkit-border-bottom-right-radius: .3125em;\n  -webkit-border-bottom-left-radius: .3125em;\n}\n.ui-listview.responsive > li > a.ui-btn:only-child {\n  border-bottom-width: 1px;\n}\n/* icon size in regular listview */\n.ui-listview.responsive li .ui-btn .ui-li-icon-custom:after {\n    font-size: 1.5em;\n    padding: 0.5em 0.1em;\n}\n/* text padding in regular listview */\n.ui-listview.responsive > .ui-li-has-icon > .ui-btn,\n.ui-listview.responsive > .ui-li-static.ui-li-has-icon {\n  padding-left: 3.5em;\n}\n/* First breakpoint is 48em (768px). 3 column layout. Tiles 250x250 pixels incl. margin at the breakpoint. */\n@media ( min-width: 48em ) {\n  /* TODO: fix this - app icons */\n  .ui-listview.responsive .ui-li-has-thumb > img:first-child, \n  .ui-listview.responsive .ui-li-has-thumb > .ui-btn > img:first-child, \n  .ui-listview.responsive .ui-li-has-thumb .ui-li-thumb {\n    max-width: 8em;\n    max-height: 8em;\n    left: 31%;\n    top: 5%;\n  }\n\n  /* limit controlbar width */\n  html .ui-page .ui-controlbar.responsive,\n  form.responsive {\n    max-width: 40em; /* 640px */\n    margin: 0 auto;\n    clear: both;\n  }\n  .ui-listview.responsive li {\n    float: left;\n    width: 30.9333%; /* 33.3333% incl. 2 x 1.2% margin */\n    height: 14.5em; /* 232p */\n    margin: .5625em 1.2%;\n  }\n  .ui-listview.responsive li > .ui-btn {\n    -webkit-box-sizing: border-box; /* include padding and border in height so we can set it to 100% */\n    -moz-box-sizing: border-box;\n    -ms-box-sizing: border-box;\n    box-sizing: border-box;\n    height: 100%;\n    border-bottom-width: 1px;\n  }\n  .ui-listview.responsive li.ui-li-has-thumb .ui-li-thumb,\n  .ui-listview.responsive li.ui-li-has-icon .ui-li-icon-custom {\n    height: auto; /* To keep aspect ratio. */\n    max-width: 100% !important;\n    max-height: none;\n  }\n  /* Overwrite custom icon width 22px */\n  .ui-listview.responsive li span.ui-li-icon-custom {\n    width: 100% !important;\n  }\n  /* Make all list items and anchors inherit the border-radius from the UL. */\n  .ui-listview.responsive li,\n  .ui-listview.responsive li .ui-btn,\n  .ui-listview.responsive .ui-li-thumb,\n  .ui-listview.responsive .ui-li-icon-custom {\n    -webkit-border-radius: inherit;\n    border-radius: inherit;\n  }\n  /* Hide the icon */\n  .ui-listview.responsive .ui-btn-icon-right:after {\n    display: none;\n  }\n  /* Enlarge custom icon */\n  .ui-listview.responsive li .ui-btn .ui-li-icon-custom:after {\n    font-size: 3em;\n  }\n  /* Align center */\n  .ui-listview.responsive li > .ui-btn {\n    text-align: center;\n  }\n  /* Make text wrap. */\n  .ui-listview.responsive h1,\n  .ui-listview.responsive p {\n    white-space: normal;\n    overflow: visible;\n    position: absolute;\n    left: 0;\n    right: 0;\n  }\n  /* Text position */\n  .ui-listview.responsive h1 {\n    font-size: 1.25em;\n    margin: 0;\n    padding: .125em 1em;\n    bottom: 40%;\n  }\n  .ui-listview.responsive p {\n    font-size: 1em;\n    margin: 0;\n    padding: 0 1.25em;\n    min-height: 40%;\n    bottom: 0;\n    overflow: hidden;\n    white-space: nowrap;\n    text-overflow: ellipsis;\n  }\n  /* Semi transparent background and different position if there is a thumb. The button has overflow hidden so we don\'t need to set border-radius. */\n  .ui-listview.responsive .ui-li-has-thumb h1,\n  .ui-listview.responsive .ui-li-has-thumb p,\n  .ui-listview.responsive .ui-li-has-icon h1,\n  .ui-listview.responsive .ui-li-has-icon p,{\n    background: #111;\n    background: rgba(0,0,0,.8);\n  }\n  .ui-listview.responsive .ui-li-has-thumb h1,\n  .ui-listview.responsive .ui-li-has-icon h1 {\n    bottom: 25%;\n  }\n  .ui-listview.responsive .ui-li-has-thumb p,\n  .ui-listview.responsive .ui-li-has-icon p{\n    min-height: 25%;\n  }\n  /* ui-li-aside has class .ui-li-desc as well so we have to override some things. */\n  .ui-listview.responsive .ui-li-aside {\n    padding: .125em .625em;\n    width: auto;\n    min-height: 0;\n    top: 0;\n    left: auto;\n    bottom: auto;\n    /* Custom styling. */\n    background: #990099;\n    background: rgba(153,0,153,.85);\n    -webkit-border-top-right-radius: inherit;\n    border-top-right-radius: inherit;\n    -webkit-border-bottom-left-radius: inherit;\n    border-bottom-left-radius: inherit;\n    -webkit-border-bottom-right-radius: 0;\n    border-bottom-right-radius: 0;\n  }\n  /* Animate focus and hover style, and resizing. */\n  .ui-listview.responsive li,\n  .ui-listview.responsive .ui-btn {\n    -webkit-transition: all 500ms ease;\n    -moz-transition: all 500ms ease;\n    -o-transition: all 500ms ease;\n    -ms-transition: all 500ms ease;\n    transition: all 500ms ease;\n  }\n}\n\n/* Second breakpoint is 63.75em (1020px). 4 column layout. Tiles will be 250x250 pixels incl. margin again at the breakpoint. */\n@media ( min-width: 63.75em ) {\n  .ui-listview.responsive .ui-li-has-thumb > img:first-child, \n  .ui-listview.responsive .ui-li-has-thumb > .ui-btn > img:first-child, \n  .ui-listview.responsive .ui-li-has-thumb .ui-li-thumb {\n    max-width: 8em;\n    max-height: 8em;\n    left: 25%;\n    top: 5%;\n  }\n  /* Set a max-width for the last breakpoint to prevent too much stretching on large screens.\n  By setting the max-width equal to the breakpoint width minus padding we keep square tiles. */\n  /* responsive content */\n  html form.responsive,\n  html .ui-page .ui-content-element.responsive,\n  html .ui-page .ui-listview.responsive,\n  html .ui-page .ui-controlbar.responsive {\n    max-width: 62.5em; /* 1000px */\n    margin: 0 auto;\n    clear: both;\n  }\n  /* Enlarge custom icon */\n  .ui-listview.responsive li .ui-btn .ui-li-icon-custom:after {\n    font-size: 4em;\n  }\n  /* Align center */\n  .ui-listview.responsive li > .ui-btn {\n    text-align: center;\n  }\n  /* Overwrite custom icon width 22px */\n  .ui-listview.responsive li span.ui-li-icon-custom {\n    width: 100% !important;\n  }\n  /* Because of the 1000px max-width the width will always be 230px (and margin left/right 10px),\n  but we stick to percentage values for demo purposes. */\n  .ui-listview.responsive li {\n    width: 23%;\n    height: 230px;\n    margin: .625em 1%;\n  }\n}\n/* =========== */\n\n\n/* listview */\nhtml .ui-panel-inner .ui-listview .ui-li-divider {\n  font-weight: bold;\n  padding: 0.5em 1em;\n  border: 0 none;\n}\nhtml .ui-panel-inner .ui-listview li a {\n  padding: 0.4em 2.75em !important;\n}\n.ui-panel-inner .ui-listview > li h1,\n.ui-panel-inner .ui-listview > li h2,\n.ui-panel-inner .ui-listview > li h3,\n.ui-panel-inner .ui-listview > li h4,\n.ui-panel-inner .ui-listview > li h5,\n.ui-panel-inner .ui-listview > li h6 {\n  font-size: .9em;\n  margin: 0;\n}\n.ui-panel-inner .ui-listview > li p {\n  font-size: .7em;\n  margin: 0;\n}\n.ui-panel-inner .ui-listview .ui-li-has-thumb > img:first-child,\n.ui-panel-inner .ui-listview .ui-li-has-thumb > .ui-btn > img:first-child {\n  max-height: 2.5em;\n  max-width: 2.5em;\n  overflow: hidden;\n  padding: 0.2em 0;\n}\n\n/* overwrite icon positioning for fontawesome */\n/*\n.ui-panel-inner .ui-btn-icon-right:after,\n.ui-panel-inner .ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after {\n  right: 0;\n}\n.ui-btn-icon-right:after,\n.ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after {\n  right: 0.3625em;\n}\n*/\n/* reset */\n/*\nhtml.ui-nosvg .ui-btn-icon-right:after,\nhtml.ui-nosvg .ui-panel-inner .ui-listview > li > .ui-btn[class*=\"ui-icon-\"]:after {\n  right: 0.5625em;\n}\n.ui-btn.ui-btn-icon-left:after {\n  left: 0.3625em;\n}\nhtml.ui-nosvg .ui-btn-icon-left:after {\n  left: 0.5625em;\n}\n*/\n/* custom icons */\n.ui-listview li span.ui-li-icon-custom {\n  bottom: 0;\n  top: 0;\n  box-shadow: none !important;\n  font-size: 1.25em;\n  height: 100%;\n  left: 0.25em;\n  line-height: 1em;\n  margin: 0;\n  max-height: 80px;\n  max-width: 80px;\n  position: absolute;\n  text-align: center;\n  width: 22px;\n  top: 19%; /* no friend... */\n}\n.ui-listview li span.ui-li-icon-custom:after {\n  background: none repeat scroll 0 center transparent;\n}\n\n/* checkboxradio */\n/* overwrite icon background for fontawesome */\n.ui-radio .ui-btn.ui-radio-on:after {\n  background: 0 none;\n  border-width: 0;\n}\n/* reset */\n.ui-nosvg .ui-radio .ui-btn-ui-radio-on:after {\n  background-color: #FFFFFF;\n  background-image: none;\n  border-width: 5px;\n}\n/* position icons */\n.ui-radio .ui-btn.ui-radio-on:after,\n.ui-radio .ui-btn.ui-radio-off:after,\n.ui-checkbox .ui-btn.ui-checkbox-on:after,\n.ui-checkbox .ui-btn.ui-checkbox-off:after {\n  margin: -14px 2px 0;\n}\n/* icon size */\n.ui-checkbox .ui-btn.ui-checkbox-on:after,\n.ui-checkbox .ui-btn.ui-checkbox-off:after {\n  font-size: 1.25em;\n  opacity: 1; /* overwrite JQM .3 for off... */\n}\n/* reset */\n.ui-nosvg .ui-radio .ui-btn.ui-radio-on:after,\n.ui-nosvg .ui-radio .ui-btn.ui-radio-off:after,\n.ui-checkbox .ui-btn.ui-checkbox-on:after,\n.ui-checkbox .ui-btn.ui-checkbox-off:after {\n  background: 0 none;\n  background-image: none;\n  margin: -11px 2px 0;\n}\n/* overwrite JQM showing focus icon */\n.ui-icon-check:after,\nhtml .ui-btn.ui-checkbox-on.ui-checkbox-on:after {\n  background-image: none;\n}\n\n/* filterable */\nhtml .ui-panel-inner .ui-input-search.ui-input-has-clear .ui-btn.ui-input-clear,\nhtml .ui-panel-inner .ui-input-search .ui-input-action {\n  background-image: none;\n}\nhtml .ui-panel-inner .ui-input-search.ui-input-has-clear .ui-btn.ui-input-clear {\n  margin: -9px 0.3125em 0;\n}\nhtml .ui-input-search .ui-input-clear:after,\nhtml .ui-input-search .ui-input-action:after {\n  margin-top: -12px;\n}\nhtml .ui-pane