dget_officejs_liberator.js\ngadget_officejs_liberator.html NETWORK: *'),(15458,'Field Graph With plotly.js gadget_field_graph_plotly.js /*global window, rJS, RSVP, console, Plotly */ /*jslint nomen: true, indent: 2\n*/ (function (window, rJS, RSVP, Plotly) { \"use strict\"; //////////////////////\n/////////////////////////////////////////// // templates //////////////////////\n/////////////////////////////////////////// var gadget_klass = rJS(window); var\ngetGraphDataAndParameterFromConfiguration = function (configuration_dict) { var\ngraph_data_and_parameter = {}, given_data_list, current_data, given_data,\naxis_mapping_id_dict, i, j, AXIS_MAPPING_DICT, mapped_axis_list, axis_list_dict\n= {}; AXIS_MAPPING_DICT = {0: \"x\", 1: \"y\", 2: \"z\"}; if\n(configuration_dict.constructor === String) { configuration_dict = JSON.parse\n(configuration_dict); } given_data_list = configuration_dict.data; console.log\n(\"getGraphDataAndParameterFromConfiguration 1 configuration_dict\",\nconfiguration_dict); graph_data_and_parameter.data_list = [];\ngraph_data_and_parameter.layout = {modeBarButtonsToRemove:\n[\'sendDataToCloud\']}; if (configuration_dict.title !== undefined) {\ngraph_data_and_parameter.layout.title = configuration_dict.title; } function\nsetCurrentData(axis_data) { console.log(\"setCurrentData, axis_data\",\naxis_data); var axis_id = AXIS_MAPPING_DICT[axis_data[0]], axis_value_list =\naxis_data[1]; current_data[axis_id] = axis_value_list; } console.log\n(\"getGraphDataAndParameterFromConfiguration 2\"); console.log(\"plotly\ngiven_data_list\", given_data_list); function setAxisLayout(axis_mapping) { var\naxis_id = AXIS_MAPPING_DICT[axis_mapping[0]], axis_identifier = axis_mapping\n[1], axis_name, axis_layout, mapped_axis_list; mapped_axis_list =\naxis_list_dict[axis_id] || []; if (mapped_axis_list.indexOf(axis_identifier) ==\n= -1) { mapped_axis_list.push(axis_identifier); axis_list_dict[axis_id] =\nmapped_axis_list; axis_name = axis_id + \"axis\"; console.log(\"mapped_axis_list\nin loop\", mapped_axis_list); axis_layout = {}; if (mapped_axis_list.indexOf\n(axis_identifier) !== 0) { axis_name = axis_name + (mapped_axis_list.indexOf\n(axis_identifier) + 1); axis_layout.overlaying = axis_id; axis_layout.side =\n\'right\'; axis_layout.position = 1 - (0.05 * mapped_axis_list.indexOf\n(axis_identifier)); // We must also reduce graph size to display all the axis\nlabels. We assume here that this // happens only for cases of having multiple y\naxis graph_data_and_parameter.layout.xaxis =\ngraph_data_and_parameter.layout.xaxis || {};\ngraph_data_and_parameter.layout.xaxis.domain = [0.0, axis_layout.position];\ncurrent_data[axis_id + \"axis\"] = axis_id + (mapped_axis_list.indexOf\n(axis_identifier) + 1); } console.log(\"axis_name\", axis_name); if\n(given_data.title !== undefined) { axis_layout.title = given_data.title; }\ngraph_data_and_parameter.layout[axis_name] = axis_layout; } } for (i = 0; i <\ngiven_data_list.length; i = i + 1) { current_data = {}; given_data =\ngiven_data_list[i]; Object.entries(given_data.value_dict).forEach\n(setCurrentData); if (given_data.title !== undefined) { current_data.name =\ngiven_data.title; } if (given_data.type !== undefined) { current_data.type =\ngiven_data.type; if (given_data.type === \"scatter\") { current_data.mode =\n\'markers\'; } } axis_mapping_id_dict = given_data.axis_mapping_id_dict || {};\nObject.entries(axis_mapping_id_dict).forEach(setAxisLayout);\ngraph_data_and_parameter.data_list.push(current_data); } console.log\n(\"getGraphDataAndParameterFromConfiguration 3\"); console.log(\"axis_list_dict\",\naxis_list_dict); console.log(\"graph_data_and_parameter\",\ngraph_data_and_parameter); graph_data_and_parameter.bar_config =\n{modeBarButtonsToRemove: [\'sendDataToCloud\']}; return graph_data_and_parameter;\n}; ///////////////////////////////////////////////////////////////// // some\nmethods /////////////////////////////////////////////////////////////////\ngadget_klass /////////////////////////////////////////////////////////////////\n// ready /////////////////////////////////////////////////////////////////\n.ready(function (gadget) { gadget.property_dict = {}; }) //////////////////////\n/////////////////////////////////////////// // published methods //////////////\n/////////////////////////////////////////////////// ///////////////////////////\n////////////////////////////////////// // acquired methods ////////////////////\n///////////////////////////////////////////// /////////////////////////////////\n//////////////////////////////// // declared methods //////////////////////////\n/////////////////////////////////////// .declareMethod(\'render\', function\n(option_dict) { var gadget = this; //delegate rendering to onStateChange to\navoid redrawing the graph //every time render is called (a form might call\nrender every time //some other fields needs update gadget.changeState({value:\noption_dict.value}); }) .onStateChange(function (modification_dict) { var\ngadget = this, container, graph_data_and_parameter, chart, graph_value;\ncontainer = gadget.element.querySelector(\".graph-content\");\ngadget.property_dict.container = container; console.log(\"container inside\niframe\"); graph_value = modification_dict.value; graph_data_and_parameter =\ngetGraphDataAndParameterFromConfiguration(graph_value); console.log(\"plotly\ngraph_data_and_parameter\", graph_data_and_parameter); if\n(gadget.property_dict.already_rendered === true) { Plotly.purge(container); }\nPlotly.plot(container, graph_data_and_parameter.data_list,\ngraph_data_and_parameter.layout, graph_data_and_parameter.bar_config);\ngadget.property_dict.already_rendered = true; }); }(window, rJS, RSVP,\nPlotly));'),(15459,'Field Graph With plotly.js HTML gadget_field_graph_plotly.html 001'),(15460,'Field Graph Interface gadget_field_graph_interface.html 001 field_graph_interface\n\nA graph gadget allows to display various types of graph (lines, bars, 3D, etc)\n\nrender\n    render a graph\n\n    option_dict\n        Schema available here : gadget_field_graph_interface_html_schema.json\n        Generic graph gadget. The purpose of this gadget is to provide an\n        unique API for various charting libraries Please see json schema for\n        supported parameters. Options were inspired by https://plot.ly/\n        javascript/ which supports various types of charts. For axis,\n        typically, on a scatter: - axis 0 would be mapped to x - axis 1 would\n        be mapped to y For a 3D surface, we would have : - axis 0 would be\n        mapped to x - axis 1 would be mapped to y - axis 2 would be mapped to z\n        Example of options: {value: {data: [{ value_dict: {\"0\": [0, 1, 2], \"1\":\n        [0, 1, 4] }, type: \"scatter\", label_list: [\"First Point\", \"Second\n        Point\", \"Third Point\"], axis_mapping_id_dict: {\"1\": \"1_1\"}, title:\n        \"first data set\" }, { value_dict: {\"0\": [0, 1, 3], \"1\": [0, 10, 40] },\n        type: \"scatter\", title: \"second data set\", axis_mapping_id_dict: {\"1\":\n        \"1_2\"} } ], layout: {axis_dict : {\"0\": {\"title\": \"x axis label\",\n        \"scale_type\": \"linear\", \"value_type\": \"number\"}, \"1_1\": {\"title\": \"y\n        axis label for first data set\", \"scale_type\": \"log\", \"side\" : \"left\"},\n        \"1_2\": {\"title\": \"y axis label for second data set\", \"position\":\n        \"right\"} }, title: \"Title for my global graph\"} } }');
INSERT INTO `full_text` VALUES (15461,'Field Graph With Echarts gadget_field_graph_echarts.js /*global window, rJS, RSVP, echarts */ /*jslint nomen: true, indent: 2,\nunparam: true */ (function (window, rJS, RSVP, echarts, loopEventListener) {\n\"use strict\"; /////////////////////////////////////////////////////////////////\n// templates /////////////////////////////////////////////////////////////////\nvar gadget_klass = rJS(window), getGraphDataAndParameterFromConfiguration =\nfunction (configuration_dict) { var graph_data_and_parameter = {}, data, trace,\ntrace_type, type_list = [], label_list = [], trace_value_dict, dataset_list =\n[], dataset, i, j, layout, title; if (configuration_dict.constructor ===\nString) { configuration_dict = JSON.parse(configuration_dict); } data =\nconfiguration_dict.data || []; layout = configuration_dict.layout || {}; title\n= layout.title; // title // The position of the title in plotly was fixed, like\nthe \"x:center\" in echarts. // For now, every graph have to provide a title. if\n(title === undefined) { throw new Error(\"No title provided\", data); }\ngraph_data_and_parameter.title = { text: title, x: \"center\" }; // tooltip //\nECharts have to enable the tooltip manually. graph_data_and_parameter.tooltip =\n{}; graph_data_and_parameter.tooltip.trigger = \"item\"; // legend // Initialize\nthe legend. graph_data_and_parameter.legend = {};\ngraph_data_and_parameter.legend.y = 25; graph_data_and_parameter.legend.data =\n[]; // Axis // Initialize the axis graph_data_and_parameter.xAxis = [];\ngraph_data_and_parameter.yAxis = []; for (i = 0; i < data.length; i = i + 1) {\ntrace = data[i]; trace_type = trace.type || \"bar\"; type_list.push(trace_type);\ntrace_value_dict = trace.value_dict || {}; if ( trace_value_dict[0] ===\nundefined || trace_value_dict[1] === undefined ) { throw new Error(\"Unexpected\ndata for ECharts\", data); } dataset = {}; dataset.type = trace_type;\ndataset.name = trace.title || {}; // If the graph type is pie, set the pie\nradius // plotly doesn\'t have this option. if (trace_type === \"pie\") {\ndataset.radius = \"55%\"; dataset.center = [\"50%\", \"60%\"]; } // For pie graph,\nthe legend labels come from each item\'s title(aka trace.title) // For graph\nwhich contains the axis, the legend labels come from the item\'s value_dict[0].\n// See the trace_value_dict in below. But the duplicated value_dict[0] seems\nfor 2D graph // seems is redandunt. if (trace.type !== \"pie\") {\ngraph_data_and_parameter.legend.data.push(dataset.name); } dataset.data = [];\nfor (j = 0; j < trace_value_dict[0].length; j = j + 1) { if (label_list.length\n!== trace_value_dict[0].length) { label_list[j] = trace_value_dict[0][j]; } } /\n/ Value for (j = 0; j < trace_value_dict[1].length; j = j + 1) {\ndataset.data.push({ value: trace_value_dict[1][j], name: label_list[j],\nitemStyle: null }); // Handle the colors in different ways. Maybe enhanced\nlatter if (trace.colors) { // In the pie graph, set the color each individual\n\"data\" item. if (trace.type === \"pie\") { dataset.data[j].itemStyle = { normal:\n{ color: trace.colors[j] } }; } else { // In other types of graph, set the\ncolor for each group. dataset.itemStyle = { normal: { color: trace.colors[0] }\n}; } } } dataset_list.push(dataset); } // For the pie graph, the legend label\nis the value_dict[0] if (trace.type === \"pie\") {\ngraph_data_and_parameter.legend.data = label_list; } // Axis if (trace.type !==\n\"pie\") { // if not value type provided, set it as \"value\".\ngraph_data_and_parameter.yAxis.push({ type: \"value\", name: layout.axis_dict\n[1].title }); graph_data_and_parameter.xAxis.push({ data: label_list, name:\nlayout.axis_dict[0].title }); } else { graph_data_and_parameter.xAxis = null;\ngraph_data_and_parameter.yAxis = null; } graph_data_and_parameter.series =\ndataset_list; return graph_data_and_parameter; }; /////////////////////////////\n//////////////////////////////////// // some methods //////////////////////////\n/////////////////////////////////////// function promiseChartEventListener\n(chart, type) { ////////////////////////// // Resolve the promise as soon as\nthe event is triggered // eventListener is removed when promise is cancelled/\nresolved/rejected ////////////////////////// var handle_event_callback;\nfunction canceller() { chart.off(type, handle_event_callback); } function\nresolver(resolve) { handle_event_callback = function (params) { canceller();\nresolve(params); return false; }; chart.on(type, handle_event_callback); }\nreturn new RSVP.Promise(resolver, canceller); } function loopChartEventListener\n(chart, type, callback) { ////////////////////////// // Infinite event listener\n(promise is never resolved) // eventListener is removed when promise is\ncancelled/rejected ////////////////////////// var handle_event_callback,\ncallback_promise; function cancelResolver() { if ((callback_promise !==\nundefined) && (typeof callback_promise.cancel === \"function\")) {\ncallback_promise.cancel(); } } function canceller() { if (handle_event_callback\n!== undefined) { chart.off(type, handle_event_callback); } cancelResolver(); }\nfunction itsANonResolvableTrap(resolve, reject) { var result;\nhandle_event_callback = function handleEventCallback(params) { cancelResolver\n(); try { result = callback(params); } catch (e) { return reject(e); }\ncallback_promise = new RSVP.Queue(result) .push(undefined, function\nhandleEventCallbackError(error) { // Prevent rejecting the loop, if the result\ncancelled itself if (!(error instanceof RSVP.CancellationError)) { canceller();\nreject(error); } }); }; chart.on(type, handle_event_callback); } return new\nRSVP.Promise(itsANonResolvableTrap, canceller); } gadget_klass\n.declareAcquiredMethod(\"chartItemClick\", \"chartItemClick\") ////////////////////\n///////////////////////////////////////////// // ready ////////////////////////\n///////////////////////////////////////// /////////////////////////////////////\n//////////////////////////// // published methods /////////////////////////////\n//////////////////////////////////// //////////////////////////////////////////\n/////////////////////// // acquired methods ///////////////////////////////////\n////////////////////////////// ////////////////////////////////////////////////\n///////////////// // declared methods /////////////////////////////////////////\n//////////////////////// .declareMethod(\"render\", function (option_dict) { //\ndelegate rendering to onStateChange to avoid redrawing the graph //every time\nrender is called (a form might call render every time //some other fields needs\nupdate) return this.changeState({ value: option_dict.value, clickHandlerReady:\nfalse }); }) .onStateChange(function (modification_dict) { var gadget = this,\nchart; // the gadget is ready when both the graph is rendered and the click\nhandler is attached. if (modification_dict.hasOwnProperty(\"clickHandlerReady\"))\n{ if (gadget.state.clickHandlerReady) { gadget.element.querySelector\n(\".graph-content\").removeAttribute(\"disabled\"); } else {\ngadget.element.querySelector(\".graph-content\").setAttribute(\"disabled\",\n\"disabled\"); } } if (modification_dict.hasOwnProperty(\"value\")) { chart =\necharts.init( gadget.element.querySelector(\".graph-content\") ); return new\nRSVP.Queue(RSVP.all([ promiseChartEventListener(chart, \'finished\'),\nchart.setOption(getGraphDataAndParameterFromConfiguration(\nmodification_dict.value )) ])) .push(function () { gadget.listenToWindowResize\n(chart); gadget.listenToClickEventOnTheChart(chart); }); } }) .declareJob\n(\"listenToWindowResize\", function (chart) { return loopEventListener( window,\n\"resize\", { passive: true }, function () { return chart.resize(); }, false );\n}) .declareJob(\"listenToClickEventOnTheChart\", function (chart) { var gadget =\nthis; return RSVP.all([ loopChartEventListener(chart, \"click\", function\n(params) { return gadget.chartItemClick([params.name, params.seriesName]); }),\ngadget.changeState({clickHandlerReady: true}) ]); }); }(window, rJS, RSVP,\necharts, rJS.loopEventListener));'),(15462,'Field Graph With Echarts HTML gadget_field_graph_echarts.html 001'),(15463,'Field Graph With Echarts CSS gadget_field_graph_echarts.css 001 html { height: 300px; } body { height: 100%; margin: 0; } .graph-content {\nheight: 95%; width: 95%; }'),(15464,'Field Graph Dygraph JS gadget_field_graph_dygraph.js /*global window, rJS, RSVP, console, Dygraph */ /*jslint nomen: true, indent: 2\n*/ (function (window, rJS, RSVP, Dygraph) { \"use strict\"; /////////////////////\n//////////////////////////////////////////// // templates /////////////////////\n//////////////////////////////////////////// var gadget_klass = rJS(window);\nvar getGraphDataAndParameterFromConfiguration = function (configuration_dict) {\nvar graph_data_and_parameter = {}, layout, data, x_label, y_label, label_list =\n[], trace_value_dict, dygraph_data = [], trace, dygraph_data_and_parameter =\n{}, axis_dict, object_key_list, axis_definition, axis_mapping_id_dict, type,\nserie, serie_value_list = [], serie_value_mapping = {}, i, j; if\n(configuration_dict.constructor === String) { configuration_dict = JSON.parse\n(configuration_dict); } layout = configuration_dict.layout || {}; data =\nconfiguration_dict.data || []; axis_dict = layout.axis_dict || {}; x_label =\n(axis_dict[0] || {}).title; y_label = (axis_dict[1] || {}).title; if (x_label !\n== undefined) { graph_data_and_parameter.xlabel = x_label; } if (y_label !==\nundefined) { graph_data_and_parameter.ylabel = y_label; } label_list.push\n(x_label); /* Dygraph only support 2D, so we assume we have only only two axis\nfor data. Then for now we only support series having same x, it can be enhanced\nlater.*/ /* We assume below that the x axis for all data is the same.\nOtherwise, dygraph needs that we fill empty values by hand, which is not done\nhere yet When having several series, we can set mapping to [y1, y2, y3, etc].\nThough dygraph expect having exactly y, y2, y3, etc]. So we have to remap. */\ngraph_data_and_parameter.series = {}; function setSerie(value) { var\nserie_value_index; var mapped_serie; serie = {}; serie_value_list.push(value);\nserie_value_index = serie_value_list.indexOf(value); if (serie_value_index ===\n0) { mapped_serie = \"y\"; } else { mapped_serie = \"y\" + (serie_value_index + 1);\n} serie.axis = mapped_serie; serie_value_mapping[value] = mapped_serie; if\n(type === \"scatter\") { serie.drawPoints = true; serie.strokeWidth = 0; }\ngraph_data_and_parameter.series[trace.title || \'\'] = serie; } for (i = 0; i <\ndata.length; i = i + 1) { trace = data[i]; trace_value_dict = trace.value_dict\n|| {}; label_list.push(trace.title || \'\'); if (trace_value_dict[0] ===\nundefined || trace_value_dict[1] === undefined) { throw new Error(\"Unexpected\ndata for dygraph\", data); } if (dygraph_data.length === 0) { // Initialize x\naxis for (j = 0; j < trace_value_dict[0].length; j = j + 1) { // When used\nwithin iframe, we have to recreate date object since the date is now string\ndygraph_data[j] = [new Date(trace_value_dict[0][j])]; } } type = trace.type ||\n\'line\'; // to fill y axis for trace for (j = 0; j < trace_value_dict[1].length;\nj = j + 1) { dygraph_data[j].push(trace_value_dict[1][j]); }\naxis_mapping_id_dict = trace.axis_mapping_id_dict || {}; Object.values\n(axis_mapping_id_dict).forEach(setSerie); } /* Define parameters of axes */\ngraph_data_and_parameter.axes = {}; object_key_list = Object.keys(axis_dict);\nObject.entries(axis_dict).forEach(function (axis_data) { var axis_id =\naxis_data[0], axis_configuration = axis_data[1]; if (serie_value_mapping\n[axis_id] !== undefined) { axis_id = serie_value_mapping[axis_id]; }\ngraph_data_and_parameter.axes[axis_id] = {}; if (axis_configuration.position !=\n= undefined) { graph_data_and_parameter.axes[axis_id].position =\naxis_configuration.position; graph_data_and_parameter.axes\n[axis_id].independentTicks = true; // XXX Needed ??? } }); if\n(graph_data_and_parameter.axes[0] !== undefined) {\ngraph_data_and_parameter.axes.x = graph_data_and_parameter.axes[0];\ngraph_data_and_parameter.axes.x.title = \"date\"; // XXX FIX delete\ngraph_data_and_parameter.axes[0]; } graph_data_and_parameter.labels =\nlabel_list; graph_data_and_parameter.dygraph_data = dygraph_data;\ngraph_data_and_parameter.dygraph_parameter_dict = graph_data_and_parameter;\nreturn graph_data_and_parameter; }; var formatGraphDict = function (input_dict)\n{ var i, j, key, series = [], label_list = [\'x\'], point_list = [],\nserie_length, point; for (i = 0; i < input_dict.data.length; i = i + 1) { for\n(key of Object.keys(input_dict.data[i].value_dict)) { serie_length =\ninput_dict.data[i].value_dict[key].length; if (key == 0) { if (series.length ==\n= 0) { series.push(input_dict.data[i].value_dict[key]); //x } } else {\nseries.push(input_dict.data[i].value_dict[key]); //yi } } label_list.push\n(input_dict.data[i].title); } for (i = 0; i < serie_length; i = i + 1) { point\n= []; for (j = 0; j < series.length; j = j + 1) { point.push(series[j][i]); }\npoint_list.push(point); } var dygraph_dict = { dygraph_data: point_list,\ndygraph_parameter_dict: { labels: label_list, drawPoints : true, pointSize : 1,\n} }; return dygraph_dict; }; //////////////////////////////////////////////////\n/////////////// // some methods ///////////////////////////////////////////////\n////////////////// gadget_klass ///////////////////////////////////////////////\n////////////////// // ready ///////////////////////////////////////////////////\n////////////// .ready(function (gadget) { gadget.property_dict = {}; }) ///////\n////////////////////////////////////////////////////////// // published methods\n///////////////////////////////////////////////////////////////// /////////////\n//////////////////////////////////////////////////// // acquired methods //////\n/////////////////////////////////////////////////////////// ///////////////////\n////////////////////////////////////////////// // declared methods ////////////\n///////////////////////////////////////////////////// .declareMethod(\'render\',\nfunction (option_dict) { var gadget = this; //delegate rendering to\nonStateChange to avoid redrawing the graph //every time render is called (a\nform might call render every time //some other fields needs update\ngadget.changeState({value: option_dict.value}); }) .onStateChange(function\n(modification_dict) { var gadget = this, container, graph_data_and_parameter;\ncontainer = gadget.element.querySelector(\".graph-content\"); if\n(modification_dict.value.new_format) { graph_data_and_parameter =\nformatGraphDict(modification_dict.value); } else { graph_data_and_parameter =\ngetGraphDataAndParameterFromConfiguration(modification_dict.value); }\ngadget.property_dict.graph = new Dygraph(container,\ngraph_data_and_parameter.dygraph_data,\ngraph_data_and_parameter.dygraph_parameter_dict); }); }(window, rJS, RSVP,\nDygraph));'),(15465,'Field Graph With Dygraph gadget_field_graph_dygraph.html 001'),(15466,'Field Graph With Chart.js JS gadget_field_graph_chart.js /*global window, rJS, RSVP, console, Chart */ /*jslint nomen: true, indent: 2 *\n/ (function (window, rJS, RSVP, Chart) { \"use strict\"; ////////////////////////\n///////////////////////////////////////// // templates ////////////////////////\n///////////////////////////////////////// var gadget_klass = rJS(window); var\ngetGraphDataAndParameterFromConfiguration = function (configuration_dict) { var\ngraph_data_and_parameter = {}, data, trace, trace_type, type_list = [],\nlabel_list = [], trace_value_dict, dataset_list = [], dataset, i, j, layout,\ntitle, type = \'bar\', x_label, y_label; if (configuration_dict.constructor ===\nString) { configuration_dict = JSON.parse(configuration_dict); } data =\nconfiguration_dict.data || []; layout = configuration_dict.layout || {}; title\n= layout.title; /* title seems to be ignored by Chart.js, so do not handle it\nfor 