anty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA 02111-1307, USA.\n\nimport io\nfrom ZPublisher.HTTPRequest import HTTPRequest\nfrom ZPublisher.HTTPResponse import HTTPResponse\nfrom Products.ERP5Type.tests.ERP5TypeTestCase import ERP5TypeTestCase\nfrom Products.ERP5Type import IS_ZOPE2\nfrom erp5.component.module.BTreeData import BTreeData, PersistentBytes\n\n\n# like Testing.makerequest, but\n#\n#   1. always redirects stdout to BytesIO,\n#   2. stdin content can be specified and is processed,\n#   3. returns actual request object (not wrapped portal).\n#\n# see also: Products.CMFCore.tests.test_CookieCrumbler.makerequest()\n# TODO makerequest() is generic enough and deserves moving to testing utils\ndef makerequest(environ=None, stdin=b\'\'):\n  stdout = io.BytesIO()\n  stdin  = io.BytesIO(stdin)\n  if environ is None:\n    environ = {}\n\n  # Header-Name -> HEADER_NAME\n  _ = {}\n  for k,v in environ.items():\n    k = k.replace(\'-\', \'_\').upper()\n    _[k] = v\n  environ = _\n\n  response = HTTPResponse(stdout=stdout)\n  environ.setdefault(\'SERVER_NAME\',    \'foo\')\n  environ.setdefault(\'SERVER_PORT\',    \'80\')\n  request  = HTTPRequest(stdin, environ, response)\n  # process stdin data\n  request.processInputs()\n  return request\n\n# generate makerequest-like function for http method\ndef request_function(method_name):\n  method_name = method_name.upper()\n  def method_func(environ=None, stdin=b\'\'):\n    if environ is None:\n      environ = {}\n    environ.setdefault(\'REQUEST_METHOD\', method_name)\n    return makerequest(environ, stdin)\n  method_func.func_name = method_name\n  return method_func\n\ndef checkBTreeData(tree, length, read_offset, read_length, data_, keys=None):\n  #print(list(tree._tree.items()))\n  tree_length = len(tree)\n  tree_data = tree.read(read_offset, read_length)\n  tree_iterator_data = b\'\'.join(tree.iterate(read_offset, read_length))\n  assert tree_length == length, tree_length\n  assert tree_data == data_, repr(tree_data)\n  assert tree_iterator_data == data_, repr(tree_iterator_data)\n  if keys is not None:\n    tree_keys = list(tree._tree.keys())\n    assert tree_keys == keys, tree_keys\n\n\n# requests\nget = request_function(\'GET\')\nput = request_function(\'PUT\')\n\nif IS_ZOPE2: # BBB Zope2\n  # FIXME Zope translates 308 to 500\n  # https://github.com/zopefoundation/Zope/blob/2.13/src/ZPublisher/HTTPResponse.py#L223\n  # https://github.com/zopefoundation/Zope/blob/2.13/src/ZPublisher/HTTPResponse.py#L64\n  R308 = 500\nelse:\n  R308 = 308\n\n\nclass TestBTreeData(ERP5TypeTestCase):\n  \"\"\"Tests for ERP5.Document.BTreeData\"\"\"\n  def getBusinessTemplateList(self):\n    \"\"\"bt5 required to run this tests\"\"\"\n    return (\'erp5_big_file\',\n               # test runner does not automatically install bt5 dependencies -\n               # - next erp5_big_file dependencies are specified manually\n               \'erp5_dms\',\n                 \'erp5_web\',\n                 \'erp5_ingestion\',\n                 \'erp5_base\',\n               )[::-1]	# NOTE install order is important\n\n\n  def testBTreeData_checkData(self):\n\n    PersistentBytes.__repr__ = lambda self: repr(self.value)\n\n    data = BTreeData()\n    data.write(b\'\', 10)\n    checkBTreeData(data, 10, 0, 20, b\'\\x00\' * 10, [10])\n\n    data.truncate(0)\n    checkBTreeData(data, 0, 0, 20, b\'\', [])\n\n    data.write(b\'a\', 5)\n    checkBTreeData(data, 6, 4, 3, b\'\\x00a\', [5])\n\n    data.write(b\'b\', 5)\n    checkBTreeData(data, 6, 4, 3, b\'\\x00b\', [5])\n\n    data.write(b\'0123456\', 0)\n    checkBTreeData(data, 7, 0, 10, b\'0123456\', [0, 5])\n    checkBTreeData(data, 7, 0, 1, b\'0\')\n    checkBTreeData(data, 7, 1, 1, b\'1\')\n    checkBTreeData(data, 7, 2, 1, b\'2\')\n    checkBTreeData(data, 7, 5, 1, b\'5\')\n    checkBTreeData(data, 7, 6, 1, b\'6\')\n\n    # Unaligned write, spilling in next existing chunk\n    data.write(b\'XY\', 4)\n    checkBTreeData(data, 7, 0, 10, b\'0123XY6\', [0, 5])\n    # Unaligned write, inside existing chunk\n    data.write(b\'VW\', 1)\n    checkBTreeData(data, 7, 0, 10, b\'0VW3XY6\', [0, 5])\n    # Empty write inside existing chunk\n    data.write(b\'\', 4)\n    checkBTreeData(data, 7, 0, 10, b\'0VW3XY6\', [0, 5])\n    # Aligned write\n    data.write(b\'Z\', 5)\n    checkBTreeData(data, 7, 0, 10, b\'0VW3XZ6\', [0, 5])\n\n    data.write(b\'a\', 10)\n    data.write(b\'8\', 8)\n    checkBTreeData(data, 11, 0, 10, b\'0VW3XZ6\\x008\\x00\', [0, 5, 8, 10])\n    checkBTreeData(data, 11, 7, 10, b\'\\x008\\x00a\')\n\n    data.write(b\'ABCDE\', 6)\n    checkBTreeData(data, 11, 0, 11, b\'0VW3XZABCDE\', [0, 5, 8, 10])\n\n    data.truncate(7)\n    checkBTreeData(data, 7, 0, 7, b\'0VW3XZA\', [0, 5])\n    data.truncate(5)\n    checkBTreeData(data, 5, 0, 5, b\'0VW3X\', [0])\n    data.truncate(3)\n    checkBTreeData(data, 3, 0, 3, b\'0VW\', [0])\n    data.truncate(0)\n    checkBTreeData(data, 0, 0, 0, b\'\', [])\n\n    data.truncate(10)\n    checkBTreeData(data, 10, 0, 10, b\'\\x00\' * 10, [10])\n    data.write(b\'a\', 15)\n    checkBTreeData(data, 16, 0, 16, b\'\\x00\' * 15 + b\'a\', [15])\n    data.write(b\'bc\', 9)\n    checkBTreeData(data, 16, 0, 16, b\'\\x00\' * 9 + b\'bc\' + b\'\\x00\' * 4 + b\'a\', [9, 15])\n\n    data = BTreeData(chunk_size=4, max_chunk_size=10)\n    data.write(b\'01\', 0)\n    checkBTreeData(data, 2, 0, 10, b\'01\', [0])\n    data.write(b\'23\', 2)\n    checkBTreeData(data, 4, 0, 10, b\'0123\', [0])\n    data.write(b\'AB4\', 2)\n    checkBTreeData(data, 5, 0, 10, b\'01AB4\', [0])\n    data.write(b\'C56\', 4)\n    checkBTreeData(data, 7, 0, 10, b\'01ABC56\', [0])\n    data.write(b\'7\', 7)\n    checkBTreeData(data, 8, 0, 10, b\'01ABC567\', [0, 7])\n    data.write(b\'8\', 8)\n    checkBTreeData(data, 9, 0, 10, b\'01ABC5678\', [0, 7])\n    data.write(b\'C\', 12)\n    checkBTreeData(data, 13, 0, 13, b\'01ABC5678\\x00\\x00\\x00C\', [0, 7, 12])\n    data.write(b\'9ABcDEFG\', 9)\n    checkBTreeData(data, 17, 0, 17, b\'01ABC56789ABcDEFG\', [0, 7, 12])\n    for _ in data.defragment():\n      pass\n    checkBTreeData(data, 17, 0, 17, b\'01ABC56789ABcDEFG\', [0, 10])\n    data.write(b\'HIJKL\', len(data))\n    checkBTreeData(data, 22, 0, 22, b\'01ABC56789ABcDEFGHIJKL\', [0, 10, 17])\n    for _ in data.defragment():\n      pass\n    checkBTreeData(data, 22, 0, 22, b\'01ABC56789ABcDEFGHIJKL\', [0, 10, 20])\n    data.write(b\'NOPQRSTUVWXYZ\', 23)\n    checkBTreeData(data, 36, 0, 36, b\'01ABC56789ABcDEFGHIJKL\\x00NOPQRSTUVWXYZ\', [0, 10, 20, 23, 33])\n    for _ in data.defragment():\n      pass\n    checkBTreeData(data, 36, 0, 36, b\'01ABC56789ABcDEFGHIJKL\\x00NOPQRSTUVWXYZ\', [0, 10, 20, 23, 33])\n\n    data = BTreeData(max_chunk_size=10)\n    for x in range(255):\n      data.write(b\'%02x\' % x, x * 2)\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [x * 2 for x in range(255)])\n    defragment_generator = data.defragment(batch_size=2)\n    next(defragment_generator)\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [0] + [x * 2 for x in range(2, 255)])\n    opaque = next(defragment_generator)\n    defragment_generator.close()\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [0] + [x * 2 for x in range(4, 255)])\n    defragment_generator = data.defragment(batch_size=2, resume_at=opaque)\n    next(defragment_generator)\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [0] + [x * 2 for x in range(5, 255)])\n    defragment_generator.send(10)\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [0, 10, 20] + [x * 2 for x in range(13, 255)])\n    next(defragment_generator)\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [0, 10, 20, 30, 40] + [x * 2 for x in range(23, 255)])\n    for _ in defragment_generator:\n      pass\n    checkBTreeData(data, 510, 0, 10, b\'0001020304\', [x * 10 for x in range(51)])\n\nclass TestBigFile(ERP5TypeTestCase):\n\n  # check that object (document) method corresponding to request returns\n  # result, with expected response body, status and headers\n  def checkRequest(self, document, request, kw, result, body, status, header_dict):\n    # request -> method to call\n    method_name = request[\'REQUEST_METHOD\']\n    if method_name == \'GET\':\n      method_name = \'index_html\'\n    method = getattr(document, method_name)\n\n    ret = method (request, request.RESPONSE, **kw)\n    # like in ZPublisher - returned RESPONSE means empty\n    if ret is request.RESPONSE:\n      ret = b\'\'\n    self.assertEqual(ret,       result)\n    self.assertEqual(status,    request.RESPONSE.getStatus())\n    for h,v in header_dict.items():\n      rv = request.RESPONSE.getHeader(h)\n      self.assertEqual(v, rv, \'%s: %r != %r\' % (h, v, rv))\n\n    # force response flush to its stdout\n    request.RESPONSE.write(b\'\')\n    # body and headers are delimited by empty line (RFC 2616, 4.1)\n    response_body = request.RESPONSE.stdout.getvalue().split(b\'\\r\\n\\r\\n\', 1)[1]\n    self.assertEqual(body, response_body)\n\n\n  # basic tests for working with BigFile via its public interface\n  def testBigFile_01_Basic(self):\n    big_file_module = self.getPortal().big_file_module\n    f = big_file_module.newContent(portal_type=\'Big File\')\n    check = lambda *args: self.checkRequest(f, *args)\n\n\n    # after creation file is empty and get(0-0) returns 416\n    self.assertEqual(f.getSize(), 0)\n    self.assertEqual(f.getData(), b\'\')\n\n                                             #  result body status headers\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'\', 200, {\'Content-Length\': \'0\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',R308, {                                  \'Range\': \'bytes 0--1\'})  # XXX 0--1 ok?\n    check(get({        \'Range\': \'bytes=0-0\'}),{},   b\'\', b\'\', 416, {\'Content-Length\': \'0\',    \'Content-Range\': \'bytes */0\'})\n\n\n    # append empty chunk - the same\n    f._appendData(b\'\')\n    self.assertEqual(f.getSize(), 0)\n    self.assertEqual(f.getData(), b\'\')\n\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'\', 200, {\'Content-Length\': \'0\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',R308, {                                  \'Range\': \'bytes 0--1\'})  # XXX 0--1 ok?\n    check(get({        \'Range\': \'bytes=0-0\'}),{},   b\'\', b\'\', 416, {                          \'Content-Range\': \'bytes */0\'})\n\n\n    # append 1 byte - file should grow up and get(0-0) returns 206\n    f._appendData(b\'x\')\n    self.assertEqual(f.getSize(), 1)\n    self.assertEqual(f.getData(), b\'x\')\n\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'x\', 200, {\'Content-Length\': \'1\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\', R308, {                                \'Range\': \'bytes 0-0\'})\n    check(get({        \'Range\': \'bytes=0-0\'}),{},   b\'\', b\'x\', 206, {\'Content-Length\': \'1\',  \'Content-Range\': \'bytes 0-0/1\'})\n\n\n    # append another 2 bytes and try to get whole file and partial contents\n    f._appendData(b\'yz\')\n    self.assertEqual(f.getSize(), 3)\n    self.assertEqual(f.getData(), b\'xyz\')\n\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'xyz\',  200, {\'Content-Length\': \'3\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',    R308, {                                \'Range\': \'bytes 0-2\'})\n    check(get({        \'Range\': \'bytes=0-0\'}),{},   b\'\', b\'x\'  ,  206, {\'Content-Length\': \'1\',  \'Content-Range\': \'bytes 0-0/3\'})\n    check(get({        \'Range\': \'bytes=1-1\'}),{},   b\'\',  b\'y\' ,  206, {\'Content-Length\': \'1\',  \'Content-Range\': \'bytes 1-1/3\'})\n    check(get({        \'Range\': \'bytes=2-2\'}),{},   b\'\',   b\'z\',  206, {\'Content-Length\': \'1\',  \'Content-Range\': \'bytes 2-2/3\'})\n    check(get({        \'Range\': \'bytes=0-1\'}),{},   b\'\', b\'xy\' ,  206, {\'Content-Length\': \'2\',  \'Content-Range\': \'bytes 0-1/3\'})\n    check(get({        \'Range\': \'bytes=1-2\'}),{},   b\'\',  b\'yz\',  206, {\'Content-Length\': \'2\',  \'Content-Range\': \'bytes 1-2/3\'})\n    check(get({        \'Range\': \'bytes=0-2\'}),{},   b\'\', b\'xyz\',  206, {\'Content-Length\': \'3\',  \'Content-Range\': \'bytes 0-2/3\'})\n\n    # append via PUT with range\n    check(put({\'Content-Range\': \'bytes 3-4/5\', \'Content-Length\': \'2\'}, b\'01\'),{},  b\'\', b\'\', 204, {})\n    self.assertEqual(f.getSize(), 5)\n    self.assertEqual(f.getData(), b\'xyz01\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'xyz01\',200, {\'Content-Length\': \'5\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',    R308, {                                \'Range\': \'bytes 0-4\'})\n    check(get({        \'Range\': \'bytes=0-4\'}),{},   b\'\', b\'xyz01\',206, {\'Content-Length\': \'5\',  \'Content-Range\': \'bytes 0-4/5\'})\n    check(get({        \'Range\': \'bytes=1-3\'}),{},   b\'\',  b\'yz0\' ,206, {\'Content-Length\': \'3\',  \'Content-Range\': \'bytes 1-3/5\'})\n    check(get({        \'Range\': \'bytes=1-2\'}),{},   b\'\',  b\'yz\'  ,206, {\'Content-Length\': \'2\',  \'Content-Range\': \'bytes 1-2/5\'})\n    check(get({        \'Range\': \'bytes=2-2\'}),{},   b\'\',   b\'z\'  ,206, {\'Content-Length\': \'1\',  \'Content-Range\': \'bytes 2-2/5\'})\n\n    # replace whole content via PUT without range\n    # (and we won\'t exercise GET with range routinely further)\n    check(put({\'Content-Length\': \'3\'}, b\'abc\'),{},  b\'\', b\'\', 204, {})\n    self.assertEqual(f.getSize(), 3)\n    self.assertEqual(f.getData(), b\'abc\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'abc\',  200, {\'Content-Length\': \'3\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',    R308, {                                \'Range\': \'bytes 0-2\'})\n\n    # append via PUT with range (again)\n    check(put({\'Content-Range\': \'bytes 3-7/8\', \'Content-Length\': \'5\'}, b\'defgh\'),{},  b\'\', b\'\', 204, {})\n    self.assertEqual(f.getSize(), 8)\n    self.assertEqual(f.getData(), b\'abcdefgh\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'abcdefgh\', 200, {\'Content-Length\': \'8\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',        R308, {                            \'Range\': \'bytes 0-7\'})\n\n    # append via ._appendData()  (again)\n    f._appendData(b\'ij\')\n    self.assertEqual(f.getSize(), 10)\n    self.assertEqual(f.getData(), b\'abcdefghij\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'abcdefghij\', 200, {\'Content-Length\': \'10\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',          R308, {                          \'Range\': \'bytes 0-9\'})\n\n    # make sure PUT with incorrect/non-append range is rejected\n    check(put({\'Content-Range\': \'bytes 10-10/10\', \'Content-Length\': \'1\'}, b\'k\'),{}, b\'\', b\'\', 400, {\'X-Explanation\': \'Total size unexpected\'})\n    self.assertEqual(f.getData(), b\'abcdefghij\')\n    check(put({\'Content-Range\': \'bytes 10-10/11\', \'Content-Length\': \'2\'}, b\'k\'),{}, b\'\', b\'\', 400, {\'X-Explanation\': \'Content length unexpected\'})\n    self.assertEqual(f.getData(), b\'abcdefghij\')\n    check(put({\'Content-Range\': \'bytes 8-8/10\',   \'Content-Length\': \'1\'}, b\'?\'),{}, b\'\', b\'\', 400, {\'X-Explanation\': \'Can only append data\'})\n    check(put({\'Content-Range\': \'bytes 9-9/10\',   \'Content-Length\': \'1\'}, b\'?\'),{}, b\'\', b\'\', 400, {\'X-Explanation\': \'Can only append data\'})\n    check(put({\'Content-Range\': \'bytes 9-10/11\',  \'Content-Length\': \'2\'},b\'??\'),{}, b\'\', b\'\', 400, {\'X-Explanation\': \'Can only append data\'})\n    check(put({\'Content-Range\': \'bytes 11-11/12\', \'Content-Length\': \'1\'}, b\'?\'),{}, b\'\', b\'\', 400, {\'X-Explanation\': \'Can only append data\'})\n\n    # TODO test \'If-Range\' with GET\n    # TODO test multiple ranges in \'Range\' with GET\n\n\n  # test BigFile\'s .data property can be of several types and is handled\n  # properly and we can still get data and migrate to BTreeData transparently\n  # (called from under testBigFile_02_DataVarious driver)\n  def _testBigFile_02_DataVarious(self):\n    # BigFile\'s .data can be:\n    # bytes       - because data comes from Data property sheet and default value is b\'\'\n    # None      - because it can be changed\n    # BTreeData - because it is scalable way to work with large content\n    #\n    # bytes can be possibly non-empty because we could want to transparently\n    # migrate plain File documents to BigFiles.\n    #\n    # make sure BigFile correctly works in all those situations.\n\n    big_file_module = self.getPortal().big_file_module\n    f = big_file_module.newContent(portal_type=\'Big File\')\n    check = lambda *args: self.checkRequest(f, *args)\n\n    # after creation .data is b\'\'  (as per default from Data property sheet)\n    _ = f._baseGetData()\n    self.assertIsInstance(_, bytes)\n    self.assertEqual(_, b\'\')\n\n    # make sure we can get empty content through all ways\n    # (already covered in testBigFile_01_Basic, but still)\n    self.assertEqual(f.getSize(), 0)\n    self.assertEqual(f.getData(), b\'\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'\', 200, {\'Content-Length\': \'0\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',R308, {                                \'Range\': \'bytes 0--1\'})  # XXX 0--1 ok?\n    check(get({        \'Range\': \'bytes=0-0\'}),{},   b\'\', b\'\', 416, {\'Content-Length\': \'0\',  \'Content-Range\': \'bytes */0\'})\n\n\n    # set .data to non-empty str and make sure we can get content through all ways\n    f._baseSetData(b\'abc\')\n    _ = f._baseGetData()\n    self.assertIsInstance(_, bytes)\n    self.assertEqual(_, b\'abc\')\n    self.assertEqual(f.getSize(), 3)\n    self.assertEqual(f.getData(), b\'abc\')\n    check(get(), {\'format\': \'raw\'},                 b\'abc\', b\'\',    200, {\'Content-Length\': \'3\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\'   , b\'\',   R308, {                                \'Range\': \'bytes 0-2\'})\n    check(get({        \'Range\': \'bytes=0-2\'}),{},   b\'\'   , b\'abc\', 206, {\'Content-Length\': \'3\',  \'Content-Range\': \'bytes 0-2/3\'})\n\n    # and .data should remain str after access (though later this could be\n    # changed to transparently migrate to BTreeData)\n    _ = f._baseGetData()\n    self.assertIsInstance(_, bytes)\n    self.assertEqual(_, b\'abc\')\n\n\n    # on append .data should migrate to BTreeData\n    f._appendData(b\'d\')\n    _ = f._baseGetData()\n    self.assertIsInstance(_, BTreeData)\n    self.assertEqual(f.getSize(), 4)\n    self.assertEqual(f.getData(), b\'abcd\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'abcd\', 200, {\'Content-Length\': \'4\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',    R308, {                                \'Range\': \'bytes 0-3\'})\n    check(get({        \'Range\': \'bytes=0-3\'}),{},   b\'\', b\'abcd\', 206, {\'Content-Length\': \'4\',  \'Content-Range\': \'bytes 0-3/4\'})\n\n\n\n    # change .data to None and make sure we can still get empty content\n    # NOTE additionally to ._baseSetData(None), ._setData(None) also sets\n    #      .size=0 which is needed for correct BigFile bases operation.\n    #\n    #      see ERP5.Document.File._setSize() for details.\n    f._setData(None)\n    # NOTE still b\'\' because it is default value specified in Data property\n    #      sheet for .data field\n    _ = f._baseGetData()\n    self.assertIsInstance(_, bytes)\n    self.assertEqual(_, b\'\')\n    # but we can change property sheet default on the fly\n    # XXX ( only for this particular getter _baseGetData -\n    #       - because property type information is not stored in one place,\n    #       but is copied on getter/setter initialization - see Getter/Setter\n    #       in ERP5Type.Accessor.Base )\n    # NOTE this change is automatically reverted back in calling helper\n    self.assertIsInstance(f._baseGetData._default, bytes)\n    self.assertEqual(f._baseGetData._default, b\'\')\n    f._baseGetData.__func__._default = None  # NOTE not possible to do on just f._baseGetData\n    self.assertIs(f._baseGetData._default, None)\n    self.assertIs(f._baseGetData(), None)   # <- oops\n\n    self.assertEqual(f.getSize(), 0)\n    self.assertIs   (f.getData(), None)\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'\', 200, {\'Content-Length\': \'0\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',R308, {                                \'Range\': \'bytes 0--1\'})  # XXX 0--1 ok?\n    check(get({        \'Range\': \'bytes=0-0\'}),{},   b\'\', b\'\', 416, {\'Content-Length\': \'0\',  \'Content-Range\': \'bytes */0\'})\n\n\n    # on append .data should become BTreeData\n    f._appendData(b\'x\')\n    _ = f._baseGetData()\n    self.assertIsInstance(_, BTreeData)\n    self.assertEqual(f.getSize(), 1)\n    self.assertEqual(f.getData(), b\'x\')\n    check(get(), {\'format\': \'raw\'},                 b\'\', b\'x\',    200, {\'Content-Length\': \'1\'})\n    check(put({\'Content-Range\': \'bytes */*\'}),{},   b\'\', b\'\',    R308, {                                \'Range\': \'bytes 0-0\'})\n    check(get({        \'Range\': \'bytes=0-3\'}),{},   b\'\', b\'x\',    206, {\'Content-Length\': \'1\',  \'Content-Range\': \'bytes 0-0/1\'})\n\n\n\n  # helper to call _testBigFile_02_DataVarious() and restore .data._default\n  def testBigFile_02_DataVarious(self):\n    big_file_module = self.getPortal().big_file_module\n    f = big_file_module.newContent(portal_type=\'Big File\')\n\n    # Data property sheet specifies .data default to b\'\'\n    _ = f._baseGetData()\n    self.assertIsInstance(_, bytes)\n    self.assertEqual(_, b\'\')\n\n    # NOTE obtaining getter is not possible via BigFile._baseGetData\n    g = f._baseGetData.__func__\n    self.assertIsInstance(g._default, bytes)\n    self.assertEqual(g._default, b\'\')\n\n    try:\n      self._testBigFile_02_DataVarious()\n\n    # restore ._baseGetData._default and make sure restoration really worked\n    finally:\n      g._default = b\'\'\n      f._baseSetData(None)    # so that we are sure getter returns class defaults\n      _ = f._baseGetData()\n      self.assertIsInstance(_, bytes)\n      self.assertEqual(_, b\'\')\n\n\n\n  # TODO write big data to file and ensure it still works\n  # TODO test streaming works in chunks'),(16354,'document.erp5.BigFile BigFile # -*- coding: utf-8 -*-\n##############################################################################\n#\n# Copyright (c) 2002 Zope Foundation and Contributors.\n#               2012 Nexedi SA and Contributors. All Rights Reserved.\n#                    Romain Courteaud <romain@nexedi.com>\n#\n# This software is subject to the provisions of the Zope Public License,\n# Version 2.1 (ZPL).  A copy of the ZPL should accompany this distribution.\n# THIS SOFTWARE IS PROVIDED \"AS IS\" AND ANY AND ALL EXPRESS OR IMPLIED\n# WARRANTIES ARE DISCLAIMED, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED\n# WARRANTIES OF TITLE, MERCHANTABILITY, AGAINST INFRINGEMENT, AND FITNESS\n# FOR A PARTICULAR PURPOSE\n#\n##############################################################################\n\nfrom AccessControl import ClassSecurityInfo\nfrom Products.ERP5Type import Permissions, PropertySheet\nfrom Products.ERP5Type.Base import removeIContentishInterface\nfrom erp5.component.document.File import File, _MARKER\nfrom erp5.component.module.BTreeData import BTreeData\nfrom ZPublisher.HTTPRequest import FileUpload\nfrom ZPublisher import HTTPRangeSupport\nfrom zope.datetime import rfc1123_date\nfrom Products.CMFCore.utils import _setCacheHeaders, _ViewEmulator\nfrom DateTime import DateTime\nimport re\nimport io\nimport six\n\nif six.PY3:\n  long_or_int = int\n  from email.generator import _make_boundary as choose_boundary\nelse:\n  long_or_int = long  # pylint:disable=undefined-variable\n  from mimetools import choose_boundary  # pylint:disable=import-error\n\nclass BigFile(File):\n  \"\"\"\n  Support storing huge file.\n  No convertion is allowed for now.\n\n\n  NOTE BigFile maintains the following invariant:\n\n    data property is either\n\n      - BTreeData instance,  or\n      - bytes(*),  or\n      - None.\n\n    (*) bytes has to be supported because b\'\' is a default value for `data` field\n        from Data property sheet.\n\n        Even more - for\n\n            a) compatibility reasons, and\n            b) desire to support automatic migration of File-based documents\n               from document_module to BigFiles\n\n        non-empty bytes for data also have to be supported.\n\n        XXX(kirr) I\'m not sure supporting non-empty str is a good idea (it\n            would be simpler if .data could be either BTreeData or \"empty\"),\n            but neither I\'m experienced enough in erp5 nor know what are\n            appropriate compatibility requirements.\n\n            We discussed with Romain and settled on \"None or str or BTreeData\"\n            invariant for now.\n        notes: for python3 port \"str\" becomes \"bytes\", but kirr message was not modified.\n\n  \"\"\"\n\n  meta_type = \'ERP5 Big File\'\n  portal_type = \'Big File\'\n\n  # Declarative security\n  security = ClassSecurityInfo()\n  security.declareObjectProtected(Permissions.AccessContentsInformation)\n\n  # Default Properties\n  property_sheets = ( PropertySheet.Base\n                    , PropertySheet.XMLObject\n                    , PropertySheet.CategoryCore\n                    , PropertySheet.DublinCore\n                    , PropertySheet.Version\n                    , PropertySheet.Reference\n                    , PropertySheet.Document\n                    , PropertySheet.Data\n                    , PropertySheet.ExternalDocument\n                    , PropertySheet.Url\n                    , PropertySheet.Periodicity\n    )\n\n  # OFS.File has an overloaded __str__ that returns the file content\n  __str__ = object.__str__\n\n  security.declareProtected(Permissions.AccessContentsInformation,\n                            \'getData\')\n  def getData(self, default=None):\n    \"\"\"Read the full btree\n    \"\"\"\n    btree = self._baseGetData()\n    if isinstance(btree, BTreeData):\n      return btree.read(0, len(btree))\n    else:\n      return btree\n\n  security.declareProtected(Permissions.ModifyPortalContent, \'updateContentMd5\')\n  def updateContentMd5(self):\n    \"\"\"Update md5 checksum from the original file\n    \"\"\"\n    self._setContentMd5(None)\n\n  def _read_data(self, file, data=None, serialize=True): # pylint: disable=redefined-builtin,arguments-differ\n\n    # We might need to make this value configurable. It is important to\n    # consider the max quantity of object used in the cache. With a default\n    # cache of 5000 objects, and with n = 64KB, this makes using about 330 MB\n    # of memory.\n    n=1 << 16\n\n    if isinstance(file, bytes):\n      # Big string: cut it into smaller chunks\n      file = io.BytesIO(file)\n\n    if isinstance(file, FileUpload) and not file:\n      raise ValueError(\'File not specified\')\n\n    seek=file.seek\n    read=file.read\n\n    seek(0,2)\n    end=file.tell()\n\n    if data is None:\n      btree = BTreeData()\n    elif isinstance(data, bytes):\n      # we\'ll want to append content to this file -\n      # - automatically convert bytes (empty or not) to BTreeData\n      btree = BTreeData()\n      btree.write(data, 0)\n    else:\n      btree = data\n    seek(0)\n    pos = file.tell()\n    offset = len(btree)\n\n    while pos < end:\n      next_ = pos + n\n      if next_ > end:\n        next_ = end\n\n      btree.write(read(next_-pos), offset+pos)\n      pos = file.tell()\n\n    if serialize:\n      self.serialize()\n    return btree, len(btree)\n\n  def _data_mtime(self):\n    \"\"\"get .data mtime if present and fallback to self._p_mtime\"\"\"\n    # there is no data._p_mtime when data is None or str.\n    # so try and fallback to self._p_mtime\n    data = self._baseGetData()\n    mtime = getattr(data, \'_p_mtime\', self._p_mtime)\n    return mtime\n\n  def _range_request_handler(self, REQUEST, RESPONSE):\n    # HTTP Range header handling: return True if we\'ve served a range\n    # chunk out of our data.\n    range_ = REQUEST.get_header(\'Range\', None)\n    request_range = REQUEST.get_header(\'Request-Range\', None)\n    if request_range is not None:\n      # Netscape 2 through 4 and MSIE 3 implement a draft version\n      # Later on, we need to serve a different mime-type as well.\n      range_ = request_range\n    if_range = REQUEST.get_header(\'If-Range\', None)\n    if range_ is not None:\n      ranges = HTTPRangeSupport.parseRange(range_)\n\n      data = self._baseGetData()\n\n      if if_range is not None:\n        # Only send ranges if the data isn\'t modified, otherwise send\n        # the whole object. Support both ETags and Last-Modified dates!\n        if len(if_range) > 1 and if_range[:2] == \'ts\':\n          # ETag:\n          if if_range != self.http__etag():\n            # Modified, so send a normal response. We delete\n            # the ranges, which causes us to skip to the 200\n            # response.\n            ranges = None\n        else:\n          # Date\n          date = if_range.split( \';\')[0]\n          try: mod_since=long_or_int(DateTime(date).timeTime())\n          except Exception: mod_since=None\n          if mod_since is not None:\n            last_mod = self._data_mtime()\n            if last_mod is None:\n              last_mod = 0\n            last_mod = long_or_int(last_mod)\n            if last_mod > mod_since:\n              # Modified, so send a normal response. We delete\n              # the ranges, which causes us to skip to the 200\n              # response.\n              ranges = None\n\n      if ranges:\n        # Search for satisfiable ranges.\n        satisfiable = 0\n        for start, end in ranges:\n          if start < self.getSize():\n            satisfiable = 1\n            break\n\n        if not satisfiable:\n          RESPONSE.setHeader(\'Content-Range\',\n              \'bytes */%d\' % self.getSize())\n          RESPONSE.setHeader(\'Accept-Ranges\', \'bytes\')\n          RESPONSE.setHeader(\'Last-Modified\', rfc1123_date(self._data_mtime()))\n          RESPONSE.setHeader(\'Content-Type\', self.content_type)\n          RESPONSE.setHeader(\'Content-Length\', self.getSize())\n          RESPONSE.setStatus(416)\n          return True\n\n        ranges = HTTPRangeSupport.expandRanges(ranges, self.getSize())\n\n        if len(ranges) == 1:\n          # Easy case, set extra header and return partial set.\n          start, end = ranges[0]\n          size = end - start\n\n          RESPONSE.setHeader(\'Last-Modified\', rfc1123_date(self._data_mtime()))\n          RESPONSE.setHeader(\'Content-Type\', self.content_type)\n          RESPONSE.setHeader(\'Content-Length\', size)\n          RESPONSE.setHeader(\'Accept-Ranges\', \'bytes\')\n          RESPONSE.setHeader(\'Content-Range\',\n              \'bytes %d-%d/%d\' % (start, end - 1, self.getSize()))\n          RESPONSE.setStatus(206) # Partial content\n\n          # NOTE data cannot be None here (if it is - ranges are not satisfiable)\n          if isinstance(data, bytes):\n            RESPONSE.write(data[start:end])\n            return True\n          for chunk in data.iterate(start, end-start):\n            RESPONSE.write(chunk)\n          return True\n\n        else:\n          boundary = choose_boundary()\n\n          # Calculate the content length\n          size = (8 + len(boundary) + # End marker length\n              len(ranges) * (         # Constant lenght per set\n                  49 + len(boundary) + len(self.content_type) +\n                  len(\'%d\' % self.getSize())))\n          for start, end in ranges:\n            # Variable length per set\n            size = (size + len(\'%d%d\' % (start, end - 1)) +\n                end - start)\n\n          data = self._baseGetData()\n\n          # Some clients implement an earlier draft of the spec, they\n          # will only accept x-byteranges.\n          draftprefix = (request_range is not None) and \'x-\' or \'\'\n\n          RESPONSE.setHeader(\'Content-Length\', size)\n          RESPONSE.setHeader(\'Accept-Ranges\', \'bytes\')\n          RESPONSE.setHeader(\'Last-Modified\', rfc1123_date(self._data_mtime()))\n          RESPONSE.setHeader(\'Content-Type\',\n              \'multipart/%sbyteranges; boundary=%s\' % (\n                  draftprefix, boundary))\n          RESPONSE.setStatus(206) # Partial content\n\n          for start, end in ranges:\n            RESPONSE.write(b\'\\r\\n--%s\\r\\n\' % boundary)\n            RESPONSE.write(b\'Content-Type: %s\\r\\n\' %\n                self.content_type)\n            RESPONSE.write(\n                b\'Content-Range: bytes %d-%d/%d\\r\\n\\r\\n\' % (\n                    start, end - 1, self.getSize()))\n\n            # NOTE data cannot be None here (if it is - ranges are not satisfiable)\n            if isinstance(data, bytes):\n              RESPONSE.write(data[start:end])\n\n            else:\n              for chunk in data.iterate(start, end-start):\n                RESPONSE.write(chunk)\n\n          RESPONSE.write(b\'\\r\\n--%s--\\r\\n\' % boundary)\n          return True\n\n  security.declareProtected(Permissions.View, \'index_html\')\n  def index_html(self, REQUEST, RESPONSE, format=_MARKER, inline=_MARKER, **kw): # pylint: disable=redefined-builtin\n    \"\"\"\n      Support streaming\n    \"\"\"\n    if self._range_request_handler(REQUEST, RESPONSE):\n      # we served a chunk of content in response to a range request.\n      return b\'\'\n\n    web_cache_kw = kw.copy()\n    if format is not _MARKER:\n      web_cache_kw[\'format\'] = format\n    _setCacheHeaders(_ViewEmulator().__of__(self), web_cache_kw)\n\n    if format is _MARKER and not kw:\n      # conversion parameters is mandatory to download the converted content.\n      # By default allways return view action.\n      # for all WevDAV access return raw content.\n      return self.view()\n\n    if format is _MARKER:\n      format = None\n\n    data = self._baseGetData()\n    mime = self.getContentType()\n\n    RESPONSE.setHeader(\'Content-Length\', data is not None and  len(data)  or  0)\n    RESPONSE.setHeader(\'Content-Type\', mime)\n    if inline is _MARKER:\n      # by default, use inline for text and image formats\n      inline = False\n    if not inline:\n      # need to return it as attachment\n      filename = self.getStandardFilename(format=format) # pylint: disable=unused-variable\n      RESPONSE.setHeader(\'Accept-Ranges\', \'bytes\')\n\n\n    if data is None:\n      return b\'\'\n    if isinstance(data, bytes):\n      RESPONSE.setBase(None)\n      return data\n    for chunk in data.iterate():\n      RESPONSE.write(chunk)\n    return b\'\'\n\n  security.declareProtected(Permissions.ModifyPortalContent,\'PUT\')\n  def PUT(self, REQUEST, RESPONSE):\n    \"\"\"Handle HTTP PUT requests\"\"\"\n    self.dav__init(REQUEST, RESPONSE)\n    self.dav__simpleifhandler(REQUEST, RESPONSE, refresh=1)\n\n    type_=REQUEST.get_header(\'content-type\', None)\n\n    file_=REQUEST[\'BODYFILE\']\n\n    content_range = REQUEST.get_header(\'Content-Range\', None)\n    if content_range is None:\n      # truncate the file\n      self._baseSetData(None)\n    else:\n      current_size = int(self.getSize())\n      query_range = re.compile(r\'bytes \\*/\\*\')\n      append_range = re.compile(r\'bytes (?P<first_byte>[0-9]+)-\' \\\n                                 \'(?P<last_byte>[0-9]+)/\' \\\n                                 \'(?P<total_content_length>[0-9]+)\')\n      if query_range.match(content_range):\n        RESPONSE.setHeader(\'X-Explanation\', \'Resume incomplete\')\n        RESPONSE.setHeader(\'Range\', \'bytes 0-%s\' % (current_size-1))\n        RESPONSE.setStatus(308)\n        return RESPONSE\n\n      if append_range.match(content_range):\n\n        result_dict = append_range.search(content_range).groupdict()\n        first_byte = int(result_dict[\'first_byte\'])\n        last_byte = int(result_dict[\'last_byte\'])\n        total_content_length = int(result_dict[\'total_content_length\'])\n        content_length= int(REQUEST.get_header(\'Content-Length\', \'0\'))\n\n        if (first_byte != current_size):\n          RESPONSE.setHeader(\'X-Explanation\', \'Can only append data\')\n          RESPONSE.setStatus(400)\n          return RESPONSE\n        elif (last_byte+1 != total_content_length):\n          RESPONSE.setHeader(\'X-Explanation\', \'Total size unexpected\')\n          RESPONSE.setStatus(400)\n          return RESPONSE\n        elif (last_byte+1-first_byte != content_length):\n          RESPONSE.setHeader(\'X-Explanation\', \'Content length unexpected\')\n          RESPONSE.setStatus(400)\n          return RESPONSE\n\n      else:\n        RESPONSE.setHeader(\'X-Explanation\', \'Can not parse range\')\n        RESPONSE.setStatus(400) # Partial content\n        return RESPONSE\n\n    self._appendData(file_, content_type=type_)\n\n    RESPONSE.setStatus(204)\n    return RESPONSE\n\n  security.declareProtected(Permissions.ModifyPortalContent,\'appendData\')\n  def appendData(self, data_chunk, content_type=None):\n    \"\"\"\n    append data chunk to the end of the file, available in restricted environment.\n    \"\"\"\n    self._appendData(data_chunk, content_type)\n\n  def _appendData(self, data_chunk, content_type=None):\n    \"\"\"append data chunk to the end of the file\n\n       NOTE if content_type is specified, it will change content_type for the\n            whole file.\n    \"\"\"\n    data, size = self._read_data(data_chunk, data=self._baseGetData())\n    content_type=self._get_content_type(data_chunk, data, self.__name__,\n                                        content_type or self.content_type)\n    self.update_data(data, content_type, size)\n\n\n# CMFFile also brings the IContentishInterface on CMF 2.2, remove it.\nremoveIContentishInterface(BigFile)'),(16355,'module.erp5.BTreeData BTreeData from __future__ import print_function\nfrom BTrees.LOBTree import LOBTree\nfrom persistent import Persistent\nimport itertools\nimport six\n\n# Maximum memory to allocate for sparse-induced padding.\nMAX_PADDING_CHUNK = 2 ** 20\n\nclass PersistentBytes(Persistent):\n  def __init__(self, value):\n    assert isinstance(value, bytes)\n    self.value = value\n\n  def __bytes__(self):\n    return self.value\n  if six.PY2:\n    __str__ = __bytes__\n\n  # Save place when storing this data in zodb\n  __getstate__ = __bytes__\n  __setstate__ = __init__\n\nPersistentString = PersistentBytes  # BBB compatibility with old name instances that might be saved in ZODB\n\n\nnegative_offset_error = ValueError(\'Negative offset\')\n\nclass BTreeData(Persistent):\n  \"\"\"\n  In-ZODB (non-BLOB) storage of arbitrary binary data.\n\n  File is managed as chunks, each with a starting offset. Chunks are\n  individually persistent (so they are loaded individually when accessed),\n  and organised in a BTree (so access to any part of the file is in\n  O=log(N)).\n\n  Each call to write() creates a new chunk, so the number and size of chunks\n  is (and must be) controled outside this class.\n\n  It supports sparse files, ie writing one byte at 10M offset will not use\n  10MB on disk. Sparse bytes read as 0x00 (NULL-bytes).\n  \"\"\"\n  _chunk_size = None\n  _max_chunk_size = None\n\n  @property\n  def chunk_size(self):\n    \"\"\"Aggregate consecutive writes up to this size.\"\"\"\n    return self._chunk_size\n\n  @chunk_size.setter\n  def chunk_size(self, value):\n    if value is not None and (value <= 0 or int(value) != value):\n      raise ValueError(\'Invalid chunk_size\')\n    self._chunk_size = value\n\n  @property\n  def max_chunk_size(self):\n    \"\"\"Prevent chunks from exceeding this size.\"\"\"\n    return self._max_chunk_size\n\n  @max_chunk_size.setter\n  def max_chunk_size(self, value):\n    if value is not None and (value <= 0 or int(value) != value):\n      raise ValueError(\'Invalid max chunk_size\')\n    self._max_chunk_size = value\n\n  def __init__(self, chunk_size=None, max_chunk_size=None):\n    \"\"\"\n    chunk_size (int, None)\n      If non-None, aggregate consecutive writes up to this size.\n      Overlaping or larger writes may exceed this size, though.\n    max_chunk_size (int, None)\n      If non-None, prevent chunks from exceeding this size.\n    \"\"\"\n    self._tree = LOBTree()\n    self.chunk_size = chunk_size\n    self.max_chunk_size = max_chunk_size\n\n  def __len__(self):\n    \"\"\"\n    Return the position of last data chunk in file.\n    Does not tell how many bytes are actually used.\n    \"\"\"\n    tree = self._tree\n    try:\n      result = tree.maxKey()\n    except ValueError:\n      return 0\n    return result + len(tree[result].value)\n\n  def write(self, buf, offset):\n    \"\"\"\n    Create a new chunk at given offset, with given data.\n\n    buf (bytes)\n     Data to write\n    offset (int)\n     Offset of first data byte.\n    \"\"\"\n    # TODO: auto-aggregation of continuous keys when overwriting\n    if offset < 0:\n      raise negative_offset_error\n    tree = self._tree\n    key = offset\n    try:\n      lower_key = tree.maxKey(offset)\n    except ValueError:\n      pass\n    else:\n      # Reuse data from an existing and overlapping entry, if any.\n      # Avoids fragmenting the file when overwriting with unaligned\n      # writes.\n      if lower_key < offset:\n        chunk = tree[lower_key]\n        chunk_end = lower_key + len(chunk.value)\n        if chunk_end > offset or (\n              len(chunk.value) < (self._chunk_size or 0) and\n              chunk_end == offset\n            ):\n          key = lower_key\n          buf = chunk.value[:offset - key] + buf\n    try:\n      tree.minKey(len(buf) + offset)\n    except ValueError:\n      try:\n        eof = tree.maxKey()\n      except ValueError:\n        pass\n      else:\n        if not tree[eof].value:\n          del tree[eof]\n    max_to_write_len = self._max_chunk_size or float(\'inf\')\n    while buf or offset > len(self):\n      try:\n        next_key = tree.minKey(key + 1)\n      except ValueError:\n        to_write_len = len(buf)\n        next_key = None\n      else:\n        to_write_len = min(len(buf), next_key - key)\n      try:\n        chunk = tree[key]\n      except KeyError:\n        tree[key] = chunk = PersistentBytes(b\'\')\n      entry_size = len(chunk.value)\n      if entry_size < to_write_len:\n        to_write_len = min(to_write_len, max_to_write_len)\n      to_write = buf[:to_write_len]\n      buf = buf[to_write_len:]\n      if to_write_len < entry_size:\n        assert not buf, (key, to_write_len, entry_size, repr(buf))\n        to_write += chunk.value[to_write_len:]\n      chunk.value = to_write\n      key = next_key or key + to_write_len\n\n  def read(self, offset, size):\n    \"\"\"\n    Read data back from object.\n\n    offset (int)\n     Offset of first byte to read.\n    size (int)\n     Number of bytes to read.\n\n    Returns bytes of read data.\n    \"\"\"\n    return b\'\'.join(self.iterate(offset, size))\n\n  def iterate(self, offset=0, size=None):\n    \"\"\"\n    Return file data in storage-efficient chunks.\n\n    offset (int)\n     Offset of first byte to read.\n    size (int, None)\n     Number of bytes to read.\n     If None, the whole file is read.\n\n    Yields data chunks as they are read from storage (or locally generated,\n    when padding over sparse area).\n    \"\"\"\n    if offset < 0:\n      raise negative_offset_error\n    tree = self._tree\n    try:\n      key = tree.maxKey(offset)\n    except ValueError:\n      key = offset\n    # (supposedly) marginal optimisations possible:\n    # - use key found by maxKey\n    # - avoid loading last key if its past the end of read request\n    # Would simlify the loop, but might duplicate code... And CPU is not\n    # expected to be the bottleneck here.\n    if size is None:\n      size = len(self) - offset\n    next_byte = offset\n    for key in tree.iterkeys(key):\n      padding = min(size, key - next_byte)\n      if padding > 0:\n        next_byte += padding\n        size -= padding\n        chunk_offset = 0\n        while padding:\n          padding_chunk = min(padding, MAX_PADDING_CHUNK)\n          padding -= padding_chunk\n          yield b\'\\x00\' * padding_chunk\n      else:\n        chunk_offset = next_byte - key\n      if size == 0:\n        break\n      chunk = tree[key]\n      to_write = chunk.value[chunk_offset:chunk_offset + size]\n      # Free memory used by chunk. Helps avoiding thrashing connection\n      # cache by discarding chunks earlier.\n      chunk._p_deactivate()\n      to_write_len = len(to_write)\n      size -= to_write_len\n      next_byte += to_write_len\n      yield to_write\n\n  def truncate(self, offset):\n    \"\"\"\n    Truncate data at given offset.\n\n    offset (int)\n     Offet of the first byte to discard.\n    \"\"\"\n    if offset < 0:\n      raise negative_offset_error\n    tree = self._tree\n    try:\n      key = tree.maxKey(offset)\n    except ValueError:\n      tree.clear()\n    else:\n      chunk = tree[key]\n      chunk_len = len(chunk.value)\n      value_len = offset - key\n      if chunk_len > value_len:\n        chunk.value = chunk.value[:value_len]\n      minKey = tree.minKey\n      # It is not possible to drop keys as we iterate when using\n      # iterkeys, so call minKey repeatedly.\n      while True:\n        try:\n          key = minKey(offset)\n        except ValueError:\n          break\n        del tree[key]\n    self.write(b\'\', offset)\n\n  # XXX: Various batch_size values need to be benchmarked, and a saner\n  # default is likely to be applied.\n  def defragment(self, batch_size=100, resume_at=None):\n    \"\"\"\n    Merge contiguous chunks up to max_chunk_size.\n\n    This method is a generator,  allowing caller to define a stop condition\n    (time, number of calls, ...). Yield value is an opaque, small and\n    serialisable value which only use is to be passed to resume_at\n    parameter.\n\n    batch_size (int)\n      Yield every this many internal operations. Allows trading overhead\n      for precision. This value may be adjusted on-the-fly by giving the\n      new value as parameter of the \"send\" method on generator (see\n      Python doc on generators).\n\n    resume_at (opaque)\n      If provided, resume interrupted processing at that point.\n    \"\"\"\n    chunk_size = self._max_chunk_size\n    key = resume_at or 0\n    tree = self._tree\n    for iteration in itertools.count(1):\n      try:\n        key = tree.minKey(key)\n      except ValueError:\n        return\n      if iteration % batch_size == 0:\n        new_batch_size = yield key\n        if new_batch_size:\n          batch_size = new_batch_size\n      chunk = tree[key]\n      chunk_len = len(chunk.value)\n      remainder = chunk_size - chunk_len\n      if remainder <= 0:\n        # Current entry is large enough, go to next one.\n        key += 1\n        continue\n      end_offset = key + chunk_len\n      try:\n        next_key = tree.minKey(key + 1)\n      except ValueError:\n        # No next entry, defrag is over.\n        return\n      if next_key != end_offset:\n        # There is a hole between current entry end and next one, do\n        # not concatenate and move on with next entry.\n        assert next_key > end_offset, (key, chunk_len, next_key)\n        key = next_key\n        continue\n      next_chunk = tree[next_key]\n      next_chunk_len = len(next_chunk.value)\n      if next_chunk_len >= chunk_size:\n        # Next entry is larger than target size, do not concatenate and\n        # go to the entry after that.\n        key = next_key + 1\n        continue\n      # Concatenate current entry and next one.\n      chunk.value += next_chunk.value[:remainder]\n      del tree[next_key]\n      if next_chunk_len > remainder:\n        key = next_key + remainder\n        # Concatenation result is larger than target size, split into\n        # a new entry.\n        next_chunk.value = next_chunk.value[remainder:]\n        tree[key] = next_chunk'),(16357,'erp5_big_file'),(16374,'Run Upgrader This step will run all constraints that have contraint_type equal upgrader.'),(16375,'Run Pre Upgrade This step will run all constraints that have contraint_type equal pre_upgrade.'),(16376,'Run Post Upgrade This step will run all constraints that have contraint_type equal post_upgrade.'),(16377,'Run Full Upgrade This alarms controls the upgrade process by calling others upgrader alarms.\n\nIt delegates sense to calling fix on \"Run Pre Upgrade\" then \"Run Upgrade\" alarms an aggregating the results.\n\nIt delegate fix to calling fix on \"Run Pre Upgrade\" then \"Run Upgrade\" then \"Run Post Upgrade\" alarms then aggregating the results.\n\nNote that post upgrade steps are not executed in the sense, because they require the upgrade step to be actually executed.'),(16378,'test.erp5.testUpgrader testUpgrader ##############################################################################\n#\n# Copyright (c) 2013 Nexedi SA and Contributors. All Rights Reserved.\n#                         Gabriel M. Monnerat <gabriel@nexedi.com>\n#\n# WARNING: This program as such is intended to be used by professional\